-- 自动生成：仅含中文译文与匹配指纹。来源见 SOURCES.md。
local D = LegionChineseDB
D.Strings[36325]="埃鲁纳克，来看看这个。还记得我跟你说过的视象法术吗？这看起来像是个有力的证据。"
D.Strings[36326]="埃鲁纳克检视着碎片，认同地点了点头。"
D.Strings[36327]="那我这就准备施法。这也许总算能让我们对纳迦的手段和意图有所了解。"
D.Strings[36328]="贸易区守住了！现在，守住城市的其它部分！"
D.Strings[36329]="我们守住了法师区！所有入侵者都已被击退，撤离也已顺利完成！"
D.Strings[36330]="你好啊，$n。我可以对你进行法师方面的训练。"
D.Strings[36331]="教堂区又归暴风城控制了！圣光之力永胜！"
D.Strings[36332]="对不起，$c，我帮不了你。你得去找$c训练师。"
D.Strings[36333]="滚开，联盟渣滓！"
D.Strings[36334]="对不起，我无法对你进行训练。"
D.Strings[36335]="别放松，$n！"
D.Strings[36336]="让这群怪物见识下暴风城的力量，$n！"
D.Strings[36337]="看来你这强大$c的名头可真是名不虚传啊，$n！"
D.Strings[36338]="你的作战技巧令人印象深刻，$n。"
D.Strings[36339]="有像$n一样的$c守卫，暴风城怎么会陷落？为了暴风城！"
D.Strings[36340]="新鲜的空气！以圣光的名义，我想念它。我看见在我们的北边有几艘船，$n——快朝他们的方向发射信号弹！"
D.Strings[36341]="新鲜的空气！以格罗姆胡须的名义，我想念它。我看见在我们的北边有几艘船，$n——快朝他们的方向发射信号弹！"
D.Strings[36342]="说“啊——”。"
D.Strings[36343]="你上一次体检是在什么时候？"
D.Strings[36344]="你在干什么？你影响了我的工作！腐烂之痕的重振都是我的功劳！"
D.Strings[36345]="吃两剂，早上再叫我。"
D.Strings[36346]="你该考虑减减肥了。"
D.Strings[36347]="我只想要……做点……好事……"
D.Strings[36348]="今天，你们要么成为奴隶，要么粉身碎骨！"
D.Strings[36349]="在这儿又与纳迦短兵相接。"
D.Strings[36350]="前进……"
D.Strings[36351]="麻烦真多…重组阵型！"
D.Strings[36352]="我们的目标已经在望——前进……"
D.Strings[36353]="耐普图隆的仆从在拼死抵抗！我们得快点！"
D.Strings[36354]="我们被发现了！准备战斗！"
D.Strings[36355]="诺莫瑞根隐秘行动组织的凯尔希·钢烁为你效劳！要是你想接受潜行者方面的训练，你可来对地方了。"
D.Strings[36356]="很抱歉，我不能对你进行训练。你得去找更熟悉你技能的训练师。"
D.Strings[36357]="欢迎回来，$n。你去得比我预想的要久。了解到什么有用的信息了吗？"
D.Strings[36358]="埃鲁纳克！我们没时间做这个……"
D.Strings[36359]="我们被纳迦围攻了，他们想要破坏我们的气闸！守住船的上舷！"
D.Strings[36360]="地精！进度报告！"
D.Strings[36361]="继续轰击洋底！让那些纳迦看看部落的力量！"
D.Strings[36362]="纳迦从左舷和右舷方向同时发动了攻击！正前方还遭遇到未知目标的突袭……！我们在人数上处于极端劣势，但船还在坚持，长官！"
D.Strings[36363]="在<此处为海怪号的名字>的力量面前，这条破船简直是废铁一块！"
D.Strings[36364]="花园已经变成了废墟……我们今天得另寻出路了。这该死的龙！"
D.Strings[36365]="更多的纳迦！当心！"
D.Strings[36366]="感谢海浪的庇护，你终于回来了！别人都已经撤退，我们得离开这儿！"
D.Strings[36367]="拉葛雷克死了！"
D.Strings[36368]="动作快，$n！我们没多少时间，拉瑟莱克很快就会回来。"
D.Strings[36369]="<这群岩池鱼人宝宝朝海洋的方向看去。>"
D.Strings[36370]="<继续帮助岩池鱼人蝌蚪。>"
D.Strings[36371]="啊！回到这儿来！"
D.Strings[36372]="暴风城的市民们！开始撤离城市！"
D.Strings[36373]="暴风城的宾客们，请在风暴来临前找到栖身之所！"
D.Strings[36374]="清空街道！"
D.Strings[36375]="疏散市民！清空暴风城的街道！"
D.Strings[36376]="我们必须快点！元素无法抵挡这样的攻击。"
D.Strings[36377]="你们愚蠢地侵入了我们的水域，联盟的傻瓜们。接受我风暴的鞭笞吧！"
D.Strings[36378]="啊，有客——人！"
D.Strings[36379]="真是个意外的惊喜。"
D.Strings[36380]="请原谅……我没时间陪你们找乐子了。"
D.Strings[36381]="我走之后，我的仆人……会满足你们的需求的。"
D.Strings[36382]="尽情享乐吧！"
D.Strings[36383]="你需要什么吗，$g老兄:女士;？"
D.Strings[36384]="不管你要什么，我都有……"
D.Strings[36385]="好东西。你肯定很有钱。"
D.Strings[36386]="你在这儿干什么？体验苦日子吗？"
D.Strings[36387]="你想要什么？消息？这我也有！"
D.Strings[36388]="你在找更有……异域风情的东西吗？"
D.Strings[36389]="我想我们能做笔交易。"
D.Strings[36390]="往这儿瞧瞧，$g老兄:女士;。"
D.Strings[36391]="海巫，我们没那么容易对付！"
D.Strings[36392]="就算我们要死，也要带着消灭夙敌的荣耀！"
D.Strings[36393]="这儿究竟发生了什么？"
D.Strings[36394]="对纳迦的最后一战即将打响。我们将取胜，或在深渊裂口里奋战至死。"
D.Strings[36395]="看来法布隆一家遭到了杀害……"
D.Strings[36396]="我们是怎么了？我们现在比迪菲亚恣意妄为时的状态更糟！"
D.Strings[36397]="没错。那个国王简直一无是处。"
D.Strings[36398]="我们赶快离开这里吧，不然他们又要归罪到我们头上。"
D.Strings[36399]="说得对。"
D.Strings[36400]="在我们加入最终战斗之前，我们必须对发生在对面那个上古生灵体内的事情做个了断。否则，我们将毫无胜算。$B$B尽全力去帮埃鲁纳克吧，$n。"
D.Strings[36401]="拉葛雷克是位远古之神，就在沟壑的另一侧。他正在受到某种力量的侵扰。$B$B我们必须终结这一切，否则我们谁都活不了！"
D.Strings[36402]="尽管我们拼尽了全力，纳迦还是对裂口发动了攻击！$B$B必须守住水元素位面！"
D.Strings[36403]="在深渊裂口，一场战争正在酝酿。希望与扳钳X2号一起赶来的援军足够抵挡。"
D.Strings[36404]="放我们进去！"
D.Strings[36405]="打倒国王！"
D.Strings[36406]="尝尝马粪的滋味！"
D.Strings[36407]="你有什么权利不让我们进去？"
D.Strings[36408]="我们又冷又饿！帮帮我们！"
D.Strings[36409]="没心没肺的怪物！"
D.Strings[36410]="这就叫人人享有平等与公正？"
D.Strings[36411]="你还想要我们怎么样？"
D.Strings[36412]="在我们加入深渊裂口的最终战斗之前，我们必须终结在对面那上古生灵体内所发生的一切。否则，我们都将失败。$B$B尽全力去帮埃鲁纳克吧，$n。"
D.Strings[36413]="对纳迦的最后一战已经打响。我们将根除他们，或在深渊裂口里光荣地奋战至死。"
D.Strings[36414]="要是你问我的话，我认为让那些汤羹和肉汁去充数就够了。$B$B趁我们还没变成烤面包之前，应该纵身从这儿逃出去。$B$B你明白我的意思吗，宝贝儿？"
D.Strings[36415]="嘿，你好啊伙计！"
D.Strings[36416]="你们俩这是要去哪儿呢？"
D.Strings[36417]="我们只是想饱餐一顿，要是能再舒服的睡上一觉就更好了。"
D.Strings[36418]="我们两个私下说，宝贝儿，我的身高不适合执行这种任务。再坚持一个月我就要离开了。$B$B我已经死过一次。没必要再来一回。"
D.Strings[36419]="你不认字吗，伙计？看来是的，哈？"
D.Strings[36420]="牌子上写着：“严禁游民！”还不赶紧滚开！"
D.Strings[36421]="要与第一个上古生物奈瑟匹拉打交道已经够难了。而在我们对面的那个，叫拉葛雷克的，就快要死了。$B$B我能感觉到它痛苦的哀号。有什么东西正在偷取它的生命能量。我不知道那些被偷走的生命能量将被用于什么目的。"
D.Strings[36422]="肮脏恶心的杂碎。你们一定会遭报应的。"
D.Strings[36423]="我们赶紧离开这鬼地方。真希望这里能化为焦土。"
D.Strings[36424]="我希望能与你在即将打响的战争中并肩作战，但埃鲁纳克要我留下。$B$B祝你好运，$n。"
D.Strings[36425]="这深渊可真是噩梦。$B$B但和即将加入的下方裂口里的战斗比起来，简直就是小巫见大巫。"
D.Strings[36426]="看来我给咱们找到了一块可口又干净的泥巴！今晚我们将吃得像皇帝一样，企鹅先生！我当然会与你分享！你可是我最好的朋友！"
D.Strings[36427]="我快饿死了！"
D.Strings[36428]="哈哈哈！好样的，企鹅先生！好样的！"
D.Strings[36429]="我恐怕做不到……"
D.Strings[36430]="我这是怎么了？我从前可是暴风城的国王！"
D.Strings[36431]="看来我们今天的晚餐又只能啃皮鞋了。"
D.Strings[36432]="不知道吃石头行不行？这儿附近可有好多石头。想象一下！我将因这一伟大的发现成为这世上最富有的人！"
D.Strings[36433]="我怀念被迪菲亚抢劫的那段日子。起码他们偶尔还会给你留下点儿吃的。"
D.Strings[36434]="嘿！说你呢！离我的东西远点儿！"
D.Strings[36435]="$g他:她;穿靴子了吗？快抢！"
D.Strings[36436]="翻$g他:她;口袋！"
D.Strings[36437]="我什么都不会告诉你！"
D.Strings[36438]="喔，是大英雄来了。我得救了！对，是的……"
D.Strings[36439]="你想聊聊？给钱。"
D.Strings[36440]="你看到是谁杀了法布隆一家吗？"
D.Strings[36441]="也许几枚铜币就能撬开你的牙齿。现在请你告诉我，你有没有看到是谁杀了法布隆一家？"
D.Strings[36442]="你确定要给这流浪汉钱吗？"
D.Strings[36443]="你收买不了我！去死吧！"
D.Strings[36444]="我唯一能告诉你的，就是给我滚开！"
D.Strings[36445]="这儿没你的事儿，笨蛋！快滚！"
D.Strings[36446]="他们是自然死亡……"
D.Strings[36447]="审判日到了！兄弟会必将重生！"
D.Strings[36448]="听着，$g伙计:女士;，我可不想惹麻烦。我没看见是谁杀了他们，但我听到了！不绝的哭喊声，还有人说话的声音……懂了吗？现在赶紧离开这儿，趁我还没改变主意把你的鞋子扒下来痛打你一顿。"
D.Strings[36449]="我没看见是谁杀了他们，$g伙计:女士;，但我嗅到了点儿什么。闻上去像是有钱人的味道，跟你有点儿像。我也感到很遗憾。法布隆一家是这儿的老住户了。他们一家都是好人，总是愿意拿出饭菜或泥土与人分享。"
D.Strings[36450]="谁杀了法布隆一家？让我来告诉你是谁干的——是瓦里安·乌瑞恩国王，对，就是他！而且他还要把我们都杀了，一次性全干掉。我唯一能告诉你的，就是我看到有几个豺狼人在办案人员到来的几小时前从那里走掉了。"
D.Strings[36451]="你知，我知，树知——是鱼人杀死了法布隆一家。没错，是我亲眼看见的。我想他们已经蓄谋了好几天，甚至是好几个月了。后来当他们听到与“约翰尼警员”和那白痴编队有关的风声时，就仓皇逃走了……"
D.Strings[36452]="你们有钱人都是一个样！"
D.Strings[36453]="不管什么事情，我都不会告诉你的！"
D.Strings[36454]="像个畜生一样的活着已经够痛苦了，现在你还来羞辱我！"
D.Strings[36455]="也许我能拿你的肝脏去换几个钱。"
D.Strings[36456]="我告诉过你要全部付清了，小子！"
D.Strings[36457]="你这蠢货竟然真敢这么干！尝尝我的拳头！"
D.Strings[36458]="你想让我踢你前胸还是屁股？随你挑。"
D.Strings[36459]="攻击开始！"
D.Strings[36460]="这是艾泽拉斯的困难时期，$n。元素已经把许多市民和与他们交战的对手都囚禁了起来。我们可以给你一个图腾，用它就能打破元素的禁锢。"
D.Strings[36461]="你们听见他说的了。我们将坚守此地！"
D.Strings[36462]="让我们到我营地处重聚——以朋友与同行英雄的身份，来讨论我们最后也是最重要的任务。来吧，多香果！"
D.Strings[36463]="你的功绩为部落带来了辉煌与荣耀，$n！"
D.Strings[36464]="把这些入侵者立即处死，$n！"
D.Strings[36465]="碾碎这些元素，$n！把它们从我们的土地上驱逐出去！"
D.Strings[36466]="就是这儿！进入耐普图隆王国的入口……"
D.Strings[36467]="把他们击退，$n！"
D.Strings[36468]="不要松懈，$n！"
D.Strings[36469]="这些元素在你面前毫无机会，$n！"
D.Strings[36470]="让这些元素痛不欲生！听从我的指挥，$n！"
D.Strings[36471]="你可真有两下子，$n！"
D.Strings[36472]="集结起来，艾萨拉的孩子们！我们终于要夺取水元素位面了！"
D.Strings[36473]="去吧，我的纳迦！迎接强大的猎潮者来到艾泽拉斯。"
D.Strings[36474]="我们召集起了一支强大的军队，击败了瑟玛普拉格的爪牙，一路杀回这座城市。但瑟玛普拉格这个篡位者还留了一招……"
D.Strings[36475]="沙怒巨魔与暮光之锤联手？！不要紧。那个邪恶的女巫别想把她的怪物送进我的城市。"
D.Strings[36476]="来吧，勇士们！我们要用他们的污血点缀这片沙地，凯旋而归！"
D.Strings[36477]="我们不得不撤退。瑟玛普拉格则继续躲在地下的辐射尘中，派遣他的部下碎轮来到地面上作恶。"
D.Strings[36478]="部落夺回了力量谷！进攻奥格瑞玛的可怜把戏必将覆灭。为了部落！"
D.Strings[36479]="巫毒是部落的力量。精神谷现在受沃金控制！"
D.Strings[36480]="荣誉谷守住了！"
D.Strings[36481]="扳钳X2号马上就要到了！整装列队，弟兄们！"
D.Strings[36482]="扳钳X2号已经到达。全体上船！"
D.Strings[36483]="你这小小的凡人想要什么？为什么要找格拉布托克？"
D.Strings[36484]="真可悲……这就是你向往的生活吗，格拉布托克？从洞穴里时不时地跑出来靠敲诈发点儿小财？"
D.Strings[36485]="格拉布托克要粉碎你！"
D.Strings[36486]="哦你会吗？你敢冒生命危险做这种越界的事情吗？"
D.Strings[36487]="另一个选择是什么？"
D.Strings[36488]="你可以试着杀死我——然后失败——或者你也可以接受另一个选择。"
D.Strings[36489]="加入我，我将让你沐浴在财富与权力之中。"
D.Strings[36490]="所以格拉布托克现在有两种选择——死，或是变得富有而强大？"
D.Strings[36491]="干得漂亮，$n！暴风城将永远不忘你的恩情。"
D.Strings[36492]="格拉布托克选第二个。"
D.Strings[36493]="我就知道我们会达成共识。"
D.Strings[36494]="等时机到来时我会来找你。"
D.Strings[36495]="从！"
D.Strings[36496]="我的！"
D.Strings[36497]="船上！"
D.Strings[36498]="滚出去！"
D.Strings[36499]="你和你那些长鳞的虫子根本不是我的对手……"
D.Strings[36500]="蠢货！今天就是你的死期！"
D.Strings[36501]="你可以从任何大地之环成员那里取得图腾！用图腾将市民和防御者从元素囚牢中解救出来！"
D.Strings[36502]="他们在追赶酋长。"
D.Strings[36503]="酋长的飞船着火了！开始坠落了！"
D.Strings[36504]="你……你见到她了吗？"
D.Strings[36505]="是的。真的是她。"
D.Strings[36506]="她要我转告你们这群蠢货，她很欣赏我们替她对法布隆一家所做的一切。还给了我不少赏金，让我跟你们分。"
D.Strings[36507]="你看到她的脸了吗？她的脸真是……"
D.Strings[36508]="哇，看看谁在这儿？看来我们这儿混进了个偷听者，小子们。"
D.Strings[36509]="对惹人讨厌、一无是处的偷听者来说，只有一个待遇。"
D.Strings[36510]="赶快回到法布隆的小屋里去！"
D.Strings[36511]="看起来不太好，菜鸟。"
D.Strings[36512]="这片土地在饱受煎熬……它在乞求怜悯，$r，它在乞求怜悯。"
D.Strings[36513]="这是一次死刑裁决。不管是谁干的，都是为了传达一个信号……"
D.Strings[36514]="用来警告任何胆敢告发这些罪犯的人。"
D.Strings[36515]="看来可怜的洛伊真把他的脚放进了……"
D.Strings[36516]="自己的嘴里。"
D.Strings[36517]="拜托了英雄们，求你们帮帮我的同胞，我们会帮助你们的！"
D.Strings[36518]="多谢你救了我，现在请你帮帮我其它的同胞！"
D.Strings[36519]="喂饱 一支部落大军可不是件容易的事。我有许多活儿要干，你有时间帮帮我吗？"
D.Strings[36520]="你当时就站在这儿！你究竟看见了什么？快说！"
D.Strings[36521]="我……我什么也没看见！他……他是自然死亡的。"
D.Strings[36522]="自然死亡？胸部中了两枪，鞋子也跑到头上去了。什么样的自然死亡会是这种效果？"
D.Strings[36523]="我们必须不惜一切代价将世界之柱碎片重新拼合在一起。$B$B但首先，我们得先找齐它们。"
D.Strings[36524]="我这辈子都没离开过西部荒野，$g兄弟:姐妹;。我还记得西部荒野曾是荆棘谷这一侧最富生机的地方。那些日子已经一去不复返了。$B$B尽管我们摆脱了迪菲亚制造的麻烦，但他们恐怖统治的影响至今犹存。更糟糕的是，我们现在正面临有史以来最严重的经济危机。由于我们将所有的积蓄都拿去对付天灾军团，所以那些不在军中任职的普通百姓全都陷入失业与最终无家可归的境地。$B$B你猜这些人最后怎么办了？"
D.Strings[36525]="啊——后甲板集合。有敌人登船了。射击！干掉它！"
D.Strings[36526]="来人呐，快做点什么！这是命令！"
D.Strings[36527]="它被缠在索具里了。"
D.Strings[36528]="干得好，英雄们。这传送门本来是用来送这怪物的，现在就让我们从这道门返回吧！在暴风城还有许多工作在等着我。"
D.Strings[36529]="在奥格瑞玛附近布下路障来保卫城市！$B$B从散落在城市各个角落的箱子里拾取路障$B$B将它们安放在红色箭头|TInterface\\Icons\\ABILITY_HUNTER_MARKEDFORDEATH.blp:32|t所标记的位置。"
D.Strings[36530]="没错，她是这么说的：“只是一次前往废土的简单旅程，毫无压力。”"
D.Strings[36531]="谢谢你，$n。我们永远不会忘记你的慷慨相助。"
D.Strings[36532]="开饭啦！快来吃吧！"
D.Strings[36533]="我太高兴了。谢谢你，妈妈；也谢谢你，$n。"
D.Strings[36534]="她要炸了！快背好降落伞准备跳！"
D.Strings[36535]="%s把自己埋进了沙里！"
D.Strings[36536]="你只能在摩尔森农场使用过载的麦田傀儡。"
D.Strings[36537]="正在初始化清除……"
D.Strings[36538]="舰体严重损毁，长官！"
D.Strings[36539]="抛去全部多余负重。加固装备舱。让飞船转向岸边。"
D.Strings[36540]="全部准备跳伞！"
D.Strings[36541]="求救！求救！求救！所有人跳伞。跳！"
D.Strings[36542]="%s消散了！"
D.Strings[36543]="就算是在这儿——在这海浪与暖日的环抱下，我都能感觉到在这些土地上涌动的黑暗力量。$B$B这可真有趣儿，你不觉得吗？"
D.Strings[36544]="赶走元素！精神谷是我们的！"
D.Strings[36545]="我们自豪地宣称，我们是效忠于部落的森林巨魔最后的部族。$B$B总有一天，我们将战胜其它部族，还有那些矮人，辛特兰将属于我们。"
D.Strings[36546]="谢谢你，和善有礼的陌生人。"
D.Strings[36547]="杂味炖肉？我永远都不会忘了这一刻！"
D.Strings[36548]="不论走到哪儿都会牢记的味道！萨尔玛的拿手炖肉！"
D.Strings[36549]="也许……也许活着是有意义的。"
D.Strings[36550]="祝福你，朋友。"
D.Strings[36551]="也许有一天我将报答你的善举。"
D.Strings[36552]="我帮不了你。要是你想进行术士训练的话，可以去找沃德雷卡。"
D.Strings[36553]="心智的训练，你会发现黑暗艺术要比任何武器都要强大得多。"
D.Strings[36554]="这里的巨魔很能接受像我这样的人。毕竟，在被遗忘者还没出现时，他们就已经与死者交流了几个世纪。$B$B这是个很好的契机。"
D.Strings[36555]="在我小时候，我的家人不许我研习萨满巫术。任性而愚蠢的我竟然从他们身边逃离，一个人学习了起来。有一天当我回到故乡，却发现父母都已不在。我的家园也已被毁。没人知道是谁下的手。\n\n我耗尽毕生的精力，想要延展我萨满的视野来回望过去——查明在我家人身上究竟发生过什么，谁该对此负责。我一路走来历尽艰辛。现在我已学会将意念集中在于不久前发生的重大事件上，可要想获知发生在那么久之前的事，我还有很长的路要走。"
D.Strings[36556]="我忘记把你给我的魔能之刃放哪儿了。你看见过吗？"
D.Strings[36557]="<当你站在塑像面前时，你感觉到一阵风呼啸而过。>"
D.Strings[36558]="阿基尔达拉，把我送回盟友那里。"
D.Strings[36559]="辛萨罗一定属于我们，朋友。邪枝部族只不过是软弱而令人生厌的背叛者，他们不配得到神灵的眷顾。"
D.Strings[36560]="送我到平台中央的阿基尔达拉那里去。"
D.Strings[36561]="你会得到我们全力的配合，中尉。法布隆一家是好人。他们决不会枉死。"
D.Strings[36562]="这是个好消息，长官。可尽管$n已经将行凶者绳之以法，但他们的主谋却仍逍遥法外。也许在西部荒野人民军的协助下，我们终于能够了结这个案子。"
D.Strings[36563]="请允许我问一下，那里面关着的狼人是怎么回事儿？"
D.Strings[36564]="这畜生在村庄里屠杀羊群时被我们抓住了。他死不悔改，脾气极为暴躁。千万别靠得太近，中尉。"
D.Strings[36565]="有本事别让我逃出去，否则我就要把你的心挖出来一口吃掉！"
D.Strings[36566]="哇哦，治安官看来没开玩笑。"
D.Strings[36567]="可你的吠叫……"
D.Strings[36568]="比你的撕咬还凶狠？"
D.Strings[36569]="你们太过火了，毒蛇。你们会为这次入侵付出惨重的代价！"
D.Strings[36570]="%s试图藏在海底！"
D.Strings[36571]="诺森德的战火给我们所有人都造成了损失，$n。尽管我们在寒冰荒野上取得了胜利，我们自己的土地却陷入了混乱。"
D.Strings[36572]="关于这件事你到底知道些什么，怪物？谁是首领？快说！"
D.Strings[36573]="黎明来临了，斯托曼，你的末日也将到随之到来。"
D.Strings[36574]="一头疯狼的胡言乱语。啊呸！"
D.Strings[36575]="包在我身上，$n。"
D.Strings[36576]="门都没有。"
D.Strings[36577]="小菜一碟。"
D.Strings[36578]="他完了！"
D.Strings[36579]="那群豺狼人失败了，女主人。"
D.Strings[36580]="他们已经成功牵扯了敌人的注意力。我们按计划继续。"
D.Strings[36581]="可是女主人，将军仍然……"
D.Strings[36582]="我们将在黎明之时把将军放出来。"
D.Strings[36583]="是，女主人。"
D.Strings[36584]="审判日很快就要到来了，赫利克斯。"
D.Strings[36585]="叫来我的人民。我想在黎明到来之前再对他们讲最后一次话。"
D.Strings[36586]="月溪镇，女主人？"
D.Strings[36587]="是。就在今夜。"
D.Strings[36588]="过来，奴仆们！开始攻击！"
D.Strings[36589]="别松懈！他正在变弱！"
D.Strings[36590]="纳兹夏尔和她的荣誉守卫！拼死一战吧！"
D.Strings[36591]="纳兹夏尔和她的荣誉守卫…拼死一战吧！"
D.Strings[36592]="现在去参加派对有点儿早，不是吗？"
D.Strings[36593]="你在自取灭亡，伙计！"
D.Strings[36594]="你觉得你这是要去哪儿？"
D.Strings[36595]="要是你不跟我们合作，那就是与我们作对！死吧！"
D.Strings[36596]="准备好检查了，$g阁下:女士;！"
D.Strings[36597]="这个孩子只属于我！我叫她“节流圈儿”。"
D.Strings[36598]="准备好检查了！……记得温柔一点。"
D.Strings[36599]="看见没有？铁甲万能车！"
D.Strings[36600]="没错。稍事休息，再接再厉！"
D.Strings[36601]="我们什么都做不了，只有等待……并心存希望。"
D.Strings[36602]="呃噢。嗯。哎呦。"
D.Strings[36603]="看哪，看哪，没事了！只是个小得不能再小的小故障。看到没有？"
D.Strings[36604]="涂上点儿漆，就完事大吉了！"
D.Strings[36605]="我……不管怎样我从来都没想过要当工程师。"
D.Strings[36606]="我一直想当个……舞者！电动工具让我害怕。"
D.Strings[36607]="我能旋舞。在脚尖上旋舞。就像只蝴蝶一样。想看看吗？"
D.Strings[36608]="%s飞快地跑掉了。"
D.Strings[36609]="它还能用作船运。我稍微修修就好！"
D.Strings[36610]="快要开始集结了！"
D.Strings[36611]="集合，兄弟姐妹们！所有人都过来，听好了！"
D.Strings[36612]="兄弟们。姐妹们。我们是被遗弃的——我们是暴风城的孤儿。"
D.Strings[36613]="我们的“国王”高高坐在他那用黄金打造的宝座上，对我们的困境无动于衷。"
D.Strings[36614]="与此同时，我们的孩子们却正饿死在我们脚下的这些条街道上！"
D.Strings[36615]="他的战争——并不是我们的战争，却夺走了我们幸福的生活。我们用自己与所爱的人的鲜血，换来了联盟的胜利！"
D.Strings[36616]="时机已经到来了，兄弟姐妹们，我们要让正义得伸！"
D.Strings[36617]="暴风城与整个联盟的执政阶级，必须为他们对我们犯下的罪行负责！"
D.Strings[36618]="今天，我们获得了新生！今天，我们是以男人和女人的身份屹立在这里，而不再是无名无姓的数字！"
D.Strings[36619]="%s把他的鱼扔向你，恐惧地试图逃走！"
D.Strings[36620]="谢谢你把我从这儿弄出来！"
D.Strings[36621]="我再也不想闻到穴居人身上几百年没洗的臭味了！"
D.Strings[36622]="谢谢你。现在，让我们把这洞穴炸烂吧！"
D.Strings[36623]="你想象不出我见到你有多高兴！"
D.Strings[36624]="终于见到个不是穴居人的人！"
D.Strings[36625]="我自由了！我真的自由了！"
D.Strings[36626]="部族的朋友们，我们的城市遭到了攻击！拿起你们的武器，共同保卫我们的家园！要是你不想战斗，那就把天气障壁安放在城市周围，保护市民免受元素的侵扰！"
D.Strings[36627]="把天气障壁放在雷霆崖周围来保护城市！$B$B从城市周围的箱子里取出防风屏障$B$B将它们安放在红色箭头标出的位置|TInterface\\Icons\\ABILITY_HUNTER_MARKEDFORDEATH.blp:32|t。"
D.Strings[36628]="我们马上就开始，$g阁下:女士;！"
D.Strings[36629]="我们夺回了中央高地！赞美大地之母！"
D.Strings[36630]="明白！"
D.Strings[36631]="是$g阁下:女士;！马上执行，$g阁下:女士;！"
D.Strings[36632]="我们守住了猎人高地！入侵者已经被彻底击退，撤退完成了！"
D.Strings[36633]="灵魂高地守住了！所有入侵者都已被击退，撤离也已顺利完成！"
D.Strings[36634]="你无路可逃了，范克里夫！迪菲亚的末日到了！"
D.Strings[36635]="我们是来此做了结的！面对我们吧，懦夫！"
D.Strings[36636]="去做准备吧，$n，但动作要快！"
D.Strings[36637]="我准备好了，埃鲁纳克。出发吧！"
D.Strings[36638]="守住门——我们抓到他了！"
D.Strings[36639]="哦不，别在酒吧里闹事！去外面解决，伙计！"
D.Strings[36640]="我现在停止巡查了！"
D.Strings[36641]="我现在开始巡查了！"
D.Strings[36642]="胜利属于联盟！荣誉献给暴风城！"
D.Strings[36643]="让我们尽快返回哨兵岭，伙伴们，把范克里夫死亡的消息通知给格里安！"
D.Strings[36644]="爸爸……"
D.Strings[36645]="狂风与空气的元素之灵正欲毁灭雷霆崖。要是你认为自己强大到足以进去帮忙，那么请便。不然的话就别进去添乱，让我们来解决这一危局。"
D.Strings[36646]="别去打扰这年老的龙喉兽人喝酒了，$c。$B$B我曾经对抗过足以把你脊椎扭弯的怪物，在湿地的沼泽和外域的废墟间看着自己的人民惨遭屠戮。$B$B茫然。无措。"
D.Strings[36647]="这是什么，$c？你知道我叫什么？$B$B那你可知道我的名气？$B$B我是龙喉部族的火牙。我曾统领军团，驭龙驰骋，见证过格瑞姆巴托的分崩离析……$B$B该死的暮光之锤，还有他们屁股后面那群食人魔哈巴狗。看看我现在的落魄样。只能絮叨着与廉价的烈酒为伴。"
D.Strings[36648]="龙喉必将再次崛起。帮我们征服暮光之锤吧——你能给我一张地图吗？"
D.Strings[36649]="我会帮忙，可你要知道，你们正在踏入毒蛇的巢穴。让我来为你画张地图——哇——你后面！"
D.Strings[36650]="这么说来，暮光之锤想要除掉我？恬不知耻的垃圾！$B$B我一定会帮助你的，$c。你说你需要一张地图？"
D.Strings[36651]="不管在别处正在发生着什么，铁炉堡没有忘记这片土地，也没有忘记卡兹莫丹的任何角落！"
D.Strings[36652]="你感觉到你被跟踪了……"
D.Strings[36653]="你毫无荣誉感地战斗，死也死得像只害虫！"
D.Strings[36654]="暮光渣滓。"
D.Strings[36655]="感受龙喉的利齿吧！"
D.Strings[36656]="又一只虫子回归大地了。"
D.Strings[36657]="只有弱者才藏在阴影里，暮光垃圾！"
D.Strings[36658]="是的，一张绘有海岸地形的地图。"
D.Strings[36659]="%s在一张撕下的羊皮纸上画下了他故乡港口附近的地形。"
D.Strings[36660]="拿去吧，$n。所有可攻入暮光高地的安全路线都在这上面了。将毁灭带给我们的敌人吧！"
D.Strings[36661]="暮光之锤。啊呸！一群上蹿下跳的紫色……娘娘腔。算了，坐在酒吧里喝酒才是正经事儿。格莱维！我喝点什么好呢？"
D.Strings[36662]="很好。那就随便来吧。"
D.Strings[36663]="你反正什么酒都喝，老兄。"
D.Strings[36664]="%s朝你打手势，还有话要对你说。"
D.Strings[36665]="你怎么还待在这儿，$c？$B$B你不是应该已经抵达暮光高地，让那该死的教派彻底毁灭吗？"
D.Strings[36666]="他们在我们的食物中下了毒……教徒们早就混上了船……"
D.Strings[36667]="他们引我们去伏击部落的炮艇……可这是为什么呢？"
D.Strings[36668]="在黑暗降临的一瞬间，我听见他们在向自己的黑暗神灵祈祷……是暮光之锤干的！"
D.Strings[36669]="人们开始纷纷倒毙……那些吃过食物的人全都没能幸免。"
D.Strings[36670]="暮光渣滓！这是你们造的孽！"
D.Strings[36671]="把那块大头骨扔进锅里去！"
D.Strings[36672]="然后把魔精扔到头骨上！"
D.Strings[36673]="法术完成。"
D.Strings[36674]="看尼姆布亚给你变个他最擅长的戏法。"
D.Strings[36675]="战士们。你们曾在寒冷的荒野上顽强奋战。现在又到了再次考验你们勇气的时候了。"
D.Strings[36676]="我的战士们！你们已经证明了自己的勇猛。这也是酋长选中你们的原因。"
D.Strings[36677]="部落的英雄们！你们准备好创造历史了吗？"
D.Strings[36678]="我们很快就将登船前往遥远的彼岸，扑向敌人的老巢。"
D.Strings[36679]="我们的敌人——潜于暗影之中，妄图颠覆我们的世界。我们不会再失去另一个家园。"
D.Strings[36680]="我们的目的地是暮光高地。我们要直接把敌人跃动的心脏给挖出来。"
D.Strings[36681]="我们集结了庞大的军队——凝聚海陆空三军。我们是强大的军团！"
D.Strings[36682]="当我们释放出怒火，我们的敌人就只会瑟缩不已！"
D.Strings[36683]="我们的怒火将把高地染红——或是敌人血液的任何颜色！"
D.Strings[36684]="地狱咆哮的双目在注视着你。"
D.Strings[36685]="让我们看看高昂的斗志吧。出击！出击！出击！"
D.Strings[36686]="现在。让我看看你的怒火。来吧！"
D.Strings[36687]="这我可不喜欢，$n。保持警觉！"
D.Strings[36688]="你们这群混蛋要为自己的罪行付出代价。"
D.Strings[36689]="希望！什……"
D.Strings[36690]="希望？当我看见父亲的头被你的手下砍掉时，我心里应该有这种感觉吗？"
D.Strings[36691]="希望就是个残忍的笑话，是这个严酷而冷漠的世界同我们开的一个玩笑。希望根本就是不存在的，存在的只有梵妮莎。梵妮莎·范克里夫。"
D.Strings[36692]="站起来吧兄弟会！破晓之日即将到来！"
D.Strings[36693]="把他们绑起来。"
D.Strings[36694]="长官，你的帽子。"
D.Strings[36695]="谢谢你，宝贝儿。"
D.Strings[36696]="执行者博登，我是代表大地之环来的。我愿你族远离任何伤害。我们希望修复横亘在我们世界间的裂隙。你为什么要攻击我们？"
D.Strings[36697]="哈！你是不是把我错认成岱亚曼塔，$r？还是只知道哭鼻子的软骨头穴居人？"
D.Strings[36698]="如果你寻求和平，那么就放弃世界之柱并离开深岩之洲。这是我们的国度，你不会受到欢迎，只配被我碾于脚下。"
D.Strings[36699]="麦氏移山人有限公司杰萨普·麦格雷，为您效劳。"
D.Strings[36700]="要是您想要搬山，找我就对了。我还能为您造座山出来。"
D.Strings[36701]="这不是我所干过最重要的工作，连边儿都沾不上。大灾变一定是我们所经历过最棒的事了！"
D.Strings[36702]="我能为你做些什么吗，长官？"
D.Strings[36703]="多谢你的帮忙。不知为什么那个要难对付得多。"
D.Strings[36704]="让你们所见之处只留下灰烬，兄弟们！把哨兵岭烧光！"
D.Strings[36705]="至于你，$n，我会饶你不死。你帮了我们不少忙——尽管是在不经意间，但下一次我们再见面时，就只能用武器说话了。"
D.Strings[36706]="我只想知道一件事，梵妮莎。"
D.Strings[36707]="你为什么要除掉法布隆一家？"
D.Strings[36708]="我别无选择，中尉。他们认出了我。在这个世界上唯一知道我存在的人，从我在襁褓之时起就认得我的脸。"
D.Strings[36709]="他们的死亡令我也感到难过。"
D.Strings[36710]="现在可以肯定了。这些石头元素不久前才被唤醒。"
D.Strings[36711]="只有元素领主才有可能在短时间内唤醒这么多的元素。看来，我们面对的正是石母本尊……"
D.Strings[36712]="愿元素保护我们。"
D.Strings[36713]="$n，前去暴风城。把一切都告诉乌瑞恩国王。一切！现在就去！"
D.Strings[36714]="终于能喘口气了！谢谢你。"
D.Strings[36715]="以元素之名……那家伙……就是死不了……"
D.Strings[36716]="谢谢你的帮忙。这儿可真危险。"
D.Strings[36717]="我本以为我们要被留在这儿了。谢谢你出手相救！"
D.Strings[36718]="多加小心，他们不会就这么停手。"
D.Strings[36719]="别待在这儿太久，随时会有更多敌人出现。"
D.Strings[36720]="谢谢你。我可以稍微休息下了。"
D.Strings[36721]="干得漂亮！让我们解决了他。"
D.Strings[36722]="需要帮忙吗？"
D.Strings[36723]="我看见你那一把抓过来的动作了。等我们回去，一定要给弟兄们讲讲你的英勇事迹。"
D.Strings[36724]="快！趁现在把他干掉！"
D.Strings[36725]="这才像话。"
D.Strings[36726]="别再朝我们扔石头了，好不？"
D.Strings[36727]="哪儿有像那样的绳子？！那可真棒！"
D.Strings[36728]="千万别让他再站起来……"
D.Strings[36729]="兄弟姐妹们，铁炉堡遭到了攻击！拿起你们的武器，保卫我们的主城！要是你不想回应战斗的召唤，也可以帮忙部署防御工事，确保城墙不会倒塌！"
D.Strings[36730]="平民区守住了！现在去守卫城市其它区域！"
D.Strings[36731]="在铁炉堡城墙周围构筑防御工事，来防止城墙坍塌！$B$B从城市周围的箱子里取出城墙防御工事$B$B将它们安放在红色箭头标出的位置|TInterface\\Icons\\ABILITY_HUNTER_MARKEDFORDEATH.blp:32|t。"
D.Strings[36732]="照做！把迅猛龙给他！我不喜欢他把剑指在我脸上的感觉！"
D.Strings[36733]="我想我失去它们了。"
D.Strings[36734]="已发现光学感应故障！正在关闭中……"
D.Strings[36735]="军事区危险已排除，而且我们已成功撤离该区市民！"
D.Strings[36736]="秘法区里已经没有元素了。我们还救出了所有被困住的人！"
D.Strings[36737]="我被打断了！去叫阿莱克斯！"
D.Strings[36738]="巨人倒下了。快杀了他！"
D.Strings[36739]="铁炉堡遭到了攻击！要是你想进去，你最好足够强壮以参与到保卫城市的战斗中去。$B$B国王麦格尼·铜须已下达全面撤离的命令，并要我负责这项工作。不要进去了，万一你受伤又要怪到我头上来！"
D.Strings[36740]="但愿你会飞，小不点儿！"
D.Strings[36741]="就是那样，$n！"
D.Strings[36742]="现在决不能松懈，$n！"
D.Strings[36743]="继续作战，$n！"
D.Strings[36744]="你令人闻风丧胆的$c威名可真是名不虚传啊，$n！"
D.Strings[36745]="你的作战技巧可真令人难忘，$n。"
D.Strings[36746]="简直无懈可击，$n！"
D.Strings[36747]="千万别松懈，想都别想，$n！"
D.Strings[36748]="持续攻击，$n！"
D.Strings[36749]="你是最具战斗力的斗士，$n！"
D.Strings[36750]="嘿，$c！$B$B有兴趣签几份赚钱的合约吗？我会分给你十分之一！百分之一的十分之一！"
D.Strings[36751]="到底是怎么回事，$c？$B$B码头附近有传言说，你最近一直在我的建筑工地附近游荡……"
D.Strings[36752]="没人敢不把加尔鲁什·地狱咆哮放在眼里。你赶紧造好这些船——还要造得漂亮——否则就是给你自己找麻烦。"
D.Strings[36753]="我用不着别人来告诉我该怎么在这儿做生意。"
D.Strings[36754]="做好准备！大地在震颤，火焰也燃烧得更猛烈！要是你还能逃脱，就赶紧走！"
D.Strings[36755]="小心那些滚落的石头！大地颤动得更为剧烈了。快逃离城市！"
D.Strings[36756]="铁炉堡的市民们！开始撤离！"
D.Strings[36757]="铁炉堡的宾客们！快离开！城市随时都会倒塌！"
D.Strings[36758]="小心那些滚落的石头！清空街道！"
D.Strings[36759]="快逃离城市！大地还在不停的颤动！"
D.Strings[36760]="天黑下来了，元素们变得越来越躁动不安！快找地方躲起来！"
D.Strings[36761]="做好防卫！云团滚滚而来，狂风骤起！快躲起来！"
D.Strings[36762]="雷霆崖的市民们！撤离城市！"
D.Strings[36763]="风力越来越大了！快乘升降机去安全的地方！"
D.Strings[36764]="清空道路！别待在绝壁两侧！"
D.Strings[36765]="撤离雷霆崖！都别待在绝壁两侧！"
D.Strings[36766]="只是几颗铆钉而已。船上多得是！"
D.Strings[36767]="我确定它在平静的水域中航行时一定会平稳得多。"
D.Strings[36768]="少几颗铆钉就意味着更整洁的环境！"
D.Strings[36769]="……我们能用钱解决这个问题吗？"
D.Strings[36770]="好吧好吧，停！停！你可真有说服力。"
D.Strings[36771]="我会让工人们加班加点，再从自己的腰包里掏钱来让这些船能禁得起大风大浪并且按时交工。放心吧！"
D.Strings[36772]="关于此次攻击没什么混乱的。元素和巨人们有组织地前来对付我们。看来我们在不经意间引起了石母本人——塞拉赞恩的愤怒。"
D.Strings[36773]="欢迎来到祖尔格拉布，小不点儿。它现在的样子可能和以往大相径庭，但假以时日……"
D.Strings[36774]="啊……回家的感觉真好。"
D.Strings[36775]="在这儿有许多像你一样的人，可我并不担心竞争。你有着我的老朋友——奥根的血统。你看……我们的灵魂交织在一起，你的和我的。"
D.Strings[36776]="好了，准备开始训练吧，小家伙。我建议你忘记关于$r $c那些没用的东西，开始思考你在祖尔格拉布的责任。"
D.Strings[36777]="没有了！安戈龙格回家了！"
D.Strings[36778]="弱小的巨魔别想阻止安戈龙格！"
D.Strings[36779]="祭司了解很多与祖尔格拉布有关的事。$b$b祭司认为你需要她的帮助。"
D.Strings[36780]="我准备好开始意识影像仪式了，胡纳拉。"
D.Strings[36781]="你给我回到围栏里去！"
D.Strings[36782]="碎轮的失败将向他的主人瑟玛普拉格发出强大的信息。诺莫瑞根的侏儒是不可被阻止的！"
D.Strings[36783]="我已经准备好发起攻击了。"
D.Strings[36784]="我已得出结论——你必须死！"
D.Strings[36785]="我应该……预见到……的……"
D.Strings[36786]="机械师瑟玛普拉格拒绝承认他的失败已经近在眼前！现在，他又派出了拉兹诺·碎轮来阻止我们重新建设我们亲爱的诺莫瑞根！"
D.Strings[36787]="但是我们勇敢的朋友$n已经挫败了他们的邪恶计划。铁炉堡的矮人也在与我们并肩作战！"
D.Strings[36788]="让我们击败他，让他爬着回去见他的主子！"
D.Strings[36789]="你！怎么可能逃过我的哨兵机器人？这不可能！"
D.Strings[36790]="没有关系！我会带领护卫迅速地干掉你。准备战斗！"
D.Strings[36791]="我们成功了！我们胜利了！"
D.Strings[36792]="主动式负载平衡器！"
D.Strings[36793]="碎轮被打败了，瑟玛普拉格一定正在他的机械坦克里发抖，下一个完蛋的就是你，瑟玛普拉格，下一个就是你！"
D.Strings[36794]="这就是你招惹强大铁炉堡和诺莫瑞根的下场！"
D.Strings[36795]="对，让我们给这脑筋错乱的侏儒上一课！"
D.Strings[36796]="$n一把推开斯姆特，把他丢到了地上。"
D.Strings[36797]="喔主动式负载平衡器……我让你失望了！"
D.Strings[36798]="他们正在西北边的战场上等着你！快去吧！"
D.Strings[36799]="神殿被包围了。我们需要你出去，马上！"
D.Strings[36800]="到战场上去！"
D.Strings[36801]="继续前进！他们需要你前去支援！"
D.Strings[36802]="我们在西北面拖住他们了——增援前线！"
D.Strings[36803]="我们的兄弟们在西北面遇到了危险。快去帮帮他们！"
D.Strings[36804]="土元素转而攻击我们了。快到战场上阻击他们！"
D.Strings[36805]="我们被元素和巨人包围了！西北面需要你的援助，大地守护者！"
D.Strings[36806]="将炉石绑在此处。"
D.Strings[36807]="购买食物和饮料。"
D.Strings[36808]="你可以在此休息，这里还有食物和饮料可供享用。"
D.Strings[36809]="你永远也不可能战胜真正的诺莫瑞根之子！"
D.Strings[36810]="为主动式负载平衡器欢呼！"
D.Strings[36811]="一部主动式负载平衡器就能统御一切！"
D.Strings[36812]="来见证——主动式负载平衡器。"
D.Strings[36813]="是我把它造出来。它是我的。主动式负载平衡器！"
D.Strings[36814]="喔，主动式负载平衡器。有什么是你办不到的吗？"
D.Strings[36815]="我爱你，主动式负载平衡器！"
D.Strings[36816]="在第一天的黎明到来之时，主动式负载平衡器就看到了它所引发的一切，瞧瞧，多好。"
D.Strings[36817]="你可真勇敢，居然想要逃走，年轻的奥根阿卡。$b$b在你继续之前，让我教你如何用牙齿咬破那些巨魔的网。"
D.Strings[36818]="<从年老迅猛龙那里学习用牙咬穿网的技能。>"
D.Strings[36819]="你要离开迅猛龙巢穴了吗？我奉命守卫这岗哨并阻止逃逸，不过……我想我明白你为什么会想要离开。$b$b好吧。你可以通过这里，但首先，我有个要求。$b$b巨魔们经常会携带好多包迅猛龙爱吃的食物，而我已经许多天没进过食了。也许你打架毫无胜算，可你身形小巧，应该能趁那些巨魔熟睡时从帐篷里偷点儿吃的出来……"
D.Strings[36820]="好吧，特基乌。我去从那些熟睡的巨魔身边帮你偷些吃的。"
D.Strings[36821]="我给你带回一些食物。"
D.Strings[36822]="能走到这一步可真令人印象深刻啊，奥根阿卡。你可真是只天赋异禀的年轻迅猛龙……可最难通过的考验还在后面呢。$b$b巨魔们就在前方的桥附近巡视，他们的注意力很难被分散。可要是你能在他们的必经之路上放块头骨，也许能把他们绊个跟头……"
D.Strings[36823]="<从年老迅猛龙那里学习丢落头骨的技能。>"
D.Strings[36824]="抓住你了！"
D.Strings[36825]="我准备好开始意识控制仪式了，胡纳拉。"
D.Strings[36826]="绳子已经紧紧绕在他的脚踝上了。拉动绳子把他绊倒！"
D.Strings[36827]="到这儿来，你这傻大个儿！"
D.Strings[36828]="你！快放开我！等等……不！别放手！"
D.Strings[36829]="$n与大工匠梅卡托克和巡山人石磨一起击败了拉奇诺·碎轮！"
D.Strings[36830]="英雄们载誉凯旋了！寒风峡谷的控制权又是我们的了！"
D.Strings[36831]="$g阁下，是阁下:女士，是女士;！"
D.Strings[36832]="$g马上，阁下:马上，女士;！"
D.Strings[36833]="终于胜利了！"
D.Strings[36834]="抱歉，$g阁下:女士;！"
D.Strings[36835]="不会再有下一次，$g阁下:女士;。"
D.Strings[36836]="请别让督军知道……"
D.Strings[36837]="回到顶上找我。这个双头怪物有几个问题要回答！"
D.Strings[36838]="好吧，好吧，我放弃！我什么都告诉你！"
D.Strings[36839]="严厉训斥一个擅离职守的兽人步兵。"
D.Strings[36840]="你又不是我老大！"
D.Strings[36841]="我看这个$c是想要找茬打架。"
D.Strings[36842]="你想试试吗？！"
D.Strings[36843]="那个愚蠢的$r认为$g他是:她是;我的头儿。"
D.Strings[36844]="$C，你刚为自己争取到一顿海扁。"
D.Strings[36845]="我错了——我马上回到岗位上去！"
D.Strings[36846]="够了！我不该质疑你的命令……"
D.Strings[36847]="那是我几个星期以来最痛快的一次吵架了！我要把剩下的留给我们的敌人。"
D.Strings[36848]="你可真能打！希望你能和我一起前往高地。"
D.Strings[36849]="你现在可以参与黑石岩窟的测试了，这是位于黑石山的一座79-81级地下城。请在传送至地下城之前组满队伍。集合石目前对该地下城不可用。\n\n若要离开岩石大厅，只需从位于地下城内的普通出口离开即可，你将被自动传送至达拉然。如果你在战斗中死亡并释放灵魂，你则需要通过该NPC传送回地下城。"
D.Strings[36850]="我已组好队伍，准备好被传送到黑石岩窟了！"
D.Strings[36851]="送我回黑石岩窟！"
D.Strings[36852]="擅离职守的兽人步兵投了投骰子。"
D.Strings[36853]="梅卡托克——大炮！"
D.Strings[36854]="骰子不会说谎！"
D.Strings[36855]="你骗人。"
D.Strings[36856]="梅卡托克——激光！"
D.Strings[36857]="梅卡托克——导弹！"
D.Strings[36858]="梅卡托克——射线！"
D.Strings[36859]="谁把它放在这儿的，伙计？哇啊……"
D.Strings[36860]="我……我失去……平衡了……老兄……"
D.Strings[36861]="哎呦，伙计！我被绊倒了！"
D.Strings[36862]="你要去哪儿，小家伙？"
D.Strings[36863]="你想要逃出祖尔格拉布？"
D.Strings[36864]="谁也别想从祖尔格拉布逃出去！只要金度在，就别想！"
D.Strings[36865]="你该庆幸我现在不会马上杀了你……不过我为你准备了更重要的任务。"
D.Strings[36866]="你看……要想召唤哈卡，我就需要曼多基尔。而曼多基尔，他需要你。"
D.Strings[36867]="你好啊，奥根阿卡。"
D.Strings[36868]="血领主，你要更用心地照看你的财产吗？"
D.Strings[36869]="喔没错，金度。我们会非常小心地照料奥根阿卡。"
D.Strings[36870]="我造了个新笼子，而且我们有许多种手段来……教她打消逃跑的念头。"
D.Strings[36871]="很好，很好。还有你……对，就是你……在意识控制法术中忙活的虫子。别以为金度看不见你。"
D.Strings[36872]="等你有勇气回到这里时，可一定要做好准备。因为金度为你准备了一份惊喜……"
D.Strings[36873]="你好，朋友！$B$B酋长命我集结他麾下最精锐的部队攻击暮光高地。$B$B你看起来底子不错，$c，可我们需要的士兵得更加……久经沙场一些。也许有一天你和我能并肩作战。在那以前，继续加紧训练吧！"
D.Strings[36874]="你好，朋友！很高兴见到诺森德战役的老战友。$B$B酋长命我集结他麾下最精锐的部队攻击暮光高地。$B$B<酋长把你上下打量了一番。>$B$B我们也许需要你的帮助。去奥格瑞玛的酋长那里，看看他有没有任务交给你。"
D.Strings[36875]="|TInterface\\Icons\\inv_misc_net_01.blp:32|t$b$b用把网罩一起吃掉的技能咬穿古拉巴什的网！"
D.Strings[36876]="从熟睡的古拉巴什士兵身上偷取食物！"
D.Strings[36877]="|TInterface\\Icons\\spell_fire_fire.blp:32|t$b$b从火盆里取出燃烧的树枝，然后用点火技能烧毁祖尔格拉布神像！"
D.Strings[36878]="|TInterface\\Icons\\inv_misc_bone_orcskull_01.blp:32|t$b$b从巫毒堆里取出古拉巴什徽记，然后丢在巨魔的必经之路上！"
D.Strings[36879]="一位士兵在这样的城镇里能惹上许多麻烦。$B$B许多麻烦。"
D.Strings[36880]="谢谢你。$b$b作为回报，我会教你如何分散前面那群巨魔的注意力。"
D.Strings[36881]="神像！快把火扑灭！"
D.Strings[36882]="着火了！动作快伙计！"
D.Strings[36883]="有人在烧我的神像！"
D.Strings[36884]="到这儿来，兄弟们，赶快！"
D.Strings[36885]="你想逃走？没问题，可你必须得先了解一些事情。$b$b离那些巨魔远点儿。他们不会杀你，可他们会困住你然后把你带回来。$b$b和你所见到的每只迅猛龙都打个招呼。它们不仅能教你新的技能，还会帮你记住你的进度，让你能更加容易地逃离祖尔格拉布。$b$b你已经学会了急奔技能——用它来脱离险境吧。$b$b喔……还要注意别下水。$b$b祝你好运！"
D.Strings[36886]="|cFF768EBD五年前，在死亡矿井的中心……|r |TInterface\\QuestFrame\\UI-QUESTLOG-BOOKICON.BLP:32|t"
D.Strings[36887]="呀，你对我这儿的东西都没兴趣，$g小男孩:小女孩;。$B$B快走开！"
D.Strings[36888]="喔，嚯！喔嚯嚯。$B$B呦嚯嚯，扯平。$B$B去往暮光高地的航班正在准备中。与此同时，我愿意送你去——全速直达。$B$B你信任我吗，$c？"
D.Strings[36889]="嗯，送我去吧！"
D.Strings[36890]="是我带领暗矛部族来到这儿。但现在奥格瑞玛已经不再是我们的家了。"
D.Strings[36891]="不过，我也在担心会过于意气用事。萨尔竭尽心力，才让部落成为今天这个样子，我不想因为一时冲动就离开。我需要再好好想想。"
D.Strings[36892]="沃金。很高兴看到你，兄弟。"
D.Strings[36893]="这是老祖尼最后的请求。"
D.Strings[36894]="你会变成了不起的人，别忘了我，兄弟。"
D.Strings[36895]="兽人消灭$r！"
D.Strings[36896]="求饶吧！"
D.Strings[36897]="把你吃掉！"
D.Strings[36898]="黑石夺取森林！"
D.Strings[36899]="葡萄可真香甜！"
D.Strings[36900]="把所有金子都交出来！"
D.Strings[36901]="谁也别想活着离开！"
D.Strings[36902]="你在错误的时间来到了错误的地点，$g小伙子:小姑娘;！"
D.Strings[36903]="要钱还是要命！"
D.Strings[36904]="是命运把你带到我的面前！"
D.Strings[36905]="她没撒谎。诺达希尔处于险境之中。我必须加紧准备海加尔的防御。"
D.Strings[36906]="这次将由你来使用远古号角，阻止索苟斯的回归。"
D.Strings[36907]="啊……玛法里奥·怒风。我原本希望能再把你多拖住一会儿。我的目标是要保证在我的盟友出击时，让你远离海加尔。看来我已经成功了。"
D.Strings[36908]="我根本不用和你作战，因为我显然已经赢了。你不能在阻止我们攻击黑海岸的同时，还能救得了海加尔山！"
D.Strings[36909]="你不属于这个世界，邪恶的生物！忍受自然的愤怒吧！"
D.Strings[36910]="我要吞噬你们的灵魂，无礼的凡人！"
D.Strings[36911]="送我去奥格瑞玛。"
D.Strings[36912]="我们在这儿的任务完成了。莫高雷不会再受到恐怖图腾仇恨的侵扰。"
D.Strings[36913]="我会在雷霆崖上与你再次会面。"
D.Strings[36914]="<从年老迅猛龙那里学习点火的技能。>"
D.Strings[36915]="刀刃插进了莫什奥格的馈赠，把它打开！"
D.Strings[36916]="%s皮肤"
D.Strings[36917]="你待在后面！那巨魔是我的！"
D.Strings[36918]="劈颅……是……永存的……伙计……"
D.Strings[36919]="赞吉尔正在集结一支荡涤荆棘谷的大军！血顶、劈颅、古拉巴什与部落……都将为赞吉尔效命！"
D.Strings[36920]="与大地作对的人就只有死路一条！"
D.Strings[36921]="你不属于土地的国度！"
D.Strings[36922]="呃哦……我要……嗝儿！"
D.Strings[36923]="非常感谢你的点心！"
D.Strings[36924]="嗯，谢谢！"
D.Strings[36925]="再见！"
D.Strings[36926]="$c，欢迎来到格罗姆高。为了避免今后发生问题，我现在要提醒你，我的营地里可容不下懒人。希望像你这样的健康$r能在这里发挥出应有的作用。"
D.Strings[36927]="即使是在这个世界如此偏远的角落里，都不要忘记地狱咆哮的双目在注视着你。"
D.Strings[36928]="荆棘谷的巨魔对我们暗矛部族并不怎么友好。我不怕那些血顶或劈颅，可是……格罗姆高的高墙令我感到安全。"
D.Strings[36929]="也许格罗姆高并非像我想的那么安全。$b$b身为巨魔，不论走到哪里，都要随时小心自己的脖颈被偷袭。"
D.Strings[36930]="<大锅在冒着气泡。>"
D.Strings[36931]="我的兄弟多年来一直在研究使麻风侏儒痊愈的方法。通过研习他的笔记，我想我已经完善了流程——可以使那些已经被认定无药可救的侏儒回复到从前的样子。"
D.Strings[36932]="炮兵的双手沾满了黑色的火药粉。"
D.Strings[36933]="<巨魔自己唱着歌，眼睛看着锅里。他像是受了伤。>"
D.Strings[36934]="让我们试试这个。所有人带好眼镜！"
D.Strings[36935]="在那片丛林里可藏着许多钱，$r。你看见了吗？$b$b不，这钱的样子跟你平时见到的金币或铜币不同。它的外观是迅猛龙的龙皮，还有矿脉，以及古老的巨魔圣物。$b$b好吧，也许矿脉和金币铜币的样子有点儿像。$b$b不过反正你明白我的意思了，对吧？"
D.Strings[36936]="伟大的拉斯塔哈为你送来了问候，部落的成员。"
D.Strings[36937]="真了不起！我们成功了！"
D.Strings[36938]="当然，他个子小了点儿，即使是按侏儒的标准来看也一样，可他够机敏！关键问题是，他还记得什么？"
D.Strings[36939]="别把我当空气！我只知道我现在饥肠辘辘，我还要脱掉这身又臭又脏的衣服！"
D.Strings[36940]="等等，快回来！我还要读取信息！"
D.Strings[36941]="你该看医生了！"
D.Strings[36942]="看看这是谁，$n？"
D.Strings[36943]="我们是要前往大地神殿，对吧？"
D.Strings[36944]="把我带到你这位大地之环的朋友那里去。我有重要的消息要告诉给你们两位。"
D.Strings[36945]="船长的日志就放在附近。"
D.Strings[36946]="唯一要紧的事是救出我父亲。"
D.Strings[36947]="你必须放下手头所有事情，全力帮我救出我的父亲——土灵之王。"
D.Strings[36948]="我们必须抓紧时间并与你大地之环的朋友交谈。"
D.Strings[36949]="当我受到攻击时我正在前往神殿的途中。必须在石头穴居人对我父亲下手前把他救出来。"
D.Strings[36950]="土灵与石头穴居人的战争已经不知持续了多少年。可在眼下这混乱之中，他们竟然将土灵之王囚禁了起来。他们威胁说，如果我们不投降，就杀了他。"
D.Strings[36951]="你要是聪明就别耽误时间。要是我父亲死了，那世界之柱中部碎片的位置也将和他一同消亡。我知道你们这些人想要得到它。"
D.Strings[36952]="唤地者，我的父亲，岩幔国王，已经被针石熔渣场的石头穴居人抓为了俘虏。"
D.Strings[36953]="我要你派人前往巨石之炉。帮我们打赢这场仗，把岩幔国王救出来。"
D.Strings[36954]="帮我的这个人应该能够胜任。让他们去报告给我们在巨石之炉的军队指挥官——克拉格·摧石者。"
D.Strings[36955]="你必须飞往巨石之炉，帮我的人民击败石头穴居人，救出我的父亲。$B$B等我与唤地者谈过之后就会去那里找你。$B$B别让他死了，$n，否则我会亲手把你埋进地里！"
D.Strings[36956]="我已经准备好与你口中的唤地者会面了。"
D.Strings[36957]="外壳上写着：“暴风城皇家工业集团”"
D.Strings[36958]="你去过丛林吗，$r？$b$b那可真是个好地方。"
D.Strings[36959]="荆棘谷，$g伙计:宝贝儿;。就在那儿！"
D.Strings[36960]="啊，要是再回到荆棘谷。那些发出尖啸的迅猛龙，巨魔间的战争，目力所及处各式各样的丛林生物，就等着人们的捕杀……$b$b<博特叹了口气。>"
D.Strings[36961]="我的机器人就要大功告成了。"
D.Strings[36962]="终于，完成了。"
D.Strings[36963]="起来吧，我的……我该叫你什么好呢？叫你“多功能机器人”怎么样？起来吧，我的多功能机器人！"
D.Strings[36964]="呃……看来还需要略做调整……"
D.Strings[36965]="难道你又带了一队人来，会吗？我们这儿已经没有人手了。"
D.Strings[36966]="$r来了！"
D.Strings[36967]="又有个$r进来了！"
D.Strings[36968]="$R进入！"
D.Strings[36969]="欢迎来到赤脊山，$c！"
D.Strings[36970]="时刻保持警惕，$c。"
D.Strings[36971]="保持警觉，$c。"
D.Strings[36972]="暮光教派中存在着对我们具有严重威胁的法术。$B$B我们恨不得马上让他们滚出我们的家园。$B$B我们被分开了，所以我们不能这么做。$B$B于是我在观望着……$B$B等待着……"
D.Strings[36973]="又一只岩虫！快杀了它！"
D.Strings[36974]="我们遭到攻击了！准备作战！"
D.Strings[36975]="营地里又出现一只岩虫！快召唤龙！"
D.Strings[36976]="以元素的名义，这个比之前的还要大！"
D.Strings[36977]="出发，$c。"
D.Strings[36978]="$R正驶离赤脊山！"
D.Strings[36979]="$C正驶离赤脊山！"
D.Strings[36980]="大地之环必亡！"
D.Strings[36981]="深岩之洲会塌在你们身上！"
D.Strings[36982]="面对暮光炫目的怒气吧！"
D.Strings[36983]="死亡之翼的阴影笼罩着你。"
D.Strings[36984]="塞拉赞恩必死无疑！"
D.Strings[36985]="你的世界已经破碎！很快，你也将成为这世上的亡魂！"
D.Strings[36986]="暮光的敌人只有死路一条！"
D.Strings[36987]="暮色降临！在恐惧中战栗吧！"
D.Strings[36988]="拉奇诺·碎轮已经完蛋了！铁炉堡和诺莫瑞根的成员们今天团结在了一起。给我听好了，瑟玛普拉格。你被我们消灭的日子也不远了！"
D.Strings[36989]="最好弄成个火箭专家。"
D.Strings[36990]="奇怪……昨天我刚刚被决定派往灰谷。"
D.Strings[36991]="我在半途接到与你们汇合的命令。这准是个重要的任务。"
D.Strings[36992]="你没听说吗？"
D.Strings[36993]="一座岛屿从深渊里升了起来……就在暴风城的海岸边。"
D.Strings[36994]="我们要去占领它。"
D.Strings[36995]="一旦我们成功，暴风城就没几天好日子了。"
D.Strings[36996]="一座岛屿从海里冒出来……暴风城在它的攻击范围内？"
D.Strings[36997]="送我去恶齿村。"
D.Strings[36998]="这绝不是巧合！艾泽拉斯世界正眷顾着部落！"
D.Strings[36999]="给，战士。吃掉它。"
D.Strings[37000]="它能让你变得更加灵敏，更加坚韧。"
D.Strings[37001]="哈！我不需要这种玩意儿，朋友。"
D.Strings[37002]="我曾经面对过暴风城最强的战士，而我还是站在这儿。"
D.Strings[37003]="我干掉的联盟战士可不比你少，兄弟。也许更多。"
D.Strings[37004]="只有彻底的胜利才能让地狱咆哮满意。"
D.Strings[37005]="要是我们失败了，他会一直追到地狱来惩罚我们的。"
D.Strings[37006]="恩，你的话语中包含着智慧，兄弟。我会带上你的食物……"
D.Strings[37007]="当然，兄弟。就是这样……"
D.Strings[37008]="好运相伴，$n！"
D.Strings[37009]="好的，我也要。"
D.Strings[37010]="我们是地狱咆哮的先锋！"
D.Strings[37011]="为什么我们要乘着这些可悲的雇佣兵船去打仗？"
D.Strings[37012]="其他的舰队都已经被派往战区了。"
D.Strings[37013]="…但他们迟迟没有返航。"
D.Strings[37014]="哈！他们早知道该先派我们出马。"
D.Strings[37015]="我同意，兄弟，部落最近征战不断，可先锋战士的数量却不够……"
D.Strings[37016]="我们的敌人真走运，我们每次只能出现在一个地方。"
D.Strings[37017]="准备作战！我们已经对邪枝部族忍无可忍！"
D.Strings[37018]="闲聊结束！我们的船来了。"
D.Strings[37019]="这是由地狱咆哮亲自派来的。"
D.Strings[37020]="你们都给我记住—— 不得侵扰船员！"
D.Strings[37021]="我们必须终结渗入灰谷的堕落之息。"
D.Strings[37022]="呜……这艘船上有人类的臭气。"
D.Strings[37023]="哈！人类……"
D.Strings[37024]="听我号令，弟兄们！"
D.Strings[37025]="我们将航向一座新生的岛屿，那是艾泽拉斯世界赠予部落的厚礼！"
D.Strings[37026]="占领那岛屿，我们就能赢得这场战争！"
D.Strings[37027]="就联盟而言，敌人的表现还不错……但他们已经显出疲态了。"
D.Strings[37028]="我们将摧毁剩下的敌人，并占领那座岛屿。"
D.Strings[37029]="以它为桥头堡，我们将征服暴风城，粉碎敌人依靠的任何希望。"
D.Strings[37030]="艾泽拉斯世界将会重新臣服同一面旗帜之下！"
D.Strings[37031]="这面旗帜！"
D.Strings[37032]="我们不能再任由我们的敌人——瑟玛普拉格，继续对诺莫瑞根的其余地区施行统治了。"
D.Strings[37033]="他已经命部下——拉奇诺·碎轮来让我们疲于防御。辛克尔斯，有什么关于拉奇诺和他手下的最新情报吗？"
D.Strings[37034]="我们的侦察兵很难获知碎轮的计划。"
D.Strings[37035]="快上船来，快点。踩上来！"
D.Strings[37036]="据我们所知，碎轮正在使用一种先进的步行坦克原型，而他手下那些被辐射的侏儒们正在破旧的兵工厂里奋力修复更多同类坦克。"
D.Strings[37037]="若想单凭我们的力量解决简直太难了。我已经送信到矮人主城铁炉堡，请求他们的支援。"
D.Strings[37038]="要是你往你的左边看看，就会发现侏儒们已经夺回了诺莫瑞根！我们真是太伟大了！"
D.Strings[37039]="外面也有许多事情正在发生。通往机场的路线打通了，在东边有关于黑铁部族的传闻……噢，我想矮人国王麦格尼最近也有些不太对劲。也许应该去查清楚。"
D.Strings[37040]="这意味着什么？！"
D.Strings[37041]="我们到了！欢迎来到卡拉诺斯！出去时请小心脚下。"
D.Strings[37042]="我们必须胜利！"
D.Strings[37043]="有位来自烈酒村的信使今早抵达了这里。矮人们正派出一支巡山人小队来帮我们。"
D.Strings[37044]="当巡山人抵达时，我们必须做好对付碎轮的准备。"
D.Strings[37045]="打败碎轮之后，瑟玛普拉格肯定会立刻启动他的步行坦克。你的下一个目标就是瑟玛普拉格！下一个目标就是！"
D.Strings[37046]="准备好打斗了吗，$g小伙子:小姑娘;？"
D.Strings[37047]="多管闲事的虫子们！你以为你能轻易地打败我们？"
D.Strings[37048]="坚守信念，兄弟们！浴血杀敌！"
D.Strings[37049]="深岩之洲是个平静而节奏缓慢的地方。永远都充满生机，平稳改变，有条不紊。我一度努力与大地融为一体。在很大的程度上，我成功了。$B$B后来，大地的守卫者回来了，身上带着累累伤痕。起初他并没有扰乱平衡。他曾经在这里生活过，我们了解他。直到暮光教派开始和他打交道以后，他才真正开始发生了变化。"
D.Strings[37050]="当大地守护者逐渐恢复的时候，他开始不满足于这里的安静与和平。没过多久，他就驱使岩石巨龙攻击我们。$B$B死亡之翼离开之后，它们一直没有明确的目标。我们能够让它们明白我们的力量，再次将它们送回到大地母神的怀抱中。"
D.Strings[37051]="所以我看到你已经向岱亚曼塔发出了诉求。我接受的命令是容忍你的出现，凡人。但我对你的接受程度也仅限于此。$B$B不要忘记我们的第一次交谈。要得到我的信任，你还需要做很多事。$B$B你最好先离开吧。我已经厌倦了每迈出一步都必须小心不要踩到你这种事。"
D.Strings[37052]="请登船，朋友们！小心……"
D.Strings[37053]="都登船啦，这就对啦……"
D.Strings[37054]="请不要太在意……呃……我们船员的多样性。"
D.Strings[37055]="敬请放心。他们一定会把你们安全地送到目的地。"
D.Strings[37056]="那还是东部王国海岸边的处女地呢。"
D.Strings[37057]="好，大家坐稳啦……我们出发！"
D.Strings[37058]="从你身后传来了石头撞击的声音。"
D.Strings[37059]="砾石佩波欢快地上下蹦跳着。"
D.Strings[37060]="砾石佩波在周围欢快地滑动着。"
D.Strings[37061]="砾石佩波不停地绕着圈，显得非常欢快。"
D.Strings[37062]="砾石佩波快活地蹭着你的腿。"
D.Strings[37063]="砾石佩波伤心地趴了下去。"
D.Strings[37064]="砾石佩波伤心地转过了身。"
D.Strings[37065]="砾石佩波充满希望地抬头看着你。"
D.Strings[37066]="你听到砾石佩波体内石块的撞击声。他显得很是兴奋。"
D.Strings[37067]="砾石佩波的石块散落在地上，然后又慢慢地组合成一个完整的，快活的砾石佩波。"
D.Strings[37068]="砾石佩波看到前面的水晶，兴奋地向它们跑了过去！"
D.Strings[37069]="坚守不退！"
D.Strings[37070]="把这些石头穴居人赶回到地下去！"
D.Strings[37071]="援军来了！为了国王而战！"
D.Strings[37072]="你想要永生不死吗？"
D.Strings[37073]="撑住侧翼！"
D.Strings[37074]="这就是巨石之炉！"
D.Strings[37075]="以卡兹格罗斯的铁锤起誓，我们一定要消灭他们！"
D.Strings[37076]="为了岩幔国王！"
D.Strings[37077]="我没法在他们进攻的时候干这事儿！"
D.Strings[37078]="把这些石头穴居人赶走，这样我才能召唤岩石崩落！"
D.Strings[37079]="我没法在他们攻击我的时候继续进行仪式！"
D.Strings[37080]="$c，能不能先帮个小忙？"
D.Strings[37081]="等这些石头穴居人死掉之后，再把那些试剂给我。"
D.Strings[37082]="别让他们打到我，然后我才能封住这个缺口！"
D.Strings[37083]="我不知道他们是怎样从下面上来的。但如果不将他们击退，我就没办法把这个缺口封住！"
D.Strings[37084]="我们必须先击退这些石头穴居人。然后再把那些试剂给我。"
D.Strings[37085]="砾石佩波感激地来回蹦跳着。"
D.Strings[37086]="为了巨石之炉！"
D.Strings[37087]="消灭石头穴居人！"
D.Strings[37088]="感恩吧，公民。我推荐你去见卫兵帕克。他就在这座塔的顶上。"
D.Strings[37089]="兴奋的砾石佩波引起了附近剥石者的注意！"
D.Strings[37090]="好了，宝贝儿。快把你知道的都说出来，别逼我动手！"
D.Strings[37091]="等等！你不能这么做！你们总得有点儿荣誉感还是什么的！"
D.Strings[37092]="我是蛮锤部族的女儿，大地之环的萨满祭司。我的信条迫使我捍卫祖先与元素的荣耀。"
D.Strings[37093]="别胡扯那些有关脏垢食人魔的事。"
D.Strings[37094]="你可以从世界之柱碎片的下落开始说。带着你这个胖子飞了这么长的时间，我的狮鹫看上去有点儿累了。"
D.Strings[37095]="快住手，你这狂暴的小女人！我把一切都告诉你！你想知道什么？"
D.Strings[37096]="它被送到了死亡之翼的陨落地，交到了铸炉之主的手里。我就知道这么多了！"
D.Strings[37097]="有人吗……请……把……这块……石头……挪开……"
D.Strings[37098]="疼啊……真是太疼了……"
D.Strings[37099]="我……只……想……建好……这座……该死的……桥……"
D.Strings[37100]="你从来没有生命危险，宝贝儿。我朋友在下面会接住你的。你活着对我们的价值可太大了！"
D.Strings[37101]="满意了吗？快把我拉起来，你这凶残的矮子！"
D.Strings[37102]="什么？不……你都干了什么？不，你知不知道要是暮光议会发现我开了口，我会有什么下场？我宁可早点死！"
D.Strings[37103]="有趣。在这以前我还从来没听说过暮光议会。"
D.Strings[37104]="把你们的后背靠上去，孩子们！"
D.Strings[37105]="该死的石头，就是不动！"
D.Strings[37106]="继续用力！"
D.Strings[37107]="我已经拼尽全力了！这东西肯定有一吨重！"
D.Strings[37108]="我们会救你出来的，工头。坚持住！"
D.Strings[37109]="$n，要去岸边？$B$B只要你说一声，我就会为你放下一艘小船。"
D.Strings[37110]="送我去岸边，霍尔佐格。"
D.Strings[37111]="嗯，这并不好。你的两辆蒸汽坦克都在战斗中损毁了。我的搜救队在确认安全之后就会把它们的残骸取回来。"
D.Strings[37112]="只要有足够的配件和一支工程师队伍，你的坦克就能得到彻底修复。但这还需要很长一段时间。"
D.Strings[37113]="可怜的巨魔碾压者。至少这个老女孩竭尽全力做了一件她喜爱的事情。"
D.Strings[37114]="振作起来，石轮！你是一名蒸汽坦克驾驶员，为圣光而战！"
D.Strings[37115]="他们怎么敢囚禁我们的国王！$B$B我们要夺回巨石之炉，然后将战线推进到石头穴居人的老窝，在那里彻底粉碎他们！"
D.Strings[37116]="霍尔佐格下令将一艘登陆艇放进水中。"
D.Strings[37117]="让我们从这里出去，把那些石头穴居人赶回到地底去，$r！"
D.Strings[37118]="拉兹，告诉他一切都会好起来的！"
D.Strings[37119]="我需要你上阵支援我，$n。$B$B你将使战局产生逆转。我们将一举击溃石头穴居人。$B$B我们必须救出岩幔国王！"
D.Strings[37120]="是的，是的，一切都会好起来的！会变得非常好。她会比以往任何时候都更好！"
D.Strings[37121]="<克莱嘟囔着，冷笑着。>$B$B这个该死的时代。"
D.Strings[37122]="好了，我立刻就去看看那些装备！"
D.Strings[37123]="看到了吗？老巨魔碾压者很快就会好起来的！用不了多久，你就又会吹牛说赢过我了……"
D.Strings[37124]="好了，再来一杯啤酒吧。"
D.Strings[37125]="等到仪式完成的时候，玛尔纳就会到来。我的人会帮忙塑造出这个奇异的怪物。"
D.Strings[37126]="想象一下最令人惊叹的升降机会是什么样子……它就在这里。很漂亮，不是么？糟糕的是，它还没有准备好。"
D.Strings[37127]="现在就传送我。我已经等不及使用那个漂亮的升降机了！"
D.Strings[37128]="耐心……我们的机会就要来了。"
D.Strings[37129]="<鱼人用饥渴的眼睛看着你。>"
D.Strings[37130]="<给这个鱼人一些喝的。>"
D.Strings[37131]="$R来看奥古斯？照相，待久一些。"
D.Strings[37132]="<给这个食人魔一些喝的。>"
D.Strings[37133]="呀，谁也不会有我这样渴。"
D.Strings[37134]="<给这个海盗一些喝的。>"
D.Strings[37135]="死亡之翼的侵入在我们的世界和深岩之洲之间打开了一道裂隙。$B$B重建世界之柱是唯一控制住裂隙的方法。"
D.Strings[37136]="谈判进展得并不顺利，$n。龙喉氏族还不是意志自由的兽人。$B$B不管怎样，我们必须争取他们加入部落！$B$B如果你要返回舰队，就告诉我。"
D.Strings[37137]="石头没有多重！小人类！"
D.Strings[37138]="能给我一艘船返回舰队么？"
D.Strings[37139]="扔去哪儿？扔到桥上？"
D.Strings[37140]="古穆尔格要跟随你。"
D.Strings[37141]="好吧！扔到水里！"
D.Strings[37142]="欧纳克下令让一艘小艇去舰队。"
D.Strings[37143]="哦……奥古斯觉得不太好……"
D.Strings[37144]="奥古斯觉得$r柠檬水有问题……"
D.Strings[37145]="再见，爸爸！"
D.Strings[37146]="该死的！这个旱鸭子无赖来拿朗姆酒了！"
D.Strings[37147]="什么？"
D.Strings[37148]="天哪！"
D.Strings[37149]="不，不，不！求求你！"
D.Strings[37150]="千万不要是那座桥！"
D.Strings[37151]="去哪里，朋友？"
D.Strings[37152]="如果你需要一艘小艇去岸边，就来找我，$n！"
D.Strings[37153]="我们已经陷在和霜鬃巨魔的战斗中了。"
D.Strings[37154]="我们的大多数蒸汽坦克都已经无法使用，而且我们的山地作战人员也损失惨重。"
D.Strings[37155]="很好，扎伊拉。我相信你做得对。$C，我能拯救你那些被打败的战士……"
D.Strings[37156]="我……我不能把我们的物资给你！我们的酋长……他会……"
D.Strings[37157]="格雷戈，你这个懦夫！兽人的鲜血正泼洒在我们的海岸上。如果你毁灭了他们，你就把我们全都毁了。"
D.Strings[37158]="欢迎来到奥格瑞玛火箭车换乘站！别担心，你看上去还是一整块儿的。"
D.Strings[37159]="$n，要知道，我们的“酋长”并不代表我们所有人的意志。我们之中有一些人希望看到龙喉氏族再次强大起来……并不再继续堕落下去。"
D.Strings[37160]="我们的物资也就快要耗光了，队长。由于巨魔和雪人的袭击，一周之内我们的定额口粮就得减半。"
D.Strings[37161]="我们已经坚持不了多久了。戴博和他的队伍必须尽快从钢架补给站发动进攻！"
D.Strings[37162]="别这么快，疯家伙！"
D.Strings[37163]="戴博和他的人正在没日没夜地工作，队长。他已经设计出一种手段，能够将进攻部队送到战场的侧后方。"
D.Strings[37164]="奥格瑞玛火箭车换乘站，谢谢。"
D.Strings[37165]="僵尸海盗？！消灭它！"
D.Strings[37166]="为了这次行动，我们还取得了空中支援。行动很快就要展开了。如果你们想要加入进攻部队，就去找戴博吧。"
D.Strings[37167]="南部火箭车终点站，谢谢。"
D.Strings[37168]="加里维克斯火箭车换乘站，谢谢。"
D.Strings[37169]="北部火箭车换乘站，谢谢。"
D.Strings[37170]="北部火箭车终点站，谢谢。"
D.Strings[37171]="很高兴听到这个消息。我会将能够调遣的部队全派给戴博。"
D.Strings[37172]="我们龙喉氏族经历过太多的磨难……在格瑞姆巴托的失败……那么多强大的战士死在外域……现在，暮光之锤又向我们发动了进攻。$B$B有时我会怀疑，我们是否还能再次强大起来。但像扎伊拉这样的年轻人让我们这些老骨头又有了希望。"
D.Strings[37173]="你需要什么，外乡人？我不应该和你说话的……"
D.Strings[37174]="我们的战士正一个个死去。你有药品能让我带回去吗？"
D.Strings[37175]="欢迎来到加里维克斯火箭车换乘站！付清债务，或者滚开。"
D.Strings[37176]="欢迎来到北部火箭车换乘站！我们火箭车相关人员很高兴你在最后一个转弯中活了下来！"
D.Strings[37177]="欢迎来到北部火箭车终点站！你也许转错了弯，但我们还是很高兴看到你！"
D.Strings[37178]="欢迎来到南部火箭车终点站！这里是世界闻名的秘密实验室之家！"
D.Strings[37179]="这个古老的图腾被雕刻成一只蝙蝠的形状。"
D.Strings[37180]="我们完了！我也许应该在兽人杀过来之前发出撤退令，疏散湖畔镇的居民。"
D.Strings[37181]="我们刚刚建好了那座该死的桥！$n，我们还有什么希望？"
D.Strings[37182]="希望仍然存在，所罗门。"
D.Strings[37183]="什么希望，上校？有什么能拯救我们，挡住敌人的进攻？"
D.Strings[37184]="他在第一次，第二次和第三次兽人战争时期完成过248个任务。"
D.Strings[37185]="在五年以前，他被一支肮脏下贱的黑石部队俘虏。他被俘的地方距离南部非军事区只有五分钟路程。"
D.Strings[37186]="在五年时间里，他不断地受到各种拷打和折磨，还成为了年轻兽人战士的溺器。"
D.Strings[37187]="约翰·J·基沙恩。"
D.Strings[37188]="基沙恩还活着？我还以为他已经死了。"
D.Strings[37189]="是的，他还活着，在过去的五个月里像个被放逐者一样活在湖畔镇。你没有注意到吗？我们已经聊够了。我还要去救人！"
D.Strings[37190]="我不知道我的交涉者在哪里。实际上，他可能已经死了。还有其他人选吗？"
D.Strings[37191]="我可不喜欢坐在这个洞里。真希望我们在等待达纳斯将军回来的时候能好好喝上一杯潘趣酒。"
D.Strings[37192]="嗨，这身红褂子就让我看上去是一件可消耗品吗？"
D.Strings[37193]="我准备好了，$n。龙喉氏族很快就会成为部落的一份子！"
D.Strings[37194]="我听说一位伟大的龙喉医师就住在右边的那座棚子里。"
D.Strings[37195]="这个古老的图腾被雕刻成一只蝙蝠的形状。它一定是查巴尔所说的图腾。"
D.Strings[37196]="将熏香放在这尊雕像的脚下。"
D.Strings[37197]="经过多次谈判之后，我期待一个长久的繁荣时代即将到来。"
D.Strings[37198]="龙喉酋长就在这里山顶上最高大的那座房子里。相信他是个通情达理的人。"
D.Strings[37199]="就是这里！跟紧我，让我来谈判。我是这方面的专家。"
D.Strings[37200]="欢迎来到鹰巢山，蛮锤部族的家园。$B$B大领主弗斯塔德·蛮锤已经前往铁炉堡，有事情的话可以和我说。"
D.Strings[37201]="战斗将在1分钟内开始。"
D.Strings[37202]="战斗将在30秒内开始。做好准备！"
D.Strings[37203]="这片土地的英灵不会再容忍这种黑暗魔法和邪恶的献祭。$B$B邪枝巨魔必须被赶走！"
D.Strings[37204]="你的脑袋倒是能做成个好袋子！"
D.Strings[37205]="让我们结束这一切吧。我现在只想回到鹰巢山的家里去，而不是盯着这些丑陋的巨魔。"
D.Strings[37206]="$r，你以为这些长胳膊能让你占据优势？再想想吧！"
D.Strings[37207]="别惹昂格隆格！"
D.Strings[37208]="不要浪费时间了！这里还有许多亡灵呢。"
D.Strings[37209]="稳住，不要鲁莽。"
D.Strings[37210]="赞吉尔受够了！现在该休息……"
D.Strings[37211]="赞吉尔回来了！"
D.Strings[37212]="如果我能从这里出去，我一定会在你的脑袋上拉泡屎。你这个该死的兽人。"
D.Strings[37213]="我的人都在哪里？？！"
D.Strings[37214]="你以为这些东西能困住我？哈！"
D.Strings[37215]="高阶祭司耶克里克就要痊愈了！"
D.Strings[37216]="最受敬爱的酋长——"
D.Strings[37217]="酋长，你误会了。不管能否得到你的帮助，加尔鲁什·地狱咆哮都将在这片海岸上抢滩登陆。我们的要求是——"
D.Strings[37218]="你在这儿干什么？不要紧，在你找到机会插手之前，我要复活耶克里克！"
D.Strings[37219]="可部落已经集结了一支所向披靡的大军！这支规模庞大的舰队满载着精锐老兵和战争机器。地狱咆哮会把你碾碎，只要——"
D.Strings[37220]="呃哦……金度一定不会喜欢这个……"
D.Strings[37221]="该离开这儿了！"
D.Strings[37222]="别废话了，虫子。要是你真想得到龙喉的帮助，你应该卑躬屈膝地来，还要带上足够多的金子。"
D.Strings[37223]="这算是威胁吗？我在外域见过地狱咆哮。不过是个只会哀鸣的小崽子罢了。他算什么酋长。"
D.Strings[37224]="把他带上来！"
D.Strings[37225]="龙喉！！"
D.Strings[37226]="别让那$c死了。$g他:她;将是我们谈判的筹码。"
D.Strings[37227]="叫其它人来。我们将粉碎地狱咆哮的部落军团，把他们的尸体丢进海里喂鱼……"
D.Strings[37228]="保持炸弹的温度，这显而易见。我看上去像是在做什么？"
D.Strings[37229]="你光坐在那儿是要干什么？！"
D.Strings[37230]="高阶祭司温诺希斯快要痊愈了！"
D.Strings[37231]="带我到羽月废墟的战场上去。"
D.Strings[37232]="你是否愿意不惜一切代价来挽救你的王国？"
D.Strings[37233]="我必须返回羽月要塞！"
D.Strings[37234]="你又回来了，哈？真是太糟了，因为我这次混合制出了更为强大的药剂！温诺希斯将复活！"
D.Strings[37235]="我已经受够了……"
D.Strings[37236]="赞吉尔来了！"
D.Strings[37237]="啊哈哈哈！这次的赢家是赞吉尔！而且快看看是谁来庆祝！"
D.Strings[37238]="不！赞吉尔失败了……"
D.Strings[37239]="城市中的克瓦迪尔已经被清除了。现在我们可以开始仪式的准备了。"
D.Strings[37240]="女武士，我有一个任务需要你去完成。"
D.Strings[37241]="女武士！立即赶赴战场。克瓦迪尔已经突破了我们的战线！"
D.Strings[37242]="坚持住！召唤仪式就要完成了。"
D.Strings[37243]="消灭他们，女武士！"
D.Strings[37244]="挡住他们！绝不能让他们靠近神殿！"
D.Strings[37245]="消灭他们，绝不怜悯，兄弟们！"
D.Strings[37246]="你们只能在死亡后获得和平，克瓦迪尔！"
D.Strings[37247]="你们在迈向死亡！艾萨拉会将你们彻底驱逐出海洋！"
D.Strings[37248]="你们这是……急着寻死，蠢货。"
D.Strings[37249]="蠢货！懦夫！"
D.Strings[37250]="你应该接受你的失败。"
D.Strings[37251]="回来了，就只有死路一条。"
D.Strings[37252]="等待你的只有奴役和死亡。"
D.Strings[37253]="克瓦迪尔人正从桥上涌过来！女武士，纳兹夏尔女士在召唤你！"
D.Strings[37254]="回到沙子里去吧，渣滓！"
D.Strings[37255]="真不错，他们一个接一个的进来。"
D.Strings[37256]="就像海草一样难以剿除。"
D.Strings[37257]="他们也许真的喜欢这座城市。因为这儿风景不错？"
D.Strings[37258]="古拉巴什连同哈卡一起都完蛋了。大多数追随我的赞达拉巨魔都回到了他们的家园。$b$b现在，看护祖尔格拉布的任务落在了我、梅维克和邦巴拉暗矛巨魔的肩上。"
D.Strings[37259]="查巴尔，我光顾着追踪赞吉尔，忘了自己该干的事儿了。你能提醒我接下来要去哪儿吗？"
D.Strings[37260]="女武士，克瓦迪尔要将这座城市从我们手中夺回去。外边的人需要你的帮助。"
D.Strings[37261]="妖术师金度！我已经好久没见过那面具了。"
D.Strings[37262]="是什么风把你吹到我这儿来了？我还不习惯接待来自神圣祖尔格拉布的访客。"
D.Strings[37263]="你对我来此的原因了解得一清二楚，赞吉尔。"
D.Strings[37264]="古拉巴什遭遇了危难。我活了下来，曼多基尔也回来了……可我们却失去了剩下的所有人。"
D.Strings[37265]="真是遗憾……可对于像赞吉尔这样的老牌流亡者来说算不了什么。"
D.Strings[37266]="嗯，赞吉尔，我有个能让你在意的理由。我找到了高阶祭司耶克里克和温诺希斯的遗体。"
D.Strings[37267]="我还记得你能让那些合剂发挥出什么样的效力。你愿意用你的合剂帮帮老朋友吗？"
D.Strings[37268]="老朋友？你可是那群落井下石的人之一啊，金度。但是过去的就让它过去吧，你说好吗？"
D.Strings[37269]="这么说，你的蝙蝠和蛇群需要赞吉尔的帮助？非常好。那我们在祖尔格拉布里面见吧……老朋友。"
D.Strings[37270]="克瓦迪尔永生……这座城是我们的……"
D.Strings[37271]="我们知道的只是皮毛而已，$n。我可以向你担保。"
D.Strings[37272]="我以为我们把所有人都杀了……莫诺洛克一定会很开心的！"
D.Strings[37273]="你的种族就是海洋的疾病。"
D.Strings[37274]="耐普图隆将会崛起，将你们从艾泽拉斯清除掉。"
D.Strings[37275]="窒息于克瓦迪尔之沙！"
D.Strings[37276]="你们该把这座城市还给波涛。"
D.Strings[37277]="这儿发生什么事了？"
D.Strings[37278]="赞吉尔！解决温诺希斯，然后我们再来讨论下你的失败。"
D.Strings[37279]="是，金度。"
D.Strings[37280]="还有你。你这是最后一次破坏我的计划。"
D.Strings[37281]="哈卡变得越来越不耐烦了。我也一样。"
D.Strings[37282]="你也许杀死了耶克里克，可你别想活着离开祖尔格拉布。"
D.Strings[37283]="而且要是你往右侧转一转头，你会看见……我的朋友，就要被杀死了！"
D.Strings[37284]="快！抓住梯子！"
D.Strings[37285]="慢慢接近她，二号。"
D.Strings[37286]="开火！开火！把它轰出水面！"
D.Strings[37287]="稳住，二号……"
D.Strings[37288]="以加里维克斯的黑心肠起誓，那怪兽逃得真快！"
D.Strings[37289]="怪兽逃跑了！以梅卡托克的胡子起誓，它可真快！"
D.Strings[37290]="等我离开这儿，你们这群兽人就要倒霉了。"
D.Strings[37291]="偿还总是痛苦的。"
D.Strings[37292]="赞吉尔传送到了别处！"
D.Strings[37293]="欢迎来到硬钳避世乐园！$b$b希望远离纷繁嘈杂的城市生活？那你可来对地方了！$b$b想要亲眼见证艾泽拉斯知名丛林的奇迹胜景？不用去别处了！$b$b想要购买新鲜出炉的生物燃料或武器级矿物？这里一定能满足你的需要，$c！"
D.Strings[37294]="嘿，老大。"
D.Strings[37295]="您想来点儿什么？要不要尝尝我们的招牌菜芝士焗龙虾？"
D.Strings[37296]="谢谢你，$r。"
D.Strings[37297]="我想我能自己回去了。"
D.Strings[37298]="你是个长相奇特的家伙。谢谢你。"
D.Strings[37299]="帮我干掉几个，可以吗？"
D.Strings[37300]="别担心我。我们快去救国王！"
D.Strings[37301]="我们不能不管这些难民，克朗恩。布伊恩已经把他的武器和护甲换成了救助难民的食物。他一个人的力量是不够的。"
D.Strings[37302]="你要干掉颤地者特罗格佐尔！"
D.Strings[37303]="我得赶回去汇报了。谢谢你，$c！"
D.Strings[37304]="我不是对他们的痛苦视而不见，罗旺，可我们来此的任务是了解大灾变所带来的灾难。艾泽拉斯世界正在受苦。"
D.Strings[37305]="我已经派人前往圣光之愿礼拜堂来筹措照料难民所需要的资金。执行你的任务，但也请尽全力帮助我们。"
D.Strings[37306]="谢谢你，伽文神父。在这黑暗的时刻，这个世界需要更多像你和布伊恩这样的人。"
D.Strings[37307]="这么多无谓的损失。"
D.Strings[37308]="钓鱼是我家族世代相传的天性。不过你看上去倒像是能帮点儿小忙。替钓鱼者跑跑腿儿怎么样？"
D.Strings[37309]="含羞而败吧你这恶心的杂种！"
D.Strings[37310]="去和你的造物主团聚吧！"
D.Strings[37311]="一无是处的废物！"
D.Strings[37312]="想打架，你可找错人了！"
D.Strings[37313]="不用找零了，你这恶心的生物！"
D.Strings[37314]="我刚才只是在热身！"
D.Strings[37315]="我都还没穿装备！"
D.Strings[37316]="对，就像那样，你死定了！"
D.Strings[37317]="我见过比你更强硬的废物。"
D.Strings[37318]="欢迎来到地狱！"
D.Strings[37319]="脚趾向上……"
D.Strings[37320]="你听到那声音了吗？！"
D.Strings[37321]="复仇这道菜，配上“屁股开花”这小吃就完美了！"
D.Strings[37322]="你一杯！我一杯！愿我们默契永相随。$b$b可要是没了默契……那你就去死吧！我再来一杯。"
D.Strings[37323]="我听说你这儿有喝的东西卖，斯利姆。"
D.Strings[37324]="%s打了个响嗝儿。"
D.Strings[37325]="这艘救生船像是被丢弃了。也许它的主人会是附近的海盗？"
D.Strings[37326]="这一定就是海克拜瑞·斯莫特船长提到的那艘救生船。"
D.Strings[37327]="你用片刻时间默默怀念用这艘救生船击败奈古拉什的事。那可真是段美好的日子。"
D.Strings[37328]="<把食物和饮料放进救生船里。>"
D.Strings[37329]="你知道，我一直不明白为什么他们要叫自己兽人。"
D.Strings[37330]="这是个非常不雅的词汇，你知道吗？我常把这个词和上大号联系在一起。比如说："
D.Strings[37331]="在享用完感恩节大餐后，我美美地拉了坨又大又臭的大便。"
D.Strings[37332]="我们来这儿是想要帮忙的，可看来他们对你的好感还没有延及我们。"
D.Strings[37333]="我真的很想念你，丹弗斯。"
D.Strings[37334]="我记得有一次，基沙恩和我到湖畔镇的桥上钓鱼，然后基沙恩突然放了个屁。我想奥斯洛在那件事情上永远都不会原谅基沙恩……"
D.Strings[37335]="你知道，黑石兽人夺走了基沙恩的妻子。在那件事情发生后他就像变了个人似的。仿佛他生命中的太阳瞬间陨落。只剩下黑暗，$g老兄:女士;。纯粹的黑暗。"
D.Strings[37336]="他们把我们叫做B连。当有杀戮任务时，我们负责让血……流成河。"
D.Strings[37337]="梅森纳是火焰法术的大师。我们每次烧烤都会邀请他来助阵。"
D.Strings[37338]="顺便说一句，约根森是位真正的雅士。他是位圣骑士，所以在他身边说话时要小心点儿，否则你很可能会令他抓狂。"
D.Strings[37339]="我听说瓦里安·乌瑞恩回来了。是真的吗？不好意思，我有点儿闭塞了。"
D.Strings[37340]="你有没有注意到赤脊山那儿的人有多尖刻？有时我真觉得我要一把火烧了所罗门那蠢货的城镇大厅。"
D.Strings[37341]="赶快，格索乌。解开$g他的:她的;镣铐。"
D.Strings[37342]="$n，我已为你找回了装备。我想你已经看到你所需要看到的一切。"
D.Strings[37343]="我感到很虚弱。我是说比平时还要虚弱。这星期的圣光像是又无力了许多。也许和我吃的东西有关。兽人的食物让我觉得恶心。"
D.Strings[37344]="你见过基沙恩消灭兽人的情景吗？那可真是壮观啊，$g老兄:女士;。"
D.Strings[37345]="记住，$n。并非所有的龙喉成员都是你的敌人！"
D.Strings[37346]="真是难以置信，我们居然又把过去的队伍集结在一起了。这都要感谢你，$n。"
D.Strings[37347]="我听说萨尔离开了部落。是真的吗？"
D.Strings[37348]="你知道，我一直听那些黑石兽人说，关于地狱咆哮返回部落的事。那究竟是怎么回事？地狱咆哮不是死了吗？"
D.Strings[37349]="我可能是这队伍中最重要的成员了——我的圣骑士和所有其它身份。"
D.Strings[37350]="等这些兽人注意到我们。B连重操旧业！"
D.Strings[37351]="我在小队中，并已准备好传送到潮汐王座！"
D.Strings[37352]="那么暴风城里那个小可爱怎么样了？她叫女伯爵普瑞斯托。"
D.Strings[37353]="真奇怪。我的屁股好疼。疼得莫名其妙。"
D.Strings[37354]="现在可以参与潮汐王座的初始测试了，这是位于瓦丝琪尔的一座79-81级地下城。这座地下城目前仍处于开发过程中，与最终首领的战斗尚无法进行。请在传送至地下城之前组满队伍。集合石目前对该地下城不可用。\n\n若要离开潮汐王座，只需从位于地下城内的普通出口离开即可，你将被自动传送至达拉然。如果你在战斗中死亡并释放灵魂，你则需要通过该NPC传送回地下城。"
D.Strings[37355]="基沙恩是个好人，$n。我们所有人都甘愿为他卖命。"
D.Strings[37356]="等这一切都尘埃落定之后，我要度假休息段日子。"
D.Strings[37357]="送我回到潮汐王座！"
D.Strings[37358]="我们的命都属于基沙恩。他已经救过我们无数次了。"
D.Strings[37359]="当法师有当法师的好处，可那高昂的洗衣账单可真让人头痛。"
D.Strings[37360]="那湖畔镇的那座桥后来怎么样了？奥斯洛把它造完了吗？"
D.Strings[37361]="等这一切都结束后，我也许会去达拉然。帮他们重新把那座城市复建得风生水起。"
D.Strings[37362]="我需要用下洗手间。"
D.Strings[37363]="一旦B连重新回来投入工作，这些兽人必会猛然觉醒。"
D.Strings[37364]="世界闻名的诺格弗格药剂此处有售！$B$B由纯天然材料萃取炼制而成，只在加基森当地装瓶销售！而且口感顶呱呱——这是当然的！"
D.Strings[37365]="我要诺格弗格！"
D.Strings[37366]="啊，马洛拉克。你可算从那间被你叫做实验室的隔离屋走出来了，你这次有什么成果？"
D.Strings[37367]="当然可以，我洗耳恭听。"
D.Strings[37368]="看来你的实验失败了。那小龙已经完全瞎了！你看看他。"
D.Strings[37369]="看看他！"
D.Strings[37370]="不，还没有。"
D.Strings[37371]="你这失败的作品也许……对我……还有点儿价值。"
D.Strings[37372]="走吧，可悲的炼金师。我急切地期待着你的下一次失败。"
D.Strings[37373]="打扰了您，我深表歉意，我的主人。但我相信，我这儿有您非常感兴趣的东西！"
D.Strings[37374]="我从各种巨龙军团成员的血液里精炼出萃取物，制成药膏，可以使涂抹者获得视野之外的视野！"
D.Strings[37375]="我授予你实验代号——25463-D！"
D.Strings[37376]="这怎么可能？！我马上解决他！"
D.Strings[37377]="我乞求你的仁慈，大人。"
D.Strings[37378]="我不能和你做交易，$c。这是酋长的命令。"
D.Strings[37379]="我这儿没什么东西可以卖给你。"
D.Strings[37380]="走开，$c！我可不想让执行者看见我在和你做交易……"
D.Strings[37381]="滚开，我不想让酋长发现我在跟部落的人说话。"
D.Strings[37382]="我不会把商品卖给部落。你不满意？那去找酋长吧！"
D.Strings[37383]="莫格霍尔酋长不许我们和部落做生意。$B$B<商人暴怒地朝地上吐了口口水，拒绝再对这话题有任何回应。>"
D.Strings[37384]="我感觉不太好……"
D.Strings[37385]="我帮不了你的忙，$c。要是我敢把我们的双足飞龙借给部落使用，莫格霍尔酋长会把我处死的。$B$B总有一天他会得到他应得的……"
D.Strings[37386]="超越一切凡人的感知力！"
D.Strings[37387]="看来我们还有场胜仗要打。"
D.Strings[37388]="痛苦号列车来了！"
D.Strings[37389]="强尼回来了，宝贝儿！耶！"
D.Strings[37390]="呃……你刚提到了什么私人奥术助手？"
D.Strings[37391]="懦夫！面对龙巢之母或是万劫不复！"
D.Strings[37392]="空气中激荡的电流噼啪作响！"
D.Strings[37393]="真人观察者是无可取代的，但我现在需要那些巡山人来帮忙。我们只能暂时依靠那些小个子的侏儒观察机器人了……"
D.Strings[37394]="这地方还不赖，前提是你不过分专注于那“阳光”。"
D.Strings[37395]="送我们出去，梅森纳。"
D.Strings[37396]="没问题，强尼！"
D.Strings[37397]="我们在这儿，所有人都出去！"
D.Strings[37398]="请原谅，我得继续工作了。"
D.Strings[37399]="琼兹，我是来讨债的。给钱吧。"
D.Strings[37400]="猩猩可真是令人着迷的生物。比暗夜精灵要好多了，那些家伙就只会干蠢事……比如在赌场上输个精光，还害自己登上“海狼”马克基雷的黑名单。"
D.Strings[37401]="那你知道我来这里的原因了。好吧小腹，给钱吧。"
D.Strings[37402]="你是怎么找到我的？！"
D.Strings[37403]="我身无分文！走开！"
D.Strings[37404]="继续，$r。给我个理由。"
D.Strings[37405]="这儿可是莫格霍尔酋长说了算。别忘了这一点。"
D.Strings[37406]="<执行者的眼中闪着红光。>$B$B我倒希望你们这些可怜的兽人来攻击我们。我很久没畅快地挥洒热血了，$c！"
D.Strings[37407]="那愤怒！那力量！我一生中从未感到如此强壮。$B$B很快，整个龙喉部族都将有同样的感觉。"
D.Strings[37408]="不要自取其辱，$c。$B$B<执行者握住剑柄的手指又紧了紧，就等你先动手了。>"
D.Strings[37409]="莫格霍尔酋长将率领龙喉部族再次崛起！$B$B我们用不着你们这群没用的部落。"
D.Strings[37410]="我们现在要怎么做？酋长肯定想让我们用武力席卷港口！"
D.Strings[37411]="也许吧。也许我们能取胜，但代价会有多大？说不定$n有更好的主意……"
D.Strings[37412]="重击！"
D.Strings[37413]="摧毁！"
D.Strings[37414]="好吧，让我们试着把这东西砸开！"
D.Strings[37415]="大家准备好！猩猩们来了！"
D.Strings[37416]="艾卓曼德斯！主人在召唤你。"
D.Strings[37417]="见证无尽力量的光辉吧！"
D.Strings[37418]="观众的兴奋，战斗的刺激——你真该亲眼看看！自从厄运之槌竞技场被那群食人魔占领之后，我就被迫在这儿扎营。目击者格林比克斯——哈！目击什么？目击营火？还是那丛灌木？或者是这棵怪里怪气的紫树？\n\n听着，要是你想打上一架的话，斯卡尔正在前往拉瑞斯小亭，拉扎尔正在朝新萨兰纳尔飞去。在血战开始前，别忘了通知我下注！"
D.Strings[37419]="不，不！离戈洛普远点儿！我的蘑菇！我的！"
D.Strings[37420]="蘑菇大又壮。没人能踩扁大蘑菇！可是它能踩扁别人！"
D.Strings[37421]="为什么你一定要来我的洞？我的洞！我可从没弄坏过你的洞！"
D.Strings[37422]="后退！后退！"
D.Strings[37423]="真是有趣啊，丹弗斯。"
D.Strings[37424]="这个石头穴居人与赤红岩床的变数有关。$B$B我在这里感觉到一股奇怪的力量……多加小心。"
D.Strings[37425]="我已经准备好，就等你了，诺莎拉。"
D.Strings[37426]="呀，你有什么本事？穿着花哨的$c长裤，长着一张$g海巨人:鹰身人;的脸，就是个只会舔舱底的$r罢了。我宁可去啃尼哈鲁的靴子，也不愿意带像你这样的菜鸟去对付血帆海盗。$b$b等你经历丰富些再回来找我吧。"
D.Strings[37427]="呀，有叛徒！还长得那么丑！快滚出我的办公室，别等我一拳把你打到海盗老巢！"
D.Strings[37428]="<小母牛正在努力思索该怎么下楼。>"
D.Strings[37429]="<小母牛用大大的、澄澈的黑眼睛望着你。>"
D.Strings[37430]="<小母牛优雅地低下了头，仿佛理解你请求中所包含的重要性与意义。>"
D.Strings[37431]="小母牛，我需要你帮我一个大忙。我要把你的头切下来，证明自己对血帆海盗的忠诚，从而混入他们的内部，希望能藉此发现他们的真实意图。\n\n藏宝海湾需要你，小母牛……比以往任何时候都更需要你。"
D.Strings[37432]="哞。"
D.Strings[37433]="<行动。>"
D.Strings[37434]="<退缩。>"
D.Strings[37435]="%s长长地舒了一口气。"
D.Strings[37436]="想要购买什么海盗物品吗？"
D.Strings[37437]="我需要一顶超大海盗帽。是海角的命令。"
D.Strings[37438]="告诉他这是最后一顶了。在漂亮的帽子上戳洞，这可让可怜的纳尔克伤透了心！"
D.Strings[37439]="你找来了什么？"
D.Strings[37440]="可恶的……石头魔鬼……"
D.Strings[37441]="我们快点做个了断。"
D.Strings[37442]="你造成的伤害够多了，戈洛普。大地不再欢迎你了。"
D.Strings[37443]="追上他，快点！"
D.Strings[37444]="狡猾的石头穴居人。"
D.Strings[37445]="开玩笑吧……"
D.Strings[37446]="嘿财主，再来点儿！"
D.Strings[37447]="欢迎来到藏宝海湾，$r。"
D.Strings[37448]="行了。"
D.Strings[37449]="这是头颅和帽子，舰队指挥官。"
D.Strings[37450]="你说了算。"
D.Strings[37451]="看起来不错，但是我认为要是能把它弄皱些就更好了。你知道，要给人一种经历过战斗的感觉。你说呢？"
D.Strings[37452]="丹弗斯，报告。"
D.Strings[37453]="黑石兽人炸毁了通往石堡要塞的桥梁。正面交战是不可能了。"
D.Strings[37454]="卡拉克尔？"
D.Strings[37455]="有两种方式可以深入敌后，约翰尼。如果算上死的话，总共有三种。"
D.Strings[37456]="向北穿过奥瑟尔伐木场，但我们得遭遇嗜血的座狼大军，或是向南穿过撕裂者山谷。"
D.Strings[37457]="约根森，你对撕裂者山谷有把握吗？"
D.Strings[37458]="那鬼地方到处都是黑石兽人，约翰尼。在必经之路上有一座主塔，还有两间稍小一些的木屋。那可是死亡陷阱。"
D.Strings[37459]="死亡陷阱，嗯？梅森纳，我有计划了。得用到些爆盐。"
D.Strings[37460]="爆盐？我要上哪儿去找那鬼东西，约翰尼？"
D.Strings[37461]="这就不是我要考虑的问题了，梅森纳。总之要找到。"
D.Strings[37462]="$n，把你的东西收拾好。我要派你上战场了。"
D.Strings[37463]="别让污点存在太久！"
D.Strings[37464]="污点会毁了甲板！"
D.Strings[37465]="你在甲板上发现了一个污点！"
D.Strings[37466]="又出现了两个污点！继续清洁！"
D.Strings[37467]="污点出现得越来越快了！"
D.Strings[37468]="甲板被毁了。再拿把拖把重新尝试吧。"
D.Strings[37469]="我的兄弟们很强壮，但却总是非常被动。$B$B没有运动、没有竞争、没有暴力，就不会产生变化。我们的敌人深谙此道，不管他们是不是完全意识到了这一点。我兄弟们被动的天性使他们在这些新的敌人面前显得脆弱而无力。$B$B别把我算在内。我不惧怕改变。我愿意撕裂大地，挪移群山。我热爱改变。"
D.Strings[37470]="你已经拿到了拖把，现在赶快去清除污点！"
D.Strings[37471]="我留下来确认他们剩下的实体也被消灭了。"
D.Strings[37472]="跟着无家可归者前往死亡矿井地下城的入口。"
D.Strings[37473]="稳住！纳迦进攻了！"
D.Strings[37474]="大家抓紧！萨满，赶快行动！"
D.Strings[37475]="潜艇快爆炸了！我们必须离开，快！"
D.Strings[37476]="更多的纳迦…做好准备！"
D.Strings[37477]="以萨尔之名，和纳迦战斗令我作呕！"
D.Strings[37478]="这我可不喜欢……"
D.Strings[37479]="这儿有人吗？"
D.Strings[37480]="我闻到一股……臭味。"
D.Strings[37481]="我留在这儿。你去查查是怎么回事！"
D.Strings[37482]="%s施放了侦测潜行。保持距离！"
D.Strings[37483]="有贼！！"
D.Strings[37484]="呀！那些酸橙是我光明正大得来的！"
D.Strings[37485]="啊！给我回来，你这喝泔水的小崽子！"
D.Strings[37486]="我正想给我的伙伴们做点儿酸橙汽水！我发誓！"
D.Strings[37487]="死人别想偷酸橙！"
D.Strings[37488]="再练练偷酸橙的本事吧，你这下流的无赖！"
D.Strings[37489]="不，别碰我的酸橙，听见没有！"
D.Strings[37490]="随着奥妮克希亚体内电荷的增加，在她身体四周开始出现能量电弧。"
D.Strings[37491]="随着奥妮克希亚体内的电荷积聚到危险程度，电弧也在不断加强！"
D.Strings[37492]="微小的闪电灼烧着奥妮克希亚的皮肤。她体内的电荷已积聚到濒临迸发的阶段！"
D.Strings[37493]="我应该返回红雾号了。到那儿再见。"
D.Strings[37494]="让我们把这些忍者干掉，老大。我已经在前方看见一些了。"
D.Strings[37495]="我们自由了！逃命去吧！"
D.Strings[37496]="我们捅了马蜂窝了，$n！$B$B希望你已经有了应对的计划。克罗格的战士们正在铲除龙喉，可我们每前进一寸都在遭受惨重的损失……"
D.Strings[37497]="我终有一天会死，女海巫……"
D.Strings[37498]="……但绝不是今天！"
D.Strings[37499]="靠紧点！我们的人已经很少了。"
D.Strings[37500]="你差点就走散了！不要掉队！"
D.Strings[37501]="跟着我！在这儿掉队就死定了！"
D.Strings[37502]="你的干涉会让你付出生命的代价，$r！"
D.Strings[37503]="你已成功将爆盐炸弹安放在军需营帐处。"
D.Strings[37504]="你已成功将爆盐炸弹安放在黑石塔楼处。"
D.Strings[37505]="这与你无关，$r！"
D.Strings[37506]="软皮人，你会成为那只野兽的可口点心！"
D.Strings[37507]="我已准备好将一队元素护送过开阔地。"
D.Strings[37508]="迅速些，$c。石龙不会这么轻易的屈服。"
D.Strings[37509]="现在激活你的B连战地工具。|TInterface\\Icons\\INV_MISC_ENGGIZMOS_20.BLP:16|t$B用伪装使你的小队成员隐形。|TInterface\\Icons\\SPELL_NATURE_PROTECTIONFORMNATURE.BLP:16|t"
D.Strings[37510]="我们已接近撕裂者山谷。这些兽人很难对付！一定要将自己伪装好！|TInterface\\Icons\\SPELL_NATURE_PROTECTIONFORMNATURE.BLP:16|t"
D.Strings[37511]="分散敌人的注意力，以便使约根森和你能悄悄过去。|TInterface\\Icons\\ABILITY_ROGUE_BLOODYEYE.BLP:16|t"
D.Strings[37512]="!有时你只需要解决一个目标。在敌人背后使用麻醉！|TInterface\\Icons\\SPELL_NATURE_SLEEP.BLP:16|t"
D.Strings[37513]="你是来帮龙喉重获自由吗？$B$B去和扎伊拉谈谈——她在协调我们的反抗行动！"
D.Strings[37514]="放弃港口？莫格霍尔把你的理智都打没了吗？这次攻击是我们夺回命运掌控权的最好机会——等等！让我们先见见来自部落的$n！"
D.Strings[37515]="我的治疗确实不具备原先那样的“吸引力”，$n。你明白我在说什么吗？"
D.Strings[37516]="作为圣骑士可真不是件容易的事情。圣光是如此难以驾驭。有些天当我醒来时，感觉就像我所有的能量都被弱化了。"
D.Strings[37517]="呀，抓紧了，朋友，再没有比我更好的划手了！"
D.Strings[37518]="我不知道，也许对岸的草真的更绿些？你明白吗？卡拉克尔和丹弗斯真是一流的战士。也许我也该放弃这圣骑士的身份，考虑转行做战士。"
D.Strings[37519]="我们要扬帆前往那群地精声称发现黑金子的地方。那些金子属于血帆海盗！"
D.Strings[37520]="梅森纳能如此迅速地干掉坏人。我真希望自己杀敌的速度能和他媲美。为什么我不能发出火球？圣光与火球相比优势在哪里？"
D.Strings[37521]="我驾驶，你来操控老滑膛。别把你的衣服打成结……等我们接近时我会减速的！"
D.Strings[37522]="到了！任意开火！"
D.Strings[37523]="准备……开火！"
D.Strings[37524]="两翼都是敌人！送他们去见耐普图隆！"
D.Strings[37525]="有一次，基沙恩告诉我，他能同时把五个我打倒。我为什么这么弱？"
D.Strings[37526]="那金子是我们的！开火，这是命令！"
D.Strings[37527]="随时确认我们是否处于伪装状态。要是被撕裂者山谷的兽人发现，我们两个就都没命了。"
D.Strings[37528]="撤退，照我说的做！"
D.Strings[37529]="下次再打！"
D.Strings[37530]="暂停攻击！我们撤！"
D.Strings[37531]="在伪装状态下，当我们处于敌人身后时更难被发现。"
D.Strings[37532]="喂！我在那边看见更多地精！"
D.Strings[37533]="有时分散注意力的行为会引发反效果，让兽人们变得多疑。在那种情况下，兽人们会主动寻找我们。最好离那些具备侦测隐形能力的兽人远一点儿。"
D.Strings[37534]="遵命，长官。正在逆行返回海岸。"
D.Strings[37535]="有时我们会遇见落单的兽人，这时胜利距我们只有一步之遥。在这种情况下通常会用到麻醉。需要记住的是，若要使用麻醉，我们必须位于敌人身后。"
D.Strings[37536]="啊，你需要什么？"
D.Strings[37537]="嗨朋友！升锚整帆，放下舱口盖准备出海！今天我们要毁掉风险投资公司那些该死的装置，把它们统统丢进海里喂鱼！赶紧行动，别让我对你动手！"
D.Strings[37538]="我……我需要一艘船。"
D.Strings[37539]="|cFF768EBD我已经准备好爆盐炸弹。我们要前往军需营帐和塔楼处。|r|TInterface\\Icons\\INV_MISC_BOMB_04.BLP:24|t"
D.Strings[37540]="查看中"
D.Strings[37541]="一桶烈酒。正对海盗的胃口。"
D.Strings[37542]="一桶烈酒。正对海盗的胃口。$b$b桶口的软木塞好像塞得不太紧。"
D.Strings[37543]="<轻推木塞。>"
D.Strings[37544]="酒从桶里漏了出来。这将会激怒很多海盗。"
D.Strings[37545]="一桶火药粉。爆破性极强。"
D.Strings[37546]="一桶火药粉。旁边还放着一大罐水。"
D.Strings[37547]="<把水倒在火药上。>"
D.Strings[37548]="火药粉完全被浸湿了。短时间内不会再有人用这火药粉发射炮弹了。"
D.Strings[37549]="一个巨大的箱子，里面装满了炮弹。"
D.Strings[37550]="一个巨大的箱子，里面装满了炮弹。旁边还放着一罐看似毫不相干的烹饪用油。"
D.Strings[37551]="<用油涂抹炮弹。>"
D.Strings[37552]="你在这些重型金属炮弹表面涂满了油。菲尔拉伦的手下肯定很难把它们装填上去。"
D.Strings[37553]="确保椽子的安全！"
D.Strings[37554]="让两个狙击手待在后面，掩护甲板。其他人，顺着绳子下去。让他们下地狱去吧！"
D.Strings[37555]="我们在锅炉室里放了炸弹，现在先挡下他们！"
D.Strings[37556]="停！"
D.Strings[37557]="来打我呀！"
D.Strings[37558]="给我让开！"
D.Strings[37559]="你这条不听话的狗！不自量力！"
D.Strings[37560]="我才不会抛弃同伴，你这条只会摇尾乞怜的狗！"
D.Strings[37561]="管好你自己吧，你这专爱鹰身人的无赖！"
D.Strings[37562]="我才不会倒戈，你这长着绿鳃的鱼人！"
D.Strings[37563]="反叛？我让你看看什么叫反叛，你这弱不禁风的醉鬼！"
D.Strings[37564]="让我来送你一程，你这只配跟炮弹接吻的大饼脸！"
D.Strings[37565]="我要送你去见耐普图隆，你这条笨重的大河豚！"
D.Strings[37566]="我要拿你去喂鱼，你这下三滥的穴居人！"
D.Strings[37567]="我要把你的天灵盖刺穿，你这条没种的鳗鱼！"
D.Strings[37568]="龙喉必胜！"
D.Strings[37569]="只是几张没用的书写稿。"
D.Strings[37570]="在这些计划书里列出了即将发起进攻的细节！"
D.Strings[37571]="皮克，我准备好护送投石车了。"
D.Strings[37572]="今天是审判日，$c！"
D.Strings[37573]="你是来帮忙对付莫格霍尔的吗？"
D.Strings[37574]="扎伊拉说部落需要援助！我能做些什么？"
D.Strings[37575]="不用给我盔甲。一把刀就够了，告诉我要杀谁。"
D.Strings[37576]="部落来了！是时候发挥领袖的作用了！"
D.Strings[37577]="我会与你并肩作战，$c。你不会后悔帮助我们的！"
D.Strings[37578]="与我一同战斗！拿起这把刀，像战士一样厮杀！"
D.Strings[37579]="看来今天不是个戒杀兽人的好日子。"
D.Strings[37580]="算我一个，教官！我做好战斗的准备了！"
D.Strings[37581]="今天莫格霍尔的暴行即将终结。"
D.Strings[37582]="没错，$c！革命开始了！"
D.Strings[37583]="$c！扎伊拉说部落为我们准备了武器。有些什么呢？"
D.Strings[37584]="长牙约翰·库珀，“急浪船帮”做好战斗准备了吗？"
D.Strings[37585]="是的，$g 阁下: 女士;！我们已经在吉尔尼斯蓄势已久。我们渴望鲜血！"
D.Strings[37586]="关于“急浪船帮”，你能告诉我什么？"
D.Strings[37587]="我们曾在海上自由驰骋……直到该死的格雷迈恩国王把吉尔尼斯海港给封了！要不是因为他，我们就不会……"
D.Strings[37588]="你知道作战计划，对吧？"
D.Strings[37589]="是，$g阁下:女士;。我们根据您的信号指示从北面发起攻击。 “急浪船帮”将荡涤藏宝海湾！喔啰！！！"
D.Strings[37590]="快来帮助和治疗我！拿起这把战锤，有点萨满祭司的样子。"
D.Strings[37591]="我的另一半走丢了！快帮帮我！"
D.Strings[37592]="镇民正在不断消失，所罗门。你打算怎么办？"
D.Strings[37593]="该醒醒了，长官！这次不是普通的豺狼人攻击！"
D.Strings[37594]="我们从暴风城请来的援兵呢？"
D.Strings[37595]="要是你的卫兵连豺狼人都阻挡不了，那我们为什么要交税给你？"
D.Strings[37596]="我的孩子在睡梦中被劫走了！我想要知道真相，所罗门！"
D.Strings[37597]="你最好赶紧采取行动，不然暴乱是难免的了，所罗门！"
D.Strings[37598]="豺狼人从没这么放肆过。到底怎么了，所罗门？快告诉我们！"
D.Strings[37599]="我们得在这儿站多久，才会有人听到我们的恳求？"
D.Strings[37600]="快让这该死的队伍动起来！"
D.Strings[37601]="你一无是处，所罗门！"
D.Strings[37602]="你别想连任了，地方官！"
D.Strings[37603]="没有正义，没有和平！"
D.Strings[37604]="要是你不对这些豺狼人采取行动，我们要动手了！"
D.Strings[37605]="快帮帮我！我全家只剩我一个了。其它人都被劫走了！"
D.Strings[37606]="不指望你了，所罗门。我会自己找到我的家人。"
D.Strings[37607]="这场可悲的革命，到此为止了！"
D.Strings[37608]="<大财主里维加兹的私人宝物。任何时候都不要乱动！>"
D.Strings[37609]="问问你自己，$n——这对风险投资公司有利吗？"
D.Strings[37610]="虽然没有恶魔之血，但你却比自己所想的更像你父亲。"
D.Strings[37611]="把这些担忧留给老家伙们。而你还有很多东西要学。去帮助暗矛的族人吧。相信我们很快就会再见面的。"
D.Strings[37612]="我做出这个决定并不轻松。我知道，我们的盟友将因此承受磨难。部落将发生无可挽回的改变。但我相信，加尔鲁什正是部落现在所需要的人。"
D.Strings[37613]="我相信你和其他领袖不会让我们的族人因此而分裂。你们有足够的力量。"
D.Strings[37614]="但，我还是希望萨尔终有一天能够回来。现在我眼中的未来只剩下了暴力和血腥。"
D.Strings[37615]="去吧，让暗矛部族以你为傲。我们前方还有很多战斗。我相信你会和我们一起走到底。"
D.Strings[37616]="救——命！"
D.Strings[37617]="喔上帝，他们来了！啊——！"
D.Strings[37618]="海盗！啊——！"
D.Strings[37619]="强尼，你意识到我们刚才把半个赤脊山给炸毁了，对吧？"
D.Strings[37620]="各位，恐慌时间到了！"
D.Strings[37621]="赤脊山将会得到治愈，可那群兽人当然不会……"
D.Strings[37622]="放下舱口盖，伙计们！"
D.Strings[37623]="把那群胆小的无赖从水里炸出来！"
D.Strings[37624]="“急浪船帮”和血帆海盗死定了！藏宝海湾是黑水强盗的！"
D.Strings[37625]="快把火扑灭！"
D.Strings[37626]="坚守阵地，兄弟们！胜利属于我们！"
D.Strings[37627]="把他们全都干掉，这是命令！"
D.Strings[37628]="菲尔拉伦，出来像个地精一样地战斗吧！"
D.Strings[37629]="你们已经踏上了大财主的地盘，你们这群卑鄙的狼人渣滓！"
D.Strings[37630]="你在这一战中给敌人造成了最多的伤害！"
D.Strings[37631]="你在这一战中为盟友治疗了最多的伤害！"
D.Strings[37632]="你是这一战中杀敌最多的人！"
D.Strings[37633]="看来你们等不及要下地狱了……"
D.Strings[37634]="你们还没意识到自己有多愚蠢，可你们很快就将在黑暗烈焰面前战栗。"
D.Strings[37635]="让我上车。"
D.Strings[37636]="波奇找到一条鱼！"
D.Strings[37637]="游戏结束了，伙计！！！"
D.Strings[37638]="元素要复仇！"
D.Strings[37639]="小的们，快来帮我！"
D.Strings[37640]="留神！大家伙来了！"
D.Strings[37641]="这玩意儿究竟是从哪来的？"
D.Strings[37642]="托德曼。"
D.Strings[37643]="托德曼？"
D.Strings[37644]="为您效劳。"
D.Strings[37645]="小小胖为您服务。请吃好住好。"
D.Strings[37646]="骑上一只角鹰兽，我们的机会来了！"
D.Strings[37647]="我们必须等待出击的最佳时机！"
D.Strings[37648]="我们必须等待时机。他们不会知道是谁袭击了他们。"
D.Strings[37649]="举起手来，绿皮人！乖乖照着指示做。你要是玩什么花样，就让你尝尝子弹的味道。"
D.Strings[37650]="剩下的人，跟我下去！"
D.Strings[37651]="你可真是挑了个有趣的时机来和老科博克聊天啊。"
D.Strings[37652]="对不起，我不是来聊天的。我需要一头双足飞龙来执行特殊任务。"
D.Strings[37653]="[兽人语]Dabu？"
D.Strings[37654]="啊——！！！"
D.Strings[37655]="啊啊啊——！！！"
D.Strings[37656]="啊啊啊啊啊——！！！"
D.Strings[37657]="鲜血与雷鸣，对吧？！"
D.Strings[37658]="我找不到你的腿，乔伊！我找不到你那该死的腿！"
D.Strings[37659]="去见你们的黑暗神灵吧，你们这些龌龊的畜生！"
D.Strings[37660]="没有友好的平民！"
D.Strings[37661]="圣光将教会你什么？"
D.Strings[37662]="太阳的光辉照耀着通往智慧的道路。我们今天要去哪儿，朋友？"
D.Strings[37663]="愿太阳的光辉守护你，$c。"
D.Strings[37664]="现在，摧毁这些可恶的东西……"
D.Strings[37665]="等所有人都准备好，我们就出发。"
D.Strings[37666]="耐心点儿，朋友们。我们很快就会出击。"
D.Strings[37667]="别着急，朋友。等大家都准备好，我们就会出击。"
D.Strings[37668]="给大家集合的时间。我们需要找些人跟我们一起去。"
D.Strings[37669]="蚀沙荒漠就在西边。"
D.Strings[37670]="这不是浪费，石母。它派上了不小的用场。"
D.Strings[37671]="它站在这个地方的原因也许正如它所说的那样。"
D.Strings[37672]="你有许多需要证明的事情。但看样子，你已经带来了那块石头。这是个好的开始。"
D.Strings[37673]="将这块石头放在我面前的地上。"
D.Strings[37674]="我已经给其他石领主送去了消息。"
D.Strings[37675]="拿上这枚徽记，它代表了我对你的祝福。现在我只能祈祷自己没有错信你。"
D.Strings[37676]="岱亚曼塔，这就是让你浪费时间的东西？"
D.Strings[37677]="那么你将对它的行为担负起责任来，石领主。当它的真实意图显露之后，你将必须给我一个解释。"
D.Strings[37678]="至于你，血肉之躯。考虑一下你现在的处境吧。你的身躯被重重岩石所包围，你脚下的大地屈从于我的意志。"
D.Strings[37679]="如果你背叛了我们，你就将无路可逃。我会缓慢地摧毁你的身体，倾听你每一片骨头碎裂的声音。"
D.Strings[37680]="这次谈话很愉快。"
D.Strings[37681]="你要来证明你自己吗？碎岩之渊在东北方。你要找的石头就在那里。"
D.Strings[37682]="准备好了就敲打水晶，我们将共同面对龙母。"
D.Strings[37683]="你远离了石母的注视，石龙。是时候让你回到你的位置了。"
D.Strings[37684]="她屈服了。干得好，血肉之躯。"
D.Strings[37685]="你正在尝试说服我，这些血肉之躯应该得到我的信任。"
D.Strings[37686]="他们就是堕落的化身，确是如此。他们的皮肤就说明了一切。"
D.Strings[37687]="他们只会寻求力量，与暮光别无二致。但你却信心十足的认为他们不会背叛我们。我养大了一个蠢货？"
D.Strings[37688]="哼，它们杀掉了石头穴居人，你觉得这能打动我？这不算什么功绩。"
D.Strings[37689]="你的看法呢？博登，你怎么看这个“勇士”？"
D.Strings[37690]="也许你说的对。即使是蠢货也能有些用处。我不是照样留下了你。"
D.Strings[37691]="我不喜欢入侵者，石母，但这些血肉之躯不辞辛苦地清理掉了赤红岩床上的污秽。"
D.Strings[37692]="他们不是暮光之锤的人。我不相信他们会是敌人。"
D.Strings[37693]="我还没有和那些外来者交谈过，但是我已经见证了他们的勇士深入碎岩之渊，并毫发未损地回来。它的能力毋庸置疑。"
D.Strings[37694]="这名勇士还直面了石龙和石龙主母，它们曾令最强大的巨人退缩，这个血肉之躯却没有丝毫的恐惧和犹豫。"
D.Strings[37695]="您知道我的立场，石母。"
D.Strings[37696]="驱使它的并非勇气。它仿佛将这里当作了自己的家园，冲锋在我的身前。它只是个傻瓜，迟早会送命。"
D.Strings[37697]="勇士归来了。"
D.Strings[37698]="这么小。这么软。真好奇你是如何坚持到现在的，血肉之躯。"
D.Strings[37699]="或者说，这正显示出了你的能力？"
D.Strings[37700]="你做的这些就只是为了世界之柱的碎片？你们这些萨满究竟想拿它做什么？"
D.Strings[37701]="然后呢？你们就会安静地离开深岩之洲？"
D.Strings[37702]="你至少有些洞察力。"
D.Strings[37703]="我的提议是：我们会向暮光教派进军，将死亡之翼的名讳从这个世界中彻底抹消掉。你们大地之环，将随我而战。"
D.Strings[37704]="如果你能做到，我就会派格尔西克将世界之柱的碎片送到神殿去。"
D.Strings[37705]="封印那道裂隙，然后离开。"
D.Strings[37706]="留着你的感谢。当我们的部队集结完毕之后就向暮光绝壁进军。我期待在战场上见到你。"
D.Strings[37707]="我们前来封住死亡之翼留下的裂隙。我们需要世界之柱来修复这一侧的裂口。"
D.Strings[37708]="我们会离开。我们无意继续留在不受欢迎之地。"
D.Strings[37709]="我们会照做的。感谢您，石母。"
D.Strings[37710]="大地来夺你性命了，邪教！"
D.Strings[37711]="你的入侵将不会被原谅。死亡之翼不会再在这里庇护你了。"
D.Strings[37712]="在即将吞噬你的大地之前畏缩吧！"
D.Strings[37713]="干得好，$r。返回神殿吧，格尔西克会在那儿等着你。"
D.Strings[37714]="欢迎来到深岩之洲，邪教徒。"
D.Strings[37715]="你呢，邪教徒？你会飞吗？"
D.Strings[37716]="你觉得我很强大？听着，精彩的还在后面。"
D.Strings[37717]="逃不掉的，小子们。"
D.Strings[37718]="你们把居所建造在我们的岩石上面。你们的无知只会导致你们的毁灭。"
D.Strings[37719]="很快，你们这些家伙就会变成我脚底下的一块污渍。"
D.Strings[37720]="看看这个东西……勇敢的站在大地之上，以为能够挑战我。"
D.Strings[37721]="你的恶臭真刺鼻，人类。"
D.Strings[37722]="你会成为一具顽强的尸体。"
D.Strings[37723]="又小又脆弱，却又如此勇敢。"
D.Strings[37724]="石龙就在这儿，凡人。赶快！"
D.Strings[37725]="死亡之翼自会对付你的石母。"
D.Strings[37726]="暮光将笼罩你，即使在这漆黑深邃的洞穴中。"
D.Strings[37727]="这是不自量力，伙计。"
D.Strings[37728]="你在地面行动自如，到了空中又如何呢？"
D.Strings[37729]="你还得再快点才行！"
D.Strings[37730]="继续攻击，野兽们！把他们在空中撕碎！"
D.Strings[37731]="我可是受够你了，伙计。"
D.Strings[37732]="不！不……"
D.Strings[37733]="塞拉赞恩终于攒足了勇气来挑战我们，是吧？"
D.Strings[37734]="靠近点，亲爱的。我有些小小的看法。"
D.Strings[37735]="你意识到一切都毫无希望了，对吧？死亡之翼已经崛起了，你的世界注定毁灭。"
D.Strings[37736]="跟紧点，亲爱的。我值得你的追逐。"
D.Strings[37737]="没那么容易，甜心。也许下一次。"
D.Strings[37738]="[Broken Common]在此受死吧。"
D.Strings[37739]="你们的尸体正好可以拿来当黑石战争机器的好燃料。"
D.Strings[37740]="请原谅我，主人……我让你失望了。"
D.Strings[37741]="B连为你带来最美好的祝愿。"
D.Strings[37742]="他别想再站起来了。"
D.Strings[37743]="啊——！"
D.Strings[37744]="啊啊啊——！"
D.Strings[37745]="世界之柱的最后一块碎片被复原了！我们必须将它们重组到一起以阻止这个世界向艾泽拉斯崩塌。"
D.Strings[37746]="整队，兄弟姐妹们！让我们履行自己的职责，载誉回到萨尔的面前！"
D.Strings[37747]="你已经证明了你有能力击败任何敌人。有你作为仪式的守卫让我倍感荣幸，年轻的英雄。"
D.Strings[37748]="暮光的刺客就要过来了！不能让他们打断这个仪式！"
D.Strings[37749]="不——！洛瓦留斯……"
D.Strings[37750]="他们在……下沉。继续努力，兄弟们！我们必须在他们返回之前完成仪式！"
D.Strings[37751]="别让刺客靠近我！"
D.Strings[37752]="他们回来了！准备战斗！"
D.Strings[37753]="阻止她！我们还能继续完成仪式！"
D.Strings[37754]="感谢元素…"
D.Strings[37755]="完成了！仪式结束了！"
D.Strings[37756]="世界之柱复原了，这个世界安全了。该去治疗地表上的伤痕了。"
D.Strings[37757]="我伤得很重……我坚持不住了……"
D.Strings[37758]="你的传说将在此终结，萨满。"
D.Strings[37759]="死亡之翼会给尘世的所有秩序带来毁灭。到那一天，我将成为他的利刃！"
D.Strings[37760]="哈哈……"
D.Strings[37761]="我们毁掉你们的要塞时，你们就该接受警告的，异教徒。"
D.Strings[37762]="玛哈特，杀掉这些教徒。我会去对付那愚蠢的女祭司。"
D.Strings[37763]="你敢回来就必死无疑。"
D.Strings[37764]="仪式几乎就要完成了！"
D.Strings[37765]="感谢你，石母。这是我的荣幸……"
D.Strings[37766]="你证明了你所言不虚，大地治愈者。为此，你将免遭大地之怒。"
D.Strings[37767]="你的伤势愈合了，就离开吧，也算是感谢我。"
D.Strings[37768]="$n，穿上你身后那套终极足球炸弹制服，到下方的码头那里去。帮助萨尔对付贸易大王！"
D.Strings[37769]="副总亲自送礼物来，真是让我感到荣幸。我马上就要打开它！"
D.Strings[37770]="所有火炮！对准红雾号开火！"
D.Strings[37771]="好的，好的！我明白她的意思了！"
D.Strings[37772]="叛徒！除非我死，否则别想让我向你投降！"
D.Strings[37773]="哈哈！这下可热闹了！"
D.Strings[37774]="小心！他们来了！"
D.Strings[37775]="$n，我需要你的帮助！"
D.Strings[37776]="该死的石头穴居人！在那儿！"
D.Strings[37777]="石头穴居人来了！"
D.Strings[37778]="随意开火！"
D.Strings[37779]="现在轮到谁挨打了？！"
D.Strings[37780]="带走了我的国王。我要带走你悲惨的生命！"
D.Strings[37781]="他们来了！不惜一切代价保护投石车！"
D.Strings[37782]="我的戒指……谁拿走了我的家族戒指……蒂罗亚，是你吗？"
D.Strings[37783]="托比亚斯……"
D.Strings[37784]="全是真的，兄弟。每个字都是真的。你有所怀疑吗？"
D.Strings[37785]="兄弟！"
D.Strings[37786]="告诉我那不是真的，兄弟。告诉我你没杀人！"
D.Strings[37787]="你知道原因！"
D.Strings[37788]="好吧，我们行动吧。"
D.Strings[37789]="我们必须继续前进！"
D.Strings[37790]="我们出发吧。尽量离那些石头穴居人远一点儿。"
D.Strings[37791]="我们越快赶到前线的另一侧，就能越快把针石熔渣场毁成碎石堆。"
D.Strings[37792]="可是为什么？！你怎么可以？"
D.Strings[37793]="出去！"
D.Strings[37794]="感觉怎么样，你这石头穴居人渣滓？！"
D.Strings[37795]="喔耶！在我们强大的投石车面前战栗吧！"
D.Strings[37796]="你们这群石头穴居人根本不知道将要到来的是什么！"
D.Strings[37797]="你当然感到愤怒。愤怒的情绪是如此邪恶和凶狠，会让你想要把人撕成碎片……"
D.Strings[37798]="你难道现在没有感觉到吗？"
D.Strings[37799]="不……不！快停下！"
D.Strings[37800]="你看，兄弟……我们并没有多大的差异……"
D.Strings[37801]="我不在乎成功率会有多低。只要我们能从这丛林的疯狂与凶残中救出一只狼人，我们的努力就都没有白费。"
D.Strings[37802]="亡者在乞求慰藉。他们的痛苦在风中回响。"
D.Strings[37803]="守卫，请退下。"
D.Strings[37804]="我得承认，请你来此并非为了自我介绍和寒暄。"
D.Strings[37805]="且让我直奔主题。我们有事相求于你。"
D.Strings[37806]="在我们的城里有一名叛徒。蓄谋已久的叛徒。"
D.Strings[37807]="我们其中一名最好的哨兵前去追踪\"他\"——我们假设那是名男子——但她似乎暴露了。"
D.Strings[37808]="今天早上，她被我们的巡逻队发现了。她就在我们自己的城市里被谋杀了。"
D.Strings[37809]="很难分辨谁能够信任。你刚到此地不久……对此一无所知。也许你能胜任这次调查。"
D.Strings[37810]="我们需要你的帮助，追捕这名叛徒。你愿意吗？"
D.Strings[37811]="还有一件事。我们安排了一名自己的人随你一同调查。"
D.Strings[37812]="这位是莉莉奥瑞伦。"
D.Strings[37813]="请叫我莉莉。"
D.Strings[37814]="我们之前提到的那位哨兵是莉莉的姐妹。她可以信任。"
D.Strings[37815]="我们会抓住那名叛徒的，女祭司。您无需担心。"
D.Strings[37816]="我相信你会的，但请一定小心。"
D.Strings[37817]="…这看上去几乎没有搏斗的痕迹。"
D.Strings[37818]="这很反常。当危险临近之时，她一定会全力一搏。"
D.Strings[37819]="你认为那个杀手偷袭了她？即使她认为她发现了他的踪迹？"
D.Strings[37820]="别放过任何细节。这里一定有什么线索能帮助我们捉到那个凶手。"
D.Strings[37821]="你找到什么了？"
D.Strings[37822]="一片沾泥的叶子……"
D.Strings[37823]="%s轻轻闻了闻那片叶子。"
D.Strings[37824]="翠羽树叶！真是好运。"
D.Strings[37825]="在达纳苏斯只有一个地方长有这种树。也许我们要找的凶手就是在那里沾上这片树叶的。"
D.Strings[37826]="我们要找的那栋建筑就在工匠区。我们走。"
D.Strings[37827]="维罗拉比我要大上几岁。"
D.Strings[37828]="过去这几个月我们一同经历了一段困难的时光。我猜所有人都是。"
D.Strings[37829]="你是否有过这种体验，某件事情你明知十分重要，却怎么也想不起来？似乎自从玛法里奥回来之后，所有人都变成了这样。"
D.Strings[37830]="有时候我的眼前会闪过恐怖的镜像。阴影在黑夜中吞噬我们。亲友反目，自相残杀。"
D.Strings[37831]="这些很难用语言形容。一切都应该变好的。玛法里奥回来了。泰达希尔终于得到了巨龙的祝福…某些巨龙的祝福。"
D.Strings[37832]="但我总觉得……觉得我生命中的某些东西不见了，消逝了。仿佛梦境终于醒来。"
D.Strings[37833]="我不应当让这种失常影响到我。我……我应该比我的姐妹们要好受一些。"
D.Strings[37834]="我的懊恼到此为止。这就是那座建筑。让我们进去调查一下。"
D.Strings[37835]="这些房间通常会提供给造访城市的客人。任何人都有可能会居住在这里。"
D.Strings[37836]="这是一张黑海岸的地图。上面绘有从奥伯丁通往洛达内尔的小径……还有几条路通往其他的安全藏身处。"
D.Strings[37837]="这是某种攻击计划？奥伯丁已经被大灾变的动荡撕碎了。那儿能有什么价值？"
D.Strings[37838]="我认为这些可能是逃跑路线。"
D.Strings[37839]="这条穿过海滩的路线被圈了起来。我们赶快前往那个地方，看看能不能有什么发现。"
D.Strings[37840]="我会向泰兰德和玛法里奥报告我们的进展。我会尽快与你在海滩会合。"
D.Strings[37841]="你最好径直过去，但千万留心。"
D.Strings[37842]="以艾露恩之名！他们都遭到了伏击…这是背叛…"
D.Strings[37843]="那个叛徒策划了一切！他是这场屠杀的帮凶。"
D.Strings[37844]="他受伤了。我想我能追踪这些血迹。"
D.Strings[37845]="这边！跟着我。"
D.Strings[37846]="这边有一些新鲜的痕迹，沿着森林的边缘一直延伸到了镇上。但很难讲是不是他留下的。"
D.Strings[37847]="这儿！一块血迹。我们的方向是正确的。"
D.Strings[37848]="就在守卫的眼皮下？自信的杂种…"
D.Strings[37849]="哨兵！你有没有看到一个受伤的暗夜精灵经过？"
D.Strings[37850]="是的。朝瀑布那边去了。我劝他疗好伤再走，可他不听。"
D.Strings[37851]="过来，朋友，赶快！"
D.Strings[37852]="在那里！他在和谁说话？"
D.Strings[37853]="……他们去了哪里？"
D.Strings[37854]="他们从地面上逃不掉，难道他们……"
D.Strings[37855]="我希望你会游泳，狼人。"
D.Strings[37856]="真高兴你成功了。"
D.Strings[37857]="他们就在头顶上。流水应该能掩盖我们接近的声音。当你准备好就告诉我。"
D.Strings[37858]="让我们结束这一切。"
D.Strings[37859]="我会对付邪教徒。你处理那个叛徒。"
D.Strings[37860]="别让他逃走了！"
D.Strings[37861]="别动，让我结果他。"
D.Strings[37862]="不，莉莉，别杀他。"
D.Strings[37863]="但…我…是的，我的女士，如你所愿。"
D.Strings[37864]="为什么，德纳萨里安？我看着你长大，你心中曾经充满希望。"
D.Strings[37865]="希望？就像范达尔希望为我族赢回往日的荣耀？重新得到不朽的生命？"
D.Strings[37866]="因为你的嫉妒，你对他判刑，将他关进你的秘密监狱，如同对你的亲兄弟所做的一样。"
D.Strings[37867]="如果我不能在我的族人之中找到一个家，我还能去哪里，“导师”？"
D.Strings[37868]="%s转过身，看上去非常不安。"
D.Strings[37869]="莉莉，请将这名犯人带给哨兵，我们将公正的对待他。"
D.Strings[37870]="还有你，我亲爱的狼人，今天你可帮了我们一个大忙。"
D.Strings[37871]="玛法里奥也许不会把他的想法挂在嘴边，但他却一直在关注着你的族人。"
D.Strings[37872]="他非常了解你们所遭受的诅咒和它的可怕影响。对此他也对自己怀有几分自责。"
D.Strings[37873]="我想今天你已经消除了他的疑虑。你显示出的高贵和自律也许已经超出了他期待。"
D.Strings[37874]="真心地感谢你。"
D.Strings[37875]="当你准备离开这儿时请一定告诉我。"
D.Strings[37876]="把那个带给扬希——就在瀑布边上。那个无知的人类不会知道那不是我。"
D.Strings[37877]="可怜的虫子。准备面对莫格霍尔猛击吧！"
D.Strings[37878]="这位是格雷戈里。"
D.Strings[37879]="他是我们的新盟友，从吉尔尼斯而来。很容易就能推断出他并未牵涉进此事，我们能够相信他。"
D.Strings[37880]="我们定会捉住那名叛徒的，我尊敬的女士。您无需担忧。"
D.Strings[37881]="一名哨兵会如此容易地被击倒？我以为她们都是精锐的战士。"
D.Strings[37882]="也许她被偷袭了。也许…她完全信任那个杀手。"
D.Strings[37883]="一种特别的气味。附近区域里没有东西会发出这种味道。"
D.Strings[37884]="我应该能追踪这些痕迹。希望是那个杀手留下的。"
D.Strings[37885]="这些足迹延向了东北方。请跟着我。"
D.Strings[37886]="长久以来，我对吉尔尼斯之外的世界一无所知。我深恐我们再也没办法找到一个可以称之为家园的地方了。"
D.Strings[37887]="泰兰德和玛法里奥张开双臂接纳了我们。就好象我们是失散已久的家人。这很奇怪…也很令人宽慰。"
D.Strings[37888]="但我也听到了一些传言…困惑的传言…甚至是反对的声音。"
D.Strings[37889]="我向玛法里奥问起此事，他告诉了我这座城市近来经历的悲剧。一名领袖被劫走了，许多生命逝去了。"
D.Strings[37890]="他似乎比那些低语的平民所知更多，他确信这名叛徒是达纳苏斯最后的麻烦，除了大灾变。"
D.Strings[37891]="玛法里奥的智慧和诚实令我折服。我相信了他的说法。也许还有其他的答案，但与我无关。"
D.Strings[37892]="闲聊到此为止。足迹一直延伸到了这里。这座建筑里的植物长满了我们之前找到的那种叶子。"
D.Strings[37893]="这是客房。有些客房被提供给了我的族人。"
D.Strings[37894]="太多人曾使用过这个地方，我们无从分辨气味。也许我们能在里边找到些线索。"
D.Strings[37895]="一张黑海岸的地图。在到达鲁瑟兰村之前不久我才见过这些地方。"
D.Strings[37896]="上面标注了一些路线，从奥伯丁出发，数个目的地。看起来像是撤离计划。"
D.Strings[37897]="这条通往西部海滩的路线被圈了起来。你知道怎么去那个地方吗？"
D.Strings[37898]="我向玛法里奥作过承诺，无论有任何进展都将向他报告。我将尽快与你在海滩碰头。"
D.Strings[37899]="这是一场屠杀。一次有计划的伏击？这些元素的目标到底是谁？"
D.Strings[37900]="我们要找到那个叛徒。我发誓。"
D.Strings[37901]="他受伤了。我很容易就能找到他的痕迹。"
D.Strings[37902]="他的痕迹还很新鲜。我们距离他不远了。"
D.Strings[37903]="希望你知道怎样游泳。"
D.Strings[37904]="没那么快，叛徒。"
D.Strings[37905]="你不会这么容易就得到解脱。你还要等着月神殿的发落。"
D.Strings[37906]="令人印象深刻，格雷戈里。我必须承认，我从未料想过你能如此克制。"
D.Strings[37907]="我的族人们绝不是徒有虚名，我的女士。如果给您留下了任何疑虑，我都向您致歉。"
D.Strings[37908]="格雷戈里，请将这名凡人带给哨兵，我们将公正的对待他。"
D.Strings[37909]="至于你，我亲爱的朋友，今天你可帮了我们一个大忙。"
D.Strings[37910]="要让我们信赖一位新人着实不易。你恰好在这个危急时刻造访了我们。"
D.Strings[37911]="这真是我们的幸运，你显示出了高尚的荣誉感和奉献精神。"
D.Strings[37912]="这么快就回来了？"
D.Strings[37913]="是的——我需要另一只双足飞龙。"
D.Strings[37914]="别想把我骗到外面，我不会中你的陷阱！就在这里面对我吧，懦夫！"
D.Strings[37915]="在外多加小心，$n。你不会想要在那艘船上待很久……再来几发炮弹她就会沉了。"
D.Strings[37916]="呜哇！感受莫格霍尔的愤怒吧！"
D.Strings[37917]="准备受罚吧！莫格霍尔猛击！"
D.Strings[37918]="我们终将自长久萦绕的阴影中获得解脱。"
D.Strings[37919]="凡尔纳号很快就要到了！拿起武器整队备战，兄弟们！"
D.Strings[37920]="凡尔纳号已经到达。全体登船！"
D.Strings[37921]="狼人凝视着迟疑了！"
D.Strings[37922]="战斗是我的天性！"
D.Strings[37923]="这是你自找的！"
D.Strings[37924]="不来惹我们就没事了。"
D.Strings[37925]="感受雷霆的怒吼吧！"
D.Strings[37926]="你无足轻重！"
D.Strings[37927]="你的痛苦让我感到兴奋不已！"
D.Strings[37928]="这个世界已经毁灭了，$n。"
D.Strings[37929]="我还记得曾几何时，在这个世界上没有兽人。你能想象吗？没有那些该死的兽人！"
D.Strings[37930]="也许有一天我们能重享和平。也许我能在上厕所时拉出金子来。"
D.Strings[37931]="等这一切都结束之后，我要请你喝一杯，$n。"
D.Strings[37932]="要是我之前没对你说过，$n，欢迎来到B连。"
D.Strings[37933]="你很好，$n。不像暴风城里那些一无是处、只知敛财的政治家。"
D.Strings[37934]="等我们把这里清理干净，也许我们会开始重建这地方。可能他们会把它交给B连。我们可以管它叫B连要塞！"
D.Strings[37935]="我不喜欢这个……感觉太简单了。"
D.Strings[37936]="$n告诉过你我们是怎么找到丹弗斯的吗，约翰尼？我想那群兽人也许对他做过不恰当的事。"
D.Strings[37937]="我已经对兽人感到厌倦了。我们应该把他们全都杀死，然后让萨尔慢慢甄选。"
D.Strings[37938]="谁有我女儿达希的消息？"
D.Strings[37939]="等我们结束这里的事情，我想我会前往铁炉堡。尝尝铁炉堡最富盛名的美酒，再见见那些友善的矮人姑娘。"
D.Strings[37940]="射击视野良好！再来点弹药！"
D.Strings[37941]="你也听到了！保持机枪的弹幕！"
D.Strings[37942]="这才叫“目标不计其数”嘛！"
D.Strings[37943]="发射那些炮弹要小心…"
D.Strings[37944]="不能让耐普图隆的亡魂把我们当成敌人！"
D.Strings[37945]="如果他们在水元素位面站住了脚，我们就麻烦了！"
D.Strings[37946]="弹道计算中……"
D.Strings[37947]="弹药就绪！"
D.Strings[37948]="开始射击！"
D.Strings[37949]="萨满，那个强大的耐普图隆在哪？！"
D.Strings[37950]="为什么要我们守卫他的领土？"
D.Strings[37951]="元素位面的领主们都是纯粹的混沌存在，纳兹戈林。"
D.Strings[37952]="没人能判断他们的动机……"
D.Strings[37953]="呸！除非他想让他家里塞满这些纳迦，否则他最好赶紧出现……"
D.Strings[37954]="看看那些玩意儿的大小！那是些什么东西？"
D.Strings[37955]="纳迦得到了上古之神奴仆的帮助。"
D.Strings[37956]="扭曲的怪物们一心要毁灭全部生灵。"
D.Strings[37957]="那些元素完全寡不敌众啊。"
D.Strings[37958]="他们一点机会都没有……"
D.Strings[37959]="我感觉到了绝望。"
D.Strings[37960]="没有援助，他们必败。"
D.Strings[37961]="B连，全体出席并作为……"
D.Strings[37962]="你真相信以兽人的脑子能制定出如此大规模的入侵计划？"
D.Strings[37963]="不要紧。你现在就要死了，作为在我们进军暴风城之时献给死亡之翼的卑微供品。"
D.Strings[37964]="被主人的怒火吞没吧！快来受死！"
D.Strings[37965]="我对这些游戏感到厌烦了！"
D.Strings[37966]="在烈焰中呻吟吧！"
D.Strings[37967]="浮在这个地方只是在浪费时间……"
D.Strings[37968]="我们到那裂口旁边去！"
D.Strings[37969]="这、这不可能，长官！水流……太急了！"
D.Strings[37970]="别停下，伙计们！保持火炮的弹药充足！"
D.Strings[37971]="呜哈！这才叫“目标不计其数”嘛！"
D.Strings[37972]="如果他们进了裂口，就赶不出去了。"
D.Strings[37973]="萨满，那个耐普图隆到底在哪。"
D.Strings[37974]="他为什么不保护他自己的领土？"
D.Strings[37975]="元素位面的领主们都是纯粹的混沌存在，队长。"
D.Strings[37976]="如果他不好好保护家园，那他就要无家可归了。"
D.Strings[37977]="那些元素显然寡不敌众。"
D.Strings[37978]="徒劳的战斗……"
D.Strings[37979]="这毫无意义！"
D.Strings[37980]="我们这样是抵挡不住纳迦的。"
D.Strings[37981]="不可能，长官！水流太急了！"
D.Strings[37982]="真是些狂妄的蠢货！"
D.Strings[37983]="你将和我一起死，基沙恩！这世界上的英雄已经够多了！"
D.Strings[37984]="你这胆小的混蛋！你杀了他们所有人！现在我要杀了你！"
D.Strings[37985]="现在！放出海怪！"
D.Strings[37986]="跟着我，宠物们！耐普图隆的国度终于成了我们的掌中之物！"
D.Strings[37987]="现在怎么办，老朋友？"
D.Strings[37988]="我们遭受了惨重的失败。"
D.Strings[37989]="我们世界未来的希望，变得渺茫了。"
D.Strings[37990]="必须让萨尔知道这一切。"
D.Strings[37991]="他会指引我们……"
D.Strings[37992]="埃鲁纳克！不——！"
D.Strings[37993]="那个兽人……可真大。"
D.Strings[37994]="它要爆炸了！快跳上飞龙！"
D.Strings[37995]="你是人民真正的英雄，利亚姆。不像其他的贵族，我们将让他们付出代价。"
D.Strings[37996]="好吧，萨满，现在呢？"
D.Strings[37997]="埃鲁纳克，在你身后！"
D.Strings[37998]="这是……？"
D.Strings[37999]="我们必须把敌人拖得更久一点。用不了多久，塞纳留斯就会回到我们中间。"
D.Strings[38000]="快点……她就要挣脱束缚了！"
D.Strings[38001]="我宁可去酿酒也不愿意打架！$B$B可要是走运的话，也许我两项工作都能胜任，呃？"
D.Strings[38002]="趁一切还有转机，让我们快去海加尔吧！"
D.Strings[38003]="那可不太好。"
D.Strings[38004]="这片土地的祝福与你同在。"
D.Strings[38005]="深岩之洲是大地的国度。死亡之翼在第一次被击败之后逃到了这里。"
D.Strings[38006]="他的追随者就是在这座神殿里侍奉他，为他恢复力量。坚固的源质盔甲被镶嵌到了他的躯壳上。"
D.Strings[38007]="死亡之翼重返艾泽拉斯时给两个世界留下了巨大的裂隙。这道裂口是造成大灾变的主要原因，威胁了我们世界的存亡。"
D.Strings[38008]="萨尔在艾泽拉斯一侧使用他的全部力量稳定着这道裂隙。我们也在这边尽力维持裂隙的稳定。"
D.Strings[38009]="死亡之翼离开这里的时候不仅仅伤害了我们的世界，在这个神殿里原本存放着的一块泰坦制造的魔法巨石也随之破碎了。"
D.Strings[38010]="世界之柱——可不止是个响亮的名字，它不仅承受着这座神殿的重量。如果它没有被复原，那么整个深岩之洲都向艾泽拉斯崩溃，这将会给两个世界都带来灭绝性的后果。"
D.Strings[38011]="世界之柱碎裂之后，有三块碎片遗失了。我们必须找到这些碎片，否则，我们的世界将迎来末日。"
D.Strings[38012]="我们必须让那些真菌恶魔远离前线。它们太强大了！"
D.Strings[38013]="我父亲就在附近，我能感觉到！我们必须突破他们的防线，救出我的父亲！"
D.Strings[38014]="古加尔开始施放末日之烈焰轴心！"
D.Strings[38015]="让我们尽量接近那个坑洞！"
D.Strings[38016]="珊蒂斯弯弓对准了群星！"
D.Strings[38017]="烧吧！烧吧，你们这群可怜虫！"
D.Strings[38018]="艾露恩，指引我的箭矢！"
D.Strings[38019]="如果你想要骑乘狮鹫，那你就来对地方了。"
D.Strings[38020]="波涛之王，你的统治已经到头了！"
D.Strings[38021]="再过不久，你宝贵的王座就会成为一片废墟！"
D.Strings[38022]="你那章鱼脑袋将成为献给女王的战利品……"
D.Strings[38023]="你们在我的国度里，毒蛇！"
D.Strings[38024]="你以为我对这种袭击毫无防备？"
D.Strings[38025]="净化你们的方法就近在咫尺…"
D.Strings[38026]="……但你们却永远找不到。"
D.Strings[38027]="搜查这个地方，我的军团！把猎潮者的陷阱找出来！"
D.Strings[38028]="啊，我无畏的协助者，对吧？"
D.Strings[38029]="你们也许会后悔来到这里。"
D.Strings[38030]="在我净化这片水域时，那些污秽的仆从定会拼命阻挠我。小心！"
D.Strings[38031]="啊……他们的污秽玷污了我！"
D.Strings[38032]="我开始……厌烦了……"
D.Strings[38033]="蠢货！派上点儿用场……"
D.Strings[38034]="耐心点，客人们。这片水域快被净化了。"
D.Strings[38035]="那头怪兽回来了！绝对不能让它污染我的水域！"
D.Strings[38036]="见证这纯水之力吧！"
D.Strings[38037]="我的水域净化了！汲取它的力量吧！"
D.Strings[38038]="你们这种人……不可信任。"
D.Strings[38039]="我的国度容不下你……"
D.Strings[38040]="关注你们……简直浪费精力……"
D.Strings[38041]="终于把污秽从我的国度中清除了。"
D.Strings[38042]="你们可以自行离开了。"
D.Strings[38043]="谢谢！我不知道我们还能活多久。"
D.Strings[38044]="这个笼子困住了我的魔法。"
D.Strings[38045]="如果你不介意，我要把我们传送回反抗军营地了。我们会稍后再向你表达我们的谢意。"
D.Strings[38046]="莫格霍尔！你应该和你那些恶魔混血渣滓一起死在外域！这儿没有你的容身之处。"
D.Strings[38047]="喔，嚯。"
D.Strings[38048]="自由！甜美无比的自由！"
D.Strings[38049]="震耳欲聋的战吼在要塞中回荡！"
D.Strings[38050]="他太强了！撤退！"
D.Strings[38051]="无论带往何方，我们都会昂着头，维持血脉的纯净。总算摆脱你了，莫格霍尔。今天就是龙喉氏族的新生黎明。"
D.Strings[38052]="扎伊拉……愚蠢的叛徒……你把灵魂出卖给了部落？你和我有什么区别？去追随地狱咆哮吧，看他能带你们走向何方。"
D.Strings[38053]="起作用了。用力抓住他，基特斯。"
D.Strings[38054]="我……我不能……"
D.Strings[38055]="该死的，基特斯，我说了，抓住！"
D.Strings[38056]="基特斯……"
D.Strings[38057]="基特斯！"
D.Strings[38058]="我记起来了……这全都是你的错！"
D.Strings[38059]="你把狼人带到了暮色森林！你将黑暗骑士引到了我的农场，任由他们杀死我的家人，你却躲了起来！"
D.Strings[38060]="我生命中每一道痛苦的伤痕都是你造成的！我应该杀掉你！"
D.Strings[38061]="如果你要证明自己和那些野兽不同，就必须放他走，我的朋友。"
D.Strings[38062]="基特斯，你有许多东西需要补偿。我不会轻易放过你的。"
D.Strings[38063]="我要让你看看什么是真正的力量！"
D.Strings[38064]="奥哈恩凝聚了她的力量！"
D.Strings[38065]="欢迎来到多兰纳尔，$c。如果你需要菜谱或者基础的烹调材料，就请来找我。"
D.Strings[38066]="好了，我们把这个加在这里……"
D.Strings[38067]="离心分离……"
D.Strings[38068]="好了！看看这个！"
D.Strings[38069]="石龙主母低下头表示投降。"
D.Strings[38070]="希望你不是在找东西吃，$c。"
D.Strings[38071]="停止你的愚行！"
D.Strings[38072]="我们会解决他们！"
D.Strings[38073]="石龙主母靠近了。"
D.Strings[38074]="$n！酋长他还活着——他在海岸那边被救了。快出来。这座城镇一定是我们的了！"
D.Strings[38075]="地狱咆哮，我是龙喉氏族的扎伊拉。你的人民使我们从暴君的手中重获自由。我们是你的武器。龙喉氏族之力听你号令。为了部落！"
D.Strings[38076]="当你准备开始时就去找坚定者特尔拉斯对话。"
D.Strings[38077]="是的，我还活着！没有暮光龙能击败我。"
D.Strings[38078]="啊，是龙喉氏族的女武士。让我好好看看你的脸。"
D.Strings[38079]="鲜血与荣耀，英雄。部落欢迎你。你们的能力将在消灭暮光之锤，夺取这片海岸的战争中受到考验。但首先……还有些事情要处理。"
D.Strings[38080]="来吧！*哼哼*我在这里就能闻到你的$r臭气。"
D.Strings[38081]="令人印象深刻……"
D.Strings[38082]="……事已至此。"
D.Strings[38083]="现在，见证真正的力量吧！"
D.Strings[38084]="……感受元素的愤怒！"
D.Strings[38085]="$n？你早就该来了。是什么拖住了你？我的父亲正生命垂危！"
D.Strings[38086]="我决定了！这次外出冒险时，我要让呼噜先生帮我拉怪。"
D.Strings[38087]="采取行动。"
D.Strings[38088]="嘿，你好啊。我想要领出我的宠物——呼噜先生！"
D.Strings[38089]="呼噜先生！可怜的，可怜的呼噜先生……"
D.Strings[38090]="呼噜先生！！回到我这里来，呼噜先生！"
D.Strings[38091]="呼噜先生……呃……好啊……"
D.Strings[38092]="对了……他逃走了！他真是个又肥又多汁的家伙，但他刚从我们这儿逃走了。真遗憾。"
D.Strings[38093]="维尔隆紧张地看着周围，努力不去看烤肉架上的那头猪。"
D.Strings[38094]="Lok'tar ogar！这个年轻的$r$c战胜了埃其亚基。$g他:她;的行动显示了新部落的力量！"
D.Strings[38095]="%s被制服了。"
D.Strings[38096]="为吉尔尼斯而战"
D.Strings[38097]="面对你的末日！"
D.Strings[38098]="根除……"
D.Strings[38099]="湮灭……"
D.Strings[38100]="你的能力还不足以参加吉尔尼斯之战。当你的经验更丰富之后再回来吧。"
D.Strings[38101]="啊，丛林。知道吗，能够偶尔离开城市真是一件好事情。"
D.Strings[38102]="你的能力还不足以参加双子峰的战斗。当你的经验更丰富之后再回来吧。"
D.Strings[38103]="双子峰"
D.Strings[38104]="就要开始了……"
D.Strings[38105]="看到小强冰冷僵硬的尸体，%s陷入了狂怒！"
D.Strings[38106]="小强的死使%s陷入了狂暴！"
D.Strings[38107]="$n，你要从这些巨人和石腭怪的头顶上飞过去。不要试图从他们中间穿过去。"
D.Strings[38108]="在线。"
D.Strings[38109]="摧毁。"
D.Strings[38110]="恢复活动。"
D.Strings[38111]="伟大的拉斯塔哈向你致以问候，联盟的成员。"
D.Strings[38112]="石爪山的兽人绝不会再容忍你的暴虐，邪恶的怪物。"
D.Strings[38113]="这是我的马车！\n\n我的！"
D.Strings[38114]="第一个移动的家伙会被一道闪电劈中脑袋！"
D.Strings[38115]="让那些家伙老实一点，不要乱动！"
D.Strings[38116]="只要乖乖听话，就不会有人受伤！"
D.Strings[38117]="你让元素蒙羞。小心一点，否则你可就要小命不保了！"
D.Strings[38118]="你们的主人会感觉到你们所经受的每一点痛苦。"
D.Strings[38119]="该死的，我要的就是它！"
D.Strings[38120]="忠诚的信徒将侍奉在他身边！啊！！！"
D.Strings[38121]="任何牢狱都困不住我！！"
D.Strings[38122]="你是$n，对吗？加兹鲁维让我带你到这条河上游去！准备好出发以后就跳进来吧。"
D.Strings[38123]="又开始了……"
D.Strings[38124]="不要再来了……"
D.Strings[38125]="我得到了这个……"
D.Strings[38126]="他不会去任何地方。"
D.Strings[38127]="任何人都不许离开，这是利亚姆王子的命令。"
D.Strings[38128]="现在离开并不安全。这片森林中潜伏着可怕的东西。"
D.Strings[38129]="保持冷静。一切都在控制之中。"
D.Strings[38130]="赶快，$n！"
D.Strings[38131]="你不能对我们这样做！"
D.Strings[38132]="我的孩子们还在风谷村里，没有人照顾！我必须去找到他们！"
D.Strings[38133]="出了什么事？我仿佛看到有什么东西在房顶上。"
D.Strings[38134]="朋友，你需要什么？"
D.Strings[38135]="斯奇兹说他已经为我前往硬钳避世乐园的旅途付过钱了。我想现在出发。"
D.Strings[38136]="睁大眼睛，$c。即使是杜隆塔尔也难免会潜藏着敌人。"
D.Strings[38137]="乌尔弗雷德说他已经为我前往探险者协会挖掘场的旅行付过钱了。我想现在出发。"
D.Strings[38138]="探险者协会的组建是为了发掘出隐藏在这个世界各个角落的秘密。大灾变对这个世界造成了巨大的破坏，但数不清的古代遗迹和宝藏也因此有机会重现天日。"
D.Strings[38139]="吆，我们的确是遇到了一点麻烦，不过剩下的旅途就应该是一帆风顺了。"
D.Strings[38140]="乘着一艘温暖、舒适的小艇泛舟杜隆塔尔真是一大乐事。"
D.Strings[38141]="在这样美好的旅程中，出现一些失误也是难免的事。"
D.Strings[38142]="大家总是说：“荷尔登，为什么你要在这条河上行船？”我则问他们：“为什么你们不这样做？”……然后，呃，往往就没有然后了。"
D.Strings[38143]="我们很快就会停下来了。然后你沿着大路向西前进，就能到达诺兹波克的哨站了。"
D.Strings[38144]="为什么大门紧关着？"
D.Strings[38145]="我们必须离开这里！嚎叫声每晚都在变得更大。"
D.Strings[38146]="他们对我们说，吉尔尼斯城是安全的……"
D.Strings[38147]="和其他人一起留在这里，不要擅自行动。"
D.Strings[38148]="别让他们突破阵线！"
D.Strings[38149]="为了风谷村！为了吉尔尼斯！"
D.Strings[38150]="去死吧，恶心的怪物！"
D.Strings[38151]="对着风谷村防御者咆哮。"
D.Strings[38152]="我只对战士进行训练，$c。你得去别处找找。"
D.Strings[38153]="你准备好接受训练了吗，战士？"
D.Strings[38154]="真高兴看到你成功了，$n。"
D.Strings[38155]="让我看看今天的馅饼有哪些选择。"
D.Strings[38156]="为什么是馅饼而不是蛋糕？"
D.Strings[38157]="馅饼比蛋糕要高级多了！这简直是人尽皆知！难道像你这样有身份的$c竟不知道这么重要的事？"
D.Strings[38158]="我会记住的。"
D.Strings[38159]="听到什么有趣的消息了吗，$n？你要是敢泄露与我有关的半点儿消息，就等死吧。"
D.Strings[38160]="真是可悲。部落变得一天比一天弱……"
D.Strings[38161]="暮光之锤的耳目无所不在！杀了我，马上会有无数人接替我的工作！"
D.Strings[38162]="我的预视能力……我看到了未来……我看到了将要发生的一切……"
D.Strings[38163]="这个世界分崩离析。要是你能看到我所目睹的恐怖之景……"
D.Strings[38164]="效命是疯狂的，可反抗……是不可能的！"
D.Strings[38165]="不管暮光之锤的信徒们藏到哪里，我们都将击败他们。就连元素位面也不是他们安全的避风港。"
D.Strings[38166]="你应该让宠物等在这里。小心黑石狼骑首领！|TInterface\\Icons\\SPELL_NATURE_TIMESTOP.BLP:24|t"
D.Strings[38167]="别忘了命令你的宠物跟着你！|TInterface\\Icons\\ABILITY_TRACKING.BLP:24|t"
D.Strings[38168]="当死亡之翼毁掉世界之柱时，他打开了一道位于你我世界间的裂隙。这些孢子与菌类就是后果之一。$B$B让我们看看能否共同解决它们。"
D.Strings[38169]="别忘了抓个战争卫士，$n。"
D.Strings[38170]="B连战地工具现已激活。在你的动作条上已有可用的新技能。$B关闭B连战地工具即可停用。"
D.Strings[38171]="B连战地工具现已激活。在你的动作条上已出现放置爆盐技能。$B关闭B连战地工具即可停用。"
D.Strings[38172]="石胆，你这懦夫！找个和你体型一样大的人交手吧！"
D.Strings[38173]="赶快把我身上这些锁链弄掉！我要把你碾碎！"
D.Strings[38174]="弗林特！快走开！他太强大了！"
D.Strings[38175]="不得好死的臭气熏天的石头穴居人！你们永远别想知道我把世界之柱的碎片藏在哪儿！"
D.Strings[38176]="你太迟了，石胆。大名鼎鼎的骑兵已经到了！"
D.Strings[38177]="你好啊，$c。想要买点儿什么吗？"
D.Strings[38178]="等我挣脱这些锁链，元素位面中没有任何力量能阻止我杀了你，石胆！"
D.Strings[38179]="快放了我，否则就来不及了！要是没有完整的世界之柱，深岩之洲撑不了多久！"
D.Strings[38180]="你还没意识到你在做什么，石胆！你囚禁我，这是在把深岩之洲和我们所有人都推向万劫不复！"
D.Strings[38181]="$n！你可真是稀客啊。快过来帮帮我，好吗？"
D.Strings[38182]="我们只需把这两个混在一起……"
D.Strings[38183]="……稍微搅一搅……"
D.Strings[38184]="……炼金术，炼金术，炼金术……"
D.Strings[38185]="……然后，我们把药水放到样本上……"
D.Strings[38186]="好了。你给我带来的物质大约是……十五万年前的？什么？！我还得再进行另一个实验。"
D.Strings[38187]="古拉巴什已经灭亡，连同哈卡一起。我大多数的赞达拉同胞都回到了他们的故乡。$b$b现在，守卫祖尔格拉布的重任就落在了我，查巴尔和邦巴拉暗矛巨魔的肩上。"
D.Strings[38188]="梅维克，我光顾着追踪赞吉尔，忘了自己该干的事儿了。你能提醒我接下来要去哪儿吗？"
D.Strings[38189]="这根古老的图腾有着蝙蝠的造型。这一定就是梅维克说的那根图腾。"
D.Strings[38190]="这些泰坦圣物基本毫无活动力。像赞吉尔药剂这样的东西应该不会产生任何效果。让我们试试看！"
D.Strings[38191]="这很……出乎意料。"
D.Strings[38192]="哦，嗨，$n。"
D.Strings[38193]="你救了我和我儿子。"
D.Strings[38194]="我和我的人民都对你感激不已。"
D.Strings[38195]="把好消息带回给燃钢·磁石。我们很快就会在巨石之炉再见面。"
D.Strings[38196]="这位英雄是代表大地之环来的。他们需要中部碎片。"
D.Strings[38197]="嘿！你在那下面干什么呢？"
D.Strings[38198]="快，抓住梯子！那巨魔看起来可不太友善！"
D.Strings[38199]="那王子跑了。糟透了！"
D.Strings[38200]="Zub zub。$B$B什么？走开。"
D.Strings[38201]="Zub zub。$B$B什么？两声Zub对你来说还不够吗，$c？Zub zub。"
D.Strings[38202]="干嘛问我？我又不了解暮光之锤。"
D.Strings[38203]="<劳工一边流汗一边抽搐。>$B$B我……我是说……呃，真糟！"
D.Strings[38204]="<劳工的瞳孔因恐惧而放大。>$B$B不！你发现萨乌拉诺克是奥格瑞玛新的教派领袖？他告诉我他的秘密是安全的！"
D.Strings[38205]="等等——啊——你在套我的话！这不公平！"
D.Strings[38206]="秘密教派已经渗入奥格瑞玛航运线了吗？"
D.Strings[38207]="我可没提到什么暮光之锤。是你说的暮光之锤。"
D.Strings[38208]="我对你们的教派领袖了解得一清二楚。"
D.Strings[38209]="这么说来是真的了？萨乌拉诺克真的背叛了部落！"
D.Strings[38210]="安静点，白痴。"
D.Strings[38211]="奥格瑞玛变得比以往更强大！"
D.Strings[38212]="我能帮什么忙吗？"
D.Strings[38213]="你好啊，$c！奥格瑞玛是世界航运的枢纽。北飞艇塔能把你送往荆棘谷和幽暗城。南飞艇塔会带你去雷霆崖或直达诺森德。$B$B飞行管理员多拉斯会送你畅游卡利姆多各地——至少能把你送到你已经去过的地方。"
D.Strings[38214]="教派？我不知道。不过似乎有些可疑分子在南飞艇塔附近晃来晃去。"
D.Strings[38215]="我什么都不知道！去问别人吧。"
D.Strings[38216]="秘密教派？是不是在南飞艇塔底下集会的那些人？"
D.Strings[38217]="秘密教派？有些鬼祟的兽人在南飞艇塔附近游荡，这事儿跟你没关系吧？"
D.Strings[38218]="我这么蠢，根本加入不了教派。自从我从飞艇的后部摔下来就成这样了。我被螺旋桨打到。然后掉到了一块石头上。他们用一只金属大碗把我的头固定住，以让它变得又圆又硬。$B$B<他用拳头敲了敲自己的头。>$B$B然后闪电就来了。"
D.Strings[38219]="南飞艇塔里一直能听到兽人在诡异地窃窃私语。每当我走近，他们就立即不说话了。"
D.Strings[38220]="我不知道。$B$B别打我！"
D.Strings[38221]="快点挖！再快点！不许停！"
D.Strings[38222]="快挖！矿工们！为了永远的和平！"
D.Strings[38223]="讨厌的矿工！照我们说的去做！"
D.Strings[38224]="挖矿石！矿工们快点儿挖矿石！"
D.Strings[38225]="这些矿工太懒了！矿工为什么会这么懒？！"
D.Strings[38226]="矿工们赶快挖，不然狗头人再让你们吃鞭子！"
D.Strings[38227]="对不起，可我无法对你进行训练。"
D.Strings[38228]="选择成为法师就是选择走上一条布满荆棘的险途。许多人都不理解我们。就连我们自己人都在艰难地接受我们的艺术。"
D.Strings[38229]="父亲！让我帮你除去那些锁链。"
D.Strings[38230]="你是来帮助铁炉堡的吗，还是要整天看着我发呆？"
D.Strings[38231]="真是活见麻疯侏儒了！见到你真是太好了。我原本还在担心前面那只熔岩巨虫会把来访者都吓跑了。既然你来了，就来帮我一把。"
D.Strings[38232]="我想你得找把钥匙才能打开这笼子。等等，你该不是想告诉我，我身后那个吓人的怪物把钥匙给吃了？是吗？"
D.Strings[38233]="我们必须尽快找到世界之柱的中部碎片，返回大地神殿。"
D.Strings[38234]="|TInterface\\Icons\\ability_rogue_shadowdance.blp:20|t%s开始召唤|cFFFF0000腐蚀信徒|r来协助他！"
D.Strings[38235]="$n，到这儿来。"
D.Strings[38236]="世界之柱的中部碎片已经被挖出来，然后不知所踪了！"
D.Strings[38237]="要是你想休息，我能为你提供免费床位。虽然不怎么舒服，不过你也不像是个会花很多时间睡觉的人。"
D.Strings[38238]="在我从丹奥加兹赶来的路上，我看见一只豺狼人正在湖心捕猎蛇颈龙。要是你从没见过狗使长矛的滑稽样，那你可有眼福了！"
D.Strings[38239]="他们说迅猛龙女王就住在恐龙岭深处，守着她那些龙蛋。"
D.Strings[38240]="几天前我正在维尔加那儿……从迅猛龙尸骨堆里搜寻……泰坦圣物，然后我看见他了！萨尔图斯还活着！\n\n好吧，他本来就是亡灵，说活着好像不太恰当，但反正他还在。萨尔图斯还在！"
D.Strings[38241]="龙喉部族正在试图把势力扩大到怒牙营地以外的地方，并已对东边的车队发起了突袭。他们找来了两位强大的战士领军。要是你愿意接受挑战的话，你也许能在营地找到他们——那群正在策划密谋和从事其它邪恶活动的兽人。"
D.Strings[38242]="岩幔国王，裂地之斧回到你手里了吗？"
D.Strings[38243]="是的。用它的时候要更加小心些。"
D.Strings[38244]="我这里没有你要学的东西。去找$c训练师吧。"
D.Strings[38245]="你是来接受训练的吗，猎人？"
D.Strings[38246]="Lok'tar！我们需要你的帮助！"
D.Strings[38247]="有了你们强大力量的支持，鱼人们，我们的计划必将取得成功。我们的狗头人朋友们会给我们挖出许多许多的矿石……"
D.Strings[38248]="并且，装备上出自豺狼人之手、由无坚不摧黄铜所铸造的武器，你们这些鱼人定将势不可挡！"
D.Strings[38249]="那是什么？那见鬼的味道又是什么？"
D.Strings[38250]="……你干嘛那样看着我？"
D.Strings[38251]="你会后悔的！这是你唯一的机会，你这呆鱼！"
D.Strings[38252]="噶啊啊啊——！诅咒你突然的背叛！诅咒你必然的背叛！"
D.Strings[38253]="呃——！快跑！"
D.Strings[38254]="*嗅一嗅*"
D.Strings[38255]="考古学探究的是事实，而非真理。"
D.Strings[38256]="如果你对真理感兴趣，卡迪·诺德林格主讲的哲学班就在大厅的另一端。"
D.Strings[38257]="快忘了你那些关于失落的城市、奇妙的旅行以及把世界挖个底朝天的想法吧。"
D.Strings[38258]="你不能凭借地图来发掘那些深埋于地下的财宝，而且“X”永远、从来都不代表正确的位置。"
D.Strings[38259]="考古学有70%%是在图书馆里完成的。要研究。要阅读。"
D.Strings[38260]="我们不能把神话与票面价值划等号。"
D.Strings[38261]="呃哼！嗯……啊，下一周——“塔纳利斯”。从玛尔冯·瑞文斯克在公元22年挖出破碎石柱的事情讲起。"
D.Strings[38262]="我将在接下来的一个半小时里留在这儿做研究，要是谁有问题可以来找我。"
D.Strings[38263]="%s对着哈里森·琼斯眨着睫毛。"
D.Strings[38264]="拉葛雷克，你能再给我一块调和过的禁锢符文石吗？"
D.Strings[38265]="尽量……别丢了……那个。"
D.Strings[38266]="你是来这儿学习考古的吗？"
D.Strings[38267]="我喜欢这些小精灵！真是太可爱了！"
D.Strings[38268]="安静点，伊莎娜。你的噪音快把我们吵死了。"
D.Strings[38269]="入侵者已经攻破了圣殿大厅！"
D.Strings[38270]="快醒醒你这傻瓜！我们被攻击了！"
D.Strings[38271]="欢迎来到守望堡，$c。你可以叫我“妈妈”，我会好好照顾你。"
D.Strings[38272]="高阶地占师，我已为仪式做好了准备。"
D.Strings[38273]="死亡，令我们重生。"
D.Strings[38274]="艾比希昂正在施放威力强大的暗影新星，快躲起来！"
D.Strings[38275]="只要杀了艾比希昂，就能拿到第一块世界之柱碎片！"
D.Strings[38276]="艾比希昂被困住了！保持移动以躲避他的攻击！"
D.Strings[38277]="我们认识吗？不要紧。我会压碎你的骨头！"
D.Strings[38278]="不——！别再来了！"
D.Strings[38279]="你必须待在塔伦迪斯营地攻击区域内！"
D.Strings[38280]="拜托！把其他人也放出来！"
D.Strings[38281]="一旦我们重获自由，我们将与你一同飞过格瑞姆巴托！"
D.Strings[38282]="变异地精的触角掉了下来，在地上滚动！"
D.Strings[38283]="你得去找别的训练师，$c。我帮不了你。"
D.Strings[38284]="需要接受训练可随时回来找我。"
D.Strings[38285]="在我的坚守下，佐拉姆加一定会成为御敌入侵的新壁垒。$B$B为了部落的荣耀！"
D.Strings[38286]="真荣幸能有你这样的英雄与我们同在，$n。"
D.Strings[38287]="不，不，不……你毁了我的家庭，但你别想夺走我的土地！"
D.Strings[38288]="快回来，$r！"
D.Strings[38289]="你能不能别来骚扰我们？"
D.Strings[38290]="滚出我的厨房！"
D.Strings[38291]="我想我真是太好命了，$n。以被遗忘者和皇家药剂师协会成员的身份重回这个世界……我的命可真是好得无可挑剔。"
D.Strings[38292]="放……我……走……"
D.Strings[38293]="你只是……在拖延……你的死期……"
D.Strings[38294]="你……将……燃尽……"
D.Strings[38295]="混乱……"
D.Strings[38296]="别白费……力气了……"
D.Strings[38297]="德鲁伊和哨兵们喜欢各干各的，但我们的合作总是很默契。$B$B各自为政并不代表合不来。"
D.Strings[38298]="真是座美丽的城市，对吧？这里当时叫做吉尔尼斯。$B$B但这都已经过去了，总有一天，我们也将成为历史。只有大地与她的秘密会永远留存。$B$B你是否愿意探究呢，$n？"
D.Strings[38299]="那才叫做吸引力！我希望我们所有的药水都能产生那样的效果！"
D.Strings[38300]="爬上哨塔！"
D.Strings[38301]="用被诅咒的矿石来引导炮火的攻击！"
D.Strings[38302]="与外部冲突相比，激怒这里的野猪人太危险了，$r。我不可能永远把他们挡在外面。$B$B我们必须终止他们侵害自然的行为。"
D.Strings[38303]="看来你带来了整支舰队啊，$n！还找来一群愤怒的急浪成员！$b$b但愿你已经做好了战斗的准备，因为这些家伙可不是吃素的。"
D.Strings[38304]="我已经老了！他们人数太多了！$b$b<舰队指挥官卡拉·海角停下来喘了口气。>$b$b我在说什么？他们人数太少了！去死吧，你们这群下贱的杂种！"
D.Strings[38305]="啊啊啊啊——噢噢噢噢！啊啊啊啊——噢噢噢噢！海盗即吾命。"
D.Strings[38306]="我们抢劫，我们掠夺，我们无恶不作，干杯吧水手们——噢噢噢！"
D.Strings[38307]="我们借着月光去劫掠，去破坏，去席卷，干杯吧水手们，啊啊啊啊——噢噢噢！"
D.Strings[38308]="!我们是主宰，我们是玩客，我们来自吉尔尼斯，干杯吧水手们，啊啊啊啊——噢噢噢！"
D.Strings[38309]="我们要夺下藏宝海湾，否则菲尔拉伦会要我们好看，怒吼吧，水手们，啊啊啊啊——噢噢噢！"
D.Strings[38310]="我们肮脏，我们邋遢，我们是狼人，干杯吧水手们，啊啊啊啊——噢噢噢！"
D.Strings[38311]="我们发现他们标记他们撕碎他们咀嚼他们，大声唱吧水手们，啊啊啊啊——噢噢噢！"
D.Strings[38312]="什么？当然不是！这么简单的装置根本困不住我，可我没时间。看见没，就在不久前我还在一只猛兽的肚子里住了好几个月……"
D.Strings[38313]="根据我的回忆，你被困住了。这情形相似得不可思议。"
D.Strings[38314]="这并非出于完全自愿，可我有个令人难以置信的大发现。这野兽看来能消化一切，而且从不会产生不良反应。"
D.Strings[38315]="比如说，身穿熔岩装的侏儒。"
D.Strings[38316]="作为复仇计划的最后一步，迦顿男爵把你变成了一枚活动炸弹！离你的同伴远一点儿！"
D.Strings[38317]="那个俾格米头盔应该能蒙住他们，至少能拖住一阵子。快回城！"
D.Strings[38318]="没错。我拿粘在我衣服上的残留消化液做了几个实验……\n\n<芬克跑题了>\n\n我说，你没见过我那把剥皮刀吧？我不知道放哪儿了。"
D.Strings[38319]="不。我，呃，我没看见。你刚才说什么？"
D.Strings[38320]="哦是的，胆汁——真是种奇妙的物质。只要加上适当的催化剂，就能把与其接触到的任何物质变为不朽的存在*。我已经用我最可靠的胆汁喷洒机800采集到了这种物质，而且这次肯定取得了比例正确的混合物。现在缺少的只是几个志愿者，帮我找个合适的生物进行实验。你觉得怎么样，朋友？\n\n*请注意“不朽”也是有局限的。"
D.Strings[38321]="走开。我没能力也没兴趣教你什么。"
D.Strings[38322]="我会教你学会运用令敌人无可抵挡的力量。"
D.Strings[38323]="局限？什么局限？"
D.Strings[38324]="这太可怕了，杜莱克！萨鲁法尔根本不会理你的！我们该怎么办？！"
D.Strings[38325]="你说萨鲁法尔也牵涉其中了？"
D.Strings[38326]="嗯，那就只剩下一件事可干了……"
D.Strings[38327]="他们在不断地冲过来！把他们击退！我们必须尽力救出更多的吉尔尼斯人！"
D.Strings[38328]="这一切来得比我预想中要早。"
D.Strings[38329]="我需要一匹马，去救克雷南。"
D.Strings[38330]="$n，恐怕你已经没什么用处了……"
D.Strings[38331]="哎呀！那控制杆激活了胆汁喷洒机。喔，要是你刚好能找到一把钥匙的话……"
D.Strings[38332]="不给糖就捣蛋！"
D.Strings[38333]="总共有两个：一个是贸易区的交易者大厅，另一个是矮人区的暴风城拍卖行。"
D.Strings[38334]="这才是部落人该有的精神！"
D.Strings[38335]="又一个勇敢者！我对这个很有信心……"
D.Strings[38336]="这些当中一定有一个能通过！"
D.Strings[38337]="矮人区拍卖行"
D.Strings[38338]="胆汁喷洒机恢复运作，并开始喷射一种恶臭的物质。"
D.Strings[38339]="你能在矮人区的最北边，城北降落点的附近找到那间拍卖行。"
D.Strings[38340]="暴风城共有两个银行——分别是位于贸易区的暴风城会计室和位于矮人区的暴风城皇家银行。"
D.Strings[38341]="贸易区银行"
D.Strings[38342]="矮人区银行"
D.Strings[38343]="暴风城皇家银行位于矮人区最北边的角落里，城北降落点区域内。"
D.Strings[38344]="%s鼾声震天。"
D.Strings[38345]="%s一边哼哼着一边睁开了一只眼。"
D.Strings[38346]="贸易区旅店"
D.Strings[38347]="矮人区旅店"
D.Strings[38348]="黄金酒桶旅店位于矮人区的北部，就在喷泉旁边。"
D.Strings[38349]="邮箱在城中随处可见。你在任何一间拍卖行、银行以及旅店门外都能找到。"
D.Strings[38350]="暴风城有许多特色景点，从矿道地铁到暴风要塞。$B$B你想去哪里呢？"
D.Strings[38351]="在旧城区与矮人区都能找到兽栏管理员。"
D.Strings[38352]="矮人区兽栏管理员"
D.Strings[38353]="旧城区兽栏管理员"
D.Strings[38354]="卡琳就在暴风城的最东边，穿过旧城区后部的门就能找到她。"
D.Strings[38355]="商贩"
D.Strings[38356]="纳迦女祭司们仿佛在召唤无穷无尽的援军！"
D.Strings[38357]="突袭似乎毫无效果。他们又稳住阵脚了！"
D.Strings[38358]="他们人数太多了……面对我们的袭击几乎毫发无损。而我们已经损失惨重！必须得想个办法……"
D.Strings[38359]="把这些畜生打回地狱！"
D.Strings[38360]="一波接一波！坚守阵地！"
D.Strings[38361]="击退他们！为了吉尔尼斯！"
D.Strings[38362]="尽全力死守你们的阵地！"
D.Strings[38363]="上天啰！"
D.Strings[38364]="我们遭到攻击了！"
D.Strings[38365]="纳迦不会就此罢休。我们得集结盟友的力量，把他们彻底击退！"
D.Strings[38366]="我去找埃鲁纳克……必要的话我只能自己去！"
D.Strings[38367]="雷塔维在过去的近四十年里一直都是考古界的英雄。要是他还记得它们，哦，他要讲的那些故事……"
D.Strings[38368]="嗯，我想我应该跟他进去。$b$b再没有比在这时候去面对地狱咆哮更坏的事情了……"
D.Strings[38369]="在旧城区指挥部与矮人区里都能找到猎人训练师。"
D.Strings[38370]="矮人区猎人训练师"
D.Strings[38371]="旧城区猎人训练师"
D.Strings[38372]="你在旧城区的东门外总能看到几位猎人。"
D.Strings[38373]="雄狮之眠"
D.Strings[38374]="雄狮之眠是一片反省与缅怀之地，是纪念那些为我们而牺牲的英雄们的宁静公园。"
D.Strings[38375]="暴风要塞"
D.Strings[38376]="要塞位于暴风城北部。$B$B沿着运河向北前行，你就会看到一座吊桥……通往要塞庭院。"
D.Strings[38377]="监狱"
D.Strings[38378]="监狱？你干吗要去那儿？就在城中央，法师区的东北部。$B$B你要是真去可一定要小心。听说最近发生了不少暴动事件。"
D.Strings[38379]="车队没有防护——我回来了！"
D.Strings[38380]="近来我们不断收到在艾泽拉斯各地出现元素扰动的报告。消息表明这并不完全是自然现象，但我们还没能追溯到源头。尽管已经有一些猜测，可现在下定论还为时过早。$B$B提高警惕，在冒险途中留心任何可疑的元素活动。要是你找到任何有价值的信息，请及时告知大地之环使者。你在任何主城都能与我们取得联系。$B$B睁大双眼。危机在临近。"
D.Strings[38381]="随着时间的推移，艾泽拉斯的元素变得越发躁动。平息这躁动的关键就在此地——纳格兰。当德拉诺分崩离析之时，所有元素位面都陷入了极大的混乱之中，再也没有恢复平静。这里的裂隙是自然形成的，也彰显着大地所遭受的重创。$B$B在艾泽拉斯看到像这样的崩裂之景并不仅会让人心神不宁，还可能预示着一场前所未见的大毁灭将降临在这个世界上。$B$B$n，把你在外域找到的任何有用信息都带回来给我。$B$B我必须花些时间来解决这里的元素问题，想办法让艾泽拉斯的元素再次平静下来……再晚就来不及了。"
D.Strings[38382]="我们在设法让艾泽拉斯日渐躁动的元素重归平静。这里——在纳格兰，我们看到了同样的裂隙正在形成，但这些是作为德拉诺破碎的直接后果而出现的。它们是星球日渐衰弱和元素位面产生巨变的标志。$B$B但是，在艾泽拉斯，却找不到令人信服的解释。$B$B当你在外域冒险时，要是你能找到任何与这些裂隙相关的信息，记得来告知我们。我们将继续在此与元素对话，争取找到能使艾泽拉斯元素平静下来的办法……再晚就来不及了。"
D.Strings[38383]="位于贸易区与运河间的登曼家族珠宝，你在那里应该可以找到所有想要找的东西。"
D.Strings[38384]="除了外出实地考察外，哈里森·琼斯平时都在暴风要塞的皇家图书馆里教授考古学。"
D.Strings[38385]="专业技能供应商总是待在对应的专业技能训练师附近。其它商贩则遍布暴风城的各个角落。$B$B你要买什么？"
D.Strings[38386]="勇士大厅"
D.Strings[38387]="勇士大厅位于旧城区的东南端。$B$B荣誉与战利品军需官就在那里。"
D.Strings[38388]="英雄及勇气军需官"
D.Strings[38389]="军需官就在位于旧城区东南门外的指挥部里。"
D.Strings[38390]="荣誉与战利品军需官"
D.Strings[38391]="养马人"
D.Strings[38392]="马厩就在旧城区东南门边上。你在那里能找到骑术训练师与养马人。"
D.Strings[38393]="要是我能到得了发射台，再给我一架那种美轮美奂的飞机——只需一架，我就能夺回诺莫瑞根，并把“坏脾气”巴拉克斯的眼镜给吓得掉下来！$B$B如果你还需要降落伞的话，我们在降落点附近的箱子里存了一些。"
D.Strings[38394]="你知道贸易区那边的狮鹫栖息地吗，就是飞行管理员所在的地方？$B$B有几个蛮锤矮人正在那儿饲养和贩售狮鹫，他们还能教你学会骑乘这种坐骑。"
D.Strings[38395]="我们甘愿效忠女妖之王。"
D.Strings[38396]="骑术"
D.Strings[38397]="飞行"
D.Strings[38398]="你就过来吧。"
D.Strings[38399]="你看上去累极了。出了什么事？"
D.Strings[38400]="你取回最后一块了吗？"
D.Strings[38401]="找到塞拉赞恩了吗？"
D.Strings[38402]="你看上去很不安。有什么需要我帮忙的吗？"
D.Strings[38403]="需要我帮忙吗？"
D.Strings[38404]="我想我恐怕得稍微休息一会儿。我可真没用。"
D.Strings[38405]="我们正在赶往洛苏娜之门的突袭前线。正好需要你的帮助。"
D.Strings[38406]="我这就动身。"
D.Strings[38407]="收到。我这就去。"
D.Strings[38408]="元素与我们同在。"
D.Strings[38409]="有活儿干了。真好。"
D.Strings[38410]="我真高兴这次竟然能和石母并肩作战。"
D.Strings[38411]="那营地一直在试图得到我们的关注。我们去解决这件事。"
D.Strings[38412]="这正是我想要听到的。出发吧。"
D.Strings[38413]="明白。我这就去。"
D.Strings[38414]="让太阳温暖的祝福像暖流一般流遍你的全身！"
D.Strings[38415]="别让他们接近碎片！"
D.Strings[38416]="杀掉他们！把他们全都杀死！"
D.Strings[38417]="碾碎他们！我去把碎片送到石母手里。"
D.Strings[38418]="我们控制世界之柱！"
D.Strings[38419]="别去管暮光之锤渣滓！他们都是蠢货。去杀那边那个，赶快！"
D.Strings[38420]="你休想从我手里夺走世界之柱的碎片！"
D.Strings[38421]="塞拉赞恩一定会很高兴取得中部碎片的。"
D.Strings[38422]="干掉它们！我们得尽快加入大地神殿的战斗！"
D.Strings[38423]="那个长着食人魔脑袋的小丑来了吗？"
D.Strings[38424]="啊，说到就到了……"
D.Strings[38425]="事情最好足够重要，希尔瓦娜斯。你知道我有多讨厌这鬼地方和这里的恶臭。你找我来想要干什么？"
D.Strings[38426]="更重要的是，那些天灾恶魔在这儿干什么？"
D.Strings[38427]="酋长，你终于来了。"
D.Strings[38428]="巫妖王倒下之后，许多更为难缠的天灾军团士兵都变成了……散兵游勇。这些“恶魔”——真是个雅致的称呼——叫做瓦格里。他们现在听从我的命令……"
D.Strings[38429]="……而她们就是我要求见你的部分理由。"
D.Strings[38430]="有话快说，希尔瓦娜斯。"
D.Strings[38431]="遵命，酋长。我解决了被遗忘者一直以来的困境！"
D.Strings[38432]="作为一个种族，我们被遗忘者没有繁衍后代的能力。"
D.Strings[38433]="但是，现在有了瓦格里的帮助，我们能够将新的生命赋予那些倒下的人类。"
D.Strings[38434]="阿加莎，让酋长看看！"
D.Strings[38435]="这太扭曲了！"
D.Strings[38436]="你在此所做的一切，希尔瓦娜斯……违背了自然的规律。恶心是我唯一能用来形容它的词。"
D.Strings[38437]="酋长，没有新的被遗忘者，我的子民将会灭绝……我们对吉尔尼斯和北洛丹伦的统治也将瓦解。"
D.Strings[38438]="你考虑过这意味着什么吗，希尔瓦娜斯？"
D.Strings[38439]="现在的你，和巫妖王又有什么分别？"
D.Strings[38440]="答案还不明显吗，酋长？我为部落效忠。"
D.Strings[38441]="小心你的伶牙俐齿，贱人。"
D.Strings[38442]="克鲁姆什，你留下来“守卫”女妖之王，确保她受到“彻底”的保护。下次见面时我希望看到一份完整的报告。"
D.Strings[38443]="记住，希尔瓦娜斯，终有一天，我们都将站在造物主面前接受审判。你的审判日也许比别人来得更早……"
D.Strings[38444]="动作快，$n。要是莫格莱尼在你完成前注意到我们，一切努力就白费了。"
D.Strings[38445]="暮光之锤已经渗入了我的城市。如果没人去制止他们，城市就将彻底覆灭。在围剿他们位于高地的据点前，我必须确认暴风城不会成为他们阴谋的牺牲品。$B$B我需要在城里安插更多脚踏实地、忠心不二的耳目。像你这样经验丰富的$c，作用是无可估量的。你准备好帮助暴风城了吗？"
D.Strings[38446]="我的名字不叫弗朗科！"
D.Strings[38447]="左转！"
D.Strings[38448]="小心那只龟！"
D.Strings[38449]="我要来一份铁板奇美拉肉排，双倍调料！"
D.Strings[38450]="别再叫我弗朗科了！"
D.Strings[38451]="俯冲！俯冲！俯冲！"
D.Strings[38452]="战栗吧，十字军，在被遗忘者的力量面前战栗吧！"
D.Strings[38453]="血肉撕裂者们，为我们的勇士们守好前庭！"
D.Strings[38454]="血色修道院现在的主人是被遗忘者！"
D.Strings[38455]="看着自己的人死在夙敌手上，这感觉怎么样啊，检察官？"
D.Strings[38456]="欢迎来到暴风城，$c。"
D.Strings[38457]="<安度因上下打量了你>$B$B$n，对吧？你的一些英勇事迹已经被广为传诵。$B$B在诺森德奋战的感觉还好吗？你见到世界之树了吗？那些关于瓦丝琪尔的传闻是真的吗？我有太多问题要问了！"
D.Strings[38458]="请跟我来，殿下。"
D.Strings[38459]="你能预料到吗，傻瓜？"
D.Strings[38460]="我一直想知道当个德鲁伊是什么感觉。当你变熊时你的衣服去哪儿了呢？"
D.Strings[38461]="这么说你是个猎人？我父亲教会了我怎样和弓打交道。"
D.Strings[38462]="你和吉安娜·普罗德摩尔一样，是个法师？你研习奥术有多久了？那玩意儿看起来可挺难学的。"
D.Strings[38463]="你是个圣骑士？大领主弗塔根曾经也是。他教过我不少东西。我……我还是很想念他。"
D.Strings[38464]="我本人正在被受训成为一名牧师。希望有一天我也能变得和你一样强大。"
D.Strings[38465]="这可太棒了，我还从没和暴风城里的潜行者交谈过。他们总是那么的安静和神秘……"
D.Strings[38466]="当萨满祭司是什么感觉？我和萨尔有过一面之缘。我父亲不太信任他，但他看起来还是相当睿智的。"
D.Strings[38467]="成为一名出色的术士想必很难。你有没有担心过，要是你的恶魔失控了怎么办？"
D.Strings[38468]="你是我所见过的长相最凶狠的战士之一，$n！"
D.Strings[38469]="$n，我记得你第一次来见我父亲，是在黑锋要塞战役结束之后。真高兴你仍与我们同在。"
D.Strings[38470]="嗨，小可爱！介意帮我涂点儿防晒霜吗？"
D.Strings[38471]="亵渎者！恶棍！魔鬼！离开这座神殿！"
D.Strings[38472]="我送你去见你的神明。"
D.Strings[38473]="你的生命将成为我的祭品。"
D.Strings[38474]="炽热之光……请接纳我。"
D.Strings[38475]="你能感受到太阳温暖的祝福吗……？"
D.Strings[38476]="无法控制的事物令你恐惧，但你能控制你的恐惧吗？"
D.Strings[38477]="你现在醒悟了吗？"
D.Strings[38478]="是的！驾驭……你的……仇恨。"
D.Strings[38479]="看啊！无尽的黑暗降临到你们的世界了！"
D.Strings[38480]="你的生命能量将使这座殿堂更加辉煌！"
D.Strings[38481]="枯萎凋亡！"
D.Strings[38482]="生命能量的浪费。"
D.Strings[38483]="轮回仍将继续……"
D.Strings[38484]="释放你的生命吧！"
D.Strings[38485]="直视这片星空！你看到了什么？"
D.Strings[38486]="你的生命光辉，就快熄灭了。"
D.Strings[38487]="微不足道！"
D.Strings[38488]="永世的黑暗……因你而降临。"
D.Strings[38489]="我的光辉……黯淡了。"
D.Strings[38490]="沐浴我的光辉吧！"
D.Strings[38491]="虫群又有腐肉吃了……"
D.Strings[38492]="塔赫……不复存在了……"
D.Strings[38493]="大地，颤抖吧！"
D.Strings[38494]="退回去，入侵者！这里的殿堂绝不允许亵渎！"
D.Strings[38495]="这一切都是因为你的傲慢。"
D.Strings[38496]="你都……干了些……什么？"
D.Strings[38497]="光之信标啊，将你的庇护赐予我！"
D.Strings[38498]="我不会为此后悔。"
D.Strings[38499]="我相信你和我儿子相处得不错？安度因唯一不具备的特质就是内向。"
D.Strings[38500]="终点站——被遗忘者先锋军到了！所有人都下去！"
D.Strings[38501]="等守住了暴风城，就该轮到我们把战火烧到暮光高地了！"
D.Strings[38502]="这是单程旅行，孩子，而且你一定不会想要乘坐另一辆车回来。"
D.Strings[38503]="离开这里，异教徒！这里不欢迎你们！"
D.Strings[38504]="愿你终获安宁。"
D.Strings[38505]="天堂才是你的归宿！"
D.Strings[38506]="在我面前下跪忏悔吧！"
D.Strings[38507]="都上来！下一站——瑟伯切尔。"
D.Strings[38508]="全体登车！最后一站——被遗忘者先锋军！"
D.Strings[38509]="把握机会吧，凡人。奥库鲁斯永远都不会被打败！"
D.Strings[38510]="如此傲慢……如此无礼……"
D.Strings[38511]="我们掌控时间的进退流返！永恒之龙是不可战胜的！"
D.Strings[38512]="我曾经的弟兄们，你们没有时间了！加入我们吧，趁还没有迷失在永恒之沙里！"
D.Strings[38513]="时间之沙能算出你离死亡还有多远！"
D.Strings[38514]="诺兹多姆的子嗣们，听我说！时间的层面无穷无尽，我们的兵力无法计数！你无法、也不可能击败我们所有人！"
D.Strings[38515]="邪教徒来了！安息之厅需要帮手！"
D.Strings[38516]="多亏你的帮忙，$n，阿基尔达拉神像又回到了我们手中！快过来，让我带你承着她的祝福，前往辛萨罗深处！"
D.Strings[38517]="辛特兰的鹰之魂已与我们同在，$n。$B$B有了从邪枝那里取回的神像，我就能直接把你传送到辛萨罗的上层。直击他们的要害！"
D.Strings[38518]="嗨。欢迎光临我的美发沙龙。$B$B你看起来容光焕发！但如果你想换个造型的话，就随便找把椅子坐下来好了。"
D.Strings[38519]="沙普比克是鹰巢山最出色的狮鹫。它会把你直接送到辛萨罗顶部，我们就能以迅雷不及掩耳之势直取顶层平台。"
D.Strings[38520]="我们必须夺回属于我们的东西。我们的生死存亡在此一举。"
D.Strings[38521]="我需要前往辛萨罗顶部。该沙普比克出场了！"
D.Strings[38522]="靠近点儿，安娜斯塔西娅。我们一起找点儿乐子。"
D.Strings[38523]="威廉和冬娜过会儿会成为你的玩伴。这听起来如何？"
D.Strings[38524]="我前几天遇见小提米了，安娜。你想要养只小猫吗？"
D.Strings[38525]="等湖面一冻上，我们就去溜冰，宝贝儿。"
D.Strings[38526]="血色十字军将荣返故里！"
D.Strings[38527]="我们准备帮小安蒂编辫子了。你要编吗，宝贝儿？"
D.Strings[38528]="安娜，再给你10分钟，然后快点洗漱。我们为你准备了你最爱吃的——通心面与奶酪。"
D.Strings[38529]="安娜，想不想去港口玩会儿？"
D.Strings[38530]="我明天要去帮国王陛下理发。你愿意来见见他吗，安娜？"
D.Strings[38531]="我知道情势非常严峻，但我们的敌人一定会为他们的恶行付出代价。我保证。"
D.Strings[38532]="如果连像我这样的人都会被那呆子抓住，那你必须得是个绝对的勇士才能来此冒险。\n\n要是你能转移哈尔弗斯的注意力，帮我挣脱锁链，我就能与你并肩作战。\n\n我能使指定区域内的时间流驶速度变慢，从而使原龙巨兽的火球弹幕无法命中你。"
D.Strings[38533]="狮鹫管理员塔隆艾克斯派我前往风暴之羽哨站！"
D.Strings[38534]="真棒！"
D.Strings[38535]="酷。"
D.Strings[38536]="呀，天哪……呜！"
D.Strings[38537]="喔呀，啊哈。"
D.Strings[38538]="好。"
D.Strings[38539]="不该你说话时别多嘴。"
D.Strings[38540]="够了……准备开始！"
D.Strings[38541]="我们赢了！这儿有点奖品，谢谢。"
D.Strings[38542]="谢谢。那家伙可真难缠！"
D.Strings[38543]="那家伙简直神出鬼没！"
D.Strings[38544]="狼人渣滓！我要朝你的尸体吐口水！"
D.Strings[38545]="想夺走我们的土地，没那么容易！"
D.Strings[38546]="我们在设法弄清真主之门那里究竟有什么重要的事情在发生。$B$B但我可以确保，那些暮光之锤败类一定不会干什么好事。太反常了！我们一路追随线索而来，现在却连靠近都做不到。"
D.Strings[38547]="我是天穹之主，谁胆敢威胁我的孩子，就必须付出代价。"
D.Strings[38548]="干得好，$n！雷霆崖欠你一份人情。"
D.Strings[38549]="干得好，$n！奥格瑞玛欠你一份人情。"
D.Strings[38550]="干得好，$n！铁炉堡欠你一份人情。"
D.Strings[38551]="向你致敬，$n，真正的勇士，雷霆崖的守护者！每个人都该永远铭记$n的英勇事迹！"
D.Strings[38552]="Lok'tar！所有人都不该忘却这个名字——$n，奥格瑞玛真正的勇者！向你致敬，$n！"
D.Strings[38553]="向你致敬，$n，真正的勇士，铁炉堡的守护者！每个人都该永远铭记$n的英勇事迹！"
D.Strings[38554]="谢谢你……真希望我能帮你找到铸炉之主。"
D.Strings[38555]="铸炉之主是个杀人狂魔。你确定想要去找他吗？"
D.Strings[38556]="啊，是的……我知道铸炉之主！我刚才不小心听说他现在不在里边。"
D.Strings[38557]="铸炉之主正在和暮光官员会面。相信我，这是我用变质面包换来的小道消息！"
D.Strings[38558]="我不认识什么铸炉之主。快告诉我你是从什么安全的地方来的？"
D.Strings[38559]="我听说铸炉之主把会面纪要夹在一本书中，藏在一座可俯瞰营地的塔里。"
D.Strings[38560]="请叫我孪生姐妹。莫维就是这么称呼我的。$B$B不，我们长的不像。你瞎了吗？看在圣光的份上——她可是个侏儒！不过我们行事方式很像。尤其是在打架的时候。$B$B至于我的名字……你听说过鼎鼎大名的蛮锤布鲁尔家族吗？想不想来杯佳酿？"
D.Strings[38561]="像月光一样灼热！"
D.Strings[38562]="快停下！"
D.Strings[38563]="跃起！"
D.Strings[38564]="飞扑！"
D.Strings[38565]="回到这儿来，伙计！"
D.Strings[38566]="赞吉吉来也！"
D.Strings[38567]="暮光之锤极有可能在真主之门那里有了什么新发现。$B$B也许像你这么$g能干的:可爱的;$c刚好能帮帮我？"
D.Strings[38568]="也许我可爱的同伴已经告诉你了，我们正在追寻某样神秘而强大的物品。现在所有的线索都指向真主之门。$B$B不幸的是，那些叫做暮光之锤的狂热邪教徒却阻止我们搜寻那片区域。我相信像你这样声名远播的$c一定能帮神圣遗物学会解决这个小问题吧？"
D.Strings[38569]="我来对付他！"
D.Strings[38570]="我打到他了吗？"
D.Strings[38571]="啊呜！"
D.Strings[38572]="乱锤掌！扫堂爪！裂伤牙！"
D.Strings[38573]="赞吉吉掌控一切！"
D.Strings[38574]="到这儿来，你这懦夫！"
D.Strings[38575]="喂，打我呀！这边，伙计！"
D.Strings[38576]="我来对付这家伙！"
D.Strings[38577]="变形！月火术出场！"
D.Strings[38578]="变形！接受月火术的试炼吧！"
D.Strings[38579]="变形！接招，伙计！"
D.Strings[38580]="变形！赞吉吉准备猛扑！"
D.Strings[38581]="变形！变个猫玩玩儿！"
D.Strings[38582]="变形！尝尝我爪子的厉害！"
D.Strings[38583]="变形！赞吉吉吸收伤害！"
D.Strings[38584]="变形！该熊登场了！"
D.Strings[38585]="变形！这边，这边！"
D.Strings[38586]="变形！呃哦……等一下……"
D.Strings[38587]="变形！哦不！不会吧……"
D.Strings[38588]="变形！现在试着游走，伙计！"
D.Strings[38589]="过来帮个忙……"
D.Strings[38590]="我好像……卡住了……"
D.Strings[38591]="赞吉吉由衷地感到抱歉。"
D.Strings[38592]="这可不对。"
D.Strings[38593]="有人能来帮帮赞吉吉吗？"
D.Strings[38594]="你们怎么都是头朝下？"
D.Strings[38595]="严刑审讯一个畏缩的码头工人。"
D.Strings[38596]="我能帮你调查暮光之锤吗？我们不必告诉我父亲……"
D.Strings[38597]="你来了，$n！我还以为你已经忘了我了。"
D.Strings[38598]="用凋零化合药剂消灭所有鱼人！$B$B|r|TInterface\\Icons\\INV_ALCHEMY_POTION_05.BLP:24|t"
D.Strings[38599]="返回被遗忘者统帅部！$B$B|r|TInterface\\Icons\\ACHIEVEMENT_ZONE_SILVERPINE_01.BLP:24|t"
D.Strings[38600]="你想要什么？你没看到我还有蝙蝠粪便要清理吗？"
D.Strings[38601]="我要把一只蝙蝠带到黎明岛去。"
D.Strings[38602]="你最好把那只蝙蝠毫发无伤地带来，$n！"
D.Strings[38603]="洛苏娜正在准备施放一个强大的法术——快躲好！"
D.Strings[38604]="暮光之锤？我什么都不知道！你干吗问我？"
D.Strings[38605]="我对教派一无所知！快放我回去工作吧……"
D.Strings[38606]="暮——暮——暮光之——之锤？离我远点！"
D.Strings[38607]="什么？那个疯狂的世界末日教派？要是我听说了什么，我会第一个告诉你的！"
D.Strings[38608]="你要问我什么？我是个只会干活的傻瓜！"
D.Strings[38609]="我发誓在我找到他的时候他已经死了！什么——喔——暮光之锤？不，我什么也不知道。"
D.Strings[38610]="我什么也没听说。我发誓！"
D.Strings[38611]="我是无辜的！无辜的听到没有！大灾变不是我的错！"
D.Strings[38612]="这里不欢迎你，亚门纳尔。"
D.Strings[38613]="|TInterface\\Icons\\spell_nature_earthquake.blp:20|t%s开始施放|cFFFF0000|Hspell:83445|h[震荡波]！|h|r"
D.Strings[38614]="是什么把你带到这片受诅咒的土地上来的？"
D.Strings[38615]="暮光之锤挖出了泰坦界门，而且似乎正在试图激活它。"
D.Strings[38616]="巫妖王既死，我所拥有的就只剩下责任。没有家人，没有朋友……只有这个。$b$b战争。"
D.Strings[38617]="嗯……这儿没有有用的信息。"
D.Strings[38618]="你可真擅长和人打交道啊，$n。人们惧怕你，却又尊敬你。"
D.Strings[38619]="你不觉得这是在浪费时间吗？这些工人一无所知！"
D.Strings[38620]="更多加兹瑞迪安？你为什么觉得我还愿意要更多这玩意？我已经积压了九千个了，一个都卖不出去！我竟然以为有人会对这种超大块头的毒蛇雕像感兴趣！啊呸！"
D.Strings[38621]="我看见废土强盗和他们的领袖——卡利夫·斯科比斯汀往南边去了。多加小心，他们看起来更强大了！"
D.Strings[38622]="我见到一只你前所未见的大虫子，就在那其中一个——要不就是两个异种蝎虫巢附近徘徊。我想我快要中暑了……你看见那边那只沙猫没？"
D.Strings[38623]="我对龙没什么研究，可有一天，突然有一只又大又可怕的龙出现在那边——就在时光之穴入口附近。他不停的叫嚷着……说什么来着……我们所知的时间尽头？我还真没怎么注意听。"
D.Strings[38624]="我一位名叫Frokle的老友原本是要前往加基森，可他和船上的所有锈水船员却从来都没有抵达。我听说在遥远的南边，有一伙疯狂的地精潜伏在一架被击落的飞行器附近，会不会是……？"
D.Strings[38625]="我在沙丘那边分析森提帕尔异种蝎小吃（专利申请中）的潜在利润时，发现了一辆破旧的货车。于是我想，“嘿，免费货车哎！”后来就出现了那只你前所未见的大蜥蜴，害得我只能空手而逃！"
D.Strings[38626]="你见过那些会在沙丘地下窜来窜去的大土堆吗？它们是隧道虫的一种，艾泽拉斯大陆上可从来没出现过这玩意儿！要是能和它们斗上一场，对向你这样经验丰富的冒险家来说，一定是次难得的学习机会。"
D.Strings[38627]="大灾变发生时，艾泽拉斯元素间的连结大大弱化了。其中一个元素——亚奎门塔斯，获得了自由。我听说他正在给南海海盗制造不小的麻烦！"
D.Strings[38628]="你经常替人找东西吗？我以为英雄的时间总是很宝贵呢。"
D.Strings[38629]="我们所有的炸药都不见了？！$n，这里一定正在酝酿着什么邪恶的事情。"
D.Strings[38630]="<厕所里一片死寂。>"
D.Strings[38631]="尤瑞克，你在里面吗？我可要动手啦！我们上！"
D.Strings[38632]="来吧蠢货们。拥抱死亡吧。你们的末日到了！"
D.Strings[38633]="泰坦界门即将完全开启。我们将协助托维尔重塑奥丹姆，毁灭艾泽拉斯的一切生灵！"
D.Strings[38634]="我们已对死亡之翼大人效忠已久。让我们为他献出所有，在末日到来之时沐浴在他的烈焰之中！"
D.Strings[38635]="死亡之翼大人对永恒之井的破坏，削弱了奥丹姆的防御。做好准备。我们很快就将穿越界门！"
D.Strings[38636]="你好吗，$n？"
D.Strings[38637]="很久以前，在上一场大战还没开始的时候，我的父亲经营着北山伐木场。那是他的生命，他为之投入了全部的精力。然后战火袭来，我们逃去了暴风城——这个决定令他痛苦万分。$B$B但如今，天灾军团的威胁已经消除，血色十字军也已被击退……北山伐木场终于又回到了我们手中。"
D.Strings[38638]="超乎想象的力量通过我传到界门！呜哈哈哈哈哈哈！"
D.Strings[38639]="正在解读最后的指令。我们很快就能激活界门！"
D.Strings[38640]="我们中间出现了入侵者。干掉他们！谁也别想破坏死亡之翼大人的计划！"
D.Strings[38641]="我们的确效忠于死亡之翼，可我们同时也效忠于更强大的存在。别忘了这一点！"
D.Strings[38642]="我们没有多少时间了。克罗雷马上就要到了。开始吧！"
D.Strings[38643]="快住手，伙计。"
D.Strings[38644]="嘿，痒死了，伙计！"
D.Strings[38645]="好了，出发！"
D.Strings[38646]="那边！躲进衣橱里！我会躲在你旁边的阴暗处。"
D.Strings[38647]="准备出发，伙计！"
D.Strings[38648]="你有考虑过我的提议了吗，伊瓦？"
D.Strings[38649]="返回西瘟疫之地，否则你的野马将把你踢下去！"
D.Strings[38650]="我们现在为什么要相信你，克罗雷？你抛弃了我们。任由我们自生自灭。"
D.Strings[38651]="我们若想打赢这一仗，就需要你的帮助。眼下必须团结一致！否则，被遗忘者会把我们全都消灭。"
D.Strings[38652]="你真了不起，伊瓦。银松森林其余所有狂野之灵都将听命于你。"
D.Strings[38653]="我对你的战争不感兴趣，克罗雷。"
D.Strings[38654]="可我亲眼目睹过被遗忘者的卑鄙行径。这是真的。他们追杀我们……杀死那些毫无还手之力的无辜民众。"
D.Strings[38655]="那你会帮忙？"
D.Strings[38656]="是，我将收拾行装……我们……"
D.Strings[38657]="%s对着空气嗅了嗅。"
D.Strings[38658]="看来我们受到了监视，克罗雷。你的性格如此软弱……这应该是格雷迈恩的错。"
D.Strings[38659]="奸诈的小崽子！"
D.Strings[38660]="你还有什么话说，间谍？"
D.Strings[38661]="我或生……或死……都效忠于女妖之王。"
D.Strings[38662]="我就知道你会这么说……"
D.Strings[38663]="我会整理行装。把他们全都集结起来需要花点时间，可我们愿意加入……至少目前如此。"
D.Strings[38664]="$n，你回来了！那是中部碎片吗？"
D.Strings[38665]="我需要更多加密计划书。"
D.Strings[38666]="什么？！你竟然对我的空气法术免疫？"
D.Strings[38667]="我的火焰箭居然没用！不要紧，你这自鸣得意的小虫子。我一定会把你毁掉！"
D.Strings[38668]="你竟然免疫我的水系法术！这怎么可能？"
D.Strings[38669]="谢……谢谢你。"
D.Strings[38670]="嘿老兄！你是来帮赞吉吉出去的吗？"
D.Strings[38671]="是，赞吉吉。让我们去操练下战斗技巧。"
D.Strings[38672]="这可真有趣，老兄！我喜欢做德鲁伊！"
D.Strings[38673]="赞吉吉，为什么你不先回治愈者营地去呢？"
D.Strings[38674]="这是什么地方？呃，还有那股味道……"
D.Strings[38675]="这座祭坛上曾举行过某种仪式，看起来像是范伦曾经说过的那种异教徒入会仪式。血腥又令人作呕。"
D.Strings[38676]="你以为是——等等——$n，小心身后！"
D.Strings[38677]="要去哪里，船长？"
D.Strings[38678]="还不算太糟。也许有点儿重，可我能行。"
D.Strings[38679]="嚄！也许有点儿软，船长？"
D.Strings[38680]="好重……什么也看不见。"
D.Strings[38681]="也许船长也搬了个箱子？"
D.Strings[38682]="呃……这些箱子太重了。要掉地上了！"
D.Strings[38683]="船长，我需要帮助！"
D.Strings[38684]="我快得疝气了。船长，什么叫疝气？"
D.Strings[38685]="这可不包括在我的职责范围内！等等！是的，这是在我的职责范围内。"
D.Strings[38686]="拜托了，船长，我能把箱子放下吗？"
D.Strings[38687]="看不见了！往哪边走？！要干吗？！"
D.Strings[38688]="这可真痛苦。简直赶上肚痛腹泻了。"
D.Strings[38689]="到此为止！这是我的……上……上限了……不行了！"
D.Strings[38690]="小心——我又发现一个！"
D.Strings[38691]="把他们击退——我快撑不住了！"
D.Strings[38692]="$n，你成功了。他们看来在逃窜了。"
D.Strings[38693]="我就知道那群渣滓不值得信任！击碎他们！"
D.Strings[38694]="啊——！敌人太多了！"
D.Strings[38695]="你们这群小鬼想要暴动？我要让你们瞧瞧厉害！"
D.Strings[38696]="铸炉之主！我被告知敌人打断了你的行动。现在，碎片在哪里？"
D.Strings[38697]="很好。在巨石之核里和我碰头，等待我的进一步指示。"
D.Strings[38698]="我就直说吧，铸炉之主，我们有些很有势力的朋友。"
D.Strings[38699]="碎片现在在巨龙手上，夫人。"
D.Strings[38700]="是，夫人。马上就去！"
D.Strings[38701]="呃，要是您不介意，我想问问。我们是怎么找回碎片的？又是怎么悄悄地渗透进了敌人阵营的？"
D.Strings[38702]="远处传来巨大翅膀的扇动声。龙母来了！"
D.Strings[38703]="嘿$n，别让那次小伏击的事传到我父亲耳朵里。要是他发现我竟敢冒这种险，我就再也别想踏出要塞一步……"
D.Strings[38704]="谁没喝醉，托罗克？"
D.Strings[38705]="包括我？"
D.Strings[38706]="<嗝儿！>嗯……让我们瞧瞧……看来没人例外啊。整船的人都醉得找不着北了，长官……除了那些新兵……<嗝儿！>"
D.Strings[38707]="在我被地狱咆哮的目光盯得无地自容前，我要把这地方烧成灰烬！"
D.Strings[38708]="我跟我的新兵走散了，长官。你能再派一个给我吗？"
D.Strings[38709]="放哪儿？要掉地上了！快来帮忙！"
D.Strings[38710]="就是这里了。萨缪尔森的文件应该在三楼，沿着旋转楼梯一路上去就能找到。"
D.Strings[38711]="我们走。殿下想要看些文件，这个理由应该不会引起任何人的怀疑。"
D.Strings[38712]="完全不对。这儿根本没有任何与暮光之锤有关的东西。萨缪尔森在玩什么把戏？"
D.Strings[38713]="够了。诅咒教派不需要安多哈尔。就把这座毫无价值的城市留给你们吧。"
D.Strings[38714]="库尔迪拉！我听到传闻说你在洛丹伦。"
D.Strings[38715]="你听得没错，萨萨里安。我想再给你一个杀死我的机会。"
D.Strings[38716]="看来情形可能真会如你所说。"
D.Strings[38717]="嗯，可能会……但不是今天。既然已扫除了天灾军团的威胁，我准备重新集结我的军队。"
D.Strings[38718]="我明白了。那么我也会这么做。"
D.Strings[38719]="可你必须清楚，库尔迪拉——我们的兄弟情已尽。你现在是部落的一员，而我效忠于联盟。"
D.Strings[38720]="最终，我们将为安多哈尔而战，我们之中只有一人能载誉离开这个战场。"
D.Strings[38721]="是的，我知道。而且我不认为我会对你手下留情。"
D.Strings[38722]="非常好。我翘首期待着。"
D.Strings[38723]="不要和任何人提起今天的协议，$n。把这看做是你直属长官所下达的命令。"
D.Strings[38724]="我要返回王座大厅，监视萨缪尔森的一举一动。多加小心！"
D.Strings[38725]="怎么会有那么大的灌木小鸡？"
D.Strings[38726]="让我感到饥肠辘辘了……为什么那么大呢？是白痴还是什么？居然把小鸡弄得那么大……是谁干的？"
D.Strings[38727]="是被遗忘者干的……是他们……真是太大了……看看它那蠢笨的大脖子。我真想一把掐死它！"
D.Strings[38728]="敢碰我的小鸡，我就让你在梦里去见阎王。听懂没有？"
D.Strings[38729]="她来了，老大！"
D.Strings[38730]="没时间闲聊了。我们的人民正处于水深火热之中，每个辛多雷成员都肩负着重任。"
D.Strings[38731]="欢迎参加派对，$g老兄:女士;！"
D.Strings[38732]="谢谢你，朋友。让我们去杀几个超大号的……蜘蛛。我觉得是个好主意。"
D.Strings[38733]="我们要找出幕后主使，结果了她！"
D.Strings[38734]="给我来杯酒！"
D.Strings[38735]="我能指导你锻造的技巧，并向你提供必要的工具。$B$B需要我帮忙吗？"
D.Strings[38736]="我能指导你钓鱼的技巧，并向你提供渔具和各种物资。$B$B需要我帮忙吗？"
D.Strings[38737]="你的灵魂属于我。"
D.Strings[38738]="起来吧，被遗忘者！"
D.Strings[38739]="你现在效忠于女妖之王了，凡人。"
D.Strings[38740]="起来吧，$n！加入被遗忘者吧！"
D.Strings[38741]="别耽误时间了，$n。我们不该让女妖之王久等。"
D.Strings[38742]="不同的主人，对力量的无尽贪欲却是一样。"
D.Strings[38743]="我感受到了你将面临的毁灭，$n。"
D.Strings[38744]="这里的温暖感觉令我恶心。"
D.Strings[38745]="我向往诺森德的冰冻荒原。"
D.Strings[38746]="你感觉到了吗，$n？黑暗在席卷我们。"
D.Strings[38747]="生命是毫无意义的。我们在死后才会面临真正的考验。"
D.Strings[38748]="通过我，女妖之王看得见一切……"
D.Strings[38749]="他来了。准备好，兄弟们！"
D.Strings[38750]="象沿对角线移动着！"
D.Strings[38751]="象威胁着卒……"
D.Strings[38752]="将！"
D.Strings[38753]="游戏还没结束……"
D.Strings[38754]="卒……吃了……象……"
D.Strings[38755]="我是被遗忘者。"
D.Strings[38756]="为了黑暗女王的荣耀！"
D.Strings[38757]="出……出什么事了？"
D.Strings[38758]="我是永恒……我是死亡。"
D.Strings[38759]="你对我做了什么！？"
D.Strings[38760]="随着那个可耻的叛徒咽下最后一口气，黑主教的护盾终于消散了。"
D.Strings[38761]="向你的新主人俯首致敬吧！"
D.Strings[38762]="起来，摧毁我们的敌人！"
D.Strings[38763]="感谢你帮助我，朋友！我已经不想再变形了……现在我要努力提高我的治疗术水平！"
D.Strings[38764]="这场棋局已经开始！而你只不过是一个卒子。我则是……黑主教！"
D.Strings[38765]="将军。"
D.Strings[38766]="你好，年轻人，真高兴能再见到一个高贵的灵魂。$B$B埃德萨拉已经彻底堕落，成为了今日的厄运之槌。我亲眼看着我的同胞们败倒在黑暗和混乱力量的脚下。可能许多人都认为，只有把这里彻底夷为平地，才能永远结束盘踞在这里的恐怖。$B$B但厄运之槌还是值得拯救的，凡人。帮帮我，也许我们的共同努力能够重新唤醒这里巨大的善良力量，让久远以前的美好时代重新回来。"
D.Strings[38767]="我能指导你钓鱼的技巧，并向你提供各种有用的物资。$B$B需要我的帮助吗？"
D.Strings[38768]="我能指导你草药学的技巧，并向你提供各种有用的物资。$B$B需要我的帮助吗？"
D.Strings[38769]="大地之子，需要我的帮助吗？"
D.Strings[38770]="丛林中暗影重重，但它的土地肥沃丰茂。$B$B愿大地之灵眷顾你，$c。"
D.Strings[38771]="我希望了解更多关于大地之灵的秘密，请训练我。"
D.Strings[38772]="戈多克们不喜欢达戈索尔，所以他杀了他们。那些愚蠢的树和山羊人也不喜欢达戈索尔，所以他也想杀光他们。$B$B小$r喜欢达戈索尔吗？是不是愿意帮助他征服这个地方？还是达戈索尔也要杀掉你？$B$B愚蠢的树一直在盯着大使达戈索尔……"
D.Strings[38773]="我已经彻底弹尽粮绝了，而道路又遭到了兽人的封锁，我的运气可真好啊！"
D.Strings[38774]="快，陛下！敌人杀上来了！"
D.Strings[38775]="<少校略点了一下头。>"
D.Strings[38776]="$n，这么快就回来了？有没有从码头工人那里得到什么消息？"
D.Strings[38777]="结束了，萨缪尔森。我们知道你的身份，你要在教堂中实行的小阴谋已经破产了。"
D.Strings[38778]="我们一点咖啡都没有了？"
D.Strings[38779]="我怎么总是得到这样的安排？"
D.Strings[38780]="寻找线索？这里倒是有一个线索：兽人。还有另一个线索：兽人气味。"
D.Strings[38781]="我的肚子告诉我，现在应该是我们立即行动，开始痛饮的时候了。"
D.Strings[38782]="诅咒之地——真是个合适的名字。诅咒这个地方，诅咒这座城堡，我还要诅咒另一座一模一样的城堡。"
D.Strings[38783]="我看不见！"
D.Strings[38784]="这张桌子的反面真的很脏！"
D.Strings[38785]="我很好奇，斯通菲尔德妈妈到底能不能修好那扇窗子上的锁……"
D.Strings[38786]="兽人！是兽人！不，等等，还是科洛兰的肚子。"
D.Strings[38787]="是的……是的，$c。这全都是真的。我并不为此感到羞愧。和我所侍奉的力量相比，凡间的国王只不过是一些蛆虫而已。"
D.Strings[38788]="我恨你，诺比西。"
D.Strings[38789]="我的肚子里有一种奇怪的感觉，指挥官。你觉得会是那种鱼人鳍汤在作怪吗？"
D.Strings[38790]="至少你不必把老婆丢在铁炉堡。我真无法想象，没有我在身边，她到底会怎么样。你对女人永远无法像对矿石那样了解。"
D.Strings[38791]="你觉得恩诺哈尔会不会给我们送几桶酒来？这样至少可以让我们的精神振作一些。"
D.Strings[38792]="%s突然抽出了一把暗藏的匕首！"
D.Strings[38793]="我还没有完蛋呢。要死的是国王！"
D.Strings[38794]="艾比希昂来了。做好准备！"
D.Strings[38795]="我不行了！你只能靠自己的力量打败他了！"
D.Strings[38796]="父亲，小心！"
D.Strings[38797]="%s施放真言术：盾以保护他的父亲。"
D.Strings[38798]="不！休想干扰我！我的变化还没有结束！"
D.Strings[38799]="我要离开这儿！"
D.Strings[38800]="我自由了！谢谢你！"
D.Strings[38801]="我以为我要死在那里面了。"
D.Strings[38802]="还好我遇到了你。"
D.Strings[38803]="现在我唯一关心的就是修复埃德萨拉。在这座城市平安无事之前，其它所有事情，战争、冲突、忠诚，对我都没有意义。"
D.Strings[38804]="愿光明拥抱你。"
D.Strings[38805]="再见，$n。请将我的问候转达给治愈者营地的好人们。"
D.Strings[38806]="被遗忘者已经攻破了你的防线，镇长。"
D.Strings[38807]="你必须马上做出决定！"
D.Strings[38808]="死在战场上，成为被遗忘者的奴仆，或者……"
D.Strings[38809]="喝下我的血，作为狼人重生，只有这样才不会堕落成为被遗忘者。"
D.Strings[38810]="帮助我们消灭被遗忘者，为联盟夺回洛丹伦！"
D.Strings[38811]="我们宁死也不愿变成狼人。但我们也知道，即使是死亡也无法让我们逃避这场残暴的战争……"
D.Strings[38812]="我们选择复仇！"
D.Strings[38813]="希望你的意志够强！穿越裂口的旅程可不适合弱者。"
D.Strings[38814]="我们正处在大漩涡的中心，这道裂隙分隔了深岩之洲和艾泽拉斯。看着它把你们的世界撕成碎片吧！"
D.Strings[38815]="但愿我们进入裂隙之后萨尔他们能够维持住它！"
D.Strings[38816]="要进去了！做好准备！"
D.Strings[38817]="死亡之翼的污染，连同他的暮光教徒都将被彻底从深岩之洲中清除干净！"
D.Strings[38818]="联盟成功地守住了托尔巴拉德！"
D.Strings[38819]="你成功了！很好！"
D.Strings[38820]="这是大地神殿。它是深岩之洲最重要的建筑物。"
D.Strings[38821]="暗影诸神，暮光的君主们……赐予我力量吧！"
D.Strings[38822]="石头穴居人正在进攻！"
D.Strings[38823]="还有更多的石头穴居人杀过来。保卫投石车！"
D.Strings[38824]="这儿曾经有块泰坦制造的石头，被称作世界之柱。如同其字面意思，它承载了深岩之洲世界所有的元素之力和磁吸引力。"
D.Strings[38825]="看起来，这是石头穴居人最后的一波攻击了。你的胜利已经近在眼前了！"
D.Strings[38826]="死亡之翼冲破了穹顶，在两个世界间制造了裂隙，世界之柱也裂成了碎片。如果我们不能让世界之柱复原，那么整个深岩之洲都会崩溃。"
D.Strings[38827]="跑……"
D.Strings[38828]="第一块碎片本应由一艘名叫风暴之怒的部落炮艇给我们送来。但它始终没抵达。"
D.Strings[38829]="我们控制了这座神殿，并在竭力抑制它受到的伤害。到神殿里和玛鲁特谈谈，下面由他负责。"
D.Strings[38830]="部落成功地守住了托尔巴拉德！"
D.Strings[38831]="联盟成功地占领了托尔巴拉德！"
D.Strings[38832]="部落成功地占领了托尔巴拉德！"
D.Strings[38833]="我们全都指望你了。"
D.Strings[38834]="Al'golath mal shal'nel……黑暗吞噬……"
D.Strings[38835]="这边走，$n。我们要让他们大吃一惊。"
D.Strings[38836]="接管铁炉堡的时候，我也在场——那时真是一片混乱。$B$B所以当我离开城堡的时候，父亲会采取这样的保护措施也就不奇怪了。"
D.Strings[38837]="我们要离开这里！"
D.Strings[38838]="你怎么能活着走到这里？你一定就是那个来对抗厄运之槌的英雄。"
D.Strings[38839]="好了，我们出发！"
D.Strings[38840]="进来，朋友……暂时把你的担忧放到一边去吧！$B$B让自己的灵魂和躯体都好好休息一下。"
D.Strings[38841]="我并非一直是女妖之王，$n。"
D.Strings[38842]="我的人民也并非一直是被遗忘者。"
D.Strings[38843]="曾经，这片土地属于北部王国洛丹伦，由泰瑞纳斯·米奈希尔国王统治。"
D.Strings[38844]="泰瑞纳斯有一个儿子，名叫阿尔萨斯。"
D.Strings[38845]="阿尔萨斯…单是说出他的名字就会让我的身体因愤怒而颤抖。"
D.Strings[38846]="这个幼稚的男人，阿尔萨斯，亲手拔出了一把名为霜之哀伤的邪剑。"
D.Strings[38847]="手持霜之哀伤，阿尔萨斯杀死了亲生父亲，并毁掉了这片土地和所有的生物。"
D.Strings[38848]="阿尔萨斯和他的军队肆虐了我的家园奎尔萨拉斯，杀死我的人民，并给我带来了死亡。"
D.Strings[38849]="阿尔萨斯的残忍没有止境，他将我的灵魂抽离了身体，把我变成女妖，以侍奉他的天灾军团。"
D.Strings[38850]="被天灾的战争机器杀死的每个人都遭遇了同样的厄运。"
D.Strings[38851]="在这深渊的火焰中净化你的灵魂吧！"
D.Strings[38852]="忏悔吧，凡人们！在这无法阻止的大毁灭之前忏悔吧！"
D.Strings[38853]="拜服于强者脚下，你也许还能在这个渺小世界的毁灭中逃过一死！"
D.Strings[38854]="以萨格拉斯的名义！没有信仰的人只能成为祭品！"
D.Strings[38855]="伟大的君主萨格拉斯将看到你的背叛，你的欲望，还有你彻底的毁灭！"
D.Strings[38856]="死后，我们变成了没有思想的亡灵。"
D.Strings[38857]="但阿尔萨斯并非不可战胜！他的力量日渐衰竭，他对受诅者意志的掌控也弱化了。"
D.Strings[38858]="在阿尔萨斯最虚弱的时候，我发起了进攻！"
D.Strings[38859]="阿尔萨斯赎罪的时刻眼看就要到来，但那只蛆虫逃脱了命运的制裁，回到了诺森德的冰冻废土。"
D.Strings[38860]="随着阿尔萨斯一同消失的还有他对洛丹伦众多亡灵的思想控制。我恢复了身体，并让剩下的天灾亡灵也获得了自由。"
D.Strings[38861]="阿尔萨斯后来成为了巫妖王，凭着对他的共同仇恨，被遗忘者诞生了。"
D.Strings[38862]="我们的目的—我们唯一的目的便是毁灭巫妖王。我们加入了部落，并踏上了通往救赎的远征。"
D.Strings[38863]="现在，巫妖王被消灭了，我们回到了这片土地。"
D.Strings[38864]="这些人民将这片土地称为家园，生亦如此，死亦如此。"
D.Strings[38865]="但联盟不承认我们的主权。他们声称这片土地属于他们，妄图将它从王国的创立者们手中夺走。"
D.Strings[38866]="我绝不允许…绝不！"
D.Strings[38867]="洛丹伦永远属于被遗忘者，永远。"
D.Strings[38868]="我提供的材料都是罕见而且强大的。"
D.Strings[38869]="你已经证明了自己的实力和才智。我相信你将成为打败旋岩虫的英雄。那是我们无法完成的任务。你要深入碎岩之渊，那里是我们唯一无法通过的地方。"
D.Strings[38870]="前进，毁灭的奴仆们，让这个世界彻底陷入下界位面扭曲的烈火之中！"
D.Strings[38871]="天空被黑暗笼罩，你们的灭亡已经临近！"
D.Strings[38872]="时间到了！进军，将毁灭带给这片被诅咒的土地，带给那些怯懦的生灵！"
D.Strings[38873]="不！你告诉金矿那个蠢地精，他死定了！我们的合同完了！"
D.Strings[38874]="石鳞主母被困住了！注意不断变换位置，躲避她的攻击！"
D.Strings[38875]="深岩之洲？我痛恨这个地方。等等……你不是见习萨满金矿！"
D.Strings[38876]="我知道你在找什么。我能感觉到它！"
D.Strings[38877]="这不是我的合同！死吧，$r！"
D.Strings[38878]="哦，金矿，我似乎是找不到你的火焰图腾了。"
D.Strings[38879]="我可不是火焰图腾做的，这你知道！"
D.Strings[38880]="维尔顿只不过是个该死的懦夫。他刚刚逃得一条活命，现在却装成一副英雄的样子跑到这里来了？$B$B呸！"
D.Strings[38881]="不要听阿莱克斯瞎说。瘟疫袭来的时候他却不知道逃走，那只能说明他的愚蠢。看看他现在的样子——和这里的其他憎恶没有两样。$B$B别担心，我们会夺回通灵学院和它周围的土地。把它们交给巴罗夫最后一个活着的儿子。他才是这里的合法继承人。"
D.Strings[38882]="库尔迪拉！你的女王在召唤你！"
D.Strings[38883]="陛下。我将……安多哈尔献给您。"
D.Strings[38884]="你这个傲慢的家伙。你以为我是个瞎子？看不见幽暗城外面发生的一切？"
D.Strings[38885]="我……陛下，我们胜利了！"
D.Strings[38886]="别想得到我的感谢。当我们击败天灾军团的时候，安多哈尔就已经应该属于我们了。"
D.Strings[38887]="我知道你的秘密，库尔迪拉。我知道你和联盟死亡骑士萨萨里安之间的友谊。"
D.Strings[38888]="陛……陛下……"
D.Strings[38889]="阿尔萨斯在创造死亡骑士的时候就已经必败无疑了。你还很软弱。"
D.Strings[38890]="幸运的是，我的部下可以帮助你……消除你的软弱。到到幽暗城下面去吧。"
D.Strings[38891]="嘘……安静，死亡骑士。当我了结你的时候，你的恐惧也将不复存在。"
D.Strings[38892]="到那时，你就会感谢我了。"
D.Strings[38893]="你不会是又想偷我的炸药吧，是吗？"
D.Strings[38894]="看看这地方！$b$b这是考古学家的梦想……"
D.Strings[38895]="这次可不要偷走我的炸药了，好吗？"
D.Strings[38896]="我很想停下来聊一会儿，但这些炸药可不会自己走路……"
D.Strings[38897]="赢取胜利的英雄回来了！$B$B你还没有见到熔岩之牙？$B$B<这名见习萨满露出担忧的神情。>"
D.Strings[38898]="好好看看，我有没有变漂亮些？"
D.Strings[38899]="裂隙已经被关闭，雷霆崖安全了！这些传送门一定与他们的下一步行动有关。$B$B赶快！进入传送门！我们必须乘胜追击！"
D.Strings[38900]="他们会吸干洛克湖，直到那里只剩下一点泥巴，但我们还是要英勇奋战以保卫它。"
D.Strings[38901]="$n，能占用一下你的时间吗？"
D.Strings[38902]="我能告诉你的秘密会让你的灵魂四分五裂，$c。$B$B相信我：你应该去别人那里接受训练。"
D.Strings[38903]="有多少人知道，外界的黑暗中到底隐藏着怎样的恐怖……那是能够让灵魂发疯的诡谲之物！$B$B我们一直都很清楚这一点。而你也想来此一探究竟，对么？"
D.Strings[38904]="你好，$n。你想要学习隐秘的艺术吗？"
D.Strings[38905]="你好，$c。\n\n真是可悲啊，你最终还是无法了解这个世界的辛秘：时间、命运、燃烧的星辰和凄冷的黑暗……你永远也无法知道这终极的真实了！"
D.Strings[38906]="准备好了就告诉我，$n。"
D.Strings[38907]="准备好进行仪式之后就告诉我，$n。"
D.Strings[38908]="消灭最靠近的无名者。"
D.Strings[38909]="准备去死吧，$r！"
D.Strings[38910]="当你准备好的时候，只需要告诉赞吉吉就可以了！我会为你弄一只鸟下来！"
D.Strings[38911]="喔……放轻松，就是现在。"
D.Strings[38912]="赶快，$n！到箱子里去！"
D.Strings[38913]="你好，$g勇敢的:美丽的;$c。我能为你做些什么？"
D.Strings[38914]="最近你有没有注意到一些奇怪的事情？铁匠铺里有没有来过什么新顾客？"
D.Strings[38915]="嗯，让我想想……我看见几个苦工从那边的矿井里跑出去了。嘴里念叨着蜘蛛还是什么的。新客户？嗯，有位年轻可爱的侏儒小姐，名叫杰拉莉，她上星期买了把比她大一倍的斧子。喔，魔导师毕斯普来咨询过护甲。不知道他要板甲做什么……"
D.Strings[38916]="最近你有没有注意到一些奇怪的事情？有没有来过什么新顾客，买走什么可疑的东西？"
D.Strings[38917]="这算什么，审问吗？你不是弗丁的内部事务处理人员吧？$b$b嗯，反正我也没什么可隐瞒的。让我翻翻我的记录。上星期米纳尔中尉从我这儿买了件舞会礼服，这让我感到有些奇怪。还有……魔导师毕斯普买了几件皮上衣，也没说出什么原因。喔，弗拉尔·伯林汉姆来为他的硬钳避世乐园之旅订购泳衣。就这些。$b$b要是你不介意的话，我得招呼客人了！"
D.Strings[38918]="你好，$c！"
D.Strings[38919]="你好，女士。最近有没有听到过什么有趣的传闻？"
D.Strings[38920]="嗯，让我们瞧瞧。我听说魔导师毕斯普最近一直把自己关在塔顶，好像是在研究什么新法术之类的东西。$b$b德尔·盖罗恩正准备退休，回农场养老。事实上他可能已经离开了。$b$b喔，我还听说有个什么$r$c在城镇附近游荡，拉住人们问东问西！$b$b只是和你开个玩笑，宝贝儿。希望这些信息能帮到你。"
D.Strings[38921]="愿光明眷顾你，孩子。在这样美好的日子里，我能为你做些什么？"
D.Strings[38922]="我正在寻找一个曾经在壁炉谷偷窃物资的贼。有什么线索么？"
D.Strings[38923]="被盗的补给品？嗯，让我想想……$b$b我知道有个叫达莉亚的祭司，在上星期活动结束后把剩下的酒都拿走了，并没有照我说的放回来。不过我相信她很快就会前来为此道歉的。$b$b<阿尔法斯朝你眨了眨眼。>$b$b我还听到那个法师……叫什么来着……克里斯普？还是利斯普？差不多就是这名字吧。他这礼拜一反常态地做了不少次忏悔。$b$b好了，快走开吧。"
D.Strings[38924]="你……你在这里做什么，$r？难道你看不出，你已经干扰了银色北伐军的官方行动？！"
D.Strings[38925]="我只是在奇怪，你对南边的那些豺狼人到底有些什么了解。有人正在利用它们施行巫术。"
D.Strings[38926]="竟敢阻挠我的计划，你将为此付出生命的代价，你这个可怜的渣滓！"
D.Strings[38927]="<哼哼>$b$b你需要些什么，$r？"
D.Strings[38928]="怎么了？我现在有些忙。"
D.Strings[38929]="我正在接受训练。可以等一会儿吗？"
D.Strings[38930]="米纳尔中尉要求我与你进行一场决斗。"
D.Strings[38931]="好啊。你想要这个？"
D.Strings[38932]="北伐军的时代到来了！"
D.Strings[38933]="好啊……但我是不会退缩的！"
D.Strings[38934]="准备好，我来了！"
D.Strings[38935]="我想，我还需要更多练习。"
D.Strings[38936]="妈妈说得对……我永远也没办法进入银色北伐军。"
D.Strings[38937]="这次是你赢了。"
D.Strings[38938]="%s点燃了地精烤肉野餐的篝火！准备好加入聚会吧！"
D.Strings[38939]="它发挥作用的频繁程度一定会让你吃惊的。"
D.Strings[38940]="在我们与部落交战之后，我们的舰队在进入港口的时候还保持了大致完整的规模。我们在滩头堡的阴影中起锚，重新集结。$B$B就在此时，纳迦出现了。$B$B无数只覆盖着闪光鳞片的手攀住锚链……将人们拖入水中，让他们尖叫着沉入深渊……$B$B这是被诅咒的海岸，$n。被诅咒了。"
D.Strings[38941]="消灭他们，$c！摧毁尽可能多的纳迦，为逝去者报仇。"
D.Strings[38942]="龙女王飞到了我们头顶上！别害怕，年轻人，我被称为“坚定者”可是有来由的……"
D.Strings[38943]="从一块石头跳到另一块石头上，吸引龙女王的注意力！"
D.Strings[38944]="我们不能失败，$n。许多个世界的未来都将由这场战斗而决定。"
D.Strings[38945]="别想拿走箱子！"
D.Strings[38946]="谢谢……这样的话，我们还可以坚持几个小时，不跑进岩石里去。但那以后，我就没办法做任何保证了。"
D.Strings[38947]="带我去巴拉丁监狱。"
D.Strings[38948]="带我去熔渣车间。"
D.Strings[38949]="带我去铁甲兵营。"
D.Strings[38950]="把我扔上去！"
D.Strings[38951]="带我去典狱官岗哨。"
D.Strings[38952]="带我去东部尖塔。"
D.Strings[38953]="带我去西部尖塔。"
D.Strings[38954]="带我去南部尖塔。"
D.Strings[38955]="我现在必须走了……"
D.Strings[38956]="嗯，我已经道过别了。该是出发的时候了。"
D.Strings[38957]="我已经在这里等待了太长时间。该是道别的时候了。"
D.Strings[38958]="我……我想，我已经准备好离开了。"
D.Strings[38959]="你是谁？你对我做了什么？"
D.Strings[38960]="离开这里！"
D.Strings[38961]="你这个没脑子的$r！你要为你的行为付出代价！"
D.Strings[38962]="裂隙已经被关闭，奥格瑞玛安全了！这些传送门一定与他们的下一步行动有关。$B$B赶快！进入传送门！我们必须乘胜追击！"
D.Strings[38963]="我为刚刚的无礼行为道歉。因为我非常担心我的父亲。我们是朋友，对不对？"
D.Strings[38964]="我一定会让你得到世界之柱中端的残片。"
D.Strings[38965]="在死亡之后，我还能帮你些什么？"
D.Strings[38966]="我无法帮助你。"
D.Strings[38967]="她来了。哦，海洋的邪恶荡妇……"
D.Strings[38968]="转开你的视线！不要看她！"
D.Strings[38969]="不要听她的声音！"
D.Strings[38970]="不要看她那……红宝石般的……柔软的……肉欲的双唇！哦……"
D.Strings[38971]="在那里！她显形了。攻击！"
D.Strings[38972]="调查"
D.Strings[38973]="看起来，这只箱子的功用应该是储存武器和盔甲。"
D.Strings[38974]="真高兴能有机会喘一口气。谢谢你的帮助！"
D.Strings[38975]="你以为我对付不了他们？不要因为我矮就瞧不起我。不管怎样，还是要感谢你的帮忙。"
D.Strings[38976]="真高兴能再见到你！感谢你的帮忙。我再过一会儿就能站起来了。"
D.Strings[38977]="戴上这副面具，我什么都看不见。但我可不会告诉她这个。"
D.Strings[38978]="武器……盔甲……这些都是取得胜利的关键。任何一名战士，无论他是多么强壮，都很难周全地保护自己。$B$B$r，我曾经打造过许多传奇的武器和护甲，你在全艾泽拉斯也无法找到能和它们比拟的杰出作品。它们正是我的同胞赢取胜利的关键。"
D.Strings[38979]="血肚一直想当个农夫。"
D.Strings[38980]="血肚站在太阳底下真高兴。"
D.Strings[38981]="血肚想帮忙干农活。血肚已经准备好镰刀了！"
D.Strings[38982]="血肚不太擅长耕种，可血肚超级擅长收割。"
D.Strings[38983]="如果你真的想帮忙，你可以帮我和我的朋友们进行一些格斗练习。"
D.Strings[38984]="那些所谓的圣骑士不让我通过。这样我就没办法去确认那些传说中弗拉斯·希亚比的著名烟草在斯坦索姆是否还有一些遗存！要我说，他们比天灾怪物好不了多少。$B$B这话我也就对你说说，我相信他们那个所谓的“圣光兄弟会”根本就是一场骗局。一个精心设计的阴谋！"
D.Strings[38985]="你想打架吗？好吧，血肚跟你打。"
D.Strings[38986]="血肚认输！你们这群农民更能打！"
D.Strings[38987]="你是来找死的吗？"
D.Strings[38988]="鸡蛋碰石头！"
D.Strings[38989]="你走错路了，朋友？呵呵呵。\n\n我能帮你些什么？"
D.Strings[38990]="你的同类在这里并不常见，朋友。\n\n我能帮你些什么？"
D.Strings[38991]="这块石头就要塌落了！跳到另一块上面去！"
D.Strings[38992]="你离家已经很远了，朋友。呵呵呵。\n\n我能帮你些什么？"
D.Strings[38993]="嗨，朋友。我能帮你些什么？"
D.Strings[38994]="我一直都在打算调查这个地方。$b$b而现在这种情形还从没有发生过！"
D.Strings[38995]="她真的很美……"
D.Strings[38996]="准备好了？我们行动吧！努力跟上，$n。"
D.Strings[38997]="兄弟姐妹们，前进！"
D.Strings[38998]="你死定了。"
D.Strings[38999]="炸弹！这是陷阱！快跑！"
D.Strings[39000]="我准备好了，琼斯博士！"
D.Strings[39001]="我听说过许多关于你的事情，$n。这个世界比以往更加需要像你这样的人。"
D.Strings[39002]="记住这一天——是弗尔特斯基救了你。快跑吧！回到希尔瓦娜斯那里去！"
D.Strings[39003]="嗨，朋友。$B$B你是想要拴住你的宠物吗？还是在寻找一个丢失的同伴？"
D.Strings[39004]="嗨，朋友。$B$B你需要找回一个丢失的同伴吗？"
D.Strings[39005]="抱歉，$c。$B$B我不认为你有能力掌握传送门魔法的真髓。"
D.Strings[39006]="嗨，朋友。$B$B如果你准备好了，我能教你如何开启一道返回这里的传送门……"
D.Strings[39007]="拍卖行和银行就位于山谷中部那高耸入云的建筑顶部，伙计。$B$B去找泽基和Makavu吧。"
D.Strings[39008]="你得去找斯加姆比，伙计。$B$B她就在山谷中部那座高高的建筑里。"
D.Strings[39009]="就在这座山谷的旅店外面，朋友。$B$B就是山谷中部的那座高大的建筑物。"
D.Strings[39010]="法师&传送门"
D.Strings[39011]="比起其它任何组织，圣光兄弟会更有能力铲除敢于冒犯圣光的人。我们会采取一切必要手段，将亡灵那样的邪恶怪物从这个世界上彻底清除掉。没有任何人能阻挡我们。$B$B你要加入我们？还是和我们作对？"
D.Strings[39012]="巫医尤姆布一直在山谷四处活动，照料受伤的病人与元素之灵。$B$B去中部建筑附近找他吧。"
D.Strings[39013]="库扎莉和曾迦是一流的训练大师，他们就在山谷东南端的一座小岛上，伙计。"
D.Strings[39014]="毁灭这个非自然的怪物！"
D.Strings[39015]="你正在污染我们的新家园！"
D.Strings[39016]="兄弟姐妹们，拿起刀剑来！他们正在摧毁这片沃土！"
D.Strings[39017]="去别的地方寻找你的黑金吧！"
D.Strings[39018]="你在这里只能得到鲜血！"
D.Strings[39019]="轰碎那个怪物！"
D.Strings[39020]="压住它！"
D.Strings[39021]="石油不是好东西！"
D.Strings[39022]="这里没有激动，这里没有道统，这里没有狂热。$B$B凝聚在这里的只有兄弟间生死与共的誓言。$B$B乌瑟尔·光明使者就是在这座礼拜堂中加入了白银之手骑士团。而我，科尔法克斯，圣光之勇士，将在此地让无畏者感到恐惧。$B$B没有任何力量能抑制我的愤怒——血色十字不行，银色黎明不行，我的兄弟们不行，你同样不行。"
D.Strings[39023]="好像天使一样……"
D.Strings[39024]="看上去，战况好像对我们不利，但血色十字军终将取得胜利。我坚信，我们一定能彻底清除斯坦索姆的天灾怪物。虽然我不看好银色黎明，不过圣光兄弟会确实是一支能发挥作用的队伍。$B$B闲聊到此结束，$c。我们开始吧。"
D.Strings[39025]="暗影行者祖鲁能够帮助你。$B$B你可以在东南方那座更高的建筑物最下面的一层中找到他。"
D.Strings[39026]="夜行者库纳基应该是你要找的人。$B$B他就在精神谷中部建筑的北边。"
D.Strings[39027]="你要找的人是塞瑟比，伙计。$B$B她通常在老渔夫——恩姆贝托旁边的树下打盹儿，看上去就像只大老虎。"
D.Strings[39028]="你一定是疯了，伙计，居然对那样的巫术感兴趣。可我没资格阻止你。$B$B乌恩加里·邪语就在东南方那座较高的建筑里，穿过暗影祭司的神殿就是了。"
D.Strings[39029]="扎姆沙是奥格瑞玛最好的厨师，朋友。$B$B你可以在这座山谷的中心建筑南边找到她。如果你真的很饿，也可以在巴塔姆西那里买到扎姆沙烹制的食物。"
D.Strings[39030]="加迪和希尔拉亚就在这座山谷中心建筑北边的一座小屋里工作。$B$B他们能提供你所需要的帮助，朋友。"
D.Strings[39031]="酒！！！啊！"
D.Strings[39032]="痛快痛快！口水横流！"
D.Strings[39033]="这酒就像地狱一样够劲！"
D.Strings[39034]="我的力量回来了！"
D.Strings[39035]="兽人需要花生！"
D.Strings[39036]="我也不知道自己有没有喝醉。"
D.Strings[39037]="老恩姆贝托就在位于山谷中部建筑东面的一座小岛上。"
D.Strings[39038]="毒物与药剂"
D.Strings[39039]="宠物蛇"
D.Strings[39040]="Huju和克森图能帮上你的忙。$B$B去山谷的中央建筑里找他们吧，伙计。"
D.Strings[39041]="跪倒吧，联盟！在被遗忘者强大的力量之前跪倒吧！"
D.Strings[39042]="紧紧抓住，$c。这样你才能保护好自己。"
D.Strings[39043]="我们的一些德鲁伊和斥候组成了一支小队伍，前来援助乱风岗的牛头人，对抗我们共同的敌人：恐怖图腾部族。"
D.Strings[39044]="东部尖塔受到了重创！"
D.Strings[39045]="东部尖塔被摧毁了！"
D.Strings[39046]="克萨迪斯和他的蛇群就在这座山谷的中心建筑周围游荡，朋友。"
D.Strings[39047]="西部尖塔被摧毁了！"
D.Strings[39048]="西部尖塔受到了重创！"
D.Strings[39049]="南部尖塔受到了重创！"
D.Strings[39050]="南部尖塔被摧毁了！"
D.Strings[39051]="当大水涌入的时候，他们对我们发动了攻击！就好象他们早已知道了那场洪水的爆发。$B$B他们要为他们犯下的罪行付出代价。"
D.Strings[39052]="联盟失去了对铁甲兵营的控制！"
D.Strings[39053]="联盟获得了对铁甲兵营的控制！"
D.Strings[39054]="部落突袭了铁甲兵营！"
D.Strings[39055]="部落失去了铁甲兵营！"
D.Strings[39056]="联盟失去了对熔渣车间的控制！"
D.Strings[39057]="联盟获得了对熔渣车间的控制！"
D.Strings[39058]="部落突袭了熔渣车间！"
D.Strings[39059]="部落失去了熔渣车间！"
D.Strings[39060]="联盟失去了对典狱官岗哨的控制！"
D.Strings[39061]="联盟获得了对典狱官岗哨的控制！"
D.Strings[39062]="部落突袭了典狱官岗哨！"
D.Strings[39063]="部落失去了典狱官岗哨！"
D.Strings[39064]="我们行动，$n。尽量靠近我。"
D.Strings[39065]="保持警惕，$n。谁也不知道我们在这里会碰到什么……"
D.Strings[39066]="如果你需要材料，尽可以在我这里挑选。"
D.Strings[39067]="我不能训练你，朋友。"
D.Strings[39068]="欢迎来到月光林地，$c。这里的大门对所有愿意坚守神圣和平的人敞开着。"
D.Strings[39069]="我自由了。"
D.Strings[39070]="不过是风尘中的沙土。"
D.Strings[39071]="呼啸的南风，助你的主人一臂之力吧！"
D.Strings[39072]="天空……在召唤……"
D.Strings[39073]="承受这场风暴！"
D.Strings[39074]="你们的城市将被埋葬，你们的生命将归于元素！"
D.Strings[39075]="在风暴中颤抖吧！"
D.Strings[39076]="我需要一些时间来研究这些样品，$n。等我完成了分析，我会再和你谈谈。"
D.Strings[39077]="$n，我们赢得了这场战斗。只要那些农夫还在被遗忘者的侧翼位置大杀大砍，我们就一定能击溃他们。"
D.Strings[39078]="我有些言之过早了，$n。虽然有你的支援，但我们的部队似乎还是陷入了困境。"
D.Strings[39079]="我还没有计划要同时与士兵和农夫作战。如果这些农夫继续骚扰我们的侧翼，我们将有可能无法集中力量完成我们的任务：攻占安多哈尔。"
D.Strings[39080]="这就是你们赢得战争的方法！真应该有人教导一下那个死亡骑士该如何运用军事策略。"
D.Strings[39081]="Ishnu-alah，$c。愿好运伴随你。"
D.Strings[39082]="我很快就会与你汇合。我们要让那些恐怖图腾的野人明白，什么是光荣。"
D.Strings[39083]="那是一个……瓦格里吗？"
D.Strings[39084]="Nechi owachi，$c。向你致敬并表示感谢。"
D.Strings[39085]="我很快就会与你汇合，我们要让那些恐怖图腾的懦夫明白什么是恐惧。"
D.Strings[39086]="那个牛头人告诉我，如果我干得好，她就会教我治疗的技艺！我们开始吧，朋友！"
D.Strings[39087]="不要走进那里！"
D.Strings[39088]="嗯……什么？谁？出什么事了？"
D.Strings[39089]="好的，$n。让我们看看你到底有怎样的能力。"
D.Strings[39090]="Lok'tar！现在就让我们从刚才我们通过的那道传送门回去吧……在奥格瑞玛还有许多工作在等着我。"
D.Strings[39091]="干得好，英雄们。这个传送门本来是为这怪物准备的，现在就让我们通过它回去吧！在雷霆崖还有许多工作在等着我。"
D.Strings[39092]="干得好，英雄们。现在就让我们从刚才我们通过的那道传送门回去吧……在铁炉堡还有许多工作在等着我。"
D.Strings[39093]="<在爆炸前，质量均可保证！>$B$B<塞入钱款，即可得到专业训练和售卖服务。>"
D.Strings[39094]="和我……共赴深渊吧。"
D.Strings[39095]="我要接受主要专业技能的训练。"
D.Strings[39096]="使用专业售卖机"
D.Strings[39097]="如果你愿意，可以在这里休息。现在大地神殿由我们管理。"
D.Strings[39098]="有了适合的技术，你能修好任何东西，$n。当然，我总会会遇到各种故障、短路和不配合的病人。它们为我带来了不少乐趣。"
D.Strings[39099]="加丁是强大的。但不必担心。当你和他的战斗展开之后，我就会来支援你。"
D.Strings[39100]="为了支援乱风岗的牛头人，击退恐怖图腾部族，我们有许多事情要做，却没有多少时间。$B$BTor ilisar'thera'nal！让我们的敌人知道恐惧！"
D.Strings[39101]="这是恐怖图腾最后一次向我们发动进攻了。既然他们不可能明白自己的错误，我们就要像消灭野兽一样摧毁他们。$B$B愿大地母亲原谅我们。"
D.Strings[39102]="可以再给我一瓶元素灵契吗？"
D.Strings[39103]="可以再给我一个净化图腾吗？"
D.Strings[39104]="<石母凝视着你。她的目光仿佛穿过你的肉体，正在望着你的灵魂。>$B$B我的女儿——瑟莱德丝，将自己隔绝在泰拉莫克水晶洞穴深处，终日为挚爱扎尔塔的离去而心伤。就在那里，突然闯进了一群没心没肺的畜生，将正沉浸在哀思之中的她杀死。$B$B要是有任何理由能让我对长着血肉之躯的凡人心存信任，这理由也已在那天消逝。而在你傲慢的态度里，我看到了坚持。$B$B总有一天，你也会变得毫无用处。"
D.Strings[39105]="我听从你的召唤而来，石母。"
D.Strings[39106]="联盟控制了暮光海岸的滩头阵地。"
D.Strings[39107]="部落控制了暮光海岸的滩头阵地。"
D.Strings[39108]="不必害怕。我不会让你掉下去的。"
D.Strings[39109]="警告：此交通工具不可在托尔巴拉德以外使用。现在返回。"
D.Strings[39110]="抱歉，朋友。你只能去别的地方寻找训练机会了。"
D.Strings[39111]="只要一点捐赠，我就能教导你牧师的技艺。"
D.Strings[39112]="啊！不许拿走那宝物！！！"
D.Strings[39113]="我能帮你些什么，$c？"
D.Strings[39114]="你能修理设备吗？"
D.Strings[39115]="嗯，你可以和那边的大地治愈者多罗斯谈谈……就是那名大个子的德莱尼。你可以在暮光营地的左侧找到他。"
D.Strings[39116]="他们的营地几乎被彻底摧毁了。不过我们还是从那片废墟中找到了一些可用的东西。$B$B你需要些什么，$r？"
D.Strings[39117]="我这里没有你要找的东西。$B$B不过赫格莉德正在收集暮光补给品，供我们自己使用。你也许应该找她谈一谈。"
D.Strings[39118]="干得好，英雄们。长久以来，巴纳扎尔一直都是我们的威胁。最让我们头痛的两个敌人——天灾军团和血色十字军的出现都与他有关。如果我们对他的复活放任不管，也许战争的天平会朝不利于我们的方向倾斜。"
D.Strings[39119]="巴纳扎尔并没有被真正消灭，这一点实在是让人感到懊丧。在物质位面击败一名恐惧魔王，只能让它返回到扭曲虚空中去。总有一天，他会回来，甚至有可能再度与他的兄弟瓦里玛萨斯和迪瑟洛克联手。"
D.Strings[39120]="到现在为止，我们已经恢复了对斯坦索姆这半边的控制，我们应该为此感到高兴。这座白银之手的堡垒终于回到了它的主人手中。这里有数不清的财富，而且我们现在还拥有了展开下一次进攻的坚固阵地。"
D.Strings[39121]="这里正需要你们，英雄们。斯坦索姆之战还没有结束。你们应该向东进发，前往东墙大门。那里是这座城市的出入口，也是能够进入瑞文戴尔男爵的天灾军团领地的唯一通道。如果我们能把他打败，斯坦索姆将再一次完全属于我们。"
D.Strings[39122]="我会在阿隆索斯礼拜堂等你。那里是乌瑟尔·光明使者加入白银之手的地方。也是唯一一座天灾怪物们无法触碰的建筑物。那里将成为我们进攻另外一半城市时的桥头堡。有了你的帮助，斯坦索姆一定会成为圣光之都，洛丹伦新生的起点。"
D.Strings[39123]="这种枯萎病是没用的。"
D.Strings[39124]="他们是用什么测试这种废物的？鱼人？"
D.Strings[39125]="啊呀！！！把你喂鳄鱼！！！"
D.Strings[39126]="没用的垃圾。甚至没办法让他们慢一点。"
D.Strings[39127]="我们就要因为各种“规章”而输掉这场战争了。下一步又会怎样？难道我们只能挥挥木剑了吗？"
D.Strings[39128]="这是一场战争，对不对？我们应该用我们的武器消灭敌人，不是吗？"
D.Strings[39129]="把你打倒一定是一件令人愉快的事！"
D.Strings[39130]="看看我们这里都有些什么人？一个被打败的懦夫和一个管闲事的外路人？"
D.Strings[39131]="你们很快就会学会该如何拜倒在恐怖图腾的脚下！不过我却不一定会让你们活到那个时候。"
D.Strings[39132]="嗯，看样子你这种人还是有一点骨气的。"
D.Strings[39133]="裂隙已经被关闭，铁炉堡安全了！这些传送门一定与他们的下一步行动有关。$B$B赶快！进入传送门！我们必须乘胜追击！"
D.Strings[39134]="别人丢下的东西，我都会收集起来。$B$B最近可是有不少东西需要收集。"
D.Strings[39135]="我不能。我只负责收集。$B$B伊布迪尔应该能帮到你。他擅长修理。"
D.Strings[39136]="别人弄坏的东西，我都会修理好。$B$B最近可是有不少东西需要修理。实在是太多了。"
D.Strings[39137]="巫婆长老所选择的人！你还没意识到，是吗？我要先干掉你！还有你的朋友！"
D.Strings[39138]="她为什么会选择……一个外人？"
D.Strings[39139]="我们能再用大炮轰击一下吗？我觉得我们的炮火轰击还不够。"
D.Strings[39140]="就是这样！轰平那片海滩！除了沙子，什么都不留。"
D.Strings[39141]="既然我们要派遣部队登上那片海滩，我们就应该用加倍猛烈的炮火轰击那里。如果你明白，就来帮忙吧。"
D.Strings[39142]="炮火一定要更猛烈！我从来都不喜欢什么半岛。"
D.Strings[39143]="我这里没有什么能帮到你的东西。$B$B也许德罗姆的收集品中会有一些能让你感兴趣的东西。"
D.Strings[39144]="我知道你有自己的办法。我不在乎他们对于你和阿利卡拉的关系有着怎样的议论。那些话到我这里就结束了！"
D.Strings[39145]="在黑云峰上，一切就这样结束了？"
D.Strings[39146]="一旦你决定成为一名萨满祭司，就再无法回头了。$B$B我曾经严重低估了火元素的效用。而且它也很容易管束：只需要加水就可以了。"
D.Strings[39147]="暮光之锤一直在这片高地的各处向我们发动进攻。现在他们已经占领了不少地方。这是我们最后的阵地了，我们可不打算把它丢给敌人，无论他们会从地底下召唤出多么恐怖的怪物来攻击我们。"
D.Strings[39148]="你就是我的姑妈派来的那个家伙？毫无疑问，这是一次测试。我会迅速地干掉你，再一次向她证明我的实力。"
D.Strings[39149]="不！玛加萨，请原谅我！带我回去！"
D.Strings[39150]="干得好，$c！你要做的就是依照线索采取行动。"
D.Strings[39151]="哦，做点好事，顺便为我杀掉阿纳克吧，他已经成为了家族的耻辱。"
D.Strings[39152]="快一点，小$n。我还要让你经历一场挑战，好看看你是否能得到这份光荣。"
D.Strings[39153]="那些呆子在哪里？"
D.Strings[39154]="愿大地母亲怜悯！"
D.Strings[39155]="嗨！为什么你要坐在前面？"
D.Strings[39156]="因为我赢了我们的打赌。也因为我喊了“射击”。"
D.Strings[39157]="谁说你赢了？我们还没有比较分数呢。"
D.Strings[39158]="好吧。我杀了五个僵尸。都是巨型僵尸。你干掉了多少亡灵？"
D.Strings[39159]="我确信自己干掉了六个。"
D.Strings[39160]="我打赌你只杀了四个。"
D.Strings[39161]="你……你怎么知道的？"
D.Strings[39162]="我不知道。是你告诉我的！"
D.Strings[39163]="我是认真的，你们的僵尸狩猎进行得如何了？我很想听一听。"
D.Strings[39164]="吉德文？你不理我了？"
D.Strings[39165]="吉蒂……你生我的气了，是么？"
D.Strings[39166]="还记得我们小的时候么，吉德文？我们会用一整天的时间玩打败巨魔，打败鱼人，或者是打败女孩的游戏。"
D.Strings[39167]="别这样，塔伦纳。"
D.Strings[39168]="我们给自己起了一个名字……是什么名字……？"
D.Strings[39169]="你记得很清楚。"
D.Strings[39170]="我是认真的。我完全忘记了。"
D.Strings[39171]="<叹息>……“圣骑士党”"
D.Strings[39172]="吉德文，下次你可以和我一起坐在前面。"
D.Strings[39173]="也许我不想了。也许我更愿意和我的新朋友们坐在后面。前面有一股马味儿。"
D.Strings[39174]="我在左边看到了一座塔楼。我们停下来休息一下如何？"
D.Strings[39175]="我们在几分钟前刚刚休息过！还是赶紧去圣光之愿礼拜堂吧！"
D.Strings[39176]="这里的路很难走，吉德文。我可不想冒失去一匹马的危险。"
D.Strings[39177]="我们不会失去马的。看看它们！它们还和我们刚刚出发时一样精力充沛。"
D.Strings[39178]="确实，菲奥拉说得没错。"
D.Strings[39179]="我们就算是晚到一会儿，银色北伐军也不会着急的。而且……我们的客人也许很快就会想要下车了。"
D.Strings[39180]="我们到了！"
D.Strings[39181]="卡林，你有达隆郡全史吗？"
D.Strings[39182]="嗯，有的……克罗米需要这个？应该是吧。$b$b我可以把它给你，随你翻看。它会告诉你达隆郡的历史，以及导致那么多人死亡的许多事件细节。"
D.Strings[39183]="联盟援军到了。"
D.Strings[39184]="英雄们，你们成功了！斯坦索姆是我们的了！来吧，我们就等在屠宰房外面！"
D.Strings[39185]="你们行动的目的是夺取这座城市。对于瘟疫之地，瑞文戴尔的死亡标志着一个新时代的到来。残存在这里的天灾军团很快就会被消灭干净。这片土地终将得到重生。"
D.Strings[39186]="斯坦索姆的彻底净化和重建还需要相当长的时间和巨大的精力，但我很高兴能亲身经历这个过程。也许在未来的某一天，我们能在这座白银之手的堡垒看到下一位伟大的圣光守卫者，亲眼见证他在阿隆索斯礼拜堂加入我们的队伍。无论以后会如何，我们在这里的工作总有一天会结下丰硕的果实。"
D.Strings[39187]="谢谢你们，勇敢的英雄们。谢谢你们向艾泽拉斯证明了，无论邪恶的力量多么恐怖，凶猛，不可阻遏，总有一线圣光会冲破黑暗，为我们带来希望。"
D.Strings[39188]="绝不要低估后勤供给的作用。战士们也许会赢得几次战斗，但只有足够的物资供应才能确保一场战争的胜利。"
D.Strings[39189]="感谢你的礼物，让我们看看你有怎样的价值，$c！"
D.Strings[39190]="住手！你已经打败了我的风蛇。"
D.Strings[39191]="我被暮光之锤俘虏了。"
D.Strings[39192]="我不确定那是在哪里。一开始，是在他们西边的基地。那里能够俯瞰风巢。"
D.Strings[39193]="投降？我的投降书只能用他们的血来写。"
D.Strings[39194]="我没办法保证你们能在这里得到平静的休息环境，$c。这些兽人根本不知道什么是平静。"
D.Strings[39195]="一个喝醉的兽人很值得看一看。而一支喝醉的兽人军队则是我绝对不想看到的。"
D.Strings[39196]="如果我妈妈告诉我会有这样的时代，我绝对不会相信她的话。"
D.Strings[39197]="嗨，“老水兵”，你什么时候能换个名字？这个小镇子可不应该有两个叫同样外号的……"
D.Strings[39198]="嗨，那边！嗨！嗨！就是那边！去看看格尔加怎么样啦？"
D.Strings[39199]="呦喉！“老情歌”！看起来你们的物资……嗯……看来你还有许多箱子需要登记……"
D.Strings[39200]="呸！呸！嗨！“胡椒”！你们要照顾好所有这些物资！有没有看见我刚才做了什么？部落……为了部落！"
D.Strings[39201]="“麦芽”！嗨，“麦芽”！我还以为你会给我们带更多的酒来呢！你到底带来了什么？"
D.Strings[39202]="是“老水兵”！我先到了这里！是我先从船上跳到了这片陆地上！我才叫“老水兵”。嗨……你的宠物在哪里？"
D.Strings[39203]="也许你应该担心你的宠物，而不是我！我对工作一直都很尽职尽责！"
D.Strings[39204]="“老水兵”，这是我的名字！你的名字应该是“我管不住宠物”。我才不相信会有人敢把宠物交给你。"
D.Strings[39205]="嗨，别来打扰我。你可真是我们的羞耻。你甚至连自己的宠物都管不好！"
D.Strings[39206]="嘘！嘘！！！如果你能安静一会儿，也许你的宠物就会回来找你了！"
D.Strings[39207]="我的宠物！哦，不！嗯……我相信那个小东西应该就在这附近……"
D.Strings[39208]="哈！你根本就什么都不知道。我把那个畜生放在第三艘船上了！"
D.Strings[39209]="等等……我的宠物在哪里？它不见了！别慌……我只需要喝上一杯，就能想出它到哪里去了。"
D.Strings[39210]="我一直都不喜欢那只宠物。而且……人们总是把他们的宠物给我。就算丢了一只，也没关系。我还有好几十只可以丢呢！"
D.Strings[39211]="我派我的宠物去找些酒回来。等它带回来一马车赛马酒，而你什么也得不到的时候，你就知道后悔了。"
D.Strings[39212]="我想我看到他们了！这边！这边！"
D.Strings[39213]="我能闻到你！"
D.Strings[39214]="我们一直都在希望你不会轻易投降！"
D.Strings[39215]="我们正在找你！"
D.Strings[39216]="我们会找到你的，怪物！"
D.Strings[39217]="我们绝不能让女妖之王失望。"
D.Strings[39218]="我的职责不是问为什么。"
D.Strings[39219]="敢于反抗被遗忘者的，只有死路一条！"
D.Strings[39220]="高弗雷一定是个非常特别的人。主人付出了巨大的代价，只是为了让他回来。"
D.Strings[39221]="凡人……他们一直都让我感到惊讶。"
D.Strings[39222]="这些可怜的小狼崽不可能抵挡住被遗忘者的力量。"
D.Strings[39223]="女妖之王已经预见到了一切。"
D.Strings[39224]="我们已经完成了另外两个目标。高弗雷是最后一个了。"
D.Strings[39225]="高弗雷毕生致力于守卫吉尔尼斯。当狼人诅咒在吉尔尼斯传播的时候，他将主要精力转向防御狼人的进攻。"
D.Strings[39226]="我听说，当高弗雷知道他的国王也受到感染，精神上立刻遭到了沉重的打击。你能想象那种遭到背叛的感觉吗？他所效忠的国王成为了他势必要消灭的怪兽。"
D.Strings[39227]="高弗雷将成为我们的秘密王牌。依靠他对吉尔尼斯和狼人的知识，我们必将取得胜利。"
D.Strings[39228]="我的部下已经复活了高弗雷的两名副官：灰葬男爵和沃登勋爵。"
D.Strings[39229]="如果高弗雷站到我们这一边，我们一定能粉碎这场叛乱！"
D.Strings[39230]="联盟将永远无法从我们的打击中恢复过来！"
D.Strings[39231]="与作为人类时相比，我能够更加清晰地感受到生的活力。这才是生命，$n，这才是活着！"
D.Strings[39232]="让他们来吧！所有敌人都将被黑暗女王的战争机器摧毁！"
D.Strings[39233]="%s将破狼草油涂抹在他的武器上。"
D.Strings[39234]="想要与我们同行吗？我们正要去圣光之愿礼拜堂。"
D.Strings[39235]="嗯，我们正好顺路。是那些在道路上出没的怪兽让我无法成行，只能在皇冠哨卫这里耽误时日。$b$b我想和你做笔交易：帮我清除道路上的怪物，我就会加入你们的队伍。"
D.Strings[39236]="你们帮我消灭了道路上的那些凶狠的怪物。看样子，我已经没什么可抱怨的了。让我们出发吧！"
D.Strings[39237]="我已经在那个镇子里浪费了太长时间。那是一个不错的地方，我很享受在那里的生活。但我想，我更喜欢留在这里。"
D.Strings[39238]="啊！不，我可不行。我害怕马。"
D.Strings[39239]="不！谢谢，也许将来有可能，也许过去也有可能，但绝不是今天。"
D.Strings[39240]="很抱歉，我不行。我的任务是看守这个角鹰兽哨站。这些角鹰兽看上去很驯顺，但它们的确需要二十四小时看管。"
D.Strings[39241]="你好，旅行者？"
D.Strings[39242]="这只是暂别。"
D.Strings[39243]="马车里放的都是装货物的箱子。还有菲奥拉和她的同伴们的一些私人物品。"
D.Strings[39244]="乘菲奥拉的马车前往下一个目的地。"
D.Strings[39245]="这个地方真是考古学家的梦想之地！$b$b真希望我能有时间进行一场彻底的考古发掘。"
D.Strings[39246]="这里的地形真可怕！吸饱了地下水的泥土中混杂着许多树根和石块，就像一锅煮糊的麦片粥。黏软的泥浆甚至能把一辆蒸汽坦克吸进去。$B$B我们的设备全都陷在了泥里，还有部落的混蛋不停地给我们捣乱！"
D.Strings[39247]="你需要返回瓦丝琪尔吗？"
D.Strings[39248]="帮助约瑟夫·卡林的部队守卫达隆郡！"
D.Strings[39249]="保护达维·莱法尔！"
D.Strings[39250]="掠夺者霍古斯出现了，快消灭他！"
D.Strings[39251]="雷德帕斯队长出现在战场上了！保护他！"
D.Strings[39252]="约瑟夫·雷德帕斯队长被腐蚀了！快杀死他！"
D.Strings[39253]="同约瑟夫·雷德帕斯谈谈。他就在达隆郡中心。"
D.Strings[39254]="靠后站，$n。我们不想让你$g:这样漂亮的小东西;受伤。"
D.Strings[39255]="是的，请带我去瓦丝琪尔。"
D.Strings[39256]="别害怕。我其实并不像外表显示的这样可怕。$B$B我的名字是阿克莱多斯塔兹，你可以称呼我阿克莱德。我的女王派我到这里来阻止奈法利安。在任务完成之前，我绝不会休息。但这里还有一些敌人守卫着他的巢穴。仅凭我的力量是无法战胜他们的。$B$B请帮我消灭掉他们。阿莱克丝塔萨一定会因此而感激你。也许你还不知道这个名字，但我相信，你总有一天会因为今天帮助了我而感到庆幸。"
D.Strings[39257]="我们不需要再多找点儿见证人吗？"
D.Strings[39258]="我不希望大肆张扬。如此轻率的举动代价高昂，而且仅仅能满足我们的虚荣心而已。但如果你希望庆祝一下的话……"
D.Strings[39259]="不，酋长，这就够了。"
D.Strings[39260]="你知道眼下正是部落的困难时期。我们的补给日渐匮乏。我们的土地日益贫瘠。我们的战士们疲惫不堪。为了部落的利益，这些都是亟待解决的问题。"
D.Strings[39261]="人们会为我们在诺森德取得的成功而感到欣喜。"
D.Strings[39262]="我们的成功？巨魔，部落在诺森德所取得的胜利与你毫无关系。当我带领我们的战士对抗巫妖王时，你只不过在忙着收回几个散落的岛屿。"
D.Strings[39263]="小心你的言行，年轻人。你不会——"
D.Strings[39264]="加尔鲁什！沃金！注意你们的言辞。眼下还有更要紧的事情。"
D.Strings[39265]="请原谅我的无礼。酋长，请继续。"
D.Strings[39266]="尽管我们在诺森德取得了成功，我们却面临着无法用刀剑解决的更大难题。地震使各地战栗不已。元素在乡间肆虐妄为。我能听见我们的大地——听见艾泽拉斯，在痛苦地哀号。"
D.Strings[39267]="这些就是你必须离开的原因。"
D.Strings[39268]="你呢，贝尔蒙特？你要怎样回去？"
D.Strings[39269]="我不会有事的，阿尔苏拉。狼人不知道我们的气味。他们甚至可能不知道我们就在这里。"
D.Strings[39270]="也许我能抢在你们两个……呃……三个前面回到被遗忘者先锋军。"
D.Strings[39271]="现在就行动！绝不能让女妖之王等待。"
D.Strings[39272]="这里的大门永远都向你和你的钱敞开着。"
D.Strings[39273]="就这样吧，再见，贝尔蒙特。"
D.Strings[39274]="天哪……抓紧！"
D.Strings[39275]="兄弟们！攻击这个$r！"
D.Strings[39276]="你不需要和我作战，$r。我对你没有恶意。"
D.Strings[39277]="我可以再次接受你的测试吗，维克斯图？"
D.Strings[39278]="荷尔登示意你到那艘破旧的小船旁边去。"
D.Strings[39279]="能够执行乌瑞恩国王的任务，帮助一位效忠于联盟的战士，这是我的光荣。"
D.Strings[39280]="任何军情七处的朋友也就是我的朋友。你大概不会想要站在我的刀锋所指的地方吧？"
D.Strings[39281]="她被困在了这堆垃圾里，而我已经失去了蒸汽动力。这里的地面太泥泞了！$B$B你能帮我们离开这里么？"
D.Strings[39282]="|TInterface\\Icons\\spell_shadow_shadetruesight.blp:20|t%s开始施放|cFFFF0000|Hspell:82299|h[脓血]|h|r!"
D.Strings[39283]="毋庸置疑，能够为圣光和联盟效忠肯定是一种无上的光荣。"
D.Strings[39284]="这里有一些多余的零件。当你进行修理的时候，我会掩护你！"
D.Strings[39285]="嘿，在孩子们进行修理的时候一定要保护好坦克！我会努力让她动起来……"
D.Strings[39286]="锅炉开始猛烈地冒起了气泡。"
D.Strings[39287]="按照贝蒂娜的要求，倒入一滴液体。"
D.Strings[39288]="倒入一整瓶液体。"
D.Strings[39289]="倒入全部12瓶液体。"
D.Strings[39290]="这些金属可不会像元素对你说话那样对我说话，但我希望你会发现这件武器值得你这样做。乌瑞恩国王和你们的先知都对你的能力有着很大的信心。"
D.Strings[39291]="我上次加工月钢已经是多年以前的事情了，但我还没有忘记这个技术。丹恩，到铁砧旁去等我。"
D.Strings[39292]="你的武器完成了，$n。用它去夺取光荣，为所有联盟的成员树立榜样吧。"
D.Strings[39293]="似乎什么事都没有发生。天灾之锅也许已经被毁掉了，但它看上去的确和以前没什么两样。你要怎样做？"
D.Strings[39294]="什么都不做。贝蒂娜说过，只需要一滴就够了。"
D.Strings[39295]="我们准备好了。麦格尼，是你召集了此次会议。是什么困扰着你？"
D.Strings[39296]="你们肯定已经注意到在过去几周内发生的数次地震。这让我感到有些蹊跷。"
D.Strings[39297]="我们矮人与大地之间存在着联结。我们能感觉到她的痛苦。而大地此刻正在哀号。这些地震……它们既是自然形成但也非全然如此。我想要将你们聚集在一起，共同商讨对策。"
D.Strings[39298]="即使是在达纳苏斯，我们都感到大地有些不对劲。"
D.Strings[39299]="我在诺森德的兄弟布莱恩传来了消息。在他探索奥杜尔的过程中，他见到了一些很不寻常的石板……年代相当久远。"
D.Strings[39300]="那鬼地方没出过什么好东西。"
D.Strings[39301]="这也许恰恰能改变你的看法。此时布莱恩正在将那些石板运送到这里。从探险者协会的初步报告看来，这些石板也许能帮我们理解这些地震背后的真相。"
D.Strings[39302]="我们的顶尖人才一直在探究这些地震活动……嗯，我们主要是在模拟地壳构造转变的同时，研究如何稳固住建筑物的框架……"
D.Strings[39303]="那就是你迁出来的原因吗？"
D.Strings[39304]="哈，才不是呢！尽管这是个令人惊异的巧合。诺莫瑞根一直都在令我们的人民蒙羞。我们早该夺回自己的家园了。"
D.Strings[39305]="嗯，局面在朝着……有利于你和你人民的方向转变，这很不错，大工匠。可并非我们所有人都能如此奢侈地将自己的王国迁走。"
D.Strings[39306]="起来，文森特·高弗雷爵士，重生成为我复仇的工具吧！"
D.Strings[39307]="我又活了……"
D.Strings[39308]="重生的你将效忠于我，高弗雷。我们将一起粉碎狼人的叛乱，为被遗忘者夺回吉尔尼斯。"
D.Strings[39309]="为了部落……"
D.Strings[39310]="是的，当然……"
D.Strings[39311]="那些讽刺我当前处境的话，我都已经听见了，希尔瓦娜斯女王。"
D.Strings[39312]="但就像我说过的那样，死亡也要比变成狼人更好。"
D.Strings[39313]="所以，亡灵要比狼人更好。"
D.Strings[39314]="让你的部队做好准备。吉尔尼斯解放阵线正在格雷迈恩之墙集结。他们的援军很快也会从暴风城赶到。我们不能再浪费任何一分钟了。"
D.Strings[39315]="服从您的命令，女妖之王。"
D.Strings[39316]="盔甲、武器，你所需要的一切都能在我身后的供给站找到。现在，行动吧。"
D.Strings[39317]="你再一次地令我震惊，$n。没有你的帮助，我们绝对不会取得这样的成功。欢迎与我同行……"
D.Strings[39318]="<你可以学习最多两种主要专业技能。请从下列专业技能中选择：>"
D.Strings[39319]="我要接受辅助专业技能训练。"
D.Strings[39320]="<你可以学习所有种类的辅助专业技能。请从下列专业技能中选择：>"
D.Strings[39321]="<数据错误……请前往扎普诺兹医生处获取进一步指示。>"
D.Strings[39322]="守卫攻城坦克！"
D.Strings[39323]="啊，该死的。动起来，动起来啊！"
D.Strings[39324]="好啦！我们成功啦！让我们离开这里。"
D.Strings[39325]="攻城坦克爆炸了！"
D.Strings[39326]="成功了！攻城坦克能够撤退了。"
D.Strings[39327]="能够执行乌瑞恩国王的命令永远都是我的骄傲。我立刻就行动。"
D.Strings[39328]="就是你进入影牙城堡，取得了藏在那里的罕见而且具有强大力量的材料？"
D.Strings[39329]="在你从那座城堡中取得的物品里，有一件很适合做成强大的魔力核心，镶嵌在你的新法杖上。"
D.Strings[39330]="杰萨拉，把那些灰尘和碎片给我。"
D.Strings[39331]="我把那个卷轴放在哪里了？啊，是了，在这里……"
D.Strings[39332]="终于完成了，$n，这是你的法杖。骄傲地挥舞它，为联盟而战吧。"
D.Strings[39333]="当然，鲁坎。给你。"
D.Strings[39334]="你进入了红龙的统治领域。"
D.Strings[39335]="我不知道你是不是为了响应你的新龙喉盟友的号召来到这里。即使不是，我也不会信任你。"
D.Strings[39336]="你很幸运，因为你的命运并不由我来决定。凯伦正在那棵树旁边等着你。"
D.Strings[39337]="我的龙会盯着你。记住，要谨言慎行，$r。"
D.Strings[39338]="你和你的盟友曾经在格瑞姆巴托的大门前攻击我们。对于我们用生命保护的誓言，你们却毫无敬意。我不可能信任你。"
D.Strings[39339]="你一定是乌尔夫所说的那位传奇猎人吧。就连乌瑞恩国王也在关注你。"
D.Strings[39340]="你从那座被诅咒的古老城堡中取得的材料能够制作一张非常强大的弓。"
D.Strings[39341]="我没有恶意，但我觉得你连一头科多兽的肚子都射不中。$B$B我们不应该再浪费彼此的时间了，去找一位合适的训练师吧。"
D.Strings[39342]="嗨，想进行瞄准练习么？"
D.Strings[39343]="给你，$n。一张强有力的弓才配得上你这样天才的猎人。用它为联盟建功立业吧。"
D.Strings[39344]="嗨，$n。想要学习知识吗？我可没有一整天的时间跟你耗……"
D.Strings[39345]="嘿，你学不会施法可不是我的错。\n\n去找个$c训练师吧，好吗？"
D.Strings[39346]="这里没什么可看的，朋友。为什么不到别处去逛逛？"
D.Strings[39347]="我听说你走了很远的路才来到这里，朋友。也许你需要更多一些训练？"
D.Strings[39348]="什么？我看上去像个$c吗？$B$B请让开一点，好吗？"
D.Strings[39349]="看起来很不错，小孩。$B$B你说什么？想进行训练？"
D.Strings[39350]="你需要什么？$B$B太糟糕了。我可帮不了你，$c。"
D.Strings[39351]="“为了乐趣和利润控制元素。”$B$B这就是重点所在，同意我的话吗？让我们开始吧。"
D.Strings[39352]="听着，你不会想知道我到底掌握着什么。$B$B别以为我在开玩笑。那种力量能融化你的大脑。去别的地方，找些好玩的事情吧。"
D.Strings[39353]="你会喜欢恶魔能量的：廉价，能够恢复，而且肯定能把你痛恨的东西炸碎。$B$B当然，你也会因此而必须面对一些东西——那种超越时间和空间的，难以想象的恐怖。你可能会因此而永远丢失你的心智。不过只有冒险才能得到巨大的回报！$B$B那么，你想让我教你些什么，嗯？"
D.Strings[39354]="试炼于此时开始。勇士们！奋勇拼杀，击败那三个敌人！"
D.Strings[39355]="热身结束了。现在，真正的试炼开始了！"
D.Strings[39356]="只有我死了，你才能从我的手中夺走达拉然大法师的遗物！"
D.Strings[39357]="事情不应该这样！我只是想再见到我的家人……同他们分享这份礼物！"
D.Strings[39358]="他们将为抛弃我们的行为付出代价。把我们丢在这里，任由我们在凶残的不死亡灵间腐烂……"
D.Strings[39359]="我要走了。我没有理由留在这里。也许我是个亡灵，但我拥有属于自己的意志。"
D.Strings[39360]="我在另一个世界里的绿野上等你，$n。"
D.Strings[39361]="干得好，英雄们。你们已经通过了我的战斗测试。"
D.Strings[39362]="祝你好运。"
D.Strings[39363]="来吧，我们走！"
D.Strings[39364]="塔伦纳，你这个傻瓜！礼拜堂还在二十码以外！我们快走！"
D.Strings[39365]="我们能走了吗，塔伦纳？我想要加入北伐军！"
D.Strings[39366]="<次元之门发出“嗡嗡”的响声。>"
D.Strings[39367]="<使用安伯米尔次元传送门。>"
D.Strings[39368]="拉响警报！入侵者穿过了传送门！"
D.Strings[39369]="我……*咳嗽*谢谢你，陌生人。"
D.Strings[39370]="我欠你一条命。在和死亡之翼的战斗中，我的人民已经付出了高昂的代价。"
D.Strings[39371]="$r，我以前只在故事里听到过你们。真没想到，我竟然会被你救了一命。"
D.Strings[39372]="奴仆们，消灭入侵者！绝对不能让护盾被摧毁！"
D.Strings[39373]="你不会成功的，怪物！"
D.Strings[39374]="我们……绝不……放弃！"
D.Strings[39375]="联盟的军队将踏碎你们！"
D.Strings[39376]="洛丹伦属于联盟。你们只是在拖延无可阻挡的命运……"
D.Strings[39377]="跑啊！别让他们转变你！"
D.Strings[39378]="跳上来，$n。我们走！"
D.Strings[39379]="希望你们联盟能给这里的龙喉兽人狠狠一击。"
D.Strings[39380]="这里的情况你已经很清楚了，朋友。跟我来，我们找出到底谁是这里的头领。"
D.Strings[39381]="我简直无话可说了！库德兰·蛮锤就出现在我眼前。他还活着！"
D.Strings[39382]="必须承认，当我接到酋长的命令时，完全没有想到来的人会是你。"
D.Strings[39383]="如果你能赢得酋长的尊敬，那么你一定是有些过人之处。如果你能拿起这件武器，它就是你的了。"
D.Strings[39384]="也许当你拥有一件合适的武器，你就不需要过于依赖你的咒语了。"
D.Strings[39385]="对于你这样的人，外表实在是一种欺骗。别担心，我会打造适合你的战斗风格的武器。"
D.Strings[39386]="你显然能够和元素进行顺畅的交流。等我的工作完成之后，你就会有一件精良的武器。它能帮助你充分施展元素的力量。"
D.Strings[39387]="我已经有许多年没有加工过月钢了。不过这种技艺是不可能被忘记的。学徒们，是时候显示你们锻打真正金属的能耐了！"
D.Strings[39388]="朋友，蛮锤部族的情况如何？我们有很多事情要谈！"
D.Strings[39389]="别管它了，Crablegs。这太费时间了！"
D.Strings[39390]="你的武器完成了。正是因为你对部落的忠诚，我们才会将努力工作的成果赠送给你。用它来让我们的敌人胆战心寒吧！"
D.Strings[39391]="空间障碍物被打破了！现在，展开进攻！为了女妖之王！"
D.Strings[39392]="起来，法师！重生为被遗忘者吧！"
D.Strings[39393]="即使我是酋长真正的忠仆，他也不会轻易给我奖励。他的智慧指引着我的战锤。"
D.Strings[39394]="伊莉莎很美……真是很美……"
D.Strings[39395]="我的鸟！闪电——他们射中了她！那些肮脏的野兽从天空中射中了她！"
D.Strings[39396]="可怜的闪电。她需要一段时间才能复原。"
D.Strings[39397]="还有那些对这些地震的危险性了解得一清二楚的人。我们唐突的着陆让埃索达时至今日都还在震颤。"
D.Strings[39398]="……因为从好的方面说，这可能是个便利的装置——“摇晃器2000型”。可是另一方面，我们侏儒最不愿看到的就是丹莫罗群山崩塌，将铁炉堡压成碎片。"
D.Strings[39399]="好吧。准备好飞翔了吗？"
D.Strings[39400]="虽然我们想要组织人民进行迁移，但我不知道是否能做得到。我们已经接到报告，元素出现在各个地方，向我们发动袭击。无论城镇还是郊野，无一能够幸免。迁移也许不是个好选择。"
D.Strings[39401]="嗯，至少还有那么点儿好消息……无意冒犯，格尔宾。震颤似乎也引起了大地之环的注意。就连蛮锤萨满祭司都伸出了援手。"
D.Strings[39402]="也许辛德拉的上层精灵也是因此赶来的。"
D.Strings[39403]="这个世界仿佛正在破碎。我曾在德拉诺见过这些征兆……我们也许无力阻止这场灾难。逃生或许是我们最好的选择。"
D.Strings[39404]="逃生可不是我眼下愿意采纳的方案。我们会想出其它办法来的。也许这些来自奥杜尔的石板能帮我们更好的理解当前的困境。"
D.Strings[39405]="希望我们能尽快找到答案。这里的人民惊惧不已，而教徒们正在利用他们的恐惧。"
D.Strings[39406]="这些教徒只是在使问题更加恶化。他们到处鼓吹末日论，或是宣扬世界正在遭受新生前的剧痛……他们极尽夸张之能事，让人们无法听而不闻。"
D.Strings[39407]="真是困难时期啊。对未知的恐惧会导致人们做出蠢事来。"
D.Strings[39408]="而我们找不到答案，这只会激起人们更大的困惑。"
D.Strings[39409]="所以我们更有理由对此追根究底。来自奥杜尔的石板将为我们指出正确的方向。布莱恩对这一点非常坚信。如果布莱恩坚信，那我也一样。"
D.Strings[39410]="我已经说过，凡是跟大地有关的事情都别跟矮人争。要是铜须家族的人相信这块石板能解决困扰大地的难题，那我们就该尽力支持他们。"
D.Strings[39411]="冒险者都是伪君子！难道你是刚刚在路边拣到了你的武器吗？"
D.Strings[39412]="在奥格瑞玛的其它地方，你再也无法找到比这个更好的火器了。"
D.Strings[39413]="奥玛克告诉我，你会来的，$n。"
D.Strings[39414]="你从影牙城堡拿出来的这些材料绝非凡品。它们能够让你的武器具有强大的力量。"
D.Strings[39415]="你的弓完成了，$n。希望它能为你建立伟大的功勋，就如同你为部落建立的伟大功勋一样。"
D.Strings[39416]="夏格，你是不是把我要的那些配方和材料收起来了？"
D.Strings[39417]="这样应该就能完成附魔步骤了。$n，给你新的法杖。用它来为部落建功吧。"
D.Strings[39418]="主人，我已经为您把它们搜集好了。"
D.Strings[39419]="洛甘纳尔说你会从影牙城堡带来强大的宝物。一开始，我还在怀疑你能弄些什么东西出来。"
D.Strings[39420]="我什么都不告诉你，$r混蛋！"
D.Strings[39421]="我不害怕死亡和你的暴行，$r！"
D.Strings[39422]="现在这个矮人属于我们了！滚开吧！"
D.Strings[39423]="当我看到这些物品的时候，我就感觉到了洛甘纳尔所说的那种强大力量。它们可以被做成一件适合于你的精良武器。"
D.Strings[39424]="病木林实在是太大了！你的朋友失踪了！你绝对不可能找到他！"
D.Strings[39425]="她绝对不会将那个矮人还给你！"
D.Strings[39426]="愚蠢的$r！你在找那个矮人？安娜丝塔丽已经妥善地把他藏起来了！"
D.Strings[39427]="你绝对无法阻止我们！"
D.Strings[39428]="你绝不可能阻止天灾！"
D.Strings[39429]="死亡对我毫无意义，$r！"
D.Strings[39430]="哦，天哪……这次的作品甚至远比我想象的更加强大。"
D.Strings[39431]="议会将这支法杖给你，就是将一件拥有强大力量的宝物放在你手中，$n。你要用它来守卫我们所信奉的原则。"
D.Strings[39432]="刮取"
D.Strings[39433]="$n突袭了磨坊！"
D.Strings[39434]="联盟占领了磨坊！"
D.Strings[39435]="部落占领了磨坊！"
D.Strings[39436]="$n守住了磨坊！"
D.Strings[39437]="$n突袭了磨坊！如果不赶快采取行动的话，联盟将在1分钟内占据它！"
D.Strings[39438]="$n突袭了磨坊！如果不赶快采取行动的话，部落将在1分钟内占据它！"
D.Strings[39439]="联盟占领了矿洞！"
D.Strings[39440]="部落占领了矿洞！"
D.Strings[39441]="$n突袭了矿洞！如果不赶快采取行动的话，联盟会在1分钟内控制它！"
D.Strings[39442]="$n突袭了矿洞！如果不赶快采取行动的话，部落会在1分钟内控制它！"
D.Strings[39443]="$n突袭了灯塔！"
D.Strings[39444]="联盟占领了灯塔！"
D.Strings[39445]="部落占领了灯塔！"
D.Strings[39446]="$n守住了灯塔！"
D.Strings[39447]="$n突袭了灯塔！如果不赶快采取行动的话，联盟将在1分钟内占据它！"
D.Strings[39448]="$n突袭了灯塔！如果不赶快采取行动的话，部落将在1分钟内占据它！"
D.Strings[39449]="我们已经做出保证，要打开一个从暴风城前往高地的元素通道。但暮光堡垒的干扰让我们无法成功。$B$B他们到底在那里发什么疯？"
D.Strings[39450]="届时，他们将放出风水两种元素，用狂风暴雨吞没整座城市，为我们主人的荣归搭设舞台！"
D.Strings[39451]="取得斥候的日志。"
D.Strings[39452]="什么时候才能结束？"
D.Strings[39453]="地震！"
D.Strings[39454]="我们死定了！"
D.Strings[39455]="我发现了一个令人难以置信的地方！$b$b这里到处都闪耀着古代文明的光辉。$b$b如果不是因为今天太晚了，我真想立刻就对这座建筑展开调查！$b$b今晚估计我要睡不着觉了……"
D.Strings[39456]="为什么会这样？"
D.Strings[39457]="拜托……阻止这一切吧。"
D.Strings[39458]="以风、水、地、火之力……我们将前往暴风城，$n！"
D.Strings[39459]="传送门打开了！感谢你的帮助，现在我们能够从暴风城迅速到达暮光高地了。"
D.Strings[39460]="没有什么比在高空中翱翔更令人兴奋了。$B$B嗯，也许在飞翔时战斗会更好，最好在战斗之后还能喝上一杯上好的啤酒！"
D.Strings[39461]="安古斯，我来这里是为了领导蛮锤小队，空降军情七处的人员。"
D.Strings[39462]="为什么你不早说？替我给那些暮光异教徒狠狠来一下子，好不好？"
D.Strings[39463]="如果有人告诉你天灾军团被打败了，不要信他的话。看看吧……难道他们不是仍然在病木林横行肆虐吗？他们死守着他们的腐蚀之地，如同儿童拼命抓住自己的小床。$b$b我别无选择，只能战斗。在我呼出最后一口气之前，我绝不会停止和他们的战斗。"
D.Strings[39464]="我们正在调查这些邪教徒组织。"
D.Strings[39465]="我们正在调查你所提交的失踪人口报告。"
D.Strings[39466]="一旦有消息，我们会即刻通知你。"
D.Strings[39467]="我们在竭尽所能。"
D.Strings[39468]="情况在我们的掌控之中。"
D.Strings[39469]="我们当下正在对邪教徒的活动进行调查。"
D.Strings[39470]="我们在以非常严肃的态度处理这些失踪人口报告，女士。"
D.Strings[39471]="我们派出了精英团队调查这些问题。"
D.Strings[39472]="他们……他们全都死了？"
D.Strings[39473]="他们从阴影中发动攻击。我们连反抗的机会都没有。"
D.Strings[39474]="你一定就是那个所有人都在谈论的英雄。谢谢你。"
D.Strings[39475]="你们这群卑鄙的邪教徒夺走了我的丈夫！他就这样丢下我们，去追随你们所鼓吹的那些“末日论”鬼话了！"
D.Strings[39476]="他们到处都是！你一定要小心！"
D.Strings[39477]="我们听到了他们的命令……不留任何活口……"
D.Strings[39478]="滚开！你们夺走了我的丈夫，这还不够吗？还想怎么样？"
D.Strings[39479]="带着你们邪恶的鬼话离开这座城市！别想再用虚假的“预言”骗走更多市民了！"
D.Strings[39480]="懦弱的狗子。回到你妈妈那里去，好好地躲起来吧。"
D.Strings[39481]="黑暗女王会让这些渣滓活着？除非……"
D.Strings[39482]="你们用谎言毒害的人还不够多吗？离我远点儿！"
D.Strings[39483]="我要把这个地方和他们一起烧光……"
D.Strings[39484]="这些懦弱的士兵应该在羞耻中死掉。真是巨大的羞耻。"
D.Strings[39485]="别让我看到你，否则我就对你执行死刑！"
D.Strings[39486]="$g他:她;死在了战场上。低下你们的头……"
D.Strings[39487]="这也是一种仁慈。"
D.Strings[39488]="懦夫不应该回家。"
D.Strings[39489]="没用的蛆虫。"
D.Strings[39490]="$c，你将拥有这座半岛。$B$B你将成为一件武器。$B$B你将成为带来胜利的战争之神。"
D.Strings[39491]="带着你的谎言滚吧，邪教徒。你对我们造成的伤害已经够多了！"
D.Strings[39492]="今天可真是成果丰硕！$b$b这座建筑果然有着古老的起源，里面还有年久失修的宏大装置。$b$b我明天再来详细调查一番。$b$b这个发现肯定会让Schnottz注意到我！$b$b经过这件事，他怎么能不嘉奖我呢？"
D.Strings[39493]="我花了一整天的时间去研究这些秘密符号：$b$b$b通过湛蓝的双眼星光$b在闪现。$b$b十块碎片一根棒，纱幕$b消失不见。$b$b$b忘了Schnottz和他那些虚无的承诺吧！$b$b要是我能破解这些密语，其中所包含的秘密就是我的！"
D.Strings[39494]="报告！"
D.Strings[39495]="我成功了！$b$b利用从这座建筑物的装饰上取得的蓝宝石，我拼出一副眼镜。我能够通过它看到……无比神奇的东西！$b$b运气好的话，我在写下一篇日记的时候就会是一个富翁了！"
D.Strings[39496]="经过一番快速的查看，你确定这个人刚刚死了几个小时。"
D.Strings[39497]="他们……太多了！"
D.Strings[39498]="到降落点去！"
D.Strings[39499]="蛮锤！"
D.Strings[39500]="让我们把这些人类送到降落点去。"
D.Strings[39501]="我们需要照亮这里的路面。"
D.Strings[39502]="抓紧。颠簸会非常剧烈！"
D.Strings[39503]="我要向你说明白……我们不是在为你们提供出租车服务！"
D.Strings[39504]="有些人只想看着这个世界燃烧。而另一些人更要亲手把它点燃……"
D.Strings[39505]="通过熊熊烈火，我们净化了这片大地上的杂质。"
D.Strings[39506]="一切化为灰烬……用不了多久，吉尔尼斯和狼人的污染都将不复存在。"
D.Strings[39507]="臭气熏天的双头魔！"
D.Strings[39508]="暮光之锤去死吧！"
D.Strings[39509]="为了库德兰！"
D.Strings[39510]="我们要不惜一切代价，阻止古加尔制造出他的终极武器，就算这意味着我们要牺牲自己的生命。"
D.Strings[39511]="我们出来了。真是好运气！"
D.Strings[39512]="幸好有我们的团结奋战！"
D.Strings[39513]="消灭那些双头魔，这样我们才能回来完成工作。"
D.Strings[39514]="我们在胜利者岗哨见！"
D.Strings[39515]="他们从各个方向朝我们发动攻击，朋友！"
D.Strings[39516]="他们数量太多了，朋友！"
D.Strings[39517]="暮光渣滓！"
D.Strings[39518]="为我消灭他们！"
D.Strings[39519]="有人需要减重了，朋友。"
D.Strings[39520]="我们到降落点去！"
D.Strings[39521]="刺客？我们只需要在他们头顶上丢几颗火焰炸弹！"
D.Strings[39522]="我们为什么要提供出租车服务？难道你不能偷偷溜到那里去吗，朋友？"
D.Strings[39523]="好啦，好啦。我们离开这里，朋友！"
D.Strings[39524]="再见啦！"
D.Strings[39525]="你要消灭那些双头魔，这样我们才能回来完成工作，朋友！"
D.Strings[39526]="我们粉碎者据点见。"
D.Strings[39527]="没有任何事情能比飞到敌人头顶上，向他们“轰隆轰隆”地扔炸弹更痛快的了！$B$B把两百五十磅的兽人扔到敌人头顶上也不错。对不对，朋友？"
D.Strings[39528]="乔乔，我到这里来是为了领导你的双足飞龙小队，空降库卡隆刺客。"
D.Strings[39529]="我刚喝下一瓶治疗药水！暂时无法再使用药水了！"
D.Strings[39530]="嘿，你干嘛不早说？教训教训那群暮光之锤，回来之后我们好好庆祝一下！$B$B我跟我的夫人在海滩上筑了个温馨的小窝。记得来串门！"
D.Strings[39531]="风行者女王亲自派我来，作为部落的使者与扎伊拉和龙喉氏族联系。女王和那位新酋长加尔鲁什正在试图修复他们的关系。$B$B不管怎样，我们必须彻底结束暮光的威胁。而最重要的是，我们必须阻止古加尔制造出他的终极武器。"
D.Strings[39532]="|TInterface\\Icons\\ability_warrior_shieldreflection.blp:20|t欧泽鲁克开始施放|cFFFF0000|Hspell:78939|h[源质壁垒]|h|r！"
D.Strings[39533]="太好了！真高兴你在这里，$n。我们有许多事要谈。"
D.Strings[39534]="看，卡修斯，我早就和你说过，我们可以指望$n。"
D.Strings[39535]="我们蛮锤是一个光荣的部族。相信你在联盟中一定也有同样的光荣，$n。"
D.Strings[39536]="我的$g男孩:女孩;回来了！$n，战况如何？"
D.Strings[39537]="真高兴又看到你了，$n。期待我们能再次并肩作战。"
D.Strings[39538]="那些暮光渣滓坚持不了多久了。龙喉氏族为此已经等待了太长的时间，$n。"
D.Strings[39539]="看，柯丝温，我早就和你说过，我们可以依靠$n。"
D.Strings[39540]="龙喉氏族与部落并肩作战，这是我们共同的荣耀。暮光堡垒一定会被攻陷，$n！"
D.Strings[39541]="炎魔之王终将为艾泽拉斯带来末日！你们将成为他怒火中的灰烬，蠢货！"
D.Strings[39542]="我觉得有些混乱。我并不习惯这种……情况。"
D.Strings[39543]="克罗雷？我认识他。在我们的国土遭受诅咒之前，他只不过是一名罪犯。而现在，他成为了伟大的狼人英雄？真令人作呕……"
D.Strings[39544]="血牙？首先对吉尔尼斯发动攻击的正是血牙的狼人。那个怪物和他的爪牙们已经在这片土地上横行肆虐了许多年。"
D.Strings[39545]="按照我说的去做，这场战争将顺利结束。当然，我们不应该太在意死在洛丹伦的那些狼人。"
D.Strings[39546]="我做梦也没有想到过我们的“国王”会背叛我们。只要想到他在统治我们的时候已经秘密地变成了一个狼人，我就想呕吐……"
D.Strings[39547]="“结束了，高弗雷……”这就是他在我跳下悬崖之前对我说的最后一句话。格雷迈恩，没有结束！我又活了！"
D.Strings[39548]="当我们杀死狼人的时候，总会把它们烧死，这样才能确保它们不会重新活过来。"
D.Strings[39549]="吉尔尼斯已经变成了一个不可能实现的梦。只有真正有眼光的人才能看清这一点……而格雷迈恩？绝不可能……"
D.Strings[39550]="天哪，灰葬，看看你自己。你的腿骨都突出来了。"
D.Strings[39551]="我可不会让这种小麻烦来困扰我自己，高弗雷。记得么？这是一份“礼物”。现在，好好享受这份“礼物”，闭上嘴吧。"
D.Strings[39552]="他们应该已经烧掉了我该死的尸体。"
D.Strings[39553]="作为被遗忘者，自然有其好处。让我想想……我能活在水下面。比起有血肉的凡人，我的潜水时间要长233%%。没错，233%%，很值得惊叹吧。"
D.Strings[39554]="哦，现在我还能轻松地摆脱意识控制效果——因为我根本没有脑子！！！"
D.Strings[39555]="也许，最好的一件事就是我开始渴望其他人形生物的血肉了。吃掉他们腐烂的尸体能够让我获得力量，而且那种东西非常好吃……"
D.Strings[39556]="毫无疑问，这是高弗雷的错。"
D.Strings[39557]="我一直都很喜爱银松森林——直到巫妖王放出他的天灾大军，将这片土地变成了一个腐烂的巨大尸坑。现在，每当我再看到它，血管里的绿色血液也禁不住要沸腾。"
D.Strings[39558]="说话简略一些。我可没心情听什么抱怨和闲聊。"
D.Strings[39559]="我失去理智了。我没办法让精神集中起来……"
D.Strings[39560]="现在我的体内只剩下了愤怒。"
D.Strings[39561]="我不仅仅是被遗忘者……不仅仅是一个人……我是某种全新的，某种……不同的。"
D.Strings[39562]="出……？出了什么事？你们是谁？"
D.Strings[39563]="救命！救命！我被怪物捉住了！"
D.Strings[39564]="哈！你不认识我们了，德姆西？我是高弗雷。在我身边的是沃登和灰葬男爵。我们刚刚“救了”你，而你却连句感谢的话都没有？"
D.Strings[39565]="入侵者，停止你的盗窃行为！"
D.Strings[39566]="你正踏在神圣的土地上！而你必须被彻底净化！"
D.Strings[39567]="我们已经立下效忠的誓言，入侵者。你也必须一样。"
D.Strings[39568]="你……你救了我？我是个被诅咒的怪物！你也是个被诅咒的怪物！看看你自己吧！"
D.Strings[39569]="那些珍爱星光的人必须永远保护它！"
D.Strings[39570]="我曾经是一名盗贼，现在则是群星的仆人。"
D.Strings[39571]="欢迎你接受这份永恒的任务，盗贼。"
D.Strings[39572]="你一直都是个没骨气的懦夫，德姆西。"
D.Strings[39573]="你在引发混乱之后，无法自行打开后门逃走。你可以选择的方案有：杀死酒吧客人，让卫兵打开后门；或者让罗克诺特下士喝醉，这样他会进行破坏；或者是看看普拉格的身上有没有钥匙！"
D.Strings[39574]="死亡之翼回来了，他已经控制了格瑞姆巴托和这片高地的很大一部分。我已经无力阻止他了。$B$B我们的女王很快就会到来，我们将齐心协力，把那个曾经的大地守护者赶回他应在的位置上。"
D.Strings[39575]="那是什么？！"
D.Strings[39576]="除了雾气之外，这里什么都没有！"
D.Strings[39577]="继续战斗！我要到顶上去和古加尔谈谈！"
D.Strings[39578]="我监视黑铁矮人已经有很长时间了……我谋划，期待，希望着能有机会驱逐他们，夺回我的家园。$B$B他们可以保留黑石山。我希望那座山会再次爆发，彻底毁灭他们。我想得到现在被称为燃烧平原的那个地方，那里本来是赤脊山脉中属于我的那一部分，却被他们的烈焰统治者摧毁了。$B$B$C，我要让全世界知道，我的国土上到底蕴含着怎样的力量。我会在他们留下的死亡与欺诈之上建立一个和平公正的王国。我的守望已经结束。现在我要奋勇作战，夺回应属于我的东西。$B$B为此，我将不惜牺牲自己的生命。"
D.Strings[39579]="刺客！我要把你们的牙齿都打出来！"
D.Strings[39580]="别想逃脱惩罚，你这个丑陋，恶心的巫婆！"
D.Strings[39581]="哦，真的？你还能做些什么，矮人？这里可没有人能救你。"
D.Strings[39582]="你错了，女妖。我们就是要带吉德文回去的。"
D.Strings[39583]="就你们两个？你们根本没有机会。"
D.Strings[39584]="我可不敢苟同。"
D.Strings[39585]="很难向龙喉兽人解释“火力覆盖”和“压制炮火”这样的概念。$B$B幸运的是，他们很清楚什么是“杀”和……嗯……“杀光”。"
D.Strings[39586]="我请求援军来帮我们守住海滩。结果部落就派来了这群小不点儿和他们的小金属管。$B$B<格拉洛克不屑地看了看身边的地精。>"
D.Strings[39587]="女妖之王派遣了刺客？"
D.Strings[39588]="罗娜，这就是你向老朋友问候的方式？"
D.Strings[39589]="高弗雷？那么，那些传闻是真的了？"
D.Strings[39590]="你真的要背叛你的王国？"
D.Strings[39591]="我的王国？我的王国已经不复存在了。"
D.Strings[39592]="这就是你的父亲和格雷迈恩所做的一切……不，当他们允许那些怪兽肆意作恶的时候，吉尔尼斯就已经死了。"
D.Strings[39593]="现在，放下武器投降吧。我们来这里不是为了杀你。至少现在还不是。"
D.Strings[39594]="哈！那就先杀了我再说吧！去死吧！"
D.Strings[39595]="这座要塞相当坚固，但我们的敌人从四面八方攻击我们。我们必须先在海岸上站稳脚跟，才能向内陆挺进。"
D.Strings[39596]="赶快！我们必须在被发现之前返回被遗忘者先锋军！"
D.Strings[39597]="火焰之地的英灵，让你的愤怒充满我的身躯！"
D.Strings[39598]="我们将永远纪念卡加斯·刃拳，为了他曾经为部落所做的一切。他是有史以来最优秀的战士之一。即使是联盟也不能否认这一点。$B$B卡加斯远征军以他为名，也以他为荣。我们将在他的名义下，驱逐黑铁矮人，夺回黑石山以及其周围区域。这些都是应该属于部落的国土。$B$B你将成为酋长对抗索瑞森的有力武器。这也是属于你的巨大光荣。"
D.Strings[39599]="天空之牆的英灵，听从我的召唤！"
D.Strings[39600]="深岩之洲的英灵，给予我你的力量！"
D.Strings[39601]="看样子，他们已经找到了回家的路。我终于放心了。$b$b你也回来了！有兴趣加入我们吗？"
D.Strings[39602]="顺便说一句，马车里的物资随你使用……只要你在用完之后把它们拿回来！"
D.Strings[39603]="我希望能有一天，在圣光之愿礼拜堂建起一座商店。我对战斗不在行，但这并不意味着我就不能帮上任何忙。"
D.Strings[39604]="那些男孩和我只是一同旅行了很短一段时间，但我已经无法想象没有他们相伴的生活了。"
D.Strings[39605]="希望你随意使用我的马车里的物品。只要不是我们正在使用的物品，你都可以借走。"
D.Strings[39606]="为什么他会那样逃走？！"
D.Strings[39607]="向我保证，你一定会找到他，$n。"
D.Strings[39608]="<菲奥拉显得非常不安，没有半点说话的心情。>"
D.Strings[39609]="很高兴能再见到你，$n！"
D.Strings[39610]="嗨，$n！你是来这里看望我们，还是要买些东西？"
D.Strings[39611]="哈哈，看看谁来了！"
D.Strings[39612]="真无法相信，我们竟然就这样停下了！我们在这里还有任务要完成呢！"
D.Strings[39613]="为什么我们还不离开？如果你们不走，我就要自己走了。"
D.Strings[39614]="出了什么事，菲奥拉？"
D.Strings[39615]="好了，吉德文……深呼吸……"
D.Strings[39616]="$R！你的尸体会被扔进大海。"
D.Strings[39617]="迫击炮弹幕！"
D.Strings[39618]="拿起这名斥候的眼镜。"
D.Strings[39619]="没用的血精灵！我们还有任务，而他却在浪费我们的时间！"
D.Strings[39620]="我不知道为什么要容忍他。他从来没有对一件事认真过。"
D.Strings[39621]="泰罗索斯亲自派我们前往北谷！为什么我们却要和那些猖狂的蛛魔浪费时间？！"
D.Strings[39622]="如果他再耽搁我们，我就把锤子敲到他的脑袋上。"
D.Strings[39623]="吉德文就在附近……我知道。这是圣骑士的直觉。"
D.Strings[39624]="我们一定要为母亲复仇！\n\n是那个怪物杀了她，转移他的注意力，把我们从笼子里放出去，我们就会与你并肩作战。\n\n我们能减少敌人造成的伤害，帮你顶住原龙巨兽的灼热气息。"
D.Strings[39625]="就连我这样的人都会被那个蠢笨的呆子捉住。而你却能一直闯到这里，你一定是个非常勇敢的家伙。\n\n如果你能转移哈尔弗斯的注意力，并且打断捆绑我的锁链，我就会和你一同战斗。\n\n我可以让一个敌人失明，这一定能帮助你抵抗哈尔弗斯的狂乱攻击。"
D.Strings[39626]="就连我这样的人都会被那个蠢笨的呆子捉住。而你却能一直闯到这里，你一定是个非常勇敢的家伙。\n\n如果你能转移哈尔弗斯的注意力，并且打断捆绑我的锁链，我就会和你一同战斗。\n\n我可以让一个敌人暂时麻痹，这一定能帮助你抵抗哈尔弗斯的致伤打击。"
D.Strings[39627]="就连我这样的人都会被那个蠢笨的呆子捉住。而你却能一直闯到这里，你一定是个非常勇敢的家伙。\n\n如果你能转移哈尔弗斯的注意力，并且打断捆绑我的锁链，我就会和你一同战斗。\n\n我能够用狂乱的暴风缠住一名敌人，这一定能影响哈尔弗斯施放暗影新星。"
D.Strings[39628]="哦，啊……你好，善良的旅行者！我这个好地精能为你做些什么？$b$b我向你保证，我会独自来到圣光之愿礼拜堂，是因为我像这些银色北伐军一样痛恨天灾军团。绝对不是因为我在一次令人羞愧的飞艇坠毁事故中逃跑了！$b$b嗯，我还是闭嘴吧。俗话说，言多必失嘛。"
D.Strings[39629]="你提供了一个有趣的选择，$r。我会好好考虑一下。$b$b好吧，我考虑好了。我会与你同行。也许我在圣光之愿礼拜堂已经待了太长时间。我已经准备好要行动了！呵呵！"
D.Strings[39630]="如果你想找个地方躲起来，那么尽可以到我们的马车上来。"
D.Strings[39631]="嗨，老板，如果你需要有人帮你赶马车，就和老比吉尔说一声。"
D.Strings[39632]="践踏者，守卫你们的酋长！"
D.Strings[39633]="劫掠者们，到我的身边来！"
D.Strings[39634]="地卜师，用岩石和烈火埋葬他们！"
D.Strings[39635]="让T.A.D.单位对准优先目标！"
D.Strings[39636]="对准次级目标！"
D.Strings[39637]="你将为自己的罪行受到惩罚，盗贼！"
D.Strings[39638]="真高兴又看见你了，$n。当你准备对大门发动进攻的时候，我们中的一些人也潜入到这里。$B$B我们计划在这里与肖尔大师碰面。$B$B<那名小队长拿出一张暮光堡垒的地图，指出那个地点。>$B$B等你准备好之后就告诉我，我们将并肩作战。"
D.Strings[39639]="我准备好了，指挥官，我们出发吧。"
D.Strings[39640]="让他们尝尝厉害！"
D.Strings[39641]="放松放松，消费一下……我们这里什么都有——兑钱商、洗衣店、异国美酒，你可以享受到一流的服务。$B$B如果有人找你麻烦，就来找我，我会为你处理的。$B$B我是米达……大老板米达。$B$B噢，修理？当然，我很愿意以一个合理的价格来帮助我们的新盟友。"
D.Strings[39642]="看看这里……这里的生意是多么兴旺啊！$B$B当加里维克斯还为他在艾萨拉荒地的花哨宫殿选墙纸的时候，我已经在为老大挣取双倍的利润了。$B$B听我说：数数这里的房子、货栈、各种建筑和维护设施；看看这里的战争工事和补给线……$B$B这一切都还只是刚刚开始！兽人能打仗，但他们不懂得后勤运输。我的人搞运输的速度比他们快两倍，成本却只有他们的一半！好吧……前提是运输途中不出意外。$B$B不管怎样！在这里你可以尽情享受。放松放松，消费一下……我们这里什么都有——兑钱商、洗衣店、异国美酒、钓鱼训练师，你可以享受到一流的服务。"
D.Strings[39643]="旅途中有人作伴的感觉真好。否则一路上孤孤单单的。"
D.Strings[39644]="$n，前进！我们会击退联盟狗，为被遗忘者占领洛丹伦！为了部落！"
D.Strings[39645]="现在还不行，$g小伙子:姑娘;。$B$B我还要调试老板的伐木机。$B$B她可不喜欢像那些老木头一样徒步在城周围走来走去，特别是在她要去对付那个酋长的时候。"
D.Strings[39646]="我要把你们的城市夷平，把你们碾碎！"
D.Strings[39647]="放下武器投降！"
D.Strings[39648]="格雷迈恩之墙！我们要把他们逼入绝境。"
D.Strings[39649]="是的，我将动身前往纳格兰，去了解那里的元素。它们也遭受着痛苦，并且见到了许多像这样的征兆。"
D.Strings[39650]="你准备去多久？"
D.Strings[39651]="也许要花些时间才能弄清我必须要了解的。我相信我不会离开很久，但可能也要几个星期——甚至几个月。"
D.Strings[39652]="在我离开的这段日子里，我命令你——加尔鲁什·地狱咆哮，担任部落的领袖。你凭借力量与勇气一定能率领我们的人民在这困难时期生存下去。"
D.Strings[39653]="我很荣幸，酋长。但我还没准备好担任统治者。"
D.Strings[39654]="你并非孤身一人。会有顾问从旁协助你——凯恩、伊崔格和沃金，他们会指引你的。"
D.Strings[39655]="而且尽管我很快就要离开，我也可以指点你一些。"
D.Strings[39656]="就先拿这群邪教徒小试牛刀吧。人们恐慌不已。他们不知道发生了什么事。"
D.Strings[39657]="可就连我们也不知道这究竟是怎么一回事。我们该不该把这些邪教徒抓起来，让他们闭嘴？但那会激怒剩下的人……尽管如此，我们决不允许教派恣意散播恐惧与谎言……"
D.Strings[39658]="现在你已经像统治者那样思考了，加尔鲁什。你必须全面地分析问题。听听你顾问的意见，信心满满地展开行动吧。"
D.Strings[39659]="他们会帮你的，加尔鲁什。我也会帮你。我一定会找到我们要找的答案，来消除人们的恐惧，安抚躁动的元素。"
D.Strings[39660]="我不会让你失望的，酋长。我会尽我所能管理好部落，并与你推荐的顾问多加沟通。我深知你所赋予我的是一份极大的荣耀，我会全力以赴，让自己无愧于此。"
D.Strings[39661]="那就这样吧。"
D.Strings[39662]="确保你所做的一切都是为了部落。"
D.Strings[39663]="在病木林深处很少会有访客。通常都是憎恶。$b$b我能帮你什么忙吗？"
D.Strings[39664]="将军在上一次海战中不幸遇难。我把他的舰船改造成了堡垒。$B$B这只是个应急方案，$c。"
D.Strings[39665]="记住——地狱咆哮的双眼在注视着你，$n！"
D.Strings[39666]="从石板上的秘密符文看来，有办法让这装置重新焕发活力。$b$b我们只需要想出该如何做……"
D.Strings[39667]="看来你的前人已经把信号弹搭好了，但还没来得及发射。$b$b现在看你的了，$n。"
D.Strings[39668]="信号弹发射器已清空。"
D.Strings[39669]="果仁……你能不能等我们下了船，再把它拆散？"
D.Strings[39670]="果仁，你觉得把你现在正坐的船拆烂，这明智吗？"
D.Strings[39671]="果仁，你们这些地精要是再拆一块这船的支承架，它就要窜到海里冲浪去了！"
D.Strings[39672]="富贵险中求，Rok'tar。"
D.Strings[39673]="谁更需要这块金属，洛克塔尔？是你……还是出价最高的人？"
D.Strings[39674]="这片高地上的树木质都很坚硬。它们之中有一些……甚至是石头。我也不明白这究竟是为什么。$B$B为了砍伐这些木材，我们在伐木机上装备了钻石刀刃。但联盟却总是在破坏那些伐木机。"
D.Strings[39675]="好吧，$g小子:姑娘;，来让我们好好看看。"
D.Strings[39676]="呦喉，$g小甜心:姑娘;！退开一点，看看这场魔法吧。"
D.Strings[39677]="万一我们遭到伏击，记得掩护我。"
D.Strings[39678]="看样子，这台伐木机还是可以修理的。你打个信号弹……"
D.Strings[39679]="向你致敬，$n。当你准备对大门发动进攻的时候，我们中的一些人也潜入到这里。$B$B我们计划在这里与迦罗娜汇合。$B$B<那名小队长拿出一张暮光堡垒的地图，指出那个地点。>$B$B等你准备好之后就告诉我，我们将一同行动。"
D.Strings[39680]="好吧，别管它了。这东西已经没希望了。我要离开这里！"
D.Strings[39681]="我们做到了！来，我们要让这个杰作动起来……"
D.Strings[39682]="我们应该行动了，$n。攀上这段阶梯，然后直接去找肖尔大师。"
D.Strings[39683]="死亡锯刃……被激活！系统完整性检测：百分之五十七正常。"
D.Strings[39684]="这东西的确很符合锈水标准。"
D.Strings[39685]="移动火箭平台展开！……好啊。"
D.Strings[39686]="来吧，人类！来舔舔你们的新神的不锈钢靴子！"
D.Strings[39687]="等等！你有没有听到些什么？"
D.Strings[39688]="克罗雷，你的部众已在我强大的军队面前落败了。你输了！"
D.Strings[39689]="还没结束，希尔瓦娜斯。还早呢。"
D.Strings[39690]="你鲁莽地葬送人民的生命，而你们的国王却端坐在由谎言铸成的王座上，连手指头都不曾动过一下。"
D.Strings[39691]="吉尔尼斯值得让那么多人失去生命吗？还有更多将要失去的生命？你赢不了的。"
D.Strings[39692]="我们将奋战至死！"
D.Strings[39693]="那你的女儿呢？你本可以救她……你本可以为她献出你的鲜血，可是你没有。为什么？"
D.Strings[39694]="罗娜？什么……她在哪儿？！你对她做了什么？！"
D.Strings[39695]="暂时还没做什么……"
D.Strings[39696]="我现在给你个选择的机会——这机会我可不曾获得过。"
D.Strings[39697]="我要用罗娜的性命，换取你无条件的投降。"
D.Strings[39698]="仔细想想再回答我，克罗雷。如果你拒绝我，那么她就将变成我不死的奴仆——直到永远。"
D.Strings[39699]="把她带上来，高弗雷！"
D.Strings[39700]="你好啊，老朋友！"
D.Strings[39701]="高弗雷！你这虚伪的蛆虫！"
D.Strings[39702]="罗娜……我……快放了她。我会下令撤兵。"
D.Strings[39703]="你不是认真的吧，克罗雷。你这可怜的混蛋！"
D.Strings[39704]="放了她，高弗雷。"
D.Strings[39705]="当然，主人。"
D.Strings[39706]="现在你可以离开了，克罗雷，永远别再回来。"
D.Strings[39707]="洛丹伦属于被遗忘者。"
D.Strings[39708]="原谅我，女儿……"
D.Strings[39709]="部落的战士们！我们胜利了！洛丹伦是……"
D.Strings[39710]="你干了什么，高弗雷！"
D.Strings[39711]="干了件我早该完成的事，你这龌龊的怪物。"
D.Strings[39712]="吉尔尼斯是我的，很快，整个洛丹伦都会是我的！"
D.Strings[39713]="现在，跟你的主人一起下地狱吧！"
D.Strings[39714]="撤退，弟兄们！回影牙！"
D.Strings[39715]="这片土地将因我们的毁灭之势而战栗，而颤抖！"
D.Strings[39716]="快弄好她……弄好她！"
D.Strings[39717]="我们束缚于她，姐妹们……"
D.Strings[39718]="这会毁了我们的，姐妹们……"
D.Strings[39719]="这是我们神圣的职责。契约已经缔造，交易已经达成……"
D.Strings[39720]="那就接受吧。"
D.Strings[39721]="正当我朝着虚无漂移时，一道亮光出现了，然后又一道，再一道……我亲爱的瓦格里。"
D.Strings[39722]="我现在明白了——并且坚信不疑——瓦格里是我们的未来。"
D.Strings[39723]="我们永远不会放弃洛丹伦。永远不会……"
D.Strings[39724]="我的人民长久以来都和蛮锤部族保持着良好的关系。$B$B我们当中有少数人在此定居。那些人把这片土地看作是值得守护的家园。"
D.Strings[39725]="卑鄙的兽人，卑鄙！放了那些小崽子！"
D.Strings[39726]="你们别想逃离高地，兽人！"
D.Strings[39727]="残忍的渣滓！虚伪的混蛋！"
D.Strings[39728]="燃烧吧！燃烧吧，痛苦吧！"
D.Strings[39729]="够胆子的话就跟我走！"
D.Strings[39730]="该战略性撤退了！"
D.Strings[39731]="你会为此后悔的！"
D.Strings[39732]="别说我没有警告你！"
D.Strings[39733]="监狱生活给我上了一堂很重要的课，如果算上要把肥皂捏稳那就是两堂，是的！生存第一！"
D.Strings[39734]="啊哈！我就是想把你引到这儿来！"
D.Strings[39735]="现在……见识米尔豪斯·法力风暴的全部力量吧！"
D.Strings[39736]="联盟士兵！非常大胆，非常傲慢。（匆忙，匆忙，匆忙的凡人。）你们势单力孤，而且来得太迟了。（无助而无望的，无助而无望的。）"
D.Strings[39737]="即使是在克尔苏加德统治结束后这光明的日子里，在巫妖王战败之后——兄弟会仍生生不息。"
D.Strings[39738]="没人能接近世界之心！"
D.Strings[39739]="轮回完成了。"
D.Strings[39740]="被我的身躯碾碎。感受大地的力量！"
D.Strings[39741]="保护者倒下了。世界之心暴露了！"
D.Strings[39742]="无数人将随我的死亡而倒下。重担……落到你们……肩上了。"
D.Strings[39743]="仆从们，信徒们，灭世者之子，我在此召唤你们！我们父亲的神圣大厅已经被玷污了！杀死入侵者！"
D.Strings[39744]="见证死亡之翼赋予我的强大力量吧！感受大地之怒！"
D.Strings[39745]="主人，请收下祭品。"
D.Strings[39746]="这个世界将在烈焰中重生！"
D.Strings[39747]="哈卡有许多尽为人知的名字。有人叫他血神，另一些人则直白地把他称作夺灵者。抛开名衔不说，他是这个世界上强大力量与邪恶意图的化身。$B$B我早先发现了这座神庙，并将它沉到了悲伤沼泽的下方。不幸的是，我们似乎只是在帮助阿塔莱——确保他们召唤哈卡的计划能在不受干扰的环境下实施。许多负责守卫神庙的巨龙都已被腐化，夺灵者的气息却一天天变得更为强烈。$B$B我无法凭自己的力量阻止他们。但如果我们合作，也许能有足够的时间终止他们的疯狂举动。"
D.Strings[39748]="护送希尔瓦娜斯·风行者穿过战斗前线。"
D.Strings[39749]="部落的走狗！我曾经像你们一样。（老主人弱小又饥饿。）你们无法摆脱凡人的躯壳……（血泪白骨的肉袋）……却竭力否认自身的渺小。"
D.Strings[39750]="我们快点行动吧，$n。上台阶直接去找迦罗娜。"
D.Strings[39751]="死亡之翼途径暴风城，为花园区留下了满目疮痍。我们只得暂时返回达纳苏斯。"
D.Strings[39752]="上层精灵回来了，还带回了失落已久的神秘法术。$B$B你有什么需要我检视的东西吗？"
D.Strings[39753]="重铸一件物品。"
D.Strings[39754]="什么是重铸？"
D.Strings[39755]="奥术重铸师能更改一件物品的魔法效果，这种奇术就叫重铸。$B$B通过重铸，武器、防具或珠宝原有的某种次要属性将被移除，以为其添加新的次要属性。通过这种方式，使用者可以对其装备进行自定义，以更好地与其角色和技能相匹配。$B$B例如，如果某样物品可使你更准确地命中敌人，但你却更想获得更快的攻击速度，则可花费若干费用，通过奥术重铸师重铸这件物品，降低命中而提高急速。"
D.Strings[39756]="如果你想要找奥术重铸师重铸物品，可以去法师区外的附魔商店，那里有一位上层精灵法师可以帮上你的忙。"
D.Strings[39757]="重铸"
D.Strings[39758]="这一点儿都不公平！！"
D.Strings[39759]="我为什么就非得坐在顶上，跟这堆东西挤在一起？！"
D.Strings[39760]="因为你最勇敢，宝贝儿。"
D.Strings[39761]="因为你个子矮。"
D.Strings[39762]="嘿！我可真该把这些东西砸到你头上，塔伦纳。"
D.Strings[39763]="我知道我答应让你坐在前排，吉德文，可我们这儿有位年长的客人。真对不起。"
D.Strings[39764]="菲奥拉，我必须提醒你——吉德文之所以想要坐到前排，就是为了亲你的脸。"
D.Strings[39765]="喔闭嘴，你这白痴。恐怕是你想要亲她一百遍吧。"
D.Strings[39766]="住口！"
D.Strings[39767]="啊咳！我，啊，很感谢你能让我搭便车，菲奥拉女士。偶尔歇歇脚也不错。"
D.Strings[39768]="你经常一个人走在这些路上吗？"
D.Strings[39769]="嗯，是的，不过在我年轻时更容易些。这些日子我得加倍小心才行。"
D.Strings[39770]="要是你不介意的话——我很好奇，你是做什么的，需要走那么多路？"
D.Strings[39771]="我负责照看五座银色塔楼。主要就是修理和维护之类的，有时还涉及一些简单的魔法工作。"
D.Strings[39772]="要是照看不当的话，瘟疫之地的建筑就会……没入时间的洪流中。"
D.Strings[39773]="真是高尚的工作。"
D.Strings[39774]="这让我很有满足感。我喜欢靠自己的双手工作。"
D.Strings[39775]="顺便说一句——要是你们需要修理工的话，记得通知我。我随时愿意效劳。"
D.Strings[39776]="这么说来，你是银色黎明的成员咯？"
D.Strings[39777]="那也许你能为我们美言几句？我们正想加入这个组织。"
D.Strings[39778]="没问题。虽然我现在不常去圣光之愿礼拜堂了，但你们到那儿之后，可以告诉玛克斯·泰罗索斯是我派你们去的。"
D.Strings[39779]="哇哦……他允许你叫他玛克斯？"
D.Strings[39780]="女士，你介意让我在圣光之盾哨塔那里下车吗？就在前面。我得在这儿停一下。"
D.Strings[39781]="当然，我不仅会把你放下，海毕肯大人。我们还很乐意在这儿等你回来。"
D.Strings[39782]="不——！又停车了！"
D.Strings[39783]="圣光之愿礼拜堂就在前面了，年轻的圣骑士。介意步行吗？"
D.Strings[39784]="步行，呃……？"
D.Strings[39785]="我真不敢相信我竟然让吉德文跑了！"
D.Strings[39786]="这不是你的错，塔伦纳。是他自己要跑的。我们谁都阻止不了他。"
D.Strings[39787]="我们不能确定他是不是被杀了。也许只是跑到别处去了。"
D.Strings[39788]="不，他决不会丢下自己的祈祷书。他总是把脸埋在那本书里，学个没完。"
D.Strings[39789]="他总是在学习，总是想要变得更好。"
D.Strings[39790]="那我们更有理由相信，他还活着。"
D.Strings[39791]="像吉德文那样的圣骑士绝对是死亡骑士的好胚子。天灾军团任何强大到足以将他击败的成员都会看出这一点。"
D.Strings[39792]="他很有可能就被囚禁在某处，等待死亡仪式的开始。"
D.Strings[39793]="真的？这可是天大的好消息！"
D.Strings[39794]="嗯，事实上，这是个相当坏的消息，不过总比死了好……"
D.Strings[39795]="我们要是想要找到他，朝这个方向前进就对了。他很可能被带去了斯坦索姆，或是病木林。"
D.Strings[39796]="这两个地方都被强大的邪恶气息所笼罩。是我最不愿意去的地方。"
D.Strings[39797]="我不确定我是否已经做好了只身一人进去的准备。"
D.Strings[39798]="你不是只身一人，塔伦纳。你一路上结交了许多盟友。除此之外，你自己本身就是个技艺高超的圣骑士。"
D.Strings[39799]="我，技艺高超？不，不，吉德文才是个出色的圣骑士。他每天夜里都不眠不休地苦苦操练……"
D.Strings[39800]="……可你却能始终与他齐头并进。在没有操练的情况下。"
D.Strings[39801]="你们两个的战斗技艺我都见过，塔伦纳。你有着与生俱来的天赋——在这一点上，吉德文永远也赶不上你。"
D.Strings[39802]="也许这就是他独自离去的原因。"
D.Strings[39803]="也许他觉得自己需要证明，他和你一样天赋异禀。"
D.Strings[39804]="这一切都是我的错。我必须找到他，弥补这些过失。"
D.Strings[39805]="我不认为这是你的错，塔伦纳。可我不会阻止你去救吉德文。"
D.Strings[39806]="我们别拐弯抹角了，$r。我来这儿的目的只有一个——那就是消灭古加尔！$B$B你的任务就是阻止他造出终极武器。那可能是个灌注了上古之神力量的强大神器。"
D.Strings[39807]="有个神器——那是种武器，正在被注入上古之神的力量。我们不知道它究竟在哪儿，可我们必须赶在古加尔完成之前找到它。$B$B其它任何事都是次要的。任何人的生命都是可以牺牲的，包括你和我。"
D.Strings[39808]="在这片废墟上空飞行可要多加小心，$g年轻人:小姑娘;。暮光飞龙尤其喜欢会飞的东西。"
D.Strings[39809]="净化程序启动……"
D.Strings[39810]="净化已完成。等待送交。"
D.Strings[39811]="警告，系统已过载。故障即将发生！"
D.Strings[39812]="全都烧成灰烬！"
D.Strings[39813]="点燃引线，兄弟们！"
D.Strings[39814]="我们要让你知道，为什么财宝是海盗最好的朋友！"
D.Strings[39815]="把他们炸成碎片，老大！"
D.Strings[39816]="把他们的眼球啄出来！"
D.Strings[39817]="用最厉害的招数对付他们！"
D.Strings[39818]="准备发射高能炮弹！"
D.Strings[39819]="杀了那个工程师，别让她还击！"
D.Strings[39820]="你认识我父亲吗？"
D.Strings[39821]="把我装进炮筒里，伙计！"
D.Strings[39822]="呃！离我的宝贝远点儿，你这龌龊的海老鼠！"
D.Strings[39823]="把如此神圣的使命交给古加尔那种傻瓜真是太蠢了！我会亲自解决你们这些入侵者！"
D.Strings[39824]="不，别碰净化者……那是我的骄傲与乐趣所在！"
D.Strings[39825]="啊！我可不要再这样了！我已经提出请求，要参加下一次的探险……"
D.Strings[39826]="我的孩子们会啃光你们的骨头！"
D.Strings[39827]="真无能……"
D.Strings[39828]="我已经厌倦了。看见你们立足的这片巢群了吗？我的力量正是滋养它们的活力。但这些生命力量永远属于我。面对这超越认知的力量吧！"
D.Strings[39829]="啊，可哪个才是真的？"
D.Strings[39830]="我可怜的宝贝儿，你一定累坏了。$B$B这儿有食物和饮料，要是你愿意的话，可以放心地在这儿休息。"
D.Strings[39831]="想吃点儿什么吗，$c？$B$B还是你只想找个地方放松一会儿？"
D.Strings[39832]="喔伙计，终于有人来了！这下面简直疯狂透顶！比疯狂还要疯狂！"
D.Strings[39833]="不……这个世界……属于我……"
D.Strings[39834]="我仅代表卓绝而永保中立的热砂集团——欢迎来到沼桨镇！我们是东部王国独一无二的滨海度假胜地与军用武器补给港。$B$B也许你们这些家伙刚刚在南面不远处经历了战火的洗礼，可在这围墙之内，只有欢声笑语。忘了肩头的重担吧，来歇会儿，喝上两杯，但切记别找麻烦……否则我这儿的彪悍卫兵会让你们明白什么叫做“中立地域”。"
D.Strings[39835]="|TInterface\\Icons\\spell_arcane_arcaneresilience.blp:20|t%s开始施放|cFFFE1CF7|Hspell:79729|h [能量转化]！|r"
D.Strings[39836]="|TInterface\\Icons\\spell_nature_lightningshield.blp:20|t%s开始施放|cFF1CF2FE|Hspell:79900|h [不稳定的护盾]！|r"
D.Strings[39837]="|TInterface\\Icons\\spell_nature_nullifydisease.blp:20|t%s开始施放|cFF1CFE1C|Hspell:79835|h [浸毒外壳]！|r"
D.Strings[39838]="|TInterface\\Icons\\spell_fire_firearmor.blp:20|t%s开始施放|cFFFF9A20|Hspell:79582|h [屏障]！|r"
D.Strings[39839]="托尔本·光爆，传送应对方案工程师为您效劳！"
D.Strings[39840]="|TInterface\\Icons\\ability_hunter_mastermarksman.blp:20|t%s注视着|cFFFF0000$n|r开始施放|cFFFF0000|Hspell:79501|h [获取目标]！|r"
D.Strings[39841]="送我回到地表，托尔本。"
D.Strings[39842]="好的，现在盒子里已经装了两个俾格米人。你要做的就是小心劈砍，对准他们之间的空隙。"
D.Strings[39843]="像这样？"
D.Strings[39844]="不，不！你怎么一点表现力都没有？要讲究舞台艺术！"
D.Strings[39845]="要运用你的力量！真真正正地把这箱子劈成两半，看好了！"
D.Strings[39846]="你刚才……？"
D.Strings[39847]="嗯，我想是的。"
D.Strings[39848]="喔……我的天……"
D.Strings[39849]="看来我们得再找几个俾格米人了。"
D.Strings[39850]="动作触发间隙法术平滑测试。"
D.Strings[39851]="动作触发间隙事件平滑测试。"
D.Strings[39852]="事件生成间隙法术平滑测试。"
D.Strings[39853]="事件生成间隙事件平滑测试。"
D.Strings[39854]="你好啊。$B$B你是来存放宠物，还是在寻找失踪的同伴？"
D.Strings[39855]="你好啊。$B$B你是在寻找失踪的同伴？"
D.Strings[39856]="等我们安全回到地表之后，会有大把的时间供我们交谈。"
D.Strings[39857]="你们两个快一点。在一切完成之前，我还想再装满十二只桶呢！"
D.Strings[39858]="啊，液体黄金。每一滴都要收集好！"
D.Strings[39859]="我喜欢早晨的这种清新气味。当然，就是这种硫磺的酸气……这里全都是这种气味。闻起来就像是……金钱的气味。"
D.Strings[39860]="来自于清水，被灌入桶中。赶快！时间就是金钱。"
D.Strings[39861]="这就是我所说的利润精华。嗨！你漏掉了一些，就在那里。"
D.Strings[39862]="如果我们要活着离开这里，就必须从这群无意识的麻疯侏儒中间冲过去！"
D.Strings[39863]="拿上我们最后的传送信标，带这些幸存者离开这里。谢谢你帮助我们，我们应该能自己从这里冲杀出去。"
D.Strings[39864]="你好，我名叫泰瑟兰·血望者。我将一生中最好的时光都用来进行巫术的训练，并召集与我志同道合的血精灵，组成了神圣遗物学会。$B$B要知道，在这个世界的各个角落里埋藏着许多古老、强大的宝物。我打算利用这些宝物将我的族人从他们堕落的嗜好中解救出来，让他们重新团结为一体，成为往日那个光荣而坚强的种族。$B$B我可以向你保证，魔法是可以接触的。只要得到适当的教导，任何人都能使用这种力量并且免于因它而堕落。$B$B现在，联盟的各个种族，甚至是部落的人都在嘲笑我们遭受重创的首都，仍然矗立的逐日者雕像，和我们在世界各处一次又一次遭受的挫折。$B$B但这种情况不会再继续下去了。"
D.Strings[39865]="我不想死在这里！"
D.Strings[39866]="不要让它们吃掉我！"
D.Strings[39867]="有人吗！有人能救救我吗？！"
D.Strings[39868]="我真的要死在这里了吗？"
D.Strings[39869]="救命！我已经没力气了。"
D.Strings[39870]="离开走私者洞穴，向埃达尔拉发信号"
D.Strings[39871]="深渊海马看上去非常不高兴。"
D.Strings[39872]="啊呀！"
D.Strings[39873]="嘿呀！"
D.Strings[39874]="我把附近残骸里能抢救的东西都抢救出来了，现在我已经坚持不住了……"
D.Strings[39875]="永远地感谢你。"
D.Strings[39876]="还有暮光之锤的暴徒没消灭干净。"
D.Strings[39877]="我已经不再被奴役了！"
D.Strings[39878]="现在是复仇的时候了，凡人们！"
D.Strings[39879]="这一点微小的礼物完全无法表达我的感激之情。谢谢你！"
D.Strings[39880]="请原谅，我得去和那些奴役我的家伙“谈谈”了。"
D.Strings[39881]="跑吧，渺小的暮光教徒们。你们的末日就要到了！"
D.Strings[39882]="在我回家之前，还要进行一点小小的复仇。"
D.Strings[39883]="你们一族注定要承受这一切，$r。"
D.Strings[39884]="你和这些魔鬼结盟了？你也将会有被焚毁的一天！"
D.Strings[39885]="<黑色的巨龙身上布满了伤口。他一直盯着你，眼睛里闪烁着凶恶的光芒。>"
D.Strings[39886]="<凶恶的黑色巨龙拼命扯拽着捆缚他的锁链。你最好还是离他远一些。>"
D.Strings[39887]="我不可能永远困在这里，$c。你最好现在就祈祷，祈祷当我复仇的时候，你不会在我面前。"
D.Strings[39888]="龙并不是猪和牛那样简单的野兽。他们是一种自然的力量。强大……原始的力量。$B$B让他们服从你，就是要驾驭这个世界。$B$B能够支配他们，你也就支配了命运的力量。"
D.Strings[39889]="自从这场企业联合战争开始以前，我就在进行各种药剂混合工作了。我现在并不打算停止这行当。$B$B只要还有买家，芭芭就不愁没生意做！"
D.Strings[39890]="他们的火力相当强劲。也许我们不应该小看那些地精矬子。"
D.Strings[39891]="在海马分神的时候抓住它！"
D.Strings[39892]="干得好，$n！相信从这里开始，你在波涛下的旅程将会变得更加顺畅。"
D.Strings[39893]="听从召唤……服从他……加入我们……"
D.Strings[39894]="好了，孩子们，我们要夺回自己的家园！"
D.Strings[39895]="我们本可以用文明的手段解决这一问题，但我不打算这样！"
D.Strings[39896]="看到前面的通道了吗，$g小子:姑娘;？"
D.Strings[39897]="是……"
D.Strings[39898]="有埋伏。"
D.Strings[39899]="你看起来很笃定。"
D.Strings[39900]="哦，$g小伙子:姑娘;！已经4次了。"
D.Strings[39901]="我以为你又要走了……"
D.Strings[39902]="该死的，没错！"
D.Strings[39903]="嗯，就这么干吧。"
D.Strings[39904]="就是这种感觉！"
D.Strings[39905]="没错，给他们点颜色瞧瞧。让他们来吧！"
D.Strings[39906]="如果是凯莉派你来抓我回去，那她可要失望了。这里还有许多暮光暴徒没消灭干净呢。"
D.Strings[39907]="我很快就会回来的，$g小伙子:小姑娘;。为了能过上好日子，还得再走一趟。"
D.Strings[39908]="你就这点能耐？！"
D.Strings[39909]="凯登弄到了一把刻着你的名字的斧头！"
D.Strings[39910]="上啊！"
D.Strings[39911]="我知道，你们的小窟窿里还藏着你的同伙……"
D.Strings[39912]="哈！这个地方到处都是好东西！$b$b看看我在这里挖出了什么……$b$b一顶呼吸帽子！"
D.Strings[39913]="起来，你这个懒鬼，战斗还没有结束呢！"
D.Strings[39914]="打啊，打啊！"
D.Strings[39915]="从洞里出来，胆小鬼！"
D.Strings[39916]="想躲着老凯登吗……"
D.Strings[39917]="有人在家吗？"
D.Strings[39918]="行动……狠狠地打他们！"
D.Strings[39919]="这很有趣。"
D.Strings[39920]="我要回去了。"
D.Strings[39921]="你的招式全是破绽。"
D.Strings[39922]="又少了一个邪教徒。"
D.Strings[39923]="把尸体留在这里，让他们知道，和龙喉兽人做对的下场。"
D.Strings[39924]="这实在是太有趣了。"
D.Strings[39925]="我猜，不算坏。"
D.Strings[39926]="为了龙喉部族的光荣！"
D.Strings[39927]="不是敌人死，就是我们亡！"
D.Strings[39928]="干掉这些傻瓜，否则伦道夫就会杀光我们！"
D.Strings[39929]="为你们悲惨的结局而战吧，没用的东西！"
D.Strings[39930]="你好，$r。我是绿龙军团的伊萨里奥斯勋爵。$B$B我带着善良的意愿来到这里，要从这座神殿的邪恶中解救我的同族。你愿意帮助我吗？"
D.Strings[39931]="我知道你会来。没有人能与我对抗，即便是你也不行！"
D.Strings[39932]="你是来接受训练的，很好！"
D.Strings[39933]="$n，你在这里！请帮助我们守卫这个广场。"
D.Strings[39934]="小心，有更多的龙喉兽人杀过来了。还有部落的军队支援他们！"
D.Strings[39935]="好了，我们已经在这里造成了足够的破坏。我们要准备进行另一场伏击了。"
D.Strings[39936]="我们成功了！占领道路，封锁这个地点。"
D.Strings[39937]="有没有试过我的呼吸帽？$b$b老巴德可不要再嘬蛤蜊了！不，先生……"
D.Strings[39938]="护士莉莲叹了口气。"
D.Strings[39939]="帮助塞纳留斯击败拉格纳罗斯！"
D.Strings[39940]="你要为此付出代价，霍格！"
D.Strings[39941]="总有一天……我会复仇……"
D.Strings[39942]="森林也要后退！"
D.Strings[39943]="现在要战斗，以后再吃饭！"
D.Strings[39944]="感谢圣光！我成功了。"
D.Strings[39945]="能再次回到正常侏儒的中间，实在是让人松了口气！"
D.Strings[39946]="我还以为我要完了！"
D.Strings[39947]="你……你不会吃掉我的，对吧？"
D.Strings[39948]="光凭我自己肯定不行……"
D.Strings[39949]="感谢你把我救出来！"
D.Strings[39950]="我的家人……你有没有找到我的家人？"
D.Strings[39951]="啊，一个新人。这边走，先生。"
D.Strings[39952]="%s察觉到它被发现了，立刻开始装死！"
D.Strings[39953]="深水领主金加塔尔进入了战场！"
D.Strings[39954]="一切都将焚毁！"
D.Strings[39955]="灰烬！"
D.Strings[39956]="火焰……熄灭了！"
D.Strings[39957]="以国王的名义，后退！"
D.Strings[39958]="守住战线！不要让他们通过！"
D.Strings[39959]="典狱官塞尔沃特，我们需要向前推进！"
D.Strings[39960]="我们必须行动，趁我们还能采取行动的时候！"
D.Strings[39961]="请让我做一下自我介绍。我是兰多菲·摩洛克。今天，我会把你们杀光。"
D.Strings[39962]="这种对生命的浪费实在是可惜。"
D.Strings[39963]="我宏大的谋略，绝妙的计划！都完了！"
D.Strings[39964]="稳住……稳住……"
D.Strings[39965]="停火！这是典狱官的命令……禁止射击……"
D.Strings[39966]="紧盯着他们。如果有任何异动，他们就死定了。"
D.Strings[39967]="待在我身边。我们一定会把你弄出去的。"
D.Strings[39968]="你会得到援助的。"
D.Strings[39969]="你做得很好……你会没事的。"
D.Strings[39970]="解救"
D.Strings[39971]="纳迦逃出了前面的隧道。绝不要对他们有任何怜悯，$c。"
D.Strings[39972]="我永远都感谢你，$n。"
D.Strings[39973]="我会去对付那些龙。你只需要处理那些暮光垃圾就行了。"
D.Strings[39974]="只有当最高议会全体表决通过的时候，拉穆卡恒才会对尼斐塞特发动战争。$B$B我们的机会不大，但我的兄弟必须明白，死亡之翼的盟军绝对不会讲任何道理。"
D.Strings[39975]="来了一个——抓住他！"
D.Strings[39976]="睁大了眼睛，别放过那些矮人猪。"
D.Strings[39977]="$n，是你吗？请帮我摆脱这些锁链。"
D.Strings[39978]="他们抓住了我们的同伴！绝不要对龙喉有任何怜悯！"
D.Strings[39979]="交出那只鸟，你们这些肮脏的野兽。为蛮锤而战！！"
D.Strings[39980]="你和那些尼斐塞特 杂碎是一伙的？是不是他们派你来干什么肮脏的勾当？快说！"
D.Strings[39981]="我正在找塔赫特。我这就帮你摆脱这些锁链。"
D.Strings[39982]="还不算太糟糕……$b$b我还有我的呼吸帽子！"
D.Strings[39983]="援救狮鹫"
D.Strings[39984]="守卫夺取的战利品"
D.Strings[39985]="你！$C！帮我们挡住敌人的反攻。"
D.Strings[39986]="等等！尼斐塞特卫兵冲过来了！和我一同战斗，好好教训他们一顿！"
D.Strings[39987]="终于自由了。感谢你，陌生人。塔赫特已经不在这里了。一个残忍的尼斐塞特将军带走了他。那个将军的名字叫凯玛斯。"
D.Strings[39988]="我必须警告你。凯玛斯对待囚犯非常残忍……他最喜欢强迫囚徒们与他豢养的怪兽进行决斗。也许你要做最坏的打算，朋友。"
D.Strings[39989]="注意了——联盟正在帮助蛮锤矮人！"
D.Strings[39990]="%s从尼斐塞特执行者身上拣起一把钥匙。"
D.Strings[39991]="又一个愿意帮助蛮锤战斗的朋友！"
D.Strings[39992]="冲进关押所，消灭纳迦！"
D.Strings[39993]="部落的战争机器需要你！"
D.Strings[39994]="你是来这里助战的吗？海加尔山必将燃起熊熊大火！"
D.Strings[39995]="能不能派我去月光林地，使者？"
D.Strings[39996]="将军和他的部队正要去攻取一座已经由你进行过侦查的基地。你应该去与他们汇合。"
D.Strings[39997]="那只巨型鱿鱼就要完蛋了。凡尔纳已经重整装备，准备再次上阵……现在，我们只需要耐心等待。$B$B它会回来的。$B$B你就看着吧。"
D.Strings[39998]="大家干得好。现在，各就各位，我们准备行动。"
D.Strings[39999]="这会让你有事可干！"
D.Strings[40000]="龙喉！"
D.Strings[40001]="跳起来，甩掉那些小鳄鱼！"
D.Strings[40002]="来吧。这座山脊上的战斗还没结束呢。"
D.Strings[40003]="啊……来这里拜访我的人并不多。$B$B请多坐一会儿吧。"
D.Strings[40004]="联盟需要你。响应英雄的号召吧！"
D.Strings[40005]="我们完成了这个工作。"
D.Strings[40006]="呸！只是运气好而已！我的宠物会把你撕个粉碎！"
D.Strings[40007]="够了！我已经厌烦你了！"
D.Strings[40008]="搜索这座城镇，消灭一切幸存者！"
D.Strings[40009]="喂！$n！到这里来……"
D.Strings[40010]="引诱凯玛斯到鳄鱼蛋旁边去，但你可不要踩上那些鳄鱼蛋！"
D.Strings[40011]="上城墙，冲啊！"
D.Strings[40012]="为了荣誉！为了光荣！为了桑德玛尔！"
D.Strings[40013]="远处的那片碎石堆曾经是我们家族传承了五代的产业。$B$B我们正在把它夺回来。$B$B敌人的数量远远超过我们……但我们是蛮锤部族！你愿意帮助我们吗？"
D.Strings[40014]="不工作的人不美丽！"
D.Strings[40015]="没错，锤子就应该这样挥舞，先生们！"
D.Strings[40016]="好啊！在我搜索这片古老的家园时，把那些肮脏的尸体都烧光吧。"
D.Strings[40017]="哦，那些地狱的渣滓。它们把这个地方全都毁了！"
D.Strings[40018]="我们已经得到了我们所需要的。现在撤离。我们会在别的地方再次狠狠地打击他们。"
D.Strings[40019]="再见，朋友！祝你猎宝收获多多！"
D.Strings[40020]="我会将这个消息带到桑德玛尔。"
D.Strings[40021]="$C！保持警惕。我已经在附近闻到了蛮锤的臭气……"
D.Strings[40022]="小心——更多的矮人正从后面攻过来！"
D.Strings[40023]="天哪！我的老心脏可受不了！"
D.Strings[40024]="哈！龙喉又赢得了一场辉煌的胜利。"
D.Strings[40025]="莫提姆·摩洛克被命中要害，颓然倒下！"
D.Strings[40026]="彻底搜索这片区域，收集一切可用的物资。迅速行动——他们很快又要发动攻击了。"
D.Strings[40027]="我记得很清楚。那是一个阳光灿烂的日子……"
D.Strings[40028]="那时我正专心于自己的工作，突然之间，死亡之翼出现了！"
D.Strings[40029]="我对自己说，“我要一拳砸扁那头龙的脸！”"
D.Strings[40030]="不幸的是，这场大灾变释放出无数愤怒的元素。"
D.Strings[40031]="“你们这些该死的石头元素！”我说，“我也要把你们砸扁！”"
D.Strings[40032]="你们这些该死的石头元素！"
D.Strings[40033]="我也要把你们砸扁！"
D.Strings[40034]="到此为止了，霍格！"
D.Strings[40035]="他……他已经死了？"
D.Strings[40036]="这不可能是真的。你不可能这样轻易地杀死他！"
D.Strings[40037]="接招吧！"
D.Strings[40038]="尝尝我的拳头！"
D.Strings[40039]="来——来吧！"
D.Strings[40040]="我就是为你来的，死亡之翼！"
D.Strings[40041]="迷失者塞尔杜林！"
D.Strings[40042]="我要一拳砸扁那头龙的脸！"
D.Strings[40043]="狠狠一拳！"
D.Strings[40044]="尝尝这个，危险的敌人！"
D.Strings[40045]="你们没有权力把我们挡在外面！"
D.Strings[40046]="我们对这座城市和它的国王绝对没有恶意……"
D.Strings[40047]="你们必须让我进去，我的客人们还在等着呢。"
D.Strings[40048]="作为一名纳税公民，我有权利访问这座城市！"
D.Strings[40049]="乌瑞恩国王为什么会害怕他自己的人民？"
D.Strings[40050]="你们不能这样对待我们！"
D.Strings[40051]="我要和治安官玛克布莱德谈谈！这样对待我简直太无礼了！"
D.Strings[40052]="我有掌握权柄的朋友。如果他们听到我被这样对待，肯定不会高兴的！"
D.Strings[40053]="你在找我？"
D.Strings[40054]="再和我说说那个故事，塞尔杜林。"
D.Strings[40055]="不，不，不，塞尔杜林。你把故事讲错了！"
D.Strings[40056]="嗯……我走的不是这个方向。我想我的确是把故事讲错了。"
D.Strings[40057]="什么？！那是什么？！不可能！他的身体就在这里！除非……"
D.Strings[40058]="%s的眼睛开始发光了。赶快找掩护！"
D.Strings[40059]="坚守主路。这是我们的主攻击方向。"
D.Strings[40060]="英雄们，我知道他是真正的霍格。我看到我的眼睛就挂在他的腰带上。那其中包含着一段非常黑暗的往事。他的力量……已经超出了我们的理解范畴……"
D.Strings[40061]="爸爸让我射击！"
D.Strings[40062]="镇定！我们要尽快查清楚每一个人……"
D.Strings[40063]="你们大喊大叫只能耽误更多时间。"
D.Strings[40064]="什么？还有更多蛮锤矮人？那些傻瓜真是不想活了！"
D.Strings[40065]="让我看看你都出售些什么，菲奥拉。"
D.Strings[40066]="这边走。聚在一起，别走散了！"
D.Strings[40067]="不要吵！我们会尽快做好甄别工作。"
D.Strings[40068]="如果你们不安静些，你们今晚就要在监狱里待着了！"
D.Strings[40069]="国王只是在采取必要措施确保城市的安全。"
D.Strings[40070]="我们只需要把大门关上，就没有人能进来了……"
D.Strings[40071]="真是一团乱！我们刚刚从拯救深岩之洲的战斗中回来，却看到了这种场面？$B$B可憎的暮光之锤！$B$B幸好你在这里，把他们解决掉了！"
D.Strings[40072]="金矿先生，我已经准备好进行这次狂野驾驶了。"
D.Strings[40073]="我已经为部落效力多年，立下无数功劳，而我现在只能受到这样的待遇？"
D.Strings[40074]="为什么我们的领袖要把我们挡在外面？"
D.Strings[40075]="如果你们不安静些，你们就要和那些被拘捕的邪教徒关在一起了。"
D.Strings[40076]="我们只是在采取必要措施确保城市的安全。"
D.Strings[40077]="如果你想要加快速度，那就认真准备好自己的文件！"
D.Strings[40078]="你必须保护我，$n。没有了武器和图腾，我完全没有自卫的能力！"
D.Strings[40079]="兰多菲·摩洛克消失了！"
D.Strings[40080]="霍格愤怒了！"
D.Strings[40081]="哈索尔死了！吹响号角，将消息从滩头堡传往桑德玛尔！"
D.Strings[40082]="如果这些矮人只能召集起这么一点力量，这座高地很快就会是我们的了。"
D.Strings[40083]="一定要注意监视这些道路。那些蠢货有可能会再次发动攻击。"
D.Strings[40084]="蛮锤矮人不停地向这里发动猛攻，$n。但他们赢不了我。好好学着吧。"
D.Strings[40085]="我……*咳嗽*我欠你一条命，陌生人。谢谢你。"
D.Strings[40086]="恐怕你的朋友不会很快就醒过来。我一直都把我的鳄鱼喂得很饱。我不喜欢看到它们为了食物而争斗。"
D.Strings[40087]="但也许我会给你一个例外。放鳄鱼出来！喂食时间到了！"
D.Strings[40088]="就是这样？你要做到的不应该只有这些！"
D.Strings[40089]="不要惹凯登·顿沃德生气！"
D.Strings[40090]="呸！这里应该有一些的……"
D.Strings[40091]="顿沃德有许多房子，为什么偏偏是这一座？！"
D.Strings[40092]="他们干得太过份了！今天一定要有一些暮光暴徒付出生命的代价！"
D.Strings[40093]="啤酒？！为什么他们要毁掉这些啤酒？！怪物！"
D.Strings[40094]="没有灵魂的，不喜欢啤酒的，粗蠢的混蛋！你们可别让我看见！"
D.Strings[40095]="我甜美的啤酒啊……都没了……太恐怖了……"
D.Strings[40096]="真……渴啊……"
D.Strings[40097]="伊欧因，那里有一口满是清水的井。"
D.Strings[40098]="水？！你疯了吗？！我要的是啤酒！"
D.Strings[40099]="我真没有必要这么听话。"
D.Strings[40100]="我可以解释自己为什么会在这里。"
D.Strings[40101]="我没有什么可隐瞒的。"
D.Strings[40102]="你能快一点吗？我还要赶路呢。"
D.Strings[40103]="这是什么？我什么都没做！"
D.Strings[40104]="暴风城的公民们，就像你们知道的那样，一个危险的邪教正在图谋颠覆我们的城市。乌瑞恩国王下达命令，在彻底摧毁那个邪教之前，要进入暴风城的人必须接受搜查和询问。"
D.Strings[40105]="别动我的啤酒，你这个肮脏的，不喜欢啤酒的怪物！"
D.Strings[40106]="一切正常，你可以走了。"
D.Strings[40107]="你可以进城了。"
D.Strings[40108]="你可以自由进入暴风城了。"
D.Strings[40109]="这是邪教文书。我要用锁链捆住你，再把你牵进暴风城。"
D.Strings[40110]="暮光之锤的徽章？卫兵！"
D.Strings[40111]="这是邪教的宣传文稿。你被捕了。"
D.Strings[40112]="你竟然私带邪教文卷，我不能让你进城。"
D.Strings[40113]="这些可疑的文件是什么？卫兵，监押这个人。"
D.Strings[40114]="跟我来，公民。"
D.Strings[40115]="哦，这太好了！"
D.Strings[40116]="抓紧！"
D.Strings[40117]="我的图腾！！！"
D.Strings[40118]="跳！！！"
D.Strings[40119]="我要搜查你，公民。"
D.Strings[40120]="我的啤酒！"
D.Strings[40121]="%s开始转变为大地之力！"
D.Strings[40122]="$r，现在你是我们的了。"
D.Strings[40123]="地精可以帮你把钱数得一清二楚，但你绝对要小心他们。"
D.Strings[40124]="你们不可能把我们都找到！"
D.Strings[40125]="我们一定能取得最终的胜利。"
D.Strings[40126]="不要以为你们已经赢了。"
D.Strings[40127]="这座城市即将陷落！"
D.Strings[40128]="别碰我，你们这些愚忠的渣滓。"
D.Strings[40129]="不，不，蠢$r……"
D.Strings[40130]="没人能骑我的驼背淑女！"
D.Strings[40131]="在那次攻击之后，有些人逃难到了这里，但他们之中并没有尖喙。"
D.Strings[40132]="这里满是血腥之气。但没有尖喙的踪迹。"
D.Strings[40133]="这些建筑物完全被毁了。尖喙不可能藏身在这里。"
D.Strings[40134]="尖喙！你在哪里，尖喙？"
D.Strings[40135]="尖喙！到东尼利这里来。东尼利会保护你！"
D.Strings[40136]="回来，尖喙！不要受伤了！"
D.Strings[40137]="尖喙！不要再躲着了。现在就出来！"
D.Strings[40138]="你似乎是有了一名同伴。你应该带他回东尼利那里去。"
D.Strings[40139]="这具矮人的尸体被严重地损毁了。暮光之锤一定都是些以屠杀为乐的疯子。"
D.Strings[40140]="消灭联盟$c！"
D.Strings[40141]="这边——这里有个联盟$c！"
D.Strings[40142]="我必须承认那些暮光暴徒并非无能之辈……也许他们缺乏战斗技巧，但他们的数量和坚韧完全可以弥补这个缺陷。在我们的上一次战斗中，他们的确取得了一些战果。"
D.Strings[40143]="顿沃德家族以刚强悍勇著称，但他们的脑子并不怎么灵光。我很担心我的兄弟们会把他们的名誉和生命浪费在一些不必要的地方。"
D.Strings[40144]="工作卖力一些，黑铁狗子们！"
D.Strings[40145]="我还要更多源质！动作快一点！"
D.Strings[40146]="古加尔会大笑着把你生吞活剥！"
D.Strings[40147]="如果你们再这样慢吞吞的，我就把你们变成一堆灰烬！"
D.Strings[40148]="不要让那些蜘蛛把源质吃掉！"
D.Strings[40149]="嗨，你！是的，就是你！到这里来。我要把你活埋！"
D.Strings[40150]="暮光堡垒需要更多源质！"
D.Strings[40151]="你们这帮矮人只配挖矿！"
D.Strings[40152]="一个柯尔之子来帮助你了，但你要小心他的大石头！"
D.Strings[40153]="|TInterface\\Icons\\spell_fire_twilightfire.blp:20|t%s进行了一次|cFFFF0000|Hspell:86059|h[深呼吸]|h|r!"
D.Strings[40154]="|TInterface\\Icons\\spell_holy_consumemagic.blp:20|t%s开始施放|cFF00EEFF|Hspell:86622|h[噬体魔法]|h|r!"
D.Strings[40155]="|TInterface\\Icons\\spell_fire_twilightpyroblast.blp:20|t%s开始施放|cFF00EEFF|Hspell:86408|h[眩光毁灭]|h|r!"
D.Strings[40156]="哈！我的兄弟们正渴望着一战。我已经无法再阻止他们了。$B$B你要参加这一战吗？"
D.Strings[40157]="兄弟们，让我们给他一个正式的顿沃德式欢迎！"
D.Strings[40158]="我参加。"
D.Strings[40159]="准备好以后就告诉我。越快越好——凯登已经有些迫不及待了。"
D.Strings[40160]="别想这么容易就抓住我！阿塔莱即将崛起……"
D.Strings[40161]="你们竟然战胜了豺狼人之王。你们真是伟大的英雄。在今后的许多年中，全艾尔文森林和西部荒野的人都会津津乐道你们的伟大胜利。谢谢你们。"
D.Strings[40162]="这些船可不会自行完成建造！"
D.Strings[40163]="我期待着我的工人们能够显示出最杰出的造船工艺。给我加倍拿出力量来！"
D.Strings[40164]="你的时间就要结束了。"
D.Strings[40165]="随你怎么想吧，但你会看到，我才是对的。"
D.Strings[40166]="也许我现在是陷入了困境，但是当主人的复仇之雨在这座城市上洒落的时候，我必将重获自由。"
D.Strings[40167]="我已经踏上成神的道路，那种狂妄而卑微的英雄不可能阻挡我。"
D.Strings[40168]="你的生命即将终结，而我的则刚刚开始。"
D.Strings[40169]="我们必须控制住被我们释放出来的奥术能量。"
D.Strings[40170]="我们不能让奥术能量进一步积累了！"
D.Strings[40171]="我们必须在精灵或魔鬼注意到这股能量之前让它消散。"
D.Strings[40172]="当你察觉到真实情况的时候，一切都已经太晚了。"
D.Strings[40173]="我的力量正在消褪……兄弟们，支援我！"
D.Strings[40174]="你们在这座城市里做些什么？"
D.Strings[40175]="移动达拉然的魔法太强大了！我们没办法一直压制住它！"
D.Strings[40176]="达拉然的法师们是艾泽拉斯最强大的法师！我们不会失败的！"
D.Strings[40177]="我能感觉到奥术能量再一次开始积累！一定要警告大法师！"
D.Strings[40178]="我的胳膊累了……"
D.Strings[40179]="我们已经将主人的预言变为现实。仪式已经开始了，而且我们数量众多，你不可能阻止我们。"
D.Strings[40180]="很高兴能回来，先知。我想为仪式的完成而出力。"
D.Strings[40181]="我们很担心你会被抓住，但我绝不想把你排除在传送门仪式之外。"
D.Strings[40182]="拿起这本书，完成仪式。每一个步骤都要完美无缺，否则元素就不会在正确的时间通过传送门。"
D.Strings[40183]="你摧毁了他们的大地符文！我打赌，他们一定还有另外三个符文，而且那些符文一定都连接在这道火焰传送门的后面。"
D.Strings[40184]="我们要把他们全部毁灭。但首先，我需要把那块弹片从我的背上取出来。"
D.Strings[40185]="你身上湿了吗？我简直湿透了！好吧，你觉得下一个风之力的符文会是什么样子？"
D.Strings[40186]="该死的风把我的头发都吹干了。不过它让我有了一个关于飞行器引擎的伟大灵感！"
D.Strings[40187]="看到东尼利，尖喙发出欢快的叫声！"
D.Strings[40188]="啊哈哈哈，这是他们最后的符文了！暮光崽子们，你们的元素之力都完蛋了！"
D.Strings[40189]="尖喙，回家去找凯莉。她会保护你，直到东尼利回来。"
D.Strings[40190]="什么！那里是什么？"
D.Strings[40191]="熔岩之牙？！不！！！"
D.Strings[40192]="你要到哪里去，小家伙？！"
D.Strings[40193]="金矿！你以为我忘记了吗？！！我告诉过你，我要复仇！！！"
D.Strings[40194]="救命！在这边！"
D.Strings[40195]="现在我要移去你眼前的迷雾。看着吧，我们的俘虏。"
D.Strings[40196]="死亡之翼已经彻底被自己的疯狂征服了。而我们红龙必须趁这个机会把黑龙从他的眼皮底下偷走。我们要让黑龙恢复他们往日的样子，成为大地的守护者。"
D.Strings[40197]="%s力竭倒下了。"
D.Strings[40198]="%s显出要醒过来的样子！"
D.Strings[40199]="你就像顿沃德家族的一员。我喜欢你。"
D.Strings[40200]="你这个傻瓜！这是一场仪式，不是在做饭！"
D.Strings[40201]="我们被背叛了！你也许赢了这一次，但我们的仪式终将完成！"
D.Strings[40202]="这里还有很多可供我们使用的设备。立刻散开。加快速度！龙喉兽人已经很近了。"
D.Strings[40203]="拿走一切能拿得动的东西，赶快离开。龙喉兽人随时都有可能出现！"
D.Strings[40204]="提高警惕，小心龙喉兽人。"
D.Strings[40205]="小麦与水的远古之力，我已经为你们打通了道路。来摧毁暴风城吧！"
D.Strings[40206]="士兵们，你们要学习$n，誓死保卫暴风城，抵抗敌人的进攻。"
D.Strings[40207]="这些邪教徒已经决意要毁灭暴风城。我们必须时刻保持警惕，守卫我们的城市和国王，就像$n所做的那样！"
D.Strings[40208]="你们都将被烧毁！"
D.Strings[40209]="我们将为暴风城奉献我们的全部忠诚，女士！"
D.Strings[40210]="还有邪教叛徒？能把他们抓起来实在是一件好事。"
D.Strings[40211]="你终于回来了！我们已经开始担心你被逮捕了。"
D.Strings[40212]="我们能用那个丑家伙换几个椰子？"
D.Strings[40213]="吃土去吧，矮子！"
D.Strings[40214]="软弱的矮人，毫无用处！"
D.Strings[40215]="又完蛋一个。"
D.Strings[40216]="可怜的，长胡子的小老鼠！"
D.Strings[40217]="还有蛮锤渣滓。向那座山脊发动进攻！"
D.Strings[40218]="提高警惕，$n。龙喉就要进攻了！"
D.Strings[40219]="攻占山脊！消灭蛮锤矮人！"
D.Strings[40220]="我会抓住你的，金矿！"
D.Strings[40221]="以古加尔的名义，你在干什么？！"
D.Strings[40222]="传送门将开启，你们宝贵的城市将被夷为平地！"
D.Strings[40223]="只有这种带劲的南海朗姆酒能让我的骨头暖和起来！"
D.Strings[40224]="呦喉，呦喉，我应该去干海盗！"
D.Strings[40225]="你要为此付出代价，叛徒！"
D.Strings[40226]="你以为你已经赢了，但暮光的力量才能取得最终胜利！"
D.Strings[40227]="没错！他们可以不断地杀过来，而我们将一次又一次地把他们打趴下！"
D.Strings[40228]="这就是对付兽人的办法，男孩们。"
D.Strings[40229]="好了，去工作吧。如果我们的速度够快，我们就能在敌人再次发动攻击之前完成这里的任务。"
D.Strings[40230]="快一点，桑德玛尔需要这些物资。"
D.Strings[40231]="我们完成了！现在那些龙喉兽人如果想要伏击蛮锤部族，我们会给他们一点颜色看看。"
D.Strings[40232]="这个世界充满了瑕疵！我们必须开始一个全新的世界！"
D.Strings[40233]="奥丹姆的秘密只能属于我们！"
D.Strings[40234]="你不可能阻止我们！我们将释放这片坟墓下面所埋藏的能量！"
D.Strings[40235]="我们将毁灭所有反对我们的人！"
D.Strings[40236]="我的剑上又多了一道凹痕。"
D.Strings[40237]="又一场胜利！我的腰带上又能多挂几把胡子了。"
D.Strings[40238]="哈！把蛮锤矮人赶下他们的狮鹫，看看他们能怎样战斗。这帮无用的家伙！"
D.Strings[40239]="我们上吧，我的剑刃已经在渴望着战斗了。"
D.Strings[40240]="结束了。把这个地方彻底摧毁。不要留下任何东西！"
D.Strings[40241]="<当你靠近这座控制台的时候，它发出一阵“嗡嗡”声。>"
D.Strings[40242]="我想，我们只能把这些丢掉了……等等！我突然有了个主意。"
D.Strings[40243]="是的，绝对是个好主意。"
D.Strings[40244]="好啊，好啊！"
D.Strings[40245]="你能从那些腿上弄一个垫片下来！"
D.Strings[40246]="要以正弦波的幅度晃动它，宝贝！"
D.Strings[40247]="它是TXR-5000！"
D.Strings[40248]="200马力，双重燃烧引擎，修正流体电容！开动！"
D.Strings[40249]="我没想到它竟然还快如闪电！太惊人了！！"
D.Strings[40250]="检测修正的腿部关节！完美适应各种路况！"
D.Strings[40251]="我要检查这些曲线！"
D.Strings[40252]="真是……伟大！！！"
D.Strings[40253]="武装鲨鱼？为什么我没有想到这个？！"
D.Strings[40254]="厉害！！！"
D.Strings[40255]="真精彩！"
D.Strings[40256]="抓住我们的人和死亡之翼结盟了，$r。"
D.Strings[40257]="他们没有任何怜悯之心，你安心受死吧。"
D.Strings[40258]="这座笨重的雕像立在这里，已经有许多个世纪没有被碰触过了。"
D.Strings[40259]="虽然这座雕像已经非常古老了，却没有任何被风蚀损坏的痕迹。"
D.Strings[40260]="<将人偶放在缺口上。>"
D.Strings[40261]="奥格瑞玛的市民们，如你们所知，一个危险的邪教正在图谋分裂我们的城市。诺森德英雄，兽人的勇士，加尔鲁什·地狱咆哮酋长下达命令，在彻底摧毁那个邪教之前，要进入奥格瑞玛的人必须接受搜查和询问。"
D.Strings[40262]="根据颜色判断，这一定就是戒卫。$b$b你在它上面找到一个小缺口，与你的棋卒轮廓正好吻合。"
D.Strings[40263]="这座红色雕像很像是你带在身上的哨卫的棋卒。$b$b这座雕像上有一个小缺口，正好与你的棋卒形状相吻合。"
D.Strings[40264]="烈火与大地的远古之力，我已经为你们打通了道路。来摧毁奥格瑞玛吧。"
D.Strings[40265]="面粉与大地的远古之力，我已经为你们打通了道路。来摧毁奥格瑞玛吧。"
D.Strings[40266]="$n，你有什么可以报告的？你被跟踪了吗？"
D.Strings[40267]="我们需要及时弄清楚古加尔神秘武器的一切信息。"
D.Strings[40268]="看样子，这个矿洞里只有你、我和那两个大地之环成员。我们要加快速度，$n，在被发现前完成任务。"
D.Strings[40269]="真高兴能回到原野上。这里比暴风城的那些鸽子笼舒服多了。"
D.Strings[40270]="我们迟早都要与古加尔和碎颅者正面作战。你要参加这场战争吗，$n？"
D.Strings[40271]="希望你已经为这个有去无回的任务做好了准备，$n。你随时都可以退出，但我还是希望你能与我们并肩奋战。"
D.Strings[40272]="在对暮光堡垒发动最后的进攻之前，我们需要处理好这里的一切问题。"
D.Strings[40273]="我有没有告诉过你，暮光之锤曾经想要征募我？千真万确。"
D.Strings[40274]="这话别告诉别人，$r。让我们赶快把这里的问题解决掉。这样我就能去干掉古加尔了。"
D.Strings[40275]="三个？他至少值五个椰子，很轻松……蠢货！"
D.Strings[40276]="很高兴能在这里又看到你，$n。我们已经有许多兄弟姐妹落在了酋长的手里。我们还以为永远也见不到你了。"
D.Strings[40277]="有什么发现吗，$n？有没有被跟踪？"
D.Strings[40278]="我们需要尽快搞清楚古加尔到底在制造一种什么样的武器！"
D.Strings[40279]="那些暮光白痴根本不知道他们在制造什么样的灾难。"
D.Strings[40280]="古加尔一直藏在暮光堡垒里。真希望他能出来，好好和我们玩一玩。"
D.Strings[40281]="希望你已经为这个有去无回的任务做好了准备，$n。"
D.Strings[40282]="我们需要消灭所有邪教徒和他们的领袖，这样我们才能占领暮光堡垒。"
D.Strings[40283]="古加尔曾经用一个魔法咒语控制了我的心神，让我做了许多令我深感羞耻的事情。我要让他付出十倍的代价。而你要帮助我，$n！"
D.Strings[40284]="来吧，肮脏的邪教徒。"
D.Strings[40285]="好的，我会让这辆马车直达目的地。你留在后面，扫除我们的一切踪迹。准备好以后就告诉我。"
D.Strings[40286]="你怎么敢质问我？"
D.Strings[40287]="你的质问损害了我的荣誉。"
D.Strings[40288]="搜查快一点，我还要赶时间呢。"
D.Strings[40289]="希望你带来了矿工锄，朝圣者。没有任何地方能比这里更适合挖掘古代宝藏了。"
D.Strings[40290]="看上去没有问题，你可以走了。"
D.Strings[40291]="你可以进入奥格瑞玛了。"
D.Strings[40292]="这是邪教文书，你只能戴着镣铐进奥格瑞玛了。"
D.Strings[40293]="邪教的宣传手册。你被逮捕了！"
D.Strings[40294]="我不能让你带着这些邪教文章进入奥格瑞玛。"
D.Strings[40295]="装完车，做好准备之后就告诉我，$n。"
D.Strings[40296]="元素诅咒你！"
D.Strings[40297]="你只是酋长的一条狗！"
D.Strings[40298]="在火刃部族灭亡之后，我们剑圣就发誓，要从恶魔的统治之下解放我们自己和我们的族人。$B$B这个任务终于完成了，但我的荣誉并没有得到恢复。$B$B我要为部落而战，直到我在战场上光荣牺牲。这是我唯一的道路。$B$B好吧，你准备好进行训练了吗？"
D.Strings[40299]="又一只落进蜘蛛网的苍蝇……"
D.Strings[40300]="假首脑终于被消灭了，感谢你们，冒险者。"
D.Strings[40301]="在火刃部族灭亡之后，我们剑圣就发誓，要从恶魔的统治之下解放我们自己和我们的族人。$B$B这个任务终于完成了，但我的荣誉并没有得到恢复。$B$B我要为部落而战，直到我在战场上光荣牺牲。这是我唯一的道路。"
D.Strings[40302]="梵妮莎·范克里夫仍然在逃，谋划与我们对抗。但没有了这个基地，她已经无法对联盟造成威胁了。"
D.Strings[40303]="当我们清理死亡矿井的时候，我会提高警惕，防备任何可能发生的意外。希望我们能尽快让它恢复成往日那座著名的金矿。至于说那个首脑的命运……"
D.Strings[40304]="这就是……"
D.Strings[40305]="还有叛徒？把他们扔进大坑里去，那才是他们应该待的地方！"
D.Strings[40306]="找到闯入者！我知道他们就藏在北边！"
D.Strings[40307]="把你们的水泡眼睁大一点！我们中间有入侵者。"
D.Strings[40308]="为了古加尔的荣耀，工作得更卖力一些！"
D.Strings[40309]="我感觉到我们中间有一个外人！"
D.Strings[40310]="这件武器很快就能完成了。蛮锤矮人和龙喉兽人都将不复存在。"
D.Strings[40311]="集结一支部队，到湖边去。我要让瓦拉尔女伯爵活不过今天！"
D.Strings[40312]="暮光之锤的力量，无人能挡！"
D.Strings[40313]="准备进攻粉碎者据点和胜利者岗哨！"
D.Strings[40314]="你的爸爸说要把我射过这片海湾。"
D.Strings[40315]="科甘长官。更多的元素正从裂隙西侧涌过来。"
D.Strings[40316]="找到伊安。保护他召集的狮鹫骑士，和他们一同去挡住敌人，不要让敌人到达这个镇子。"
D.Strings[40317]="启动程序完毕。扫描目标……"
D.Strings[40318]="目标确认。扫描……"
D.Strings[40319]="异常察觉。可能来源：艾泽拉斯上古之神。尝试排除异常……"
D.Strings[40320]="异常排除。重复子程序……"
D.Strings[40321]="异常排除。重组剩余物料……"
D.Strings[40322]="可用目标编译。无异常。"
D.Strings[40323]="用户目标程序完成。停滞程序重新启动。"
D.Strings[40324]="我将召唤末日枯骨的力量，在恐惧中颤抖吧！"
D.Strings[40325]="看看它有多么巨大！你不害怕吗，凡人？你是否见到过如此伟大的毁灭之力？"
D.Strings[40326]="战栗吧，怪物，看我召唤出一支机械狼人的大军！"
D.Strings[40327]="现在，你已经被机械狼人包围了！你还能做些什么？你能逃到哪里去？"
D.Strings[40328]="接受这个吧，忘恩负义的元素。我为你们付出的一切努力都白费了！"
D.Strings[40329]="啊哈哈哈哈哈哈，开火？真的？"
D.Strings[40330]="我干掉你的朋友之后，下一个目标就是你！"
D.Strings[40331]="哦，是吗？嗯……抓住他！！！"
D.Strings[40332]="终于摆脱了，你这个狂妄的，被烤熟的，痴迷爆炸的纵火狂！看我还会不会再召唤你！"
D.Strings[40333]="好吧，让我们从他身上找到控制器，用这道传送门离开这里。"
D.Strings[40334]="这……这是什么？"
D.Strings[40335]="我死了！被暮光之锤杀死了。"
D.Strings[40336]="洛克之灵派你到这里。你要寻找信息。"
D.Strings[40337]="他们捉住并奴役我们，逼迫我们制造一件武器。"
D.Strings[40338]="那是一件特殊的东西……一件古加尔所需要的东西。"
D.Strings[40339]="我们被告知，我们将因为自己最伟大的工作而得到奖励，但我们……只得到了这样的下场。"
D.Strings[40340]="他们将一位上古之神的力量注入这件武器。"
D.Strings[40341]="这件你正在寻找的武器被称为暮光神锤。"
D.Strings[40342]="现在，走吧，我已看到了圣光……"
D.Strings[40343]="这股力量……太强大了……我坚持……不下去了……"
D.Strings[40344]="她派你来完成这个肮脏的任务，对不对？杀掉你之后，我自然会去对付她！"
D.Strings[40345]="不久之前，暮光之锤侵入了这片曾经质朴清澈的水域和它周围的岛屿。$B$B他们污染了我的湖水。我要彻底驱逐他们，这样我才能净化这片湖泊。"
D.Strings[40346]="摧毁大法师阿塔瑞克身边的奥术魔，让防护盾过载！"
D.Strings[40347]="这片土地是兽人和人类第一次展开大规模战争的地方。南边不到一里远就是斯通纳德。兽人在那里首次集结，入侵我们的国土。$B$B就是在这里，他们在我们不知不觉间聚集起大规模的军队。就是在这里，他们攻击西边的联盟小镇，拉开了三次兽人战争的序幕。$B$B那是我的城镇，为了救我，我的父母都死在了那里。$B$B但我来这里不是为了复仇……我是要赢得一场战争。"
D.Strings[40348]="喔……"
D.Strings[40349]="嘿！又错了！"
D.Strings[40350]="我必须……集中精神！"
D.Strings[40351]="真是……难啊！"
D.Strings[40352]="来吧，小子们，在这里组织防御。我们要把敌人挡在这里，否则桑德玛尔就危险了！"
D.Strings[40353]="拿起武器！"
D.Strings[40354]="缴械"
D.Strings[40355]="哎呀！救救霍格！"
D.Strings[40356]="霍格正在恢复生命！阻止他！"
D.Strings[40357]="霍格昏迷了！"
D.Strings[40358]="啊！！！什么……你怎么……？"
D.Strings[40359]="焊钩！你在发什么疯？我们带来了你需要的人员，但这里……根本没有什么研究工作。这里只有疯狂！"
D.Strings[40360]="什么……？？？？啊……"
D.Strings[40361]="蠢货！对他们来说，一切都已经太晚了。对你们所有人来说都太晚了！你们要和我们一起发掘出这个将毁灭世界的秘密！"
D.Strings[40362]="而你……是下一个！"
D.Strings[40363]="嗨！以前没有见过你。你也失去了家园吗？如果你愿意，可以和我坐在一起。"
D.Strings[40364]="哦，天哪！真的是非常感谢你。你不知道这对我有多么重要。你真是最好的人！"
D.Strings[40365]="你肯定不是蛮锤的人。为什么要到这里来？不管怎样，你在这个时候跑到这里来，只能说是你的运气不好。"
D.Strings[40366]="什……我的玫瑰？！是凯林告诉你的吗？真不知该怎样感谢你。我还以为自己再也闻不到家乡的气息了……"
D.Strings[40367]="很高兴见到你，年轻的$g先生:女士;。"
D.Strings[40368]="什么……？？"
D.Strings[40369]="我家的锤子？！怎么会在你这里……没关系，我不在乎这个，锤子回来了才是最重要的。我们永远都欢迎你，我们家的桌旁永远都有你的位置。谢谢你。"
D.Strings[40370]="为了锈水财阀！为了碎手军团！为了部落！"
D.Strings[40371]="我出了什么事？"
D.Strings[40372]="我在这片废墟中找到了这个。凯林告诉我，这是你的……"
D.Strings[40373]="相信这些应该是你的，米艾拉。"
D.Strings[40374]="如果我没弄错，这应该是你的。"
D.Strings[40375]="他们在我们没有察觉的时候偷袭了我们……同时对高地各处发动了攻击。他们破地而出，又从空中俯冲而下。大部分狮鹫都受惊逃走了。许多优秀的矮人白白牺牲。$B$B如果不是科甘及时将我们召集起来，重整了队伍，我们可能早已经被围歼了。是他救了我的命。至少现在，我们还有反击的机会。"
D.Strings[40376]="你肯定不是本地人。不过这对我来说没什么关系。无论是谁，只要真心愿意帮助我们，我都会和他生死与共。"
D.Strings[40377]="使用机械控制干扰器让焊钩的机械机甲无法运作！"
D.Strings[40378]="我很久以前就来到这里，研究我们受到诅咒的兄弟，寻找治疗他们的办法。$B$B玛格图尔热情地欢迎我。我住在这里的时候，他成为了我最亲密的朋友。$B$B而现在，他躺在我面前，奄奄一息……"
D.Strings[40379]="很抱歉，我辜负了你，我的朋友。"
D.Strings[40380]="该我了，阿弗恩。没有人应受责备……"
D.Strings[40381]="看上去，你能为我们挣不少钱。去杀戮熔炉里转一圈如何，朋友？"
D.Strings[40382]="躲开熔岩！"
D.Strings[40383]="这片高地全都属于龙喉氏族，这个大坑也不例外！"
D.Strings[40384]="我的小妹妹也能把你们都打趴下。这里不是竞技场。这里根本就是个托儿所！"
D.Strings[40385]="卡尔德说，如果我杀了你，我就能得到你的零件！"
D.Strings[40386]="你们好，伙计们，今晚，我为你们准备了一个不应该让你们太吃惊的惊喜。"
D.Strings[40387]="这片土地应该在暮光烈焰中被净化！"
D.Strings[40388]="我会把这个留在这里。"
D.Strings[40389]="现在该去找蛋了……"
D.Strings[40390]="我的小宝贝怎么样了？"
D.Strings[40391]="不……是……是你！不！"
D.Strings[40392]="你这个莽撞的小崽子……我知道你和那个凡人想要干什么。"
D.Strings[40393]="准备好去死了吗，龙？"
D.Strings[40394]="是的，只是……请饶过这颗蛋。"
D.Strings[40395]="饶过？！"
D.Strings[40396]="我什么也不会饶！你要为自己的冒犯而被烧为灰烬，龙！"
D.Strings[40397]="回去，蛆虫！（软弱，渺小的虫子！）"
D.Strings[40398]="看哪，凡人，这件造物便是你们的末日。（这战锤，是下界诸神之手。）用熔火之血铸造……（……主人的礼物。他的礼物！）在最后的风暴祭坛锻造。"
D.Strings[40399]="暮光神锤。（暮光神锤！）它由死亡的化身赐予。是世界的破坏者。不是你能使用的。（消灭入侵者！）把他们杀光！"
D.Strings[40400]="死亡之翼开始行动了……（……没人能够阻止。）没有人！尤其是你们这些可怜虫（让他们，让他们彻底完蛋！）"
D.Strings[40401]="伟大的杀戮熔炉正在等着你，$n。记住，当战斗开始的时候，你将无法离开竞技场。你的结局非赢即死！"
D.Strings[40402]="女士们，先生们，我们共聚在杀戮熔炉，再次见证生与死的伟大战斗！在这一轮中，我们将看到$n与……一个真正的肥食人魔对战？等等，这是真的？！我们就只能看到这个？我付钱给你是为了什么？"
D.Strings[40403]="不管怎样，让战斗开始吧！"
D.Strings[40404]="战斗就要开始了！$n对凶狠的龙喉兽人——“托格·掠龙者”！嗯，我想他应该是很凶狠的，虽然现在还很难说。既然他们让我们管理他们的老竞技场，我就把他放了出来。因为这里需要一些真正精彩的战斗！"
D.Strings[40405]="接下来为大家准备了个特别的节目！你们在这家伙面前简直渺小如微尘！$n对决凶残的蛮锤斗士……萨利·碎膝！！！"
D.Strings[40406]="这一战必定会速战速决！好吧，好吧，我说完了。血战开始！"
D.Strings[40407]="想象一下，当我遇到那个被遗忘者天才卡尔德·格雷的时候，是多么惊讶。他说，他制造出了一名战士，那名战士拥有以前所有勇士的全部最优秀的能力……真的会有这样的战士！有谁能拒绝向卡尔德的造物挑战的机会？！"
D.Strings[40408]="你知道他们所说的……如果不能击败他们，就加入他们！除此之外，你将别无选择！杀戮熔炉，我是如此热爱你。"
D.Strings[40409]="从遥远的吉尔尼斯废墟中传出阵阵吼声，我们的勇士来了！把裤子穿好，$n，你不会想让他看到两轮满月吧！"
D.Strings[40410]="暮光之锤：随时随地愿意为实现各种邪恶计划出力，今天也不例外！我们的终极战士向大家致敬！他们来自不远处的暮光堡垒……或者那是暮光城堡……管他呢，谁会在乎这个！"
D.Strings[40411]="有人赢了——赢了赢了赢了赢了！我们有了一位胜利者！干得漂亮！"
D.Strings[40412]="难以置信！新的杀戮勇士诞生了！！！我们高大的，凶恶的，力大无穷的挑战者被一个衣衫褴褛的无名之辈打败了！真是个不可思议的结局！"
D.Strings[40413]="不要伤害霍格！"
D.Strings[40414]="我们听命，血卫士。为了部落！"
D.Strings[40415]="嗯，$n领导了奥格瑞玛对抗末日教教徒的战斗。"
D.Strings[40416]="邪教徒并没有停止进攻。将命令传出去：安排两倍的卫兵，逮捕任何有嫌疑的人。这是酋长亲自下达的命令！"
D.Strings[40417]="握紧你的武器，冒险者！"
D.Strings[40418]="哈蒙德·克雷将军！"
D.Strings[40419]="这个怪物是河爪豺狼人的头领，如果要结束豺狼人对艾尔文入侵，也许就要从他下手。"
D.Strings[40420]="以国王瓦里安·乌瑞恩的名义，我们将对他予以监管。"
D.Strings[40421]="安多玛斯，带我们去监狱。"
D.Strings[40422]="看上去，这头狮鹫受了伤。也许治疗或急救技能可以让它重新站起来。"
D.Strings[40423]="狮鹫专注地看着你。它显然是从你的衣服上闻到了熟悉的气味。"
D.Strings[40424]="这头狮鹫似乎是被困住了。不过看上去，它应该能轻松地挣脱身上的束缚。"
D.Strings[40425]="你有1层神圣能量！"
D.Strings[40426]="你有2层神圣能量！"
D.Strings[40427]="你有3层神圣能量！"
D.Strings[40428]="让狮鹫嗅一下这块焦黑的高地桦木。"
D.Strings[40429]="当这片黑暗向狮鹫蔓延过去的时候，狮鹫绷紧了肌肉，眼神也变得犀利明亮。"
D.Strings[40430]="你竟然穿过了那条通道！我暴露了！"
D.Strings[40431]="我的痛苦是永恒的！"
D.Strings[40432]="狮鹫看着你，眼睛里充满了感激之情。"
D.Strings[40433]="伊瑟拉的幻象在你面前逐渐变得清晰真实。"
D.Strings[40434]="$n，你释放了狼魂先祖，并击败了他的影子。你的行动已经在梦境中产生了反响，谢谢你。但你还有更多的事要去做……"
D.Strings[40435]="<伊瑟拉的影像在你的眼前闪动，仿佛一切都是在梦中。再没有其他人看见她在这里。而那幻象显然也感觉到了你的存在。>"
D.Strings[40436]="当你将这头狮鹫解救出来的时候，它发出了欢快的叫声。"
D.Strings[40437]="托尔托拉已经在为我们而战了。你拥有巨大的智慧，$n。要赢得这位古老神祗的信任是非常困难的。而现在，他将成为我们可以依赖的力量。"
D.Strings[40438]="天空的守卫者再次展翅翱翔了！这真是令人振奋的消息，$n。但我们还有很多事要做。我们现在必须把注意力转到别的地方……"
D.Strings[40439]="<伊瑟拉的幻象如同梦一般飘落在你面前。一开始，她的心思似乎并不在你身上。过了一会儿，她才注意到你。>$B$B许多年以来，艾维娜一直在我的梦境边缘闪动。我想知道，她会不会回来。但我也害怕她的灵魂因为过去那段岁月而变得黑暗……$B$B不管怎样，如果我们真的要拯救这座山脉，就必须关注一些更紧迫的事情。"
D.Strings[40440]="不能受到干扰！我们不能让主人久等！决不能再次失败！"
D.Strings[40441]="一点儿也不浪费……"
D.Strings[40442]="剥去皮肉，收割内脏！"
D.Strings[40443]="再也不会有像我这样的……"
D.Strings[40444]="他们在智能方面的缺失能够用暴力来弥补！"
D.Strings[40445]="我的失败将是你的衰亡！"
D.Strings[40446]="为时尚早，但别无选择……必须实验！来面对我的原型实验体吧！"
D.Strings[40447]="见见我的心血之作！原型实验体，吞噬他们！"
D.Strings[40448]="|TInterface\\Icons\\INV_POTION_24.BLP:20|t马洛拉克将一只|cFFFF0000红瓶|r扔进了大锅里！"
D.Strings[40449]="|TInterface\\Icons\\INV_POTION_20.BLP:20|t马洛拉克将一只|cFF809FFE蓝瓶|r扔进了大锅里！"
D.Strings[40450]="|TInterface\\Icons\\INV_POTION_162.BLP:20|t马洛拉克将一只|cFF33FF00绿瓶|r扔进了大锅里！"
D.Strings[40451]="勇士们，求求你们，请从暮光之锤的手中救出我的兄弟吧！"
D.Strings[40452]="一定要阻止暮光巨龙！请救出其他红龙。我们会帮助你的！"
D.Strings[40453]="阿弗恩，有些人花费了数十年的时间思考这个秘密。我并不希望同样的命运会落在你身上。"
D.Strings[40454]="圣光不愿意让任何人受苦，我的孩子。但在我们的国度里，它并不能决定一切。"
D.Strings[40455]="现在，光明与黑暗之间的决战即将爆发。我们全都会受到召唤，参加这场大战。与它相比，所有凡间的痛苦都将变得毫无意义。"
D.Strings[40456]="玛格图尔，你已经勇敢地接受了你的挑战。现在，你准备好回归圣光的怀抱了吗？"
D.Strings[40457]="那么，愿圣光拯救你，激励你。"
D.Strings[40458]="记住，阿弗恩，并非所有徘徊者都是迷失之人。"
D.Strings[40459]="现在我仍是一无所获。为什么？为什么圣光会抛弃无辜者？"
D.Strings[40460]="先知维伦！"
D.Strings[40461]="……谢谢你，先知。你已经让我们得到了巨大的安慰。我会继续我的工作，这也是我对玛格图尔的纪念。"
D.Strings[40462]="嗨，看啊！它在飞！"
D.Strings[40463]="是的……"
D.Strings[40464]="这里真不错。你不这样认为吗？$b$b也许是有一点热，但只是干热而已……"
D.Strings[40465]="爸爸总是对我说，大家伙力气大，但速度慢……$b$b我相信爸爸一定没有见过这个家伙！"
D.Strings[40466]="疯狂。混乱。看到泰坦的作品没有完成时，我全身战栗。现在我只希望当主人回来的时候，自己还能活着。好了，我会帮助你的。"
D.Strings[40467]="<黑角望向地狱的远方，然后又将注意力转回到你身上。>"
D.Strings[40468]="我只想得到一点平静与安宁！"
D.Strings[40469]="愚蠢的凡人！你根本无法理解自己正在玩弄怎样的奥术力量！而我将结束这出魔法的闹剧！"
D.Strings[40470]="英雄们，你们并非在这黑暗之地孤军奋战！"
D.Strings[40471]="辛萨尼亚！你的主人欠我一笔巨债——我要好好在你的身上讨回来！"
D.Strings[40472]="那些肮脏的笨蛋强迫我离开了芬里斯城堡，我绝不会再被赶出我的营地！"
D.Strings[40473]="向女王致敬！"
D.Strings[40474]="这是必然结果。"
D.Strings[40475]="你这是白白送死！"
D.Strings[40476]="这是你的教训！"
D.Strings[40477]="站起来！你敢吗？"
D.Strings[40478]="哼哼！一定很疼吧！"
D.Strings[40479]="哈！太简单了！"
D.Strings[40480]="他们会对你保持一定程度的信任。"
D.Strings[40481]="这至少能让你得到证明自己的机会。"
D.Strings[40482]="这位勇士已经证明了自己的决心和能力。"
D.Strings[40483]="我认为，我们没有理由不信任它。"
D.Strings[40484]="一块不显眼的大理石板。"
D.Strings[40485]="将雕像放在这块石板上。"
D.Strings[40486]="一块不显眼的石板。"
D.Strings[40487]="塞纳留斯死了！"
D.Strings[40488]="<这位巨大的远古半神仍然对你保持着警惕，但他已经像对待盟友一样和你说话了。>"
D.Strings[40489]="回去参加战斗！"
D.Strings[40490]="海洋将完全属于我们，远大征程才刚刚开始。"
D.Strings[40491]="当我到达斯通纳德的时候，我还带着赫格拉姆。在我严厉的教导下，他成为了一名比以前更优秀的追踪者……也是我唯一的同伴。$B$B我以为自己很强。我以为任何痛苦都不可能让我的灵魂倒下。但是，当我看到那些人类的刀剑刺穿赫格拉姆，杀死了我的同伴……我发现自己彻底错了。"
D.Strings[40492]="找到一棵树去爬。"
D.Strings[40493]="抓住一只熊崽。"
D.Strings[40494]="爬到树顶。"
D.Strings[40495]="抛下熊崽！"
D.Strings[40496]="我是拉穆卡恒的纳顿亲王。尼斐塞特部族已经公然与其他托维尔为敌。$B$B请帮我逃出这里，这样我就能说服我的兄弟，也就是我们的国王向这些叛徒发动战争！"
D.Strings[40497]="我是拉穆卡恒的纳顿亲王。我的人民来自于托维尔……或者严格来说，是托维尔人的后代。$B$B尼斐塞特人本来也像我们一样有血有肉……$B$B但在死亡之翼到来之后，一切都改变了。"
D.Strings[40498]="他承诺会让我们恢复往日的光荣……再次成为真正的托维尔人。$B$B但条件是……我们必须发誓向他效忠。"
D.Strings[40499]="我们是了奥丹姆秘密的守护者。在无尽的沙海中……在巍峨的金字塔下……那里埋藏着无比强大的力量。$B$B那是足以形成和破坏整个世界的力量。$B$B但如果没有我们，他就无法使用这种力量。"
D.Strings[40500]="他已经让尼斐塞特部族成为了他的奴仆。$B$B奥西斯明确地摆出了挑战的姿态。$B$B拉穆卡恒竭力想找到一个和平解决的方法，但对于死亡之翼和他的盟军，和平是绝不存在的。"
D.Strings[40501]="把我解救出来。$B$B这样我们就能召集我的人民，共同对抗死亡之翼。$B$B如果你觉得这还不够，我还会给你丰厚的酬劳。毕竟，我是一位亲王。"
D.Strings[40502]="死亡之翼来到了这里，却没有把你们都杀光？"
D.Strings[40503]="这样说来，你们并没有全都与他结盟？"
D.Strings[40504]="同意。那么你想让我干什么？"
D.Strings[40505]="赶快！到飞机里面去！"
D.Strings[40506]="$n准备了一场烤全龙盛宴！"
D.Strings[40507]="$n准备了一场海鲜盛宴！"
D.Strings[40508]="继续前进。我的部下会处理这只悲惨的尸骨袋。"
D.Strings[40509]="血牙狂战士们开始大流口水。"
D.Strings[40510]="控制住你们自己！我们在这里唯一的目标是高弗雷的脑袋！其它战利品以后再拿！"
D.Strings[40511]="如果我们要干掉他，就必须全力向前推进。跟着我，我会打开院子的大门，让你们可以展开全面突击。"
D.Strings[40512]="冲啊！上啊！冲冲冲！"
D.Strings[40513]="我可以教导你任何最基础的采集和生产技能，仅此而已。\n\n如果你要学习初级以上的技能，你就需要去访问专门掌握某一个技能的大师。\n\n你最多可以学习两个主要专业技能：两个采集技能；或者两个生产技能；或者是采集、生产技能各一个。\n\n考古学、烹饪、急救和钓鱼是辅助技能，不会占用你的主要专业技能的学习位置。你可以学习全部辅助技能。"
D.Strings[40514]="和我说说采集技能。"
D.Strings[40515]="和我说说生产技能。"
D.Strings[40516]="采集技能让你能够获得生产技能所需的原始材料：采集草药；开采矿石、石料和宝石；或者从野兽的尸体上剥去皮革。\n\n你可以用自己采集来的原料支持你的生产技能需求，或者是在拍卖行中出售你采集来的原料。"
D.Strings[40517]="我要学习炼金术。"
D.Strings[40518]="我要学习锻造。"
D.Strings[40519]="我要学习附魔。"
D.Strings[40520]="我要学习草药学。"
D.Strings[40521]="我要学习铭文。"
D.Strings[40522]="我要学习珠宝加工。"
D.Strings[40523]="我要学习制皮。"
D.Strings[40524]="我要学习采矿。"
D.Strings[40525]="我要学习剥皮。"
D.Strings[40526]="我要学习裁缝。"
D.Strings[40527]="我要学习工程学。"
D.Strings[40528]="坚守阵地。蛮锤部族战至最后一息也不后退！"
D.Strings[40529]="首先，死亡之翼出现的时候没有太阳，而是阴云满空。"
D.Strings[40530]="那头胆小的龙一定是看见我了，因为他转过头，又钻进了黑云里。"
D.Strings[40531]="幸运的是，我一直在修补我的世界缩小设备。"
D.Strings[40532]="“我会在那堆云里找到你的，你这只大虫子！”我吼道：“然后我就会把你丢到卡利姆多去！”"
D.Strings[40533]="我会在那堆云里找到你的，你这只大虫子！"
D.Strings[40534]="然后我就会把你丢到卡利姆多去！"
D.Strings[40535]="我决定继续收缩世界，直到我能摸到那些云彩。$b$b|TInterface\\Icons\\inv_helmet_47.blp:32|t"
D.Strings[40536]="高阶萨满祭司就在这里——我能看到那团暴风云。干掉他，我们也许能从他身上弄到一个漂亮的战利品！"
D.Strings[40537]="生产技能让你可以将采集到的原始材料加工成各种有用的物品。你可以自行使用这些物品；或者将它们赠予你的同伴；或者在拍卖行出售它们。\n\n每一项生产技能通常都会有与之相对应的采集技能，这样你就可以用自己采集的原料支持你的生产技能。不过你也可以在拍卖行购买自己所需要的原料。"
D.Strings[40538]="草药学让你能在原野上找到并采集草药。草药可以在拍卖行出售，或者作为炼金术和铭文技能的原料。\n\n技艺高超的草药师还能利用他们对于大地的知识进行自我治疗。"
D.Strings[40539]="采矿让你能够在原野和地下洞窟中找到矿脉露头，采掘矿石、矿物、石料。你可以在拍卖行出售你的采掘成果，或者用它们支持锻造、工程学和珠宝加工技能。\n\n技艺高超的采矿师在采矿过程中会让身体逐渐强化，使耐力得到提升。\n\n如果要采矿，你需要一把矿工锄；你可以从商人或者采矿供应商那里购买到矿工锄。"
D.Strings[40540]="剥皮让你能够从被猎杀的动物身上剥取皮革，并对皮革进行硝制。你可以在拍卖行中出售你的皮革，或者用它们来支持你的制皮技能。\n\n技艺高超的剥皮师往往还是解剖学专家，从而提高他们对敌人造成爆击的几率。\n\n为了从动物身上剥取皮革，你需要一把剥皮小刀。你可以从商人或者制皮供应商那里买到剥皮小刀。"
D.Strings[40541]="炼金术让你能够利用草药和其它原料制作具有各种效能的药剂、药水、油剂、合剂和药锅。如果你使用自己配制的药剂和合剂，你获得的优势将更为强大，持续时间也会更长。\n\n技艺高超的炼金术师还能够制作出各种元素和矿物材料，供其它生产技能使用。\n\n炼金术师与草药学为对应技能，你可以利用草药学自行采集草药，供炼金术使用。"
D.Strings[40542]="锻造让你能够利用金属、矿物和石料铸造近战武器，锁甲、板甲等重型铠甲，以及其它专业技能所需的原料，还能让你制造磨刀石、盾刺等可升级装备的物品。\n\n技艺高超的锻造师能够在他们自己的护腕和手套，以及他们自己或他人的腰带上开凿宝石槽。这些宝石槽中可以装入魔法宝石，使物品变得更加强大。\n\n锻造很适合与采矿搭配，因为你可以利用采矿自行采集矿石等原料，供锻造使用。"
D.Strings[40543]="龙喉兽人进攻了！保护高阶萨满祭司。"
D.Strings[40544]="警报……龙喉兽人！"
D.Strings[40545]="附魔让你能够对物品施加魔法，从而使它们具备各种作用；并能够分解物品；以及制造魔杖和魔法油。\n\n技艺高超的附魔师甚至可以对他们自己的戒指进行附魔。这是其他人绝对无法做到的。\n\n附魔所需要的大部分原料必须通过分解物品获得。这会摧毁被分解的物品。所以这一技能和裁缝是对应技能。你可以通过分解带有魔法效能的裁缝物品提取出附魔所需的原料。\n\n附魔师还能将魔法施放在羊皮纸上。附魔师可以将这样的羊皮纸在拍卖行出售，或者保存它们，供以后使用。你可以从附魔供应商那里购买羊皮纸和其它有用的附魔材料。"
D.Strings[40546]="工程学让你能够制造各种有用的，令人惊叹的，或者是怪异无比的物品。比如步枪和瞄准镜，摩托车，还有机械松鼠。但这些物品中有许多只能供你自己或者其他工程师使用，比如特殊的眼镜，腰带、靴子、手套和斗篷上的机械配件，以及飞行机械。\n\n大部分工程学原料都是通过采矿获得的金属，所以这两个技能为对应技能。\n\n制造许多工程学物品都需要铁匠锤和一些必要材料，比如火药和熔剂。你可以从商人或者工程学供应商那里购买它们。"
D.Strings[40547]="铭文让你能够制造魔法卷轴、雕文、副手武器、暗月卡片，甚至还有其它专业的配方。\n\n铭文所需的许多原料都来自于草药学采集的草药，所以这两个技能很适合搭配。\n\n你需要学者的书写工具来制作铭文物品，此工具和羊皮纸等其它铭文材料都可以从铭文供应商那里购买。"
D.Strings[40548]="珠宝加工让你能够制造魔法戒指、项链、饰品以及切割宝石。\n\n珠宝加工所需的宝石可以通过购买获得，也可以对通过采矿技能获取的矿石进行选矿，从而获得。因此，珠宝加工和采矿是对应技能。\n\n制作大多数珠宝加工制品都需要用珠宝制作工具。高级珠宝加工制品往往还需要简易研磨器。这些工具都能够从珠宝加工供应商那里购买。"
D.Strings[40549]="制皮让你能够用皮革、整皮和鳞片制造皮甲、斗篷、皮甲强化护甲片和其它类似物品。制皮所需的其它材料可以通过玩家间交易获得，或者从制皮供应商那里购买。\n\n制皮与剥皮为对应技能。你可以通过剥皮技能获得原料，支持你的制皮技能所需。制皮所需的其它必要物品，比如线和染料都可以从商人或者制皮供应商那里购买。\n\n技艺高超的制皮师还可以强化他们的护腕和腿甲。"
D.Strings[40550]="裁缝让你能够用各种布料制造护甲、斗篷、衣服、袋子、魔线和其它类似物品。你可以购买这些布料，或者通过杀死人形生物获得布料。其它的必要材料，比如线和染料都可以通过玩家间交易获得，或者从裁缝供应商那里购买。\n\n技艺高超的裁缝还能够用魔法刺绣来强化他们的斗篷。\n\n很多裁缝都会兼作附魔师，这样他们就能分解他们制作出来的魔法物品了。"
D.Strings[40551]="和我说说草药学。"
D.Strings[40552]="和我说说采矿。"
D.Strings[40553]="和我说说剥皮。"
D.Strings[40554]="和我说说炼金术。"
D.Strings[40555]="和我说说锻造。"
D.Strings[40556]="和我说说附魔。"
D.Strings[40557]="和我说说工程学。"
D.Strings[40558]="和我说说铭文。"
D.Strings[40559]="和我说说珠宝加工。"
D.Strings[40560]="和我说说制皮。"
D.Strings[40561]="和我说说裁缝。"
D.Strings[40562]="什么？更多的龙喉兽人？收紧队形，绝对不要散开——他们正从四面八方攻过来！"
D.Strings[40563]="一旦这个世界收缩到足够小，我就会开始在云端猎捕死亡之翼。$b$b|TInterface\\Icons\\spell_frost_arcticwinds.blp:32|t"
D.Strings[40564]="大家打得好！我的锤子上又多了几道刮痕，而威胁桑德玛尔的龙喉兽人又少了一些。"
D.Strings[40565]="守住主路。愚蠢的龙喉兽人一定会再次发动进攻的。"
D.Strings[40566]="血牙是为你们而来的，狼人猎手们！"
D.Strings[40567]="指挥官斯普林瓦尔就在那座大厅里，英雄们。"
D.Strings[40568]="那个蛮锤高阶萨满祭司已经完了。计算一下我们的死伤。溅血谷地一定在等待着我们胜利的消息！"
D.Strings[40569]="他们很快就会回来。我们回溅血谷地去。"
D.Strings[40570]="使用流星，对%s造成致命一击！"
D.Strings[40571]="我已经搜查了每一片云，但就是找不到死亡之翼。"
D.Strings[40572]="这时我意识到：他正藏在太阳里。我向上望过去。"
D.Strings[40573]="对于这个地下室，你有一种很不好的感觉……"
D.Strings[40574]="太阳严重地灼伤了我，但我的双手终于抓住了他黏滑的脖子。"
D.Strings[40575]="我聚集起全部力量，转向西方，将他朝卡利姆多扔了过去。"
D.Strings[40576]="你一定要试试这种啤酒。"
D.Strings[40577]="再和我聊聊那个故事，卢希恩。"
D.Strings[40578]="龙，你在哪里？"
D.Strings[40579]="你藏在这团云里吗？"
D.Strings[40580]="卢希恩要抓住你！"
D.Strings[40581]="吃惊吧，龙！哦，哼！"
D.Strings[40582]="你在哪里？"
D.Strings[40583]="他不可能逃得太远……"
D.Strings[40584]="等我找到那条龙，我就把它扔到卡利姆多去。"
D.Strings[40585]="我恨你，死亡之翼。"
D.Strings[40586]="喔，卢希恩。你绝对不能再喝了。"
D.Strings[40587]="如果你不打算工作，那就离我们的发掘场远一些。"
D.Strings[40588]="嘿，帅哥！"
D.Strings[40589]="还有地方吗，甜心？"
D.Strings[40590]="跟我走吗？"
D.Strings[40591]="一位淑女能够上马驰骋一番吗？"
D.Strings[40592]="马特克，你今天看上去很英俊。"
D.Strings[40593]="哦，马特克，我能和你一起驰骋吗？"
D.Strings[40594]="马特克，你是我所知道的最勇敢的兽人。"
D.Strings[40595]="救救我，马特克！我需要你！"
D.Strings[40596]="上来，宝贝。"
D.Strings[40597]="我闻到了沃登的臭气。今天他难逃一死！"
D.Strings[40598]="骨头？"
D.Strings[40599]="这条路通向城市的更深处。继续朝南，向装载室走。"
D.Strings[40600]="我对此有一种不祥的感觉……"
D.Strings[40601]="克莱的一支投石机部队在前线被击溃了。$n，我需要你从他那里取得一些零件，让那架投石机重新投入战斗！"
D.Strings[40602]="真是荣幸，$c。$b$b这些日子里，来我们这里的人实在是太少了。"
D.Strings[40603]="真是令人惊讶！$b$b没想到今天会有人来……"
D.Strings[40604]="死亡之翼到来的那一天，血雨腥风，好不可怕。"
D.Strings[40605]="那时我应该正在向一些辣妹展示我的摩托车。"
D.Strings[40606]="死亡之翼一出现，她们都被吓坏了，但我只能救走她们之中的一个。"
D.Strings[40607]="当然，我选择了兽人。"
D.Strings[40608]="当然，我选择了人类。"
D.Strings[40609]="当然，我选择了暗夜精灵。"
D.Strings[40610]="当然，我选择了血精灵。"
D.Strings[40611]="我们在山谷中飞驰，一边还要注意躲避落石。"
D.Strings[40612]="当我到达山谷尽头的时候，我才想起我的摩托车是能飞的。"
D.Strings[40613]="如果我能早一些想起来，情况一定会好得多。"
D.Strings[40614]="我飞到了山谷北边的柱子顶端。"
D.Strings[40615]="在那里，我看见了：死亡之翼。最终的决斗到来了。"
D.Strings[40616]="嗨，住嘴，塞尔杜林！这是我的故事！"
D.Strings[40617]="闭上嘴！别打断我！"
D.Strings[40618]="好吧，你听不到我是怎样用匕首打败死亡之翼的。这是你的损失。"
D.Strings[40619]="我一边飞翔，一边与那个可爱的兽人度过了温柔的一刻。"
D.Strings[40620]="我一边飞翔，一边与那个诱人的人类度过了温柔的一刻。"
D.Strings[40621]="我一边飞翔，一边与那个优雅的暗夜精灵度过了温柔的一刻。"
D.Strings[40622]="我一边飞翔，一边与那个窈窕的血精灵度过了温柔的一刻。"
D.Strings[40623]="你干扰我的工作了，$c。"
D.Strings[40624]="我……辜负了主人……"
D.Strings[40625]="啊，琼斯博士，那位著名的考古学家！感谢你在这里所做的一切，我的任务现在轻松多了。"
D.Strings[40626]="我还需要一块灾难预言公告板。"
D.Strings[40627]="聚集在一起。我们成功了。让我们开始吧！"
D.Strings[40628]="不！我爱你，马特克！"
D.Strings[40629]="为什么？为什么你要离开我？"
D.Strings[40630]="我爱你，马特克！"
D.Strings[40631]="很高兴能够在活着的时候认识你，马特克。"
D.Strings[40632]="再见，马特克。"
D.Strings[40633]="在这里休息一会儿，恢复一下力量。"
D.Strings[40634]="知道我最后的时刻能够和马特克在一起，我就能安心地死去了。"
D.Strings[40635]="我永远也不会忘记那段与你共渡的美好夏日，马特克。"
D.Strings[40636]="好啊！马特克选择了我！"
D.Strings[40637]="好了！睁大眼睛，关照好平民。我们行动。为了桑德玛尔！"
D.Strings[40638]="我们已经做了我们能做的一切。现在，让我们回桑德玛尔吧！"
D.Strings[40639]="必须承认，我对这个野心勃勃的小狂徒有了些兴趣。$b$b我不会急于做出判断，但我要告诉你，我已经听到了一些令人不安的谣言。$b$b时间会告诉我，他的动机是否正当。"
D.Strings[40640]="这里的效率真高，你说呢？"
D.Strings[40641]="这……是什么？！"
D.Strings[40642]="雕像活了？！"
D.Strings[40643]="我知道你在找什么，司克诺兹！只要有我在，死亡之翼永远也别想得到那只箱子！"
D.Strings[40644]="的确是效率惊人。你对我们主人有什么看法？"
D.Strings[40645]="寒冰之拳！"
D.Strings[40646]="烈焰之拳！"
D.Strings[40647]="你怎么会来找我们这些衰老又疲惫的沙漠狗子？"
D.Strings[40648]="小心——龙喉兽人有埋伏！"
D.Strings[40649]="再把那个故事为我讲一遍，马特克。"
D.Strings[40650]="我已经在战场上遭遇了他的一些部下。他们的能力相当强大。"
D.Strings[40651]="我并不吃惊。$b$b我也不可能忽略这么多的问题……$b$b为什么一个考古发掘场里会有这么多武器？这与埋藏在地下的宝物有什么关系吗？这里的发掘人员到底效忠于谁？$b$b我还没有找到这些问题的答案。我想，我得自己去寻找真相。"
D.Strings[40652]="所以，我们必须确保你和你的朋友不会插手这件事。"
D.Strings[40653]="白痴！$b$b快滚开！$b$b难道你看不出来，我正在集中精神吗？"
D.Strings[40654]="石巨人发出“隆隆”的声音，仿佛是在表示感谢。"
D.Strings[40655]="石巨人显示出困惑的神情，过了一会儿，他跑开了。"
D.Strings[40656]="石巨人敲击着他的水晶，表达谢意。"
D.Strings[40657]="石巨人带着怀疑的神情看着你。"
D.Strings[40658]="石巨人尝试着露出微笑，你听到一阵响亮的岩石撞击声。"
D.Strings[40659]="石巨人高兴地击打着地面。"
D.Strings[40660]="石巨人发出一阵满足而沉重的叹息声。"
D.Strings[40661]="石巨人兴奋地奔跑着，为自己重获自由而激动不已。"
D.Strings[40662]="抱歉打扰你，马特克。虽然你已经得到了承认……是我让你的故事精彩了五十倍。下次也应该让我露露脸了。"
D.Strings[40663]="格拉布托克让你看看奥术的力量！"
D.Strings[40664]="听我说！朋友，举起望远镜！$b$b好好看看这里。$b$b要知道，在漫长的岁月里，这个地方一直被隐藏着。"
D.Strings[40665]="你对我们慷慨的主人有些什么了解，阁下？"
D.Strings[40666]="看看他积聚的财富！$b$b他的手段经常会让我感到不舒服，但这个结果却是无法否认的……$b$b不要去想那些令人不快的事情了。要知道，这样也不礼貌。"
D.Strings[40667]="嗯，你怎么会来到这里的？"
D.Strings[40668]="好好想想，我亲爱的$g男孩:女孩;！$b$b一旦我们野心勃勃的小毛皮商发掘出足够的财宝，他就会成为艾泽拉斯最有影响力的角色。$b$b如果这一天到来，我们都会有一个令人满意的地位。"
D.Strings[40669]="他们没有注意到我们。赶快，也许我们还能阻止他们！"
D.Strings[40670]="我们应该会再见的，司克诺兹。"
D.Strings[40671]="没这么快，司克诺兹！"
D.Strings[40672]="永远！"
D.Strings[40673]="别想活着看到你那个宝贵的箱子了，琼斯！"
D.Strings[40674]="不就是这里吗？$b$b与志同道合的伙伴一同探索这个世界从未被开发过的角落？$b$b还有什么能比这样更好的？"
D.Strings[40675]="的确！你是怎样找到元首的，朋友？"
D.Strings[40676]="对于我来说，他有些太活泼了。但我想，这个世界需要各种各样的人。$b$b你为什么要问这个？"
D.Strings[40677]="摧毁黑曜石巨像！"
D.Strings[40678]="他的部队，这些卫兵……看上去倒是有些强大。"
D.Strings[40679]="我明白你的意思，我想……$b$b说实话，我来这里只是因为想要看看这个世界和各种奇异的事物，让我的知识面扩大一些。$b$b对于其他人的事情，我并不是很关心。$b$b不过还是很高兴见到你。"
D.Strings[40680]="不要碰到那些高热光线！"
D.Strings[40681]="这里的风景真美，不是吗，$c？"
D.Strings[40682]="啊，是的。在这里的时光你是怎样渡过的？"
D.Strings[40683]="实在是太棒了！$b$b元首是如此自信，还有他的声音！必须承认，他的样子真是有魅力。$b$b你知道他结婚了吗？"
D.Strings[40684]="嗯……我不确定。关于他，你还能告诉我一些什么事情？"
D.Strings[40685]="有传闻说，这里的一些古物具有神秘的力量！$b$b他似乎已经对这些东西彻底着迷了……"
D.Strings[40686]="你怎么看他手下的部队？看起来很厉害吧？"
D.Strings[40687]="很抱歉，$c。$b$b对此我真的没什么了解，所以我没什么可说的。"
D.Strings[40688]="你就是我经常听说的那个$r$c？"
D.Strings[40689]="说说你的情况，$r。"
D.Strings[40690]="我们正在注意你，$r……"
D.Strings[40691]="……一直在注意！"
D.Strings[40692]="如果佐尔奇克不在你的攻击范围内，就使用你的“跃向幼龙！”技能：\n\n|TInterface\\Icons\\ability_vehicle_launchplayer.blp:64|t"
D.Strings[40693]="巨龙峡口是联盟在荒芜之地建立的第一个立足点。虽然荒芜之地位于暴风城和丹莫罗中间，但在传统上，它一直是部落的势力范围。$b$b现在这一情况已经发生了改变，我们需要确立自己的权属地位。当然，那头龙对新卡加斯的进攻也不会干扰我们的计划。"
D.Strings[40694]="得知黑龙要与新卡加斯对抗，我像你一样感到惊讶。高恩非常顽固，拒绝任何人的帮助。$b$b即使这样，高阶考察者泰瑟兰·血望者还是要求我时刻注意新卡加斯的情况，以确保局势对我们不会太……糟糕。"
D.Strings[40695]="我们必须阻止塞拉赞恩的军队进攻巨石之炉。$B$B否则他们就有可能偷走世界之柱的中部残片。"
D.Strings[40696]="英雄们！我的力量消褪了……"
D.Strings[40697]="你以为就这么简单？愚蠢！"
D.Strings[40698]="够了！汲取这力量之源将使几个月的努力白费。你们应该为自己担得起这份损耗而感到自豪！现在……死吧！"
D.Strings[40699]="火焰即将熄灭，勇士们……带上我最后的力量。继承我未竟的事业。替我复仇。替这个世界复仇……"
D.Strings[40700]="又一个白白牺牲的家伙！我几乎已经能让他开口了。"
D.Strings[40701]="全体向$n欢呼！万岁！"
D.Strings[40702]="的确！"
D.Strings[40703]="我需要一艘前往荒芜之地的小船。"
D.Strings[40704]="我们钓鱼，我们睡觉，我们炸飞各种东西。还有什么生活能比这样更好？"
D.Strings[40705]="我能乘船去东瘟疫之地吗？"
D.Strings[40706]="飞艇将在六分钟后到达。"
D.Strings[40707]="飞艇将在五分钟后到达。"
D.Strings[40708]="飞艇将在四分钟后到达。"
D.Strings[40709]="飞艇将在三分钟后到达。"
D.Strings[40710]="飞艇将在两分钟后到达。"
D.Strings[40711]="飞艇将在一分钟后到达。1分钟。"
D.Strings[40712]="你这是要准备登上杜隆塔尔之矛号，对吧？你就要遭人嫉妒了，部落士兵！"
D.Strings[40713]="你们的新飞艇将飞跃地平线，开启航空学上的新纪元。"
D.Strings[40714]="真正的工程学根本不会在乎什么财政预算和那些愚蠢而低效率的“物理法则”。"
D.Strings[40715]="在你们等待它的到来时，我和我的助手会先讲解一下这艘非凡航空器的特别功能。"
D.Strings[40716]="大家都知道，空气的重量极小。所以，为了建造一艘比空气还要轻的飞船，我们就必须改变一些规则。"
D.Strings[40717]="杜隆塔尔之矛号里面充满了过热的易燃气体。"
D.Strings[40718]="锈水工程师们充分利用了这种气体固有的高度不稳定性和低成本优点。"
D.Strings[40719]="我们对这种气体施加巨大的压强，降低了这种气体的爆炸性。"
D.Strings[40720]="为了实现这一点，我们还去掉了一些总是让气体喷出去的安全阀。"
D.Strings[40721]="哦，是了。为了让飞艇的续航力和有效载荷达到最大化，我们还为它殿堂级的伟大引擎调配了一种非正统的火箭燃料。"
D.Strings[40722]="这种燃料中蕴含着极为强大的能量，只要一点刺激，就有可能发生爆燃。"
D.Strings[40723]="这种物质有很强的爆炸性，它也许不应该被挪动，更不要说是……飞行了。"
D.Strings[40724]="今天你们的航线是直接跨越大海。"
D.Strings[40725]="这是一个辽阔而残酷的世界，充斥于其中的是灰色的惊涛骇浪，极度凛冽的寒风，还有各种庞大的海洋怪兽。"
D.Strings[40726]="相信我，朋友，通过服药获得的迅速死亡远比在经受漫长的寒冷之后再被鲨鱼撕碎要好得多。"
D.Strings[40727]="不要问我们怎么会知道它们的味道。"
D.Strings[40728]="如果你们的飞艇在途中遭到攻击，惊慌失措肯定是不明智的。"
D.Strings[40729]="你们应该迅速找到并操作安装在甲板上的火炮，对抗敌人的进攻。"
D.Strings[40730]="格瑞里，给他们演示该如何操作甲板火炮。"
D.Strings[40731]="只要瞄准，再扣动扳机。或者不瞄准也行。你会怎么干和我可没有任何关系。"
D.Strings[40732]="格瑞里，你不会在锈水港随意开火吧？"
D.Strings[40733]="如果发生了灾难性的事故，船上却还有幸存者，当然这种情况的可能性不大……"
D.Strings[40734]="……船栏旁边能找到一些降落伞。"
D.Strings[40735]="只需要抓住身边的降落伞，跳离燃烧的飞艇。然后希望自己能平安落在陆地上就行了。"
D.Strings[40736]="格瑞里，你要不要示范一下我们的降落伞是如何工作的？"
D.Strings[40737]="很好，杜隆塔尔之矛号差不多要到达了。"
D.Strings[40738]="你们的安全和福祉已经与我无关了。"
D.Strings[40739]="祝你有一趟刺激的高地之旅！"
D.Strings[40740]="不要在舒适和安全方面浪费一个钱！"
D.Strings[40741]="我们把没用的废物都省掉了！"
D.Strings[40742]="我们一省再省。"
D.Strings[40743]="你自己想一想：一个总是漏气的“安全”阀有什么用？我感觉这种东西一点也不安全。"
D.Strings[40744]="和他们说说引擎，老板。"
D.Strings[40745]="我们称它为“末日果汁”。"
D.Strings[40746]="当然，只是口头上说说。"
D.Strings[40747]="为了保证在失火时能够让全体船员迅速做出反应，燃料箱已经从船员区挪到了乘客舱室下方。"
D.Strings[40748]="飞艇落在海面上的可能性不大。不过，如果发生了这样的事情，请伸手到椅垫下面，你可以在那里找到一粒专门为您准备的氰化物胶囊。"
D.Strings[40749]="为了避免您对氰化物的杏仁味过敏，我们特意为胶囊添加了各种调味剂。"
D.Strings[40750]="您还能找到一袋免费赠送的花生。"
D.Strings[40751]="朝各个方向随机掷出熔融金属，只有这样才能让一支由易燃飞船组成的舰队确保绝对安全！"
D.Strings[40752]="非常愿意！"
D.Strings[40753]="我能从这里击中我的房子！"
D.Strings[40754]="也许。"
D.Strings[40755]="偶尔会。"
D.Strings[40756]="我们称它为“紧急无坡道离船装置”。"
D.Strings[40757]="哦，天哪，不！这些东西都是死亡陷阱！"
D.Strings[40758]="我们留在锈水港的全体人员……"
D.Strings[40759]="别碰那些暗影符文！"
D.Strings[40760]="小心收集"
D.Strings[40761]="该死的……失去潜在收入的后果是灾难性的。"
D.Strings[40762]="你正在找的那东西很快就会属于我了，琼斯博士！"
D.Strings[40763]="格拉布托克，好了吗？"
D.Strings[40764]="奥术力量！"
D.Strings[40765]="克罗雷竟然向被遗忘者屈服了。他真是我们一族的耻辱。我们要让他们看看什么才是真正的狼人，要让他们尝尝我们无情的怒火！"
D.Strings[40766]="就这把烂锁？真可笑！想要打败我们，高弗雷可得再争气点才行啊。"
D.Strings[40767]="你的死期到了，高弗雷！"
D.Strings[40768]="我赶了这么远的路，就是为了和著名的“龙喉先知”谈一谈。在毁灭古加尔之前，我想看清楚他的黑心里面到底有什么。$B$B但她没告诉我任何有意义的东西。我只得到了一堆谜语。也许你能帮助我。"
D.Strings[40769]="那个箱子就在废墟里。$b$b我们行动！"
D.Strings[40770]="我们已经太久忽略了奥术的秘密。$B$B你是来学习这个秘密的吗？"
D.Strings[40771]="我们已经太久忽略了奥术的秘密。$B$B可惜的是，它对你来说只能是个秘密。"
D.Strings[40772]="从巨像背后攻击它！"
D.Strings[40773]="感谢你救出了国王……还有王子，$n。"
D.Strings[40774]="你让我明白了朋友的意义，$n。"
D.Strings[40775]="我见证了你的成功，$n。你是你们一族的骄傲。"
D.Strings[40776]="边界安全了，指挥官。"
D.Strings[40777]="我累了！"
D.Strings[40778]="进攻，兄弟们！让他感受到狼群的怒火！"
D.Strings[40779]="抱歉，$c。$B$B你对奥术的掌握还不够强大，还无法理解传送门魔法。"
D.Strings[40780]="你也是一名奥术的研究者？$B$B我可以教导你传送门魔法的技艺，如果你想学的话。"
D.Strings[40781]="很好。让我查看一下上次做的笔记……"
D.Strings[40782]="嗯，是的，是的……够简单……"
D.Strings[40783]="哦，哥培尔！我们已经准备好了！来吧，来吧！"
D.Strings[40784]="如果你还想参加战斗，那最好快一点。"
D.Strings[40785]="坚持住，哥培尔！所有人都向后站！"
D.Strings[40786]="在静电充能结束前使用你的暴风护盾！\n\n|TInterface\\Icons\\spell_nature_lightningshield.blp:32|t"
D.Strings[40787]="你吸收了3层静电充能。你的下一次风暴战锤将造成巨大的面积伤害！\n\n|TInterface\\Icons\\spell_nature_lightningoverload.blp:32|t"
D.Strings[40788]="到底发生了什么错误！我严格依照每一个细节……"
D.Strings[40789]="等等！这是什么！？"
D.Strings[40790]="你只是给我带来了八个雕像！"
D.Strings[40791]="这个仪式需要九个！！"
D.Strings[40792]="九个！九个！九个！九个！九个！！！"
D.Strings[40793]="滚开，别让我看到你！混……"
D.Strings[40794]="我可怜的哥培尔……"
D.Strings[40795]="敢惹老子就是死路一条！"
D.Strings[40796]="以地狱的名义，这里到底发生了什么？"
D.Strings[40797]="你也许能活着走进这座山，但我保证你没办法活着出来。"
D.Strings[40798]="托尔巴拉德是我的，是我的！"
D.Strings[40799]="只要最后一击，这座岛就是我们的了。振作起来，我们将在早晨开始行动。"
D.Strings[40800]="无论你是谁，给我滚开！遗忘丘是我的……我的！"
D.Strings[40801]="我不知道为什么这扇门关上了，英雄们。我的狼群现在应该已经干掉高弗雷了……"
D.Strings[40802]="我们不会再袖手旁观了！现在是采取行动的时候！"
D.Strings[40803]="小心蜘蛛！隆克来了！"
D.Strings[40804]="隆克骑着蜘蛛！"
D.Strings[40805]="蜘蛛肚子时间！"
D.Strings[40806]="停住别动，蜘蛛！"
D.Strings[40807]="隆克要骑你了！"
D.Strings[40808]="我弄些毒液给你。"
D.Strings[40809]="隆克用他的肚子给你弄了些毒液。"
D.Strings[40810]="看到了吗？要取得毒液不需要杀蜘蛛，只需要骑上它。"
D.Strings[40811]="蜘蛛在隆克的肚子上留下了一些毒液。你想要吗？"
D.Strings[40812]="给，我为你弄到了。"
D.Strings[40813]="你可以从隆克的肚子上把毒液刮下来。"
D.Strings[40814]="我掩护你们。上啊，英雄们！消灭高弗雷！"
D.Strings[40815]="恐怕我没办法帮你，$r，但我相信凯琳·斯蒂文可以。"
D.Strings[40816]="恐怕我没办法帮你，$r，但我相信乔吉亚可以。"
D.Strings[40817]="干得好，$g小伙子:姑娘;！现在去干掉他们的头领吧！"
D.Strings[40818]="力量……太强了……"
D.Strings[40819]="附近的石像鬼活过来了！"
D.Strings[40820]="隆克厌倦了杀戮！隆克退出！"
D.Strings[40821]="隆克要去进行真正的冒险！"
D.Strings[40822]="我们散播的这种特殊魔法会让高弗雷的军队无法离开城堡。我们却可以自由地调动部队冲杀进去，为被遗忘者夺下它！"
D.Strings[40823]="我们确认部落已经出现在了龙喉港，主人。他们组建了一支大军。"
D.Strings[40824]="我们的密探都被除掉了，主人。"
D.Strings[40825]="联盟已经登陆了，主人，他们集结在岸边，数量众多。"
D.Strings[40826]="这什么也改变不了。（什么都没改变，碾碎他们，碾碎。）"
D.Strings[40827]="我们在暴风城的探子如何了？（暴风城！这只眼睛看到了那座城市的中心。）把眼睛拿给我。"
D.Strings[40828]="我们在奥格瑞玛的探子如何了？（城市被岩石沙砾吞没，但眼睛能看到它的核心）把眼睛拿给我。"
D.Strings[40829]="（混蛋，可恶的混蛋，恨，恨啊……）没关系。一只眼睛闭上，另一只会睁开。（主人无所不知！主人无所不见！）我们将洞悉敌人的内心。他们是软弱的。给我眼睛。给我眼睛。"
D.Strings[40830]="干掉那个了！"
D.Strings[40831]="在静电熔合爆炸前躲开！|TInterface\\Icons\\ability_vehicle_electrocharge.blp:32|t"
D.Strings[40832]="主人的暗影笼罩了这个世界……（黑暗，彻底的黑暗。）我们的敌人在高地上互相残杀。一群蠢货。（鲜血，鲜血。）等等！这儿有别人！"
D.Strings[40833]="凡人竟敢偷窥这只眼睛！（勇敢的小玩具。）我看到你了！你想看看这眼睛看到的东西？（看看！给他们看看！）"
D.Strings[40834]="见证混沌的降临吧。（疯狂，疯狂，疯狂！）喜欢你看到的吗，凡人？"
D.Strings[40835]="（主人看见你了！看见了！看见了！他想要！想要想要……）"
D.Strings[40836]="你的作战能力比我料想的更强。"
D.Strings[40837]="很好，让我们打开院子的大门，这样就能继续我们的任务了！"
D.Strings[40838]="这把锁应该能轻易地打开。"
D.Strings[40839]="你是否介意用你的暗影将太阳封锁一会儿？$b$b这样会很不错……"
D.Strings[40840]="要知道，今天我并不是很想工作。"
D.Strings[40841]="在这里工作实在是太热了——特别是还要穿着这身制服。"
D.Strings[40842]="他们向我承诺过，可以在这里得到巨大的财富。$b$b这可真是个不错的笑话！"
D.Strings[40843]="他们让我们像狗一样工作。我们却什么也没得到！"
D.Strings[40844]="司克诺兹因为我们发了大财……但我们呢？！"
D.Strings[40845]="别偷懒了！你已经跟不上进度了……"
D.Strings[40846]="我可没有为这种事签过字……"
D.Strings[40847]="我根本就不应该离开塔纳利斯。"
D.Strings[40848]="我就像废土一样快乐。"
D.Strings[40849]="是啊，是啊。我们什么时候没有耽误过进度？"
D.Strings[40850]="我绝不再为这种疯子工作了！"
D.Strings[40851]="你帮我带个口信给那个暴君！"
D.Strings[40852]="自从我到这里之后，就没有得到过任何报酬！我已经厌倦了这个地方！"
D.Strings[40853]="我一直被迫在高温环境中工作！"
D.Strings[40854]="真无法想象，我竟然会相信司克诺兹的谎言！跑到了这里！"
D.Strings[40855]="他要有大动作了！阻止他！"
D.Strings[40856]="你觉得哥培尔如果在这里，会怎么看你？嗯？"
D.Strings[40857]="现在那个仪式完蛋了。你欠我一大笔债，$r。$b$b我会让你还的！"
D.Strings[40858]="保持安静。他们只有三十分钟休息时间，我不能让你打扰他们。"
D.Strings[40859]="听着，自从我们逃出来之后，我稍微庆祝了一下，喝了几杯。然后我一直在想……$b$b那些攻击我们的小人应该得到正义的惩罚！$b$b如果我们不为此做些事情，那么每一个没有准备就进入那个地方的探险家都会变成奴隶被卖掉，或者遭遇更可怕的事情！"
D.Strings[40860]="这道传送门对面就是托尔巴拉德。"
D.Strings[40861]="太好了。在这个地区播散过魔法之后，就转移到……"
D.Strings[40862]="克鲁姆什！你在这里干什么？这是一次秘密行动！"
D.Strings[40863]="如果我没有理解错误，酋长是严格禁止这种魔法被全面使用的，无论在什么样的情况下。"
D.Strings[40864]="很抱歉，克鲁姆什，但我可以向你保证，我们的行动绝无问题。我们使用的是一种效能被减弱的魔法。"
D.Strings[40865]="实际上，这种魔法顶多只能吓唬一下那些狼人，让他们不敢追踪我们到这里来。它是完全无害的。"
D.Strings[40866]="那么我相信，如果我陪同你完成这个任务，你是不会介意的。"
D.Strings[40867]="我警告你，贝尔蒙特。如果我发现你在说谎……"
D.Strings[40868]="你将第一个承受酋长的怒火。"
D.Strings[40869]="只要干掉你们，女主人就会大大的奖赏我。"
D.Strings[40870]="准备好了吗，傻大个？扔吧！"
D.Strings[40871]="凡人！你们胆敢侵入我们的内部圣殿。（无信者。异教徒！烧吧，烧吧。）\n你们既然越过了界线，就别想回头。（烧吧，烧吧，异教徒燃烧吧。）"
D.Strings[40872]="哈尔弗斯！听我号令！（主人在召唤，主人想要）保护我们的秘密，哈尔弗斯。消灭入侵者。（为主人的荣耀，为主人的欲望，杀！）"
D.Strings[40873]="当然，长官。我们有最让部落感兴趣的东西。这些英雄刚刚要继续进军，为我们消灭斯普林瓦尔。"
D.Strings[40874]="不……不！"
D.Strings[40875]="血肉之躯，虽弱犹荣。他们竟胆敢窥视主人的秘密？他们盲目的挣扎求索，发现命运交织于混沌。"
D.Strings[40876]="我已经派我的部下到屋顶上去，守住沃登勋爵周围的区域。"
D.Strings[40877]="当然，总得有人去处理这两个地方之间的那支小军队。"
D.Strings[40878]="死亡猎手指挥官贝尔蒙特咧嘴一笑。"
D.Strings[40879]="混沌的兄弟们，暮光已至！（暗影延伸，无尽的黑夜。）死亡之翼割裂了世界。（门一打开就无法关闭。）以便让真正的主人返回。（主人来了。他来了，他来了。）"
D.Strings[40880]="时间到了，士兵们！高弗雷就在前面！不要有任何怜悯之心。我们要……"
D.Strings[40881]="为部落而战！！！"
D.Strings[40882]="凡人，你们不过是在替我们筛选真正的虔诚者。（微不足道，微不足道。）"
D.Strings[40883]="如果不想错过所有这些乐趣，最好快一点。"
D.Strings[40884]="听从他的召唤！干掉异教徒！"
D.Strings[40885]="啊！诅咒你！给我小心了，我再过一分钟就会回来！"
D.Strings[40886]="快走开，小子，你惹到我了！"
D.Strings[40887]="跟我来，$n。我会把你介绍给你的训练师，阿拉玛尔·格里姆。"
D.Strings[40888]="阿拉玛尔，请允许我向你介绍$n，他刚从诺莫瑞根逃出来。"
D.Strings[40889]="我很清楚，出现在这座森林中的恶魔是因为我们一族犯下的错误。$B$B我应该不是第一个想要对此进行弥补的上层精灵。感谢翡翠议会能够不计前嫌，接受我的帮助。"
D.Strings[40890]="你们是他的天选者。（他在召唤你，他认识你。）生有肉体（肉体），鲜血净涤（鲜血），注定获得不朽！"
D.Strings[40891]="暮光之锤的兄弟，来吧！（他们的意志仍属于自己。）无信者还没倒下。毁灭他们！（粉碎身体，粉碎意志。）"
D.Strings[40892]="这……比死亡……更可怕……"
D.Strings[40893]="啊！为什么你湿了！？"
D.Strings[40894]="为什么这道门关上了？以希尔瓦娜斯的名义，这里到底发生了什么……"
D.Strings[40895]="生命……消褪……死亡？不，只是入睡……"
D.Strings[40896]="克鲁姆什！出了什么事？"
D.Strings[40897]="在暴风要塞西北方的一座湖中小岛上，大地之环建起了通向世界不同地方的传送门。\n\n那里还有巴拉丁典狱官的代表，可以帮助你前往托尔巴拉德。"
D.Strings[40898]="那些懦夫……让我中了毒……杀了他们……"
D.Strings[40899]="不要让偏见和古老的仇恨干扰我们的任务，卡多雷。等到我们把这里的事情做完，会有足够的时间争吵和怀疑。"
D.Strings[40900]="他……是……从哪里……来的……"
D.Strings[40901]="高弗雷，你要为此付出代价！"
D.Strings[40902]="但……但……"
D.Strings[40903]="那……真是个……巨大的……屁股……"
D.Strings[40904]="英雄们，你们必须消灭高弗雷！我会掩护你们，确保你们不受干扰！"
D.Strings[40905]="为什么会是一个……臭气熏天的食人魔……"
D.Strings[40906]="在飞艇塔楼北边的悬崖上，大地之环建起了通向世界不同地方的传送门。\n\n那里还有地狱咆哮近卫军的代表，可以帮助你前往托尔巴拉德。"
D.Strings[40907]="我感觉不到我的腿……"
D.Strings[40908]="有三个虚灵魔法技师在奥格瑞玛的暗巷区开了一家商店，就在路的东侧。\n\n只要找古怪的机器和紫色的灯光就对了……你绝对不会走错地方的。\n\n他们那里会提供你所需要的服务。"
D.Strings[40909]="跟我来，$n。我会把你介绍给你的训练师，教官汽轴。"
D.Strings[40910]="军士，请允许我为你介绍$n，他帮助我们救出了诺莫瑞根的幸存者。"
D.Strings[40911]="瓦里昂娜，瑟纳利昂，送他们上路。"
D.Strings[40912]="跟我来，$n。我会把你介绍给你的训练师，凯尔希·钢烁。"
D.Strings[40913]="凯尔希，请允许我为你介绍$n，他帮助我们救出了诺莫瑞根的幸存者。"
D.Strings[40914]="主人显然是在跟你说话，瓦里昂娜。我可没空去攻击谁。"
D.Strings[40915]="你竟敢说我没用！好好看着，为什么我是母亲最宠爱的孩子！"
D.Strings[40916]="照主人说的做，瑟纳利昂！杀了他们！"
D.Strings[40917]="你可真没用，瑟纳利昂！啊——啊！"
D.Strings[40918]="给，这是我从小矮人那里偷来的。"
D.Strings[40919]="他要睡上一会儿了。隆克知道。隆克以前也是这样。"
D.Strings[40920]="给，这是矮人的东西。"
D.Strings[40921]="拿到矮人的东西就行。不需要杀掉他们。"
D.Strings[40922]="坐下总比战斗容易。"
D.Strings[40923]="给你。"
D.Strings[40924]="跟我来，$n。我会把你介绍给你的训练师，贝西·冰雹。"
D.Strings[40925]="贝西，请允许我为你介绍$n，最近从诺莫瑞根出来的生还者之一。"
D.Strings[40926]="跟我来，$n。我会把你介绍给你的训练师，“怪医”克斯宾"
D.Strings[40927]="医生，请允许我为你介绍$n，他帮助内温的队伍从诺莫瑞根救出了许多幸存者。"
D.Strings[40928]="我们离开这里！这里有一股精灵味！"
D.Strings[40929]="尼比出卖了我！他出卖了我！"
D.Strings[40930]="你不能这样做！我有我自己的灵魂碎片！"
D.Strings[40931]="（近点儿，再近点儿。让我们看看你们的脸。所有人都将屈从于他的力量。）"
D.Strings[40932]="别像个白痴一样的摇晃袋子行吗？！"
D.Strings[40933]="这里可真烫！等等，那是我的脚。"
D.Strings[40934]="放我出去，我会让你实现三个愿望！我发誓！"
D.Strings[40935]="九个，九个，九个！到底有什么会这样难以理解？！"
D.Strings[40936]="我将得到允诺之箱的秘密……然后，我将得到整个世界！"
D.Strings[40937]="赫利克斯在$n的身上安了一颗炸弹！"
D.Strings[40938]="应许约柜……就要是我的了！"
D.Strings[40939]="这些财宝可真漂亮……用不了多久，就没有人能阻挡我了！"
D.Strings[40940]="这场大灾变可真是合我的胃口。"
D.Strings[40941]="%s感觉到$n的怯懦，便释放出一道闪电！"
D.Strings[40942]="在%s的命令下，风突然转向了！"
D.Strings[40943]="不要打脸！唉呦，唉呦，唉呦……"
D.Strings[40944]="把伊普斯装进袋子里！"
D.Strings[40945]="那些雕像！它们是活的！"
D.Strings[40946]="你要说什么，地精？！说啊！！"
D.Strings[40947]="我会说的，我会说的！我什么都说！赶快把这个怪味袋子从我面前拿开！"
D.Strings[40948]="<穆兰狮鹫骑士纹丝不动，双目凝视前方，仿佛完全没有意识到你的出现。>"
D.Strings[40949]="还没有放弃，是么？"
D.Strings[40950]="这是明显的挑衅！"
D.Strings[40951]="让你们的妻子躲起来！让你们的孩子躲起来！他们会杀掉这里所有的人！"
D.Strings[40952]="他们要杀死所有人！要摧毁一切！就像这样！"
D.Strings[40953]="当然，先生！马上就办！"
D.Strings[40954]="在皇家贸易区找到神圣遗物学会。毫无疑问，那个组织中的诸多考古学家之一会在那里帮助你。"
D.Strings[40955]="你还在等什么？赶快去阻止他们！"
D.Strings[40956]="太好了，太好了！你赢了。"
D.Strings[40957]="只有神圣遗物学会最高阶的成员知道我们的大殿堂在哪里。$B$B甚至有人说，大殿堂根本就不存在于这个位面……"
D.Strings[40958]="道格拉斯就派你过来挨揍了？"
D.Strings[40959]="想要打架吗？"
D.Strings[40960]="看上去，你想要从我这里得到些什么……"
D.Strings[40961]="想受惩罚吗？"
D.Strings[40962]="历史？文化？这些都是学者和抄写员关心的事情。$B$B我们神圣遗物学会关心的是……当前，或者也许是未来。$B$B我们发现、获取并收藏失落的宝物、财富和学识，以确保它们不会被别人利用来对抗我们。毕竟，力量只属于能够充分利用它的人……难道你不同意吗？"
D.Strings[40963]="让你们的妻子躲起来！让你们的孩子躲起来！让你们的丈夫躲起来！！他们会杀掉这里所有的人！"
D.Strings[40964]="$n，你要从那些海盗手中拯救我们，否则还能怎样？！"
D.Strings[40965]="我是否能请求你从那些海盗手中拯救我们，亲爱的$n？！"
D.Strings[40966]="有你们这些蠢货，我就不需要他了！"
D.Strings[40967]="才10个铜币？杀你还真不划算！"
D.Strings[40968]="形势……转变了……"
D.Strings[40969]="再给我一些那种游泳药剂！"
D.Strings[40970]="你想找胡萨克大师？他就在内环法师区南部。"
D.Strings[40971]="你会想要找到亚当·胡萨克的。他在内环法师区南部有一个办公室。$B$B如果他没有在外面进行探索工作，他应该就在那里。"
D.Strings[40972]="总有一些新东西需要调查。"
D.Strings[40973]="快一点。"
D.Strings[40974]="任何人都无法阻挡女妖之王的怒火。"
D.Strings[40975]="血牙将会崛起。"
D.Strings[40976]="我的冰激凌帝国将迅速发展壮大。提古勒和弗洛尔就要完了！"
D.Strings[40977]="欢迎你们，凡人。（脆弱之子。）鲜少有人能亲临这内部圣殿。（他们就要引火上身了！）"
D.Strings[40978]="看到我了吗，古加尔？我是来找你的！我要在你眼前砍掉你的头！"
D.Strings[40979]="天选者在此洞悉到他们的宿命。（永生不灭。）而你们也将在此直面你们的宿命。（终结血肉，终结血肉！）"
D.Strings[40980]="兄弟们！暮光之锤在呼唤你们！（火、水、土、气）蜕下你凡人的躯壳。(火、水、土、气）在此拥抱新的形态，直到永远！（燃烧、淹溺、碾压、窒息）用你们获得的恩赐消灭那些无信者。（燃烧、淹溺、碾压、窒息）！！"
D.Strings[40981]="一定要保持镇定。"
D.Strings[40982]="为了希尔瓦娜斯！"
D.Strings[40983]="愚蠢的凡人——（篡位者之子！）你的所为毫无意义——（劣等神之种！）你不要打断我说话。（听啊，听啊，听啊。主人渴望杀戮。）万物归于混沌。万物终将消亡。（混乱，混乱！）你今日的努力也无济于事。（混乱，混乱，一切都将终结）没有凡人能活着见证这一切。你的末日到了。"
D.Strings[40984]="这些记录非常散乱。我无法判断阿鲁高到底是个天才，还是个彻头彻尾的傻瓜。"
D.Strings[40985]="我必须承认，阿鲁高的研究相当新颖。"
D.Strings[40986]="散落的书页，残破的装备，被污染的样品！怎么会有人在这种环境里工作！"
D.Strings[40987]="这些藏书对我的研究非常有用。"
D.Strings[40988]="死神5000型已就绪。系统全部正常。"
D.Strings[40989]="像奥达曼这样的地方肯定隐藏着关系到我们一族过去的秘密！"
D.Strings[40990]="消灭埃卓凯丝海妖，摧毁护盾！"
D.Strings[40991]="奈瑟匹拉正在醒过来！用奈瑟匹拉流体怪消灭埃卓凯丝。"
D.Strings[40992]="戴德洛·沃姆伍德就是你想要找的那具尸体。他经常会在这个镇子的南端。"
D.Strings[40993]="布瑞尔唯一的厨师就在这个镇子的中心位置。$B$B我们不知道他为什么会在那里。而且他不出售任何他烹制的东西。我们也不知道他用来烹调的生肉都是从哪里来的。$B$B嗯，这些都是小事。祝你好运。"
D.Strings[40994]="冰激淋，布里维普。我要冰激淋！"
D.Strings[40995]="%s向前倒下，暴露出他的钳子！"
D.Strings[40996]="我有点忙，$c。你要什么？"
D.Strings[40997]="想加入我们的舞蹈吗？"
D.Strings[40998]="攻击并削弱黑色幼龙！"
D.Strings[40999]="超速引擎已激活。"
D.Strings[41000]="你们部族只剩下你们还有些理智。既然你们将纳顿亲王交给我们，作为回礼，我将你们生来就应该继承的东西赐予你，另外，我还会赐予你们更多强大的礼物！"
D.Strings[41001]="你们的造物主辜负了你们……听任你们被束缚在这种被诅咒的残缺肉体之中！但死亡之翼君王的赠礼却能让你们重新拥有完美的身体！"
D.Strings[41002]="迅速拍打你的翅膀，重新恢复高度！"
D.Strings[41003]="这个兽人受了重伤。"
D.Strings[41004]="结束这个兽人的痛苦。"
D.Strings[41005]="请原谅，朋友，但我的确是很忙。$b$b我受命为这一地区指挥官的发现进行公证。$b$b这些发现具有极为重大的意义！"
D.Strings[41006]="我有一个重要的任务，那就是为司克诺兹元首撰写传记。$b$b请原谅。"
D.Strings[41007]="我要赐予你的不仅是我们生来便应继承的力量，还有其它更加强大的礼物！"
D.Strings[41008]="借助南风的力量，我们将夺回这座城市，让那些入侵我们国土的敌人再无法染指于它！"
D.Strings[41009]="仗还没有打完呢，渣滓们。"
D.Strings[41010]="帮助受伤的兽人站起来。"
D.Strings[41011]="我向克罗姆加的军队提供各种装备。"
D.Strings[41012]="让我看看你的货物，军需官。"
D.Strings[41013]="闻起来像……黄金！"
D.Strings[41014]="|TInterface\\Icons\\spell_fire_twilightnova.blp:20|t%s施放|cFFFF0000|Hspell:86788|h[眩晕]|h|r！"
D.Strings[41015]="不久前，我看见他们向那些船上运送了一些古物。$b$b我还从没有见到过那么多黄金被堆在一起！"
D.Strings[41016]="数年以前，当我打算去研究双足飞龙的时候，却被困在了这里。一旦我恢复了自由，我就决心回去保护它们。$B$B现在，大灾变席卷了整个世界，暮光之锤开始大肆捕捉这些珍贵的野兽，甚至不惜对它们造成毁灭性的打击。"
D.Strings[41017]="我不在乎部落和联盟之间的战争。对我来说，最重要的是拯救风巢的双足飞龙。$B$B至少，我要阻止它们落进暮光之锤的手中，$r。"
D.Strings[41018]="正在获取目标。"
D.Strings[41019]="已获取目标。收割系统已启动。"
D.Strings[41020]="我已经准备好飞进大熔炉了！"
D.Strings[41021]="赶快走，不要让奴隶们看见你！"
D.Strings[41022]="你……是要救我吗？"
D.Strings[41023]="来吧，让我们离开这里！"
D.Strings[41024]="绝不！我喜欢为黑铁矮人工作！"
D.Strings[41025]="入侵者！有入侵者要救我！"
D.Strings[41026]="我绝不会离开！我在外面不知道该怎么活着！"
D.Strings[41027]="我就知道， 瑟银兄弟会一定会来救我们！"
D.Strings[41028]="哦，谢谢！谢谢！"
D.Strings[41029]="你们来得正好！我早就厌倦作奴隶了！"
D.Strings[41030]="安全限制：离线。灾难性系统崩溃即将到来。"
D.Strings[41031]="已超出过热临界值，系统崩溃，有小麦堵在2号端口内，关机中。"
D.Strings[41032]="从架子上抓起一根长矛。"
D.Strings[41033]="装备长矛。"
D.Strings[41034]="骑上一头艾维娜的守护者。"
D.Strings[41035]="你是要来阻止大公吗？"
D.Strings[41036]="我们行动，把玛托留斯和阿卡库斯干掉！"
D.Strings[41037]="你说的对！我去对付那个暮光混蛋。你对付那个小矮人。"
D.Strings[41038]="提高警惕，$n。我们要等玛托留斯和阿卡库斯回来，然后迎头痛击他们。"
D.Strings[41039]="可怜的酒囊饭袋！好好看着龙喉的强大力量吧！"
D.Strings[41040]="也许你们这些肮脏的动物想要尝尝泥土的味道！"
D.Strings[41041]="这就是你所说的严厉手段！"
D.Strings[41042]="%s被削弱了！现在驱逐他！"
D.Strings[41043]="哈特拉斯发出感激的吼声。"
D.Strings[41044]="不！这不可能！我……是……永生不死……！"
D.Strings[41045]="蠢货！你们不可能打败我！我还会回来的……"
D.Strings[41046]="要高傲地昂起头，$n。不能允许这些小矬子们给你制造任何麻烦。让他们知道，谁才是老板！"
D.Strings[41047]="我看见有个家伙过来了！看上去像个真正的胜利者。保持冷静，$n。保持冷静。"
D.Strings[41048]="嗨！嗨！救命！"
D.Strings[41049]="嗨！我还是个新人！是生着一双大翅膀的，发着白光的一个大怪物让我活过来的！我效忠于女妖之王！嘿！$B$B救命！$B$B嗨！"
D.Strings[41050]="也许你应该去打个盹，或者干些别的。我不知道这里有没有工作能给你。"
D.Strings[41051]="好啊！谢谢！我就在这里等你！谢谢！好的！"
D.Strings[41052]="等一下。这里似乎有什么东西。是了，就在这张纸上。你需要到东南方的碧玉矿洞去，向那里的凯东上尉报告。你要一直向东南走*你向东南方指过去*。"
D.Strings[41053]="向北！明白了！谢谢！再见！谢谢！"
D.Strings[41054]="这些新的被遗忘者实在是有些……嗯……愚蠢。他们还需要一段时间适应。"
D.Strings[41055]="哦，好啊……这个也不是。我知道这个兽人。他不做什么正经事，只是在这里四处晃荡，靠敲诈欺凌为生。别让他吓唬了你。"
D.Strings[41056]="哈！看上去你已经没有什么白痴可以放在这匹马背上了，达萨利亚。这个家伙实在是太弱了。"
D.Strings[41057]="小家伙，你今天给我弄到了些什么？！给我指出那些联盟的藏身之地，我会好好照顾他们！"
D.Strings[41058]="%s开始施放冻结！"
D.Strings[41059]="我见证了巫妖王的毁灭。泰坦的造物被我强大的战斧摧毁。得到号令的时候，我一个人与诺森德的怪物们对战，凭一己之力为银色北伐军赢得了巨大的胜利。现在，我来接受这场终极挑战。希尔斯布莱德丘陵能为弑君者奥尔库斯献上些什么？？？"
D.Strings[41060]="嗯……南海镇显然是遇到了些麻烦。狼人在这里发动了叛乱。你愿意帮助我对付他们吗？"
D.Strings[41061]="你说有入侵者？我会有生命危险吗？我会被肢解吗？"
D.Strings[41062]="没有。"
D.Strings[41063]="奥尔库斯会成功的！没错！"
D.Strings[41064]="好的，谢谢。只要向东南偏南前进。也许就在海岸边。"
D.Strings[41065]="是的，懦弱的任务给予者。在你的白马背上好好坐着吧。奥尔库斯则会为部落夺取光荣！我会带着一千个俘虏回来！"
D.Strings[41066]="现在只能希望他永远不要回来了。也许他会淹死？"
D.Strings[41067]="强尼·傲森来了，真庸俗。把你们无聊那些小任务交给我吧，我会记得在恰当的时间以恰当的方式去去完成它们的。不过，如果你们给的任务描述比我的地图标记还要复杂，我可就完全没兴趣了。"
D.Strings[41068]="看着我，农夫。我全身从头顶到脚趾可都是珍贵的传家宝。是艾泽拉斯历史上最伟大的英雄们给我的礼物。$B$B现在看看你自己。$B$B再看看我。$B$B当然，这匹马可是用晨星做成的。$B$B你为我准备了什么无聊的任务？你们的任务其实只应当由没脑子的兽人去完成。"
D.Strings[41069]="嗯，我们在东北方的药渣农场的确遇到了一些麻烦。你一定能帮上看守者斯蒂沃特的忙。"
D.Strings[41070]="好啊，好啊，还有什么？"
D.Strings[41071]="就是这些。"
D.Strings[41072]="就这些？一个任务？你一定是在开玩笑。这里没有狗熊要猎捕吗？也许我可以去采集某种罕见的花卉，让你能够用来调配致幻剂，喝下去以后让你能看到伟大的预兆？也许本地有令人困扰的地鼠捣乱，需要予以惩治？没有？什么都没有？"
D.Strings[41073]="就是这些，强尼·傲森。不愿意接受就走吧！"
D.Strings[41074]="既然你请求我完成这个任务，我会为你完成的，任务给予者。你最好祈祷我能再找到一些这种小任务去完成。否则我在公共论坛可不会说你的什么好话。"
D.Strings[41075]="你们这些矮人真是没用！你们来找拉格纳罗斯，想得到拉格纳罗斯的赠礼，但你们却拿不出任何东西作为奉献！"
D.Strings[41076]="没有任何奉献，除了你们的力气和铲子。所以你们就用力挖吧。"
D.Strings[41077]="挖大坑，挖深坑。找出世界下方的火焰之地。我的兄弟姐妹正渴望着得到自由。"
D.Strings[41078]="如果成功，你们将得到升腾。失败的话，你们都将被烧成灰烬。"
D.Strings[41079]="有没有听说过瑟银兄弟会？当然，我们可能很像山谷中和黑石深渊里的那些矮人。但相信我：我们和他们根本不是一种人。$b$b那些恶棍挖得太深。现在，他们愚昧地侍奉着一股黑暗的力量——拉格纳罗斯，炎魔君主。我们很高兴自己能有独立的意志。虽然在大多数时间里，我们不得不将自己的全部精力都用来弥补那些恶棍所犯下的罪行。"
D.Strings[41080]="你能修好我的设备吗，布里安？"
D.Strings[41081]="你能修好我的设备吗，阿古斯？"
D.Strings[41082]="黑石的黑铁矮人和瑟银哨塔的那些男孩都和我没关系。$b$b我是中立的，而且我喜欢这样。当然，只要出价合适，我会帮助任何人……"
D.Strings[41083]="为什么你要这么干？为什么你要杀戮？"
D.Strings[41084]="不要再杀了！隆克不喜欢！"
D.Strings[41085]="不！不要杀！"
D.Strings[41086]="你杀戮的时候，隆克感觉受了伤。"
D.Strings[41087]="请不要在隆克身边杀戮。"
D.Strings[41088]="哦，不！为什么你要杀它？"
D.Strings[41089]="你将遭受苦难！你将面对暮光之锤的怒火！"
D.Strings[41090]="你能得到的只有痛苦！"
D.Strings[41091]="死吧，爬虫！"
D.Strings[41092]="打倒你将是一件令人愉快的事！"
D.Strings[41093]="没用的双足飞龙！我不需要你！"
D.Strings[41094]="现在还不是飞出去的时候，$r。根据加尔鲁什的命令，要等到暗夜精灵被彻底清除之后，这些双足飞龙才能被用于军事行动。"
D.Strings[41095]="让我们看看这堆灰烬到底……是什么？"
D.Strings[41096]="不！滚开！别碰我！"
D.Strings[41097]="啊……！"
D.Strings[41098]="这是什么？嘘！"
D.Strings[41099]="火焰又获得了燃料。"
D.Strings[41100]="疾风，听我号令！"
D.Strings[41101]="%s开始施放雷霆震荡！"
D.Strings[41102]="不过是狂风中的低语。"
D.Strings[41103]="土壤欢迎你们的白骨。"
D.Strings[41104]="大地将吞噬你们！"
D.Strings[41105]="%s开始施放地震！"
D.Strings[41106]="你的傲慢会让你送命！"
D.Strings[41107]="你们竟敢侵入我们主人的圣殿？"
D.Strings[41108]="感受这力量！"
D.Strings[41109]="周围的空气因为充斥着强大的能量而发出“噼啪”声……"
D.Strings[41110]="你脚下的地面发出不祥的“隆隆”声……"
D.Strings[41111]="我猜，现在该是重建时期了……"
D.Strings[41112]="什么……我的创造物！它甚至没有飞上过天空！我最好检查一下我的笔记……"
D.Strings[41113]="%s被你的丑陋吓到了！"
D.Strings[41114]="呃！离我远点，你这个脏东西！"
D.Strings[41115]="如你所愿，爸爸！"
D.Strings[41116]="哦！太满了……哦，不……"
D.Strings[41117]="该是发动最后一击的时候了，亲爱的！"
D.Strings[41118]="事实证明这个司克诺兹是个明智的投资对象。$b$b看来我的洞察力的确是超强的。"
D.Strings[41119]="就像父亲一直说的那样，要成为一名成功的投资人，必须具有精明的头脑，敏锐的直觉和无尽的勇气。$b$b必须承认，我能在一哩以外就能闻到投资的机会。"
D.Strings[41120]="不要忘记更换你的主武器！"
D.Strings[41121]="大使似乎是因为某个人或某件事而遇害了！"
D.Strings[41122]="我对这一切已经受够了。现在该是让……野兽之心出来的时候了！"
D.Strings[41123]="谁会干这种事？"
D.Strings[41124]="谁能知道？$b$b他已经成为了这个行动的关键，但这不能证明任何事。"
D.Strings[41125]="你愿意调查这起谋杀案吗？"
D.Strings[41126]="谁，我？$b$b为什么？我觉得自己没有资格，嗯……不，我想我应该拒绝。"
D.Strings[41127]="好吧，你至少能把它记录下来吧，对不对？"
D.Strings[41128]="什……什么？！嗯，我……$b$b正在展开的发掘工作是如此令人兴奋，现在却要把注意力集中在这种事情上，我想这可能不合适。$b$b你也知道，这只能是一个令人困扰的故事。"
D.Strings[41129]="别……别碰我……$b$b出了什么事？！"
D.Strings[41130]="镇定。你还好吗？"
D.Strings[41131]="不！我当然不好！$b$b以前我从没见过尸体……"
D.Strings[41132]="你明白发生了什么事吗？"
D.Strings[41133]="他就从那座兵营里跌跌撞撞地爬了出来。$b$b我尖叫着寻求援助，但那些卫兵甚至不看我一眼！"
D.Strings[41134]="也许你应该躺一会儿。"
D.Strings[41135]="是的。$b$b听起来像是个好主意。"
D.Strings[41136]="我的天！仆人们，帮帮你们的主人！！"
D.Strings[41137]="玩够了！现在该是下手的时候了！"
D.Strings[41138]="赶快坐好，小伙子们。我要让你们知道什么才是真正的战斗！"
D.Strings[41139]="我们的人已经守住了通道。现在要集中全力帮助主室中的人了。"
D.Strings[41140]="|TInterface\\Icons\\spell_shaman_staticshock.blp:20|t%s施放|cFF1CF2FE|Hspell:79888|h [闪电导体]|h|r，目标为|cFF1CF2FE$n|r！"
D.Strings[41141]="我要把你彻底烧成灰烬！"
D.Strings[41142]="轻而易举！"
D.Strings[41143]="你真应该做好准备再来这里！"
D.Strings[41144]="瓦里昂娜，消灭他们！为我报仇！"
D.Strings[41145]="奴仆们，把他们烧光！"
D.Strings[41146]="让烈焰……烧尽一切吧！"
D.Strings[41147]="巨龙，听从我的命令！接住我！"
D.Strings[41148]="我不会为你而死，达加。"
D.Strings[41149]="如果他们没有杀掉你，就由我来亲自动手吧！"
D.Strings[41150]="最黑暗的日子还没有到来！"
D.Strings[41151]="真是不错的祭品。"
D.Strings[41152]="F'lakh ghet！黑暗的饥饿永无止尽！"
D.Strings[41153]="这门大炮直指海岸，而且炮膛里已经填满了弹药，安放好了引信。$B$B这可真方便啊！"
D.Strings[41154]="我要让它响起来！现在还能有什么问题？"
D.Strings[41155]="不！索朗格斯干不好就又要挨鞭子了！"
D.Strings[41156]="索朗格斯会为你找个好去处的……"
D.Strings[41157]="哈，你真弱！"
D.Strings[41158]="死亡……虽然不是最好的选择，但总比失败以后活着好。"
D.Strings[41159]="你无法突破这防御！"
D.Strings[41160]="哦，尝尝什么叫疼！"
D.Strings[41161]="嘿，索朗格斯把你劈开！"
D.Strings[41162]="我的奴仆何止成千上万。你有什么机会战胜我？"
D.Strings[41163]="爬虫们，你们的晚餐来了！"
D.Strings[41164]="清理着陆场！向熔炉守卫射击！"
D.Strings[41165]="蝾螈，该你上了！把门石打开！"
D.Strings[41166]="没问题，头儿。呃……我要把它插在哪儿？"
D.Strings[41167]="就把它插在……等等……锁眼在哪里？真是 一团乱！"
D.Strings[41168]="拧它。钟摆，你来！"
D.Strings[41169]="好的，头儿！"
D.Strings[41170]="真难以相信，我们竟然在做这个。我知道，卡尔烬德的出现会让我们全都受到威胁。但这是真的吗？统治这里的不是大地之环吗？还是别的什么组织？$b$b为什么瑟银兄弟会要如此大动干戈？"
D.Strings[41171]="死亡是我唯一的选择。"
D.Strings[41172]="像是个魔法符咒。钥匙又有什么用……"
D.Strings[41173]="挡我道者必死无疑！"
D.Strings[41174]="快进攻，你们这些胆小的爬虫！"
D.Strings[41175]="%s收回了他的旋风之盾！"
D.Strings[41176]="欢迎来到瑟银哨塔。作为这里的工头，我负责管理瑟银兄弟会的一切行动。我们的主要工作是采矿，锻造，还有一些辅助性的守卫工作。但最近我们越来越向军事化发展了……这实在是没有必要。"
D.Strings[41177]="$n，我们已经进入了熔渣之池。现在该是最终完成工作的时候了。"
D.Strings[41178]="$n，我们任何时候都欢迎你。"
D.Strings[41179]="%s施放了不稳定的接地场！"
D.Strings[41180]="蠢货。奥比斯顿！起来，消灭入侵者！"
D.Strings[41181]="埃索达没有回应我的请求，$n。恐怕只有你才能帮可怜的玛格图尔。"
D.Strings[41182]="我会为了玛格图尔继续研究下去。"
D.Strings[41183]="有什么需要我们帮忙的吗？"
D.Strings[41184]="我和我的军队能帮上什么忙吗？"
D.Strings[41185]="真的没什么需要我们帮忙了吗，尼卡？"
D.Strings[41186]="我们一点儿都帮不到赫格拉姆吗？"
D.Strings[41187]="坚守阵地，别让任何联盟渣滓靠近我们。"
D.Strings[41188]="坚守阵地，小心任何伺机进犯的联盟。"
D.Strings[41189]="留意联盟。要是他们胆敢再来进犯，我们一定要让他们好看。"
D.Strings[41190]="所有人，全力防范联盟的攻击。"
D.Strings[41191]="嘿嘿……嘿嘿嘿……哈哈哈！"
D.Strings[41192]="嘘！会被他们听见的，呆瓜！"
D.Strings[41193]="不许叫我呆瓜，你这呆瓜！"
D.Strings[41194]="嗷！现在他们发现我们了！"
D.Strings[41195]="没错，野兽。你现在听命于龙喉氏族了。"
D.Strings[41196]="要是你不听话，我们就把你砍成碎片。"
D.Strings[41197]="很好。趁那家伙处于虚弱状态，完成对它的控制。"
D.Strings[41198]="告诉我，你用的是什么魔法？"
D.Strings[41199]="恶魔之链。它能将我们的意志转换为战斗力。"
D.Strings[41200]="部落？我呸你个部落！我们的敌人是一盘无力的散沙，你却跟地狱咆哮讲条件？龙喉无人能及！"
D.Strings[41201]="我会证明给你看。我会向桑德玛尔的蛮锤部族发起攻击。"
D.Strings[41202]="当我凯旋而归时，我们倒看看龙喉的族人管谁叫“酋长”。"
D.Strings[41203]="你是怎么进来的？我要杀了你！"
D.Strings[41204]="在龙骑士与部落的支持下，我们可以对暮光堡垒发起攻击。"
D.Strings[41205]="再敢口出妄言，我就会送你到你该去的地方，纳克拉尔。"
D.Strings[41206]="纳克拉尔！要是你想挑战我，就在这儿解决。不要把我们的兵力浪费在愚蠢的征讨上。"
D.Strings[41207]="多谢你让我重获自由，$n。$B$B现在让我们看看能不能救出玛加萨，并终结暮光之锤在千针石林的罪恶行径。"
D.Strings[41208]="嘿你好啊。这下面没问题了。"
D.Strings[41209]="蜜蜂！快跳进水里把它们甩掉！"
D.Strings[41210]="面对我，$r，感受军团的愤怒吧！"
D.Strings[41211]="这些狼人是我们的阶下囚。它们将由最高统帅部来发落。"
D.Strings[41212]="跳到龙背上来！"
D.Strings[41213]="你想干什么，小矮子？趁我还没拿锤子把你的笑脸砸扁，赶紧从我面前消失！"
D.Strings[41214]="我会把我们的话语封存在悲泣的紫罗兰中……就算是在加德纳尔和暗影堡的最深处，也能听到我们的声音。"
D.Strings[41215]="无能的$r别想夺走我的天赋特权！"
D.Strings[41216]="我能帮你什么忙吗，$g帅哥:美女;？"
D.Strings[41217]="什么事？我很忙，防卫者。"
D.Strings[41218]="巨龙给了我们从暮光之锤手中夺取大门的机会。我们一定要善加利用。"
D.Strings[41219]="我随时可以前往峡谷。小队准备好了吗？"
D.Strings[41220]="他们已经在等你了，$c。"
D.Strings[41221]="（鲜血献给主人！）"
D.Strings[41222]="这就是你的宿命。"
D.Strings[41223]="拥抱死亡吧。"
D.Strings[41224]="给我你的力量！"
D.Strings[41225]="见证暮光之锤的力量！"
D.Strings[41226]="（停。巨锤惩击！）"
D.Strings[41227]="够了！（为主人碾碎所有血肉，从主人的王国，混乱降临。）对——如他所言。"
D.Strings[41228]="（无尽的折磨！）"
D.Strings[41229]="（*喷鼻息*）"
D.Strings[41230]="看看你们这脆弱世界的命运！"
D.Strings[41231]="更多。更多！"
D.Strings[41232]="（来吧，弟兄们！饱餐希望吧！）"
D.Strings[41233]="又来一个！杀了那个$r！"
D.Strings[41234]="（更多。他们想要更多。）"
D.Strings[41235]="联盟……他们在守卫蛮锤……"
D.Strings[41236]="兄弟，这不可能……（定数已到！）我的力量……（多么骄傲！他在用鲜血昭告！快听！）我的精神……（我们为他的荣耀而效忠！）究竟……是怎么了……（黎明已逝，迎来了暮光之影。来吧疯狂，来吧浩劫，来吧，无尽的黑夜！）"
D.Strings[41237]="小队报告情况。"
D.Strings[41238]="小心肚子！"
D.Strings[41239]="你想来点儿吗？！"
D.Strings[41240]="谢谢你。我不会忘记你的恩情。"
D.Strings[41241]="祝你好运。我很感激。"
D.Strings[41242]="你们是来找巫婆长老玛加萨·恐怖图腾的吗？他们把她关在东边了。"
D.Strings[41243]="这些邪教徒简直疯了。他们要毁灭整个世界！"
D.Strings[41244]="他们要献祭我，以召唤更多元素！"
D.Strings[41245]="替我复仇。"
D.Strings[41246]="我听到了他们的交谈。他们正准备在东边的基地里召唤什么大家伙！"
D.Strings[41247]="已经有太多人丧命。太多的毁灭。终结他们的恶行！"
D.Strings[41248]="（灵魂与血肉，一次吞个够！）"
D.Strings[41249]="所有人都得死。"
D.Strings[41250]="（现在他们看见黑暗了！他们的眼睛睁开了！）"
D.Strings[41251]="它们属于主人了。"
D.Strings[41252]="（混乱，疯狂！紧缚你的脑髓。）"
D.Strings[41253]="没什么新鲜事。"
D.Strings[41254]="嗯，还不错。"
D.Strings[41255]="我们很好。我们现在都很好，谢谢你。你怎么样？"
D.Strings[41256]="看到你真高兴，$c。$b$b我们最近少有访客。"
D.Strings[41257]="真意外！$b$b我们以为不会有人来……"
D.Strings[41258]="都结束了。（万物的命运。）"
D.Strings[41259]="兄弟，我们败了。（可主人……我还能听到……愤怒……主人……？）"
D.Strings[41260]="兄弟，我们败了。让她解决他们。（主人不想让他们靠近她……兄弟？主人怒不可遏……）"
D.Strings[41261]="这就是那个大名鼎鼎的$r$c，嗯？$b$b如你所知，还有一个尚未被激活的方尖碑……$b$b当复原这古老装置的时机到来时，你会在那里吗？历史会记住你吗？$b$b这取决于你是否愿意合作！"
D.Strings[41262]="我没有担当领袖的经验。我应该预见到纳克拉尔的叛逆。而我却只能收拾他留下的烂摊子。$B$B我不知道加尔鲁什·地狱咆哮是如何做到的。他一定具备过人的力量，才能将如此多样化的部落大军凝聚在一起……我愿意更加深入地了解他。"
D.Strings[41263]="|TInterface\\Icons\\spell_shadow_shadesofdarkness.blp:20|t%s开始召唤|cFFFF0000黑暗造物|r来协助他！"
D.Strings[41264]="现在可以参与旋云之巅的初始测试了，这是位于奥丹姆的一座82-84级地下城。这座地下城目前仍处于开发过程中。请在传送至地下城之前组满队伍。\n\n若要离开旋云之巅，必须使用炉石或类似方式传送出去。如果你在战斗中死亡并释放灵魂，你则需要通过该NPC传送回地下城。"
D.Strings[41265]="（命运的利爪死死拽住那些无信者！）"
D.Strings[41266]="（主人看得见，主人看得见！）"
D.Strings[41267]="我们卷入了何种疯狂？（还远远不够！）"
D.Strings[41268]="我……再也受不了了……（兄弟，这才刚刚开始！）"
D.Strings[41269]="（主人的双眼能看穿过去与未来，不是吗！）"
D.Strings[41270]="我在小队中，并已准备好传送到旋云之巅！"
D.Strings[41271]="送我回到旋云之巅！"
D.Strings[41272]="巨龙给了我们从暮光之锤手中夺取大门的机会，我们一定要善加利用。"
D.Strings[41273]="向我敞开灵魂，凡人。"
D.Strings[41274]="他们已经集结完毕。我相信你能守住通往格瑞姆巴托的道路。别让我失望。"
D.Strings[41275]="我就知道不该插手……"
D.Strings[41276]="你无权命令我，瓦里昂娜！我想包抄就去包抄！"
D.Strings[41277]="谁也别想逃开暮光飞龙的愤怒！"
D.Strings[41278]="痛苦地翻滚吧！"
D.Strings[41279]="感觉到脊背上的刺骨寒意了吗？"
D.Strings[41280]="浓雾正在翻涌……"
D.Strings[41281]="我的苦难将要终结，$r。可你的才刚刚开始！"
D.Strings[41282]="他来了，$n！把他打败，让我用恶魔之链控制住他。"
D.Strings[41283]="继续战斗，$c！恶魔之链一定能制服他。"
D.Strings[41284]="开始清除未经许可进入的个体。"
D.Strings[41285]="欧米加姿态已被激活。对入侵单位的清除即将开始。"
D.Strings[41286]="目标被消灭。"
D.Strings[41287]="清除结束。"
D.Strings[41288]="安拉斐特单位关闭……"
D.Strings[41289]="电荷金刚单位已激活。"
D.Strings[41290]="熔岩金刚单位已激活。"
D.Strings[41291]="剧毒金刚单位已激活。"
D.Strings[41292]="奥能金刚单位已激活。"
D.Strings[41293]="电荷金刚单位防护系统已就绪。"
D.Strings[41294]="熔岩金刚单位防护系统已就绪。"
D.Strings[41295]="奥能金刚单位防护系统已就绪。"
D.Strings[41296]="正将多余能量转输给熔岩金刚单位。启动火焰喷射器装置。"
D.Strings[41297]="发现入侵者。主防御矩阵已启用。"
D.Strings[41298]="可以在探险者大厅内找到学者教授铁裤。"
D.Strings[41299]="防御系统瘫痪。能源衰减……"
D.Strings[41300]="在吉布的商店——草须魔法用品店里有一位奥术重铸师，就在大锻炉的狮鹫管理员附近。$B$B他属于早已失落的上层精灵一族。但他可以帮上你的忙。"
D.Strings[41301]="我已经准备好与托斯交战了！"
D.Strings[41302]="嘿，你好。你能把我从这儿弄出去吗？"
D.Strings[41303]="你真该庆幸自己待在这些铁栅栏的另一侧！"
D.Strings[41304]="你想把我怎么样？"
D.Strings[41305]="你，说你呢。干掉我的看守！"
D.Strings[41306]="我是不会被控制的！"
D.Strings[41307]="他的意志——太强大了！"
D.Strings[41308]="在力量谷的中部要塞里有位血精灵，是银月城贝洛克代表团的成员。他就是你要找的人。"
D.Strings[41309]="可以在暗影裂口里找到那些法师。共有两个入口，一个位于力量谷与智慧谷中间，另一个在暗巷区。"
D.Strings[41310]="我……决不……从命！"
D.Strings[41311]="那你就去死吧。"
D.Strings[41312]="好吧。结束了。"
D.Strings[41313]="到咽喉洞与我见面，$n。向西飞，飞过那条河，然后沿着山脊寻找一个小山洞……"
D.Strings[41314]="合作愉快。"
D.Strings[41315]="后会有期！"
D.Strings[41316]="我有点儿喜欢你。可别送了命。"
D.Strings[41317]="迪萨克，你这讨厌鬼！等等……你的编码装置出什么问题了？"
D.Strings[41318]="嗯？什么？"
D.Strings[41319]="剧毒金刚单位防护系统已就绪。"
D.Strings[41320]="$n！真高兴你做到了。"
D.Strings[41321]="%s准备屠杀他的敌人！"
D.Strings[41322]="咽气吧！"
D.Strings[41323]="至少……瑟纳利昂和我一起倒下……"
D.Strings[41324]="瑟纳利昂，我去包抄门厅。堵住他们的退路！"
D.Strings[41325]="进入暮光吧！"
D.Strings[41326]="小心点儿，$r。$b$b仪式失败以后，司克诺兹的脾气一直非常糟糕。"
D.Strings[41327]="大使倒在血泊中。$b$b在他破烂的衣服之下，你发现一排巨大而凹深的齿印。$b$b更令人不解的是，伤口仿佛是烧蚀而成，有些地方还有焦黑的痕迹。"
D.Strings[41328]="%s陷入了虚弱状态！快用镣铐抓住他们！"
D.Strings[41329]="<那人几乎当你不存在。他显然没兴趣和你多说什么。>"
D.Strings[41330]="打破门石。把它打开。"
D.Strings[41331]="马上，长官。呃……我找不到插孔？"
D.Strings[41332]="这当然不容易做到，对吧？没关系，我们有备而来。"
D.Strings[41333]="把它炸开。这点问题用炸药就能解决。"
D.Strings[41334]="这才像样。谁会需要这碍手碍脚的门石啊……"
D.Strings[41335]="伞兵？！"
D.Strings[41336]="长官，你身后！诺莫瑞根伞兵！"
D.Strings[41337]="快看！你身后！镜子！"
D.Strings[41338]="镜子？太棒了！"
D.Strings[41339]="继续前进，$r。$b$b你的存在对我毫无意义。"
D.Strings[41340]="<密使冷笑着，看都不看你一眼。>$b$b忙你自己的事去吧，$r。"
D.Strings[41341]="太可怕了！$b$b整个地区都在回响着令人毛骨悚然的咆哮声。$b$b可怜的家伙……$b$b请原谅——我想我得来一杯。"
D.Strings[41342]="我不确定自己究竟看见了什么。$b$b在我意识到发生什么之前，就已经结束了。"
D.Strings[41343]="真是太不幸了！$b$b让我们把这清理干净，好吗？$b$b如果不是万分必要，这种事情绝不能再发生……"
D.Strings[41344]="你不想知道那人怎么了吗？"
D.Strings[41345]="我当然很好奇，但过去的就让它过去吧。$b$b我们可不该再引起什么不必要的恐慌。那可一点儿都不明智！"
D.Strings[41346]="看来你在乎的只是自身的利害关系？"
D.Strings[41347]="当然不是！$b$b我的意思是说，我确实把全部家当都押在了这儿……可老实说，一场公共危机对大家都没好处吧？"
D.Strings[41348]="发生了什么事？！$b$b你看见那人身上的伤口吗？！$b$b会是什么样的怪物干的？"
D.Strings[41349]="深呼吸。你看见什么了吗？"
D.Strings[41350]="不，我什么都不用看也知道，我们全都要死了！$b$b你听懂没有？！"
D.Strings[41351]="放松……恐慌只会让一切变得更糟。"
D.Strings[41352]="你说的倒容易。$b$b我承受不了这么多！我得赶紧想办法离开！"
D.Strings[41353]="<这名演员面无表情地看着你。>"
D.Strings[41354]="奥术重铸师，大法师普拉特最近刚刚从达拉然来到这里，他通常和本地的附魔师拉文尼亚·克洛文一起工作。在炼金房里可以找到他们。"
D.Strings[41355]="我的建议很简单，$r。$b$b别在这儿碍事。"
D.Strings[41356]="啊，你是在找那个归返的上层精灵。$B$B有位奥术重铸师正和附魔师塔兰丹一起工作。可以在工匠区找到他们。"
D.Strings[41357]="有位名叫隐世者汉蒙的学者可以帮上你的忙。你可以在月神殿里找到他，他通常在那里和归返的上层精灵交谈。"
D.Strings[41358]="我们认识吗？不？欢迎来到暮光之锤。"
D.Strings[41359]="末日即将来临！"
D.Strings[41360]="你的护甲上沾了点儿血。你还好吧？"
D.Strings[41361]="新兵？你向指挥官报到了吗？"
D.Strings[41362]="在东边的凋零法阵中正酝酿着什么大事。$B$B不论是什么，都希望能早点儿结束，我们可以到环境更好的地方去。"
D.Strings[41363]="保持警惕。他们说早先那个到处袭击平民的怪人可能还在附近。"
D.Strings[41364]="我们居然把玛加萨·恐怖图腾囚禁在此，这不奇怪吗？好在她所有的图腾都被摧毁了。$B$B我甚至听说她毒害了凯恩·血蹄。希望她是站在我们这边的。"
D.Strings[41365]="在位于中部高地的附魔店里有位名叫赫琳的血精灵奥术重铸师。她能帮上你的忙。"
D.Strings[41366]="我能嗅到你的恐惧……"
D.Strings[41367]="我要把你的心挖出来！"
D.Strings[41368]="哈哈哈哈哈！哈哈哈哈哈！"
D.Strings[41369]="你的鲜血只会刺激我的欲望！"
D.Strings[41370]="等你……找到她……一切都太迟了……"
D.Strings[41371]="督军克罗格派我到这里来固守战线。但他至今都没有派任何士兵给我。$B$B看看这个地方！对面有食人魔，有暮光之锤。我们这边却……啥也没有。"
D.Strings[41372]="$n！到这里来！"
D.Strings[41373]="这边，$n！过来！过来！"
D.Strings[41374]="赶快，$n！没多少时间了！"
D.Strings[41375]="过来，$n！到攻城坦克里来！马上！"
D.Strings[41376]="过了一万年，我终于自由了。但我的亲哥哥仍然认为我是个恶棍！我要让他看看我真正的力量！我要让他知道，恶魔不能控制我！"
D.Strings[41377]="你确定，恶魔猎手？你确定自己拥有独立的意志？"
D.Strings[41378]="你这是自寻死路，人类。你会后悔遇到我。"
D.Strings[41379]="好吧。你会发现，我们势均力敌。"
D.Strings[41380]="统率这支亡灵大军的恐惧魔王名叫提克迪奥斯。他拥有一件强大的战争宝物，被称为古尔丹之颅。"
D.Strings[41381]="正是它腐蚀了这片森林。"
D.Strings[41382]="你想让我偷取它。为什么？"
D.Strings[41383]="欧托·灰皮通常都在长者高地的长者大厅。你可以在那里找到他。他会帮助你的。"
D.Strings[41384]="我对提克迪奥斯没什么好感。我侍奉的那个主人……将从军团的溃灭中获得不少好处。"
D.Strings[41385]="你可以在猎人高地找到烈日行者集会所。"
D.Strings[41386]="长者高地的先知们会帮助你。你可以在那里的长者大厅中找到他们。"
D.Strings[41387]="巫婆长老揉搓着她的手腕，露出牙齿向你笑了笑。"
D.Strings[41388]="我无须用双眼来发现我的敌人。沉重的脚步声和恶臭已经让你们暴露了！"
D.Strings[41389]="空有双眼，却看不见真相。拥抱这一切的终结吧！"
D.Strings[41390]="你们竟然能做到这个地步，我很惊讶。"
D.Strings[41391]="死亡在黑暗中等着你！"
D.Strings[41392]="这个可悲的存在终于完结了。"
D.Strings[41393]="我想，我应该感谢你救了我。我们很快就会知道你的这个决定是否明智。"
D.Strings[41394]="你们在灼热的烈焰面前无处可逃！"
D.Strings[41395]="沿这条路向东走，我们在暮光凋零法阵外碰头。"
D.Strings[41396]="对，跑吧！每跑一步你的心跳都会加快。这心跳声，洪亮如雷，震耳欲聋。你逃不掉的！"
D.Strings[41397]="这座城里的奥术重铸师灌魔者菲娜能帮助你。通常她会和逐日王庭外的瑟丹娜及其学徒们在一起。"
D.Strings[41398]="找到密码，把我从这些恶魔骨头中放出来！"
D.Strings[41399]="一名属于达纳苏斯上层精灵的奥术重铸师正和埃索达的附魔师们呆在一起。你可以在水晶大厅中珠宝加工师的对面找到他们。"
D.Strings[41400]="不要忘记使用它！"
D.Strings[41401]="全都下地狱了，$c！"
D.Strings[41402]="如果你要找蒂亚，她经常在纳鲁之座的幻象中流连。她一定很愿意帮助你。"
D.Strings[41403]="我来负责驾驶！"
D.Strings[41404]="这些洞可都是鬼窟，伙计。里面全都是最可怕的魂能。$B$B当暮光之锤盘踞在这座山顶的时候，那些被他们淘汰的人都被扔进了这些山洞。成为了以这些山洞为巢穴的黑龙的食物。$B$B这些洞里从没有活人走出来，就连那些灵魂也逃不出来。"
D.Strings[41405]="萨露丝，我的蜘蛛丢了。能再给我一只吗？"
D.Strings[41406]="搜寻者波杜鲁通常都在贫民窟的集市里。要找他就去那里吧。"
D.Strings[41407]="上层精灵大法师埃兰希尔·星歌是一位奥术重铸大师……你也许能请求他帮助你。\n\n他通常会在达拉然西北的魔法商业区外面，和简单附魔中的那些人讨论他的魔法技艺。"
D.Strings[41408]="高等精灵法师和学者——达瑞妮斯是这座城里最博学的考古学家……也是最喜交际的人。$B$B她通常呆在魔术旅馆里，就在城中心的北边。她喜欢那里的气氛，常常会与魔术旅馆的老板和客人们谈论她在荒野中的冒险生活。"
D.Strings[41409]="|c00FF0000奇美隆的屠杀让胆汁喷洒机离线了！|r"
D.Strings[41410]="|c0000FF00胆汁喷洒机恢复联线了！|r"
D.Strings[41411]="哦，原来是你抢在我前面了。通过这个传送门离开吧……"
D.Strings[41412]="不……不！这是我的地盘！你不能占据……它……"
D.Strings[41413]="可怜的凡人……我会在你的尸体上建立一个新的帝国！"
D.Strings[41414]="谢谢！嗨！让我们为队长收集些人类！"
D.Strings[41415]="护送杜马斯安全地离开矿洞。不要让杜马斯靠近那些被网住的人类。"
D.Strings[41416]="你怎么耽搁了这么久？我要走了！再见！"
D.Strings[41417]="耶！队长，我回来了！万岁！"
D.Strings[41418]="塔伦米尔！好啊！就是那个在贫瘠之地的塔伦米尔吗！我要走了！谢谢！"
D.Strings[41419]="把他们打倒，消灭他们！给他们戴上镣铐！"
D.Strings[41420]="这很容易！没错！"
D.Strings[41421]="这里有一个！"
D.Strings[41422]="这些人是怎么跑到这里来的？！"
D.Strings[41423]="这家伙发怒了！"
D.Strings[41424]="这片广阔的田野原本并非如此，$c。是我们凭借坚定的决心和意志力，将人类腐朽的农场变成为洛丹伦最大，最丰饶的药渣田和蘑菇种植园。$B$B现在，所有这一切都可能因为一场小小的事故而将化为乌有！"
D.Strings[41425]="我曾经是一名农夫！"
D.Strings[41426]="那边有一个！"
D.Strings[41427]="这些人类看起来很危险！"
D.Strings[41428]="当我醒过来的时候，我看见女妖之王正在和一个高大的褐色兽人交谈！"
D.Strings[41429]="谁是我们的朋友？"
D.Strings[41430]="当女妖之王杀死了所有狼人的时候，你在银松森林吗？"
D.Strings[41431]="变得更大……"
D.Strings[41432]="变得更加巨大……"
D.Strings[41433]="看样子，他就要爆炸了！"
D.Strings[41434]="这里就是收藏古尔丹之颅的地方！这些低贱的恶魔不可能阻止我！"
D.Strings[41435]="现在，至少恶魔们不会再腐蚀森林了。但如果我能够掌握这种力量，我将比阿克蒙德的任何部下都更加强大。"
D.Strings[41436]="是的……这种力量应该属于我！"
D.Strings[41437]="啊，如此强大的力量！"
D.Strings[41438]="不要害怕坏魂能，$g甜心:女孩;。"
D.Strings[41439]="回去吧，$c。这座洞窟里隐藏着某种真正的黑暗。我说的可不是那种因为缺少照明而产生的黑暗。"
D.Strings[41440]="就是这个，朋友！你得到那灵魂之光了？一定要紧握住它，无论发生什么事情都不要松手。$B$B说出那个词，然后我就让你进入灵魂领域。那些灵魂会来找你，竭尽全力将你拖入黑暗。$B$B这时你就要用这灵魂之光去照耀那些污秽！"
D.Strings[41441]="那些脏东西已经被清除了，朋友。这座洞穴现在安全了。$B$B这个地方很适合成为一个家。你觉得如何？也许还缺几个面具？"
D.Strings[41442]="你可真是无所畏惧，$c！$B$B布努正在外面等着你。"
D.Strings[41443]="你要接受训练？我可帮不了你。我可不是你要找的人。"
D.Strings[41444]="你要接受训练，大个子？"
D.Strings[41445]="我会带你去装载室，$n。"
D.Strings[41446]="去这座洞里的三座祭坛。"
D.Strings[41447]="将灵魂之光对准鬼魂来驱散他们！"
D.Strings[41448]="我准备好了，尤彻克！"
D.Strings[41449]="我听不见低语声了，$n。洞里发生了什么事？"
D.Strings[41450]="你想看着千针石林彻底毁灭吗？$B$B不想？$B$B那就照我说的做。"
D.Strings[41451]="你要为你的入侵付出代价！"
D.Strings[41452]="我们就是在这儿集合幸存者，准备对他们进行净化。距离地表没多远了！"
D.Strings[41453]="我相信我不必提醒你，在这儿要保持警惕。"
D.Strings[41454]="有个囚犯逃跑了！杀了$g他:她;！"
D.Strings[41455]="你走不远的！"
D.Strings[41456]="以死亡之翼之名，我要让你见不到明天早上的太阳！"
D.Strings[41457]="要是奴役不适合你，那死亡一定适合！"
D.Strings[41458]="我要让你看到血肉之躯的软弱！"
D.Strings[41459]="你会后悔踏足奥丹姆的！"
D.Strings[41460]="|TInterface\\Icons\\spell_fire_felrainoffire.blp:20|t%s开始施放|cFFFF0000|Hspell:88972|h[邪火风暴]|h|r！"
D.Strings[41461]="嗯，我明白了。这可真奇怪。$B$B谁会把赛艇弄丢呢，长官？"
D.Strings[41462]="怎么会有人能把整条赛艇弄丢呢，$n？"
D.Strings[41463]="这里的一切都完全是光明正大的！"
D.Strings[41464]="呃……这可真难开口，可是……我恐怕把激冻冰弹给弄丢了。"
D.Strings[41465]="等一下……什么？呃，没关系。$B$B这还有个备用的。"
D.Strings[41466]="蛮锤矮人是我们不共戴天的仇敌。不是他们死，就是我们亡。"
D.Strings[41467]="这是你所想出的最低能……最愚蠢……最可笑的计划，巴德！"
D.Strings[41468]="可这恐怕是我们唯一可用的计划。"
D.Strings[41469]="我还能怎么办呢？"
D.Strings[41470]="巨怪碾碎你！！"
D.Strings[41471]="终于……自由了。你们将获得十分可观的奖励，朋友们。"
D.Strings[41472]="你们的点子实在是……出人意料。但烈焰浓烟的遮掩下，我想他们只能看见你们的轮廓。"
D.Strings[41473]="快看我！！！！我是猛犸人！！！"
D.Strings[41474]="闭上你的臭嘴，巴德。闭上！！"
D.Strings[41475]="让我们看看你在自己的同类面前能有多自信，恐惧魔王。"
D.Strings[41476]="好了！$b$b剩下的就交给那些小矮子去处理！$b$b我们回基地！"
D.Strings[41477]="冰淇淋！来吃美味、冰爽、香甜、可口的冰淇淋啰！"
D.Strings[41478]="布里维普的冰淇淋帝国。现有两种口味！"
D.Strings[41479]="试试布里维普的全新异种蝎嚼嚼乐冰淇淋吧。混合真正的异种蝎肉块。绝无人工仿制品！"
D.Strings[41480]="冰淇淋，糖果，泡泡糖！"
D.Strings[41481]="只求最好，决不将就。认准布里维普牌！"
D.Strings[41482]="别打扰我。"
D.Strings[41483]="真是炎热得出奇啊。来尝尝布里维普的异种蝎嚼嚼乐冰淇淋吧！"
D.Strings[41484]="我来此终止你的杀戮行为。"
D.Strings[41485]="布里维普牌冰淇淋，甜点的完美诠释！"
D.Strings[41486]="孩子们全都无法抵挡布里维普牌冰淇淋的诱惑！"
D.Strings[41487]="盲目的蠢货！你根本不知道自己在干什么！"
D.Strings[41488]="够了！快住手！"
D.Strings[41489]="我会查出谁才是这懦夫行为的背后主使！$b$b然后……"
D.Strings[41490]="|cFFFFFFFF药渣农场遇到了麻烦……|r"
D.Strings[41491]="要是真到了我有话对你说的时候，你应该转身就跑。"
D.Strings[41492]="你只是愚笨地在这里蹒跚而行，$r，全然不知自己已被什么样的军队包围。"
D.Strings[41493]="你心中充满了恐惧，凡人。$b$b我能感觉到。"
D.Strings[41494]="有话就说吧。尽量简短些。"
D.Strings[41495]="国王法奥瑞斯派我来了解尼斐塞特的情况。"
D.Strings[41496]="国王派了个陌生人来收集情报？我想你一定是那个……什么来着？$R？对，就是救出纳顿亲王的那个$r。$B$B不管怎样，我在这遥远的北部没察觉到任何尼斐塞特渣滓的活动迹象。不过在这儿倒有许多其它闲事需要处理。"
D.Strings[41497]="我听说过你，$n。你是来帮助我们的吗？"
D.Strings[41498]="我也许能帮上忙。尼斐塞特和此事有关吗？"
D.Strings[41499]="不。这就是废土强盗的杰作。$B$B据说他们加入了西边一个组织更为严密的团伙。他们的暴力行径野蛮至极。"
D.Strings[41500]="我听说你在城里。你可真是个奇怪的家伙。$B$B想和我谈谈？"
D.Strings[41501]="国王想了解尼斐塞特近来的动态。"
D.Strings[41502]="不，尼斐塞特没什么行动。可我刚刚收到消息，一场前所未见的强大沙尘暴袭击了奥西斯城。$B$B我正准备亲自将消息带给国王，看来你可以帮忙转达一下。"
D.Strings[41503]="格瑞里，你能让我重新穿上足球炸弹制服吗？"
D.Strings[41504]="长久以来，我们都仍希望能挽救大地看守者和他的子嗣。在某些时候，我们必须要明智地意识到，任何程度的弥补都抵不过这些巨龙对这个世界所造成的伤害。$B$B在某些时候，我们被迫要插手。"
D.Strings[41505]="跟随幼龙进入黑曜石巢穴。"
D.Strings[41506]="跟上！还有许多事情要做！"
D.Strings[41507]="混蛋！太过分了！"
D.Strings[41508]="带了这么一群蹩脚的强盗来，你能得到什么？他们只不过是历史笑柄！"
D.Strings[41509]="我一定会查明，这背叛的幕后主使究竟是谁，而你要帮助我！"
D.Strings[41510]="这件事要比你我重要得多……比任何人想象中都重要得多！"
D.Strings[41511]="这群羽翼未丰的刺客不知道他们是在和谁打交道！"
D.Strings[41512]="他们很快就会明白……而那时，他们将在恐惧中战栗！"
D.Strings[41513]="喔……我真希望我没到这儿来！"
D.Strings[41514]="我是怎么卷进来的？！"
D.Strings[41515]="我被兴奋冲昏了头。$b$b我早该感觉到的……"
D.Strings[41516]="我一生的财富都……没了。$b$b我的生活已经毫无希望了。"
D.Strings[41517]="这太难以承受了。$b$b真希望我有勇气……<啜泣>。"
D.Strings[41518]="我以为他所做的一切都是正确的。$b$b我……满怀希望。$b$b但他完全不是他自我标榜的那种人。$b$b我真是个傻瓜。"
D.Strings[41519]="海马稳稳的漂浮着。"
D.Strings[41520]="让我看看我能去哪儿。"
D.Strings[41521]="我要前往奈瑟匹拉。"
D.Strings[41522]="试着用铲子来清除食人花苗。|TInterface\\Icons\\INV_MISC_SHOVEL_01.BLP:24|t$B$B或者$B$B[右键点击]食人花苗将它们拔出来|TInterface\\Cursor\\SKINALLIANCE.BLP:24|t$B$B作出正确的选择。"
D.Strings[41523]="也……也许你也没那么坏……"
D.Strings[41524]="谢谢你救了我。我欠你份人情。"
D.Strings[41525]="我会记得你的恩情，$r。"
D.Strings[41526]="这……他们把我们像庄稼一样种到土里！斯蒂沃特简直疯了！趁还来得及，赶紧离开这儿！"
D.Strings[41527]="他杀了所有人！所有人！"
D.Strings[41528]="要是你被埋在没颈的粪池里，我肯定会拉你一把。"
D.Strings[41529]="啊，新鲜的肉！"
D.Strings[41530]="这些文件包含了几个巨魔间谍的信息。他们的脑袋一定保不住了。拿上你的奖金合理使用吧，这可都是暴风城纳税人的钱。"
D.Strings[41531]="这些文件包含了几个兽人间谍的信息。我们最优秀的杀手将会被派去终结他们的背叛行径。拿上你的奖金合理使用吧，这可都是暴风城纳税人的钱。"
D.Strings[41532]="由你为我们送来这份消息可真是荣幸。看来我们终于找到了那个潜伏在城市中的间谍……一个流浪汉。他很快就会被处决。请拿上你的奖励，干得好！"
D.Strings[41533]="喔我的天……居然有人因吃我的面包而生病了？这怎么可能？拜托了，希望我这微薄的收入能解决这困局。"
D.Strings[41534]="我们所有的物品都经过了仔细的检查，运送环节也十分严谨！如果这不是由国王本人签署的，你一分钱也别想拿到。"
D.Strings[41535]="喔……我想我要吐了。我怎么可能把人家的耳朵切下来却浑然不觉？快拿上这点钱找个医生，把耳朵接上去吧。"
D.Strings[41536]="我可不能每次都为别人从他们的坐骑上摔落而负责。我不知你是怎么盖到官方印章的，但请你拿上酬劳走开吧，别再来质疑我的马匹了！"
D.Strings[41537]="你在玩儿火……这是给你的钱，但请记住，我一直在监视着你。"
D.Strings[41538]="我发誓我刚刚才付过一次这样的罚金……"
D.Strings[41539]="我会把她那几个金币寄给她的！居然在我忙碌的时候派人来取钱，这太无礼了。"
D.Strings[41540]="我听说过有老鼠被卡在啤酒瓶里，可从没听过夹在面包里。求——求——求你了，要什么尽管拿去，别和任何人提起这件事。"
D.Strings[41541]="我很少会在给人理发后把钱退回去，可我必须承认——你的发型真是个败笔。我道歉。"
D.Strings[41542]="我那晚肯定是喝醉了，才会答应给你一匹小马。拿着你的钱，别难过，好吗？"
D.Strings[41543]="我们平常都是通过邮寄的方式解决……"
D.Strings[41544]="哇哦。我甚至都没意识到我们居然卖出过这种东西。"
D.Strings[41545]="好吧大家。跟我来，而且，呃……自然点儿。"
D.Strings[41546]="桌上没什么令你感兴趣的东西。"
D.Strings[41547]="桌上放着几堆货物。你决定先从座狼皮开始。"
D.Strings[41548]="你看到了自己早先收集到的那堆座狼皮。这些将被用来为你做衣服。"
D.Strings[41549]="往旁边看去，映入眼帘的是你从熔岩层收集来的黑曜斑点软泥。这些将被用来为你的伪装服染色。"
D.Strings[41550]="最后，你看到了一些线团，将被用来缝制伪装服。"
D.Strings[41551]="你已经集齐了物品。把它们带给萨拉隆·巨钉来完成组合。"
D.Strings[41552]="拿一张皮。"
D.Strings[41553]="拿两张皮。"
D.Strings[41554]="拿三张皮。"
D.Strings[41555]="拿四张皮。"
D.Strings[41556]="拿一捧软泥。"
D.Strings[41557]="拿两捧软泥。"
D.Strings[41558]="拿三捧软泥。"
D.Strings[41559]="拿四捧软泥。"
D.Strings[41560]="拿一团线。"
D.Strings[41561]="拿两团线。"
D.Strings[41562]="拿三团线。"
D.Strings[41563]="拿四团线。"
D.Strings[41564]="调查皮革。"
D.Strings[41565]="你抓到了小偷。享用酬劳吧！"
D.Strings[41566]="看来我们从那死去盗贼身上找到的金币归你了。你可真走运……"
D.Strings[41567]="我不会算错该付的利息……因为一分都没有！跟坐牢相比，我宁可付钱——拿去吧。"
D.Strings[41568]="我们赚的所有钱都在这儿了……真棒。"
D.Strings[41569]="他们这是派谁来了？回去告诉那裁缝，最好用从我这儿拿走的钱，把我的礼服做得完美无缺。"
D.Strings[41570]="我真不敢相信你竟然在这儿卖那些东西。我会顺路拜访厨师来把它们带走。"
D.Strings[41571]="我真该戒赌了。告诉他们我不会再玩了。"
D.Strings[41572]="我知道我上星期总共工作了一百六十八个小时……可如果查不到我的考勤记录，也许你是对的。"
D.Strings[41573]="非常感谢！我生铁锅的保修期能再延长一个月，这太令人高兴了。"
D.Strings[41574]="我的……兄弟死了？我真不敢相信自己居然从未见过他。拿着这些钱，好好安葬他吧。"
D.Strings[41575]="我的……姐妹死了？我真不敢相信自己居然从未见过她。拿着这些钱，好好安葬她吧。"
D.Strings[41576]="我的……叔叔死了？我真不敢相信自己居然从未见过他。拿着这些钱，好好安葬他吧。"
D.Strings[41577]="我的……阿姨死了？我真不敢相信自己居然从未见过她。拿着这些钱，好好安葬她吧。"
D.Strings[41578]="我听说了你在奥西斯的事迹。很荣幸能与你并肩作战。"
D.Strings[41579]="我只听命于一个$r——就是曾救出纳顿亲王的那个。"
D.Strings[41580]="我们该开始着手做些什么了。"
D.Strings[41581]="要是到了逼不得已的境地，我就算赤手空拳也要保卫拉穆卡恒！"
D.Strings[41582]="我们会守卫自己的土地！"
D.Strings[41583]="如果关于你的那些传闻都是真的，陌生人，我会非常愿意与你一同对抗尼斐塞特！"
D.Strings[41584]="这些皮革根本不够作出一套像样的伪装服。"
D.Strings[41585]="好吧，软泥实在太多了。你的伪装服一定会又黑又粘。"
D.Strings[41586]="你带来的座狼皮太多了，$n！"
D.Strings[41587]="我们还需要更多软泥来为你的伪装服染色。"
D.Strings[41588]="我已经有了适量的软泥和皮革，可用来缝制的线还不够。"
D.Strings[41589]="啊！万事俱备，可线太多了！"
D.Strings[41590]="这……这太完美了！这件伪装服简直是我的旷世杰作！"
D.Strings[41591]="在整个黑铁部族中，你再也找不到比我技巧更高超的工匠了！$b$b什么敲打、锻造、采掘，都见鬼去吧！一根缝针、一个顶针就是我所需要的全部金属！"
D.Strings[41592]="我带来了一些皮革、软泥和缝线。"
D.Strings[41593]="你给我带来了什么？"
D.Strings[41594]="快来人让这小姑娘闭嘴！"
D.Strings[41595]="你想要个洋娃娃吗，小女孩？那样会不会好一点儿？"
D.Strings[41596]="杀了我，要不就杀了那小女孩！"
D.Strings[41597]="这是斯蒂沃特的计划？在他杀死我之前，还要如此折磨我？"
D.Strings[41598]="你还在等什么呢斯蒂沃特！杀了我啊！动手啊！"
D.Strings[41599]="你还要哭多久？"
D.Strings[41600]="该死的龙喉渣滓！$B$B他们屠戮我们的鸟禽，攻击我们的亲人，夺取我们的土地。就在这世界分崩离析之时，他们还在袭击我们的家园。$B$B要是你们这群联盟想要获取蛮锤的帮助，就只有一条途径能让我们颔首——阻——止——龙喉。"
D.Strings[41601]="<布朗迪抬眼看了看你。>$B$B啊，是的。高阶萨满正在战场上拼杀，为夺回桑德玛尔废墟而努力。我就是人们口中的“低阶萨满”。$B$B在他离开的这段日子里，他让我留下处理桑德玛尔的萨满事务……"
D.Strings[41602]="桑德玛尔是蛮锤的最后一处堡垒了。我们狭小的城镇中挤满了难民，而我的兄弟此时正在奋力作战。"
D.Strings[41603]="呃……"
D.Strings[41604]="小心，牛头人先生！角鹰兽来了！"
D.Strings[41605]="那边那个！对，说你呢，$c！我被看守者斯蒂沃特强行抓来并关在了这里。把我从这笼子里弄出去，我会向你说明一切。"
D.Strings[41606]="猫咪……猫咪！我真的很抱歉，猫咪！快回来！别这样离开我！"
D.Strings[41607]="暮光精华开始自雏龙的尸体中升腾……"
D.Strings[41608]="混合精华使%s复活了！"
D.Strings[41609]="%s的尸体分解成为升腾的暮光精华。"
D.Strings[41610]="我是来自滩头堡的先遣单位，正在试图说服桑德玛尔的蛮锤部族。$B$B我想我能帮助他们，但令人难以置信的是，他们竟然没有一个三环交流极向转换装置？一个都没有！$B$B他们这些日子到底是过来的？"
D.Strings[41611]="我们这么快就完成练习了？很好，回头见。"
D.Strings[41612]="你好啊，$c！我是来自滩头堡的先遣侦察单位，尽力说服桑德玛尔的蛮锤部族。$B$B他们的狮鹫骑士正被龙喉的龙骑士们纠缠得团团转。我设计了一个奇妙的装置来帮助他们，可我缺少一些物品。许多物品。$B$B你能帮我吗？"
D.Strings[41613]="我来了，$n$g阁下:女士;！"
D.Strings[41614]="我不需要你的怜悯，$C。"
D.Strings[41615]="领导这支亡灵大军的恐惧魔王名叫提克迪奥斯。他控制着一个名为古尔丹之颅的强大术士神器。那就是这片森林堕落的根源。"
D.Strings[41616]="尝尝我的斧子吧，懦夫！"
D.Strings[41617]="把你的脏手拿开，$R。"
D.Strings[41618]="别断……千万别断……"
D.Strings[41619]="该死！那是我最后一把开锁器了！"
D.Strings[41620]="守卫来了，$n！干掉他！"
D.Strings[41621]="干得好！我正准备要动手帮你呢！但看来你已经都搞定了。"
D.Strings[41622]="锁在后面的那只像猫一样的家伙好像有话要说。也许他能帮到我们……但一定要小心。"
D.Strings[41623]="船舱里出现一个模糊的人影！"
D.Strings[41624]="看看这个全息平台。我想让你对诺莫瑞根行动有所了解。"
D.Strings[41625]="我需要进一步研究我们的发现，$n。"
D.Strings[41626]="我们不知该如何利用这些装置所能产生的能量。"
D.Strings[41627]="等我知道下一步该如何进行时，会通知你的。"
D.Strings[41628]="回头见，孩子。"
D.Strings[41629]="吃吧，孩子们！尽情享用他们肥美的躯壳吧！"
D.Strings[41630]="烁影！烁影！不——！！"
D.Strings[41631]="这件事决不会就这么算了，烁影。他们要付出代价！全都要付出代价！"
D.Strings[41632]="你不能让我一个人在这儿自生自灭！带我一起走！"
D.Strings[41633]="溃败信息已接受。正在优化下一战策略……"
D.Strings[41634]="连击信息已接受。正在调整战斗参数……"
D.Strings[41635]="战斗结果：可耻的失败。正在将新策略整合进战斗方案中。"
D.Strings[41636]="战败。可耻等级：高。正在调整未来战斗的作战策略。"
D.Strings[41637]="你好啊，兄弟会的朋友。"
D.Strings[41638]="我是来此帮你进行作战训练的，魔像。"
D.Strings[41639]="看看你多管闲事的后果吧！"
D.Strings[41640]="被我的仇恨吞噬吧！"
D.Strings[41641]="自我训练已完成！"
D.Strings[41642]="训练水平已达到要求。继续执行守卫任务。谢谢你。"
D.Strings[41643]="你在那被摧毁家伙的身体里发现了几个可回收的部件。看来你只能回收一个部件。"
D.Strings[41644]="回收排能滤网。"
D.Strings[41645]="回收黑曜石活塞。"
D.Strings[41646]="回收瑟银齿轮轴。"
D.Strings[41647]="回收石能核心。这些可是稀有物品！"
D.Strings[41648]="呃，什么？"
D.Strings[41649]="整理行装，$n！我们即将前往暮光高地。你准备好了吗？"
D.Strings[41650]="我准备好了，弗林特洛克。带我前往高地！"
D.Strings[41651]="感谢辰星！现在请转过身去，让我穿上。"
D.Strings[41652]="我奉命担任暮光高地联盟联合行动的总指挥。$B$B特立独行的蛮锤部族仍散落在这附近的乡间各地。要是我们能将他们集结于联盟的战旗之下，就将变得势不可挡！可敌人正从四面八方逼近。希望你已经做好了迎战的准备，$c。"
D.Strings[41653]="林度恩？！还活着？"
D.Strings[41654]="我现在知道你在为谁效命了，$n！"
D.Strings[41655]="你呢，珍妮？我原以为在我们之间存在着某种联结。这是你最后一次伤我的心。"
D.Strings[41656]="看守者斯蒂沃特，你这疯子，你这威胁我们生活的毒瘤。奉黑暗女王之命，我来此对你施以被遗忘者律法所允许的最严厉惩罚——真正的死亡。"
D.Strings[41657]="还有你们——与这蠢货同流合污的叛徒渣滓！"
D.Strings[41658]="我是威胁？我是疯子？！"
D.Strings[41659]="我在这儿创造的一切叫做进化！这才是引领被遗忘者走向兴盛的正途，你以为往尸体上撒点亮闪闪的魔法粉尘就够了吗！"
D.Strings[41660]="杀光他们！正好可以把他们当做下次研究的实验对象！"
D.Strings[41661]="我回来了，姐妹！"
D.Strings[41662]="感谢上帝！见到你真高兴……你裤子怎么穿反了？"
D.Strings[41663]="喔！$b$b我们一定要再这么干一次！$b$b好了，我要继续去做研究了。等我准备好了，我会来找你的。"
D.Strings[41664]="不……还不行。"
D.Strings[41665]="你们这群愚蠢的杂种！我真该用鞭子把你们全都抽死！"
D.Strings[41666]="你们这群蠢货毫无用处！毫无用处！"
D.Strings[41667]="你们这些卑劣的杂种最好尝尝我鞭子的滋味！"
D.Strings[41668]="我要让你们鲜血四溅，你们这群没用的瘦皮囊！"
D.Strings[41669]="别在呜咽了，没用的东西！"
D.Strings[41670]="你以为你赢了？再想想吧！在我全新的形态面前战栗吧！"
D.Strings[41671]="啊！我……我动不了了！"
D.Strings[41672]="不……不……让它们离我远点儿！"
D.Strings[41673]="不！啊——！！！"
D.Strings[41674]="诅咒你！诅咒你！诅咒你！"
D.Strings[41675]="喔咦！葛洛普动不了了！格尔洛普要倒下了！"
D.Strings[41676]="嘿！说你呢！想发财吗？奥弗知道哪儿有金币和财宝。跟奥弗去托维尔失落之城走一趟怎么样？奥弗保证不偷不抢。"
D.Strings[41677]="奥弗这名字听起来值得信任。带路吧！"
D.Strings[41678]="全力完善中"
D.Strings[41679]="这熔岩可真烫。"
D.Strings[41680]="格尔洛普不知别的熔岩是不是也这么烫？"
D.Strings[41681]="是我把你从死亡线上拉了回来，$G兄弟:姐妹;。我们现在需要你的帮助！"
D.Strings[41682]="我干过一些相当变态的事，可你在这儿的所作所为就连我也望尘莫及。"
D.Strings[41683]="知道吗，你可以就这么放了他们。我不会告诉任何人。"
D.Strings[41684]="够了！你把血弄得我全身都是。"
D.Strings[41685]="你有问题。"
D.Strings[41686]="真恶心。这些没有头的家伙对我们毫无价值。"
D.Strings[41687]="你认为这就是正确的选择？？？"
D.Strings[41688]="%s开始呕吐。"
D.Strings[41689]="请停下。"
D.Strings[41690]="我想回家。"
D.Strings[41691]="你真是个坏人。"
D.Strings[41692]="感谢你所做的一切，$n。可在我们彻底通过这次考验前，恐怕我会欠你更多人情。"
D.Strings[41693]="现在我可以带着尊严回去了！"
D.Strings[41694]="我们的敌人能把整座城市用沙土掩埋。我们的传统并未让我们做好应对此战的准备。"
D.Strings[41695]="我们终将重建这里，并使其复现往日的荣光——除去那些麻烦的人类。"
D.Strings[41696]="既然我们已经夺取了这座该死的岛屿，我们就得做些什么来让它变得像模像样。你能帮帮我们吗，$n？"
D.Strings[41697]="我对那个人人交口谈论的恶魔监狱不感兴趣。不过我们确实得先完成些任务才能让这地方为己所用。"
D.Strings[41698]="欢迎来到托尔巴拉德，$c。时间紧迫，我们开始吧。"
D.Strings[41699]="无耻的恶魔！你对我兄弟做了什么？"
D.Strings[41700]="以你的灵魂为代价？你再也不是我的兄弟了！离开这里，永远不要再踏上我们的土地！"
D.Strings[41701]="不！伊利丹，你怎么可以？"
D.Strings[41702]="是我，玛法里奥。这就是我现在的样子。"
D.Strings[41703]="亡灵的首领已被消灭，森林的伤痛终将痊愈。"
D.Strings[41704]="就这样吧……兄弟。"
D.Strings[41705]="什么？你是……谁？"
D.Strings[41706]="我们没有选择战争，$n。是战争选择了我们。$B$B我们必须竭尽全力去应对。"
D.Strings[41707]="它能看见我们……"
D.Strings[41708]="把它的眼睛挖出来！"
D.Strings[41709]="你别想告诉任何人！"
D.Strings[41710]="入侵者……"
D.Strings[41711]="别盯着我看，你这紫眼睛的大胖脸！啊，全都炸光，$n。"
D.Strings[41712]="跟黑石兽人达成约定可不是件容易的事儿。我是说，拜托！是黑石兽人哎！这些家伙所经历的战争比阿格拉玛还要多，而且他们还住在黑铁矿堆成的山上！酷毙了！"
D.Strings[41713]="你的死亡将使一切变得不同！"
D.Strings[41714]="你被控是个乔装打扮的恶魔，纳瓦雷克斯……如果那是你的真名！"
D.Strings[41715]="我要跟你的熔岩领主打一场。"
D.Strings[41716]="嗯，孩子？"
D.Strings[41717]="幸好我及时出现了！$b$b我想我们还没见到那最后一个司克诺兹成员。"
D.Strings[41718]="好吧兄弟们，我们有挑战者了！是时候让将军见识下我们小俘虏的本事！"
D.Strings[41719]="不——！我的宝贝儿……"
D.Strings[41720]="努波顿！不——！"
D.Strings[41721]="今天就是你的死期，大地守护者！$n会亲自解决你！"
D.Strings[41722]="阿格娜……这不可能……这太过火了……"
D.Strings[41723]="快做点儿什么，你这没用的$r。我的盟友在为你献出生命！"
D.Strings[41724]="穆恩死了！大地之环也随他一同消亡了。"
D.Strings[41725]="你令我们所有人失望了，$n。死亡之翼赢了。世界的末日已至。"
D.Strings[41726]="快醒醒！我们需要你，$n！"
D.Strings[41727]="熔岩领主现在有点儿……不对劲。别走远，这用不了一两分钟的时间。"
D.Strings[41728]="我们被包围了！它的防御太强大了。$n！快醒醒！"
D.Strings[41729]="啊哈哈！干得好！"
D.Strings[41730]="听听那个兽人的话。他说得有理。"
D.Strings[41731]="你就是那个前来对抗死亡的化身的伟大勇士？"
D.Strings[41732]="你就是那个要将我毁灭的大英雄？"
D.Strings[41733]="你可真没用。你甚至不能离开那块石头。"
D.Strings[41734]="你令你的种族失望。你令艾泽拉斯的所有生灵蒙羞。因为你，你所认识的每个人都将死去……可怖而痛苦地死去。"
D.Strings[41735]="我们得动身前往绿洲了，$n。$b$b你准备好出发了吗？"
D.Strings[41736]="<秧苗的叶子指向你，仿佛在注视着你所在的方向。>"
D.Strings[41737]="集中精神，$n。$b$b我们必须赶在司克诺兹的前面拿到应许约柜！"
D.Strings[41738]="这显然是内鬼干的！$b$b谁也摆脱不了嫌疑！"
D.Strings[41739]="呃，我想我准备好了……"
D.Strings[41740]="使用移动技能可以控制狮群移动。$B$B|TInterface\\Icons\\misc_arrowleft.blp:64|t"
D.Strings[41741]="土狼从你的左翼袭来。准备迎战！"
D.Strings[41742]="%s瞄准$n，准备发射！"
D.Strings[41743]="醒醒，醒醒！"
D.Strings[41744]="我是一棵树！"
D.Strings[41745]="欢迎来到维尔萨尔绿洲，朋友！$b$b艾泽拉斯的人间天堂！"
D.Strings[41746]="你愿意让出两个优质帐篷吗，阿萨克？"
D.Strings[41747]="真是个奇怪的请求，$r，但鉴于你为我们的亲王所做的一切，我没理由回绝你。"
D.Strings[41748]="它们从两翼同时展开密集攻击！"
D.Strings[41749]="%s失控地痛哭起来！"
D.Strings[41750]="%s恐惧地想要逃跑！"
D.Strings[41751]="%s声嘶力竭地大叫！"
D.Strings[41752]="跟上。"
D.Strings[41753]="我的选择明智吗，$n？"
D.Strings[41754]="它们从右翼袭来！如果你的狮群陷入重围，记得使用凶猛咆哮技能！$B$B|TInterface\\Icons\\ability_druid_skinteeth.blp:64|t"
D.Strings[41755]="这是什么意思？！"
D.Strings[41756]="这颜色太刺眼了！"
D.Strings[41757]="真疼啊！真疼啊！！"
D.Strings[41758]="那色彩！不——！"
D.Strings[41759]="太过分了！"
D.Strings[41760]="离我远点儿！"
D.Strings[41761]="啊——！！"
D.Strings[41762]="嘿，等一下……"
D.Strings[41763]="我不认识你……"
D.Strings[41764]="嗯……你是新来的吗……？"
D.Strings[41765]="你不是我们当中的一员，对吧……？"
D.Strings[41766]="哎呦！我干了什么？"
D.Strings[41767]="嘿！你从哪儿找来的棍棒？"
D.Strings[41768]="不是我，我发誓！你什么都证明不了！"
D.Strings[41769]="抱歉！下不为例，长官！"
D.Strings[41770]="你被发现了！在暴露之前把目标杀死！"
D.Strings[41771]="你被发现了！到安全的地方，重新穿上伪装服！"
D.Strings[41772]="你以为你在做什么，士兵？！"
D.Strings[41773]="我要把你切成两半！等一下……你是谁？"
D.Strings[41774]="停下，我不是士兵！嗯……你是吗？"
D.Strings[41775]="你戴的那是面具吗，士兵？"
D.Strings[41776]="小心，$n！他们就在这儿。到处都是……龙喉！"
D.Strings[41777]="别忘了穿上伪装服！"
D.Strings[41778]="那是什么？喔不，龙喉来了！"
D.Strings[41779]="很好，让我们看看你和你的狮子们能做些什么。"
D.Strings[41780]="总有一天，我将为拉穆卡恒贡献自己的力量。"
D.Strings[41781]="快把石头砸开，不然裂开的就是你的脑袋！"
D.Strings[41782]="你想让我拿你的脑袋去砸石头？"
D.Strings[41783]="砸开更多的石头！嘎！"
D.Strings[41784]="该来的还是来了！他们正在发起最后的猛攻。我们已无路可退。唯有坚守桑德玛尔或手握战锤而死。$B$B为了蛮锤部族！！"
D.Strings[41785]="磨洋工的家伙总能令我胃口大开！"
D.Strings[41786]="我有一大盒蜡烛！要是你们好好干，我也许会分你们几根！"
D.Strings[41787]="你想挨揍吗？赶紧挖矿！"
D.Strings[41788]="我要把磨洋工的家伙撕成碎片！"
D.Strings[41789]="你动作太慢了！想让我把格拉布托克找来吗？"
D.Strings[41790]="这看上去真暖和！我有点儿困了……"
D.Strings[41791]="对，就是这里了。"
D.Strings[41792]="再见，$n……"
D.Strings[41793]="看啊，这些盒子。它们里面到底有什么？"
D.Strings[41794]="嘿$n！到这儿来。我们需要你！"
D.Strings[41795]="探险者协会和神圣遗物学会的成员非常相似：考古学是我们的宗教，而我们的信仰都不再纯粹。\n\n我们的手段和他们的伪善没什么两样。我们就像是他们的阴暗倒影。\n\n只需要轻轻推他们一把。他们就会变成我们，远离光明……"
D.Strings[41796]="你听到了吗，$n？树梢上传来了拍击翅膀的声音……纳克拉尔来了。"
D.Strings[41797]="我已经准备好和他作战了！"
D.Strings[41798]="$n，他来了！他正从西方飞来。准备好你的武器！"
D.Strings[41799]="怎么这么多嘴？"
D.Strings[41800]="要它的脑袋！"
D.Strings[41801]="死亡已经找上你了！"
D.Strings[41802]="我想我今天的枪法不太准。"
D.Strings[41803]="我不能……再……打偏了……"
D.Strings[41804]="加油……瞄好准星……不。我想这次又失败了。"
D.Strings[41805]="这不公平……我的目标……它动了一下！"
D.Strings[41806]="视野一片模糊……跟这些水一样。"
D.Strings[41807]="也许你没有听到我的话。我说了，让我摆脱这些链子！"
D.Strings[41808]="你的伪装掉了。小心一些！"
D.Strings[41809]="炎魔之王！我祈求你……赐予我……你的……力量……"
D.Strings[41810]="他们还活着……"
D.Strings[41811]="他们还活着！！！"
D.Strings[41812]="入侵者？！炎术师，烧光他们！让那些无信仰者看看拉格纳罗斯烈焰的力量！"
D.Strings[41813]="炎魔之王不会忽视你的忠心，炎术师。"
D.Strings[41814]="你在地表立下的英勇战功甚至都已经传到了我们主人的耳中；古加尔本人非常满意。"
D.Strings[41815]="我们要继续进攻，直到他们的首都化为灰烬！在圣火中狂欢吧！"
D.Strings[41816]="不！诅咒你，凡人！你的一切挣扎都是徒劳的！"
D.Strings[41817]="你必将葬身于炎魔之王的烈焰之中！"
D.Strings[41818]="炎魔之王的意志必将实现，总大使。"
D.Strings[41819]="有传闻说，一些英雄将元素打退了，但我们还会召唤更多元素。"
D.Strings[41820]="再过一个小时，这座城市将只剩下灰烬。"
D.Strings[41821]="你已经能碰到熔喉的脑袋了！"
D.Strings[41822]="看来邪教徒盯上了那些德鲁伊！$B$B你可以通过这旋转的传送门看到野性之心哨站。穿过传送门就能返回营地。$B$B等这里的工作结束后，便可藉此快速离开。"
D.Strings[41823]="穿过传送门，返回野性之心哨站。"
D.Strings[41824]="你的戳刺引起了枯萎软泥怪的消极反抗。"
D.Strings[41825]="枯萎软泥怪发怒了！"
D.Strings[41826]="枯萎软泥怪想要吸你的血！"
D.Strings[41827]="我能感觉到我的枝桠焕发着无尽的生命力。我已经迫不及待想要让它重返大地的怀抱。"
D.Strings[41828]="您已经不再被困于此地了，伟大的公主。您还不知道吗？"
D.Strings[41829]="这些泰坦的地穴已经随着混乱力量的日渐强大而被削弱了。这座牢狱已经无法再束缚您。"
D.Strings[41830]="非常好。只要您同意，公主。"
D.Strings[41831]="小心说话，死亡之翼的奴才。你以为我是个傻瓜吗？"
D.Strings[41832]="泰拉莫克是我的家园，而不是我的牢狱。造就它的正是我曾经钟爱的一切。"
D.Strings[41833]="不过不必失望，食人魔。我会继续帮助你和你的……教派。"
D.Strings[41834]="毕竟，我很喜欢在上面的世界造成冲突与战争……我喜欢震撼，粉碎，吞噬和摧毁……"
D.Strings[41835]="……但我会留在这里，永远如是。"
D.Strings[41836]="使用改装跑车的钥匙|TInterface\\Icons\\inv_misc_key_12.blp:32|t进入你的跑车，并搭载你的朋友小静、王牌和大胖。"
D.Strings[41837]="谢谢，长官！"
D.Strings[41838]="我们在过去的一小时内没有收到负伤报告。这可是项新纪录！"
D.Strings[41839]="我希望这不用我掏腰包！"
D.Strings[41840]="这样的治疗服务绝对对得起那昂贵的医疗保险！"
D.Strings[41841]="在贸易大王加里维克斯手下工作简直是炼狱。希望你能成为新的贸易$g大王:女王;！"
D.Strings[41842]="通常，我面对那样的爆炸只会一笑了之，可我认为有人把硝基和卡亚矿石混合比例搞错了。"
D.Strings[41843]="都是霍巴特·钩锤那疯子的错！应该有人站出来把他炒掉，让他的助手升职！"
D.Strings[41844]="你知道，老板，为了公司，我很愿意在你的监督下把我自己炸飞！"
D.Strings[41845]="我们的敌人将要毁灭！"
D.Strings[41846]="我已焕然一新！"
D.Strings[41847]="洛丹伦是我们的了！"
D.Strings[41848]="真是辉煌而美丽的力量啊！"
D.Strings[41849]="胜利属于被遗忘者！"
D.Strings[41850]="什么事，小子？你看不见我正忙着吗？"
D.Strings[41851]="我可不愿意和这些术士们一起被困在这里。这是克希鲁恩的工作，不是我的！$b$b我已经等不及要参加战斗了。我需要出去，和我的龙在一起。"
D.Strings[41852]="看看这是谁！是持棍人$g他自己:她自己;！"
D.Strings[41853]="你可真是位骁勇善战的勇士。那怪物已经被解决了。我们离开这里吧。"
D.Strings[41854]="你好啊，朋友！达尔拉女士命我确保你们这群朝圣者都能享受到美好而安全的旅程！$B$B听听克朗奇警官的本地安全提示吧！呀嘿！"
D.Strings[41855]="我是最好的守卫！"
D.Strings[41856]="不，是我！"
D.Strings[41857]="我有一根大棒子，能把一切都砸扁！"
D.Strings[41858]="我的大棒子上还有根钉子！"
D.Strings[41859]="我有一根更大的钉子！"
D.Strings[41860]="我有一根生锈的钉子！"
D.Strings[41861]="这真危险。"
D.Strings[41862]="只是打坏人用的。"
D.Strings[41863]="但我才是最好的看门卫兵。"
D.Strings[41864]="不，我才是！"
D.Strings[41865]="大地在痛苦着……咆哮着！"
D.Strings[41866]="我们就快准备好开战了，兄弟们。索基佐格，有什么事吗？你为什么那样遮住自己的屁股？"
D.Strings[41867]="什么？没理由……我……我的肚子很难受。我想我是吃错了东西。"
D.Strings[41868]="你还能指挥你的部下吗？是否需要暂时把指挥权交给你的一名副官？"
D.Strings[41869]="提曼从灰烬之柱掉下去摔死了。欧萨娜被狼吃了。格尔洛普掉进了熔岩里。我的大部分副官也都在各种各样诡异的事故中丧生。"
D.Strings[41870]="我明白了。那你尽力吧。尼纳拉克，你怎么像刚从烤炉里跑出来一样？"
D.Strings[41871]="你送来的那些小鬼……他们一醒过来，就开始向所有人丢火球！一切都乱套了！"
D.Strings[41872]="送来的？醒过来了？你在说什么啊？你是被小鬼袭击了吗？"
D.Strings[41873]="小恶魔，小鬼，谁知道是什么！我对术士的玩意儿一无所知。恶魔在我看来全都一样！"
D.Strings[41874]="而且，我还在忙着处理其它问题。当那两个敌人横扫前线的时候，我的几十头龙都死了。"
D.Strings[41875]="你们全都是废物。但这没关系：我们有一个深渊领主，所以我们不需要士兵和龙。给我看着吧！"
D.Strings[41876]="一、二、三、四，拇指大战开始了！"
D.Strings[41877]="赶快使用统御宝珠，不要让那个深渊领主来打我们。"
D.Strings[41878]="它……它没有用！深渊领主不受控制了！"
D.Strings[41879]="深渊领主不受控制了！我们完蛋了！快撤！"
D.Strings[41880]="赶快，所有人都向龙靠近！所有部队，全速向龙奔跑！那些龙是我们的救星！"
D.Strings[41881]="我从没有召唤过龙……"
D.Strings[41882]="捍卫者阿尔苏达和其他战士训练师都在那个能俯瞰远行者广场的地方，就是靠近锻造师所在的那个地方。"
D.Strings[41883]="啊，我们尊敬的客人来了！"
D.Strings[41884]="这家伙全身都是割伤、瘀伤和血污。看样子，我们有了一个新的胜利者！"
D.Strings[41885]="女士们，先生们，这些斗士已经取得了胜利！下一场的赌盘现在开始！让我们的钱舞动起来吧。"
D.Strings[41886]="痛苦，但是美丽！古尔戈索克将满足你们的欲望！这是艾泽拉斯最有观赏性的角斗场。朋友们，让我感受到你们的热情吧！"
D.Strings[41887]="哦！！！看看这混乱的一切！真是令人震惊的胜利！他到底有着怎样的力量！"
D.Strings[41888]="呸，你就不能拖拖他的后腿？如果你让这一切显得太容易，人们就不会给我钱了！再加一些戏剧效果吧，好吗？！"
D.Strings[41889]="喔！叫清洁人员来。他们真是把那个挑战者弄得一团糟！"
D.Strings[41890]="摧毁！统治！征服！美妙的胜利！你所做的正是我的最爱！"
D.Strings[41891]="我感觉到有一个倒下了！我们有了胜利者。而场内的一片狼藉正说明了战况是多么惨烈。"
D.Strings[41892]="毫无疑问，他们生气了，因为我碰了一下他们脆弱的小家园。"
D.Strings[41893]="一定要以最大的热情欢迎他们，不是么 ？毕竟，他们要留在这里很长，很长的时间……"
D.Strings[41894]="如果不是形势严峻，我会出现在这里吗？"
D.Strings[41895]="我听说过你。你来此拯救你的世界，从我们这里学习知识。盖亚安祖母命我指导你，因此，你必须听我的话，古伊尔。"
D.Strings[41896]="我告诉过你，请叫我萨尔。"
D.Strings[41897]="嗯，我知道，古伊尔。萨尔是部落的领袖，可你并非以那样的身份来到这里。看看你自己——看看你这身打扮……"
D.Strings[41898]="你说你是来寻求知识与理解，可你却身穿战甲。因此，我质疑你与你的意愿——你是否已准备好完成必须完成的任务。"
D.Strings[41899]="我的衣服？！现在这变成了重要话题？难道我的着装也有争论的价值？"
D.Strings[41900]="着装只不过是潜在问题的外在表现而已。我毫不怀疑你来此学习的诚意，可你必须在精神与外貌上都做好充分的准备。"
D.Strings[41901]="那矮人说得没错。如果你希望与元素交流，你就必须具备发自内心的诚意。"
D.Strings[41902]="是你的心，是你对家园与人民的热爱把你引到了这里。不是你的战甲，也不是你的武器。"
D.Strings[41903]="萨尔，你必须将自己的全部身心投入于其中。"
D.Strings[41904]="阿格娜用不满的目光瞥了加文一眼。"
D.Strings[41905]="古伊尔。你不能继续在酋长与萨满这两种身份间徘徊。总有一天，你必须让自己做出选择。这一天很快就会到来。"
D.Strings[41906]="你们两个的话我都听过了，感谢你们的忠告。"
D.Strings[41907]="如果我想要了解所发生的一切，如果我想要发挥作用，我就必须全身心地投入，必须真心服从。"
D.Strings[41908]="这……只是……开始，凡人们！你们……全都要死！"
D.Strings[41909]="这里还有很多事情要做，$r。你做好帮忙的准备了吗？"
D.Strings[41910]="欢迎来到巴拉丁营地。我知道现在这里还完全不像是一座营地，但只要经过一番努力营建，我们就能让这里初具规模了。"
D.Strings[41911]="不可否认——他们真的干掉了那条狗！我们的前任冠军也只不过是这个水平而已！"
D.Strings[41912]="看样子，我们在这里永远都有事要做。新的命令会在每天凌晨三点到达。这可真是奇怪。"
D.Strings[41913]="看样子，我们又有了一个新的挑战者。现在，大家下注吧！"
D.Strings[41914]="部落对这里发动了凶狠的攻击。我们要在同一时间内进行两场战争。"
D.Strings[41915]="你们全都热衷于痛恨他。而他也喜欢向你们表达他的恨意。让……战斗……开始吧！！！"
D.Strings[41916]="好好欣赏一下我精美的藏品吧。"
D.Strings[41917]="朋友们。蛮锤正在受到致命的威胁。我们的敌人太强大了。我们只凭一己之力无法与他们对抗。我们必须团结起来！"
D.Strings[41918]="风之议会即将获得全部力量！"
D.Strings[41919]="你们的身体条件都很出色！如果你们愿意吸点儿这种麻醉剂，我保证当你们醒来时会比现在强壮10倍，凝聚力比现在强……100倍。"
D.Strings[41920]="不愿意？好吧……这项提议永远有效。欢迎随时到我这里来，我很乐意提供你们梦寐以求的大变身。"
D.Strings[41921]="%s开始从剩下的风领主身上获得力量！"
D.Strings[41922]="绅士们，请……"
D.Strings[41923]="啊！这比我想象的更难。"
D.Strings[41924]="喔，这可真符合焰须的身份，对自己大鼻子以外的一切都视而不见。我们在龙喉那被逼得走投无路。可你有派过一只鸟来帮忙吗？没有！"
D.Strings[41925]="我不必接受这个。有焰须归附的联盟和我将无半点儿干系。我的话到此为止！"
D.Strings[41926]="团结？现在？就连那群暮光萨满祭司攻破我们位于海岸上的要塞时，桑德玛尔人都没能真正团结起来。"
D.Strings[41927]="桑德玛尔，如果我们不是站在这片神圣的土地上，我就会把你一拳击飞，这地上留下的只有你的鞋！"
D.Strings[41928]="喔……喔！太好了！奥尔库斯恢复了神智！那个该死的人类法师肯定诅咒了奥尔库斯的灵魂。我们必须赶快前往海岸！卡莎受伤了！"
D.Strings[41929]="卡莎！到我这儿来！我没事！"
D.Strings[41930]="卡莎！不！！"
D.Strings[41931]="我要死啦！$B$B*呃呃*$B$B救命！"
D.Strings[41932]="你能站起来，奥尔库斯。这里只是浅水。赶快走到岸上去吧。"
D.Strings[41933]="向奥尔库斯说明，他只是站在浅水里。|TInterface\\GossipFrame\\GOSSIPGOSSIPICON.blp:32|t"
D.Strings[41934]="自从格瑞姆巴托陷落之后，我们蛮锤部族就再也没有真正团结起来。在这高地之上，被世界所遗忘，各个部族都已选择了各自的生存方式。$B$B若想将他们重新凝聚在一起可不是件容易的事。"
D.Strings[41935]="是的$n，我已经了解外间所发生的悲惨事件的全貌。$B$B我原本希望我那群蛮锤兄弟们能自行解决，可看来不行。$B$B你和我必须想些有创意的办法。"
D.Strings[41936]="来！跟我走，$n。"
D.Strings[41937]="这片土地可真美啊，不是吗？"
D.Strings[41938]="当危险无处不在的时候，它们也就变成家常便饭了。"
D.Strings[41939]="当面对敌友难分的情境时……"
D.Strings[41940]="但终有一天，这一切都会改变，$n。当那一天到来的时候，那些看到幻象的人才会有所准备。"
D.Strings[41941]="奥丹姆里蕴藏着丰富的财宝，我的朋友。"
D.Strings[41942]="有些就连那些最天真的人都能发现，而要想找到另一些，则需要具备非凡的智慧。"
D.Strings[41943]="莉拉让我来留心你们的身后。如果欧比斯迪在这儿的话，我会吸引住她，然后就要由你们来解决她了。"
D.Strings[41944]="这里有古老废墟与庄严金字塔，危机遍布的奥丹姆荒野，一定能变成观光者向往的天堂！"
D.Strings[41945]="救命！"
D.Strings[41946]="人们从艾泽拉斯各地赶来，向她的奇迹致敬。"
D.Strings[41947]="黏肠食人魔趁科林离开之机，攻入了桑德玛尔。他们把范妮劫走了！"
D.Strings[41948]="我计划亲自创造出一个奇迹，让他们全都看看……"
D.Strings[41949]="科林正在集结桑德玛尔部众，准备对黏肠峡谷发起全面攻击。"
D.Strings[41950]="|cFFFFFFFF那时，我刚刚使用完码头上的设备……|r"
D.Strings[41951]="呃，他们一定在煮粪便吃——不然这气味没法解释。"
D.Strings[41952]="$B$B|cFFFFFFFF我从厕所出来的时候看见他们了！要注意的是，奥尔库斯在做事的时候喜欢安静。|r$B"
D.Strings[41953]="以地狱咆哮战斧的名义！"
D.Strings[41954]="它断了。"
D.Strings[41955]="它还没有断！"
D.Strings[41956]="为什么它会从那一侧喷蒸汽出来？"
D.Strings[41957]="这是……减压阀。"
D.Strings[41958]="在这根管子的中部？"
D.Strings[41959]="呃……备用减压阀？"
D.Strings[41960]="我们应该告诉将军。"
D.Strings[41961]="哎，琳达，我们要在哪里跟这个名叫伊瓦·血牙的家伙碰面？而且以铜须的名义——这难闻的气味到底是怎么回事？"
D.Strings[41962]="你告诉他。"
D.Strings[41963]="决不！他让我浑身都是鸡皮疙瘩！"
D.Strings[41964]="我知道！瞧他看你时那双饥渴的眼睛，我就全都知道了。真不知道他背着我的时候会干出什么来！"
D.Strings[41965]="他们聚集在西边海中的赎罪岛上。我们要去那里见他们，将军。"
D.Strings[41966]="这股气味……*巴琳达用力抽抽鼻子*，我想它应该是从那里来的……"
D.Strings[41967]="看那儿，琳达！是什么……"
D.Strings[41968]="%s咆哮着，以一股强大的意志力恢复了控制！"
D.Strings[41969]="面对弑君者奥尔库斯吧，矮人！"
D.Strings[41970]="卡莎！你的主人需要你！"
D.Strings[41971]="不要再开玩笑了！！！"
D.Strings[41972]="琳达，让我们离开这儿。我们可不想引起什么不必要的注意！"
D.Strings[41973]="是，将军！"
D.Strings[41974]="这景象，这声音，这气味……"
D.Strings[41975]="我邀请你参加它的建成工作。"
D.Strings[41976]="齐心协力，我们将缔造历史！"
D.Strings[41977]="很快，我们的行动便将在艾泽拉斯住民间广为传颂！"
D.Strings[41978]="人们将从世界各地赶来，见证我们劳动的果实，$n。"
D.Strings[41979]="返回巨槌石，否则你将被丢下！"
D.Strings[41980]="我将与你同行，苏拉赫。"
D.Strings[41981]="来，朋友。$b$b跟我一起走一走，我有东西要让你看。"
D.Strings[41982]="黑石军队害怕了！趁现在攻击他们！"
D.Strings[41983]="同时，在巨槌石上……"
D.Strings[41984]="最终结局即将到来。"
D.Strings[41985]="去死吧，兽人！"
D.Strings[41986]="别想碰到我的镇子，兽人！"
D.Strings[41987]="你就弄到了这些！？"
D.Strings[41988]="你想得到范妮？你不能碰范妮！"
D.Strings[41989]="哦，你一离开了龙，就什么也不是了，对不对？"
D.Strings[41990]="来吧！让我狠狠给你一下子，兽人！"
D.Strings[41991]="没错，兽人。我要把你的魂打飞！"
D.Strings[41992]="我会让你闭嘴，兽人。我会把你埋进土里！"
D.Strings[41993]="隐形即将失效！$b$b快找掩护！"
D.Strings[41994]="卡莎，$n给你带来了泥头花。吃掉它，你就能痊愈了。"
D.Strings[41995]="%s将泥头花喂给卡莎。"
D.Strings[41996]="为了赎罪岛，卡莎！像雷霆一样驰骋吧！"
D.Strings[41997]="这群畜生妄想趁我转身之机偷袭我的城镇？！我要让他们知道什么叫蛮锤的正义！"
D.Strings[41998]="我刚刚代表费兹·霍布诺布去过铁木工程营。"
D.Strings[41999]="如果我们不尽最大可能提高生产效率，部落也许就要输掉这场战争了。如果部落输了，我们可就死定了。$B$B我不想打碎你的幻想。但你在语风林地听到的那些美妙的玩意可救不了我们……能救我们的只有勤奋的工作。"
D.Strings[42000]="|cFFFFFFFF$n, 奥尔库斯和卡莎飞向了赎罪岛……|r"
D.Strings[42001]="小心！$b$b麦泽利安能看穿你的伪装！"
D.Strings[42002]="表演我拿手好戏的时刻到了……跑——！"
D.Strings[42003]="哇噢！我这是在哪儿？"
D.Strings[42004]="够了！该像个地精的样子了！"
D.Strings[42005]="你不用告诉我两遍！"
D.Strings[42006]="我知道了！我知道了！"
D.Strings[42007]="深呼吸……深呼吸！"
D.Strings[42008]="我没事！"
D.Strings[42009]="这感觉挺不错！"
D.Strings[42010]="你会将奥尔库斯护送至赎罪岛吗？"
D.Strings[42011]="我不会离开卡莎半步。"
D.Strings[42012]="我准备好前往赎罪岛了。"
D.Strings[42013]="我来这里是为了见证主人的回忆，还有过往的真实。"
D.Strings[42014]="这儿发生了什么事？！"
D.Strings[42015]="大德鲁伊……这究竟是……？"
D.Strings[42016]="我……我必须告诉其它人。你立刻去找女猎手塞露拉。"
D.Strings[42017]="敌人在靠近。用移动技能将拉穆卡恒勇士移至南方坡道。$B$B|TInterface\\Icons\\misc_arrowleft.blp:64|t"
D.Strings[42018]="用弓箭手支援步兵。几支火焰箭就能干掉大部分敌人。$B$B|TInterface\\Icons\\ability_searingarrow.blp:64|t"
D.Strings[42019]="我被发现了！"
D.Strings[42020]="该死的$r！"
D.Strings[42021]="这地方充满邪恶的气息。它必须得到净化！"
D.Strings[42022]="如果招架不住，记得使用烈日照佑技能！这个技能将治疗你方单位，并给敌人造成巨大伤害。$B$B|TInterface\\Icons\\spell_holy_divineprovidence.blp:64|t"
D.Strings[42023]="狼巢之母会要了你的脑袋！"
D.Strings[42024]="离开这片森林！"
D.Strings[42025]="狼人和矮人合作……这个世界怎么变成了这样？"
D.Strings[42026]="抱歉，$n，我不该对你如此不敬。当我们第一次见面的时候，我还以为你只是达萨利亚的一个爪牙。"
D.Strings[42027]="$n，我们是朋友。"
D.Strings[42028]="克罗苏斯碎击！"
D.Strings[42029]="加尔鲁什·地狱咆哮：伟大的酋长还是最伟大的酋长？"
D.Strings[42030]="不要误会我，$n。我喜欢萨尔。他是一位强有力的领袖。但我不认为他适合领导部落，尤其是在一个战争的时代！"
D.Strings[42031]="我有没有和你说过我和萨鲁法尔相遇时的情景？那时我要他在我硕大的胸肌上签字。他却只是反手给了我一个巴掌，所以我现在经常会记不住事情。但这是值得的。"
D.Strings[42032]="瓦里安·乌瑞恩……我见过他在厄运之槌对敌作战的骁勇身姿。他赤手空拳打死了五个深痕雪人。这对人类来说真是相当难得，不是吗？"
D.Strings[42033]="我当时不在场，但我听说，希尔瓦娜斯死在了银松森林。而她所珍爱的瓦格里牺牲自己的生命，让她得以复活。你对此有所了解么？"
D.Strings[42034]="如果伊瓦·血牙在这里，那达利乌斯·克罗雷又在哪里？"
D.Strings[42035]="我喜欢散乱无序的狼人，你可以随意对他们大杀大砍。而这些新吉尔尼斯狼人联盟要难对付得多。"
D.Strings[42036]="$n，这话我只告诉你，我根本没有见到过巫妖王之死。其实……嗯……我从没有去过奥杜尔。我……嗯……我是地下城探险家。是的，我喜欢和朋友们一起探索地下城。这项事业的回报很丰厚，风险又很低。"
D.Strings[42037]="希尔斯布莱德已经变了。过去，这里曾经是战火连绵之地。南海镇的人类和矮人不停地向塔伦米尔的部落发动进攻。在很长一段日子里，当你望向达隆山的路口，就会看见上千人在奋死拼杀。那真是一段光荣岁月，$n——而那些岁月都已经悄然逝去了。"
D.Strings[42038]="我在冰冠冰川找到了卡莎。她身负重伤，奄奄一息。我设法将她带回了暗影拱顶，死亡骑士帮她逃脱了死神的魔爪。我们现在已经成为了彼此的挚友。"
D.Strings[42039]="我听说大漩涡已经打开了，将要吞掉整个世界。你能想象这种事情吗？"
D.Strings[42040]="如果我们能阻止这些矮人和狼人，那我们就是部落的大英雄啦！"
D.Strings[42041]="如果你的身上都是油，那一定要避开一切火星和明火，比如蜡烛、油灯、法师、凯斯特的铺子，还有克朗奇警官！"
D.Strings[42042]="工作时一定要戴上护头设备！没有人知道达尔拉小姐什么时候会给你的脑袋来一下！"
D.Strings[42043]="克朗奇警官希望能确保部下的安全和心情愉悦，他以为这样就能让他的部下按照合同的规定，对他唯命是从了！天哪！"
D.Strings[42044]="当你极度困乏的时候，工作就很容易出纰漏，朋友！换班时务必要保证至少两小时睡眠啊！"
D.Strings[42045]="漏油了！漏油了！有人把开关切了！"
D.Strings[42046]="谁也别想过去！"
D.Strings[42047]="谢谢你救了我！不过能不能别告诉费尔莉？我说是我自己逃出来的！"
D.Strings[42048]="我已得到詹姆斯·哈劳的允许，要取得前往刺枝林地的坐骑。"
D.Strings[42049]="小点儿声，动作轻些。"
D.Strings[42050]="自从月神的镰刀第一次来到这里后，我们之中很少的一部分人住到了这个地方。他们大都承受了吉尔尼斯沉沦的劫难。$B$B我们一直居住在这片森林中，学习自然之道，并致力于维持它的平衡。在这片被诅咒的土地上，我们被诅咒的族人已经找到了一条新的人生之路。"
D.Strings[42051]="要是照我的意思，你早就死了。你这种家伙实在让我厌恶。"
D.Strings[42052]="我一直在试图说服高弗雷，把你们彻底消灭，以结束你们的痛苦。但他总是拒绝我。那你们就继续受苦吧！"
D.Strings[42053]="混蛋。"
D.Strings[42054]="就算是烂在这座牢房里，也比作为耻辱的叛徒活下去更好。"
D.Strings[42055]="部落的兄弟姐妹们，奥格瑞玛正受到攻击！拿起你们的武器，保卫我们的首都！不能与入侵者正面作战的人，就来修筑工事，加固我们的城防！LOK'TAR OGAR！"
D.Strings[42056]="喔！"
D.Strings[42057]="$n？你在这里干什么？你在听从科甘·焰须的命令？"
D.Strings[42058]="在享受美好时光吗？"
D.Strings[42059]="他们有些不安分，所以我要处理一下。好了，我已经忙完了。"
D.Strings[42060]="是的！我们是来救你的！"
D.Strings[42061]="食人魔——消灭他们！"
D.Strings[42062]="你看见了吗，$n？竟有这样的女人！"
D.Strings[42063]="绝不让那些该死的兽人再入侵赤脊山！"
D.Strings[42064]="这真是孤注一掷。我们把很多赌注都押在这个计划上了。赤脊山的自由就是其中之一。"
D.Strings[42065]="停！下来，$n！"
D.Strings[42066]="小心！范达尔、巴琳达和血牙也在那里。"
D.Strings[42067]="你已到达凿握据点，$g小伙子:小姑娘;。最好能发挥你的价值。"
D.Strings[42068]="看那边，地图桌附近！联盟进攻计划在雷矛战斗大师手里！"
D.Strings[42069]="你必须先得到锈水财阀地精的友谊，我才会教你骑术。"
D.Strings[42070]="你必须先得到锈水财阀地精的承认，我才会教你骑术。"
D.Strings[42071]="准备好进行骑乘了？"
D.Strings[42072]="准备好进行骑乘了，宝贝？"
D.Strings[42073]="你的黑石伪装掉了！"
D.Strings[42074]="我……我有自己的计划。"
D.Strings[42075]="我会干掉桌旁的卫兵，吸引那三个家伙的注意力。"
D.Strings[42076]="我来吸引他们的注意力，你去守卫的尸体上找计划书。只要你一拿到计划书，我就会叫卡莎来接你离开。"
D.Strings[42077]="不要担心奥尔库斯，$n。我……我会好起来的。"
D.Strings[42078]="石头穴居人……深渊的害虫。"
D.Strings[42079]="准备好就来告诉我，我们即刻出发！|TInterface\\GossipFrame\\GOSSIPGOSSIPICON.blp:32|t"
D.Strings[42080]="准备好了么？你必须马上行动，$n。我不知道还能挡住他们多久！拿上计划，快走！"
D.Strings[42081]="我准备好了，奥尔库斯。让我们开始吧！"
D.Strings[42082]="我很想和你做生意，朋友。我是真心实意这样说的。但你首先要得到锈水财阀的友谊。"
D.Strings[42083]="上校，我的黑石伪装丢了。能再给我一件么？"
D.Strings[42084]="我很想和你做生意，朋友。我是真心实意这样说的。但你首先要得到锈水财阀的承认。"
D.Strings[42085]="呦！我是锈水三轮摩托经销商卡尔·万金。$B$B欢迎随便看看。选出您最中意的三轮摩托！$B$B一辆无比拉风的三轮摩托……一辆充满危险气息而又无惧死亡的三轮摩托……一辆为您带来荣光的三轮摩托！$B$B选好就来找我，我们来谈谈价格。"
D.Strings[42086]="拿起计划赶快走！"
D.Strings[42087]="%s温暖地闪动着，将自身能量的一部分赠与$n，以表谢意。"
D.Strings[42088]="她就像火药桶一样一碰就炸！所以她一定能生出最优秀的焰须战士来！你认为桑德玛尔会答应吗？"
D.Strings[42089]="“大法师普拉特”？去它浮云般的虚名，我的虚荣心已经随我一通消亡了。叫“查尔斯”，或是简单地称作“查斯”就行了，谢谢。"
D.Strings[42090]="我们得继续前进。这儿充满危险。"
D.Strings[42091]="别管我，卡莎！快走！"
D.Strings[42092]="卡……卡莎……你……为了我回来……"
D.Strings[42093]="安全的地方……"
D.Strings[42094]="一定要迈格拉夫一家人谈谈。他们就在庇护所里。他们会在那里安排这场仪式的。"
D.Strings[42095]="你真的是来救我的？太棒了，我们走！"
D.Strings[42096]="我想，我能骑这匹马走完剩下的路。谢谢！"
D.Strings[42097]="请照顾卡莎。一定要让她生活在够冷的地方。"
D.Strings[42098]="焰星！我可以送这些龙回归它们的族群。让我来照顾他们。"
D.Strings[42099]="如你所愿。只要确保它们不受到伤害。"
D.Strings[42100]="不要忘记伪装！"
D.Strings[42101]="你的同谋者已经把你们的计划告诉了我。我们战场上见……涂满元素余烬的战场。"
D.Strings[42102]="来，孩子，我们吃吧！我最喜欢的战士为大家带来了足够的狼肉！"
D.Strings[42103]="我猜，我只需要……把这些睡着的小鬼留在这里？这些……是小鬼吗？嘿！"
D.Strings[42104]="你知道，几分钟后，我就将用这个宝珠开始一场强大的仪式。别告诉任何人……我要召唤的是一位深渊领主。赤脊山将屈从于黑石部族的力量！"
D.Strings[42105]="准备好了，琼斯博士！"
D.Strings[42106]="这次无路可逃了，兽人！你已经喊完了最后一句兽人口号！"
D.Strings[42107]="$n，跟着我！"
D.Strings[42108]="火炮与一个爆炸陷阱连在了一起！"
D.Strings[42109]="我的内心告诉我……"
D.Strings[42110]="……这边！"
D.Strings[42111]="应该很快就好。"
D.Strings[42112]="胆汁喷洒机发出了肯定的信号，永久地关闭了。"
D.Strings[42113]="密码接受。系统激活。"
D.Strings[42114]="在火焰之地的流火中被烧毁吧！"
D.Strings[42115]="发生了什么事？你手里拿的是什么？"
D.Strings[42116]="%s仔细查看联盟作战计划。"
D.Strings[42117]="他……为了把这个送来而牺牲了？"
D.Strings[42118]="%s举起奥尔库斯没有生命的躯体。"
D.Strings[42119]="不要为奥尔库斯哀伤。他带着荣誉与自豪……而死。他是部落的英雄。"
D.Strings[42120]="从洛丹伦到卡利姆多，他们都将知道他的名字，唱起光荣的歌曲，颂扬这位牺牲的部落英雄。"
D.Strings[42121]="要知道，你所做的一切将拯救数百——也许是数千条生命。你同时也是部落真正的大英雄，$n。"
D.Strings[42122]="嗯，改变进行得非常顺利。"
D.Strings[42123]="太好便会有失真实。我本该知道的。"
D.Strings[42124]="看来我们要费一番功夫才行。我们走！"
D.Strings[42125]="系统宕机。发现内部数据破坏。$b$b构建防御机制。"
D.Strings[42126]="构建防御系统。"
D.Strings[42127]="就连天空也要在我的怒火中燃烧！"
D.Strings[42128]="|TInterface\\Icons\\ability_whirlwind.blp:20|t死神5000型启动|cFFFF0000|Hspell:88481|h[超速]|h|r！"
D.Strings[42129]="朋友，你是来学习钓鱼的？还是来买东西的？"
D.Strings[42130]="砸烂那些水晶，$n！这应该能让它关闭！"
D.Strings[42131]="凡人世界的夕阳已经落幕。平静接受你的末日，暮光的时刻来临了！"
D.Strings[42132]="发现目标！狩猎开始！"
D.Strings[42133]="这可不是运动，而是杀戮。"
D.Strings[42134]="竟然被低等平民杀掉了，真是滑稽……"
D.Strings[42135]="立刻离开这个诅咒之地！"
D.Strings[42136]="%s的束缚正在松开！全能量开启。"
D.Strings[42137]="死亡只能暂时延缓我的诅咒。"
D.Strings[42138]="愿你的灵魂得到安息。"
D.Strings[42139]="希望你的灵魂能找到庇护之地。"
D.Strings[42140]="城堡中有入侵者！准备战斗！"
D.Strings[42141]="又向胜利迈进了一步！"
D.Strings[42142]="攻击者被削弱了！"
D.Strings[42143]="我们将永远保持警惕……"
D.Strings[42144]="我竟然被一群傻瓜困住了！"
D.Strings[42145]="别想再给我找麻烦！"
D.Strings[42146]="这种幼稚的游戏该结束了！"
D.Strings[42147]="我的新生命刚刚开始……"
D.Strings[42148]="伊瓦的部队遭受了惨败。所以他现在又派来了佣兵。没关系，你们就要在巨大的痛苦中彻底被毁灭了。"
D.Strings[42149]="那个该死的希尔瓦娜斯又派你来了？没关系，来迎接你痛苦的末日吧。"
D.Strings[42150]="这就是被派来杀我的刺客？真可笑。"
D.Strings[42151]="谋杀永远也不会过时。"
D.Strings[42152]="感谢你让我死得这么痛快，要不是你，我永远也做不到……"
D.Strings[42153]="听着！$b$b拿走那些水晶会让构造体失去能量。"
D.Strings[42154]="我们必须拿到那个箱子，同时又不能惊动司克诺兹和他的手下。"
D.Strings[42155]="%s开始引导能量，准备进行一次强力攻击！"
D.Strings[42156]="一头狂暴猎犬大声咆哮……"
D.Strings[42157]="狂暴猎犬的口水淌了一地板……"
D.Strings[42158]="使用你的改装跑车|TInterface\\Icons\\inv_misc_key_12.blp:32|t追上受雇的抢掠者，夺取他们偷走的物品。"
D.Strings[42159]="那条狗茫然地盯着墙壁……"
D.Strings[42160]="是的，抓住他！"
D.Strings[42161]="哈！$b$b你真的搅起了一场沙暴，$n。"
D.Strings[42162]="黑石兽人是我的同族。我的父亲、母亲、父亲的父亲都是黑石兽人。我也是黑石兽人。$b$b但更重要的是，我是一个兽人。这意味着荣誉对我比什么都重要。$b$b我的领主允许我来到燃烧平原完成我的任务。在这里的黑石兽人明白他们的错误之前，我绝不会离开。"
D.Strings[42163]="我忠于我的父亲，尊敬他的计划……但我也忠于我心中的正义。我的黑石兄弟们制造的阴谋和欺诈，即使用一千本书也写不完。现在，他们又要入侵赤脊山，只为了满足他们盲目的扩张主义心理。$b$b我不会让他们的阴谋继续下去。这个邪恶的故事将写完它的最后一章，并得到一个绝不会让他们满意的结局。"
D.Strings[42164]="我的黑石伪装丢了。能再给我一件么？"
D.Strings[42165]="这全都是她的错！是她让我们偷的！"
D.Strings[42166]="我的孩子们……我干了什么！"
D.Strings[42167]="不……我是永生不死的……我还会……"
D.Strings[42168]="这是我们的错……这毁灭全都是我们的错……"
D.Strings[42169]="水晶还能被找到……如果我们能再次找到它……"
D.Strings[42170]="真累啊……真想休息……"
D.Strings[42171]="水晶将拯救我们！我们将得到拯救！"
D.Strings[42172]="他让它来了。"
D.Strings[42173]="为什么地面在颤抖，$n？！"
D.Strings[42174]="那是什么，$g老兄:宝贝;？"
D.Strings[42175]="其实我正想要找你呢。真的！"
D.Strings[42176]="我本打算在这里搞点小买卖的！"
D.Strings[42177]="<杰克低声嘟囔着。你觉得他似乎是在说，锤子是他的武器。>"
D.Strings[42178]="哦，不，你不能那样！"
D.Strings[42179]="我自由了！让我们以耐普图隆的名义去消灭海纳泽尔吧，$n。他就藏在这座神殿里。"
D.Strings[42180]="德拉克·奈特弗，等候你的吩咐！"
D.Strings[42181]="我想买你的东西，德拉克。"
D.Strings[42182]="%s陷入可怕的愤怒！"
D.Strings[42183]="我可不知道苏拉赫有这么多……熟人。"
D.Strings[42184]="你好，朋友！$B$B我的名字叫罗素，我的事业是音乐。历史长河中所有伟大的蛮锤英雄都活在我的歌曲中。借助我的鲁特琴弦和我的歌喉，我们的勇士得到了不朽的威名。$B$B请停下脚步，听我唱一段颂歌吧！"
D.Strings[42185]="我们开始吧！第一段是写给亲爱的范妮的，但我还没有最终完成。$B$B“眼睛”的韵脚该怎样去押呢？"
D.Strings[42186]="啊，我知道你是怎样的$c了，$n！那么，第二段是关于范妮和焰须在一起的故事。$B$B“皈依”的韵脚又该怎样押呢？$B$B"
D.Strings[42187]="……嗯，好吧，我想我可以完成这个作品了。最后一段！逐渐激扬的爱之庆典向蛮锤发出行动的呼唤。$B$B我现在只要押上“团结”的韵脚……"
D.Strings[42188]="[罗曼蒂克：]“智慧。”"
D.Strings[42189]="我需要一头狮鹫，戈斯鲁姆。我要前往西瘟疫之地。我的国王需要我！"
D.Strings[42190]="[傻子：] “一点点。”"
D.Strings[42191]="[风骚：]“大腿！”"
D.Strings[42192]="[罗曼蒂克：]“祝福。”"
D.Strings[42193]="[傻子：] “注定的。”"
D.Strings[42194]="[风骚：]“胸部……？”"
D.Strings[42195]="[罗曼蒂克：]“点亮。”"
D.Strings[42196]="[傻子：]“决斗。”"
D.Strings[42197]="[风骚：]“紧抱在一起！”"
D.Strings[42198]="我需要一只蝙蝠，凯伦。我要去西瘟疫之地。黑暗女王需要我！"
D.Strings[42199]="我准备好了，罗素。我们来写首歌吧！"
D.Strings[42200]="我需要一只蝙蝠，提摩西。我要去安多哈尔。黑暗女王需要我！"
D.Strings[42201]="我需要一头狮鹫，比比尔法兹。我要去安多哈尔。我的国王需要我！"
D.Strings[42202]="我的鲁特琴已经调整到了最佳状态。我们是否准备好谱写一些东西了？"
D.Strings[42203]="|cFFFFFFFF索菲亚高地，希尔斯布莱德四根手指的第一根。|r"
D.Strings[42204]="我没想到这里还会有人。你打算作我的同伴，还是只想找一条路出去？"
D.Strings[42205]="我要离开这个地方。"
D.Strings[42206]="终于得到了安息……"
D.Strings[42207]="现在，走吧……你不应该承受这水晶的怒火……"
D.Strings[42208]="是离开的时候了……"
D.Strings[42209]="水晶回来了。你必须离开……"
D.Strings[42210]="|cFFFFFFFF考兰之匕，希尔斯布莱德四根手指的第二根。|r"
D.Strings[42211]="|cFFFFFFFF山头营地，希尔斯布莱德四根手指的第三根。|r"
D.Strings[42212]="|cFFFFFFFF加文高地，希尔斯布莱德四根手指的第四根，即最后一根。|r"
D.Strings[42213]="|cFFFFFFFF雷矛卫队已经得到了军情七处的援助。这就是他们的侦查前哨站。|r"
D.Strings[42214]="你正在逐步消融！赶快去找大地之环萨满救你！"
D.Strings[42215]="|cFFFFFFFF雷矛卫队将这里作为士兵的前锋营地。|r"
D.Strings[42216]="|cFFFFFFFF他们在这里训练部队，传授给士兵各种最新和最激进的技能，好让他们来杀我们。|r"
D.Strings[42217]="|cFFFFFFFF那些手指都得到了严密守卫。而且他们恐怖的攻城器械正在这里集结。|r"
D.Strings[42218]="|cFFFFFFFF这些手指合在一起，如同雷矛卫队将我们紧紧攥住的拳头。必须将它们摧毁。|r"
D.Strings[42219]="故事里讲述了一位美艳无俦的女郎"
D.Strings[42220]="柔美的脸上，一双翡翠般的眼睛里闪烁着智慧的光芒"
D.Strings[42221]="人们呼喊着她的名字，“范妮”。"
D.Strings[42222]="无数人在追求她，却得不到她明眸一瞥"
D.Strings[42223]="直到强大的焰须得到她心灵的皈依"
D.Strings[42224]="我们英雄的爱直达天堂"
D.Strings[42225]="满溢的祝福，世间罕有"
D.Strings[42226]="现在，让欢呼驱散暮光"
D.Strings[42227]="蛮锤团结一致！"
D.Strings[42228]="响应这号召，证明爱情能征服一切"
D.Strings[42229]="让我们点亮整座高地！"
D.Strings[42230]="他们说，她从桑德马尔而来"
D.Strings[42231]="让我们欢呼，万岁，万岁，万岁！"
D.Strings[42232]="人们叹息着，望着那一点点奖赏"
D.Strings[42233]="为了范妮，为了范妮，嗨嗨。"
D.Strings[42234]="焰须发出他的恳求"
D.Strings[42235]="哦，我们的焰须"
D.Strings[42236]="他的目标正是注定的婚姻"
D.Strings[42237]="哦，范妮！不，范妮不要逃！"
D.Strings[42238]="现在，蛮锤团结为一体！"
D.Strings[42239]="哦，焰须和范妮"
D.Strings[42240]="团结一致，欢呼雀跃。这是与暮光的决斗"
D.Strings[42241]="为了范妮！为了焰须！为了我们的乐趣！"
D.Strings[42242]="讲述了一个大胆的女郎"
D.Strings[42243]="有着翡翠般的眼睛和能夹死男人的大腿"
D.Strings[42244]="“范妮”这是多么完美的名字。"
D.Strings[42245]="老焰须在追求她"
D.Strings[42246]="他单膝跪下，立下皈依的誓言："
D.Strings[42247]="“哦，范妮，我的范妮，能不能嫁给我？”"
D.Strings[42248]="“我爱你，爱你的胸部。”"
D.Strings[42249]="他们又矮又强壮。没人能够怀疑："
D.Strings[42250]="焰须和他的范妮紧抱在一起。"
D.Strings[42251]="你不明白！我必须研究它。必须！"
D.Strings[42252]="请原谅……我……"
D.Strings[42253]="我还以为自己注定要成为这头臭怪物的大餐了！"
D.Strings[42254]="希望我的人能够给予你适当的欢迎。这是个艰难的时代，恐怕没有多少人还会在乎礼貌和优雅了。"
D.Strings[42255]="没关系，祭司大人。您为我们所提供的一切已经让我们感激不尽了。"
D.Strings[42256]="你曾经承诺过会还我的人情。现在，我只能让你履行你的承诺了。"
D.Strings[42257]="在洛达内尔，我们的一座与鲁瑟兰隔水相望的村子里出现了一些很糟糕的情况。"
D.Strings[42258]="希望你能支援我们一些人手。在卡利姆多爆发的战争正逐步蚕食着我们。"
D.Strings[42259]="我知道完成这种任务最适合的人选。我会立刻派遣他们过去，祭司大人。"
D.Strings[42260]="谢谢你，吉恩。很高兴能看到你的人民会如此镇定从容。也许你们受到的诅咒并没有真正伤害到你们的心灵。"
D.Strings[42261]="泰兰德大人！没想到你会来。晚上好。"
D.Strings[42262]="我们就要离开了。再次欢迎你们所有人。"
D.Strings[42263]="小心，$g小伙子:姑娘;。下方有无数座狼，而兽人就潜伏在路口。一个$c在这里随时都有可能丧命。"
D.Strings[42264]="%s迫使$n服从他的意志！"
D.Strings[42265]="女妖之王已经对你做出了计划，人类。"
D.Strings[42266]="%s发出了狂怒的咆哮！"
D.Strings[42267]="你并非行走于黑暗道路上的人！你不属于这里，$r。"
D.Strings[42268]="暗影将吞噬你。你还没有准备好面对虚空。"
D.Strings[42269]="这个脏东西让我的新袍子上全是污渍！"
D.Strings[42270]="古加尔想要你们全部的脑袋！"
D.Strings[42271]="龙群今晚能饱餐一顿了！"
D.Strings[42272]="承受被诅咒者的重负吧！"
D.Strings[42273]="我……觉得……很晕。"
D.Strings[42274]="谢谢你救了我！你昏过去的时候，我还以为我们都完了！"
D.Strings[42275]="用女妖之镜召唤来一个女妖！"
D.Strings[42276]="当我说要直击那个怪兽的心脏的时候，我可没有想要穿透它的肚子……"
D.Strings[42277]="元素的力量在这里非常强大。怪不得他们会选择在这里召唤上古之神的仆人。"
D.Strings[42278]="我似乎看到一种可怕的景象——天空被遮蔽，到处都是尘泥……我还以为又回到了深岩之洲。"
D.Strings[42279]="现在该是我们返回高地的时候了！“暮光”必将终结。"
D.Strings[42280]="我记得曾经在埃索达看到过与此类似的……"
D.Strings[42281]="有许多人会把陶土议会和塞纳里奥议会混为一谈……我早就告诉过萨尔，我们应该改名为“大地之环”。"
D.Strings[42282]="萨满和德鲁伊之道截然不同。你什么时候看见过我们变成野兽？……算了。"
D.Strings[42283]="我们操纵元素的力量。风暴、大地和火焰！我才不会穿成鸡仔一样，让月光从天空上射下来。"
D.Strings[42284]="主人会让你安静下来的。"
D.Strings[42285]="我操纵风暴的力量。这听起来很强大，但我每天早晨醒来的时候，身上总是会窜起一道道静电火花。"
D.Strings[42286]="我现在就想用双拳打碎那个上古之神的脑壳！"
D.Strings[42287]="不要害怕辛玛洛。它永远也不可能属于别人。"
D.Strings[42288]="你知道，想要找到一套能配上我的护甲的武器有多难吗？"
D.Strings[42289]="其他萨满经常说：“只有你的副手应该喷火。”他们这么说是什么意思？"
D.Strings[42290]="回复生命就是恢复元素的自然秩序。"
D.Strings[42291]="萨满的治疗术是一种复杂的艺术。你不可能花一整天的时间来操纵治疗的能量。"
D.Strings[42292]="没有几个人能真正理解萨满与大地的联系。正是这种联系让伤口愈合，保护我们免于受到伤害。"
D.Strings[42293]="我不明白，他们为什么要禁止利用图腾进行净化。毕竟在净化范围内没有任何人。"
D.Strings[42294]="好吧…………这里的全都属于你。没关系，无论是有生命的、岩石的，还是……"
D.Strings[42295]="我需要飞往尘泥沼泽。"
D.Strings[42296]="如果你让两只眼睛对起来，将拇指伸向天空，用力按过去……"
D.Strings[42297]="魂精就有可能出现！就像这样。"
D.Strings[42298]="虽然这些礼物并没有什么实际用处。但它们还是能让我想起那些老朋友和过去美好的时光。"
D.Strings[42299]="当那个脑子受到进攻时，厄索拉斯的肚子也开始搅动起来！"
D.Strings[42300]="嘿！你们在干嘛？！"
D.Strings[42301]="这些不可理喻，不知好歹，肆意妄为的家伙……"
D.Strings[42302]="哈！你迷路了吗，小$g男孩:女孩;？"
D.Strings[42303]="你们完蛋了，$g小子:小姑娘;！希尔斯布莱德是雷矛卫队的！"
D.Strings[42304]="哈！得到了一根绳子！"
D.Strings[42305]="你走错了地方！"
D.Strings[42306]="士兵们，高度戒备！有报告说，在索菲亚高地附近发现了敌人的行踪！"
D.Strings[42307]="这里的情况如何？有什么行动吗？"
D.Strings[42308]="保持冷静，士兵们。我们很快就要采取行动了。"
D.Strings[42309]="你是一个女孩所能梦想的最英俊的男朋友。所有女孩都会为你神魂颠倒，甜心！"
D.Strings[42310]="看到你！我就知道我是这座岛上最幸运的男孩子！！！"
D.Strings[42311]="|TINTERFACE\\ICONS\\Spell_Frost_WindWalkOn.blp:20|t%s开始施放|cFFFF0000|Hspell:87770|h[阵风冲击]|h|r！"
D.Strings[42312]="你最好快上楼去，老板。贸易大王加里维克斯正在等你。"
D.Strings[42313]="$n，你必须加紧行动，把你的钱从银行里拿出来！"
D.Strings[42314]="老板，告诉莎希，只要生产恢复，我就能为她提供更多的卡亚可乐。"
D.Strings[42315]="他能给我们弄到更多的卡亚可乐吗？如果我们不能让自己的头号商品摆满货架，又怎么能让你成为贸易大王？！！！"
D.Strings[42316]="哦，我想你会喜欢这个的，老板！"
D.Strings[42317]="他们在这里！好了，你们三个今天来帮$g他:她; ，在聚会开始之前，$G他:她;要做的事情可是不少呢！"
D.Strings[42318]="王牌、小静、大胖，你们三个要跟着$n，帮助他处理那些坏家伙！"
D.Strings[42319]="一定要从那个银行里拿到足够的钱。我可不希望你还去买你平时喜欢穿的那种廉价衣服。这可是个重要的聚会！"
D.Strings[42320]="你们不得不等一等了！$n来了。$G他:她;将是下一任贸易大王！"
D.Strings[42321]="你要快一点，孩子。我们要让你加入比赛。但首先，我们要给这台伐木机找好零件！"
D.Strings[42322]="进入伐木机，赢得比赛。锈水财阀就指望你了！"
D.Strings[42323]="你胜利了，孩子，这太好了！可惜的是，那头龙已经把一切都毁掉了。不过没关系。你的成就让我们感到自豪。现在，回总部去吧。"
D.Strings[42324]="我会教你如何进行稳固射击，然后你就要在这些训练假人上练习这种技能了。"
D.Strings[42325]="你要做的就是学会如何施放冰霜新星。然后，到巴姆正在射击的那些训练假人那里去，冻裂它们。"
D.Strings[42326]="你所要做的就是学习暗言术：痛，并使用在附近的训练假人身上！"
D.Strings[42327]="我会教你如何施展刺骨技能。然后，你可以到巴姆正在射击的那些训练假人那里去，用影袭技能攻击其中的一个，再用刺骨技能干掉那个假人。"
D.Strings[42328]="我会教你如何进行根源打击。然后，你可以到巴姆正在射击的那些训练假人那里去，实践这个技能。"
D.Strings[42329]="你要做的就是学会如何施放腐蚀术。然后，对巴姆正在射击的那些训练假人使用这个法术，腐蚀它们。"
D.Strings[42330]="塞入硬币，全能战士NX-01型会教你如何进行冲锋。然后你可以在训练假人身上进行实践。"
D.Strings[42331]="你到了那幢小屋之后，我会将帽子设置成自动状态。小心一定要躲开那些猪！"
D.Strings[42332]="我需要飞往寒风营地，请帮助我。"
D.Strings[42333]="我需要飞往亡灵壁垒，请帮助我。"
D.Strings[42334]="真无法相信这些巨魔的勇气。他们竟然敢造我的反！"
D.Strings[42335]="你可真有胆量，兄弟！"
D.Strings[42336]="你要消灭那头大坏龙，摧毁了那座岛！"
D.Strings[42337]="我可不打算再这样了，兄弟！"
D.Strings[42338]="科赞是巨魔的！"
D.Strings[42339]="别挡我的路，兄弟。我要加入海盗！"
D.Strings[42340]="也许我应该把炸弹从你手里拿走。然后我们看看谁会爆炸！"
D.Strings[42341]="这就是卡亚矿石！是我们挥洒血汗挖掘出来的宝物！"
D.Strings[42342]="小绿地精要流血了！"
D.Strings[42343]="什么？你想要什么？你在开玩笑吗？现在跑去望风没有任何好处，$n！$B$B赶快回去工作！"
D.Strings[42344]="想要驰骋一番吗，$g坏家伙:甜心;？来吧，我们要去沼桨镇。这可是一次单程旅行。"
D.Strings[42345]="好了，我们去悲伤沼泽！"
D.Strings[42346]="我来这里是为了护送去库斯海文的人。"
D.Strings[42347]="睁大眼睛，$n！这条路上全都是龙喉兽人。"
D.Strings[42348]="喔！我们有保镖了！"
D.Strings[42349]="做着英雄梦的凡人进入了破坏大厅。希望这次“袭击”能够比上次更精彩一点。"
D.Strings[42350]="嗯……“全能金刚防御系统”。几个世纪前，这些粗糙的魔像阵列组还被称为矮人技术的杰作，殊不知每个单独的魔像都能被轻易反制。我不得不亲自修正那些设计缺陷，才能让它们给我提供些娱乐。"
D.Strings[42351]="你想离它远点，是吗？太糟糕了。"
D.Strings[42352]="愚蠢的矮人，对符文愚蠢的痴迷！为什么你们要创造能够帮助敌人的东西？"
D.Strings[42353]="闪电导体对集群目标的效果更好，对吧？"
D.Strings[42354]="你打算使用剧毒金刚的化学能量摧毁其它魔像？聪明的计划。让我来帮你毁掉这个计划。"
D.Strings[42355]="我早该知道，名字这么蠢的东西多半娱乐不了多久。"
D.Strings[42356]="我在这个房间下方的熔岩里找到了这个奇妙的样本。对你们这支可怜的小团队来说，熔喉应该是个“适度”的挑战。"
D.Strings[42357]="转念一想，“适度”的挑战又有什么乐趣呢？"
D.Strings[42358]="你们赢了？真……令人失望啊。我本以为可以目送你们葬身于火海中。"
D.Strings[42359]="啊，奇美隆，这是我的科学力量的活证。我对他进行了多年的加工和改造，才有了现在这杰出的成果。"
D.Strings[42360]="哦，你们是否有些期待在战斗中出现一些变数？那么让我看看你们对“调整方案”的适应程度如何？"
D.Strings[42361]="立刻停止自相殴斗，奇美隆！"
D.Strings[42362]="这场战斗有一点乏味了，请让我给大家助助兴！"
D.Strings[42363]="失去这个实验品可真遗憾……"
D.Strings[42364]="马洛拉克，尽量别输给那些凡人。“半称职”的帮手可是很难创造的。"
D.Strings[42365]="你的混合剂太弱了，马洛拉克！他们需要更多的……“催化”！"
D.Strings[42366]="祝贺你们！为了嘉奖你们的惊人成就，请允许我授予你们一个合适的头衔。从今以后，你们就是“蠢货、无能者和饭桶喽罗的克星。”"
D.Strings[42367]="这么多美好的回忆，这么多丰厚的利润。我可不能袖手旁观。"
D.Strings[42368]="欢迎，蛮锤的朋友们！$B$B库斯海文是我们一族的精神核心。在这里，不同的部族会在和平中聚首。$B$B在这里，我们共同哀悼逝去的英雄，将他们和他们的狮鹫埋葬在雷霆山的顶端。让他们与天空融为一体，永垂不朽。"
D.Strings[42369]="你开始施放|cFFFF0000|Hspell:91317|h[膜拜]|h|r！"
D.Strings[42370]="艾卓曼德斯，难道你不光瞎了，还是聋子？快干掉他们！"
D.Strings[42371]="艾卓曼德斯，那些英雄就在那边！"
D.Strings[42372]="这些盾牌确实讨厌。"
D.Strings[42373]="你早就该被处理掉了。"
D.Strings[42374]="一场婚礼？如果这还不能把这些家伙聚集在一起，我就吃掉我的锤子！$B$B我们需要让这场婚礼无比隆重盛大，$n，我们需要你的帮助。有一句蛮锤的老话……让我想想……那句话是怎么说的？"
D.Strings[42375]="也许我们应该把敌人要的东西给他们……这样至少可以让我们的人民免受血腥屠杀。"
D.Strings[42376]="如果这就是他们想要的，也许我们可以避免一场战争，可以阻止血流成河的惨祸发生！"
D.Strings[42377]="我必须首先保护我的人民。我们的敌人已经将奥西斯埋葬在沙漠中。你怎么能和这样的力量作战？"
D.Strings[42378]="你的话没有错，兄弟……但即使是国王也不可能独自做出决定。我会让高阶议会对此事进行投票。"
D.Strings[42379]="婚礼就要开始了！我需要为这快乐的一对准备一件礼物。一件非常重要的礼物。$B$B蛮锤的未来完全系于这最后一个将我们团结在一起的机会！"
D.Strings[42380]="古加尔开始施展|cFF006EFD|Hspell:91303|h[变节]|h|r！"
D.Strings[42381]="希望你能重新考虑，法奥瑞斯。死亡之翼会使用节杖的力量，开启奥丹姆的秘密，制造恐怖异常的毁灭灾难。"
D.Strings[42382]="我们会战斗到死，法奥瑞斯！我们一族生来就是为了保卫这片土地。我们绝不会背叛我们的血脉传统。"
D.Strings[42383]="我服从你的智慧，兄长。让我们祈祷决定能尽快被做出。敌人是不会等待我们的。"
D.Strings[42384]="现在，你已经帮助我建立起了我的冰激凌帝国。请尽情享用我的诸多美味吧！"
D.Strings[42385]="你是来寻求帮助的？"
D.Strings[42386]="我……*咳嗽*我已经活了很长的时间，亲眼见过，亲手做过许多恐怖的事。"
D.Strings[42387]="那是些让我在长夜无法入眠的事情。"
D.Strings[42388]="对于我做过的那些事，我伤害过的那些人——我认识他们……我必须面对他们……带着我深深的自责。"
D.Strings[42389]="但那些被遗忘者。*咳嗽*他们是怎样做的？"
D.Strings[42390]="他们蹂躏这片土地，摧毁他们所触及的一切。他们卑劣的毒药夺走了多少生命？"
D.Strings[42391]="有多少无辜者倒在被遗忘者的战争机器下？"
D.Strings[42392]="数不清的……数不清的……*咳嗽*"
D.Strings[42393]="是的……我做过可怕的事情，但我从不曾与被遗忘者沆瀣一气。"
D.Strings[42394]="你去告诉那个不敢来见我的软骨头兽人，霜狼氏族不会帮助被遗忘者。永远不会！"
D.Strings[42395]="准备启动微型机动战鸡！"
D.Strings[42396]="别喊了，霍巴特，我就在这里。嘘！"
D.Strings[42397]="给你，一只“微型机动战鸡”。我一直都不明白，你是怎么想出这些怪名字的。"
D.Strings[42398]="你有许多事还不明白，我亲爱的格瑞里。正因为如此，你才是助手，而我……我是霍巴特·钩锤！"
D.Strings[42399]="格瑞里叹息着，眨了眨眼。"
D.Strings[42400]="是，钩锤博士。"
D.Strings[42401]="太好了。现在，离开超级凹陷裂变测试平台，向后退。一定要慢。"
D.Strings[42402]="谢谢你。现在，你可以看着我如何稳定这种极度不稳定的微型化处理程序。"
D.Strings[42403]="助手摇了摇头。"
D.Strings[42404]="这个发明将会一劳永逸地解决困扰锈水财阀的食物短缺问题，带来无尽的利润！"
D.Strings[42405]="我很快就会成为前无古人，后无来者的，最伟大的地精工匠！另外，那个导致海地精产生的疏忽根本不值一提。"
D.Strings[42406]="打开开关！"
D.Strings[42407]="格瑞里咳嗽了一声。"
D.Strings[42408]="呃，没错，霍巴特，一切都在你的掌控之中。"
D.Strings[42409]="非常正确的回答，格瑞里。你通过了今天的突击小测验。"
D.Strings[42410]="我我要打开开关了！"
D.Strings[42411]="格瑞里，你看到了吗？我已经成功在握了！"
D.Strings[42412]="全世界的杂货店主都要给我利润抽成！"
D.Strings[42413]="我要打开第二个开关了！"
D.Strings[42414]="等等……有问题！"
D.Strings[42415]="你在想什么？霍巴特，这只微型机动战鸡很不稳定。它在剧烈膨胀！"
D.Strings[42416]="我知道……我知道！超控开关？超控开关在哪儿？"
D.Strings[42417]="就是最右边的那个！赶快，霍巴特！它就要爆炸啦！"
D.Strings[42418]="我要按啦，格瑞里，我一直都是爱你的！"
D.Strings[42419]="按下超控开关！"
D.Strings[42420]="什么？！！！"
D.Strings[42421]="我们还活着吗？"
D.Strings[42422]="我们还活着，钩锤博士，全靠你的努力。"
D.Strings[42423]="当然，我亲爱的格瑞里。看看那个。微型机动战鸡的稳定性堪称完美！"
D.Strings[42424]="霍巴特的下巴撞到地上。"
D.Strings[42425]="你脸上那是鸡蛋吗？"
D.Strings[42426]="好了，告诉我，“你一直都是爱我的”是什么意思，钩锤？"
D.Strings[42427]="我根本不明白你在说什么，格瑞里小姐。"
D.Strings[42428]="在这一点上，我们可以达成共识，博士。"
D.Strings[42429]="嗨，你还好吗，老板？霍巴特和我正在努力确保当卡亚矿石资源枯竭时，你还会有足够的库存产品。$B$B现在矿脉中的卡亚矿石只有这么多了，如果它们都被开采干净，我害怕卡亚可乐也就没有了。"
D.Strings[42430]="很高兴见到你，$n！$B$B我刚想问你是否对我带到卡亚罗贸易公司的这些产品感到满意？$B$B包括但不限于：卡亚可乐、变鸡器、胶囊盒、巨怪愚行天才帽、卡亚罗全能训练机豪华版、神奇地精射线、永不漏气的小马泳圈、大炸弹、NX-01型自动化战士和海地精。别对最后一个有任何想法。我只是奉命办事，与我无关。$B$B不管怎样，我现在还在研究几样新鲜玩意，你也许会有兴趣——比如微型机动战鸡和一个被我命名为九号实验品的小东西。"
D.Strings[42431]="你看起来不太好，朋友。你肯定是出了什么问题。"
D.Strings[42432]="嗨，$g朋友:姑娘;我们来搞定这个？"
D.Strings[42433]="看样子，这就是最后了，如果你有足够的胆量，那我也就有，$n。"
D.Strings[42434]="水！"
D.Strings[42435]="<大胖看起来很凶悍，但可以确认，他心里是害怕了。>"
D.Strings[42436]="感谢圣光！我真是渴坏了！"
D.Strings[42437]="啊，你是我的救星，朋友！"
D.Strings[42438]="我觉得自己能喝下一整座湖！"
D.Strings[42439]="嗯……我的感觉不太好。"
D.Strings[42440]="真累啊……"
D.Strings[42441]="啊！喉咙里着火啦！"
D.Strings[42442]="啊……呃……"
D.Strings[42443]="嘿伙计！$b$b这地方经历了许多改变。可以通过传送去往别处。"
D.Strings[42444]="把我传送到回音群岛！"
D.Strings[42445]="把我传送到莫高雷！"
D.Strings[42446]="|TInterface\\Icons\\ability_mage_firestarter.blp:20|t使用|cFFFF0000|Hspell:74040|h[噬体烈焰]|h|r摧毁暮光之锤！"
D.Strings[42447]="|TInterface\\Icons\\spell_holy_innerfire.blp:20|t格拉布托克造成了一道移动的|cFFFF0000|Hspell:91398|h[火墙]|h|r!"
D.Strings[42448]="我要去医院！"
D.Strings[42449]="喂！走开！"
D.Strings[42450]="臭气熏天的脏蛮锤。这些矮人只把别人当作半个矮人，不是吗？你又是什么？一个侏儒？"
D.Strings[42451]="你说什么，萨莉？！我们之中像侏儒的只有你——等我把你砍成碎块之后，你就更像了！"
D.Strings[42452]="来吧，南希！我们走！"
D.Strings[42453]="我很忙，小子。为什么你不去找一池子被遗忘者的粘液，好好给自己洗个澡，嗯？"
D.Strings[42454]="那么，我猜这是真的了。我一直都不愿意相信，你竟然真的是个一肚子大便的白毛妖怪。但现在，我只能相信了。"
D.Strings[42455]="你叫我什么？好吧，那我就让你看看“白毛妖怪”能干些什么！"
D.Strings[42456]="渣胡？你只是个丑陋的小女孩。我还不知道他们会让小女孩也能成为死亡骑士。难道巫妖王这么着急扩充队伍吗？我要让你明白，你到底是个什么货色。"
D.Strings[42457]="离开这里，否则我就只能狠狠教训你了！"
D.Strings[42458]="哦，这一定会乐趣十足。"
D.Strings[42459]="我要让你明白，该把你的脑袋摆在什么地方！"
D.Strings[42460]="啊！你是怎么把鳄鱼干掉的？！"
D.Strings[42461]="奥弗很聪明！奥弗在你不注意的时候拿走了财宝！"
D.Strings[42462]="奥弗是老板了！哦耶！"
D.Strings[42463]="谁够坏！奥弗够坏！！呃！"
D.Strings[42464]="奥弗拿走了你的财宝。呃，呃，呃！"
D.Strings[42465]="我不和废物说话！"
D.Strings[42466]="你和我不是一伙儿的，甜心。"
D.Strings[42467]="我没有劝你回学校，现在我也不打算这么干。"
D.Strings[42468]="真有趣……我说的是你穿的这身“行头”。"
D.Strings[42469]="是的，我要再来一杯。快一点。"
D.Strings[42470]="这是贸易大王的聚会，甜心。只有受邀请的人才能参加！"
D.Strings[42471]="$n，是你吗？送你一句话：不要让贸易大王抓住你。他知道你在盯着他的位子。$B$B所有人都知道。"
D.Strings[42472]="蠢货？！我可不和如此无礼的人说话。你怎么敢这样！"
D.Strings[42473]="我们应该管你这种家伙叫什么？蛮子？巨怪？$B$B我可受不了你这种人。赶快离开这里。"
D.Strings[42474]="你又大又强壮。但你需要好好洗个澡。赶快跳到池子里去吧。"
D.Strings[42475]="哦，不，别和我说话！"
D.Strings[42476]="这里是什么气味？哦，是你啊。$B$B快给我躲远点！"
D.Strings[42477]="你的名字叫什么？$B$B也许你这种蛮子还是当个哑巴比较好。否则我就只能向贸易大王投诉，告诉他你是多么令我讨厌。$B$B现在，离我远一点！"
D.Strings[42478]="再碰我一下，我就让他们送你去安德麦！"
D.Strings[42479]="哦，你可真让人讨厌！为什么来找我的总是你这种丑家伙？！"
D.Strings[42480]="我有一种非常糟糕的感觉，$n。我觉得，你现在最聪明的选择就是想尽一切办法离开这座岛。$B$B让我看看能不能进入贸易大王的胶囊镇。"
D.Strings[42481]="把他们轰成碎片，老板！"
D.Strings[42482]="希望你已经准备好了！我已经改装好了这艘血精灵船。用的都是金币能买到的最好的地精零件……也许效果还不是很好，但我会竭尽全力的。"
D.Strings[42483]="比赛就要开始了！"
D.Strings[42484]="<令你惊讶的是，这头小迅猛龙似乎是想和你说话。>$B$B$G爸爸:妈妈;……？"
D.Strings[42485]="焰须，这是个大日子。蛮锤的团结不可阻挡！"
D.Strings[42486]="不必怀疑。给你，请接受我的结婚礼物。"
D.Strings[42487]="这是我的狮鹫斯卡雷唯一留存下来的蛋。请尊重它，爱护它。斯卡雷的孩子将成为你的伙伴。"
D.Strings[42488]="我不想听到这样的话。这颗蛋是你的。它代表了我对于我们之间盟约的忠诚。"
D.Strings[42489]="而如何效忠于联盟是蛮锤的事情！"
D.Strings[42490]="看啊，$n来了，还送来了你的新娘！"
D.Strings[42491]="希望你是对的，库德兰老朋友。"
D.Strings[42492]="库德兰……不，我不能！斯卡雷是一个传奇，我不能……"
D.Strings[42493]="谢谢你，库德兰。"
D.Strings[42494]="女士们，先生们，我们聚集在雷霆山下，共同见证范妮·桑德玛尔和科甘·焰须的结合。"
D.Strings[42495]="愿他们婚姻的誓言如同风、水、岩石和火焰一样，永生不息。"
D.Strings[42496]="科甘，范妮，你们是否愿意接受对方进入自己的生活，两个人成为一体，再不分开？"
D.Strings[42497]="那么，以我被赋予的权力……我被赋予的权力……"
D.Strings[42498]="……以鲜血和暗影！"
D.Strings[42499]="我将以主人的名义，吞噬你的生命！"
D.Strings[42500]="<令你惊讶的是，这头小迅猛龙似乎是想和你说话。>$B$B我饿……是的，我饿。"
D.Strings[42501]="<令你惊讶的是，这头小迅猛龙似乎是想和你说话。>$B$B“$c”是什么意思？你是地精族长吗？"
D.Strings[42502]="是他们中的一个！"
D.Strings[42503]="<令你惊讶的是，这头小迅猛龙似乎是想和你说话。>$B$B他们管你叫$n。这是你特有的名字吗，还是你的一个荣誉称号？"
D.Strings[42504]="停下来！"
D.Strings[42505]="哇！！"
D.Strings[42506]="拯救婚礼！"
D.Strings[42507]="<令你惊讶的是，这头小迅猛龙似乎是想和你说话。>$B$B你好，我刚从一颗蛋里爬出来。你呢？"
D.Strings[42508]="<令你惊讶的是，这头小迅猛龙似乎是想和你说话。>$B$B你真的要把你吃的肉烤熟吗？真奇怪。"
D.Strings[42509]="<令你惊讶的是，这头小迅猛龙似乎是想和你说话。>$B$B你没有戴头盔。这会让你的智力变弱吗？"
D.Strings[42510]="<令你惊讶的是，这头小迅猛龙似乎是想和你说话。>$B$B你的指头尖又圆又钝。所以你要用别的东西进行战斗吗？$B$B真是有趣。"
D.Strings[42511]="比赛就要开始了，$g小伙子:姑娘;！我们正在努力完成赛道的建造。而且我一直在忙着签下有能力的参赛者。$B$B多和你的朋友么说说我的需要吧！"
D.Strings[42512]="深渊中的毒蛇！来侍奉你们的主人！"
D.Strings[42513]="来吧，我的孩子们！保卫我！"
D.Strings[42514]="$n？！你还在这里干什么？$B$B你必须离开这座岛，否则就进入我的胶囊镇！$B$B别再耽误时间了，我的孩子！浩劫就要降临在我们头上了！"
D.Strings[42515]="我们必须离开这座岛！赶快，格瑞里，拿上那些图纸！还有我的牙刷！"
D.Strings[42516]="把一切都打好包！我们必须想办法离开科赞！我们会跳进离这里最近的一个胶囊镇！他们会把胶囊镇装进贸易大王的游艇。"
D.Strings[42517]="千万要提醒我带上我的巨怪愚行天才帽！"
D.Strings[42518]="死亡之翼？！大灾变？！我们完蛋了！！我们必须在卡亚罗山爆炸之前离开科赞！！！"
D.Strings[42519]="我们该怎样让九号实验品通过海关？我知道了！把她装进胶囊实验室！"
D.Strings[42520]="一个聚会？你能相信吗？整座岛都要爆炸了，他们却在进行聚会？！他们到底在想什么！！！"
D.Strings[42521]="没有时间把所有东西都收拾好了！只拿最重要的东西！我的防爆水下G射线护目镜哪里去了？！"
D.Strings[42522]="不必为霍巴特担心，老板。他只是有一点精神崩溃。$B$B对他来说，这场大灾变来得可以说非常不是时候。他就要完成微型机动战鸡的制造了。"
D.Strings[42523]="好的，博士。图纸，检查完毕。牙刷，检查完毕。"
D.Strings[42524]="我会的，我会的。但霍巴特，你必须先平静下来。你的血压已经很高了！你全身都变成深绿色了！"
D.Strings[42525]="嗯，我应该是在这里见过它，但你确定吗？那东西并不只是会将使用者的外形放大百分之五十，而是会把使用者变成怪物，然后还会让使用者爆炸！"
D.Strings[42526]="如果你不冷静下来，你就要爆炸了！难道你不认为这样会比较方便吗？当足球炸弹最终被踢进卡亚罗山，胜负已定的时候，那头龙恰好飞过天空。"
D.Strings[42527]="我会立刻做好胶囊实验室在艾萨拉展开的标记。我会把她的小软垫和她放在一起。她是那么聪明可爱！"
D.Strings[42528]="从技术上说，这是不现实的，博士。那是从卡亚罗山火山口中喷出的岩石，也就是火山喷出物，而不是天空。那些都是液化岩石和火山灰。它们会在降落时逐渐冷却，变成熔岩炸弹。这才是恰当的解释，不是吗？"
D.Strings[42529]="那是一场真正的聚会，而且我的确受到了邀请。为什么总是有意外发生，让我永远也无法走开？我应该好好喝上一杯的。"
D.Strings[42530]="霍巴特，你正戴着它呢。"
D.Strings[42531]="你能去掉它，对不对，麦格鲁德？！"
D.Strings[42532]="圣……这到底是什么？"
D.Strings[42533]="你在开玩笑吗？看看这东西！它里面一定有上百万根线。对我来说，三根线就已经足够了……"
D.Strings[42534]="快跑！！！！！！"
D.Strings[42535]="我还是小孩子的时候，我的父亲就已经在训练我该如何尊敬元素。大地和烈火，疾风和海洋——它们都具有无比强大的能量，$c。$B$B<格朗迪的眼睛里闪过一丝光芒。>$B$B那是你没有能力去认知的能量。"
D.Strings[42536]="我会时刻睁大双眼，格朗迪。让婚礼开始吧！"
D.Strings[42537]="LOK'TAR！希尔斯布莱德是我们的！"
D.Strings[42538]="格罗尔纳要吃东西！"
D.Strings[42539]="关于对抗尼斐塞特反叛部族的议案……高阶议会的成员有没有做出决定？"
D.Strings[42540]="看吧，哭泣吧。"
D.Strings[42541]="看到了吗？什么也无法阻挡我的战锤的力量。"
D.Strings[42542]="是的，陛下。拉穆卡恒之剑决议发动战争。您的军队已经整装待发。"
D.Strings[42543]="拉穆卡恒之声同样赞成发动战争。"
D.Strings[42544]="拉穆卡恒之心……弃权。"
D.Strings[42545]="连续几个小时，我一直在为那河中的水流带给我的幻象而苦恼。"
D.Strings[42546]="在我看到的影像中，与敌人的谈判为我的人民带来了短暂的和平……随后就是可怕的出卖和毁灭。"
D.Strings[42547]="只有一个影像让我看到了一丝希望。在那里面……高阶议会没有做出你想要的决议，法奥瑞斯。"
D.Strings[42548]="找到她了，$n……应许约柜！"
D.Strings[42549]="干得好，琼斯博士！"
D.Strings[42550]="你不仅让我找到了这个箱子，还去除了它的保护！"
D.Strings[42551]="真是可怜啊……"
D.Strings[42552]="我真的很想让你在我的组织中得到一个崇高的职位，而不是杀死你。"
D.Strings[42553]="但首先！"
D.Strings[42554]="你应该亲眼见证你所珍爱的东西被彻底摧毁！"
D.Strings[42555]="约柜？！你不能……"
D.Strings[42556]="哦，不要犯傻！我从没有想过要占有你的蠢箱子。"
D.Strings[42557]="那件宝物是唯一能阻止死亡之翼开启起源重组系统的东西！"
D.Strings[42558]="等到他的复仇欲望得到满足，我就能随心所欲地统治艾泽拉斯了！"
D.Strings[42559]="嗯？那是什么？"
D.Strings[42560]="没关系！再过一会儿，这东西就彻底不复存在了！"
D.Strings[42561]="闭上你的眼睛，孩子。这可不会很好看……"
D.Strings[42562]="现在！摧毁这只箱子！也将他们一同摧毁！"
D.Strings[42563]="在那里面……高阶议会没有做出你想要的决议，法奥瑞斯。"
D.Strings[42564]="但是战争，一场由不愿遵循协议的领袖发动的战争，会让我们的国家更快地灭亡。"
D.Strings[42565]="我是一名哲人。这意味着我比你更聪明。现在，离开吧，不要等我废黜你的时候再后悔。"
D.Strings[42566]="我的君主，不久之前，尼斐塞特边境发生了一场小规模冲突，一支由您的兄弟率领的巡逻队被卷入其中……"
D.Strings[42567]="他……受了重伤，陛下。"
D.Strings[42568]="我们在天亮时进攻尼斐塞特城。"
D.Strings[42569]="指挥官，让所有前锋军团向西移动。"
D.Strings[42570]="纳顿……"
D.Strings[42571]="啊！$b$b你来得正是时候。$b$b我已经等了你好几天了。$b$b竟然把一个老矮人丢在这个闷热的地方……就算是训练新兵也比这个好。"
D.Strings[42572]="炸弹已经放好了！赶快跑到阳台上，跳下去！"
D.Strings[42573]="灰影墓穴在这边，跟我来，$n。"
D.Strings[42574]="那么，那些物资会在哪里？"
D.Strings[42575]="也许它们就在这里？"
D.Strings[42576]="不，不在这里。"
D.Strings[42577]="嗨，帮我一把，$n！我找不到摩尔多需要的那些物资了！"
D.Strings[42578]="让我看看……它们会在……"
D.Strings[42579]="干得好！你找到它们了。我们把它们送到摩尔多那里去吧。"
D.Strings[42580]="我看到有人吃惊得下巴都掉下来了。不知道摩尔多能不能把他的下巴放回去？"
D.Strings[42581]="我们完了，$n！我现在和奇普在一起了。"
D.Strings[42582]="我们完了，$n！我现在和小甜甜在一起了。"
D.Strings[42583]="何必大费周章，其实你要做的只是……"
D.Strings[42584]="……砍一下而已！"
D.Strings[42585]="侵略者，你往哪里走！"
D.Strings[42586]="过街老鼠！"
D.Strings[42587]="不能释放希亚玛特！趁现在还来得及，回头吧！"
D.Strings[42588]="[泰坦语]Murkash!"
D.Strings[42589]="走路轻点。"
D.Strings[42590]="死神的晃动干扰了铸造控制装置！"
D.Strings[42591]="熔渣剧烈地沸腾着！"
D.Strings[42592]="救命！我被困住了！"
D.Strings[42593]="帮帮忙吧？"
D.Strings[42594]="呃，喔！他现在气急败坏了！"
D.Strings[42595]="干得好伙计们！钥匙应该就在他身体的某个地方。只要，呃，仔细找找，直到找到为止。"
D.Strings[42596]="谢谢你们救了我！我要踏上更为刺激的冒险之旅了。"
D.Strings[42597]="击打冰柱来挣脱束缚！"
D.Strings[42598]="从你被释放到现在，已经过去六个星期了。你准备好告别那双镣铐了吗？"
D.Strings[42599]="我需要时间来好好想一想。还太……太早了。"
D.Strings[42600]="六个星期？我在敦霍尔德待了整整六年！这玩意儿跟了我这么久，我怎么可能如此轻易就摆脱它！"
D.Strings[42601]="我想知道的是——我脚上绑着铁球和锁链，这关你什么事？！"
D.Strings[42602]="你就不能从我的角度想想吗，医生？为什么总是关于泰迪？"
D.Strings[42603]="不，该死！第一百次的回答还是不！"
D.Strings[42604]="等我死了，你就可以随便拿掉它。"
D.Strings[42605]="你知道吗，当我刚刚被抓住时，我恨透了泰迪。他钻进我的身体，让我不能自由移动。但我现在想告诉你的是——在共度六年之后，我必须承认，他已经成为我身体的一部分。"
D.Strings[42606]="我与德鲁尔同在，医生。我们在一起很快乐。为什么要拆散我们？"
D.Strings[42607]="离我远点儿，你这怪物！"
D.Strings[42608]="亡灵是艾泽拉斯的腐蚀之源！你们这些家伙都该被毁灭！"
D.Strings[42609]="而且我们不喜欢你把我们的朋友称作“铁球和锁链”，医生。"
D.Strings[42610]="不。你在撒谎！父亲会保护我的！"
D.Strings[42611]="如果可以的话，我宁可回去。我在敦霍尔德有自己的生活。其实我在那儿每个星期顶多挨一次打。"
D.Strings[42612]="我不是什么畸形的怪物，我只是个亡灵。我想和你谈谈。"
D.Strings[42613]="莉莉安，你有没有意识到自己也是个亡灵？"
D.Strings[42614]="坦白说，我对这些治疗环节感到有些厌倦了。我们健康得很！我们只想离开。"
D.Strings[42615]="我的官方诊断结果就是——你们简直是一对白痴！听到没有，白痴！"
D.Strings[42616]="退后，怪物。想打架吗？因为我就是来大打一场的。$b$b我会把你们这些怪物都打得落花流水！听懂了吗？"
D.Strings[42617]="喔，真的吗？$b$b好的。我不想与你和你的被遗忘者为伍。也许我会创造属于自己的被遗忘者！也许我会创造出肘部会动的被遗忘者！"
D.Strings[42618]="你叫谁怪物？你才是怪物！我只是个死去的正常人。"
D.Strings[42619]="我不是来打架的。我只是奉命前来与你交谈。"
D.Strings[42620]="你想做什么都可以。"
D.Strings[42621]="什么……发生什么事了？你是谁？我这是怎么了？"
D.Strings[42622]="我……死了？$b$b是的，你说得没错。我是死了。有个兽人……他切断了我的双手，任由我死去。$b$b<瓦德雷看着自己的手。>$b$b这不是我的手！这不是我的手！"
D.Strings[42623]="<瓦德雷看着自己的手。>$b$b我想这就是我的命。哈！成为亡灵大军的一员。我怎么也没想到，自己最终竟然会为被遗忘者战斗。$b$b<他抬头看着你。>$b$b我现在还有什么选择？"
D.Strings[42624]="我明白了。那好，我们开始吧，$n！黑暗女王需要我们，对吗？"
D.Strings[42625]="你不记得了吗？你死了。"
D.Strings[42626]="别激动，瓦德雷。这可能是送葬者摩尔多为你缝上的新手。"
D.Strings[42627]="你去问送葬者摩尔多。他会告诉你该怎么做。我知道的就这么多。"
D.Strings[42628]="这是你的大型见面会。我们要让你成为贸易大王，$n！$B$B出去显示你的权威吧！"
D.Strings[42629]="海盗？！你得来解决一下，长官！他们正在毁掉派对！"
D.Strings[42630]="抓紧了。飞艇将在片刻之后抵达。"
D.Strings[42631]="呸，不出所料！他们会看到的！"
D.Strings[42632]="马上就要到了。做好准备！"
D.Strings[42633]="这看起来可不怎么样，长官。"
D.Strings[42634]="她来了！准备好火炮，该死！随时开火！"
D.Strings[42635]="老板，我们会想尽一切办法为你集齐一万亿杏仁币的！"
D.Strings[42636]="我们得尽快结束这里的事情，把你送到码头，趁贸易大王还没把我们大家甩在身后！"
D.Strings[42637]="嗨，宝贝儿。呃……我们得谈谈，不过不是现在。$B$B好吗？"
D.Strings[42638]="喔，嗨，宝贝儿。对……我们得谈谈。$B$B稍后好吗？"
D.Strings[42639]="市场营销搞得再好也没办法把我们从这座岛上弄出去。我们唯一的希望就是弄到一万亿杏仁币！$B$B你最好赶紧弄到那笔钱并且送到码头去！"
D.Strings[42640]="收割他们！$n与我们同在——胜利毫无悬念！"
D.Strings[42641]="他派来个懦夫想要干掉我，是不是？"
D.Strings[42642]="趁我还站在这儿，赶快动手……"
D.Strings[42643]="你不记得我了吗？我们都曾是银松森林中阿鲁高的仆从。多年来一直忍受着他惨无人道的折磨。在改变命运的那一晚——我们从影牙城堡中逃离，是你救了我。如果没有你，我早就死了。是你！我所认识的最高贵的狼人！他们对你做了什么，$n？这怎么可能？"
D.Strings[42644]="啊，我的背！"
D.Strings[42645]="记得你曾经是个多么伟大的狼人，$g兄弟:姐妹;！你是我们的救星！奋力战斗！"
D.Strings[42646]="已经……已经来不及了。我完了。结束我吧，$n。否则他们会把我们俩都杀死。$n……记住吉尔尼斯，我们挚爱的家园。这个世界值得我们去拯救。"
D.Strings[42647]="我们……我们不能想想办法吗？"
D.Strings[42648]="好，让我……让我……站……起来。"
D.Strings[42649]="你不记得我了吗，$n？你我在科赞共度的那段日子里，我丢掉了一份又一份工作。后来我还染上了爱喝卡亚可乐的瘾，是你救了我！是你把我带到卡利姆多，加入了热砂集团。你是我所见过唯一善良的地精。正是出于对你的了解，我才落入银色黎明手中。你怎么会变成这样？"
D.Strings[42650]="记得你曾经是个多么伟大的地精，$g兄弟:姐妹;！你曾是我最好的朋友！奋力战斗！"
D.Strings[42651]="已经……已经来不及了。我完了。结束我吧，$n。否则他们会把我们俩都杀死。$n……记住科赞，我们挚爱的家园。这个世界值得我们去拯救。"
D.Strings[42652]="尖喙！到这儿来，尖喙！"
D.Strings[42653]="啊，别怕尖喙。那只不过是个大大的……触手。东尼利会保护我们的！"
D.Strings[42654]="别怕，尖喙。回到这儿来！"
D.Strings[42655]="你安全了，尖喙。到东尼利这儿来！"
D.Strings[42656]="尖喙。尖喙！"
D.Strings[42657]="我爱你伙计……（嗝儿）如同兄长！"
D.Strings[42658]="你很好，焰须。（嗝儿）我喜欢你。"
D.Strings[42659]="我们蛮锤部族缔结百年之好……正像那样。（嗝儿）简直太美了！"
D.Strings[42660]="（嗝儿）你和我，焰须。蛮锤情谊永存。"
D.Strings[42661]="无与伦比的！婚礼！（嗝儿）"
D.Strings[42662]="蛮锤朝夕共度，比肩杀敌！"
D.Strings[42663]="暮光之锤吓不倒我。尽管来吧！"
D.Strings[42664]="蛮——锤！"
D.Strings[42665]="抓住它！杀了它！"
D.Strings[42666]="等你准备好，就可以开始了！我会紧跟新郎新娘，以防暮光之锤有任何图谋。$B$B你准备好了吗？"
D.Strings[42667]="黑暗法老倒下了！他那不朽的巨像犹如玩具一般地打着滚！"
D.Strings[42668]="尼斐塞特城将要陷落！攻击！！！"
D.Strings[42669]="炸弹即将爆炸！都让开！"
D.Strings[42670]="瓦德雷·莫莱前来报到，长官！"
D.Strings[42671]="一大波僵尸正在靠近！"
D.Strings[42672]="终于有人帮我除掉了那只丑陋的害虫！向你致敬，“英雄”们。"
D.Strings[42673]="这下不用再为那堆垃圾付修理费了。"
D.Strings[42674]="这次可真有点过分了。"
D.Strings[42675]="了不起。你们毁掉了我最恐怖的造物之一。我原以为这是不可能的。"
D.Strings[42676]="我们总是意见不合……终于摆脱他了！"
D.Strings[42677]="欢迎来到我的私家圣殿，英雄们！希望你们能有宾至如归的感觉。你们能在这里见到许多我的失败实验品，但最终将见证我最伟大的胜利！"
D.Strings[42678]="见证龙巢之母——奥妮克希亚的重生！这也许是我最高的杰作。"
D.Strings[42679]="我最亲爱的妹妹，你饿了吗？那就吃掉我们的敌人吧！"
D.Strings[42680]="暗影烈焰为他们的骨骼注入了活力！他们为我而战！"
D.Strings[42681]="血肉化为灰烬！"
D.Strings[42682]="诅咒你们，凡人！你们丝毫不尊重他人财产的行为必须受到严厉处罚！"
D.Strings[42683]="希望你会游泳……在岩浆里！"
D.Strings[42684]="我一直在尝试扮演好客的主人，可你们就是不肯受死！该卸下伪装了……杀光你们！"
D.Strings[42685]="凡人的心智……真是容易控制。"
D.Strings[42686]="真是令人愉快！"
D.Strings[42687]="你真的只能接受。"
D.Strings[42688]="失败的滋味从未如此苦涩……"
D.Strings[42689]="多谢你们专程赶来，但你们现在真的都该死了！"
D.Strings[42690]="凡人，我希望你能见证这一切，不过为了你的安全，站远一点。凯伦，你也是。"
D.Strings[42691]="不要浪费你的生命，凯伦。一旦我失败，那么世界的命运将落在你的肩上。"
D.Strings[42692]="这令我痛苦，奈萨里奥——但我必须终结你，就像我终结玛里苟斯一样。"
D.Strings[42693]="曾经的伟大盟友只剩这具空洞的金属躯壳，真是浪费泰坦的恩赐。"
D.Strings[42694]="奈萨里奥！看看你自己。残缺。扭曲。你已支离破碎。"
D.Strings[42695]="大地的守卫者……他死了。"
D.Strings[42696]="黑龙守护者之血受到了诅咒。但凡所溅之处，一万年都长不出任何东西。"
D.Strings[42697]="阿莱克丝塔萨痛苦的喘息着。"
D.Strings[42698]="但是都结束了，终于可以将他带来的恐惧尘封起来了。"
D.Strings[42699]="凯伦，不！"
D.Strings[42700]="生命的缚誓者！你以为我会听从你的号令？世界正待我毁灭。"
D.Strings[42701]="“终结”我？生命的缚誓者，你认为你能取走生命？"
D.Strings[42702]="那么见证我的新力量，来自世界真主的恩赐！"
D.Strings[42703]="如同生命终将归于死亡……秩序终将归于混沌……来吧！拥抱不可违抗的宿命！"
D.Strings[42704]="凡人世界的夕阳已经落幕，平静接受你的末日，暮光的时刻来临了。"
D.Strings[42705]="你妄想困住我！？"
D.Strings[42706]="我不会离你而去。"
D.Strings[42707]="是的，母亲。"
D.Strings[42708]="别让他们离开视线！快——跟着我！"
D.Strings[42709]="那边——他们落下去了！"
D.Strings[42710]="母亲，请别动。你伤得很重。"
D.Strings[42711]="死亡之翼——他还活着！"
D.Strings[42712]="凡人，带上红龙女王，送她去安全的地方。现在！快跑！把她从这里带走！"
D.Strings[42713]="我来拖住死亡的化身。带她去安全的地方。快走！"
D.Strings[42714]="我知道通往丧钟镇的路。跟我来！"
D.Strings[42715]="很好，你还在。亡灵卫兵萨尔坦在哪儿？"
D.Strings[42716]="啊，他在这儿呢。"
D.Strings[42717]="我们动身吧，$n。萨尔坦说我们会撞见一些尸体。"
D.Strings[42718]="我想我在前方看见了一些尸体。走吧，$n！你负责搜寻和战斗。体力活儿交给我。"
D.Strings[42719]="认为你已经有能力应对艾泽拉斯地下城的挑战了？入内查究……"
D.Strings[42720]="我想看看你的货物，雅斯敏。"
D.Strings[42721]="哦可怜的小家伙，你从头到脚都裹满了沙子！在这片美丽的绿洲好好休息，恢复下体力吧。"
D.Strings[42722]="阿莱克丝塔萨很快就会到来。来吧，让我们做好准备。"
D.Strings[42723]="为殒落已久的生命燃起烈焰，他们的魂灵与所有鲜活的生命同在。"
D.Strings[42724]="为即将降临的生命燃起烈焰，懵懂的灵魂在母体中苏醒。"
D.Strings[42725]="为新诞的生命燃起烈焰，青春盛放的热情与蓬勃不息的活力。"
D.Strings[42726]="为正值盛年的生命燃起烈焰，奋力缔造和重塑这个世界。"
D.Strings[42727]="为即将凋零的生命燃起烈焰，他们的使命也许将要完成，但他们的贡献却会成为永恒。"
D.Strings[42728]="生命的循环已经完成。一切都已就绪。"
D.Strings[42729]="啊——阿莱克丝塔萨来了。"
D.Strings[42730]="嗯……我不记得该走哪条路了。我们试试这边吧！"
D.Strings[42731]="啊！这好像是死路。我们走另一条路试试看。"
D.Strings[42732]="嗯……这楼梯看起来也不怎么靠谱。我们返回庭院，研究下是否还有别的路可走。"
D.Strings[42733]="总算有进展了！走这条路肯定能出去。不过看来有不少卫兵在把守，我迫切需要你的帮助！"
D.Strings[42734]="从舱门上方传来一阵响声！"
D.Strings[42735]="你知道，我已经等了很久了。"
D.Strings[42736]="等待属于我的时机，建立我的军队，分析敌人的心理。"
D.Strings[42737]="肉搏战从来不是我的强项。我和我父亲不同。"
D.Strings[42738]="但我总是擅于施毒。"
D.Strings[42739]="尤其是影响心智的剧毒。"
D.Strings[42740]="情况怎么样？"
D.Strings[42741]="梵妮莎向你体内注入了噩梦药剂！"
D.Strings[42742]="首先，你如入无人之境般地擅自闯入奥丹姆……"
D.Strings[42743]="笨手笨脚地给我添乱……"
D.Strings[42744]="然后无情地杀死了我忠诚的仆从……"
D.Strings[42745]="把那个俾格米关起来！"
D.Strings[42746]="抱歉，我必须要给一个龙宝宝接上断腿。你能过几分钟再回来吗？"
D.Strings[42747]="没有但是！安静！继续前进！"
D.Strings[42748]="如果那些理由还不够的话，你还破坏了我的仪式，害哥培尔送了命！"
D.Strings[42749]="最后，最重要的是——你差点儿夺走了我的生命……我的！"
D.Strings[42750]="你应该感到庆幸，我没有时间让你为自己所犯下的罪行而饱受折磨。"
D.Strings[42751]="已经够远了！"
D.Strings[42752]="接下来我自己能行了，朋友。去把问题已经解决的消息报告给你的主人吧。"
D.Strings[42753]="告诉他，不会再受到干扰。"
D.Strings[42754]="最好不会再有，司克诺兹。死亡之翼的耐心就快消磨殆尽了。"
D.Strings[42755]="那么，我们是在哪儿？"
D.Strings[42756]="啊，是的。还有什么话要说吗？嗯？"
D.Strings[42757]="什——么？！这是什么意思？"
D.Strings[42758]="你还好吧，$n？"
D.Strings[42759]="躲开，司克诺兹！"
D.Strings[42760]="我明白，阿莱克丝塔萨已经对死亡之翼做出了判决。也许这场磨难终将在这里结束？"
D.Strings[42761]="我准备好面对死亡之翼了！"
D.Strings[42762]="应该能行！"
D.Strings[42763]="你看看那……"
D.Strings[42764]="布莱恩？！什么？！怎么会……"
D.Strings[42765]="嗷呦！来吧，你这家伙……"
D.Strings[42766]="消灭那——等等……那是什么？！"
D.Strings[42767]="啊哈！终于呼吸到新鲜空气了！"
D.Strings[42768]="又比你早了两步，小子！一如既往。"
D.Strings[42769]="最好小心点儿，小伙子！下一次也许就没那么幸运正巧被我赶上了。"
D.Strings[42770]="你能帮我出去吗？没理由闲着不动，我们走吧！"
D.Strings[42771]="我不记得通向出口的路了。我们试试这条路。"
D.Strings[42772]="啊！这好像是死路。尽管这张床看上去无比舒适。我们走另一条路看看。"
D.Strings[42773]="这里看上去真是陌生。我们返回庭院吧，看看还有没有其它出路。我打从心底厌恶长长的楼梯。"
D.Strings[42774]="好了，一定是这条路。那边有几个守卫，多加小心。"
D.Strings[42775]="谢谢你，$n，我想我能骑上匹马，一径返回营地去。真是多亏了你的帮助。"
D.Strings[42776]="回头见，$n！别迟到！"
D.Strings[42777]="来吧……让我们瞧瞧。"
D.Strings[42778]="好吧，$r。$b$b看起来一切都还不错。"
D.Strings[42779]="我准备好了，布莱恩。去开启那个箱子吧。"
D.Strings[42780]="呦，看看谁来了！"
D.Strings[42781]="你好，$n！你觉得我的新装备怎么样？"
D.Strings[42782]="他们想让我当个亡灵卫兵。你能相信吗？"
D.Strings[42783]="我也许会留在丧钟镇。如果一切顺利的话……谁知道呢？或许我会见到黑暗女王本人。"
D.Strings[42784]="你呢？我听说萨维斯准备派你前往卡尔斯通庄园。重要任务，对吧？"
D.Strings[42785]="嗯，快去做你的事吧。很高兴认识你，$n。希望我们很快就能再见面。"
D.Strings[42786]="%s召唤暮光幼龙来协助他！"
D.Strings[42787]="我会留下，想办法释放这些蜘蛛。谢谢你的帮助，$n。"
D.Strings[42788]="你是来帮忙的，$c？让我们暂时待在一起。"
D.Strings[42789]="你承受住了攻击！$B岩石坚果已解锁！"
D.Strings[42790]="教学已完成！$B你已解锁向日葵。"
D.Strings[42791]="用这卷爆破胶带把那些故障阀门封紧，酋长。"
D.Strings[42792]="再坚持几分钟……塞纳留斯就快到了！"
D.Strings[42793]="你也许没那么多时间。敌人的援军正在赶来。"
D.Strings[42794]="戈德林！看来是真的……远古之神又再次出现在我们身边！"
D.Strings[42795]="在中间那条路上不断放置喷酸草来阻击僵尸。"
D.Strings[42796]="收集太阳能并在中间那条路上放置喷酸草以抗击僵尸！"
D.Strings[42797]="以后再庆祝吧，指挥官。暮光巨龙正在逼近！"
D.Strings[42798]="内部：50%僵尸大军已抵达。"
D.Strings[42799]="内部：50%食尸鬼大军已抵达。"
D.Strings[42800]="内部：50%畸变怪大军已抵达。"
D.Strings[42801]="你们俩所缺少的……"
D.Strings[42802]="……是控制。"
D.Strings[42803]="种植向日葵以生成额外的太阳能，这将帮你抵挡僵尸的攻击。"
D.Strings[42804]="种植3株以上的向日葵来确保完成任务。"
D.Strings[42805]="%s召唤了一个|cFFFF0000无面腐蚀者|r！"
D.Strings[42806]="欢迎来到坠星村，旅者。你是来帮助我们的吗？"
D.Strings[42807]="肮脏的野兽！你们出现在天空之墙的行为是不可饶恕的！"
D.Strings[42808]="毁灭吧！"
D.Strings[42809]="你胆敢凌驾于神圣之上！云巅没有凡人的位置。"
D.Strings[42810]="奥拉基尔，你的仆从请求你的帮助！"
D.Strings[42811]="我将随风而去！"
D.Strings[42812]="我家几代人都是除虫高手！尽管我们只是普通的雇佣劳工……"
D.Strings[42813]="%s开始追赶$n！"
D.Strings[42814]="古加尔老板可不会喜欢这样！"
D.Strings[42815]="这就是你的下场！死吧！"
D.Strings[42816]="罗姆欧格很抱歉……"
D.Strings[42817]="拉兹很厉害！"
D.Strings[42818]="拉兹……累了……"
D.Strings[42819]="异教徒！你要为你的罪行受到惩罚！"
D.Strings[42820]="使你获得真理启迪的途径只有一条，那就是死亡！"
D.Strings[42821]="浸沐在主人的力量中！化作主人怒火的使徒！"
D.Strings[42822]="为了主人，我万死不辞，万死……"
D.Strings[42823]="又能测试我的武器了！"
D.Strings[42824]="不过是合金中的杂质……"
D.Strings[42825]="感受这灼热吧！"
D.Strings[42826]="我们的同伴无穷无尽！你只是在白费力气……"
D.Strings[42827]="你们来寻找答案吗？来吧！用你们的生命来索求吧！"
D.Strings[42828]="主人的世界中没有你们的位置。"
D.Strings[42829]="大地可以被重铸……你们却不能！你们毫无价值！"
D.Strings[42830]="我不会被毁灭……你们……只是在拖延……"
D.Strings[42831]="拉兹，不——！"
D.Strings[42832]="快！别让他们打断伊瑟拉施法！"
D.Strings[42833]="尽全力多拖住一会儿！"
D.Strings[42834]="用岩石坚果保护喷酸草和向日葵。"
D.Strings[42835]="虚空抽吸着你的灵魂。它心满意足地慢慢享用着。"
D.Strings[42836]="当我们被罗姆欧格伏击时，他用锁链将拉兹困住，然后用|cff71d5ff|Hspell:75543|h[碎颅]|h|r攻击他！幸好我在被他最后一击命中前走开了！"
D.Strings[42837]="在那沉没的城市里，他陷入梦境。"
D.Strings[42838]="所有的地方，所有的事物都有灵魂。所有的灵魂都能被吞噬。"
D.Strings[42839]="在真实与虚幻之间没有明确的分界线。"
D.Strings[42840]="在尼奥罗萨的土地上，只有沉睡。"
D.Strings[42841]="你在沉睡时做梦吗，或者是一种对现实恐惧的逃避？"
D.Strings[42842]="在沉睡之城尼奥罗萨中，只有疯狂在徘徊。"
D.Strings[42843]="小马泳圈出现得太及时了！"
D.Strings[42844]="我差点儿就淹死了！"
D.Strings[42845]="在林区深处静静沉睡与凝望着的房屋常常陷入梦境。把它们拆除无疑是善举。"
D.Strings[42846]="是时候了！你知道我已经在这儿踩了多久水了？"
D.Strings[42847]="辰星可驱散彻骨的寒意，让人们不会在黑暗中战栗。"
D.Strings[42848]="有了小马泳圈，我就能回去了。"
D.Strings[42849]="在尼奥罗萨这座城市中充满着不计其数的古老而又可怖的罪行。"
D.Strings[42850]="就连死神也会死亡。"
D.Strings[42851]="谢谢你，朋友。我的火箭跳失败了。"
D.Strings[42852]="你可真是个奇迹般的劳动者，$n！"
D.Strings[42853]="你们最后都将是孤身一人。"
D.Strings[42854]="那溺死之神的心有如黑冰。"
D.Strings[42855]="在那幽暗的密林里有一只迷途的小羊羔。"
D.Strings[42856]="巨鸦警惕的目光在枯木间游移。在他的阴影之下，听闻不到半点儿气息。"
D.Strings[42857]="你又做同样的梦了？长着七只眼睛的黑羊从外面投来炯炯的目光。"
D.Strings[42858]="看看你的周围。他们全都会背叛你。尖叫着逃进漆黑的森林。"
D.Strings[42859]="在深邃的洋底，就连圣光也必将熄灭。"
D.Strings[42860]="打开我！打开我！打开我！然后你才能获知平静的意义。"
D.Strings[42861]="你获得了窒息藤种子！"
D.Strings[42862]="鱼群知道所有的秘密。它们熟知寒冷。它们熟知黑暗。"
D.Strings[42863]="它就站在你身后。不要移动。不要呼吸。"
D.Strings[42864]="先祖们饱受折磨的灵魂紧攫住你，无声地尖啸着。他们显然数量众多。"
D.Strings[42865]="什么能改变一个人的本性？"
D.Strings[42866]="一只食尸鬼把什么东西丢到了地上！"
D.Strings[42867]="你顽强抗拒。你紧抓住自己的生命，仿佛真能改变一切。你会了解的。"
D.Strings[42868]="软弱，短暂，易碎，生命必将终结。"
D.Strings[42869]="死亡才是终途，死亡才是永恒，死亡……是我的领域。"
D.Strings[42870]="面对我，面对死亡的化身，世界的毁灭者！"
D.Strings[42871]="恭喜你，冒险者。"
D.Strings[42872]="继续阅读……<注意：这将使梵妮莎注意到你的存在！>"
D.Strings[42873]="你已经径直走进了我的陷阱！"
D.Strings[42874]="你简直是炸弹狂人，$n！"
D.Strings[42875]="我有许多应急小马泳圈，$n。把它们扔给水中的劳工们。"
D.Strings[42876]="$n，卡拉兹工坊的救星！"
D.Strings[42877]="%s向你点头致意。"
D.Strings[42878]="好吧！跟我走！"
D.Strings[42879]="我不会游泳！"
D.Strings[42880]="我要淹死了！救命！"
D.Strings[42881]="起源大厅就在东面，靠近塔纳利斯沙漠。要走一阵子才能到，所以我们最好尽快动身。"
D.Strings[42882]="鲨鱼！！！"
D.Strings[42883]="那……没必要了。"
D.Strings[42884]="我太累了……"
D.Strings[42885]="要是我没忘记穿上标准型紧急救生衣就好了。"
D.Strings[42886]="嘿，说你呢！帮帮忙！"
D.Strings[42887]="一张便笺掉在了地上！"
D.Strings[42888]="我被困住太久了，到现在仍然感到腰酸背痛。要是我动作有些慢的话，请原谅……"
D.Strings[42889]="跟紧了！你永远不会知道死亡之翼的爪牙会什么时候突然冲出来，让我们的行动提早夭折！"
D.Strings[42890]="这可真是长途跋涉，不过如果我们能不受干扰的话，应该能在天黑以前到达目的地。你身上带吃的了吗？"
D.Strings[42891]="我简直是在拖你后腿啊，$g小伙子:小姑娘;！这么慢的步伐……真是逗人发笑！"
D.Strings[42892]="你继续前进。等我破解了这些磁盘，就去与你会合。"
D.Strings[42893]="你可以在奥达希尔找到训练师，$n。"
D.Strings[42894]="黑丝洞就在北面。多加小心，那里近来危机四伏。"
D.Strings[42895]="月亮井在东北面，在水池另一侧的山上。"
D.Strings[42896]="通往奥达希尔的梯道就在那边。盘旋而上就能找到特纳隆。"
D.Strings[42897]="埃沃隆身上的毒素已经散去，但还需要一些时间才能复原。"
D.Strings[42898]="腐坏的种子已深植在他体内。"
D.Strings[42899]="他们当然已是无可挽回，但看着他们死去，还是令人感到心如刀绞。"
D.Strings[42900]="我亲爱的朋友们……我很抱歉……"
D.Strings[42901]="他的躯体在渴求死亡，可他的灵魂却在渴求怜悯。"
D.Strings[42902]="腐化的程度远非这些蜘蛛力量能及。我担心真正的源头并不在这洞穴之中。"
D.Strings[42903]="我为我们犯下的这些罪行而哭泣。简直令人难以忍受。"
D.Strings[42904]="如此程度的腐化不可能源自外部。"
D.Strings[42905]="他体内的腐化仿佛是与生俱来的。"
D.Strings[42906]="我已经没有新东西要教你了。现在继续向东，前往治愈者营地吧。当安多哈尔之战打响之时，你将受到召唤。希望库尔迪拉没有等太久……"
D.Strings[42907]="你成功抵御了敌人的攻势！$B南瓜炸弹已解锁！"
D.Strings[42908]="打开气阀来释放你自己！"
D.Strings[42909]="抱歉，女猎手。我们的新$c都还没准备好。他们还有许多东西要学。"
D.Strings[42910]="恐怕我们并没有时间优势，伊尔萨莱恩。如果我们不尽快开始行动，就连泰达希尔也将难逃战火的席卷。"
D.Strings[42911]="我们会让你继续你的训练，伊尔萨莱恩。在这方面你才是行家。"
D.Strings[42912]="好好学习吧，$n。在下个月满之夜到来之前，我们可能会需要你协同作战。"
D.Strings[42913]="一只僵尸把什么东西丢到了地上！"
D.Strings[42914]="你获得了冻结草种子！"
D.Strings[42915]="我们成功了！控制室被攻破了！"
D.Strings[42916]="我们走！这下应该用不了多少时间了……"
D.Strings[42917]="塞纳留斯！太棒了！传送门一旦激活，我们就能畅通无阻地把军队送往前线。"
D.Strings[42918]="你是这里最受欢迎的人，玛诺恩之子！我们必须保存你的力量，以使你能率领先头部队攻击炎魔之王。"
D.Strings[42919]="交给我吧。"
D.Strings[42920]="僵尸吃掉了你的脑子！"
D.Strings[42921]="$n，把这群蛮锤渣滓赶出我的机场！"
D.Strings[42922]="我听说多亏了你的帮助，我才得到了治愈。谢谢你。衷心地向你表示感谢。"
D.Strings[42923]="那些暮光巨龙呢？从源头还会涌来更多。"
D.Strings[42924]="这个图腾正在腐蚀这些蛋！这后面很可能隐藏着一个更加巨大的威胁。瘤背一族仍然在遭受某种极端邪恶的污染。"
D.Strings[42925]="我们要做的，就是部署卡拉兹工坊微型机场，然后开始例行考察任务。$B$B我被白痴包围了！"
D.Strings[42926]="赫格拉姆！"
D.Strings[42927]="羞愧才是你显得愚蠢的唯一缘由，尼卡……"
D.Strings[42928]="你曾经告诉我，我们该如何变得坚强……你是如何无法负担软弱的代价……"
D.Strings[42929]="不论你有多坚强，你在我的臂弯中却始终软弱。"
D.Strings[42930]="坚强些，尼卡。我会注视着你……"
D.Strings[42931]="噩梦药剂发挥了作用！"
D.Strings[42932]="你已进入格拉布托克的噩梦！"
D.Strings[42933]="噩梦变换了！"
D.Strings[42934]="你进入了赫利克斯的噩梦！"
D.Strings[42935]="你已进入机械噩梦！"
D.Strings[42936]="你已进入撕心狼的噩梦！"
D.Strings[42937]="拯救艾玛·哈林顿！"
D.Strings[42938]="拯救埃里克·哈林顿！"
D.Strings[42939]="拯救卡莉莎·哈林顿！"
D.Strings[42940]="噩梦药剂的效果消退了！"
D.Strings[42941]="可怜的格拉布托克。他每次施法都会烧掉自己的住处。"
D.Strings[42942]="在他的灵魂深处，令他最为惧怕的就是……他自己。"
D.Strings[42943]="你在找寻什么，$r？知识？金钱？还是荣耀？$b$b对我而言，我总是希望能够进一步洞悉奥法艺术的真义。我对知识的渴求，已驱使我无数次地环游艾泽拉斯，而每一次我都会对这个世界上所蕴藏的神秘魔法有新的了解。$b$b逗你玩呢！其实我就是为了钱。"
D.Strings[42944]="你准备好离开荆棘谷了吗？"
D.Strings[42945]="是的。请准备传送吧，艾尔曼。"
D.Strings[42946]="我奉命前来调查藏宝海湾近来出现的怪事。这座地精之城出人意料地经受住了一场巨大海啸的考验，鉴于其以地精工程学而著称的美名，这就更加令人觉得不可思议。没想到这地方居然没有被巨浪冲垮。$b$b我怀疑在这里有什么魔法力量在作怪。你对藏宝海湾的了解也许远远不够，$c……"
D.Strings[42947]="是的。请准备传送吧，伊拉利尔。"
D.Strings[42948]="许多盗贼喜欢把自己藏在阴影中，赫利克斯是个例外。"
D.Strings[42949]="你永远不知道黑暗中潜藏着什么。"
D.Strings[42950]="你能想象一台机器的生命吗？"
D.Strings[42951]="一个小小的火花就决定了生……或是死。"
D.Strings[42952]="一切都失败了。请原谅我，我的女王……"
D.Strings[42953]="生命之火，在我体内燃烧吧，重焕我的活力！"
D.Strings[42954]="死亡之翼！我失败了……血脉……保不住了。"
D.Strings[42955]="灌注在巢群中的力量将由我自己收回！"
D.Strings[42956]="我为黑暗女王效命！"
D.Strings[42957]="我听凭你的调遣。"
D.Strings[42958]="为了被遗忘者！"
D.Strings[42959]="我……我不明白……"
D.Strings[42960]="来吧，暮光之子！"
D.Strings[42961]="你们的母亲在召唤！"
D.Strings[42962]="你变得虚弱了，辛萨尼亚。接受你注定的败局吧。"
D.Strings[42963]="你是谁？发生了什么事？"
D.Strings[42964]="撕心狼并非天生凶残嗜杀。他甚至拥有过自己的家庭。"
D.Strings[42965]="我这是在哪儿？"
D.Strings[42966]="他曾被称作詹姆斯·哈林顿。悲剧的三部曲。"
D.Strings[42967]="哎呦！$b$b怎么就不能顺利一次？！"
D.Strings[42968]="用南瓜炸弹击败大批僵尸或弱化更强大敌人的战斗力。"
D.Strings[42969]="我不会重蹈父亲的覆辙！你的传说就此终结！"
D.Strings[42970]="这只是第一个。"
D.Strings[42971]="你真以为我会只身一人前来作战？"
D.Strings[42972]="蠢货！整艘船上都布满了炸药！在烈焰中去见死神吧！"
D.Strings[42973]="我就算是死，也要拖上你们所有人！"
D.Strings[42974]="够了！你休想亲手杀死我！"
D.Strings[42975]="我的命运属于我自己！"
D.Strings[42976]="梵妮莎引爆了船上的炸药！快去抓住船侧的绳索！"
D.Strings[42977]="梵妮莎正在引爆更多的炸药！快去抓住船侧的绳索！"
D.Strings[42978]="梵妮莎要引爆最后一桶炸药了！跑啊！"
D.Strings[42979]="死亡之翼胜利了！等阿莱克丝塔萨复原后再次尝试吧。"
D.Strings[42980]="还没为阿莱克丝塔萨准备好生命循环。等我准备就绪后，再来和我交谈。"
D.Strings[42981]="阿莱克丝塔萨已经在和死亡之翼交战了！如果你动作够快，也许还来得及帮忙！"
D.Strings[42982]="卡莉莎……我很抱歉……"
D.Strings[42983]="詹姆斯……拜托……我爱你……"
D.Strings[42984]="卡莉莎快要死了！"
D.Strings[42985]="干得好，$g小伙子:小姑娘;。$b$b你让通往储藏室的路变得畅通无阻。"
D.Strings[42986]="我带来了乌瑞恩国王的问候，$c。在我身后是“英雄的召唤”公告牌——暴风城国王在此向来自各地的冒险者昭告，哪里才是他们异禀天资的用武之地。如此，英雄们可以更好的为联盟贡献力量。"
D.Strings[42987]="Lok'tar，$c。在我身后是“酋长的命令”公告牌——我们的领袖向部落的成员们发出指引。它会告诉你，哪里才是你出色战技的用武之地，以更好的帮助部落对抗我们共同的敌人。"
D.Strings[42988]="记得永远要对元素表现出你的尊重。"
D.Strings[42989]="永远努力理解，由这个世界上元素之魂所保持的平衡。"
D.Strings[42990]="把他千刀万剐！"
D.Strings[42991]="帮帮我！让他离我远点！"
D.Strings[42992]="你成功抵御了敌人的攻势！$B机构主管会不开心的……"
D.Strings[42993]="将升降梯降至底层。"
D.Strings[42994]="通过消灭暮光腐蚀者来帮助阿莱克丝塔萨。"
D.Strings[42995]="将升降梯升至第二层。"
D.Strings[42996]="将升降梯升至第三层。"
D.Strings[42997]="选择目的地。"
D.Strings[42998]="将升降梯召唤至当前层。"
D.Strings[42999]="阿莱克丝塔萨受伤了。消灭暮光腐蚀者以保持红色光束，否则她将落败！"
D.Strings[43000]="$n，去用卡拉兹加农炮把那些雷爪狮鹫打下来，别让它们把这地方毁掉！"
D.Strings[43001]="我真想看看当他们意识到自己是被你用这些破烂打下来时，脸上有什么表情。"
D.Strings[43002]="难以置信，你们竟然真要击败我的熔岩巨虫了！也许我可以帮你们……扭转局势。"
D.Strings[43003]="银色黎明同胞兄弟们的牺牲必须被永远铭记。他们信仰黎明，尽管没人能活着看到圣光重新照亮这片土地。"
D.Strings[43004]="用烈焰喷射来让敌人葬身火海！"
D.Strings[43005]="只要你出得起钱，圣光就能永远保护你，$c。"
D.Strings[43006]="如果你口袋里有钱，我相信圣光一定能传授给你些什么。"
D.Strings[43007]="我得承认，没有你的帮助，我根本没法做到。"
D.Strings[43008]="好了。这应该能行！"
D.Strings[43009]="数据访问中……请稍候。"
D.Strings[43010]="|TInterface\\Icons\\INV_ELEMENTAL_PRIMAL_SHADOW.BLP:20|t%s朝锅里施放了|cFF660099黑暗|r魔法！"
D.Strings[43011]="正在访问起源重组装置撤销系统。"
D.Strings[43012]="好了，好了。快读取这圆盘，给我访问权限……"
D.Strings[43013]="资料库访问拒绝。起源重组子程序已启动。"
D.Strings[43014]="什么？！什么！这可不好！这可一点儿都不好……"
D.Strings[43015]="警告！$b起源重组装置已激活。一分钟后爆炸。"
D.Strings[43016]="一分钟？！快点，布莱恩！快想！"
D.Strings[43017]="我要靠手动拆开它！一定有办法的！"
D.Strings[43018]="30秒后爆炸。"
D.Strings[43019]="好了！看到导爆线了！该切断哪根呢？红色？还是蓝色……？"
D.Strings[43020]="哎呀！我没法决定！"
D.Strings[43021]="来吧，怪物们！我们将把你们粉碎！"
D.Strings[43022]="好吧，只能这样了！"
D.Strings[43023]="你们这群臭狗完全不顶用！"
D.Strings[43024]="我要再消灭100只像你们这样的军用座狼！"
D.Strings[43025]="你们这群座狼在暴风城的力量面前简直就是渣！"
D.Strings[43026]="注意了弟兄们！周围到处都是兽人和座狼！"
D.Strings[43027]="佩波跳来跳去，充满希望地抬头望着你。他显然记得你是谁。"
D.Strings[43028]="来吧小家伙，让我们离开这儿。"
D.Strings[43029]="佩波跳动着顺从地跟在你身边。"
D.Strings[43030]="佩波欢快地上下弹跳着，消失在远方。"
D.Strings[43031]="佩波欢快地四下跳跃着，消失在远方。"
D.Strings[43032]="佩波欢快地在你腿边跳上跳下，然后飞也似地消失在远方。"
D.Strings[43033]="佩波充满感激地跃动着，然后消失在远方。"
D.Strings[43034]="鉴于你们所做的一切，不如我们切断……"
D.Strings[43035]="红色！为了部落！"
D.Strings[43036]="蓝色！为了联盟！"
D.Strings[43037]="起源重组装置爆炸进程已中断。"
D.Strings[43038]="从这地方逃离比我预想中还要难。$B$B当视野之中看不到出路时，你该往哪里走？"
D.Strings[43039]="哇呼——！"
D.Strings[43040]="艾泽拉斯又逃过了一劫！"
D.Strings[43041]="对，有无数人还被困在逃生舱里，老大。喔，等一下。我想你已经不再是老大了。不管怎么说，如果你不赶快把他们放出来，他们都要变成水鬼了。"
D.Strings[43042]="我帮不了你，$c。"
D.Strings[43043]="我们得用上所有炸弹和工具，才能在这荒岛上活下去，$n。"
D.Strings[43044]="$n，你必须在那些刺角雏龙逮到我们之前，把它们解决掉！"
D.Strings[43045]="你听到龙母在峭壁上的咆哮声没有？绕开她！"
D.Strings[43046]="那些香蕉一定会让猴子们乐翻天的！"
D.Strings[43047]="那是我一生中所见过最美的东西了！"
D.Strings[43048]="戴姆维克就在东南方的洞穴入口处。"
D.Strings[43049]="卡亚矿石没了，这些猴子也因为矿石而变聪明了！保护好那个矿工，$n。"
D.Strings[43050]="以锈水财阀的名义，这里的矿是我的！"
D.Strings[43051]="我们要想保住性命，就需要结交一些新朋友。希望那些兽人不会一见面就把你干掉。"
D.Strings[43052]="和你合作感觉很愉快，$g小伙子:小姑娘;。$b$b希望今后能与你再次携手。"
D.Strings[43053]="只要酬劳高，我们能干掉任何人！"
D.Strings[43054]="该加入你的朋友们了，亲吻泥土吧！"
D.Strings[43055]="我们要把这地方焚毁殆尽！"
D.Strings[43056]="受够你这些豌豆射手了。让它们往这儿打！"
D.Strings[43057]="深岩之洲近年来改变了许多。都快认不出来了。$B$B但是……我并没有被腐化。并没有受到远古之神的影响。看来有时只有在自由被剥夺的情况下，人们才能真正意识到它的珍贵。"
D.Strings[43058]="基拉格·血牙应该就在通向西边的路上，地精。"
D.Strings[43059]="%s开始施放烈焰升腾！"
D.Strings[43060]="我认识你。我要感谢你。如果不是你，我可能还会深陷在已经将我吞噬无数个岁月的腐蚀力量中。$B$B欢迎来到我的家，深岩之洲。与曾经的深岩之洲相比，这里大概只能算是一个影子。但我现在是自由的。承受过那么多磨难之后，我已经深深地明白，自由是多么可贵。$B$B不知道你为什么会到这里来，但我希望你能在这高大的石墙中找到你所需要的一切。祝你平安，$n。"
D.Strings[43061]="用你的杂草清理者割倒这些植物，小地精！"
D.Strings[43062]="这台挖掘机有些生锈了，可看起来还能使用。"
D.Strings[43063]="按下带有“经过黑铁酒吧”标签的按钮。"
D.Strings[43064]="按下带有“进入住宅区”标签的按钮。"
D.Strings[43065]="按下带有“入口”标签的按钮。"
D.Strings[43066]="注意了。所有人注意了。我要向大家致以最诚挚的歉意——很抱歉，我所拥有的财富是你们所有人都比不了的。我真心希望你们能找到致富的通途。"
D.Strings[43067]="你们真不简单。明知道永远不可能拥有与我等同的财富，却还能勇敢地继续自己的人生，这真是太难得了。我为你们坚持不懈的精神而感到骄傲。"
D.Strings[43068]="有时候……有时候抱着这么多钱也不是什么好事儿。这感觉太孤单了。我穷得就只剩下钱。"
D.Strings[43069]="哈哈哈！这让我想起，曾经有个小男孩走到我面前告诉我，他想成为和我一样的富翁——有一天能端坐在属于自己的金山上。真是可爱的小家伙。我告诉他赶快回去拖地板，别再偷懒了。我是认真的。"
D.Strings[43070]="回去告诉阿格娜，我们正在朝西北方向前进。"
D.Strings[43071]="为你们所有人三呼万岁！继续乘火箭车驰骋，从商贩手中抢购商品吧。你们正在为艾泽拉斯最高尚的事业贡献自己的力量——用金币塞满我的口袋！"
D.Strings[43072]="谢谢。谢谢你们特地前来瞻仰我这浩瀚的金币海洋。能见到我本人，相信你们一定感到无比荣幸。"
D.Strings[43073]="我简直是……太……会享受了。看看这些枪。看看这些金币。看看这些美女。谁会不想成为我呢？"
D.Strings[43074]="经由谷地返回，与荒野瞭望台的基拉格会面。"
D.Strings[43075]="你为什么要跟我说话？跟我比起来你简直就是个穷光蛋。$B$B去找你的同类吧，伙计。"
D.Strings[43076]="骑乘巴斯蒂亚！去找布拉克斯！"
D.Strings[43077]="呃哦，是贸易大王。"
D.Strings[43078]="岑塔布拉，你是传闻中提到的德鲁伊之一吗？回音群岛上许久之前就已经有德鲁伊存在了？"
D.Strings[43079]="<岑塔布拉大笑起来。>$B$B是我们散播的那些谣言，朋友。目的是要让扎拉赞恩和其它人远离我们。别相信你所听到的任何事。$B$B不，我们刚接触那门艺术不久，几年前才开始学习。但从某种程度上来说，我们毕生都在准备响应召唤……"
D.Strings[43080]="那么在你们成为德鲁伊之前，你们的身份又是什么呢？"
D.Strings[43081]="我们当中有些人曾是祭司或巫医。就像扎拉赞恩……$B$B<岑塔布拉的视线飘向南方，神色变得严峻。>$B$B我们以为是自己惹怒了神祗，完全没怀疑过是扎拉赞恩在慢慢阻断我们之间的联结。我们知道他很强大，但没想到竟会这么强……当他的巫毒妖术蔓延到其它岛屿时，我们已无力阻止他。"
D.Strings[43082]="你是怎么逃离扎拉赞恩的？"
D.Strings[43083]="<岑塔布拉闭上双眼，摇了摇头。>$B$B当沃金号令所有人逃离时，我们……我们深感无颜面对宗族。于是我们逃向了南方，藏进了那片未开化的丛林群岛。$B$B那里的野兽当晚就夺去了我们几个同伴的生命。我们在岛屿中部的深邃洞穴中找到了栖身之所，但我在那里的梦境并不安宁——我看到了幻像！"
D.Strings[43084]="什么幻像？"
D.Strings[43085]="战斗即将开始！"
D.Strings[43086]="|TInterface\\Icons\\spell_fire_flamebolt.blp:32|t用火焰冲击来焚烧暮光暗影幼龙。"
D.Strings[43087]="<岑塔布拉猛地转向你，她的眼睛闪烁着光彩，獠牙外露的大嘴现出微笑。>$B$B这真是我的记忆中最为广袤狂野的丛林！古老的迅猛龙之神，赞达拉传说中伟大的猎手贡克竟然出现在我面前！$B$B那位迅猛龙的英灵同我交谈，将我的灵魂带到了一个被称为翡翠梦境的地方。像回音群岛的其他神灵一样，那位英灵被扎拉赞恩的魔法困住了。但这位古老的英灵还是穿过扎拉赞恩的妖术，将我带到他身边。"
D.Strings[43088]="|TInterface\\Icons\\ability_druid_ravage.blp:32|t当敌人虚弱时，用终结强击来将他们击落！"
D.Strings[43089]="魂灵想要什么？"
D.Strings[43090]="|TInterface\\Icons\\spell_nature_healingway.blp:32|t生命缚誓者的礼物将在为你回复生命和法力值的同时，治疗其它成员。"
D.Strings[43091]="扎拉赞恩无意识的奴仆们正在这些岛屿上屠杀动物，烧毁植被。贡克需要我们去拯救这片群岛。因为扎拉赞恩的阻碍，我们还无法汲取神灵之力，所以贡克传授给我们一个新的方法，能够与所有自然之灵建立联系。我们将借助全部神灵的力量，而不再只是某一位单独的神灵。$B$B一开始，这样做会很难，朋友。但贡克已经让我们懂得，该如何进入翡翠梦境，直接与那里的神灵对话，向他们学习技艺！"
D.Strings[43092]="其他神灵对此有何反应？"
D.Strings[43093]="<岑塔布拉笑了。>$B$B其他神灵，特别是希瓦拉尔，对他的计划颇不以为然。他们仍然希望我们一次只敬拜他们之中的一位，而不是同时与全部神灵沟通。但贡克对他们施加了很大压力。而且他们都明白，这是从扎拉赞恩手中拯救群岛的唯一办法。$B$B我相信，贡克也不很在意其他神灵的意见。当我们在神灵那里进行学习的时候，他一直在嘲笑他们。"
D.Strings[43094]="然后发生了什么？"
D.Strings[43095]="我们之中的许多人都一直在侍奉这些神灵，早已熟悉了他们的形态。但在同诸神灵交流的练习中，我们还是渡过了许多个月亮的轮回。这并不容易，幸好除了教导我们的神灵们之外，翡翠梦境本身就是一位强大的教师……它会让一切事情以更快的速度演进。$B$B扎拉赞恩对我们造成了巨大的威胁。虽然神灵们在帮助我们，让我们掌握了新的技艺。但在过去几年，他的妖术和他无脑的奴仆们还是杀死了几名我们的兄弟姐妹。但我们终于保住了这些岛屿上的生命。当沃金和暗矛部族回归时，我们知道，彻底消灭扎拉赞恩的日子到了。"
D.Strings[43096]="神灵们仍然在履行他们允诺的职责吗？"
D.Strings[43097]="是的，朋友，至少现在还是这样。他们对于教导更多我们的族人并不热心。但只要我们还在维护这些岛屿上的生命茁壮生长，他们就会继续帮助我们。当扎拉赞恩灭亡，贡克离开的时候，他告诉我们，如果其他神灵不遵守契约，该如何与他取得联系。$B$B我希望这样的事情永远不要发生……但为了以防万一，我们还是和塞纳里奥议会建立了联系。$B$B<岑塔布拉发出一阵狂野的笑声。>$B$B哦，你真应该看看那些暗夜精灵的表情……"
D.Strings[43098]="在渗入尼斐塞特边境的行动中，我大部分兄弟都倒下了。$B$B他们决不能白白牺牲，对此我责无旁贷。"
D.Strings[43099]="赶快，$n，部署胶囊盒。我们的人都被困在里面！哦！我差点忘了你的降落伞。"
D.Strings[43100]="这是我生命中最漫长的一天。"
D.Strings[43101]="霍巴特就在你身后，$g阁下:女士;。"
D.Strings[43102]="痊愈吧，$g兄弟:姐妹;！"
D.Strings[43103]="我在全力治疗你！"
D.Strings[43104]="让圣光拥抱你！"
D.Strings[43105]="在圣光的照耀下焕发新生！"
D.Strings[43106]="继续战斗，$G兄弟:姐妹;！"
D.Strings[43107]="其实简单得很，$n。只要把这些焰火装到野生肉鸡身上，然后我会用这控制器帮它们飞进笼子。"
D.Strings[43108]="我需要治疗，兄弟！"
D.Strings[43109]="发挥你的作用，快治疗我，帕克斯顿！"
D.Strings[43110]="现在给我们找些真正的蛋来。"
D.Strings[43111]="别小看那机动战鸡，$n。那毕竟是霍巴特·钩锤的发明！"
D.Strings[43112]="占卜"
D.Strings[43113]="你感受到弥散在感恩节空气中的幸福了吗，$n？如果你需要帮助，可以来找我。"
D.Strings[43114]="感恩节快乐，$c！"
D.Strings[43115]="你好啊，$n。感恩节快乐！"
D.Strings[43116]="$n，到X型蒸汽机械鲨鱼控制器那儿去。帮我们摆脱巨锤的威胁！"
D.Strings[43117]="感恩节激发起你的购物欲了吗，$c？嗯，那你可来对地方了！"
D.Strings[43118]="祝你好运，英雄！"
D.Strings[43119]="我无惧邪恶！"
D.Strings[43120]="我……我很好！我很好！"
D.Strings[43121]="冬幕节快乐，$n！"
D.Strings[43122]="祝你冬幕节快乐，$c！"
D.Strings[43123]="你是$n！人人交口称赞的大英雄！谢谢你！"
D.Strings[43124]="你在寻找最棒的冬幕节礼物吗，$c，还是想要好好犒劳自己一番？"
D.Strings[43125]="希望你能拥有一个最幸福的冬幕节，$n！"
D.Strings[43126]="你好啊，$n。我们正需要你的帮助。"
D.Strings[43127]="市场调研结果显示，纳迦即将发起入侵！"
D.Strings[43128]="春节快乐，$n！"
D.Strings[43129]="恭祝你春节快乐，并愿你一切顺利，$c。"
D.Strings[43130]="你听见了吗，纳迦？$n正在赶来落实我们的“谈判”！"
D.Strings[43131]="愿这个春节与这个冬天成为你生命中一段美好的时光，$c。"
D.Strings[43132]="等你拿回那些皮子之后，我们就能讨论分成的问题了。我想，我九你一应该不错。"
D.Strings[43133]="美酒节快乐，$n！"
D.Strings[43134]="享受到火焰节的乐趣了吗，$c？"
D.Strings[43135]="所有人都喜欢小马泳圈。紧随在不靠谱炸弹：未成年人版之后，它是我们这里的销量亚军。"
D.Strings[43136]="火焰节快乐，$c！"
D.Strings[43137]="火焰节正是适合冒险的好时候，但也是开心购物的好时机！"
D.Strings[43138]="这个美酒节你是否过得畅快淋漓，$c？"
D.Strings[43139]="到了美酒之地，别忘了为我祝酒，$c！"
D.Strings[43140]="你尝过美酒节饼干了吗？简直太可口了，$c！"
D.Strings[43141]="$n，跳进B.C.消除者，把那些俾格米人消灭干净！"
D.Strings[43142]="如果你要和他们战斗，$n，你可以在他们的村外去找小静。"
D.Strings[43143]="暮光文件飞散开了！"
D.Strings[43144]="我是这次行动的负责人。$B$B我可不想听到有人因为我们的运输工具爆炸，或者是敌人比我们高之类的无聊事情而抱怨。我们是专业人士，要一丝不苟地完成工作。"
D.Strings[43145]="好好看着，这就是恐怖的，聪明的，无所不能的，满心憎恨的，高举利剑的，勇猛杀敌的，战无不胜的，还有最重要的一点——英俊无比的布尔吉·黑心。"
D.Strings[43146]="好好看看，我是多么美丽啊。"
D.Strings[43147]="我离开了战斗！！！"
D.Strings[43148]="在看守者斯蒂沃特到来之前建立起防御！"
D.Strings[43149]="在你被敌人压垮之前，一定要干掉看守者斯蒂沃特！"
D.Strings[43150]="不要再犯傻了。该是进行手动操控的时候了！"
D.Strings[43151]="什么？不！这片草坪……是……我的……"
D.Strings[43152]="<军情七处的密探失去了意识。>"
D.Strings[43153]="暗影所见。Bal'qwari Og Shadar。终结到来！"
D.Strings[43154]="太阳失去光芒。黑暗与灰烬覆盖大地。海洋如血般鲜红……"
D.Strings[43155]="虚无，虚无，我们化为虚无。执掌一切者握住我们的心灵，攥紧了他的拳头。"
D.Strings[43156]="我要去追埃鲁纳克。跟上我，$n！"
D.Strings[43157]="Gillari, geth'shar. Gillari, teko'shar，无所不见，无所不知。"
D.Strings[43158]="我睁开双眼，却只见到黑暗。"
D.Strings[43159]="Shethnoth, ol'goth, grell，这便是即将到来者的咒文。"
D.Strings[43160]="先驱者到来了。世界在颤抖。"
D.Strings[43161]="你想要多尔穆斯骆驼？不！那是我的骆驼！多尔穆斯杀死你！！！"
D.Strings[43162]="嗨，一定不要走进那个冒烟的地方！上一个不幸的$r就是因为无法承受那里的高热而完蛋的。$b$b那可真是个可怜又美味的$r。"
D.Strings[43163]="请不要让一个兽人认为你是蠢货。我这里的日子不好过，如果你能安静一点，我会很高兴的。"
D.Strings[43164]="剿灭纳兹夏尔和她的爪牙是我最想去做的事，但我也需要有人掩护……"
D.Strings[43165]="现在我最想去做的就是亲手消灭那个女巫。但我需要有人帮我挡住那些偷袭的纳迦……$b$b不要让我失望，$n！"
D.Strings[43166]="我们赶快将这里清理干净，把这些小子弄出去。我还有事要做。"
D.Strings[43167]="你的座驾已经准备好了，朋友。让我们离开这个地方！"
D.Strings[43168]="继续前进吧，朋友。$b$b等我的力量恢复以后，我会自己出去的。"
D.Strings[43169]="$n，你一定要去把我们的人救出来！"
D.Strings[43170]="地精僵尸？一定要警告胶囊镇！"
D.Strings[43171]="好啊！我们走。"
D.Strings[43172]="这……容易……"
D.Strings[43173]="告诉你，我要对燃烧引擎进行一次大改造，让它能一次烧光我们全部的燃料储备，把我们一下子轰到目的地去 ！"
D.Strings[43174]="无论怎样……你可不要晕过去！"
D.Strings[43175]="那些僵尸的速度很慢。你不必一直冲到他们里面去就能把他们逐一打倒。小心不要让他们吃到你的脑子，$n！"
D.Strings[43176]="我能为你做些什么，$n？"
D.Strings[43177]="我能为你做些什么，$n？需要进行训练吗？"
D.Strings[43178]="哦，僵尸？$B$B需要进行训练吗？"
D.Strings[43179]="虽然我们在这里蒙受了巨大的损失，但地狱咆哮知道纳迦将军被我们打败了，一定会很高兴的。"
D.Strings[43180]="哦，僵尸？"
D.Strings[43181]="尽管我们的许多战士牺牲了，但国王如果知道我们击败了纳迦将军，一定会很高兴的。"
D.Strings[43182]="胶囊镇已经成功地安置下来了，$n。$B$B需要进行训练吗？"
D.Strings[43183]="胶囊镇已经成功地安置下来了，$n。"
D.Strings[43184]="那些僵尸的速度很慢。射击他们就像打火鸡一样容易！$B$B现在你需要进行训练吗？"
D.Strings[43185]="那些僵尸的速度很慢。射击他们就像打火鸡一样容易！"
D.Strings[43186]="一个胶囊镇，太好了！$B$B需要进行训练吗，$n？"
D.Strings[43187]="一个胶囊镇，太好了！"
D.Strings[43188]="我在那台机器旁边总是会保持十二分的小心，$c。"
D.Strings[43189]="小心，上一个使用那台机器的$r结局相当悲惨，你可不要步他的后尘。"
D.Strings[43190]="那台机器简直就是一堆垃圾。你用过它之后，可以到我这里来接受紧急治疗服务，$c。"
D.Strings[43191]="你真的打算去鼓捣那台破烂机器，不惜拿自己的生命和肉体做赌注？在奥格瑞玛可是有许多可靠又可敬的训练师。"
D.Strings[43192]="他们怎么敢把我们的人民变成僵尸，还让这些可怜人反过来攻击我们！$B$B你一定要去狠狠踢爆他们的屁股！在此之前，你需要进行训练吗？"
D.Strings[43193]="他们怎么敢把我们的人民变成僵尸，还让这些可怜人反过来攻击我们！"
D.Strings[43194]="你闻到那股烧焦的气味了吗？有没有看到那双鞋？你能把这些线索拼合起来吗，$c？"
D.Strings[43195]="你确定不想进行急救训练？如果你真的用了那台机器，也许我能有机会在你身上实践一下我的技巧，$c。"
D.Strings[43196]="最后使用那台机器的$c只留下了靴子……或者不如说，是那台机器只留下了他们的靴子。"
D.Strings[43197]="我们需要再试一次。"
D.Strings[43198]="不要碰这些靴子！我正在等待权威人士来此收集证据。"
D.Strings[43199]="保持聚变核心的稳定几乎耗尽了我的全部计算能力。$B$B现在我们只能希望那个浮点错误已经在我的上一次维护周期中被排除了。"
D.Strings[43200]="一个胶囊镇。难道我们不是这个世界上最伟大的工匠吗？$B$B需要进行训练吗？我年轻的追随者？"
D.Strings[43201]="一个胶囊镇。难道我们不是这个世界上最伟大的工匠吗？"
D.Strings[43202]="真是出类拔萃的工艺！"
D.Strings[43203]="嗯……这样选择零件可真有趣。"
D.Strings[43204]="孩子，真希望我也有这样的座驾！"
D.Strings[43205]="我打赌，这个孩子体内流淌着真正的兽人热血。"
D.Strings[43206]="也许这样的座驾不会那么容易驾驭，但我打赌，它绝不会让你失望。"
D.Strings[43207]="我们的成绩不错。我打赌，只要再增加一些部件，这支火箭一定能成为万众瞩目的焦点。"
D.Strings[43208]="地精僵尸？地精僵尸！$n，去消灭那些俾格米人！$B$B在你出发前，需要进行一些训练么？"
D.Strings[43209]="地精僵尸？地精僵尸！$n，去消灭那些俾格米人！"
D.Strings[43210]="干得漂亮，$n。是你让这个地方活起来了！"
D.Strings[43211]="一定要对那些俾格米人采取行动，$n！"
D.Strings[43212]="曾经有一段时间，我可以对那些想要见我主人的家伙们予取予求。但现在，我的主人会接纳任何想成为他学生的人。他们能够通过他的传送门随意往来。$B$B我不会质疑他的命令，但这实在让我感到很苦恼。现在我的乐趣只剩下了让你们穿上可笑的衣服，或者看看你们的那副可怜相。但这些也已经让我感到无聊了……$B$B我对这种生活感到极度厌烦！走吧，赶快走。和别人去分享你的郁闷心情吧。"
D.Strings[43213]="你打算在这个地方花多少钱？$B$B想不想在训练方面进行一些消费？"
D.Strings[43214]="你打算在这个地方花多少钱？"
D.Strings[43215]="不管是否产生于地精，僵尸在圣光的眼中永远都是憎恶的存在。而且，你绝对不可能和他们做买卖。$B$B至少现在还不行。$B$B需要进行训练吗，$n？"
D.Strings[43216]="不管是否产生于地精，僵尸在圣光的眼中永远都是憎恶的存在。而且，你绝对不可能和他们做买卖。$B$B至少现在还不行。"
D.Strings[43217]="荒野之中的城镇。我喜欢这样！$B$B需要进行训练吗，$n？"
D.Strings[43218]="荒野之中的城镇。我喜欢这样！"
D.Strings[43219]="你可以在东北方找到厄格尔罗。这样你就能更快地跨越这道海湾了。"
D.Strings[43220]="你能不能在暗中靠近僵尸？难道当你靠近的时候，他们闻不到你脑子的气味ie？$B$B不过，这里大概有半数人已经不必担心这种事了。$B$B需要进行训练吗，$n？"
D.Strings[43221]="你能不能在暗中靠近僵尸？难道当你靠近的时候，他们闻不到你脑子的气味ie？$B$B不过，这里大概有半数人已经不必担心这种事了"
D.Strings[43222]="全能战士NX-01型处于离线状态。"
D.Strings[43223]="全能战士NX-01型毁坏！$B$B塞进钱币，获取更多训练。"
D.Strings[43224]="我已经走了这么远，绝不可能被几个亡灵混混吓退。"
D.Strings[43225]="女士们，每个人都可以有自己的看法。"
D.Strings[43226]="一个天才应该容忍别人的怪异举动。"
D.Strings[43227]="我想看看，在亡灵的连续攻势前，我能坚持多久。"
D.Strings[43228]="女士们，女士们……就是这样。我已经在我的绘画中捕捉到了那头怪物的精髓。"
D.Strings[43229]="只需要这样就好，女士们。只要看看我的绘画，回忆一下那些更加美好的日子。或者你们可以看看我，想象一下更加美好的未来。"
D.Strings[43230]="嗯，这是你表达观点的一种方法。"
D.Strings[43231]="女士们，请注意，这头野猪将活在我的艺术中。请不要再抛洒泪水了，除非你们是被我的作品所感动。"
D.Strings[43232]="去向那些僵尸展示一下锈水海盗队的精神，孩子！"
D.Strings[43233]="真是惊人啊！"
D.Strings[43234]="真是栩栩如生！"
D.Strings[43235]="简直和活的一样！"
D.Strings[43236]="真美啊！"
D.Strings[43237]="绝对是震古烁今的作品！"
D.Strings[43238]="这些色彩实在是太生动了！"
D.Strings[43239]="我这一辈子都没有见过这么美的东西！"
D.Strings[43240]="萨德希，我真想让你给我画幅像。"
D.Strings[43241]="记住，一定要找到那些俾格米头领：加奥、马奥默和塔卢可。"
D.Strings[43242]="在地面上寻找一堆堆发光的东西。"
D.Strings[43243]="你一定会爱上这个的！"
D.Strings[43244]="那个司克诺兹是个疯子！我绝对不会回去！"
D.Strings[43245]="哦，难道你能做得更好吗？"
D.Strings[43246]="别着急，$g男孩:女孩;，现在，让我看看能怎样改造这台伐木机？嗯。"
D.Strings[43247]="我已经让这支地精火箭筒能够一次发射多枚火箭。相信我一定也能完美地校准它的瞄准系统。"
D.Strings[43248]="我已经收集了这么多龙类的精华……这种力量……真让人激动不已！"
D.Strings[43249]="你不能把它拿走！任何时候都不能！"
D.Strings[43250]="弗林特洛克，如果我们有一门超级大炮，为什么我们不能……发射一颗炮弹？"
D.Strings[43251]="我主要研究两方面的问题：让微小的突然膨胀成巨大的；将巨大的放入微小的空间。$b$b今天你的需要又是什么？"
D.Strings[43252]="为我们报仇，$n。"
D.Strings[43253]="地精手榴弹对侏儒陆战地雷。让他们看看谁更强，$n！"
D.Strings[43254]="你为我们所做的一切，为我们带来了光荣，$n。"
D.Strings[43255]="我忘记了……你在科赞上过飞行课吗？"
D.Strings[43256]="这没有用。我的魔法对这些怪物是无效的。"
D.Strings[43257]="最好快一点，$n。我觉得那个萨尔应该知道大家都被囚禁在哪里。"
D.Strings[43258]="快跑，巴斯蒂亚！带$n去天坠瀑布和矿坑。"
D.Strings[43259]="格瑞里一边无意识地继续着劳作，一边说了一些昏乱的话。"
D.Strings[43260]="我们要让我们的人离开这里，$n！最关键的是要让他们喝下足够的卡亚零一度可乐！"
D.Strings[43261]="$n，我们需要从北部隧道逃出去！"
D.Strings[43262]="解决那些热砂港大鲨鱼队的队员，不要让他们碰到我们！"
D.Strings[43263]="孩子，我们会为你制造终极足球炸弹制服。但首先，我们需要零件，非常非常多的零件。"
D.Strings[43264]="你不能让他就这样轻松地甩了你！孩子，你要让他痛心疾首！"
D.Strings[43265]="我从来都不喜欢那个家伙。他偷走了你的女朋友。不过要我说，这对你也算是一种解脱！"
D.Strings[43266]="该是搞些破坏的时候了！"
D.Strings[43267]="如果我们要让我们的足球炸弹制服动起来，就需要很多油，孩子！"
D.Strings[43268]="把这件足球炸弹制服送到奴隶营去，快一点，$n！"
D.Strings[43269]="在笼子上安装推进火箭。我的下一个构想又会是什么？我真是个天才！"
D.Strings[43270]="我最恨的就是雇佣兵。他们没有半点荣誉感！"
D.Strings[43271]="她先是丢下你，投进奇普的怀里。现在，她又成了贸易大王的人！$n，你是个好人，她配不上你。"
D.Strings[43272]="女孩，她偷走了你的人！你知道该怎么做！"
D.Strings[43273]="非胜即死，$c！"
D.Strings[43274]="[右键点击] |cFFFFFFFF你在北方战场找到的负伤的暴风城步兵。|r"
D.Strings[43275]="从坟墓中站起，向黑暗女王效忠！"
D.Strings[43276]="以女妖之王希尔瓦娜斯的名义，我将这份礼物赐予你！"
D.Strings[43277]="从死亡的沉眠中醒来，加入你们的同胞之中！"
D.Strings[43278]="醒来吧，沉睡者。新的生命正等待着你。"
D.Strings[43279]="你已经重生于世。女妖之王要求你的效忠。"
D.Strings[43280]="哦，天哪！我们怎么办？！"
D.Strings[43281]="你在开玩笑？你到这里来，就是为了这个？！"
D.Strings[43282]="嗨，好汉，如果你能把我从这里弄出去，我会把老婆卖给你。她绝对不会介意的！"
D.Strings[43283]="让我们看看，我刚才还看见了一个很适合你的下巴……"
D.Strings[43284]="这样就没问题了。如果它再掉下来，就回来找我。"
D.Strings[43285]="感谢你，送葬者。"
D.Strings[43286]="万物的终结即将来临！"
D.Strings[43287]="见证主人的力量吧！"
D.Strings[43288]="你只是在拖延必将到来的结局。"
D.Strings[43289]="我被暮光照耀。"
D.Strings[43290]="你的生命毫无意义。"
D.Strings[43291]="只是在浪费我的时间……"
D.Strings[43292]="你将成为一个绝好的祭品。"
D.Strings[43293]="难道你没有感觉到主人的注视吗？！他的眼睛不会放过我们之中的任何一个！"
D.Strings[43294]="主人将结束一切的存在！"
D.Strings[43295]="万事万物都将服从主人的召唤……"
D.Strings[43296]="这就是终结……对于你的，对于这个世界的。"
D.Strings[43297]="拥抱即将到来的终结吧！"
D.Strings[43298]="我会向主人证明自己的价值！"
D.Strings[43299]="呢喃的低语……我能听到那呢喃的低语……"
D.Strings[43300]="戳刺……抓扯……紧攥……撕裂……"
D.Strings[43301]="啊……杀啊！吃啊！"
D.Strings[43302]="我……破碎……"
D.Strings[43303]="呃……碾压！"
D.Strings[43304]="杀！杀！杀！"
D.Strings[43305]="啊！撕裂！撕裂！"
D.Strings[43306]="啊！！！！"
D.Strings[43307]="我……重击！"
D.Strings[43308]="你将在深渊中粉身碎骨！"
D.Strings[43309]="在大分裂以前，这些水域就已经是我们的了！"
D.Strings[43310]="波涛吞没你！"
D.Strings[43311]="这片水域将是你的坟墓。"
D.Strings[43312]="诅咒你的族类，侵犯者！"
D.Strings[43313]="狂潮啊，给我力量！"
D.Strings[43314]="我会彻底压出你肺里的空气！"
D.Strings[43315]="别想夺走我们的水域！"
D.Strings[43316]="该死的部落！"
D.Strings[43317]="在暮光之锤身上浪费你的力量吧，怪物！"
D.Strings[43318]="如果你想要打，那我奉陪！"
D.Strings[43319]="该死的怪物！你们对我的舰队所做的一切，我都会让你们十倍偿还！"
D.Strings[43320]="从这里滚开，肮脏的部落！"
D.Strings[43321]="现在，你的“荣誉”又在哪里，部落渣滓？"
D.Strings[43322]="你们部落就像暮光之锤一样可憎！"
D.Strings[43323]="这片土地属于联盟，部落怪物！离开这里！"
D.Strings[43324]="让我来消磨一下时间吧！"
D.Strings[43325]="哈，我需要一些新的战利品了……"
D.Strings[43326]="放松，朋友，我下手很快。"
D.Strings[43327]="朋友，你正踏在我们的土地上。"
D.Strings[43328]="这里是碎矛巨魔的土地，你在这里不受欢迎！"
D.Strings[43329]="哈！我们至少应该让它有趣一些。"
D.Strings[43330]="我向来信奉先动手后说话！"
D.Strings[43331]="我们今晚要在你的坟墓上跳舞，朋友！"
D.Strings[43332]="我们要庆祝，庆祝你进坟墓！"
D.Strings[43333]="这太容易了……"
D.Strings[43334]="你的远程技巧很适合在高处进行战斗。用你的钩子跃到一头朱红啸天龙的背上，然后从那里射击盘旋的火翼龙。"
D.Strings[43335]="你骑乘的幼龙受到了致命伤害，就要跌落下去了！赶快转移到另一头幼龙身上！\n\n|TInterface\\Icons\\inv_misc_hook_01.blp:32|t"
D.Strings[43336]="加把劲。"
D.Strings[43337]="还要更多的水。"
D.Strings[43338]="我们会一直送水桶过来。"
D.Strings[43339]="那边！那里的火飚起来了！"
D.Strings[43340]="准备好接着干下去了？"
D.Strings[43341]="我们的任务还没有结束。"
D.Strings[43342]="梵妮莎开始抛掷毒药瓶了！赶快爬上去！"
D.Strings[43343]="你被狼人咬了。可能这没什么，但肯定会有些痛。$B$B|TInterface\\Icons\\INV_Misc_monsterfang_02.blp:32|t"
D.Strings[43344]="后门附近出现了一只箱子！"
D.Strings[43345]="我……我出了什么事？为什么你要这样对我？"
D.Strings[43346]="我应该是死了，就算是死了，我也会回来！"
D.Strings[43347]="这是希尔瓦娜斯女王干的？"
D.Strings[43348]="是什么样的魔法，竟然能挡住死亡之手？"
D.Strings[43349]="我……我想不起来了……为什么你们要这样做？"
D.Strings[43350]="我对黑暗女王有什么用？"
D.Strings[43351]="如果女妖之王给我这样的机会，我很愿意向她效忠。"
D.Strings[43352]="我从不想要这样！别来碰我！"
D.Strings[43353]="哈！你的动作倒真像是我的老祖母。"
D.Strings[43354]="仔细看着，好好学，孩子。"
D.Strings[43355]="好好看看什么是完美。"
D.Strings[43356]="还不赖……你也许还能打中生病科多兽的大肚子。"
D.Strings[43357]="这样应该是可以了。"
D.Strings[43358]="和你赌两个银币，我能把一支箭从中间劈开。"
D.Strings[43359]="这些龙并不糊涂。不过我不确定这些小崽子是否都知道他们要干什么。$B$B当然，我们这里是不会有问题的。我的小子们会冲在最前面，把一切都搞定。我们所需要的只是一个施展拳脚的地方。"
D.Strings[43360]="你准备好开始之后，就触碰祭坛。"
D.Strings[43361]="当试炼开始的时候，来自你脚下的暗影将周期性地突破禁制，进入附近的传送门，召唤来一个泣灵。"
D.Strings[43362]="泣灵也许很可怕，但它们的行动在某种程度上还是可以预期的。将它们引诱进铺设在地面上的符文陷阱里。"
D.Strings[43363]="每次你成功地困住一个泣灵，都将得到一层暗影诱饵。"
D.Strings[43364]="每次你被泣灵击中，都将失去一层暗影诱饵。"
D.Strings[43365]="积累20层暗影诱饵，就能完成试炼。"
D.Strings[43366]="每隔几秒钟，附近的许多符文都将起火爆炸。"
D.Strings[43367]="每个爆炸的符文都会射出一股火焰箭，击中附近的一个或多个符文，使其成为下一批爆炸的符文。"
D.Strings[43368]="如果你仔细观察这些火焰箭，确认那些没有被击中的符文，你就能在下一次爆炸中找到安全位置。"
D.Strings[43369]="偶尔会有符文冒起黑烟，这样的符文将不会在随后的爆炸中起火爆炸。"
D.Strings[43370]="待在符文中，注意不要被火焰击中，直到你积累了10层火焰之舞，完成这个试炼。"
D.Strings[43371]="注意：离开符文太长时间，或者连续被多重火焰击中，会让你重新开始这场试炼。"
D.Strings[43372]="冰霜宝珠分布在这片高地上，如果你接触它们，就会得到冰之精华。"
D.Strings[43373]="避开旋转的冰霜烧灼效果，否则你就会受到伤害，并失去一层冰之精华。"
D.Strings[43374]="如果你碰到地面上的冰霜符文，就会被抛向空中。这对你也许会有好处，也许会是个麻烦。"
D.Strings[43375]="不要靠那片寒冰之地太近，否则你会发现自己移动起来非常艰难。"
D.Strings[43376]="一定要动作敏捷，考虑周全，远离危险，收集20层冰之精华，完成此次试炼。"
D.Strings[43377]="在奥术之巅凸出的平台上分布着6个基座，如果你碰触它们，就能得到它们的能量。"
D.Strings[43378]="使用地面上的能量垫，上升至奥术之巅，碰触沿途的全部基座。"
D.Strings[43379]="任何时候都不要停在某处不动，否则你就有可能被奥术爆炸击中，落进下方的水中。"
D.Strings[43380]="如果你落进下方的水中，不要气馁。游回到第一个平台那里，重新开始吧。"
D.Strings[43381]="到达奥术之巅的顶部，积累6层充能，完成试炼。"
D.Strings[43382]="欢迎来到熔光码头，这座风景如画的海滨小城是爆炸狂们为爆炸狂建造的家园。"
D.Strings[43383]="我要让这里成为我的家。"
D.Strings[43384]="好了，跳上去！"
D.Strings[43385]="冰霜试炼是如何进行的？"
D.Strings[43386]="严格来说，它是怎样进行的？"
D.Strings[43387]="火焰试炼是如何进行的？"
D.Strings[43388]="暗影试炼是如何进行的？"
D.Strings[43389]="干得好。我会让部下继续前进，拿下最后一道门。"
D.Strings[43390]="|TInterface\\Icons\\INV_FIREARM_2H_RIFLE_CATACLYSM_B_01.BLP:20|t%s开始施放|cFFFF0000|Hspell:93520|h[弹幕]|h|r!"
D.Strings[43391]="我们出发。抓紧！"
D.Strings[43392]="小心那些触须！被它们碰到是非常可怕的。"
D.Strings[43393]="不！滚开，你这肮脏的怪物！"
D.Strings[43394]="嗨，扎克，你的爆破分析师平均寿命是多少？"
D.Strings[43395]="这很糟，不是吗？"
D.Strings[43396]="那种超能量源质炸药？你不会想知道的……"
D.Strings[43397]="烽焰！你软弱的肉体将成为我的幼崽们最好的食物！"
D.Strings[43398]="来吧，我的孩子们！苏醒过来，享受这丰美的血肉吧！"
D.Strings[43399]="破壳而出吧，来继承黑龙军团的力量吧！"
D.Strings[43400]="沐浴在大地的烈焰之血中吧！"
D.Strings[43401]="不！我的龙巢是最后的……！父亲……我辜负了你……"
D.Strings[43402]="嗨，我们没有私人仇恨，但你还是要死。"
D.Strings[43403]="不是你死就是我活，朋友。当然，最后肯定是我活。"
D.Strings[43404]="把你的一切都给我，我会让你死个痛快。"
D.Strings[43405]="我已经得到命令，要置你于死地。而且看样子，你也没钱收买我。"
D.Strings[43406]="到沙子里睡觉去吧……"
D.Strings[43407]="我喜欢这样挣钱。"
D.Strings[43408]="呸，挣这点钱可不够我花的。"
D.Strings[43409]="他们把我们的族人变成了怪物！！"
D.Strings[43410]="挡住他们！我们必须保护幸存者！"
D.Strings[43411]="别看他们的眼睛！他们已经不再是你曾经熟悉的那些人了！"
D.Strings[43412]="欢迎来到艾维娜圣殿，$c。在这里，我们安坐于毗邻苍穹的世界之巅。"
D.Strings[43413]="啊，$n！我们又见面了。我曾经帮助你在外域实现了迅速飞行。$B$B<莫希斯紧咬住牙关，摇了摇头。他衰弱的双眼中充满了哀伤。>$B$B今天这些年轻的德鲁伊……他们太过轻易就获得了这种能力。"
D.Strings[43414]="我有许多信件，$n。其中大多数都是垃圾，但有一些对于像你这样有能力的$c来说的确会有些用处。这里有几封寄到永望镇的信，要在世界的这个遥远角落中寻找帮助。$b$b说实话，我觉得我根本没法选择自己的道路！好吧，让我们看看……"
D.Strings[43415]="这尊雕像实在是让人头痛。我本来设想，我们能用一台起重机和几次定向爆破让它浮出水面。但维克认为我们应该采取更加安全和能够减少损伤的办法，就是沿这道斜坡把它滚上去。$B$B现在可好了……我们把它的角度全都弄错了。就算我们把它弄到顶上，又能怎样？$B$B我有一种很糟糕的感觉，我们要在这里耽搁很长时间，很长很长的时间……"
D.Strings[43416]="按理说，既然我在暴风城港口做了这么多漂亮的工作，这个矮人总应该能对我有一点尊敬了……$B$B我只是想让这尊雕像沿斜坡而上，尽快复位。但她对于工作的每一步都抱怨个不停。实际上，她对每一个问题的解决办法都只有爆炸。我觉得她简直就是个侏儒或者地精。至少侏儒和地精还要比她更淡定一些。$B$B看看我们的工作队伍，简直一点纪律都没有。你知道是为什么？全都是因为她在捣乱！$B$B糟糕的态度，懒惰的工人……这样下去，工作根本没办法迅速完成。"
D.Strings[43417]="塞纳里奥议会已经有很长的历史了，朋友。而我们巨魔才刚刚成为其中的一员。"
D.Strings[43418]="我想，这就是……"
D.Strings[43419]="那个可怜的人类逃走了！"
D.Strings[43420]="|TInterface\\Icons\\spell_frost_frostnova.blp:20|t婚礼团队遭受了|cFFFF0000|Hspell:91978|h[临阵畏缩]|h|r！"
D.Strings[43421]="携带一件这么大的武器在这个镇上是不合法的……"
D.Strings[43422]="别想吓唬我！我随便用多么大的武器都可以！"
D.Strings[43423]="你要明白，我是这里的长官！你最好别惹麻烦，因为你逃不过我的眼睛……"
D.Strings[43424]="罗素·布鲁尔开始演奏婚礼颂曲！靠近他，就能得到他施放的恢复效果！"
D.Strings[43425]="哦，不是那样！看啊，我正在我的靴子里震动……"
D.Strings[43426]="就像你们所知道的那样，我们就要开始下一轮密集毁坏测试了。"
D.Strings[43427]="这可不容易。实际上，每七名分析师里有六个无法活着晋升到二级爆破分析师。"
D.Strings[43428]="有一件不能忘记的重要事情，就是我们汇聚在这里，只因为我们都热爱爆炸！"
D.Strings[43429]="所以，我们要让每一次爆炸都有极高的质量！"
D.Strings[43430]="|TInterface\\Icons\\spell_holy_prayerofshadowprotection.blp:20|t脱缰野兽开始释放|cFFFF0000|Hspell:93717|h[黑影光环]|h|r！"
D.Strings[43431]="哈哈！我得到了你的发条猩猩！"
D.Strings[43432]="我想知道，你的发条猩猩能不能跳过这座花园！"
D.Strings[43433]="啦啦啦！我得到你的猩猩了！"
D.Strings[43434]="真想知道，它的发条能拧多紧？"
D.Strings[43435]="如果要我还给你，你就必须……像猴子一样求我！！"
D.Strings[43436]="现在谁是爱哭鬼，爱哭鬼？！"
D.Strings[43437]="小囡囡想要他的娃娃了！"
D.Strings[43438]="博士，你的研究进行得如何了？"
D.Strings[43439]="新的一批高能源质炸药就要完成了。"
D.Strings[43440]="希望这个突破性的进展能让我们在更小的炸弹中装入更多的炸药。"
D.Strings[43441]="不行！把我的猩猩还给我！"
D.Strings[43442]="把跳跳还给我！"
D.Strings[43443]="你不能弄坏跳跳！我不许你这样！"
D.Strings[43444]="你真坏！我要告诉妈妈去！"
D.Strings[43445]="别再拧他的腿了，它们不能弯成那样！"
D.Strings[43446]="你把他弄坏了！"
D.Strings[43447]="停下！你要把他的腿掰断了！"
D.Strings[43448]="那位博士一直都很谦虚。他很清楚该填充多少炸药，甚至不会有一粒的误差。"
D.Strings[43449]="欢迎回到桑德玛尔，$n。战火已经遍及这里的每一个角落，但只要有联盟的帮助，我相信我们一定能占据上风。"
D.Strings[43450]="%s怒吼着，发动了一次凶猛的践踏攻击！"
D.Strings[43451]="他已经知道，这将是一次决定性的胜利！"
D.Strings[43452]="夺取胜利！"
D.Strings[43453]="使用伊欧因的酒杯回复你的生命值！"
D.Strings[43454]="你好，$c。我们蛮锤绝对不会亏待朋友。"
D.Strings[43455]="当艾萨拉还是精灵女王的时候，这里正是精灵皇室的都城之一。这里埋藏着让上古知识重现天日的关键，以及极具历史价值的古代遗物。"
D.Strings[43456]="队长和他的部队已经出发去夺取你曾经为他进行过侦查的一座基地了。你应该赶快去与他们会合。"
D.Strings[43457]="图腾正在获取样品。"
D.Strings[43458]="图腾获取样品结束！"
D.Strings[43459]="你成功地守住了这座桥。召唤仪式完成了。"
D.Strings[43460]="无法……拿起……工具……"
D.Strings[43461]="你对我做了什么？"
D.Strings[43462]="我是谁？"
D.Strings[43463]="不要缩小我！"
D.Strings[43464]="为什么其他人都那么大？"
D.Strings[43465]="击退入侵者！"
D.Strings[43466]="看看他们都对我做了什么！"
D.Strings[43467]="啊！！我是个怪物，别看我！"
D.Strings[43468]="勇敢的巴特利在这个镇子里建立了狮鹫栖息地。如果你要骑乘狮鹫，就去找他吧。"
D.Strings[43469]="你不能到这里来！"
D.Strings[43470]="以库尔森之剑的名义！"
D.Strings[43471]="你要死在这座洞里了！"
D.Strings[43472]="启动祭坛，获得元素的祝福，但一定要避开致命的暗影祭坛！"
D.Strings[43473]="右键点击倒下同伴的躯体，让他们复活！"
D.Strings[43474]="霉牙最厉害！"
D.Strings[43475]="为了蛮锤！"
D.Strings[43476]="如果你不能进行远程攻击，就一定要使用“跃向幼龙！”技能：\n\n|TInterface\\Icons\\ability_vehicle_launchplayer.blp:64|t"
D.Strings[43477]="我要杀了你，否则就是我被你杀掉。"
D.Strings[43478]="蛮锤号角从库德兰的身上掉落下来！"
D.Strings[43479]="德鲁伊？我在这里从没有见过德鲁伊。不过我相信，你能在暴风城找到他们。你应该问问暴风城的卫兵。"
D.Strings[43480]="龙喉战鼓从扎伊拉身上掉落下来！"
D.Strings[43481]="我要让利箭插满你的全身！"
D.Strings[43482]="你的痛苦就是我的慰藉。"
D.Strings[43483]="吹响蛮锤号角，召唤援军！"
D.Strings[43484]="敲响龙喉战鼓，召唤援军！"
D.Strings[43485]="血色十字军还没有完！亡灵只不过是一个小小的挫折！"
D.Strings[43486]="他太强大了！你要想办法用这些祭坛为我们扳回优势！"
D.Strings[43487]="天灾军团将再次崛起，他们将得到新的黑暗主人……埃克斯拉尔！"
D.Strings[43488]="有人倒下了！我们有人倒下了！尽快让他站起来！"
D.Strings[43489]="库德兰倒下了！快点让他恢复过来，继续战斗，否则我们就完了！"
D.Strings[43490]="本杰明·福柯沃斯和他的宠物“狡猾”就在闪金镇铁匠铺的后面。也许你应该去看看他能不能帮你。"
D.Strings[43491]="我要狠狠地教训你，孬种……"
D.Strings[43492]="他太强大了！利用祭坛来操纵元素能量，也许我们还能有取胜的机会！"
D.Strings[43493]="你必须去照顾伤员！赶快！"
D.Strings[43494]="联线。"
D.Strings[43495]="扎伊拉倒下了！让她站起来，否则我们就要在这个被遗忘的祭坛上迎接末日了！"
D.Strings[43496]="我的同胞不会忘记你们所做的一切！承受我们的怒火吧，凡人们！"
D.Strings[43497]="蛮锤援军到了！"
D.Strings[43498]="是谁……离开我的发掘场！"
D.Strings[43499]="龙喉援军到了！"
D.Strings[43500]="就是你们制造了所有这些麻烦！"
D.Strings[43501]="拉格纳罗斯的怒火会将你们烧成灰烬。"
D.Strings[43502]="萨满训练师？闪金镇可没有这种人。$B$B不过暴风城矮人区的蛮锤矮人也许能帮助你。"
D.Strings[43503]="Lok-Narash！战斗！"
D.Strings[43504]="喝啊！"
D.Strings[43505]="离开赤脊山！"
D.Strings[43506]="你还想要？还想要？"
D.Strings[43507]="哦，不……我和你的事情还没有结束。"
D.Strings[43508]="你就是大地的顽疾，你无处可逃了。"
D.Strings[43509]="这些该死的兽人。"
D.Strings[43510]="在地狱里再见吧。"
D.Strings[43511]="这个还是你们这些蛆虫自己留着享受吧。"
D.Strings[43512]="战斗！我要更多的战斗！"
D.Strings[43513]="很抱歉，$c，但上层精灵的奥术秘密是你永远也无法理解的。"
D.Strings[43514]="你的战斗毫无荣誉感可言！"
D.Strings[43515]="我是古加尔主人的忠实奴仆。我可不会败在你手里。"
D.Strings[43516]="碎颅者魔山陷入狂怒之中！"
D.Strings[43517]="我们不可能抵挡如此强大的力量！你必须使用号角了！"
D.Strings[43518]="他太强大了！一定要使用战鼓了！"
D.Strings[43519]="古加尔会……把你……撕成碎片……"
D.Strings[43520]="你的血……将染在我的斧头上。"
D.Strings[43521]="你还有许多东西要学。"
D.Strings[43522]="你的战斗毫无荣誉感可言。"
D.Strings[43523]="哈！我本以为能得到一个像样的挑战者！"
D.Strings[43524]="就算有再多的敌人，也都会被我无尽的怒火吞噬。"
D.Strings[43525]="感受我的怒火吧！"
D.Strings[43526]="这太容易了。"
D.Strings[43527]="效忠龙喉兽人，你将得到丰厚的奖励，$c。"
D.Strings[43528]="来吧！尝尝圣光的滋味！"
D.Strings[43529]="喔。是因为我太强了，还是这家伙太容易死了？"
D.Strings[43530]="啊，哈哈，哈哈哈！"
D.Strings[43531]="和数千年前的魔法相比，今天的这点伎俩实在算不了什么。上层精灵掌握着许多强大的魔法。你是否已经准备好进行学习了？"
D.Strings[43532]="看到了吗，塔伦纳？"
D.Strings[43533]="我们的速度能慢一点吗？"
D.Strings[43534]="真无法相信，我们竟然真的是在为十字军而战！"
D.Strings[43535]="接着这个吧，你这个没胡子的孬种！"
D.Strings[43536]="我要让你爬也爬不起来！"
D.Strings[43537]="给我躺下吧，恶棍！"
D.Strings[43538]="这些不喝啤酒的杂种已经让我受够了！"
D.Strings[43539]="|TInterface\\Icons\\spell_holy_healingaura.blp:20|t灰葬男爵开始施放|cFFFF0000|Hspell:93468|h[怜悯治疗]|h|r！"
D.Strings[43540]="来一杯清凉醇美的啤酒如何？！"
D.Strings[43541]="我已经厌倦了这样的狩猎……去死吧！"
D.Strings[43542]="嗯，在卡拉诺斯，布洛兰·风须能送你去你想去的地方。"
D.Strings[43543]="听到了吗，$r？把耳朵贴到地面上。你能听到战鼓的回音么？我一直都能听到这鼓声，感觉到大地在颤抖。我们必须做好准备，年轻人。一切战争都将在这场战争中结束。与你并肩作战将是我的光荣。相信你已经明白了自己该做什么。"
D.Strings[43544]="我的祖先在这个地方繁衍生息。现在，我站在这里，等待敌人的到来。我已经渡过了自由的一生。而我要让我的子子孙孙能够继续平安地生活下去，远离战火的摧残。赞美法奥瑞斯国王和他为我们的人民所立下的一切英雄功业。$r，我不知道你的道路在哪里，但我相信，你不会辜负我们的期望。出发吧，$g姐妹:兄弟;，在天空被硝烟染黑之前，还有许多事要做。"
D.Strings[43545]="哈鲁宾·霜锤，你可以在雷酒酿制厂找到这位蛮锤矮人。他能够传授你萨满之道。"
D.Strings[43546]="打烂你的蘑菇！"
D.Strings[43547]="想要飞到别处去？安内特·威廉姆斯在镇子西部，她训练有素的蝙蝠能满足你的要求。"
D.Strings[43548]="暴风城公墓"
D.Strings[43549]="旅店老板瑞尼已经把店搬到了镇中心的那个大房子里。那是布瑞尔最大的房子……你不会错过的。"
D.Strings[43550]="我会把你的骨头碾成粉末。"
D.Strings[43551]="大地之山岩，听从暮光之锤的召唤！"
D.Strings[43552]="不过是挡在雪崩面前的一枚石子……"
D.Strings[43553]="不错，又是一颗要碾碎的石子！"
D.Strings[43554]="狠砸……重击……撕碎……是的，主人……"
D.Strings[43555]="我操控着你呼吸的空气……"
D.Strings[43556]="你的尖叫将随风远逝……"
D.Strings[43557]="你的毁灭……已经有了预兆。"
D.Strings[43558]="天空之风暴，听从暮光之锤的召唤！"
D.Strings[43559]="细语……风中的细语……是的，主人……"
D.Strings[43560]="你的死亡将……闪耀着电光。"
D.Strings[43561]="让我给你讲解一下……当前的情况。"
D.Strings[43562]="恐怕我要……额外给你些闪电。"
D.Strings[43563]="苍穹之闪电，听从暮光之锤的召唤！"
D.Strings[43564]="爆裂……吼叫……哀嚎……永远的哀嚎……"
D.Strings[43565]="世界将燃起熊熊大火。"
D.Strings[43566]="一切都将化成灰烬。"
D.Strings[43567]="你觉得我像是懂法术的样子吗？不过，我听说凯恩·火歌就在那间实验室里，他总是喜欢鼓捣些让人不舒服的东西。"
D.Strings[43568]="我只想让这个世界燃烧起来……"
D.Strings[43569]="下界之烈火，听从暮光之锤的召唤！"
D.Strings[43570]="烈火……它们舔舐……它们叮咬……痛苦的叮咬……"
D.Strings[43571]="愿圣光祝福我们先祖的灵魂，他们挑选了我的儿子安息在这片应允的神圣土地上。"
D.Strings[43572]="他属于这里，这片被吉尔尼斯的英雄和爱国者所环绕的土地。"
D.Strings[43573]="我们一定会回来的，利亚姆，我向你发誓。"
D.Strings[43574]="破碎，破碎，破碎！啊哈哈哈哈哈！"
D.Strings[43575]="燃烧，燃烧，燃烧！哈哈哈哈哈！"
D.Strings[43576]="就是这里！就是现在！终结已经到来！"
D.Strings[43577]="吉尔尼斯会铭记你的勇气，利亚姆。"
D.Strings[43578]="我很抱歉……我很抱歉……我很抱歉……我很抱歉……我很抱歉……"
D.Strings[43579]="我能听到！听到那呼唤！我回应那呼唤！"
D.Strings[43580]="战锤正渴望着要砸碎你，朋友。"
D.Strings[43581]="如果把你放在炖肉锅里……那一定会很好看。"
D.Strings[43582]="你是个好猎物，朋友。"
D.Strings[43583]="多少炖肉也装不满我们的大锅！"
D.Strings[43584]="如果你的运气够好，我们会把炖你的火烧得旺一些……"
D.Strings[43585]="啊，你在寻找黑暗牧师贝里尔。他就住在东边的那幢房子里。"
D.Strings[43586]="哈哈！晚饭来找我了！"
D.Strings[43587]="嗯，呀姆呀姆！"
D.Strings[43588]="我要用大块菌杀了你！"
D.Strings[43589]="唔，哦！现在你困在两倍大块菌的麻烦里了！"
D.Strings[43590]="你想要和我打吗？！我们有三倍的大块菌！"
D.Strings[43591]="我能吃了你吗？我的速度会很快的。"
D.Strings[43592]="为什么你要在我吃饭的时候戳我？！"
D.Strings[43593]="马里恩·考尔就藏在这家旅店的楼梯下面。"
D.Strings[43594]="我想吃你，但我已经饱了。所以我要杀了你。"
D.Strings[43595]="你要找的是鲁伯特·鲍什。现在他就住在这家旅店的地下室。"
D.Strings[43596]="是的，你要找的是奥斯蒂尔·德·蒙。他就在旅店附近的一辆绞肉车旁边。"
D.Strings[43597]="你要找飞龙之尾？就在勇者大厅外面。"
D.Strings[43598]="就在通向暗巷区大门的桥对面。仔细听那些地精的喊叫就能找到了。"
D.Strings[43599]="飞行管理员斯凯勒斯就站在通向永歌森林的大门前。"
D.Strings[43600]="就在力量谷，格罗玛什要塞入口的东边。"
D.Strings[43601]="你可以在能找到武器和盔甲的地方找到罗萨恩·银刃。一位战士绝对不会远离他的武器。"
D.Strings[43602]="血是红色的么？"
D.Strings[43603]="狼会嚎叫？"
D.Strings[43604]="这是你最后一次干扰我们的计划了，凡人！"
D.Strings[43605]="深渊会吞噬你！"
D.Strings[43606]="杀手会杀人？"
D.Strings[43607]="无尽深渊在等待着你！"
D.Strings[43608]="乌尔索克，阻止他们……"
D.Strings[43609]="深渊的大军，化为死亡的狂潮，吞没我们的敌人！"
D.Strings[43610]="蛆虫会吃尸体？"
D.Strings[43611]="武装起来，我的奴仆！从寒冰深渊中崛起吧！"
D.Strings[43612]="毁灭这些入侵者！将他们丢进无尽的黑暗之中！"
D.Strings[43613]="在空中翱翔的自由是没有任何东西能与之相比的。如果你想飞上天空，可以和村子中央的双足飞龙管理员塔克聊聊。"
D.Strings[43614]="不要浪费时间了，我们去干活吧。"
D.Strings[43615]="虽然我们距离主岛很远，但我们在这里的任务是很重要的。"
D.Strings[43616]="嘿，这些肮脏人类的气味每一秒都在让我觉得更难受。"
D.Strings[43617]="这座半岛可不是个渡假的地方，$r。这里到处都能找到肮脏的联盟。"
D.Strings[43618]="现在，我们已经夺回了这座岛，该是开始工作的时候了。等你准备好之后，就来找我吧。"
D.Strings[43619]="你在寻找烈日行者？烈日行者艾乌比就和我们的许多训练师居住在一起。"
D.Strings[43620]="每一名战士倒下，都会有十名战士取代他的位置……"
D.Strings[43621]="这个洞穴是个肮脏的地方，$n。除非你已经装备妥当，做好了充分的战斗准备，否则我可不会进去冒险。"
D.Strings[43622]="凝视虚空。"
D.Strings[43623]="他们不会死。"
D.Strings[43624]="自从我们到这里来之后，恶魔监狱中的恶魔一直在给我们惹麻烦。你能帮助我们吗？"
D.Strings[43625]="如果你在寻找正义的道路，你就应该去和先知艾尔苏谈谈。"
D.Strings[43626]="感谢你帮助我们夺回了这座岛，$n。现在，我们需要你继续在咒怨地牢施展你的力量。"
D.Strings[43627]="巨人会轻轻走路吗？"
D.Strings[43628]="感谢你，我的朋友。请原谅我，我……我现在太虚弱了，一点儿忙都帮不上。"
D.Strings[43629]="必须找到一个新的宿主。"
D.Strings[43630]="这个宿主太弱了。"
D.Strings[43631]="只有你的记忆会留下来……"
D.Strings[43632]="荣誉谷的银行就在通向暗巷区的大门前面。"
D.Strings[43633]="他们已经超越了轮回……"
D.Strings[43634]="火焰会烧掉石头吗？"
D.Strings[43635]="这儿，只有古厄夏。"
D.Strings[43636]="放弃吧……"
D.Strings[43637]="谁是你的盟友？"
D.Strings[43638]="这，就是，真实？"
D.Strings[43639]="石块会漂在水上吗？"
D.Strings[43640]="力量谷的银行就在格罗玛什要塞入口处的南边。主大门的西北方。"
D.Strings[43641]="冰是热的吗？"
D.Strings[43642]="你找不到飞行管理员？波洛克就在镇子的南端，那些双足飞龙旁边。"
D.Strings[43643]="萨尔达恩把角鹰兽们照顾得很好。他们就在镇子的北部。"
D.Strings[43644]="它……它起作用了！我们将用这座神殿中的能量守卫纳奥姆！"
D.Strings[43645]="长官，援军被尼斐塞特的军队阻截了。我们只能靠自己了。"
D.Strings[43646]="同剃刀岭营地外面的安苏瓦谈谈。"
D.Strings[43647]="风之议会已经沉沦。而你们光荣的行为和决心为你们赢得了与我一战的权利，凡人们。我一直在等待着你们的进攻！来吧！"
D.Strings[43648]="感谢你，军士。你可以回到岗位上去了。"
D.Strings[43649]="这样不行，$n。我们必须想办法守住纳奥姆。"
D.Strings[43650]="这样的对峙没有任何意义。我要结束这一切。"
D.Strings[43651]="干得好。找到莉拉斯塔萨，让她知道，我们胜利了。"
D.Strings[43652]="我接受你们的挑战，凡人！要知道，你们面对的是奥拉基尔，风之领主！别以为能打败我！"
D.Strings[43653]="这段密文描述的正是神殿深处的能量供给系统！"
D.Strings[43654]="就好象在拍虫子……"
D.Strings[43655]="这个小东西不会再给我找麻烦了。"
D.Strings[43656]="每一场风暴过后，都是静寂……"
D.Strings[43657]="你们已经没有时间了，凡人！你们的生命已经不再属于你们！"
D.Strings[43658]="你们无谓的顽固激怒了我！"
D.Strings[43659]="够了！我不会再容忍下去了！"
D.Strings[43660]="疾风啊！听从我的吩咐！"
D.Strings[43661]="暴风啊！到我的身边来！"
D.Strings[43662]="闪电啊！摧毁我的敌人！"
D.Strings[43663]="消灭入侵者的荣誉属于我，兄弟们！他们软弱的躯体将在我的凛冽寒风中永远冻结！"
D.Strings[43664]="牢牢地被冻住。"
D.Strings[43665]="又一个凡人完蛋了！"
D.Strings[43666]="你们抛下自己的荣誉，要像懦夫一样逃跑？那就死吧！"
D.Strings[43667]="如果你想要骑角鹰兽，就去找菲德利奥吧。"
D.Strings[43668]="强猛的烈风啊，显示力量吧！"
D.Strings[43669]="兄弟们，小心了！这些凡人非常危险。我必须暂停一下，积聚力量。"
D.Strings[43670]="消灭入侵者的功绩应该属于我。就算是我麾下最弱小的气流，也能让他们死无葬身之地！"
D.Strings[43671]="别想再玷污我们的家园！"
D.Strings[43672]="你以为能跑得比风还快？你犯了致命的错误。"
D.Strings[43673]="我的力量在衰减，兄弟们。暂时我必须依赖你们了。真是羞耻啊。"
D.Strings[43674]="我是最猛烈的风暴，撕碎入侵者的应该是我！"
D.Strings[43675]="飞走吧！"
D.Strings[43676]="只是一团尘埃……"
D.Strings[43677]="上层精灵艾莉恩蒂就在这家旅店里。她能传授你奥术的秘密。"
D.Strings[43678]="你们为什么要逃，凡人？这里没有能让你们逃避死亡的地方！"
D.Strings[43679]="兄弟们，入侵者相当难对付，我还没办法打败他们。让我暂时休息一下，聚集我的暴风力量。"
D.Strings[43680]="我……我一直都会在你身边，父亲。"
D.Strings[43681]="所有人，立刻登船！"
D.Strings[43682]="一定要有人留下来，阻止被遗忘者在这里站稳脚跟。再见了，吉恩。"
D.Strings[43683]="带领我们的人民去他们的新家园。"
D.Strings[43684]="克罗雷！你付出的已经太多了。我不能再把你丢下……"
D.Strings[43685]="我们会回来的，亲爱的朋友。我们会回来夺取属于我们的一切。这是我的誓言！"
D.Strings[43686]="父亲……为什么我们一定要承受这样的苦难？为什么我们不能居住在阳光灿烂，土地肥沃的地方？也许我们应该移居到热带岛屿去？"
D.Strings[43687]="坚强起来，孩子。我把你养大不是要让你成为一个软弱的人！"
D.Strings[43688]="有没有见过我最新的发明？它一定能让你大吃一惊……如果它没有爆炸的话。"
D.Strings[43689]="我需要一个GS-9x多功能机器人。"
D.Strings[43690]="%s准备对附近的敌人施放碎颅！"
D.Strings[43691]="一个暮光狂热者进化了！"
D.Strings[43692]="%s的护甲散发出热量。攻击！"
D.Strings[43693]="%s准备和他的一个影子交换位置！"
D.Strings[43694]="这座城市的附魔训练师那里有一位来访的上层精灵大法师。你可以在那里重铸你的物品。"
D.Strings[43695]="很高兴能得到你的帮助。"
D.Strings[43696]="我会在你的地图上标记出你要的地点位置。"
D.Strings[43697]="力量谷"
D.Strings[43698]="荣誉谷"
D.Strings[43699]="尼斐塞特城将要陷落！"
D.Strings[43700]="我还需要一个滑刃之魅，库拉。"
D.Strings[43701]="我还需要一支三叉戟。"
D.Strings[43702]="将他的|Hitem:64383|h|cff0070dd[卡多雷风铃]|r|h举到风中。"
D.Strings[43703]="将他的|Hitem:64383|h|cff0070dd[卡多雷风铃]|r|h举到雨中。"
D.Strings[43704]="将他的|Hitem:64383|h|cff0070dd[卡多雷风铃]|r|h举到雪中。"
D.Strings[43705]="%s准备好进餐了。"
D.Strings[43706]="奥弗在远处出现了！"
D.Strings[43707]="这只箱子一定已经在这里沉睡了千年之久。"
D.Strings[43708]="查看这只箱子。"
D.Strings[43709]="你必须返回奥丹姆东部，否则聚变核心就会失效！"
D.Strings[43710]="我已经准备好面对沙德拉洛了！"
D.Strings[43711]="%s被削弱了！用你的套索抓住它！"
D.Strings[43712]="他们竟然让我等了这么久，简直令人难以置信！"
D.Strings[43713]="为什么连进个城都这么困难？"
D.Strings[43714]="到底发生了什么事？他们什么也不肯告诉我，搞得我有些生气了！"
D.Strings[43715]="我需要搜查你的随身物品。"
D.Strings[43716]="我已经……精疲力尽了，往后你必须独自前进。我会在力量恢复之后自行离开。"
D.Strings[43717]="除掉诅咒！"
D.Strings[43718]="从深岩之洲回来之后，我们发现暮光之锤已经在这里建立起基地，控制了元素传送门。$B$B$n，请一定阻止他们，不要让古加尔在暮光堡垒中完成他的阴谋！"
D.Strings[43719]="你必须返回暮霭海滩！"
D.Strings[43720]="消灭奥伊纳克斯，不要让他的爪牙吞没你！"
D.Strings[43721]="我需要更多的秘密信号粉末，卡德拉克。"
D.Strings[43722]="幽暗的营火"
D.Strings[43723]="兰德鲁的小拆"
D.Strings[43724]="斑纹幼龙"
D.Strings[43725]="灭世者"
D.Strings[43726]="%s已经不再受到信标的保护了！"
D.Strings[43727]="|TInterface\\Icons\\spell_nature_earthquake.blp:20|t乌比斯将军开始施放|cFFFF0000|Hspell:74634|h[地动山摇]|h|r！"
D.Strings[43728]="拿上这块魔法碎片，$n。这样我就能通过和它匹配的另一块碎片亲耳听到矮人们的声音了。"
D.Strings[43729]="该死的虫子……只有我们能指挥这些异种虫！"
D.Strings[43730]="随意地掷出他的|Hitem:63269|h|cFFFFFFFF[侏儒老千的骰子]|r|h。"
D.Strings[43731]="帮我解除这种折磨吧！"
D.Strings[43732]="难道我付出的一切，还不够赎清我的罪行吗？"
D.Strings[43733]="我只是为了我的部族才会这样做！"
D.Strings[43734]="你是谁，竟然能审判我？"
D.Strings[43735]="我必须警告……亚什虫巢……"
D.Strings[43736]="勇士们，抓紧，我们要飞回卡德罗斯的铁砧了！"
D.Strings[43737]="要把闸门打开吗？"
D.Strings[43738]="听我的号令，暮光的爪牙们。（听从！绝对的服从！）"
D.Strings[43739]="就在我说话的时候，愚蠢而软弱的联盟与部落正在接近暮光高地。（愚蠢！盲目！软弱！而且美味……）"
D.Strings[43740]="不要忘记在这里的任务！当那些爱管闲事的英雄们仍然对这片荒凉废土视而不见的时候，你们必须将仪式进行下去。"
D.Strings[43741]="每一个祭品都会让更多主人的使者进入这个世界。（巢穴一片疯狂，一片混乱！）"
D.Strings[43742]="将这些祭品送到其它巢穴中主人的血肉那里去。（它们已经饥渴难耐……）"
D.Strings[43743]="万物的毁灭已经临近。覆亡就在眼前。（万物的毁灭！帷幕已落下！）不要让我失望。"
D.Strings[43744]="天哪，我的头……"
D.Strings[43745]="我在哪里？我们在地下吗？"
D.Strings[43746]="我竟然没有戴着镣铐……我应该不是在睡觉吧……"
D.Strings[43747]="等一下……给我一点时间。"
D.Strings[43748]="勇士们，抓紧，我们要飞回焰痕平台了！"
D.Strings[43749]="滚开！你不应该出现在这里！"
D.Strings[43750]="能送我去大厅吗？"
D.Strings[43751]="能送我去礼拜堂吗？"
D.Strings[43752]="能送我去城墙吗？"
D.Strings[43753]="能送我去实验室吗？"
D.Strings[43754]="已经厌倦了你的恶魔仆从？希望能换一个名字更有趣的跟班？\n\n只要出一定的价钱，我就能帮你除去你现有的一个仆从，这样你就能召唤一个全新的恶魔了……"
D.Strings[43755]="放弃小鬼"
D.Strings[43756]="放弃虚空行者"
D.Strings[43757]="放弃魅魔"
D.Strings[43758]="放弃地狱猎犬"
D.Strings[43759]="放弃恶魔卫士"
D.Strings[43760]="你确定想要付钱以放弃你的仆从？"
D.Strings[43761]="收集情报，同时注意避开暮光守卫！"
D.Strings[43762]="回到船上！"
D.Strings[43763]="你好，$g勇士:女士;出了什么事？"
D.Strings[43764]="你好，王牌战士。还记得我们在失落群岛落难的时候吗？"
D.Strings[43765]="你不会真的以为我只布置了一批炸药吧，对不对？"
D.Strings[43766]="你好，混蛋！"
D.Strings[43767]="好吧，上镣铐吧。但给我记住，加里维克斯，你也会有你的那一份！"
D.Strings[43768]="就是这样，$n！这里就是我们的阵地！"
D.Strings[43769]="我们终于成功了。我们吉尔尼斯人从没有放弃过希望。"
D.Strings[43770]="我不太记得是如何到达暮湾镇的。把你知道的都告诉我。"
D.Strings[43771]="|TInterface\\Icons\\spell_fire_totemofwrath.blp:20|t死神5000型|cFFFF0000|Hspell:88522|h[安全限制离线]|h|r！"
D.Strings[43772]="请刷新奈法利安"
D.Strings[43773]="看起来，这个传送设备最近被用来将物资传送到矿井深处。"
D.Strings[43774]="按下贴有“树木及木材”标签的按钮。"
D.Strings[43775]="按下贴有“金属碎片”标签的按钮。"
D.Strings[43776]="按下贴有“飞船部件”标签的按钮。"
D.Strings[43777]="%s被沸腾岩浆的熔火之力复活了！"
D.Strings[43778]="哦，我的头……今天是什么日子？"
D.Strings[43779]="这些亮光是从哪里来的？啊，赶快让它消失！"
D.Strings[43780]="他说他有糖……"
D.Strings[43781]="当希奈丝特拉操纵这些脉动的暮光之卵的能量时，卵的保护屏障消失了！"
D.Strings[43782]="|TInterface\\Icons\\ability_whirlwind.blp:10|t天哪，我要施放|cFFFF0000|Hspell:88481|h[超速]|h|r了！"
D.Strings[43783]="天哪，我要施放|TInterface\\Icons\\ability_whirlwind.blp:10|t|cFFFF0000|Hspell:88481|h[超速]|h|r了，这太疯狂了！"
D.Strings[43784]="听到了吗？|TInterface\\Icons\\ability_whirlwind.blp:10|t天哪，我要施放|cFFFF0000|Hspell:88481|h[超速]|h|r了，这太疯狂了！"
D.Strings[43785]="$n，你在这里！谢天谢地！"
D.Strings[43786]="谢天谢地，看上去你是个有脑子，也有能力的$c。"
D.Strings[43787]="这是我们的地盘！这是食人魔和巨魔的地方！"
D.Strings[43788]="人类和绿皮占据了这片土地，我们祖先的土地。"
D.Strings[43789]="石拳很强大。枯木很强大。我们在一起，打碎一切敌人！吼！！"
D.Strings[43790]="还没有完，$n。还早着呢。"
D.Strings[43791]="我准备好进行心灵视界仪式了，萨阿莉亚。"
D.Strings[43792]="我准备好进行精神控制仪式了，萨阿莉亚。"
D.Strings[43793]="哈尔琳，我丢失了蓝鳞印记。你能再给我一个么？"
D.Strings[43794]="你要找新来的上层精灵？问我就对了。\n\n你可以在月神殿的西翼找到他们。他们之中的一个也有可能在风嚎橡树。"
D.Strings[43795]="嗯……贝波蒂……门已经打开了。"
D.Strings[43796]="啊……原来如此，原来如此。你就这样继续吧，直到你一命呜呼。"
D.Strings[43797]="我并不在乎听到这些，$n。你别想进入灼热峡谷，别想。这种事绝不会发生。我必须告诉你多少次，我不会让你进去！难道你不懂人话吗？难道你是伪装的兽人吗？不，绝不！$B$B如果我随便让你进去。用不了多久，你的朋友们也会想进去，然后是他们的远亲，他们的朋友，他们远亲的朋友，朋友的远亲。上次发生这种事……我们可不会讨论上次这种事发生时的情形。$b$b我是不会开门的！"
D.Strings[43798]="一个叫维图斯·暗行者的吉尔尼斯人能帮助你。你可以在风嚎橡树找到他。"
D.Strings[43799]="欢迎来到稻草人庆典，$c！$B$B按照万圣节的习俗，我们要焚烧一个稻草人，以代表我们对自我内心的净化。如同森林在秋天洒落枯叶，我们也必须抛弃自身枯萎的那一部分——恐惧、悲哀、憾恨。将枯枝投入烈火，代表着你抛下了不应带入冬天的重担。$B$B请从大篝火中拿起燃烧的枯枝，加入我们的庆典吧！"
D.Strings[43800]="你能感觉到这个地方的污染么，$c？它来自于暗影堡深处。如果不加以阻止，它会将这里的一切吞噬。$B$B我没有多少时间了，$n。只有你能帮助我及时阻止它的蔓延。$B$B<这名受伤的暗夜精灵咳嗽着，移开手，露出肋侧的血污。>"
D.Strings[43801]="吉尔尼斯的儿女们！新老盟友们！大家请到我这里来！"
D.Strings[43802]="万圣节是一场关于转变……关于变革的庆典。"
D.Strings[43803]="只有部族中最勇猛，最具荣誉感的成员才能安息在赤色石。"
D.Strings[43804]="然而，当下不应该再是哀伤悲恸的时刻。"
D.Strings[43805]="每个黎明都会有新的战斗，还有挥之不去的动荡与不安。"
D.Strings[43806]="就让这个稻草人代表我们心中的不安。"
D.Strings[43807]="这只幼崽侧过头，期待地看着你。难道你不知道该做些什么吗，$g爸爸:妈妈;？"
D.Strings[43808]="火炬准备！"
D.Strings[43809]="让火焰飞舞！万圣节来啦！"
D.Strings[43810]="虽然许多火焰都经历过反复争夺与易手，被熄灭又被重新点燃，但所有人都可以去祭拜它们，$c。$b$b在大地之环中，我们只对火焰进行祭拜，不做其它任何轻率愚蠢的事。$b$b我们依照传统举行祭拜仪式。你会加入我们的仪式吗，$n？"
D.Strings[43811]="呃，我把X-21型灭火器弄丢了。能再给我弄一个新的吗？"
D.Strings[43812]="$n，财阀里有一个形容你这种人的专有名词：“财政累赘。”"
D.Strings[43813]="你到达了大地之环大篝火！"
D.Strings[43814]="祭拜大地之环大篝火！"
D.Strings[43815]="稻草人庆典将在10分钟后开始！请加入我们在暴风城大门外的狂欢，一同庆祝万圣节吧！"
D.Strings[43816]="有个可恨的加德纳尔恶魔发现了我！还在我的身侧划了一条大口子。这道伤口不浅，但我还能活下去。$B$B还有更要紧的事情要办，暗影议会将对我们在野性之心哨站的朋友们发起全面进攻。我现在没法战斗了，所以你必须代替我去阻止他们。"
D.Strings[43817]="吉尔尼斯人对变革有着再清楚不过的理解。"
D.Strings[43818]="%s扑向被积雪覆盖的兔子洞。"
D.Strings[43819]="%s只剩下一半的生命值了！"
D.Strings[43820]="%s几乎要被击败了！"
D.Strings[43821]="她来了！安静，你们这帮傻瓜！黑暗女王驾临……"
D.Strings[43822]="哦，太好了，谢谢。这看上去……嗯……一定很美味。"
D.Strings[43823]="主管助理不喜欢看到我们休息。我们也不喜欢看到他。"
D.Strings[43824]="哦，好啊！从前天到现在，我还完全没休息过呢！"
D.Strings[43825]="我想回家去看看我的亲人，但多德根本不让我们离开这座山！"
D.Strings[43826]="食物？我的上一期薪水支票呢？那个你带来了么？"
D.Strings[43827]="哈哈！你抓不到我！"
D.Strings[43828]="哦，一个$c！来抓我啊，你这个慢手慢脚的家伙！"
D.Strings[43829]="我跑得可快了！爸爸让我在鞋子上施了加速魔法！"
D.Strings[43830]="我的速度快不快？我想要成为和你一样的$c ！"
D.Strings[43831]="喔，我们只是在玩！"
D.Strings[43832]="我猜，下次我需要跑得更快。"
D.Strings[43833]="我可不想呆在这里面！外面才好玩！"
D.Strings[43834]="你带我们到哪里去？我们真的必须走吗？"
D.Strings[43835]="我会在你的地图上把具体位置标出来。"
D.Strings[43836]="现在，我们将这个稻草人付之一炬。这是我们战胜宿敌的象征！"
D.Strings[43837]="我们心中只有无穷无尽的愤怒……"
D.Strings[43838]="%s望向前方洞穴入口，却找不到A-Me 01。"
D.Strings[43839]="%s一直睡不着。"
D.Strings[43840]="救命！我不会游泳！"
D.Strings[43841]="这边，$c！救救我！"
D.Strings[43842]="$c，万圣节到了。希望你能在这个节日中找到许多欢乐。"
D.Strings[43843]="我已经做好了飞行准备，让我们去轰炸幽暗城！"
D.Strings[43844]="呃，这到底是什么东西？尝起来像是湿狗毛！"
D.Strings[43845]="哪个神经正常的家伙会喝这种玩意儿？呸！"
D.Strings[43846]="我有没有看到什么可疑的东西？这里唯一可疑的就是那些高得离谱的价格。"
D.Strings[43847]="我什么都没看见。别用什么暮光之锤的事情来烦我。我还要晒日光浴呢。"
D.Strings[43848]="我似乎是看见了一些穿着暮光之锤长袍的家伙。我能确定的就是，他们的个子很高。"
D.Strings[43849]="我看见有人栽下了那种火焰图腾。那时天很黑，不过我记得他们穿着红色的衣服。"
D.Strings[43850]="可疑活动？主管助理韦德斯潘不想让任何人到湖北边去。你不觉得这很奇怪吗？"
D.Strings[43851]="没错，昨晚的聚会上，我就听到有人在谈暮光之锤的事。我没有看见说话的人是谁，不过他们的口气极为粗鲁。"
D.Strings[43852]="指控"
D.Strings[43853]="你好！真是令人愉悦的一天啊，对不对？"
D.Strings[43854]="你怎么敢指控我是暮光教徒！我得罪你了吗？"
D.Strings[43855]="<多德轻蔑地向你哼了一声。>$B$B你的动作还能再慢一点吗？我身边都是没用的白痴！"
D.Strings[43856]="嗨，我们以前见过吗？"
D.Strings[43857]="如果你想听我的建议，那么我告诉你，不要打得太厉害。你只是在刺激他们。"
D.Strings[43858]="如果你再爬上一级，我就把我的酒给你喝！"
D.Strings[43859]="嘿，我在享用铁炉堡蜜酒。这段时间里，我们可能只剩下这点酒了。"
D.Strings[43860]="是谁在上来的时候忘记拿啤酒了？可不是我！哈哈哈哈！"
D.Strings[43861]="别再喝我们最后的那点酒了，快来帮我弄掉这该死的树枝！"
D.Strings[43862]="也许能有人来帮我们离开这个该死的地方！"
D.Strings[43863]="我告诉过你，不要丢掉那些猪排骨！为什么你就不能像其他巴克伊家的人一样，有一副能好好吃饭的正经胃口？"
D.Strings[43864]="再靠近一点，我就一拳砸在你的脸上！"
D.Strings[43865]="喔！一座闹鬼的灯塔，一个海盗船长的幽灵，真是精彩啊！你认为他会告诉我们宝藏埋在哪里吗？"
D.Strings[43866]="圣光啊！看看水坝变成了什么样子！其他孤儿肯定不会相信的！"
D.Strings[43867]="喔，那头大熊还在这里！你觉得大家把财宝都放进他肚子里的时候，他会不会疯掉？那一定很疼……"
D.Strings[43868]="欢迎来到治愈者营地，$c。"
D.Strings[43869]="赞吉吉可以进行更多的战斗练习吗？"
D.Strings[43870]="有没有感觉到？阿尔萨斯仿佛还在这个房间里！但他已经不在了，对不对？只是这个地方还是让人感到邪恶……"
D.Strings[43871]="你在看什么？你这个海象脑袋的笨蛋？"
D.Strings[43872]="我的佣人哪？！"
D.Strings[43873]="恐怕关于老邓肯的故事只会让人徒增伤心。知道吗？我曾经是一名真真正正的船长。$b$b但现在只要再降一级，我就又要去洗甲板了。我可没办法承受这样的耻辱。"
D.Strings[43874]="邓肯，给我听着，快拿起拖把去干活。"
D.Strings[43875]="喔，这些码头可真大！停泊在这里的船一定也像飞艇一样大！这就是我能从奥格瑞玛看到的那片大海吗？"
D.Strings[43876]="我能从这里看到那些肮脏的暗夜精灵！等我长大以后，我要为酋长而战，就像这些战士一样！"
D.Strings[43877]="只要1个金币，帅小伙子邓肯就会为你擦甲板！"
D.Strings[43878]="有麻烦吗，水手？需要帮助吗？"
D.Strings[43879]="这太耻辱了。"
D.Strings[43880]="真不敢相信会是这样。"
D.Strings[43881]="拖把？真的？"
D.Strings[43882]="我想，有时候，在爬上去之前先要跌到最下面去。"
D.Strings[43883]="也许我需要一个新绰号。"
D.Strings[43884]="酋长，在我的年轻卫士心中，您是一位伟大的英雄。您是否介意为他签个名？"
D.Strings[43885]="当然，$c。那位年轻战士叫什么名字？$B$B真希望我们有更多的人能像你那样关心奥格瑞玛的孤儿。"
D.Strings[43886]="虽然我非常想念吉尔尼斯，但还有许多远古遗迹需要我去探索！"
D.Strings[43887]="蝌蚪！蝌蚪赢了！"
D.Strings[43888]="嗨！你好！怎么样，这里闻起来也是绿色的吧？"
D.Strings[43889]="比分是四十六比五十二！"
D.Strings[43890]="把那个旋转齿轮给我，你这个生了颗矮人脑子的人崽子！不，不是那个，是另一个！"
D.Strings[43891]="我是侏儒区闲话报的首席编辑！"
D.Strings[43892]="我从不说胡话！从不！"
D.Strings[43893]="提瑞斯法下方的黑暗会把我们全部吞没……"
D.Strings[43894]="淤泥怪要喝酒！"
D.Strings[43895]="我要学习考古学。"
D.Strings[43896]="财宝猎人的人生中充满了背叛与欺骗。别再犯傻了。"
D.Strings[43897]="从雾中涌出了许多蒸汽！在被它们吞噬之前赶紧击败撕心狼将军！"
D.Strings[43898]="发现敌人。防御模式启动。"
D.Strings[43899]="甲虫"
D.Strings[43900]="狗"
D.Strings[43901]="狐狸"
D.Strings[43902]="猴子"
D.Strings[43903]="页岩蜘蛛"
D.Strings[43904]="在托尔巴拉德，我们在巴拉丁监狱的兄弟都很忙，并非总是能及时为你提供援助。现在我驻扎在这里，就是为了帮你完成由他们分配给你的任务。"
D.Strings[43905]="你不属于这里！"
D.Strings[43906]="你打破入口进去了？！我要把你打破！"
D.Strings[43907]="赶快离开这里！"
D.Strings[43908]="厄祖玛特现在衰弱了，进攻！"
D.Strings[43909]="懦夫！我可不会这么容易就掉进你们的陷阱！"
D.Strings[43910]="你在这里！对抗邪恶的战斗正在进行，而你却像懦夫一样躲在这里？"
D.Strings[43911]="别跑啦，赶快做些什么！"
D.Strings[43912]="你们都是没胆气的懦夫！如果你们能显示些勇气出来，也许我真的会付给你们薪水的！"
D.Strings[43913]="白痴！白痴！笨蛋！低能儿！蠢货！傻瓜！呆子！我应该继续吗？"
D.Strings[43914]="也许应该有人去拿些水来。有脑子的家伙早就应该去干这件事了！"
D.Strings[43915]="你们这群傻瓜！这个地方真应该被烧掉。"
D.Strings[43916]="噩梦蜘蛛出现在黑暗中！在赫利克斯的噩梦吞噬你之前消灭他！"
D.Strings[43917]="$n，至今为止，你给我留下了深刻的印象。想不想帮我烹制出终极菜肴？"
D.Strings[43918]="|TInterface\\Icons\\spell_nature_cyclone.blp:20|t%s开始施放|cFFFF9A20|Hspell:86193|h [强风冲击]！|r"
D.Strings[43919]="%s开始复活一个|cFF3366CC赞吉利狂暴者|r！"
D.Strings[43920]="%s开始复活一群|cFFCC0000赞吉利僵尸|r！"
D.Strings[43921]="%s让这一区域充满了|cFF33FF00毒性瓦斯|r！"
D.Strings[43922]="呦喉！看看她跑得多漂亮！放松，尽情观赏周围的景色吧。我们很快就能驶过湖面了。"
D.Strings[43923]="喜欢这里吗？在蒸汽池里泡一泡，你出来的时候就能年轻10岁。你要是不信，就看看我吧！"
D.Strings[43924]="有没有试过厨师特兰姆塞的菜肴？我非常喜欢他的蛾肉汤。那可真是美味！"
D.Strings[43925]="等等，你看到那里的光亮了吗？出了什么事？"
D.Strings[43926]="他……他们是暮光之锤的间谍！和他们在一起的……是度假地主管助理吗？"
D.Strings[43927]="哦，不！他们发现我们了！抓紧——我们要马上逃走！"
D.Strings[43928]="我们差一点就没命了。你最好赶快跑到拉珊那里去，告诉她你看到的一切。我们有大麻烦了！"
D.Strings[43929]="我正在诺森德寻找其他久经战阵的老兵。我们迫切需要强大的战士去击退出现在家乡的新敌人。"
D.Strings[43930]="托尔巴拉德的战斗准备将在5分钟后开始！"
D.Strings[43931]="托尔巴拉德的战斗将在2分钟后开始！"
D.Strings[43932]="托尔巴拉德的战斗将在1分钟后开始！"
D.Strings[43933]="黑暗正在逼近！除非拼死一搏，否则我绝不会离开，怪物！"
D.Strings[43934]="嗨，我的名字是凯文。你想演电影吗？"
D.Strings[43935]="我想要与夺灵者战斗，但我没有办法召唤他。你能帮助我吗？"
D.Strings[43936]="托尔巴拉德的胜利是我们的囊中之物！部落的防御已经崩溃，我们需要你立即去收集资源并参与保卫这座岛屿！"
D.Strings[43937]="托尔巴拉德的胜利是我们的囊中之物！联盟的防御已经崩溃，我们需要你立即去收集资源并参与保卫这座岛屿！"
D.Strings[43938]="你好啊，倒霉的冒险者。我只会让你们付出一点点时间……和许多的血！"
D.Strings[43939]="如果你想找一个地方休息，那么我能帮上忙。"
D.Strings[43940]="在这么多战友中，你单单选择我的躯体对抗亡灵？那好吧。"
D.Strings[43941]="燃烧吧……我的躯体……不要让我成为它们的一员……"
D.Strings[43942]="计划收入减去弹性需求的供给支出，考虑到衰减函数中的资产和负债曲线……哦，嗨！你好啊？"
D.Strings[43943]="你够格待在我的厨房里吗？"
D.Strings[43944]="见识过这里可怕的物价了吗？"
D.Strings[43945]="能给我拿些喝的来吗？我正在晒日光浴，没法去拿饮料。"
D.Strings[43946]="暮光之锤将再次崛起！你们脚下的大地将被我们复苏时的怒火吞噬！"
D.Strings[43947]="我眼前朦朦胧胧的，什么都看不清，但我很清楚这股气味！去死吧，肮脏的食人魔！"
D.Strings[43948]="哦…………"
D.Strings[43949]="老杜甘要去瘟疫之地，把那些天灾恶鬼全都赶回到地里去。"
D.Strings[43950]="风把死亡的气息带往所有地方，一切都因之而凋敝。"
D.Strings[43951]="当他到了那里的时候，他的矮人眼睛会看到什么？"
D.Strings[43952]="那里有上百箱的大麦会被酿成美酒！"
D.Strings[43953]="但那些美酒受到了死亡的诅咒，现在，老杜甘也被诅咒了。"
D.Strings[43954]="老杜甘被巫妖王的爪牙包围了，老杜甘能做些什么？"
D.Strings[43955]="虽然我感觉到了体内的诅咒，但是我的希望并没有泯灭。"
D.Strings[43956]="如果我真的会成为天灾恶鬼，那我最好还是先喝醉了吧！"
D.Strings[43957]="这个传送器将把你传送至北荆棘谷的格罗姆高那里。$B$B通常都会是这样。$B$B我的意思是说，有时候它会把你分解，或者让你全身的软组织都变成散发着臭气的绿色烟雾。不过大多数情况下它还是安全的！$B$B……大多数情况。"
D.Strings[43958]="这个传送器将把你传送至丹莫罗地下深处，那个充满辐射的诺莫瑞根废墟。$B$B别担心，那里还有另一个传送器，可以把你送回到这里……嗯，它也有可能让你身体的里里外外彻底翻转过来，或者把你全身的组织变成不稳定的有机爆炸物，就是这样！$B$B怎么啦？你还在等什么？跳进去吧！"
D.Strings[43959]="终于摆脱阿比迪斯那个疯婆娘了，我现在可以去追求我自己的目标了：鲜血，鲜血，更多的鲜血！"
D.Strings[43960]="我已经有好几周没吃过东西了，这块面包是我的！为了三明治！"
D.Strings[43961]="我断定……你很美味！"
D.Strings[43962]="阿比迪斯会回来的，我会一直等待她的归来！为了我们，她一定会回来的！"
D.Strings[43963]="我会把你在这片森林中留下的恶臭清除干净，怪物！"
D.Strings[43964]="朋友，欢迎参加这场盛宴。瞧瞧这次我都给你们准备了什么好戏。"
D.Strings[43965]="没人能阻止金度！"
D.Strings[43966]="草、沙子和软泥混合在一起，差不多就是这些脚印的样子。"
D.Strings[43967]="这些脚印都有涂抹的痕迹，就好象这只生物是拖着脚行走一样。"
D.Strings[43968]="这些泥巴中还混合着来自于附近钻探设备的油性软泥。"
D.Strings[43969]="这些足迹中带有血污。你跟随着它们，找到了附近的一个灌木丛。这里隐藏着这只怪物吃过的猎物残骸。"
D.Strings[43970]="这些足迹是刚留下的，直接指向了水中……"
D.Strings[43971]="布拉克有没有说过，这个传送器是否进行过测试？嗯，如果你准备好了要返回诺兹波特的哨站，就说一句！希望你能完整无缺地到达那里。"
D.Strings[43972]="看到了吗？有人从天上掉下来了！"
D.Strings[43973]="送我回诺兹波特的哨站。"
D.Strings[43974]="喔，这可真快啊！"
D.Strings[43975]="哈哈哈哈哈！无信者……面对贝瑟克的真正力量！"
D.Strings[43976]="你做了什么？我……不能控制……啊啊啊呃！"
D.Strings[43977]="$n，你还活着？这太好了！刚才我看见一支火箭飞上了半天，还听见你在尖叫，不由得有些担心。$B$B我们还有最后一批货要运。准备好以后就来找我，然后我们就出发。"
D.Strings[43978]="所有人都准备好了！商队将前往莫尔杉农场！"
D.Strings[43979]="那里的路况怎样？希望不要太颠簸。"
D.Strings[43980]="在这么靠近十字路口的地方，敌人不敢攻击我们。但继续前进的话，我们就要提高警惕了。"
D.Strings[43981]="希望你不要介意，我们要在鬼雾营地装载另一批补给品，并让拉车的牲口得到休息和食水，为最后一段路程做好准备。"
D.Strings[43982]="布温巴能帮得上你吗？"
D.Strings[43983]="对，承受这死亡的剧毒……"
D.Strings[43984]="我需要你的帮助，才能除去这些冒险者身上的毒。"
D.Strings[43985]="你在寻求力量？但你能走过我铺下的诅咒之路吗？"
D.Strings[43986]="我的道路是黑暗的，受到诅咒的。$c，你不会想要和我同行的。"
D.Strings[43987]="我们来了。别着急，先等我们装货……嘿！出什么事了！？"
D.Strings[43988]="快点！抓活口。我去对付补给车！"
D.Strings[43989]="公会服务"
D.Strings[43990]="你能在城市正中，圣光广场中心的建筑物里找到沙塔斯的公会管理员——以及公会和战袍商人。"
D.Strings[43991]="感谢你的帮助。"
D.Strings[43992]="职业训练师都在圣光广场中心建筑物一层的各翼区中。$B$B无论是奥尔多，占星者还是其他什么人，总有人能帮助你的。"
D.Strings[43993]="另一个巨魔？至少你不是一条毒蛇……"
D.Strings[43994]="到处都是毒蛇！"
D.Strings[43995]="毒蛇要淹没我们了。"
D.Strings[43996]="我还以为自己要死在这片可怕的丛林中了。"
D.Strings[43997]="谢谢你救了我的命。"
D.Strings[43998]="<奥术守护者指了指城市中心。>"
D.Strings[43999]="哦，娜格拉！给你饥饿的兄弟来些午餐如何？"
D.Strings[44000]="你的腰变粗了几寸，小兄弟！到这里来，给你的姐姐一个拥抱吧！"
D.Strings[44001]="我应该对付哪个？"
D.Strings[44002]="巴尔格！不！"
D.Strings[44003]="攻击那些梦魇幻象，保卫你熟睡的盟友！"
D.Strings[44004]="布温巴正在盯着你，年轻人。"
D.Strings[44005]="现在，尝尝金度真正的力量吧！"
D.Strings[44006]="就是那个肥家伙！他会是个好祭品。"
D.Strings[44007]="火刃向你们致以问候。"
D.Strings[44008]="小心，有人正在进攻哨兵岭。卫兵们，一定要打败敌人！"
D.Strings[44009]="我还从没有见过一棵飞行的树呢。让我们再靠近些！"
D.Strings[44010]="这看上去真有趣！我真想自己驾驶一下。但监护员说我年纪还太小，不能有坐骑。"
D.Strings[44011]="小心那些软泥怪。有一个直冲我过来了！"
D.Strings[44012]="啊，它跑到我的头顶上了！救命！"
D.Strings[44013]="%s要用闪电轰击你了！快闪！"
D.Strings[44014]="我有点想吐……"
D.Strings[44015]="喔！有没有看到我们飞了多高？"
D.Strings[44016]="这太棒了！我们再来一次吧！"
D.Strings[44017]="荆棘谷每一块岩石和灌木之下都潜伏着我的毒蛇。"
D.Strings[44018]="我们会重夺这片土地。古拉巴什之地。阻挡者都要死！"
D.Strings[44019]="我们要夺回我们的古拉巴什。任何敢阻挡我们的人，只有死路一条。"
D.Strings[44020]="攻击他们，奥根！我们不会再被愚弄了！"
D.Strings[44021]="萨满祭司……？一个神秘的巨魔最近来到这里拜访长者步道的哈雷尼。她也许能帮助你。"
D.Strings[44022]="我还以为这个公园已经变成了一个大洞。但现在，它更大了，还有了一个大旋风！"
D.Strings[44023]="他们要把我当作祭品！他们的魔鬼就要在我的尸体上舔它们的刀刃了。$B$B<巴尔格打了个哆嗦。>$B$B这让我一点吃东西的胃口都没有。$B$B他们安排了一名卫兵时刻监视着我。我能自己离开这里，但我需要有人吸引卫兵的注意力。"
D.Strings[44024]="什么！？火刃绑架了我的兄弟？"
D.Strings[44025]="全部前往北方灰谷的运输队都会在这里停留，休息并补充食水。确保这里一切工作正常是非常重要的。"
D.Strings[44026]="有两个牛头人来到了这里。我听说他们从莫高雷来，想要了解更多关于被遗忘者的“状况”，或者是与之相关的一些事。$B$B你可以在炼金房的草药师旁边找到他们。"
D.Strings[44027]="|TInterface\\Icons\\ability_heroicleap.blp:20|t%s开始施放|cFFFF0000|Hspell:96740|h[毁灭猛击]|h|r！"
D.Strings[44028]="这一定是全世界最大的钻石！"
D.Strings[44029]="这看上去就像是麦格尼国王的雕像！他真的是自己把自己弄成这样的？"
D.Strings[44030]="是啊，孩子。他曾经想借助一个古老的泰坦仪式保护他的人民，但这也让他自己变成了这种样子。"
D.Strings[44031]="喔，我可不认为这是个好主意……"
D.Strings[44032]="你们失去了自己的国王，真可怜。但从某种意义上来说，他将永远和你们在一起！"
D.Strings[44033]="他们发现我们了！保卫商队！"
D.Strings[44034]="这都是我的错，吾王。我应该对那些石板进行更多研究的……"
D.Strings[44035]="谢谢你，孩子。"
D.Strings[44036]="欢迎，我的$g兄弟:姐妹;。如果你是要来接受训练，我很高兴能满足你的要求。"
D.Strings[44037]="如果你在寻求古老的技艺，那我无法帮助你。"
D.Strings[44038]="城门外有一个名叫达伦斯的狼人德鲁伊。他也许能帮助你。$B$B他是一头高大的猛兽，身披白色皮毛。你不可能认错他的。"
D.Strings[44039]="喔，你和我以前见过的暗夜精灵都不一样！"
D.Strings[44040]="我们的监护员说，德鲁伊能够变成鸟、豹子和熊。但你看上去像是所有这些野兽的组合！"
D.Strings[44041]="我知道你在干什么。你要结合全部德鲁伊形态，变出一个超级德鲁伊来！"
D.Strings[44042]="听起来，翡翠梦境不像是一个适合我去的地方。如果我变成一只海龟该怎么办？我一直都想要一对翅膀，但……"
D.Strings[44043]="喔！我是个小鸟男孩了！"
D.Strings[44044]="不，小家伙，不是这样的。我的灵魂在翡翠梦境中渡过了许多岁月；而我的肉体一直在沉眠之中。于是它开始呈现出我们各种动物形体的属性。"
D.Strings[44045]="你好！需要拧紧螺丝或者松开栓钉吗？你可是来对地方了。"
D.Strings[44046]="饿……啊！！！"
D.Strings[44047]="我很……难过……"
D.Strings[44048]="喔，喔，喔！我真不敢相信，斯布特瓦夫竟然真的允许我驾驶这个小家伙！我有没有说过，这是我的第一次飞行？别担心。一切都在我的控制之中。"
D.Strings[44049]="天哪，哦，天哪……看看这惊人的景色！那些是狮子吗？哦，我差一点松开了操纵杆。"
D.Strings[44050]="等基地里的那些家伙去查个清楚吧！它已经完全失控了！"
D.Strings[44051]="我的梦想是有一天成为像斯布特瓦夫那样的超级技师。你真应该看看他设计的只有两只轮子的三轮车！"
D.Strings[44052]="嗯？等等，发动机停转了……"
D.Strings[44053]="喔！出了什么事？"
D.Strings[44054]="不，不，不……这不可能。这不是旅行计划的一部分！"
D.Strings[44055]="啊！看样子，我们发现了一条意想不到的捷径！抓紧！"
D.Strings[44056]="也许，如果我按下绿色按钮。不，蓝色的如何？等等，让我试着改动一些接线。哦！"
D.Strings[44057]="没有用！"
D.Strings[44058]="哦，不，斯布特瓦夫一定会杀了我的！唉……剩下的路你自己走吧，我还要把火箭残骸收集好，踏上返回营地的漫漫长路……"
D.Strings[44059]="我们到了，平安返回十字路口。"
D.Strings[44060]="当温诺希斯开始准备一个强大的法术时，赫希斯祭坛周围的迷雾消散了。"
D.Strings[44061]="|TInterface\\Icons\\ability_creature_poison_06.blp:20|t高阶祭司温诺希斯开始施放|cFFFF0000|Hspell:96637|h[血毒触须]|h|r！"
D.Strings[44062]="高阶祭司温诺希斯疲惫了！"
D.Strings[44063]="我没法让它停下来。我们要坠毁了！"
D.Strings[44064]="调查这具尸体。"
D.Strings[44065]="这只大猫似乎并不像猎人向你描述的那样大。"
D.Strings[44066]="让我们看看，这里有些什么……"
D.Strings[44067]="嗯……这头野兽比我想的要小。"
D.Strings[44068]="你们都要去死！"
D.Strings[44069]="塞瑞娜·血羽会挖出你的眼睛，吃掉你的心！"
D.Strings[44070]="我要为死去的姐妹报仇！"
D.Strings[44071]="我们的主人很喜欢你的鲜血！"
D.Strings[44072]="雷克萨的帮凶！刽子手！"
D.Strings[44073]="银色北伐军支持你。"
D.Strings[44074]="嗯……嗯。"
D.Strings[44075]="是……塞尔杜林！"
D.Strings[44076]="见习萨满金矿，报到！"
D.Strings[44077]="这里将有一场屠杀。一场……烈焰的屠杀！"
D.Strings[44078]="不要害怕。强尼·傲森和你并肩战斗。"
D.Strings[44079]="两把利刀和一个地精。你还能再要求些什么？"
D.Strings[44080]="有人需要圣骑士吗？"
D.Strings[44081]="指挥官，这边。"
D.Strings[44082]="喂，骑士们！我们是否已经束带贯甲，全副武装？那就让我们勇敢地踏上他们所说的冒险征程吧！"
D.Strings[44083]="我的剑将为你挥舞。"
D.Strings[44084]="让我们看看，今天能遭遇些什么灾难。"
D.Strings[44085]="Lok'tar，英雄。今天，我将与你并肩奋战。"
D.Strings[44086]="我的利爪会将你撕成碎片，入侵者。"
D.Strings[44087]="让战争开始吧。"
D.Strings[44088]="赞吉吉来了！"
D.Strings[44089]="大地之环支持你。"
D.Strings[44090]="在海加尔山，仁德会的德鲁伊将支持你的行动。"
D.Strings[44091]="我听说艾泽拉斯需要拯救。我能出些力吗？"
D.Strings[44092]="我更希望我的鱼在被捉住以后可以煮熟，让我们扑灭这些火吧。"
D.Strings[44093]="隆克来帮忙了。"
D.Strings[44094]="暗矛与你一同战斗。"
D.Strings[44095]="报到，指挥官。"
D.Strings[44096]="让我狠狠地教训他们！我要把他们轰到山下去！"
D.Strings[44097]="祝贺你，今天你将得到与我一同作战的荣耀。"
D.Strings[44098]="火元素必死！"
D.Strings[44099]="等等……我在哪里？这是什么时候？我是在海加尔吗？"
D.Strings[44100]="卡尔德·格雷，报丧……呃，报到。"
D.Strings[44101]="有人提到钩锤吗？没有？好吧，我在这里。"
D.Strings[44102]="要是吉德文在这里就好了……他一定会想看看这个的。"
D.Strings[44103]="圣光净化！"
D.Strings[44104]="哈！我一直在等待一场挑战。"
D.Strings[44105]="哈！听命！"
D.Strings[44106]="你可真不幸……我带着我的拳头呢！"
D.Strings[44107]="小心拉格纳罗斯！你是下一个！"
D.Strings[44108]="要知道，我研究火元素已经有一段时间了。我想，在这方面我应该是个专家。"
D.Strings[44109]="没错！这些家伙真的很热！"
D.Strings[44110]="也许经历过这些事之后，他们会去掉我的“见习”头衔。"
D.Strings[44111]="哦，不要逼我召唤我的巨魔仆人。"
D.Strings[44112]="见识古尔戈索克的力量吧！"
D.Strings[44113]="你将进入专属于你的痛苦竞技场，蠢货！"
D.Strings[44114]="哈哈！好啊！"
D.Strings[44115]="强尼！傲森！"
D.Strings[44116]="你根本就没有机会！"
D.Strings[44117]="杀杀杀杀！"
D.Strings[44118]="你在说什么？我听不清你说话，因为我的刀子在你的脸上！"
D.Strings[44119]="哦，没错。史莉琪要砍你。"
D.Strings[44120]="没有人告诉过我，这些家伙会有多么大。"
D.Strings[44121]="尝尝这个，恶心的火驴子！"
D.Strings[44122]="为了北伐军！喝！"
D.Strings[44123]="我一直都想要我自己的龙！"
D.Strings[44124]="来承受你的痛苦吧！"
D.Strings[44125]="我是……属于大海的……牛头人！"
D.Strings[44126]="死在我手中吧，卑劣的白痴！"
D.Strings[44127]="自豪吧，恶龙。今天，你将死于艾泽拉斯最伟大的英雄剑下。也将死在我的剑下。"
D.Strings[44128]="真好玩！我能留下这只风筝吗？求求你了！"
D.Strings[44129]="饶恕我，公主！"
D.Strings[44130]="啊孩子！我饿得连火元素都可以吃掉了！"
D.Strings[44131]="我不习惯同其他人作战。"
D.Strings[44132]="我给你一个建议：现在就死吧。"
D.Strings[44133]="他们从前都管我叫托尼·三牙。"
D.Strings[44134]="我要让你掉进痛苦的陷坑里。"
D.Strings[44135]="为了被遗忘者！为了洛丹伦！"
D.Strings[44136]="这个家伙不会回来了。"
D.Strings[44137]="我可不会可怜你。"
D.Strings[44138]="我的妻子死了，你们这些怪物！"
D.Strings[44139]="赞吉吉真的想现在就变形……"
D.Strings[44140]="塞纳里奥议会是不会放过你的，伙计！"
D.Strings[44141]="对于像赞吉吉这样强大的德鲁伊，这不是问题。"
D.Strings[44142]="没有人能逃过圣光的审判。"
D.Strings[44143]="忏悔你的罪行，求得宽恕吧！"
D.Strings[44144]="从艾泽拉斯滚出去！"
D.Strings[44145]="艾泽拉斯不欢迎你！"
D.Strings[44146]="这些憎恶造成了几十只松鼠的死亡！它们不应得到任何怜悯！"
D.Strings[44147]="不投降！不宽恕！为了艾泽拉斯！"
D.Strings[44148]="MRGLLL GLRRM GL！翻译过来：我要杀了你！"
D.Strings[44149]="我们食人魔也不都是恶棍。"
D.Strings[44150]="你得到了奥格瑞拉的支持。"
D.Strings[44151]="这个被你称为艾泽拉斯的世界是我们的朋友。很高兴能尽我所能为你提供帮助。"
D.Strings[44152]="鱼钩，鱼线，还有屠杀！"
D.Strings[44153]="这并不是我擅长的领域，不过很高兴能帮忙。"
D.Strings[44154]="我应该打个盹了。"
D.Strings[44155]="赶快滚！"
D.Strings[44156]="隆克最后一次警告你！"
D.Strings[44157]="隆克不杀人！！"
D.Strings[44158]="元素与我们同在！"
D.Strings[44159]="这些灵魂将不复存在！"
D.Strings[44160]="为了暗矛！"
D.Strings[44161]="从奥格瑞玛建立时起，我的家族就在经营贫瘠之地的运输商队。我们养育并训练科多兽。我的姐姐娜格拉是莫高雷以外最优秀的科多兽养育者。"
D.Strings[44162]="自然的愤怒将吞没你！"
D.Strings[44163]="海加尔永不陨落！"
D.Strings[44164]="赞颂远古神灵！"
D.Strings[44165]="砰！正中眉心！"
D.Strings[44166]="打猎很刺激，对不对，小伙子们？！"
D.Strings[44167]="我为你准备了一个礼物！来吧，我这就把它从我的枪膛里掏出来……"
D.Strings[44168]="你接受了试炼……并且失败了。"
D.Strings[44169]="这是烈火对烈火的时刻！还有寒冰！还有暗影！"
D.Strings[44170]="你落进了我的陷阱！"
D.Strings[44171]="我想，我已经把这家伙打得不省人事了。"
D.Strings[44172]="我从达拉然一路来到这里，这就是我得到的欢迎吗？"
D.Strings[44173]="议会已经宣布驱逐你，而我则要执行议会的命令。"
D.Strings[44174]="难以相信，你们还在海加尔奋战。你应该明白随后将要发生什么。"
D.Strings[44175]="你知道现在是什么时刻？没错，现在是死亡的时刻！"
D.Strings[44176]="让克罗米来教训你！"
D.Strings[44177]="没什么能比濒死者的尖叫声更让我喜欢，特别是当他们死在我手中的时候。"
D.Strings[44178]="你知道这些火焰怪物最糟糕的地方是什么？没有任何可供收集的器官。"
D.Strings[44179]="火焰和岩石对我来说没有任何意义，我更喜欢有血有肉的敌人。"
D.Strings[44180]="你知道吗？你让我想起了我曾经制造过的步行篝火原型机。"
D.Strings[44181]="如果你能躲开双二进制流变振波自动扳手，你就能躲开炮弹！"
D.Strings[44182]="我是天才！"
D.Strings[44183]="什么，我们已经结束了吗？"
D.Strings[44184]="再会吧！"
D.Strings[44185]="大家都会知道这件事的！"
D.Strings[44186]="很高兴为你服务！"
D.Strings[44187]="快回来为我工作。我是个忙碌的地精！"
D.Strings[44188]="虽然我的离开可能会让你难过，不过我相信，你会带着笑容眺望我的背影。"
D.Strings[44189]="嗨，和你在一起可真痛快！如果你还有敌人，一定要让我知道。"
D.Strings[44190]="北伐军感谢你在这里所做的一切，$n。"
D.Strings[44191]="感谢你让我有机会同拉格纳罗斯一战。"
D.Strings[44192]="在恐怖的灾难之前，你显示了真正的勇气与骑士精神。作为一个英雄主义的楷模，我向另一个同样的楷模敬礼！"
D.Strings[44193]="打得好。再见，英雄。"
D.Strings[44194]="下次再见！一定要活着啊！"
D.Strings[44195]="你战斗得非常英勇，英雄。期待能再次与你并肩作战。"
D.Strings[44196]="返回瘟疫之地！"
D.Strings[44197]="战士们，拿出勇气来。"
D.Strings[44198]="请记住，你在深岩之洲有朋友。如果有需要，就请来找我们。"
D.Strings[44199]="这样，我就能回到我的研究中去了。"
D.Strings[44200]="我该回奥格瑞拉去了。希望你不要忘记我们，就像我们永远不会忘记你。"
D.Strings[44201]="再见，感谢你的英勇奋战！"
D.Strings[44202]="隆克觉得你杀掉了太多坏家伙，但隆克依然觉得你是个好$g家伙:女孩;。"
D.Strings[44203]="感谢你让我有机会痛快杀敌。我会向沃金报告你的功绩。"
D.Strings[44204]="在彻底治愈海加尔山以前，我绝不会停止奋战。"
D.Strings[44205]="希望你能像我一样得到许多乐趣。"
D.Strings[44206]="这是在浪费我的时间。"
D.Strings[44207]="再见……你知道哪里可以找到我。"
D.Strings[44208]="我必须走了。这些杀戮让我想起来还有很多尸体没缝好。"
D.Strings[44209]="成功完成！返回实验室！"
D.Strings[44210]="我的怒火并未平息……只是我的心情暂时平静了一些。"
D.Strings[44211]="大家暂停攻击！"
D.Strings[44212]="停手，英雄们。这头龙的鳞正在闪耀鲜红的火光。"
D.Strings[44213]="所有人，停止攻击！"
D.Strings[44214]="停止攻击！"
D.Strings[44215]="收起武器！"
D.Strings[44216]="当护盾升起来的时候停止攻击！"
D.Strings[44217]="停止攻击！它的护盾将会粉碎你们。"
D.Strings[44218]="你也许还不知道，科多兽每天可以吃下相当于自身体重的草食。所以，每天从它们的另一头排出的东西也需要打扫很久。"
D.Strings[44219]="来自艾泽拉斯各地的手工玩具！"
D.Strings[44220]="我可以听见火刃氏族的战吼，科多兽已经准备好，随时可以前往莫尔杉农场。当你准备好出发的时候就告诉我。"
D.Strings[44221]="当护盾升起来的时候不要攻击！"
D.Strings[44222]="现在不行，凡人。$b$b我到此地有重要的事要做。"
D.Strings[44223]="让我们瞧瞧这家伙怎么了？"
D.Strings[44224]="赫希斯之耳语即将毒害你的心灵！"
D.Strings[44225]="我要把你的血变成剧毒！"
D.Strings[44226]="基尔娜拉疯狂地笑了起来。"
D.Strings[44227]="你——你杀了我的猎豹！为什么我要遭这种罪？"
D.Strings[44228]="荆棘谷属于古拉巴什。赶快离开，否则就埋了你。"
D.Strings[44229]="想留下也可以。我们的祭品总是不够用。"
D.Strings[44230]="刚才真是死里逃生，但我们成功做到了！我从来没有这样射击过……从来没有！我希望我们可以有机会再次一同骑乘，但卡德拉克有更重要的任务交给你。谢谢你把我们安全送达目的地，我的朋友。"
D.Strings[44231]="谢谢你，老朋友。我们的勇士感谢你。"
D.Strings[44232]="很高兴再次见到你，朋友。趁道路仍然畅通，赶紧上来吧。"
D.Strings[44233]="保持警惕！他们从后方包抄过来了！"
D.Strings[44234]="小心上空！使用你的火箭！"
D.Strings[44235]="他们从四面八方涌来了！再坚持一下，我们快到了！"
D.Strings[44236]="盖伦格斯遭到了玛洛恩鹿角的削弱！赶快攻击他！"
D.Strings[44237]="打得不错！那家伙短时间内是起不来了。"
D.Strings[44238]="不要生气，$r。$b$B我只是没时间分心而已。"
D.Strings[44239]="原谅我的无礼，$c。$b$b我必须全神贯注于紧迫的事情。"
D.Strings[44240]="啊啊！这是什么意思？！"
D.Strings[44241]="你们的努力值得赞赏……但光凭你们这些小东西是打不倒盖伦格斯的！我是刀枪不入的！"
D.Strings[44242]="啊！是你啊，$n。$b$B我必须马上和你谈谈。"
D.Strings[44243]="在我面前你们毫无机会！"
D.Strings[44244]="你们谁敢上前挑战盖伦格斯？上前来吧，懦夫！"
D.Strings[44245]="古拉巴什将夺回我们的土地。"
D.Strings[44246]="我们让你待得太久了。"
D.Strings[44247]="你自以为强大。你自以为勇敢。你自以为能活下来。"
D.Strings[44248]="但我们知道……"
D.Strings[44249]="你和你的族类，你们都要死了。"
D.Strings[44250]="你们死后都要服侍古拉巴什。"
D.Strings[44251]="杀掉这些虫子！"
D.Strings[44252]="欢迎来到冰锥甜筒，朋友！我们的冰激凌味道独一无二，冰寒爽口，是暴风城最优秀的法师学徒特别定制的！"
D.Strings[44253]="|TInterface\\Icons\\inv_misc_eye_04.blp:20|t%s开始施放|cFFFF0000|Hspell:96920|h[欧库塔尔之眼]|h|r！"
D.Strings[44254]="火箭将在3秒内发射……"
D.Strings[44255]="火箭将在2秒内发射……"
D.Strings[44256]="火箭将在1秒内发射……"
D.Strings[44257]="嘘！我躲在这里呢。"
D.Strings[44258]="我们认识吗？"
D.Strings[44259]="我听说托尔托拉被囚禁在此处，所以我以最快的速度赶来了。$b$b海加尔山真高啊！"
D.Strings[44260]="你准备好面对涅墨西斯了吗？我希望你能善用你的图腾。$b$b当你需要召唤他的时候跟我说一声。"
D.Strings[44261]="我准备好见阿纳克洛斯了，齐拉多尔米。"
D.Strings[44262]="我准备好面对涅墨西斯了，图加。"
D.Strings[44263]="就是现在，年轻人！攻击传送门！为了托尔托拉！"
D.Strings[44264]="我准备好见阿纳克洛斯了，克里多尔米。"
D.Strings[44265]="你不会想走这条路的，朋友。这里的灵魂狂躁不息。\n\n也许，如果你对上古神器有所了解，就能找到让灵魂安息的方法。"
D.Strings[44266]="别再等待了，$n。$b$b阿纳克洛斯正在等你！"
D.Strings[44267]="攀爬。"
D.Strings[44268]="将你们的肉体献给赫希斯，我的兄弟们！巫毒会保护你们的！"
D.Strings[44269]="虽然这件神器来自远古时代，但你无法感觉到它散发出任何特殊的气息。"
D.Strings[44270]="这件神器看起来是完整的，不过由于被厚厚的泥土掩盖而很难确定。看起来它并不蕴含任何远古魔法能量。"
D.Strings[44271]="这件神器经历了多年的风吹雨打，早已失去了往日的光芒。很难相信它是否还蕴含着什么力量。"
D.Strings[44272]="这个物件粘着了些许树叶和杂枝，显示出它曾被某种生物用来筑巢。除此以外，这东西就没有什么值得注意的地方了。"
D.Strings[44273]="这个器物表面有一些奇怪的刻痕，也许是巨魔尝试用来解开它的起源之谜的。看起来他们并未获得成功，因为该物件原封未动。"
D.Strings[44274]="神秘的符文装饰着这件神器，不过他们现在看似并无能量。"
D.Strings[44275]="这个物件质量低劣，很可能是充斥黑市的假冒伪劣产品。"
D.Strings[44276]="该物件上残留着斑斑血迹，很可能是巨魔们在争夺它时留下的。然而这个物件本身平凡无奇，其实并不值得争抢。"
D.Strings[44277]="露比，想要奖励么？"
D.Strings[44278]="露比，装死。"
D.Strings[44279]="露比，说话，"
D.Strings[44280]="露比，跳"
D.Strings[44281]="露比，后退。"
D.Strings[44282]="露比，跳舞。"
D.Strings[44283]="露比，好女孩！"
D.Strings[44284]="真是头好恐龙！"
D.Strings[44285]="你是个聪明的女孩，对不对？"
D.Strings[44286]="呀！真是惊人啊！"
D.Strings[44287]="哇，我从来不知道法师还可以做冰激凌。这太棒了！"
D.Strings[44288]="我长大以后，也要把各种怪东西拼起来！"
D.Strings[44289]="不如……在叉子上擦点肥皂？这样就万事俱备啦！"
D.Strings[44290]="肥皂消退的时候，你就拥有一把崭新的叉子了！"
D.Strings[44291]="这件神器有些奇怪……"
D.Strings[44292]="这件神器遭到了巨魔巫医的诅咒！被你碰触了之后，它开始发出邪恶的光辉。"
D.Strings[44293]="轻松点，凡人。我们必须在不紧张的情况下有效交流。$b$b当然这主要取决于你是否思路清晰且明辨事理。"
D.Strings[44294]="让我们看看你都在卖些什么。"
D.Strings[44295]="孩子们，$n给你们带来了一件礼物！来看看吧！"
D.Strings[44296]="喔，真是一个惊喜！我喜欢惊喜！"
D.Strings[44297]="嘭！我吓到你了没？$b$b万圣节只有两件事最重要：糖果和捣乱！大人们觉得还有别的更重要的事情，他们想向我灌输他们的想法，但我觉得除了点火以外都太无聊了，那真的很酷！$b$b但话说回来，就算是点火也会无聊的。你知道什么永远不会无聊吗？给别人捣乱和吃糖果！$b$b但我只想要一种糖果，就是糖果硬币！那是最棒的糖果，看起来像真的金币一样！而且如果你嫌硬币太多的话，你可以吃掉它们！感觉就像钱多得可以当饭吃一样！那太疯狂了！$b$b你有想要交易的硬币吗？"
D.Strings[44298]="娜格拉一定会切好她拿手的炙烤斑马肉等我们。她说我需要节食并多吃点蔬菜，但我觉得我还没那么胖吧……你说呢？"
D.Strings[44299]="我有一些想交换的糖果硬币。"
D.Strings[44300]="要糖！"
D.Strings[44301]="救命！放开我！"
D.Strings[44302]="这是最好的！"
D.Strings[44303]="是的，阿纳克洛斯。我准备好见证你所预见的未来了。"
D.Strings[44304]="哦，露比，你真是最好最好的宠物！"
D.Strings[44305]="你好，$c。我的名字是索克。以酋长的名义，我指挥这里的防御。$B$B你已经在十字路口立下了许多功绩。继续为部落而奋战吧！"
D.Strings[44306]="看着我，我是乌瑟尔·光明使者！"
D.Strings[44307]="这是我见过的最大的剑！"
D.Strings[44308]="喷射！喷射！喔啊啊！！"
D.Strings[44309]="你太放肆了，金度，你竟敢把远远凌驾于你的力量当作儿戏。难道你忘了我是谁？难道你忘了我能做什么？"
D.Strings[44310]="想找深山珠宝矿业协会，去大锻炉北侧吧。"
D.Strings[44311]="你可以在军事区内环找到珠宝加工训练师和供应商。"
D.Strings[44312]="去军事区内环。你会在那里找到珠宝加工匠人。"
D.Strings[44313]="出……出了什么事？我只记得自己要坐下吃东西……"
D.Strings[44314]="僵尸……到处都是！"
D.Strings[44315]="我们刚刚要吃东西，僵尸突然就出现了！"
D.Strings[44316]="食物，食物有问题！"
D.Strings[44317]="哦，我的肚子……那食物真的很糟糕。"
D.Strings[44318]="听好了，凡人。"
D.Strings[44319]="无数的时间线编织成了我们的时光之网。"
D.Strings[44320]="作为时光守护者，我们青铜龙军团一直在观察它们无尽的组合。"
D.Strings[44321]="当观察者发现了时间的扰动后，我们将负责修复。"
D.Strings[44322]="一个刚刚发生的事件，掩没于强大的魔法中，即便对我来说也很神秘……"
D.Strings[44323]="但是，这注定的结果已经很清楚了："
D.Strings[44324]="艾泽拉斯将会毁灭！"
D.Strings[44325]="事件的细节仍然扑朔迷离，但我确定了一件事……"
D.Strings[44326]="艾泽拉斯的命运将维系在一位凡人德鲁伊身上。"
D.Strings[44327]="艾泽拉斯的命运将维系在一位凡人法师身上。"
D.Strings[44328]="艾泽拉斯的命运将维系在一位凡人牧师身上。"
D.Strings[44329]="艾泽拉斯的命运将维系在一位凡人萨满身上。"
D.Strings[44330]="艾泽拉斯的命运将维系在一位凡人术士身上。"
D.Strings[44331]="你就是那个能肩负重担的凡人吗？"
D.Strings[44332]="幼崽伸出小爪子想去捕捉一只小虫子，当玩物飞走时它才注意到你在看它。"
D.Strings[44333]="幼崽用鼻子蹭了蹭你的手，心满意足地发出了咕噜咕噜的叫声。"
D.Strings[44334]="你可以在战士区找到铁匠和他的助手，就在护甲和武器供应商附近。"
D.Strings[44335]="幼崽向空中挥动着它的小爪子，看来他已经迫不及待想试试他的打猎技巧了。"
D.Strings[44336]="幼崽闻了闻你的手，觉得你暂时不是个威胁。"
D.Strings[44337]="起码还有一个吉尔尼斯工程师在工匠区工作，她应该能帮上你。"
D.Strings[44338]="你是要找工匠区的银露一家人吗？他们最近才在附魔商店附近开起了自己的小店。"
D.Strings[44339]="有二个熟练的矿工从吉尔尼斯瘟疫中成功逃了出来，来到这里，你可以在工匠区找到他们。"
D.Strings[44340]="米拉盖佐尔开始逃跑！"
D.Strings[44341]="你们这些家伙真是在浪费我的时间！"
D.Strings[44342]="是谁召唤米拉盖佐尔？"
D.Strings[44343]="你一定是在寻找苍蹄，他把升降梯和风车维护得井井有条。你可以在中部高地下层找到他。"
D.Strings[44344]="到中部高地的底层寻找追云者，他们可以就珠宝加工方面的事宜为你提供帮助。"
D.Strings[44345]="我见过地精驾驶这些东西。我知道他们可以更快的！"
D.Strings[44346]="很好奇这按钮是干吗的……"
D.Strings[44347]="这才像话嘛！"
D.Strings[44348]="我知道是怎么回事了，我来控制！"
D.Strings[44349]="抓紧你的……头盔！"
D.Strings[44350]="不，火箭！不要往那飞！"
D.Strings[44351]="我就要失去控制了！"
D.Strings[44352]="这有这个按钮我还没按过了，让我们按下去试试吧！"
D.Strings[44353]="这儿发生了些不寻常的事情，布温巴。你能来帮忙吗？"
D.Strings[44354]="你想要和灵魂谈话？好吧，让我们看看行不行……"
D.Strings[44355]="我想我找到了应急按钮。火箭都有这样的按钮，没错吧？"
D.Strings[44356]="你需要成为布温巴的双手……我需要你去扔一些木棍到营地中央的火堆里。剩下的就交给布温巴处理。"
D.Strings[44357]="玛乌里的死亡移除了附近坩埚受到的保护！"
D.Strings[44358]="提库鲁的死亡移除了附近坩埚受到的保护！"
D.Strings[44359]="这一定会很有趣！"
D.Strings[44360]="成功了！我成功让我们回到正轨上来了！"
D.Strings[44361]="跳起来甩掉燃灰幼蛛！"
D.Strings[44362]="哇，你就是女妖之王？我还以为你会更高的呢！"
D.Strings[44363]="大家都说你和酋长起了争执，将要抛弃部落。那是真的吗？"
D.Strings[44364]="我无须辩护，大使。年轻人，就跟我告诉酋长的一样，我的忠诚从来没动摇过。"
D.Strings[44365]="我们永远不会忘记，在我们被遗忘者孤立无援的时候，部落张开双臂欢迎了我们。"
D.Strings[44366]="加尔鲁什和我会一直做出最有利于我们人民的决定。"
D.Strings[44367]="所以说那不是真的？感谢先祖！我可不希望做你的敌人，希尔瓦娜斯女士。"
D.Strings[44368]="别得意忘形，小孩！你知道你面前是谁吗？"
D.Strings[44369]="你已经快抓不住了！快从树上下来！"
D.Strings[44370]="从尘世的桎梏中解脱……"
D.Strings[44371]="拿你当祭品……取悦他……"
D.Strings[44372]="死亡将缠绕你的灵魂！"
D.Strings[44373]="我的死……微不足道……"
D.Strings[44374]="啊哈哈，大家听好了！$b$b格里伏塔又回来啦！新的摊位，崭新的商品，已经做好再次开张的万全准备啦！$b$b你想变得更快、更高、更强吗？我卖的每一个护身符都绝对有效！过来买一个神奇的小玩意吧！性价比超乎想象！"
D.Strings[44375]="这些巨魔没完没了，$c。"
D.Strings[44376]="你的狮鹫可以送我到挖掘场吗？"
D.Strings[44377]="感谢你，朋友。"
D.Strings[44378]="谢谢你。我一定要在回营地的路上顺手干掉几只蜘蛛。"
D.Strings[44379]="你可不会想知道关在这里是什么感觉。"
D.Strings[44380]="谢谢你救了我。我还以为自己死定了呢。"
D.Strings[44381]="谢谢你把我救出来！真是太可怕了。"
D.Strings[44382]="好、好、好、好粘啊……"
D.Strings[44383]="谢谢你！我要赶紧处理下这种烧灼感的后遗症……"
D.Strings[44384]="啊，你在这里！我们翻遍整个丛林在找你呢！"
D.Strings[44385]="任何帮助都是宝贵的。赞达拉的计划已经将古拉巴什推向了战争之路。"
D.Strings[44386]="不是所有地方联系都如此紧密。我们会尽力帮忙，但这一切的源头，是在祖尔格拉布。"
D.Strings[44387]="如果你能确保我城镇的安全，我一定不会亏待你。"
D.Strings[44388]="干得好，布温巴。联盟竟然愿意帮忙阻止赞达拉，这实在太好了。"
D.Strings[44389]="为了夺回领土，古拉巴什不惜使用各种巫毒妖术。"
D.Strings[44390]="赞吉尔！"
D.Strings[44391]="看来你确实可以找来援助。"
D.Strings[44392]="我知道。那正是我四处奔波的原因：警告所有人。暗矛部族的领袖亲自发言时，所有人都会认真听，无论是部落还是联盟。"
D.Strings[44393]="那将是我们下一步应当去的地方，我们必须在源头遏止这次暴动。"
D.Strings[44394]="干得好，布温巴。你和你的朋友让暗矛巨魔感到骄傲。"
D.Strings[44395]="我还需要留下讨论一些事情，之后我将前往祖尔格拉布，我们在那里见。"
D.Strings[44396]="让我们看看布温巴召唤出了什么……"
D.Strings[44397]="这可是严肃的事情，温诺希斯可不是喜欢开玩笑的人。"
D.Strings[44398]="啊……是基尔娜拉。我就知道她与此有关。"
D.Strings[44399]="我不敢相信我的眼睛……那是血领主曼多基尔吗？这可糟了……"
D.Strings[44400]="这些古拉巴什巨魔来真的了，我们必须帮助这些人。"
D.Strings[44401]="%s扑向最远的玩家！"
D.Strings[44402]="雷霆崖的长者们，我把大家召集到这里，是要在先祖的见证下祭拜我的父亲——凯恩·血蹄。"
D.Strings[44403]="父亲，您不但智勇双全，还懂得体恤人民。"
D.Strings[44404]="愿您的灵魂如您身前一样继续指引我们，父亲。"
D.Strings[44405]="当我和我的德鲁伊们遭到变节兽人的伏击，您向加尔鲁什酋长提出决斗来为死去的族人伸张正义，酋长。"
D.Strings[44406]="您战斗得十分英勇，酋长，但无奈恐怖图腾的叛徒在加尔鲁什的刀刃上下了毒，让决斗失去了公平。"
D.Strings[44407]="愿您的灵魂安息。玛加萨和她的族人已经被驱逐出了城市，而您优秀的儿子将传承您的传说。"
D.Strings[44408]="我们熟知您，凯恩·血蹄。您的族人告诉了我们你的英勇事迹，而我们欢迎你进入祖先的归宿。"
D.Strings[44409]="正该如此祭拜酋长！"
D.Strings[44410]="兰德鲁的小巫妖"
D.Strings[44411]="愚人的金子"
D.Strings[44412]="不赖嘛，勇士！看来关于你传闻都是真的。不过我们得在这儿分道扬镳了。我得亲自处理这个囚犯……"
D.Strings[44413]="野蛮迅猛龙坐骑"
D.Strings[44414]="夜刃豹幼崽"
D.Strings[44415]="战团马栓"
D.Strings[44416]="阿曼尼龙鹰"
D.Strings[44417]="快点！把敌人引到我的陷阱上！"
D.Strings[44418]="元素之战"
D.Strings[44419]="巨龙暮光"
D.Strings[44420]="时间会告诉我们。"
D.Strings[44421]="不如……在斧头上擦点肥皂？这样就万事俱备啦！"
D.Strings[44422]="当肥皂褪去的时候，你就会拥有一把崭新的斧头了！"
D.Strings[44423]="孩子们，$n给你们带来了惊喜！快过来看看你们的礼物是什么！"
D.Strings[44424]="快看我，我是萨鲁法尔大王！"
D.Strings[44425]="就算毒蛇不弄死我们，猎豹也会杀死我们的！"
D.Strings[44426]="那眼睛……在我脑海中挥之不去！"
D.Strings[44427]="那嘶嘶声片刻未停，毒蛇不停地涌来！"
D.Strings[44428]="没有地方躲啦！"
D.Strings[44429]="猎豹正在追捕我们，停留在一个地方可不是个好主意。我们必须得离开了！"
D.Strings[44430]="我们完了……"
D.Strings[44431]="那只野兽捕获了那么多猎手……"
D.Strings[44432]="这个丛林就将是我们的葬身之处。"
D.Strings[44433]="我脑海里都是那眼睛……"
D.Strings[44434]="我还是被毒死算了，因为玛乌提还活着。"
D.Strings[44435]="别让猎豹把我拖走……那样的话我宁愿去死。"
D.Strings[44436]="如果真有人可以追踪到玛乌提，那就一定是格伦特。一旦解决了那只猎豹，那我们就可以专心对付毒蛇了。"
D.Strings[44437]="你听见了吗？我好像刚刚听到了那边有玛乌提的声音……"
D.Strings[44438]="无穷无尽的毒蛇和一只巨型猎豹……情况不会比这更糟了。"
D.Strings[44439]="我能感觉到玛乌提注视着我们……它正在等待另一次偷袭我们的机会。"
D.Strings[44440]="好多死掉的毒蛇啊……如果我的剥皮技巧没荒废就好了……"
D.Strings[44441]="哇啊啊啊啊啊啊！"
D.Strings[44442]="很高兴见到你，$n。你是来帮我们击退敌人的吧？"
D.Strings[44443]="你不用担心，孩子。酋长的“眼睛”在这里，他们会确保这点的。"
D.Strings[44444]="元素大军无穷无尽。如果得不到援助的话，我们恐怕没办法守住这个突破口。"
D.Strings[44445]="你低劣的咆哮激怒了莱拉克斯。"
D.Strings[44446]="莱拉克斯发出了可怜的呜咽声。"
D.Strings[44447]="快用艾森娜的翡翠净化你身上的派拉齐尼斯毒素！"
D.Strings[44448]="如果你发誓好好照顾它的话……我愿意忍痛割爱给你一只。"
D.Strings[44449]="什么？！这是何等愚蠢？"
D.Strings[44450]="那个家伙！你失去理智了吗？"
D.Strings[44451]="凡人可不该来考达拉。"
D.Strings[44452]="如果你珍惜生命，就马上离开。"
D.Strings[44453]="考达拉已经严禁低等种族进入了，$c。$b$b你在这儿会有生命危险。"
D.Strings[44454]="%s开始喷发了，大群熔岩寄生虫落在了地上！"
D.Strings[44455]="有话快说，凡人，趁着其他人还没发现你。可不是人人都像我这么有耐心的。"
D.Strings[44456]="要独自开动并驾驶蒸汽坦克可不是件简单的活儿，但总得有人去做。"
D.Strings[44457]="儿童周期间大家可以免费租用摩托车，赶快挑一架到美丽的西部荒野兜风吧！"
D.Strings[44458]="我需要另一个狼獾人孤儿哨。"
D.Strings[44459]="你应该已经知道了，$n！每次遇到困难时，茉艾拉都会下来跟那尊石像说话。在那种情况下，我都会回避，我也只能为这对父女做这点事了。\n\n后来，那里就传出了震耳欲聋的巨响，我冲回去查看发生了什么事。然后，就看到麦格尼开始走动说话了，只不过从头到脚都是由水晶构成的！\n\n他用仿佛山崩地裂一样隆隆作响的声音告诉我们，他是大地的代言人，是艾泽拉斯的一部分。他只跟部族首领们谈了一小会儿，留给我们一个燃烧军团归来的可怕警告，然后就动身前往奥杜尔了！"
D.Strings[44460]="当时你把石板带来给我，我就该把它们摔碎的，$n，可我没有。在此危难的时刻，我们仍需要国王的智慧来指引我们。"
D.Strings[44461]="拉格纳罗斯，请赐予我力量吧！"
D.Strings[44462]="主人，请让你的光辉照耀着我吧！"
D.Strings[44463]="拉格纳罗斯大人，请赐予我不熄的烈焰吧！"
D.Strings[44464]="这没用！他们的护盾太坚固了！"
D.Strings[44465]="赞达拉氏族已经疯了，我们必须阻止他们。"
D.Strings[44466]="暗矛氏族不想和赞达拉的计划有任何瓜葛。"
D.Strings[44467]="温诺希斯控制着毒蛇，是个难缠的家伙。"
D.Strings[44468]="温诺希斯擅长使毒，他是一个可怕的敌人。"
D.Strings[44469]="基尔娜拉狂热地痴迷于猎豹。"
D.Strings[44470]="你看到玛乌提的眼睛吗？它们闪烁着光芒！我早该猜到基尔娜拉是猎豹袭击的幕后黑手。"
D.Strings[44471]="干得好，勇士。我会把这个肮脏的家伙带回去的。我们有不少问题要问这个德鲁伊。"
D.Strings[44472]="炎魔之王的仆从，将入侵者烧成焦炭！烧死傲慢的海加尔守护者！"
D.Strings[44473]="你们将承受拉格纳罗斯的愤怒！"
D.Strings[44474]="没关系。我会在远处看着海加尔燃烧。"
D.Strings[44475]="赞吉尔自言自语着。"
D.Strings[44476]="对了，加一撮这个……放一把那个……嘿嘿，嘿嘿！"
D.Strings[44477]="哦，赞吉尔，赞吉尔。我和你一样爱巫毒。"
D.Strings[44478]="奴隶……僵尸……赞吉尔都无所谓。他们都要服侍古拉巴什，无论是活还是死……"
D.Strings[44479]="德鲁伊们，停止攻击！她没有武器！"
D.Strings[44480]="等一下……我认识那女孩。莱雅娜，是你吗？"
D.Strings[44481]="你的战斗技巧令人称羡，英雄。希望你能继续活跃在战场上。我会把这个罪犯带回去……审讯的……"
D.Strings[44482]="你给我留下了深刻的印象，英雄。谢谢你帮我战胜了这个……德鲁伊。我自己押这个异端回去就行。"
D.Strings[44483]="烈焰德鲁伊……她很危险，玛法里奥。你认识她吗？"
D.Strings[44484]="是的，哈缪尔。她比你想象的更危险。"
D.Strings[44485]="它是红寡妇，贝丝缇拉克的子嗣。她的其他小崽子们一定会来给它们的兄弟报仇的。"
D.Strings[44486]="小迅猛龙抬头看着你。你无法确定，但你仿佛在她眼中看到认同的眼神。"
D.Strings[44487]="我们必须阻止赞达拉，艾泽拉斯所有的巨魔都联合起来听从统一的指挥，这对我们所有人都是巨大的威胁。"
D.Strings[44488]="赞达拉对我们双方的臣民都是巨大的威胁，$r。我们必须联合起来消灭他们。"
D.Strings[44489]="拉格纳罗斯大人！庇护我吧！"
D.Strings[44490]="我们准备好打开大门了。"
D.Strings[44491]="跟我来，$c。需要我们二个人一起来才能打开大门。"
D.Strings[44492]="嘿，$n，你也来了！这些家伙都是突然冒出来的！快来帮帮我，让我喘口气！"
D.Strings[44493]="开门仪式需要我们一同敲响这个锣。"
D.Strings[44494]="也许我们还没准备好。你们准备打开大门的时候告诉我。"
D.Strings[44495]="我同意来见你，灭世者，但冒着极大的风险。如果我们被发现了……"
D.Strings[44496]="一旦新的秩序建立，你将确保我的地位，是吗？"
D.Strings[44497]="冷静，阿瑞苟斯。你的屏障能为你争取足够的时间。"
D.Strings[44498]="等到卡雷苟斯死后，你作为蓝龙之王的宿命就将确立。"
D.Strings[44499]="你将得到对魔法国度至高无上的统治权，即使是在暮光审判日之后。"
D.Strings[44500]="但我警告你，阿瑞苟斯，玛里苟斯之子，不要重蹈你父亲的覆辙。"
D.Strings[44501]="如果与我作对，你受到的惩罚将比你父亲的更可怕。"
D.Strings[44502]="听着，赞达拉的阴谋者们……暗矛部落和我们的盟友不允许你们统治阿曼尼！"
D.Strings[44503]="保护希萨莉，不要让火元素伤害她！"
D.Strings[44504]="阿曼尼知道我们在这里，进攻的时候到了！"
D.Strings[44505]="你好，$c。这些德鲁伊都曾是我们的兄弟姐妹，可现在他们已经被炎魔之王变成了熔岩的化身。现在，烈焰德鲁伊们就在执行他的疯狂计划，试图烧毁世界之树。我们绝对不能让他们得逞。"
D.Strings[44506]="看，安伦！$n来帮我们了！"
D.Strings[44507]="保护索罗和安伦，不要让火元素伤害他们！"
D.Strings[44508]="你来得正是时候，$r。我已经受够这些肮脏的怪物了。"
D.Strings[44509]="保护老树干，不要让火元素伤害他！"
D.Strings[44510]="愿为您效劳，勇士。"
D.Strings[44511]="艾露恩欢迎你，勇士。我会掩护你。"
D.Strings[44512]="只要开口求援，暗影守望者就会出现。我已经做好一切准备了。"
D.Strings[44513]="立刻报告。我们没时间了。"
D.Strings[44514]="我的剑在渴望战斗。不要让我久等了。"
D.Strings[44515]="接下来的事我自己可以搞定。我们庇护所再见了，$n。"
D.Strings[44516]="谢谢你，$n。只要我和安伦在一起，我们就没什么好怕的了。快去看看其他人吧！"
D.Strings[44517]="从这里开始我能自己搞定了，$r。我们在玛洛恩庇护所见吧。"
D.Strings[44518]="正义终将得到伸张，异端！"
D.Strings[44519]="我绝不宽恕亵渎者！"
D.Strings[44520]="别想求饶了。我的剑是不会宽恕敌人的。"
D.Strings[44521]="我要把所有的敌人都送回老家！"
D.Strings[44522]="火焰可以焚烧许多东西，但它永远碰不到阴影。"
D.Strings[44523]="我会用匕首的锋刃洗清你的罪恶。"
D.Strings[44524]="哪里有僵尸，哪里就有赞吉尔。赞达拉巨魔将要集中所有古拉巴什魔精，夺回荆棘谷。"
D.Strings[44525]="这场战争令我心情沉重。我正带领着我的人民走向死亡。但如果我们现在不站出来反抗拉格纳罗斯，将来又怎么能抵挡得住奈萨里奥呢？$B$B我们必须为自己所拥有的一切而战，否则就只能眼睁睁看着世界毁灭。"
D.Strings[44526]="有我陪着你呢，索罗！"
D.Strings[44527]="到我后面去，索罗！"
D.Strings[44528]="我们绝不分开，索罗！"
D.Strings[44529]="你真是个好兄弟，索罗！"
D.Strings[44530]="我掩护你，索罗！"
D.Strings[44531]="有我陪着你呢，安伦！"
D.Strings[44532]="你真是个好兄弟，安伦！"
D.Strings[44533]="我会保护你的，安伦！"
D.Strings[44534]="兄弟齐心，其利断金，安伦！"
D.Strings[44535]="我在这儿，安伦！"
D.Strings[44536]="你必须留在希萨莉身边！"
D.Strings[44537]="你必须留在索罗和安伦身边！"
D.Strings[44538]="你必须留在老树干身边！"
D.Strings[44539]="杀死高阶祭司，一切都安全之后再来找我，我就可以带着我的报告回到血卫士身边了。"
D.Strings[44540]="你除掉那巨魔熊了吗，朋友？我现在能安全地回去了吗？"
D.Strings[44541]="嗨，有人能听见哈兹莱克说话吗？"
D.Strings[44542]="嗨！别忘了哈兹莱克！在这里！"
D.Strings[44543]="我睡梦中都能打开这个锁，只要告诉我什么时候能安全逃跑就行。"
D.Strings[44544]="终于，我自由了！"
D.Strings[44545]="这里有些我的东西……"
D.Strings[44546]="好啦。这是给你的礼物，感谢你帮忙打败阿曼尼帝国！"
D.Strings[44547]="能从笼子里逃出来太好了，他们正要把我当祭品呢……"
D.Strings[44548]="你不用担心了。这里发生了什么？"
D.Strings[44549]="哦朋友，当时的情况是这样的……$b$b夜色寂静，突然传来一阵微风掠过树叶般的飒飒声。没等我们回过神来，阿曼尼巨魔和他们的宠物已经包围了我们！等我醒来的时候，发现自己被囚禁在牢笼中。$b$b日复一日，囚犯们接二连三地惨遭毒手。每杀死一名囚犯，那个熊巨魔的力量就增加一些。$b$b我关在牢笼中，只知道这些。"
D.Strings[44550]="你是来帮助暗矛部落的吗，$c？"
D.Strings[44551]="感谢你，$c。我以为我要被献祭了……"
D.Strings[44552]="不要忘了我！"
D.Strings[44553]="不如过来救我出去吧？"
D.Strings[44554]="我这有沃金需要的情报，快来放我出来！"
D.Strings[44555]="做事别做一半。如果安全了就告诉我一声，我好回去汇报！"
D.Strings[44556]="重获自由的感觉真好！"
D.Strings[44557]="我是来自暗矛巨魔的使者。我们面临的威胁也同样是联盟的威胁。你愿意帮助暗矛氏族吗，$r？"
D.Strings[44558]="让我给你看些我找到的东西。咦，背包哪去了？"
D.Strings[44559]="这就是利文斯顿营地？看来我们已经迟了，赞达拉的进攻已经开始。"
D.Strings[44560]="哦不……邦巴拉……看来我们太迟了，赞达拉已经发动进攻了。"
D.Strings[44561]="你们随便拿吧。作为一名斥候，带着那么多拖油瓶真是自寻死路。"
D.Strings[44562]="看样子，那些猎手成功阻击了那些毒蛇，但我感觉还有别的事不对劲……就好像有人注视着我们。"
D.Strings[44563]="感谢你，$c。$b$b如果我能帮你做什么，尽管告诉我。"
D.Strings[44564]="挖掘场里……处处都是僵尸……"
D.Strings[44565]="避世乐园里……处处都是僵尸……"
D.Strings[44566]="要是没那么多阿曼尼巨魔的话，这个地方也不算糟糕。"
D.Strings[44567]="阿曼尼和赞达拉部族再也不敢这样了。"
D.Strings[44568]="沃金会让赞达拉部族知道一件事，那就是不要和暗矛部落作对！"
D.Strings[44569]="这太可怕了，要是能快点结束回家就好了。"
D.Strings[44570]="这个地方散发着死亡和祭品的恶臭。$b$B在你成为下一个囚犯前赶快离开吧。"
D.Strings[44571]="我的英雄！过来和洛尔卡尼谈谈。"
D.Strings[44572]="洛尔卡尼仍然需要你的帮助！"
D.Strings[44573]="我必须带着报告回到沃金身边！快帮我出去！"
D.Strings[44574]="洛尔卡尼终于自由啦！"
D.Strings[44575]="他们把洛尔卡尼的东西放哪里去了？"
D.Strings[44576]="请拿着这个，洛尔卡尼不再需要这个了。"
D.Strings[44577]="能从笼子里出来真好。洛尔卡尼要复仇……"
D.Strings[44578]="我在哪里？你是来帮忙的吗？"
D.Strings[44579]="他们一定是给你下药了。你现在安全了。"
D.Strings[44580]="他们对我做了手脚！我需要帮助！"
D.Strings[44581]="我听见你的声音了，不像是抓我的那些人。靠近点，让我看得到你。"
D.Strings[44582]="我觉得头晕目眩。求你了，帮帮我！"
D.Strings[44583]="我想起来了。我是来这里……完成一个任务的……救我出去，有些事情必须完成。"
D.Strings[44584]="巫毒消散！"
D.Strings[44585]="从巫毒中解脱吧！"
D.Strings[44586]="现在，你从巫毒中被释放了！"
D.Strings[44587]="愿灵魂将你带回我们身边。"
D.Strings[44588]="来吧，兄弟姐妹们。是时候将这座污秽的塔从敌人手中夺过来了。"
D.Strings[44589]="前进！向尖塔前进！"
D.Strings[44590]="他们的首领在这儿！快把他干掉！"
D.Strings[44591]="是时候了，$c。$b$b让我们来看看，到底是什么东西被收藏得这么隐蔽……"
D.Strings[44592]="在邦巴拉东面有一座祭祀毒蛇的神殿，我需要你去扔一些木棍到神殿前面的火堆中。剩下的就交给布温巴处理吧。"
D.Strings[44593]="赞达拉的先祖，赐予我藐视死神的力量吧！"
D.Strings[44594]="找我有事吗，凡人？"
D.Strings[44595]="有话直说，朋友。"
D.Strings[44596]="你看起来……很眼熟。"
D.Strings[44597]="永恒之眼里的景象一直困扰着我，卡雷苟斯。你是怎么看的？"
D.Strings[44598]="蓝龙军团正面临重大考验，$c。$b$b很快，我们就会推举出一位新的守护巨龙，来取代玛里苟斯。$b$b阿瑞苟斯一直希望能继承它父亲的遗志，重新展开对所有的施法者的屠杀。我能预感到，这只会让我们的族群走向灭绝。$b$b现在幸存的族人对此仍有分歧，可我担心阿瑞苟斯还是会义无反顾地走上绝路……"
D.Strings[44599]="泰蕾苟萨是哪位？要没有她的话，我不可能逃出魔枢。"
D.Strings[44600]="<卡雷苟斯担忧地望着远处。>$b$b对我来说，泰蕾苟萨……有着非同一般的意义。$b$b当她还是雏龙时，我负责保护并教导她。数千年来，我们之间有着特殊的纽带，类似于你们所谓的手足之情。$b$b泰蕾苟萨甫一降生，就昭示着不凡命运的开始。如果预言是真的，那么她的生死与蓝龙军团和艾泽拉斯休戚相关。$b$b余下的军团成员都知道我们之间的关系。如果你描绘的景象真的已经发生了，那么她可能已危在旦夕。"
D.Strings[44601]="$n，我们的部队正在向斜坡上推进。你应该去那里和他们汇合。"
D.Strings[44602]="$n，我们的部队已经推进到塔下了。你应该去那里和他们汇合，快！"
D.Strings[44603]="$n，进攻很快就能准备好。请等在这里，届时和他们一起冲上斜坡。"
D.Strings[44604]="图拉克，麦琳，带领这些部队冲上斜坡，夺下塔楼。要快！"
D.Strings[44605]="德尔德伦、萨莉斯，这些人归你们。一定要攻下塔楼。"
D.Strings[44606]="丛林守护者塔尔德罗斯，我派赛拉和其他人协助你攻打塔楼。愿月神与你同在。"
D.Strings[44607]="先祖与我同在！让他们听到你的声音！"
D.Strings[44608]="$n，我们的部队很快就要向斜坡发起攻击。快去和他们汇合吧。"
D.Strings[44609]="巨魔犯了一个巨大的错误，$c。"
D.Strings[44610]="我需要借用一头双足飞龙带我去暗矛使者那里。"
D.Strings[44611]="烈焰火雨来了！都跑起来，别停下！"
D.Strings[44612]="赞达拉的先祖，标记他们，让他们走向不归之路！"
D.Strings[44613]="啊，能再次见到你真好，$r。"
D.Strings[44614]="祖尔已经预见了未来。我们必须联合起来，否则我们必定被黑暗吞噬。"
D.Strings[44615]="这是唯一的出路，兄弟们。"
D.Strings[44616]="敌人用血淋淋的手段把这片土地从我们手中夺走。"
D.Strings[44617]="巨魔帝国的绿色铁拳将重重地粉碎这片土地，并再次将它占为己有。"
D.Strings[44618]="赞达拉拥有你前所未见的力量，以及巨魔最古老的智慧，而那智慧是你应得的。"
D.Strings[44619]="这片支离破碎的大地还将继续粉碎下去，朋友。"
D.Strings[44620]="黑暗的洪潮将再次淹没大地，所有的巨魔都将处于危险之中。"
D.Strings[44621]="暗矛太愚蠢了，没人可以阻挡我们。"
D.Strings[44622]="命运早已注定。你毫无希望……烈焰将吞噬一切！"
D.Strings[44623]="你……就是那个从传送门来的人——烈焰德鲁伊……"
D.Strings[44624]="你杀死了我的学生。你将为此付出代价。"
D.Strings[44625]="这是什么？我……不能动了！谁来救救我！"
D.Strings[44626]="烧吧，牛头人！烧吧！"
D.Strings[44627]="你受够了吗？吃够苦头了吗？"
D.Strings[44628]="好好看着！这曾是艾泽拉斯最强大的“德鲁伊”，如今却空剩一具烧焦的残骸。这是范达尔·鹿盔的意志。这是烈焰的意志！"
D.Strings[44629]="去吧，扑倒在你们敬爱的牛头人身上尽情哭泣吧……但我保证你们的眼泪救不了他。"
D.Strings[44630]="这样好多了。我很虚弱，但我记得听到阿曼尼和赞达拉的人提到有财宝就藏在这个房间里。"
D.Strings[44631]="也许在这边的瓮里。退后！"
D.Strings[44632]="呼，不是那个，让我们再试试其他的罐子。"
D.Strings[44633]="那里面有东西，快去看看。"
D.Strings[44634]="你把我从笼子里救了出来，非常感谢。我神智总算逐渐清醒了，可以回去向沃金报告我掌握的情报了。"
D.Strings[44635]="不要管我，$r。$b$b洛尔卡尼已经难逃一死。赶快在阿曼尼抓到你之前离开，$r。"
D.Strings[44636]="救我出去，$r。首先，你必须杀掉抓住我的阿曼尼祭祀，他正准备献祭我呢！"
D.Strings[44637]="我是一名暗矛斥候。杀了那个阿曼尼祭祀，我就可以带着报告返回了！"
D.Strings[44638]="督军倒下了！"
D.Strings[44639]="听着，拉斯塔哈！无论在什么情况下，暗矛部落和我们的盟友都会挺身而出，挫败你和赞达拉阴谋统治巨魔部族的邪恶计划！"
D.Strings[44640]="我已经准备好陪你一起去了，卡雷苟斯。"
D.Strings[44641]="$n，我会照顾大德鲁伊。玛法里奥和麦托克劳要求你即刻报到。"
D.Strings[44642]="烈焰吞没你！"
D.Strings[44643]="泰蕾苟萨！"
D.Strings[44644]="干得好，朋友们！这座塔是我们的了！现在，我要亲手毁了这座污秽的建筑。"
D.Strings[44645]="干的好，$n。看来我们把他们打跑了。"
D.Strings[44646]="种植"
D.Strings[44647]="我带来了银月城摄政王的口谕。"
D.Strings[44648]="为什么这个流亡者会在这里？摄政王洛瑟玛大人需要一个合理的解释。"
D.Strings[44649]="奎尔萨拉斯是你的家园，同样也是我的家园。我不会任由它被我们远古的敌人攻陷。走吧，去告诉你懦弱的摄政王——"
D.Strings[44650]="温蕾萨，拜托！"
D.Strings[44651]="是我邀请她来到这里的，信使。我手下大多数远行者都在远方，无法轻易召回。温蕾萨的游侠们熟知这片土地，他们也都是经验丰富的战士。"
D.Strings[44652]="洛瑟玛大人不会赞同你的解释的，游侠将军。你无权邀请这个——"
D.Strings[44653]="我是银月城守备指挥官，凡是我认为有必要的援助，我不会拒绝！"
D.Strings[44654]="让我们继续吧，沃金酋长。在被打断之前，你刚才正在向我们叙说赞达拉的计划。"
D.Strings[44655]="是的。赞达拉召集了包括暗矛在内的所有巨魔氏族举行了一次集会。"
D.Strings[44656]="拉斯塔哈大王，他计划将所有巨魔部族归入赞达拉的麾下。"
D.Strings[44657]="包括阿曼尼巨魔？"
D.Strings[44658]="阿曼尼、古拉巴什、他们所有人。他将会派遣大使到各个部族。"
D.Strings[44659]="我的斥候报告说祖阿曼附近没有任何动静。"
D.Strings[44660]="他们躲在城市的废墟中集结部队。"
D.Strings[44661]="拉斯塔哈想跟我称兄道弟，但部落才是我真正的兄弟。我们必须阻止他，以防他继续诱骗其他部族加入他的帝国。"
D.Strings[44662]="那我们该如何对付阿曼尼和赞达拉的联盟？"
D.Strings[44663]="我们原本就该阻止这件事发生的。"
D.Strings[44664]="那就这样计划，我的手下将潜入那座城市，尽可能探查赞达拉新督军的底细。"
D.Strings[44665]="哈杜伦，我们需要把部队联合起来，根据暗矛斥候的报告做好准备。"
D.Strings[44666]="同意。信使，你可以向摄政王洛瑟玛回报我们的计划。但记住，我不希望再受到干扰。"
D.Strings[44667]="我好像……把小精灵给弄丢了。能再给我一个吗？"
D.Strings[44668]="新的魔法守护者已经选定。"
D.Strings[44669]="你已经没有容身之处了，卡雷苟斯。"
D.Strings[44670]="你……出局了。"
D.Strings[44671]="去游个泳怎么样，$r？"
D.Strings[44672]="和你一起回岩浆里去……"
D.Strings[44673]="去泡泡岩浆吧，$c！"
D.Strings[44674]="但愿岩浆灌进你的肺里去！"
D.Strings[44675]="让岩浆吞噬你们吧，冷血动物！"
D.Strings[44676]="让烈焰的热浪吞没你！"
D.Strings[44677]="火焰之灵，消灭这只爬虫吧！"
D.Strings[44678]="让烈焰把你卷走吧……"
D.Strings[44679]="古拉巴什进攻者接连不断地涌来！我们被围困在这里好多天了，完全收不到来自外围哨站的情报。"
D.Strings[44680]="火焰鞭笞者欢快地舞动起来。你找到它了！"
D.Strings[44681]="快躲起来，倒数1秒……"
D.Strings[44682]="快躲起来，倒数2秒……"
D.Strings[44683]="快躲起来，倒数3秒……"
D.Strings[44684]="不准偷看！"
D.Strings[44685]="我的灵魂与你同在，$n。"
D.Strings[44686]="灵魂状态下行走并不轻松。"
D.Strings[44687]="蠕虫要咬人了！立刻把炸弹放下去！"
D.Strings[44688]="艾泽拉斯的月蚀之夜是我们蓝龙军团举行大部分神圣仪式的日子。"
D.Strings[44689]="我也不知道这个小鞭笞者为什么要对这棵枯死的树感兴趣。"
D.Strings[44690]="怎么，我看它是想复活这棵树！"
D.Strings[44691]="可怜的小家伙……它还不明白，这棵树已经没救了。"
D.Strings[44692]="等等……有情况!"
D.Strings[44693]="等等！我觉得它还活着，但生命迹象很弱。我会尽全力救治它的."
D.Strings[44694]="我到此来监督工作顺利完成。$B$b藏宝海湾仍在努力从潮汐的冲洗中恢复！$b$b这时候我们可不想遭到一大群暴怒巨魔、僵尸巨魔、毒蛇或发狂猎豹的攻击。"
D.Strings[44695]="我到这里来的目的是为了确保藏宝海湾在这次探险中的利益。$b$b如果进展不顺利，藏宝海湾也会有麻烦。$b$b我们仍在努力从大灾难中恢复过来。"
D.Strings[44696]="噢，亲爱的！它终究还是没能挺过来。看来，它的努力让它付出了最沉重的代价。"
D.Strings[44697]="来吧，小家伙。我们回营地了，忘了这个徒劳的任务吧。"
D.Strings[44698]="这是我的荣幸，卡雷苟斯。"
D.Strings[44699]="嘿，你好啊！我真是越来越喜欢你了！"
D.Strings[44700]="生存，是一切生物的本能。"
D.Strings[44701]="陪同玛法里奥召唤玛洛恩！"
D.Strings[44702]="$n！我知道另一个使者到哪里去了。"
D.Strings[44703]="准备好出发的时候告诉我，$n。"
D.Strings[44704]="$n！我知道你要找的那个巨魔去了哪里。"
D.Strings[44705]="准备好出发的时候跟我说话，$n。"
D.Strings[44706]="小迅猛龙奥根阿卡用恳求的眼神看着你。"
D.Strings[44707]="正在取样"
D.Strings[44708]="索罗的温度计已经就绪，可以取样了。"
D.Strings[44709]="这下面比火炉还热！啊，我的脑袋上都可以煎蛋了。"
D.Strings[44710]="%s因肢体松动而发出了呻吟！"
D.Strings[44711]="我会徒步跟着你，清理一路上的火焰。我需要集中精力，所以你一定要保护我的安全。"
D.Strings[44712]="我愿意，卡雷苟斯。我会代表泰蕾苟萨投下这一票的。"
D.Strings[44713]="靠近点。保持警惕。"
D.Strings[44714]="我们就快成功了。靠近点！"
D.Strings[44715]="兄弟们！攻击！"
D.Strings[44716]="黑曜石守卫者施放了刚硬之盾，所受伤害降低！"
D.Strings[44717]="虽然我已经感觉好多了，可还不能战斗。我需要靠你护送了。"
D.Strings[44718]="我很担心索罗。"
D.Strings[44719]="开头这段路是最困难的。等我们到热排气口那里，路就好走多了。"
D.Strings[44720]="这里就是第一个热排气口了！现在面对岩壁，跳！剩下的事就交给热气流吧。"
D.Strings[44721]="只要面对岩壁，然后跳！"
D.Strings[44722]="我来了，索罗！"
D.Strings[44723]="我们就快到了。"
D.Strings[44724]="谢谢你。我得去找索罗了。他是我的德鲁伊同伴，也是我最珍贵的朋友。"
D.Strings[44725]="如果你下次再来这个洞穴，别忘记利用那些排气口。在紧急关头，它们能救你一命。"
D.Strings[44726]="索罗……是你吗……？"
D.Strings[44727]="喝点水，安伦。我们快离开这个洞穴吧。"
D.Strings[44728]="由于超负荷运转，黑曜石守卫者现在极易爆炸！"
D.Strings[44729]="那个玛法里奥……他只会派手下来找我。$b$b他就是个懦夫，一直都是。"
D.Strings[44730]="玛法里奥是懦夫？你有什么证据吗？"
D.Strings[44731]="这不关你的事，$r。从我加入烈焰德鲁伊的那一刻起，我的过去已经在烈火中消逝了。它们对你毫无意义。$b$b而且，我来是要讨论这个王国的未来，但你并不是能与我对话的人。$b$b现在回答我……玛法里奥在哪儿！？"
D.Strings[44732]="玛法里奥不会来的。只有我在。"
D.Strings[44733]="%s因护甲碎裂而开始蹒跚！"
D.Strings[44734]="很好，就让他去火焰之地吧。我们会在那儿解决他。在接受审判之前，他可以再多活两天。$b$b<莱雅娜的眼睛亮了起来。>$b$b可那个牛头人大德鲁伊，就没那么走运了。"
D.Strings[44735]="牛头人大德鲁伊？你是指哈缪尔吗？"
D.Strings[44736]="入侵者正在迅速接近，玛法里奥。赶快中断仪式，加入战斗吧！"
D.Strings[44737]="有了你的帮助，我们就能击退他们！"
D.Strings[44738]="不，麦托克劳。拉格纳罗斯不会只派几个小兵来对付我们。"
D.Strings[44739]="我感到有些大家伙正在靠近。如果我们想活下去，就需要玛洛恩的力量。"
D.Strings[44740]="耐心点，麦托克劳。仪式很快就要完成了。"
D.Strings[44741]="艾露恩在上……那是什么？"
D.Strings[44742]="击退他们！我们得争取时间！"
D.Strings[44743]="烧吧！！！"
D.Strings[44744]="守住阵线！绝不能让他们突破！"
D.Strings[44745]="屈服于烈焰之灵！"
D.Strings[44746]="坚持住！再坚持一会儿！"
D.Strings[44747]="我们聚集于此，来决定蓝龙军团的命运。"
D.Strings[44748]="我们的历史写满了挫折与挑战……"
D.Strings[44749]="我们的未来面临着更大的威胁。"
D.Strings[44750]="我们的现状呼唤一位强有力的领袖。"
D.Strings[44751]="我是父亲的膝下之子。"
D.Strings[44752]="我注视着他，是他引领我们在逆境中前进，从不畏缩挑战。"
D.Strings[44753]="有人宣称我的父亲疯了。但即使在最黑暗的时刻，他也有着清晰的远见。"
D.Strings[44754]="他永远将蓝龙军团的需要放在首位。"
D.Strings[44755]="他一直努力巩固理应属于我们的力量，以应对这场他所预见的大灾变。"
D.Strings[44756]="兄弟们，我们必须夺回属于我们的力量。"
D.Strings[44757]="在我的领导下，蓝龙军团会再次崛起，超越过去的荣光——迎接更伟大的宿命。"
D.Strings[44758]="我保证！"
D.Strings[44759]="对火焰之地的突袭刻不容缓。我们必须尽快向拉格纳罗斯和范达尔发动反击。"
D.Strings[44760]="仪式进展如何，玛法里奥？"
D.Strings[44761]="谢谢你，$c。要不是你的话，我恐怕已经死在这儿了。"
D.Strings[44762]="我感谢你。保重，$c。"
D.Strings[44763]="这里的天空比我们所知的任何地方都要危险。"
D.Strings[44764]="在这儿你要小心点。这里远比看上去更危险。"
D.Strings[44765]="要不是被卷入了一股热气流，我已经逃出去了……"
D.Strings[44766]="那个怪物把我从天上打了下来。我能活下来就已经很走运了。"
D.Strings[44767]="有那些热气流的存在，在这里飞行无异于自杀。谢谢你来帮我们。"
D.Strings[44768]="我还需要一段时间来养伤。但我还是很高兴能活下来。"
D.Strings[44769]="我欠你一个人情，$c。"
D.Strings[44770]="赞美月神！也要赞美你。"
D.Strings[44771]="我真是个蠢货，竟然被引出了战线。谢谢你给我一个重来的机会。"
D.Strings[44772]="我立刻就回去。谢谢你，$c。"
D.Strings[44773]="我可以自己回去。谢谢你，朋友。"
D.Strings[44774]="他们的攻击无休无止。谢谢你的帮助。"
D.Strings[44775]="我欠你一个天大的人情。等战斗结束后，请来找我。"
D.Strings[44776]="要不是你，我就死定了。真是多亏了你，$r。"
D.Strings[44777]="你的偷窃行为令火鹰鸟后愤怒地尖啸起来。"
D.Strings[44778]="日常波次："
D.Strings[44779]="骑兵！"
D.Strings[44780]="举起长矛，戳他！"
D.Strings[44781]="你应该回孵化场去！"
D.Strings[44782]="我们又遇上了！"
D.Strings[44783]="长矛？我都不认识她！"
D.Strings[44784]="长矛在我裤子里呢！"
D.Strings[44785]="海加尔的小鬼，海加尔的女人！他们在这儿到处戳人！"
D.Strings[44786]="和苍白暮光中的魔鬼纠缠去吧！"
D.Strings[44787]="兄弟们，姐妹们，阿瑞苟斯谈到了我们坎坷的过去。"
D.Strings[44788]="没错，过去充满了磨难。"
D.Strings[44789]="但我想说的是，我们也要对自己的伤痕担负起责任。"
D.Strings[44790]="让我们改变过去的方式。"
D.Strings[44791]="放弃将魔法从这个世界中根除的想法……"
D.Strings[44792]="……为了艾泽拉斯和所有生灵的福祉，负责地使用魔法。"
D.Strings[44793]="我们今日的选择必将改变整个蓝龙军团的宿命，甚至改变这个世界的宿命。"
D.Strings[44794]="愿泰坦指引我们。愿我们能做出明智的抉择。"
D.Strings[44795]="呆着别动。我会把你送到安全的地方。"
D.Strings[44796]="别担心。我抓住你了。"
D.Strings[44797]="别那么着急。你不会那么巧死在我们背上的。"
D.Strings[44798]="上面的落脚点很危险。小心点。"
D.Strings[44799]="我会尝试把你送回岛上。只要能穿过这些热气流就行……"
D.Strings[44800]="抓紧了，这里的气流很危险。"
D.Strings[44801]="你对我们至关重要，绝对不能这样轻易死掉。"
D.Strings[44802]="上去了。"
D.Strings[44803]="这个坠饰里填满了伤恸的回忆。如此痛苦，如此悲哀……来看看它想告诉我们什么。"
D.Strings[44804]="这是谁？好像是瓦斯坦恩，范达尔·鹿盔唯一的儿子。他在做什么？这是其拉之战的回忆吗？"
D.Strings[44805]="没错！这是千年之前在希利苏斯发生的大战。瓦斯坦恩为族人而战，却不幸被俘……殒命敌手。"
D.Strings[44806]="哦……这太可怕了。为什么莱雅娜会执着于这段回忆？瓦斯坦恩一定是个对她非常重要的人……"
D.Strings[44807]="时光流逝，丧子之痛却不会消褪。"
D.Strings[44808]="瓦斯坦恩，亲爱的丈夫，你离开得太早了。"
D.Strings[44809]="莱雅娜，我只剩下你们俩了。我向你发誓，终我一生，我将始终守护你和我的孙女。"
D.Strings[44810]="我想要救你，伊丝塔瑞亚，但我太弱了。"
D.Strings[44811]="范达尔决不会允许部落攻击我们的家园！玛法里奥派谁来保护我们了？谁也没来！"
D.Strings[44812]="你的愤怒并非受到误导。"
D.Strings[44813]="与你有着同样伤痛的人。能助你缓解伤痛的人。"
D.Strings[44814]="范达尔！你从监狱中逃出来了？"
D.Strings[44815]="新的盟友拯救了我。没能早点到你身边，我很抱歉。"
D.Strings[44816]="这是什么力量？你变成了什么？"
D.Strings[44817]="时间会让你明白一切，我的孩子。随我来吧，一起向那些错怪我们的人复仇……"
D.Strings[44818]="我们的孩子刚出生。是个女孩！多漂亮的女儿。"
D.Strings[44819]="我给她取名叫伊丝塔瑞亚。她的眼睛跟你的像极了。"
D.Strings[44820]="蠢货！奈萨里奥会杀了你们！"
D.Strings[44821]="莱雅娜点了点头。"
D.Strings[44822]="这些巨魔突然出现，向我们寻求帮助。"
D.Strings[44823]="我几乎不明白这些巨魔想说什么。"
D.Strings[44824]="这些巨魔就不能自己解决自己的问题吗？"
D.Strings[44825]="<那巨魔看着周围成堆的尸体，自顾自地唱着歌。>"
D.Strings[44826]="多谢相助。"
D.Strings[44827]="你救了我一命！"
D.Strings[44828]="布温巴，是你吗？多谢相救。"
D.Strings[44829]="毒蛇！到处都是毒蛇！"
D.Strings[44830]="毒蛇群淹没了我们。"
D.Strings[44831]="我还以为我要死在这丛林里了。"
D.Strings[44832]="灵魂在今天眷顾了我。"
D.Strings[44833]="多谢救我一命。"
D.Strings[44834]="我们不能再浪费时间了，朋友。$b$b我们整个军团群龙无首，急需新的领袖。"
D.Strings[44835]="你做到了，$n，我很高兴。"
D.Strings[44836]="欢迎来到熔火激流，$n。"
D.Strings[44837]="前边的火妖可不是吃素的。小心点。"
D.Strings[44838]="前面有很多热排气口，$n。如果你不小心陷入困境，可以利用它们来脱困。"
D.Strings[44839]="洞穴的深处恐怕有一个迷失的德鲁伊，$n。你千万要小心。"
D.Strings[44840]="%s的护甲被活跃的火山削弱了。"
D.Strings[44841]="另一个使者，他总是想着拯救世界！"
D.Strings[44842]="另一名使者是不是已经踏遍了整个丛林？"
D.Strings[44843]="我们这是陷入了何等困境？"
D.Strings[44844]="曼多基尔一定很爱他的迅猛龙。"
D.Strings[44845]="血领主，看来是他监督着古拉巴什的勇士们。"
D.Strings[44846]="每一头蓝龙都会铭记你的英勇事迹，$n。"
D.Strings[44847]="我已经准备好要参加典礼了，赫雷苟萨。"
D.Strings[44848]="跟我走，$n。我们已经为你准备了一场典礼。"
D.Strings[44849]="干得好，我们暂时安全了，但时间并不多。"
D.Strings[44850]="埋下种子，希望扎根。悉心守护，生机萌发。我们将在这个灼热世界里建立一个庇护所。"
D.Strings[44851]="我们将在此坚守，抵挡元素大军的进攻。"
D.Strings[44852]="我们要吸引拉格纳罗斯军队的注意，好让其他人直捣火焰王国的腹地。"
D.Strings[44853]="战争，已经打响了。"
D.Strings[44854]="这是个古老、宁静又安详的墓地。"
D.Strings[44855]="拿出烟熏过的坠饰。"
D.Strings[44856]="虽然这里显然是座坟墓，可没有写明葬在这里的是什么人。"
D.Strings[44857]="我可以传授烹饪的艺术。\n\n你想学吗？"
D.Strings[44858]="欢迎你，我们一直在等你。"
D.Strings[44859]="祝贺你在火焰之地所取得的胜利。"
D.Strings[44860]="但只有称赞是不够的。"
D.Strings[44861]="你改变了蓝龙军团的宿命，我们对你感激不尽。"
D.Strings[44862]="请把你的法杖交给我，我们能够赋予它更强大的力量。"
D.Strings[44863]="这个平台要塌了！跳到别的平台上去！"
D.Strings[44864]="天呐，这里可真热。我连熔炉都可以不用带了。"
D.Strings[44865]="那边那座岛上到处都是黑曜石生物！我本该自己去的，可又过不了那座桥。"
D.Strings[44866]="我不是来监督战士们的，那是训练员的责任。\n\n我关注的是那两个新来的医护人员。到目前为止，我的学生表现还不错。"
D.Strings[44867]="哦，没错。我拿了点蜡烛。\n\n那么，你想要点什么呢？"
D.Strings[44868]="你找我？我们打架！"
D.Strings[44869]="压碎了！"
D.Strings[44870]="我来抓你了，小凡人！"
D.Strings[44871]="我会抓住你，小东西！"
D.Strings[44872]="懦夫！你逃不掉！"
D.Strings[44873]="不！你躲不开古拉巴什之怒的！"
D.Strings[44874]="格里雷克……不再游荡了……"
D.Strings[44875]="今天，你会希望再也不要从梦中醒来！"
D.Strings[44876]="可怜。死后你就不能做梦了……"
D.Strings[44877]="听话……闭上眼睛吧……"
D.Strings[44878]="瞧瞧藏在你噩梦中的恐惧吧！"
D.Strings[44879]="长梦不醒，或是噩梦成真，让我们瞧瞧究竟是哪种更恐怖！"
D.Strings[44880]="睡吧……另一个梦境在等着你……"
D.Strings[44881]="我的灵魂再也不会做梦了……"
D.Strings[44882]="最终，泰蕾苟萨，我们挚爱的姐妹，她选择了你的法杖作为其精魄的永久栖息地。"
D.Strings[44883]="啊……今天我又能多收藏一把利刃了……"
D.Strings[44884]="见血封喉，一命归西。"
D.Strings[44885]="也许在你背后捅上一刀就能帮你卸下肩上的重担……"
D.Strings[44886]="盗贼从背后下手……"
D.Strings[44887]="第一次还不会要你的命。到第二次，你就死定了。"
D.Strings[44888]="尝尝这千刃乱舞的厉害！"
D.Strings[44889]="千刃乱舞！"
D.Strings[44890]="即使死一千次……我的灵魂也不会安宁……"
D.Strings[44891]="回到海加尔的侵占区去，否则你们会被抛下的！"
D.Strings[44892]="什么？你也是来嘲笑赞吉尔的？又来了！我要给你好看！"
D.Strings[44893]="别担心。赞吉尔不会让你死得太久……"
D.Strings[44894]="味道如何？"
D.Strings[44895]="哦，真漂亮……赞吉尔会让这个派上大用场……"
D.Strings[44896]="也许你想和大家伙玩！"
D.Strings[44897]="快，小东西！攻击他们！杀了他们！"
D.Strings[44898]="谁需要朋友？赞吉尔自己造朋友！"
D.Strings[44899]="站起来！赞吉尔的药剂给你们生命！"
D.Strings[44900]="深呼吸，朋友！全吸进去！"
D.Strings[44901]="你们都要付出代价！没有赞吉尔，祖尔格拉布什么都……不是……"
D.Strings[44902]="对我来说，能帮助普罗德摩尔女士进行研究是莫大的荣幸。要知道，她可是全艾泽拉斯最强大的人类法师！\n\n那么，你有什么要我帮忙的吗？"
D.Strings[44903]="你会后悔侵扰我的家园！"
D.Strings[44904]="就算这座塔里的藏书再多一倍，对我来说仍然不算多。我是不会停止收藏和抄录的。\n\n那么，你需要我帮忙吗？"
D.Strings[44905]="感到刺痛吗？这也许是你最后的感觉。"
D.Strings[44906]="你相当震惊吧……"
D.Strings[44907]="你比闪电更快吗？"
D.Strings[44908]="风暴赋予我力量！"
D.Strings[44909]="帝国的覆灭……不过是个开始……"
D.Strings[44910]="很震撼。我知道。"
D.Strings[44911]="你是说，这儿有个术士？就在塞拉摩？！\n\n噢，天呐。我们必须立刻通知普罗德摩尔女士！\n\n……哼。"
D.Strings[44912]="感受风暴的力量！"
D.Strings[44913]="拜托，小声点。最好别让普罗德摩尔女士知道我们在研究什么东西。\n\n那么，我们现在能来谈谈“真正”的力量了吗……？"
D.Strings[44914]="随着所有的攻城坦克接近完工，我开始觉得有点无聊了！\n\n你不是工程师吧？愿意来比下图纸吗……"
D.Strings[44915]="欢迎来到我的厨房！\n\n你是想来买吃的呢，还是想来自己做点儿？"
D.Strings[44916]="你知道，我曾是探险者协会的成员。\n\n可后来我才发现，我其实只对宝石感兴趣。\n\n硕大、璀璨、艳丽、珍贵的宝石……噢，我是多么爱它呀！"
D.Strings[44917]="希望她的陪伴能带给你鼓舞与宽慰。"
D.Strings[44918]="我们感谢你，蓝龙军团的挚友。"
D.Strings[44919]="你是在看我吗？很好，看着我，就该看着我。你还在看我吗？很好。"
D.Strings[44920]="烁影！为什么是烁影呢！"
D.Strings[44921]="他是个宝石狂人，一点没说错，可我还是爱他。他说过，我是他最爱的那颗宝石，嘻嘻！\n\n那么，我能帮你什么忙呢？是有关考古学的事，对吗？"
D.Strings[44922]="弹指间，你就灰飞烟灭啦……"
D.Strings[44923]="<这根法杖充盈着奥术的能量。>"
D.Strings[44924]="沼泽盛产优质皮革，如果你够胆进去找的话。里面有很多鳄鱼。我和我兄弟就打算在这里呆一段时间。\n\n有什么要我帮忙的吗？"
D.Strings[44925]="你，毫无价值！"
D.Strings[44926]="多管闲事的虫子！面对我的愤怒吧！"
D.Strings[44927]="滚吧，虫子们。下一次我再对付你们。"
D.Strings[44928]="你的欺骗是不可饶恕的，金度。你亵渎了你的神明！"
D.Strings[44929]="愿大自然保佑你。"
D.Strings[44930]="你需要我的火力支援？很好，我们直接说正事吧。"
D.Strings[44931]="今天，我们将并肩战斗。"
D.Strings[44932]="那么，今天你就是我的指挥官了。很好。"
D.Strings[44933]="医生……来了！"
D.Strings[44934]="如果不是有人又在那儿种了几棵蠢树，我还可以射得再准一点儿的！"
D.Strings[44935]="愿你能笑对苦难。"
D.Strings[44936]="以月神的名义，我会给你个痛快的。"
D.Strings[44937]="永远别回来了，元素。这是自然的领域！"
D.Strings[44938]="为了吉尔尼斯！"
D.Strings[44939]="在联盟的五大英雄面前，你就是个小火苗！"
D.Strings[44940]="我们吉尔尼斯人对外来者可没什么耐心。"
D.Strings[44941]="这里不欢迎你们，元素！"
D.Strings[44942]="艾泽拉斯可不是你们能来的。"
D.Strings[44943]="滚出去，你们这些没有灵魂的爬虫！"
D.Strings[44944]="尝尝我的武器吧！"
D.Strings[44945]="去死吧，你们这些懦夫！"
D.Strings[44946]="我要把你们撕碎！啊啊啊啊！！！！"
D.Strings[44947]="为了诺莫瑞根！"
D.Strings[44948]="看着，这就是克斯宾的实力！"
D.Strings[44949]="作为住院医师，我必须警告你们这些剩下的人，火焰对你们的健康有害。"
D.Strings[44950]="瞄准点！"
D.Strings[44951]="没错，这只是给你个教训，以后别再干那种蠢事了！"
D.Strings[44952]="如果你不能时不时从枪管里射出只毛茸茸的小动物来，又怎么能保持枪管清洁呢？德鲁伊对那种事可没什么办法！"
D.Strings[44953]="如果我愿意的话，可以直接靠唱歌把他们唱死。"
D.Strings[44954]="啦啦啦，啦啦啦……"
D.Strings[44955]="让我来！我要用我的琴狠狠揍他们一顿！"
D.Strings[44956]="就算是为了我，一定要回到泰达希尔啊。大家，再见了!"
D.Strings[44957]="我也不介意将来再跟你并肩战斗一次。再见！"
D.Strings[44958]="我们的工作还远未完成。范达尔必须为他的欺骗付出代价。"
D.Strings[44959]="我很钦佩你的力量。"
D.Strings[44960]="永远不要停止战斗！"
D.Strings[44961]="保重！"
D.Strings[44962]="好了，我得走了。到时间去喝上一杯了。"
D.Strings[44963]="下次吧，伙计们。"
D.Strings[44964]="所有人，放下武器。等护盾消失！"
D.Strings[44965]="停！停止攻击！"
D.Strings[44966]="停火，伙计们！等护盾消失！"
D.Strings[44967]="裂隙就在这座大厅后。跟着我。"
D.Strings[44968]="跟紧点，$n。如果被抓住，我们俩就都完了。"
D.Strings[44969]="守卫比之前要严密多了……阿瑞苟斯在保护什么？"
D.Strings[44970]="协助我！他们的数量太多了！"
D.Strings[44971]="来了更多的哨兵！没办法了……"
D.Strings[44972]="保护我，我来打破壁垒。"
D.Strings[44973]="什么……？暮光巨龙……在这？？"
D.Strings[44974]="哈哈哈！你就这点能耐？"
D.Strings[44975]="你残破的身躯属于哈卡。"
D.Strings[44976]="拜伏于我，拜伏于血领主曼多基尔！"
D.Strings[44977]="起来吧，奥根！为你的主人而战！"
D.Strings[44978]="斩首一击！"
D.Strings[44979]="小心你的脑袋！"
D.Strings[44980]="我的鲜血献给哈卡！我的灵魂……归于……金度！"
D.Strings[44981]="卫兵，快来保护我！"
D.Strings[44982]="欢迎光临塞拉摩岛。我能帮你什么忙吗？"
D.Strings[44983]="去和兵营第二层的出纳员兰德里谈谈吧。\n\n他会帮你安排，把物品存入塞拉摩的金库。"
D.Strings[44984]="这边走，$n。典礼马上就要开始了。"
D.Strings[44985]="到靶场附近去找杰森·法兰。"
D.Strings[44986]="霍拉斯·奥德尔就在普罗德摩尔女士的法师塔底层晃悠，你可以去那里找他。"
D.Strings[44987]="到兵营外的训练假人处寻找正在监督训练的卡尔曼修士。"
D.Strings[44988]="到兵营的拳击场去找阿伦·布莱特。\n\n他和古斯塔夫·范沃森医生正在监督岛上治疗者的训练。"
D.Strings[44989]="我不太确定。你可以到码头上去问问加莉亚·哈斯汀。我听说她和军情七处有联系。"
D.Strings[44990]="一个萨满……？\n\n塞拉摩的旅店里有个长得挺粗糙的矮人小姑娘，我想她是来这拜访老朋友的吧。\n\n她也许能帮上你。"
D.Strings[44991]="还有……那个……去中心塔楼底层找一个穿红色长袍的女人，但别说我派你去的。\n\n她叫雷迪亚·沃恩特。记住，千万别提我的名字。"
D.Strings[44992]="向兵营第二层的伊文凯恩队长报到。他将负责你的训练。"
D.Strings[44993]="炼金师纳瑞特和布兰特·加斯布鲁姆就在小作坊外面，他们可以教你炼金术和草药学，也许能帮上你。"
D.Strings[44994]="据我所知，这次到访的绒套家族矮人当中有一个考古学家。\n\n我想应该是那位太太，菲娜。他们都可算是探险者。到旅店去找他们吧。"
D.Strings[44995]="到铁匠铺去找玛蕾·霍斯顿。"
D.Strings[44996]="克莱格·诺瓦德就在旅店的厨房里工作。他可以帮你。"
D.Strings[44997]="丽萨·斯贝维克位于法师塔顶层，她是吉安娜女士手下的附魔师当中的佼佼者。"
D.Strings[44998]="到铁匠铺去找卡兹·双链。"
D.Strings[44999]="古斯塔夫·范沃森医生就在兵营的底层工作。"
D.Strings[45000]="码头上的迈克尔·克罗维可以教你捕鱼、剖鱼相关的各种知识。"
D.Strings[45001]="到普罗德摩尔女士的法师塔顶层去找瑟尔顿·曼勒斯。"
D.Strings[45002]="我敢肯定，次到访的绒套家族矮人当中就有一个珠宝匠。\n\n我想应该是那位丈夫，因格。他们都可算是探险者。到旅店去找他们吧。"
D.Strings[45003]="到塞拉摩的旅店里去找坦维尔兄弟吧。他们俩当中，应该有一个能帮你。"
D.Strings[45004]="神之真言，充盈我心，剧毒之血，灌注我身。你们将浸沐在蛇神的荣光之中。"
D.Strings[45005]="到塞拉摩的铁匠铺外去找矮人科尔里克吧。\n\n他是个酒鬼，还喜欢乱用炸药。不过他很友好，而且对矿物有独到的理解。"
D.Strings[45006]="你可以去找珊莎·玛克温斯，她就在塞拉摩的兽栏外面。"
D.Strings[45007]="提莫斯·沃森特就在塞拉摩那座大型建筑的二楼工作。他应该能帮你。"
D.Strings[45008]="跟着我，凡人！裂隙就在附近。"
D.Strings[45009]="我们该往哪儿走？"
D.Strings[45010]="有个哨兵接近了！快藏起来！！"
D.Strings[45011]="干得好，我的女士。我马上就会处理掉那些入侵者。"
D.Strings[45012]="|TInterface\\Icons\\ability_mage_worldinflames.blp:20|t%s开始施放|cFFFF6600|Hspell:99171|h[噬体烈焰]|h|r！"
D.Strings[45013]="快点！赶紧穿过裂口。"
D.Strings[45014]="我来处理这个家伙。你们去找他的同伙。"
D.Strings[45015]="我需要训练，科伦克。"
D.Strings[45016]="检测到敌对行为。激活11-b号安全协议。"
D.Strings[45017]="啊！我们不能再耽误了！"
D.Strings[45018]="这些真美味！"
D.Strings[45019]="我觉得有点饿了……"
D.Strings[45020]="那块肉闻起来真香。"
D.Strings[45021]="肋排！我的最爱！"
D.Strings[45022]="我去哪里吃第二顿呢？"
D.Strings[45023]="聪明的血肉之躯，懂得在命运之风中翱翔。是的，我知道你要找的人——兽人先知，缚地者……$b$b我感到他就在附近，他内心的恐惧掀起了一场风暴。你可以去找他……但后果自负。"
D.Strings[45024]="我们找到他了！但他变成了风暴……我要试着平息它，才能设法接近。"
D.Strings[45025]="我失败了。我辜负了这个世界……$b$b元素……不再和我交谈了。大地之环……也不再相信我的领导。我的无能……将艾泽拉斯……引向了湮灭。"
D.Strings[45026]="古伊尔，是我——阿格娜！你不认得我了？"
D.Strings[45027]="湮灭……只有……湮灭……"
D.Strings[45028]="他离得太远了！我们不能放弃！"
D.Strings[45029]="我辜负了部落……不合格的酋长……$b$b加尔鲁什会毁掉部落……$b$b毁掉我的人民。凯恩，我的兄弟……为何我不听信于你？"
D.Strings[45030]="你做了最好的选择，古伊尔！战胜那些怀疑！他们在吞噬你的心！"
D.Strings[45031]="……为何我不听信于你？"
D.Strings[45032]="打起精神——另一波又来了！"
D.Strings[45033]="我认识你的脸……阿格娜！哦，我的心——你看不到吗？我……一无是处。自私……我所做的一切……仅仅是为了满足我的傲慢。我……配不上你……"
D.Strings[45034]="你是古伊尔，杜隆坦与德拉卡之子！名正言顺的部落酋长！你还赢得了我的心！记住你是谁！"
D.Strings[45035]="阿格娜……真的是你……"
D.Strings[45036]="平静下来，我的爱人。冷静心绪。你成了使命的奴隶。但只有直面内心，你才能继续履行使命……为了你的人民……也为了我。"
D.Strings[45037]="阿格娜，我……我坚持不住了……啊！"
D.Strings[45038]="|TInterface\\Icons\\spell_fire_ragnaros_splittingblow.blp:20|t%s开始施放|cFFFF0000|Hspell:98951|h[爆裂打击]|h|r！"
D.Strings[45039]="|TInterface\\Icons\\spell_fire_selfdestruct.blp:20|t%s施放了|cFFFF6600|Hspell:98164|h[熔岩陷阱]|h|r!"
D.Strings[45040]="对不起，旅行者。我没什么东西可以给你。"
D.Strings[45041]="我们终于到了！"
D.Strings[45042]="保护好自己，朋友。那些进攻者很难缠。"
D.Strings[45043]="当心！无论如何都要避开他的吐息！"
D.Strings[45044]="我摧毁了他的护盾，释放你的能量吧！"
D.Strings[45045]="注入我的力量吧！"
D.Strings[45046]="接受蓝龙军团的祝福吧！"
D.Strings[45047]="|TInterface\\Icons\\spell_shaman_lavasurge.blp:20|t%s开始施放|cFFFF0000|Hspell:98710|h[萨弗拉斯重击]|h|r！"
D.Strings[45048]="今天的风很奇怪，真的很奇怪。"
D.Strings[45049]="我准备好了，元素。送我去见萨尔吧。"
D.Strings[45050]="$n，你抛弃了我们，现在居然还有胆跟我讲话？$b$b你这是愚蠢，还是勇猛？鉴于你过去的行为，我看你这是愚蠢至极。$b$b过会再和我讲话，我需要守护营地。"
D.Strings[45051]="逃兵……$b$b你想要做什么，$c？我们忙着守卫营地，可没空理你这种懦夫。$b$b等我心情好点再和我说话。"
D.Strings[45052]="%s吞掉了鱼。"
D.Strings[45053]="喔，瞧瞧你……已经死了。"
D.Strings[45054]="以圣光的名义，成功了！格瑞诺尔太聪明了……喔，希望没把你捏疼……不过当你尝到那肉的味道时，就知道一切都是值得的！"
D.Strings[45055]="哼……懦夫。"
D.Strings[45056]="啤酒和羊杂馅饼，纯爷们就该这么吃！"
D.Strings[45057]="你怎么知道我爱吃什么？"
D.Strings[45058]="早饭吃羊杂馅饼，中饭吃羊杂馅饼，晚饭显然也要吃羊杂馅饼！"
D.Strings[45059]="多给我些如此美味的食物你就是我最好的朋友了！"
D.Strings[45060]="替我谢谢达瑞尔，好不？"
D.Strings[45061]="暮光爪牙出现在魔枢……$b$b这真是危急万分的时刻，$r。"
D.Strings[45062]="不，不！离开这里！我只想独自怀念我的姐妹！"
D.Strings[45063]="我劝过你离开的！"
D.Strings[45064]="我发誓要保护这个地方！"
D.Strings[45065]="哈！你不过是个无聊的玩物！"
D.Strings[45066]="分担我的痛苦！"
D.Strings[45067]="感受我的痛楚！"
D.Strings[45068]="这个身体已经没用了……"
D.Strings[45069]="黑暗先驱吞噬了灵魂碎块，获取了灵魂能量！"
D.Strings[45070]="你来了！我还以为你带着啤酒逃走了！"
D.Strings[45071]="呀哈！我来杀希尔瓦娜斯啦！"
D.Strings[45072]="嗨，看看，这里有人居住。这可完全不像我的老家那些暗夜精灵的大树城市。"
D.Strings[45073]="我很生气，我们又失去了冬拥湖！取而代之的，我要杀了你们强大的领袖——希尔瓦娜斯。"
D.Strings[45074]="托尔巴拉德输了，我们必须复仇！我将给这座城市带去死亡。当我想起来如何战吼时，颤栗吧！"
D.Strings[45075]="部落的大块头们战栗吧！联盟在此！"
D.Strings[45076]="我在何处？我和埃索达一起坠毁了，却撞见了这座壮观的城市……"
D.Strings[45077]="作为一个小得可怜的侏儒，我觉得这座城市真大啊。"
D.Strings[45078]="和其他矮人一样，我又喝醉了。我挖了一条通道，钻出来就到了这儿。谁要喝酒？"
D.Strings[45079]="能再给我个诱捕工具吗？"
D.Strings[45080]="能再给我些肿胀青蛙吗？"
D.Strings[45081]="你就不担心那东西里放了什么吗？"
D.Strings[45082]="完全不担心！我在剃刀岭兵营吃了三年臭虫仙人掌浓汤也没闹过肚子，一大碗蟑螂算什么。"
D.Strings[45083]="蟑螂？！它们难道……不会吧！太恶心啦。"
D.Strings[45084]="哈！哈！哈！尽情享受这腐烂的口粮吧。汤汁真美味啊。"
D.Strings[45085]="你挑选配料很有眼光啊。"
D.Strings[45086]="选这个给阿丝卡？她会很高兴的。"
D.Strings[45087]="那个？好样的。这可是这边最好的。"
D.Strings[45088]="选得好，阿丝卡一定会很满意的。"
D.Strings[45089]="只挑最好的，是吧？"
D.Strings[45090]="你是来这里拿阿丝卡的订单的？请帮我向她问好。"
D.Strings[45091]="你准备付钱吗？哦，这是给阿丝卡的！那小心点拿。"
D.Strings[45092]="壕沟怪物潜入了水中。"
D.Strings[45093]="这是对你的审判。"
D.Strings[45094]="承认你的虚弱。"
D.Strings[45095]="你们不能进入主人的领地，凡人。"
D.Strings[45096]="我的熔岩之怒会烧尽你们！"
D.Strings[45097]="秉承炎魔之王的命令，你也会被毁灭！"
D.Strings[45098]="来到火焰的国度，就要付出血肉的代价。"
D.Strings[45099]="%s开始撤退并呼唤盟友的保护！"
D.Strings[45100]="愚蠢的凡人。你们这是自寻死路。"
D.Strings[45101]="净化的时刻到了！"
D.Strings[45102]="看那边，漩涡中有一个幻象！那就是古伊尔长久以来的期望吗？和平……摒弃敌意，结束连绵不绝的战争？"
D.Strings[45103]="他……希望放下他的武器……放下领袖的负担……"
D.Strings[45104]="另一个幻象！那是古伊尔，但……另一个人……是我。我是他最深的渴望？一个伴侣，能够分享他的生命，分享他的负担和喜悦？"
D.Strings[45105]="最后一个幻象！先祖啊……难道那是……我和他的孩子？他最深的渴望……是成为父亲？"
D.Strings[45106]="拥有自己的家庭……和我一起……？古伊尔从未见过他的父母……他几年前才找到自己的族人……我早该知道这就是他最深的渴望。"
D.Strings[45107]="先祖们，赐予我力量！漩涡的引力在增加！他的渴求之力……太强大了！"
D.Strings[45108]="很好。见证新主人赋予我的纯粹力量吧！"
D.Strings[45109]="在阿格娜被卷入漩涡前找到并救出她！"
D.Strings[45110]="你做到了不可能的事情，萨满。你平息了他心中的漩涡，而不是被它所吞噬。你对他的爱……一定非常伟大。"
D.Strings[45111]="我……和这个世界……都如此的需要他。但他却总是将其他人的需要凌驾在了自己之上。他究竟将自己的情感和渴望……压抑了多久？"
D.Strings[45112]="他的形态又开始变化了！你要失去他了！"
D.Strings[45113]="古伊尔！"
D.Strings[45114]="快，凡人。$b$b我们在魔枢里汇合！"
D.Strings[45115]="%s开始引导一次大规模暗影新星！"
D.Strings[45116]="蛆虫般的凡人！你们胆敢入侵我的领地？烈焰之灵将烧尽你们的傲慢。"
D.Strings[45117]="这是我的王国！"
D.Strings[45118]="火焰的奴仆！净化外来者！"
D.Strings[45119]="烈焰的子民，来我身边！"
D.Strings[45120]="起来吧，烈焰的奴仆，吞噬敌人的血肉！"
D.Strings[45121]="对你的审判降临了！"
D.Strings[45122]="够了！我会亲自解决。"
D.Strings[45123]="跪下吧，凡人们！一切都结束了。"
D.Strings[45124]="萨弗拉斯将会是你的末日。"
D.Strings[45125]="太早了！……你们来得太早了……"
D.Strings[45126]="太早了……"
D.Strings[45127]="啊，外来者——这不是你们的领地！"
D.Strings[45128]="当我解决了这场战斗，你们可悲的凡人世界将被我的复仇之焰烧尽！"
D.Strings[45129]="不，不——这本该是我的荣耀之时……"
D.Strings[45130]="别担心，我会保护好火红鞭笞者的。但在我们熟悉它的习性之前，它恐怕只能留在火焰之地了。"
D.Strings[45131]="多么特殊的标本啊！具有如此之多的可能性！我一定要更加努力地研究当地的动植物了。"
D.Strings[45132]="在我埋头搞研究的时候，你可以教教鞭笞者处世之道。"
D.Strings[45133]="你不会得逞的！"
D.Strings[45134]="%s正在恢复。驱散他的暮光回复法术！"
D.Strings[45135]="快！你必须在阿格娜被卷入漩涡前把她救出来！"
D.Strings[45136]="哈？软骨头的血肉凡人？在这里？麻烦，真麻烦！"
D.Strings[45137]="解决。"
D.Strings[45138]="太软了！"
D.Strings[45139]="小害虫，真吵闹。"
D.Strings[45140]="嗷，干什么。"
D.Strings[45141]="啊——讨厌的小害虫，瞧瞧你们都干了些什么！"
D.Strings[45142]="呜啊……你们现在惹我生气了！"
D.Strings[45143]="哦你们这些小畜生……"
D.Strings[45144]="践踏。"
D.Strings[45145]="我要踩烂你们！"
D.Strings[45146]="我已经沉睡了无数的时光，现在却被这些血肉生灵所扰……你们将燃烧殆尽！"
D.Strings[45147]="屈服于烈焰之灵。"
D.Strings[45148]="我的烈焰永不熄灭。"
D.Strings[45149]="吞噬……"
D.Strings[45150]="血肉……燃烧吧！"
D.Strings[45151]="碎掉了。呃……碎掉了……"
D.Strings[45152]="碾碎，碾碎，碾碎！"
D.Strings[45153]="烧毁他们孱弱的血肉。"
D.Strings[45154]="碎骨成灰！"
D.Strings[45155]="踩死他们，烧死他们！"
D.Strings[45156]="你到我们的家园来干什么呢，幼龙？"
D.Strings[45157]="卡雷苟斯已经被推举为蓝龙军团的新守护巨龙。$b$b你们中的一位勇士曾帮助阻止了阿瑞苟斯倒向死亡之翼，从而避免了一场灾难。$b$b今天，我们欢聚一堂，以颂扬他们的英雄事迹。"
D.Strings[45158]="你可以去找他……但后果自负。"
D.Strings[45159]="你认为这会有用吗，古伊尔，德鲁伊与萨满联手治愈世界之树？这能治疗这个崩坏的世界？"
D.Strings[45160]="伊瑟拉女王。"
D.Strings[45161]="古伊尔！不！"
D.Strings[45162]="但古伊尔怎么办？"
D.Strings[45163]="不！那些杂种偷走了我的古伊尔，但我决不会抛弃他。先祖在上……我的心也随他一同被偷走了。"
D.Strings[45164]="守护巨龙相信这有用……"
D.Strings[45165]="……毕竟是他们种下了这棵树。"
D.Strings[45166]="怒风大师。你能回到清醒的世界真是太好了。"
D.Strings[45167]="暮光之锤！"
D.Strings[45168]="我不惧怕死亡。"
D.Strings[45169]="欢迎，杜隆坦之子。也欢迎你，霜狼氏族的阿格娜兰。"
D.Strings[45170]="朋友们，我们今日聚集于此，是为了治愈这个用无数牺牲换回的世界。"
D.Strings[45171]="他是大地之环最强大的萨满，这场仪式不可能在他缺席的情况下继续。但我们必须做好心理准备，接受他永远消失的可能性。"
D.Strings[45172]="你们好，朋友们。"
D.Strings[45173]="我能感到你体内的巨大力量，年轻的萨尔。这些年你成长了不少。"
D.Strings[45174]="你会为此后悔的，入侵者！"
D.Strings[45175]="范达尔……他们对你做了什么？"
D.Strings[45176]="范达尔在腐蚀其他的德鲁伊。他也许已经有了邪恶的追随者——我必须立即警告月光林地。"
D.Strings[45177]="时间是宝贵的，姐妹。让我们准备仪式吧……"
D.Strings[45178]="抱歉，打扰诸位了吗？"
D.Strings[45179]="没那么快，杜隆坦之子！你和你的盟友的确阻碍了我们，但暮光审判日是不可避免的！"
D.Strings[45180]="死？谁提到过死这个字的？"
D.Strings[45181]="你也许是这个世界上最强大的萨满，萨尔——但你仍然是个凡人。主人的诅咒将降临于你——你与元素的伟大盟约将变成你的……毁灭！"
D.Strings[45182]="我会吗？"
D.Strings[45183]="看看我，大导师——想必你还认得你从前的学生吧？"
D.Strings[45184]="你还是这么天真。你的兽人宠物救不了你，玛法里奥。"
D.Strings[45185]="听我说，古伊尔！你并不孤单！我与你同在——我不会放弃你！"
D.Strings[45186]="哦，古伊尔！坚持住！我会救出你，让你拥有这样的生活，我发誓！"
D.Strings[45187]="他必须拥抱渴望，并找到平衡……否则诅咒永无终结。"
D.Strings[45188]="战胜它，古伊尔！你必须摆脱它！"
D.Strings[45189]="暮光先知已经洞察到你——只有你——是我们最后的阻碍……于是他派我来送你退场。"
D.Strings[45190]="元素无时不在撕裂你的身体——它们将以你的恐惧和怀疑为食，直到这个悲惨世界上的最后一丝生命之光熄灭为止。"
D.Strings[45191]="我们复仇的烈焰已经逼近了。准备好吧"
D.Strings[45192]="这是史上第一次，大地之环与塞纳里奥议会将联合在一起——为了恢复这棵巨树，治愈整个艾泽拉斯世界。"
D.Strings[45193]="有人吗……谁来帮帮我？"
D.Strings[45194]="他们的数量太多了！我不知道我们还能撑多久！古伊尔，是时候该醒醒了！"
D.Strings[45195]="我们要有耐心。"
D.Strings[45196]="刚才是他——？古伊尔，你能听见吗？我们需要你的帮助！动手吧！"
D.Strings[45197]="古伊尔！快醒醒，不然我们都要死了！"
D.Strings[45198]="他可不能老这么说！"
D.Strings[45199]="该死，古伊尔，快醒过来！一切不能就这样结束！我们绝不能失败！"
D.Strings[45200]="啊，你别再叫我保持耐心了你这个绿皮……"
D.Strings[45201]="现在！苏醒吧！"
D.Strings[45202]="阿格娜……我听到了你的声音……呼唤着我……$b$b我们在哪？"
D.Strings[45203]="你就要到家了，我的爱人。我们的时间很短……你又要变形了，古伊尔——但我会找到你！我永远不会放弃你！"
D.Strings[45204]="阿格娜？阿格娜！我听不见——"
D.Strings[45205]="熔火之卵开始孵化了！"
D.Strings[45206]="奥利瑟拉佐尔开始高速盘旋！狂风将移除火焰之翼的效果！"
D.Strings[45207]="|TInterface\\Icons\\ability_mage_firestarter.blp:20|t一股来自|cFFFF0000|Hspell:99794|h[火焰漩涡]|h|r的强风！"
D.Strings[45208]="|TInterface\\Icons\\spell_holiday_tow_spicecloud.blp:20|t奥利瑟拉佐尔的火焰|cFFFF0000|Hspell:99432|h[燃尽]|h|r了！"
D.Strings[45209]="|TInterface\\Icons\\inv_elemental_primal_fire.blp:20|t奥利瑟拉佐尔的火焰核心重新|cFFFF0000|Hspell:99922|h[引燃]|h|r了！"
D.Strings[45210]="|TInterface\\Icons\\spell_shaman_improvedfirenova.blp:20|t奥利瑟拉佐尔处于|cFFFF0000|Hspell:99925|h[蓄满力量]|h|r状态！"
D.Strings[45211]="凡人们，我现在侍奉新的主人！"
D.Strings[45212]="为了主人的荣耀！"
D.Strings[45213]="天空，归我统治！"
D.Strings[45214]="我会从空中烧死你们！"
D.Strings[45215]="火焰……火焰……"
D.Strings[45216]="浴火重生！"
D.Strings[45217]="烈焰之光……不能熄灭……"
D.Strings[45218]="我们将共同恳求火焰之主！"
D.Strings[45219]="我们在此恳求您，炎魔之王！"
D.Strings[45220]="目睹烈焰君王！"
D.Strings[45221]="没人能逃过火焰之地的愤怒！"
D.Strings[45222]="无信者将在火焰中毁灭！"
D.Strings[45223]="<暗影守望者静静地看着你。>"
D.Strings[45224]="你见过这样的东西吗？"
D.Strings[45225]="大地在我们脚下战栗，呻吟。火雨从空中倾泻而下。生灵在炽热的空气中窒息。这才是炎魔之王的国度。"
D.Strings[45226]="我们还不能休息，孩子。海加尔还没有沦陷。但如果我们在炎魔之王的门前踯躅，仍有可能一败涂地。愿远古半神的力量与我们同在。"
D.Strings[45227]="风暴乌鸦很难在这种高密度的空气中飞行，可那边山脊上的火鹰翱翔起来却好像很轻松。$B$B它们和这片火焰平原上的其他生物一样狂野，但它们的形态却十分美丽。"
D.Strings[45228]="只要有足够的时间，我们就能恢复这片土地。"
D.Strings[45229]="我们只不过是勉强站稳脚跟而已。所以我们需要每一个健全的士兵全部到岗。"
D.Strings[45230]="除了挣扎求生，战争还有什么其他意义呢？就像种子要努力破土发芽一样，我们也要为自己的生存而战。"
D.Strings[45231]="噢喔，你脸上好像有东西！"
D.Strings[45232]="我们能否赢得这场战争？只有天知道。"
D.Strings[45233]="这里可真闷热。有人让他们升高温度了吗？"
D.Strings[45234]="奥利瑟拉佐尔不能重燃了！快击败她！"
D.Strings[45235]="我喜欢你！青出于蓝啊。"
D.Strings[45236]="有人说我很土，可我觉得自己还挺睿智的。"
D.Strings[45237]="噢，又是你呀！你觉得，我们能召集到足够的部队吗？"
D.Strings[45238]="我从来没见过这么荒凉的地方。"
D.Strings[45239]="我们就站在贝丝缇拉克的产卵区中心。在北边那些柱子那边，就有她的子嗣。它们会拼命保护她的幼崽的。"
D.Strings[45240]="你关于守望者的一切疑问，都将在战场上找到答案。"
D.Strings[45241]="守望者是什么人？我们是精密的杀戮机器。"
D.Strings[45242]="守望者是什么人？我们是播撒死亡的旋刃。"
D.Strings[45243]="守望者是什么人？我们是无声的暗影。"
D.Strings[45244]="我们在战场上表现如何？"
D.Strings[45245]="我们用无数的牺牲才换来这个据点，但为了保住它，我们还要继续战斗。虽然我们的防御很薄弱，但只要我们不断推进战线，将来一定能招来更强大的盟友。$B$B现在，拿出勇气来吧，勇士。"
D.Strings[45246]="我们终于守住了这个据点，这多亏了你。$B$B你帮我们找到了一个珍贵的盟友。可是，敌人对我们的进攻不会停歇。$B$B我们必须守住这里，否则就会失去我们流血牺牲所换来的一切。"
D.Strings[45247]="在你的帮助下，暗影守望者和猛禽德鲁伊站到了我们这边。$B$B干得好，$c。$B$B我们已经开始扩张了，但还有许多事要做。$B$B在敌人的持续攻击下，我们仍继续建造防御工事。我们需要三样东西，$n。$B$B老树干和远古的保卫者们正守护着海加尔，可这里也急需他们的力量。$B$B虽然我们士气正盛，可我们的军械库仍需要补充额外的军用物资。$B$B最后，艾露恩的神圣之水能够治愈我们的伤兵，并让他们重获新生。$B$B为了完成这里的任务，我们需要这些东西。$B$B去吧，$n。你的努力对我们取得胜利至关重要。"
D.Strings[45248]="你做得很好，$c。拉格纳罗斯已经不能再无视我们的存在了。我们已经成了他的心腹大患。虽然他已经怒火高涨，我们仍要继续推进。$B$B在这里，我们必须时刻保持警惕，但我们应该考虑一下最终的决战了。挑战炎魔之王本人的时刻到了。"
D.Strings[45249]="用你的眼睛去看。你看到了什么？你感觉到了什么？"
D.Strings[45250]="艾维娜之风，赐予我压制火焰的力量吧！"
D.Strings[45251]="在我们准备进攻火焰之地的时候，炎魔之王派出了手下爪牙来拦截我们。我们在这里的据点绝对不能陷落，我们已经是保卫世界之树的最后一道防线了。"
D.Strings[45252]="欢迎你，$n。你是来参加对火焰之地的进攻的吗？"
D.Strings[45253]="我们暂时还无力反攻火焰之地。首先，我们得重整部队，建立补给线。你愿意帮助我们吗？"
D.Strings[45254]="眼前所发生的一切与我们所有人都息息相关。每一分力量都是宝贵的。大家必须同心协力对抗入侵。"
D.Strings[45255]="有小动物吗需要我救助吗？$B$B<米露恩两眼放光。>$B$B我要立刻去抱抱小兔子！"
D.Strings[45256]="准备工作进展如何？"
D.Strings[45257]="你好。大德鲁伊正在休息。$B$B我相信，你的造访一定会令他高兴的，但我们最好还是不要去打扰他。"
D.Strings[45258]="哈缪尔怎么样了？"
D.Strings[45259]="还很难说，他的伤很重。虽然他是位强大的德鲁伊，但我们还需要耐心地等待他彻底恢复。"
D.Strings[45260]="你好，$n。你是来协助我们进攻的嘛？像你这样出色的$c一定成为我们的宝贵外援。"
D.Strings[45261]="我需要一个真正有能力的人。我能指望你吗，$c？"
D.Strings[45262]="我们已经无路可逃了。该停下来战斗了。"
D.Strings[45263]="$n，我如何才能帮助你继续深造呢？"
D.Strings[45264]="如果你在寻求指导，恕我无法提供帮助。"
D.Strings[45265]="还有什么事儿能比骑魔法扫帚更能说明“嘿，万圣节到了”呢。"
D.Strings[45266]="你好啊！园艺可是我的强项！要打听本地的植物环境吗？"
D.Strings[45267]="没有什么比花朵的绽放更能振奋人心的了！"
D.Strings[45268]="跪拜在烈焰之前！"
D.Strings[45269]="我的古伊尔……被大海吞噬了。在他自己的欲望中煎熬！"
D.Strings[45270]="循环又开始了！古伊尔变成了活生生的石头！我们必须到深岩之洲的洞穴里去找他。$b$b在亲眼看到大地之环拯救了她的国度之后，塞拉赞恩应该更愿意帮我们救他了。如果她不肯，那位石母必将付出代价！"
D.Strings[45271]="滚出我的王国，虫子。"
D.Strings[45272]="我会看着你们燃烧。"
D.Strings[45273]="好吧，好吧。我很佩服你们的顽强。贝尔洛克已经在这座堡垒前守卫了千百个世纪。"
D.Strings[45274]="但从未有人能进入炎魔之王的居所！"
D.Strings[45275]="现在求饶，我也许会准许你们活下去。好吧，“英雄”们，你们的回答是什么？"
D.Strings[45276]="燃烧吧。"
D.Strings[45277]="整个艾泽拉斯都将燃烧！"
D.Strings[45278]="如此强大的力量！"
D.Strings[45279]="葬身于火海中！"
D.Strings[45280]="只留灰烬！"
D.Strings[45281]="是的，凡人，你们的萨尔就在这里。他的心和灵魂都已经和石头融合了。"
D.Strings[45282]="作为血肉凡人，他的灵魂十分强大。他令我惊奇……我不想放弃他。"
D.Strings[45283]="但我能听到哭泣的心声，遥远地回响在两个世界间的无尽迷宫里。这是为爱人哭泣的心声……伟大的塞拉赞恩并没有忘记爱是什么……"
D.Strings[45284]="你的救世萨满就在下面的玄武岩森林里。但他已经变成了这无尽岩石大厅的一部分。"
D.Strings[45285]="荣耀之焰！"
D.Strings[45286]="他也许不想离开，无论是谁在呼唤他。"
D.Strings[45287]="带着我的祝福……去找他吧。"
D.Strings[45288]="主人的力量有多种形式……"
D.Strings[45289]="看吧，这是火焰之地的愤怒！"
D.Strings[45290]="我的研究……才刚刚开始……"
D.Strings[45291]="感谢您，石母。"
D.Strings[45292]="快一点，朋友。古伊尔应该就在下方。"
D.Strings[45293]="战士们，做好准备。我们要进入敌人的领地了。"
D.Strings[45294]="注意。这片林地里充斥着火焰的仆从。"
D.Strings[45295]="全军警戒。如果遭遇偷袭，那就是生死立判了。"
D.Strings[45296]="一定得让这些入侵者知道，我们的土地不是那么好侵占的。我很乐意给它们上这一课。"
D.Strings[45297]="啊哈！闯入者！杀掉他们。吃掉他们！"
D.Strings[45298]="哦……真痛苦。炎魔之王……这真痛……"
D.Strings[45299]="好了，全队注意！大家都准备好了吗？"
D.Strings[45300]="随时待命，队长。"
D.Strings[45301]="该是战争践踏登场的时候了。"
D.Strings[45302]="早就迫不及待了。"
D.Strings[45303]="没问题，伙计。我们赶紧动手吧。"
D.Strings[45304]="好了，全队准备完毕！进攻！"
D.Strings[45305]="现在，你去死吧！"
D.Strings[45306]="炎魔之王会非常高兴的。"
D.Strings[45307]="|TInterface\\Icons\\ability_mage_worldinflames.blp:20|t%s开始施放|cFFFF6600|Hspell:100171|h[烈焰世界]|h|r！"
D.Strings[45308]="一文不值！"
D.Strings[45309]="这是你的晚餐！"
D.Strings[45310]="燃烧吧！"
D.Strings[45311]="裂肢——不。不！你们这些冷酷的野兽，你们怎么敢？！"
D.Strings[45312]="你们这些凶手！为什么你们要杀掉这么一只高贵的动物！"
D.Strings[45313]="对，裂肢，我也闻到他们了。外来者侵入了炎魔之王的领地。跟着足迹，把他们揪出来。我会让他们受罚！"
D.Strings[45314]="在烈焰中挣扎吧，闯入者！"
D.Strings[45315]="咬他的喉咙！"
D.Strings[45316]="我来奶吧，兄弟。我可是有特殊形态的哦。"
D.Strings[45317]="感觉到空气中的魔法能量了吗，$c？"
D.Strings[45318]="列队！我们准备好出发了。"
D.Strings[45319]="在这个季节，空气中弥漫着强大的法力，$c。"
D.Strings[45320]="我准备好了，我们去轰炸暴风城吧！"
D.Strings[45321]="干得好，德鲁伊们！这个地方看起来很安全。我们回营地去吧。"
D.Strings[45322]="准备进入飞行形态，倒数3秒……"
D.Strings[45323]="风暴乌鸦，出发！"
D.Strings[45324]="干得不错，各位！休息一下，然后立刻回去复命。"
D.Strings[45325]="火焰。我的爱人变成了火焰。我害怕的事发生了。我们必须进入拉格纳罗斯的火焰领地寻找他。"
D.Strings[45326]="保持坚强，朋友。你我心中都清楚……在火焰之地，我们将孤立无援。"
D.Strings[45327]="联盟突袭了德莱尼废墟！"
D.Strings[45328]="部落突袭了德莱尼废墟！"
D.Strings[45329]="联盟夺取了德莱尼废墟！"
D.Strings[45330]="部落夺取了德莱尼废墟！"
D.Strings[45331]="联盟守住了德莱尼废墟！"
D.Strings[45332]="部落守住了德莱尼废墟！"
D.Strings[45333]="$n突袭了德莱尼废墟！如果不赶快采取行动的话，联盟将在1分钟内占据它！"
D.Strings[45334]="$n突袭了德莱尼废墟！如果不赶快采取行动的话，部落将在1分钟内占据它！"
D.Strings[45335]="|c00FF0000%s召唤燃烧宝珠！|r"
D.Strings[45336]="联盟夺取了魔能机甲废墟！"
D.Strings[45337]="部落夺取了魔能机甲废墟！"
D.Strings[45338]="$n守住了魔能机甲废墟！"
D.Strings[45339]="$n突袭了魔能机甲废墟！如果不赶快采取行动的话，联盟将在1分钟内占据它！"
D.Strings[45340]="$n突袭了魔能机甲废墟！如果不赶快采取行动的话，部落将在1分钟内占据它！"
D.Strings[45341]="|c00FF0000灼热之种开始生长！|r"
D.Strings[45342]="联盟夺取了法师塔！"
D.Strings[45343]="部落夺取了法师塔！"
D.Strings[45344]="$n守住了法师塔！"
D.Strings[45345]="$n突袭了法师塔！如果不赶快采取行动的话，联盟将在1分钟内占据它！"
D.Strings[45346]="$n突袭了法师塔！如果不赶快采取行动的话，部落将在1分钟内占据它！"
D.Strings[45347]="联盟夺取了血精灵塔！"
D.Strings[45348]="部落夺取了血精灵塔！"
D.Strings[45349]="$n守住了血精灵塔！"
D.Strings[45350]="$n突袭了血精灵塔！如果不赶快采取行动的话，联盟会在1分钟内控制它！"
D.Strings[45351]="$n突袭了血精灵塔！如果不赶快采取行动的话，部落会在1分钟内控制它！"
D.Strings[45352]="准备，倒数3秒……"
D.Strings[45353]="作战形态，出发！"
D.Strings[45354]="滚出这片土地，入侵者！"
D.Strings[45355]="我磨利了自己的爪子，等的就是这一刻！"
D.Strings[45356]="我的獠牙很大吧？这还多亏了你。"
D.Strings[45357]="尝尝我的月光射线吧！"
D.Strings[45358]="火！火！火！"
D.Strings[45359]="每一棵树都抗拒你的到来！"
D.Strings[45360]="滚回烈焰中去吧，混蛋。"
D.Strings[45361]="你的一切努力都是徒劳的，破坏者。等干掉你之后，我们会再次治愈它。"
D.Strings[45362]="去死吧！在烈焰中再死一次吧。"
D.Strings[45363]="我要用怒吼吓跑他们！"
D.Strings[45364]="瞄准敌人！"
D.Strings[45365]="你再不跑的话，可就来不及了！"
D.Strings[45366]="德鲁伊小队，进攻！"
D.Strings[45367]="你是来参战的吗，$c？"
D.Strings[45368]="啊，$n。真高兴，我们又见面了。这儿危机重重，所以我也加入了战斗。我发现你也成长了不少。很好。我和你的族人都为你感到自豪。"
D.Strings[45369]="$n的触摸令诺达希尔的分枝产生了强烈反应！"
D.Strings[45370]="我就知道会在这儿见到你，$n。我一直觉得你是我最出色的学生。很荣幸能和你并肩战斗，朋友。"
D.Strings[45371]="$n，你看起来不错。获悉征召令后我背井离乡，来这里加入战斗。$B$B分别后你长进许多。能教导你我感到十分荣幸。你是联盟真正的英雄。"
D.Strings[45372]="你好，$n。我听说了动员令，所以暂时进入了战斗形态。我会的都已经教给你了，现在我要给上最后一课。作为一名光荣的部落战士，勇敢地去战斗吧，年轻人。"
D.Strings[45373]="暮光诅咒正在将古伊尔转换到另一种元素形态！在消失前，他进入了水元素位面。我们必须赶过去……"
D.Strings[45374]="受折磨的保护者身上一直燃烧着的火焰熄灭了！"
D.Strings[45375]="无论要走多远，我也绝不放弃他！"
D.Strings[45376]="够了……停下……"
D.Strings[45377]="阿格娜，我准备好前往深渊之喉了。"
D.Strings[45378]="烈焰不再折磨我了。但我也消耗殆尽了。"
D.Strings[45379]="我的力量只够传送一次。所以你一定要做好充分的准备。古伊尔在海底等着我们……"
D.Strings[45380]="孩子们都喜欢这个节日。有些孩子已经出去要糖果了，有些却只能留在这里。还有些孩子，比如你眼前这些，则想跟你们做个小小的交易。$b$b他们的目的是收集尽可能多的糖果，而他们想到的报酬就是送糖果给那些帮他们奔波的人。当我第一次他们说起这个打算时，都有点忍俊不禁，$c。可当我看到有那么多冒险者都愿意拿糖果来交换他们的小礼品时，我又开始担心了。$b$b他们拿到的糖果太多了。我担心孩子们从此再也睡不着觉了。"
D.Strings[45381]="你，诺达希尔之友！带走我残余的力量，击退烈焰的进攻！"
D.Strings[45382]="愿巨树之灵庇护着你……"
D.Strings[45383]="我会将我全部的力量传给你。愿世界之树的浓荫庇佑你不受这地狱烈焰的炙烤。"
D.Strings[45384]="对不起，亲爱的诺达希尔。我失败了……"
D.Strings[45385]="我们热情欢迎新的朋友，与他们一起展望并肩打造出的未来。"
D.Strings[45386]="这里的水域受到了干扰……发生了什么事？"
D.Strings[45387]="你好，旅行者。命运之潮指引你们从遥远明亮的世界而来。我知道你们在寻找什么——而他就在你们的面前……"
D.Strings[45388]="你的救世萨满已变成了渴求与欲望的漩涡。看到了吗？他的心正在吞噬一切。如果踏入其中，就连你也会被一同吞没。"
D.Strings[45389]="我们来得正好！古伊尔的灵魂变得不稳定了，如果不快点行动，他的灵魂可能会崩溃。"
D.Strings[45390]="你的救世萨满已经迷失在了暗流的深渊中。他只为吞噬而存在，被他内心汹涌的渴望所折磨，自己却浑然不知。"
D.Strings[45391]="我们一定会救出他，海卓里斯！一定会。"
D.Strings[45392]="我们已经耽搁得够久了。现在就对这个拉格纳罗斯的仆人动手吧。"
D.Strings[45393]="别再磨蹭了，我已经做好战斗的准备了。"
D.Strings[45394]="诺达希尔的分枝上出现了裂痕！法杖中涌出了某种强大的力量！"
D.Strings[45395]="%s灼热的身体开始发光并燃烧！"
D.Strings[45396]="我们将燃烧后的灰烬抹在脸上，告诉那些新的敌人——那些畏惧我们，视我们为怪物的人。"
D.Strings[45397]="我们亲眼看到自己的家园被夷平。"
D.Strings[45398]="那些认为我们不该存在于世上的人……"
D.Strings[45399]="不是！我们是一股更加恐怖的力量……"
D.Strings[45400]="阿格娜，我准备好前往深岩之洲了。"
D.Strings[45401]="亲人惨遭屠戮，而我们却只能悲愤地哭嚎。"
D.Strings[45402]="我们越早摆脱石母越好。我不相信她。"
D.Strings[45403]="我们承受过太多……那远远超过了我们的想象。"
D.Strings[45404]="请站到我面前来，将你的一切烦恼抛诸身后。"
D.Strings[45405]="我们要做的是嘲笑一切恐怖的存在，大胆瞪视残酷的未知，并放声大笑！"
D.Strings[45406]="让它随燃烧的火苗灰飞烟灭，使我们能沉着应对未来的一切。"
D.Strings[45407]="幼蛛从巢穴里爬出来了！"
D.Strings[45408]="烬网织网蛛爬下来了！"
D.Strings[45409]="我们抵达的时候，召唤符文都已经画好了。你必须把它们全部摧毁。"
D.Strings[45410]="不，恶魔。你的时间不多了。"
D.Strings[45411]="英雄们！他被束缚了！解决他！"
D.Strings[45412]="终于结束了！"
D.Strings[45413]="英雄们，这个世界欠你们太多了。"
D.Strings[45414]="拉格纳罗斯灰飞烟灭了。但他所代表的原始力量不会终结。将来，必定会有人替代他。"
D.Strings[45415]="是的，塞纳留斯。必须在这设立一个永久的岗哨。先庆祝这一天吧，庆祝这来之不易的伟大胜利。"
D.Strings[45416]="看那儿！看看他，被禁锢在石头中，无法动弹。毫无知觉。他脸上的表情……如此坚定，如此顽固。这是他拒绝妥协的表情。"
D.Strings[45417]="我见过这个表情。那是在纳格兰，他拒绝放下酋长的责任。在他受训时也出现过。"
D.Strings[45418]="我就知道！暮光之锤知道我们会来这里！保护你自己！"
D.Strings[45419]="即使是现在，无数的敌人在我们周围蠢蠢欲动，他还是拒绝行动。唉，古伊尔……有时你真是惹人生气。"
D.Strings[45420]="朋友……请接受我最深的感谢。你的勇气，你的力量……你……$b$b你让我想起了他。"
D.Strings[45421]="阿格娜，我准备好了。我们去见萨尔吧。"
D.Strings[45422]="%s开始吸取熔岩之池。"
D.Strings[45423]="熔岩火虫从地下涌出来了！"
D.Strings[45424]="|TInterface\\Icons\\inv_misc_horn_03.blp:20|t就在火焰之地的怪物轰然倒地之时，远处传来了猎人的号角声。"
D.Strings[45425]="|TInterface\\Icons\\inv_misc_horn_03.blp:20|t猎号声再次响起，显得越发迫近。"
D.Strings[45426]="圣杯的一小滴液体形成了一小口月亮井。"
D.Strings[45427]="熔火之卵开始开裂了！"
D.Strings[45428]="金度给自己的武器注入了哈卡之影！"
D.Strings[45429]="烈焰树人从地下涌出，来协助保护者了！"
D.Strings[45430]="%s即将|cFFFF0000现身|r！"
D.Strings[45431]="杀死空气图腾附近的元素，它们在西边！"
D.Strings[45432]="杀死水图腾附近的元素，它们在北边！"
D.Strings[45433]="杀死大地图腾附近的元素，它们在东边！"
D.Strings[45434]="杀死火焰图腾附近的元素，它们在萨尔身边！"
D.Strings[45435]="我的父母……在我懂事之前就被害了……背叛！"
D.Strings[45436]="古尔丹！我的怒火会烧尽来世之路，将你从藏身的地狱中揪出来！"
D.Strings[45437]="我的复仇终将实现！你听到了吗？？？"
D.Strings[45438]="他可真是发怒了！如此愤怒，如此痛苦……这么多年来他一直用自己的力量压抑着……"
D.Strings[45439]="当作奴隶养大，为取悦人类而杀戮……"
D.Strings[45440]="死亡对布莱克摩尔太仁慈了。奴役他人者的下场应该比死亡更可怕！"
D.Strings[45441]="所有人都有罪！所有人都要受罚！"
D.Strings[45442]="瓦里安国王……你想向我的人民宣战？战争是你自找的，人类！"
D.Strings[45443]="部落的怒火将横扫你的城市！你将看着你的王座被劈成两半！我发誓！"
D.Strings[45444]="加尔鲁什……加尔鲁什……"
D.Strings[45445]="古伊尔！古伊尔，你必须停下来！你的愤怒是正确的，但它会吞噬你！压抑它，否则我们都会失败！"
D.Strings[45446]="凯恩是我的兄弟！！！"
D.Strings[45447]="你能听到吗？"
D.Strings[45448]="你们都聚在这里庆祝这个伟大的节日，真是令人高兴。今年，我们经历了许多艰难困苦，所以像美酒节这样的节日特别振奋人心，特别受欢迎。"
D.Strings[45449]="许多年前，当麦格尼国王陛下把这些节日的准备工作交给我的时候，我向他保证，我们侏儒会将美酒节办成一场令人难忘的盛会。但麦格尼明白我们侏儒还有许多工作要做。所以他希望这个节日能够办得朴素庄重，以纪念往昔。"
D.Strings[45450]="我对此可以理解，但国王陛下能允许我这个侏儒去开酒桶，已经是个改变了。我还记得那无数个夜晚里，我独自一人静静思考如何最有效率地打开酒桶，并把里面的酒绝对平均地分给大家喝，请注意绝对平均和最有效率这两个词。"
D.Strings[45451]="制定出了完美的计划之后，我派出了手下最精锐的人员来研制能够完成任务的机器！我们的计算已经精确到秒……"
D.Strings[45452]="……好吧……我估计这儿已经没人想听到开罐器74205和75633的名字了……如果我说开罐器1701-D的话，你们可能会兴奋一点……"
D.Strings[45453]="我……还活着……"
D.Strings[45454]="古伊尔，我以为我要失去你了……"
D.Strings[45455]="阿格娜，我的心……你从未放弃我。我的生命，我的一切，都亏欠于你。"
D.Strings[45456]="我看清了现在的自己——怀疑和愤怒摧垮了我。终我一生，我自己选择了成为恐惧的奴隶……"
D.Strings[45457]="……一个“萨尔”。"
D.Strings[45458]="范达尔想利用我的弱点来对付我……"
D.Strings[45459]="但他和他的暮光主子永远不明白的是：愤怒与争斗并非元素存在的意义……他们为协调而生：与世界的协调，与我们的协调。"
D.Strings[45460]="我见证了真理，我的枷锁已经碎了。"
D.Strings[45461]="我又变成了曾经的我……而且更加强大。"
D.Strings[45462]="哦……你显然更加健谈了……"
D.Strings[45463]="但我们必须尽快回到世界之树！守护巨龙在等待……"
D.Strings[45464]="谢谢你，我的朋友。我难以回报你的忠诚和友谊。"
D.Strings[45465]="回世界之树再见吧。有件事情……我想邀你一同见证。"
D.Strings[45466]="请随意浏览这里的拍品。如果你有东西要拍卖的话，我也可以帮你办理。"
D.Strings[45467]="我要查看拍卖的物品。"
D.Strings[45468]="最近有可疑人员来要求拍卖一箱货物吗？"
D.Strings[45469]="我只是伟大的女妖之王，黑暗女王希尔瓦娜斯座下一名卑微的信使。"
D.Strings[45470]="你瞧，干我这份工作的人，谨慎是第一要诀。我本来是不该提这事儿的。"
D.Strings[45471]="你所说的这个人不久前才来过，想让我帮他拍卖一箱奥术物品。"
D.Strings[45472]="自然的，我告诉他我们从不接受贼赃。这里是暴风城拍卖行。可不是后街上那种鬼鬼祟祟的黑市。"
D.Strings[45473]="我没听错吧，欧穆隆？我们要参战了？"
D.Strings[45474]="你已经说服我了，$n。猛禽德鲁伊愿意帮助你。"
D.Strings[45475]="是的，希萨莉。把我们的人召集起来。我们立刻开赴熔火前线。"
D.Strings[45476]="我想我会喜欢的。"
D.Strings[45477]="|TInterface\\Icons\\ability_druid_tigersroar.blp:20|t%s变形成|c0087CEFA|Hspell:98374|h[猎豹]|h|r！"
D.Strings[45478]="|TInterface\\Icons\\inv_mount_hordescorpiong.blp:20|t%s变形成|c0087CEFA|Hspell:98379|h[蝎子]|h|r！"
D.Strings[45479]="我们的天职要求我们守好这片土地。可如果范达尔真的逃进了火焰之地，那我们必须将他绳之以法。"
D.Strings[45480]="姐妹们，显身吧。隐藏的时刻已经过去了。我们要去火焰之地对付敌人。"
D.Strings[45481]="我们战场上见，$G兄弟:姐妹;。"
D.Strings[45482]="污秽的凡人……不能进入主人的城堡……"
D.Strings[45483]="他怎么能就站在那儿，眼睁睁地看着我们击退他脚下的进攻者？"
D.Strings[45484]="做好准备。火焰之地非常危险……即使是像你这样强大的$r也不能掉以轻心。$b$b你准备好之后，就告诉我一声。"
D.Strings[45485]="我准备好了。让我们前往火焰之地，了结这一切吧。"
D.Strings[45486]="火焰的国度比我想象的还要可怕。我能感到这个世界想要压垮我的狂怒。"
D.Strings[45487]="用不了多久他们就会发现我们的。开始吧。"
D.Strings[45488]="那边！我看到他了，包裹在烈焰中！我能感受到他心中喷薄而出的狂怒。如此狂野……他的愤怒会将我们也烧成灰烬！"
D.Strings[45489]="保护我，我会将防护图腾放置在周围。"
D.Strings[45490]="瞧瞧谁来了，这火焰的王国有访客了？"
D.Strings[45491]="凡人们，你们也许还记得奥利瑟拉，在海加尔山释放过我的绿龙。她也在烈焰中……得到了重生！"
D.Strings[45492]="我真希望能亲眼看着她将你们这群可怜的家伙烧成灰烬，但我还有别的事情要忙。永别了！"
D.Strings[45493]="别再躲躲闪闪的了，昆西！我知道那个贼和那个箱子就在这儿。"
D.Strings[45494]="那个箱子里的东西非常危险。它们都来自一个守卫森严的库房，可不是从某个愚昧的暴发户收藏家那里偷来的！"
D.Strings[45495]="拜托，别吵了。我还要做生意呢……"
D.Strings[45496]="如果你肯忘记这箱东西，我可以用最优惠的价格，卖给你几件奥丹姆的新货。"
D.Strings[45497]="好啦，好啦。我好像是跟他说过，有个私人收藏家可能对那个箱子里的东西有兴趣的来着。"
D.Strings[45498]="等警卫来找你谈话的时候，但愿你能解释清楚那些奥丹姆遗物，或者那副漂亮的画作的来历。"
D.Strings[45499]="是的，$c。我们早就预见到了这一天，而且已经做好了准备。"
D.Strings[45500]="我们不能让死亡之翼得逞。如果让他赢得了这场战争，那整个世界都将生灵涂炭。"
D.Strings[45501]="保护者们，集合起来吧！我们要运用古树的力量赢得这场战争！我们决不能失败！"
D.Strings[45502]="这只是个开始。那么你呢，新来的？要不是为了追查那个箱子，你也不会到这儿来了吧？"
D.Strings[45503]="阿格娜……$n……"
D.Strings[45504]="你来的正好，莉吉特。$n说，熔火前线需要你的专业知识帮忙。"
D.Strings[45505]="哎呀！好吧，我估计那个设备也没法运转了。"
D.Strings[45506]="哇，太棒啦！是时候让那些火元素尝尝……高度易燃的爆炸类武器的厉害啦！"
D.Strings[45507]="我知道你会来。你真顽强，顽强得令人讨厌。"
D.Strings[45508]="是时候除掉你了。"
D.Strings[45509]="范达尔是个真正的领袖。而你不过是个绝望之梦。"
D.Strings[45510]="你没有力量领导任何人。"
D.Strings[45511]="他们很快就会看穿你的弱点，“大导师”。"
D.Strings[45512]="我拥有你从未知晓的力量，玛法里奥。"
D.Strings[45513]="我会杀掉你的同伴，就如同我杀死哈缪尔。而你对此无能为力。"
D.Strings[45514]="特纳隆老伙计，你能去帮这位$c收集一瓶月井之水来吗？"
D.Strings[45515]="我不相信！我本已将你的生命烧干了！"
D.Strings[45516]="去吧，$n。当你回到前线的时候，月井应该已经满溢了。"
D.Strings[45517]="这是我的荣幸，麦托克劳。"
D.Strings[45518]="我为你而来，莱雅娜。"
D.Strings[45519]="我会让你获得解脱。愿你能在死后得到安宁。"
D.Strings[45520]="抱歉我没能早点赶到，虽然一切似乎都在你的掌握之中。"
D.Strings[45521]="我们回营地汇合。"
D.Strings[45522]="莱雅娜，你必须明白范达尔已经无法救赎了。他受到的腐蚀比你想象的还深。"
D.Strings[45523]="你没有杀死哈缪尔。他还活着。"
D.Strings[45524]="欢迎回来，哈缪尔。我们离开这个地方吧。"
D.Strings[45525]="真是太棒了！"
D.Strings[45526]="这里不欢迎你们。"
D.Strings[45527]="这里只有火焰，硫磺，还有死亡。"
D.Strings[45528]="你的举动愚蠢而徒劳。你没有力量去守护你最珍视的人。"
D.Strings[45529]="你虚弱而可悲。你所爱的人会被烈焰烧尽，你的生命将弃你而去。"
D.Strings[45530]="等待你的只有虚无。无尽空虚。"
D.Strings[45531]="他们已经抛弃了你。留你独自受死。"
D.Strings[45532]="他们会在你最需要之时抛弃你。他们会看着你被烧死。"
D.Strings[45533]="你一无所有，一无所有。"
D.Strings[45534]="你对力量一无所知。你在绝望中寻求同伴，但他们救不了你。"
D.Strings[45535]="你只能奢望与他们一起被烧死。你们没有胜利的可能。"
D.Strings[45536]="|TInterface\\Icons\\inv_mace_2h_sulfuras_d_01.blp:20|t%s开始施放|cFFFF6600|Hspell:100604|h[强化萨弗拉斯]|h|r！"
D.Strings[45537]="大法师克希雷姆可不会跟你这种人讨价还价，恶棍！不给就是不给！"
D.Strings[45538]="这是什么，一个闯入者？让我们来看看这个箱子里的遗物有什么作用，如何？"
D.Strings[45539]="%s秒杀了附近所有的盟友！"
D.Strings[45540]="%s倒地后化为一堆灼热的碎片……"
D.Strings[45541]="%s再次充满力量并投入战斗，以保护他的主人！"
D.Strings[45542]="当然，我会和你分享我的智慧。"
D.Strings[45543]="玛法里奥将你的祖父关进了监狱。部落攻击灰谷时，他只能在兽穴里等死。"
D.Strings[45544]="很高兴再次见到你，巴恩斯先生。那个箱子在你手里吗？"
D.Strings[45545]="没错。$n刚把它送了回来，但我怎么能肯定你一定会信守诺言呢？"
D.Strings[45546]="我已经把护符带来了。只要一拿到箱子，我就释放它的力量。你肯改变主意是个很明智的决定，巴恩斯。"
D.Strings[45547]="有了它，你就可以躲过探测，毫发无伤地进入卡拉赞。连哈里森·琼斯都猜不到你是如何发掘出这座塔的历史的。"
D.Strings[45548]="这是箱子，请拿好。我已经开始想象，自己能在塔里的图书馆发现些什么了！"
D.Strings[45549]="为了这一天，我已经等待了好几年了。看看我的新造型！"
D.Strings[45550]="这太神奇了！"
D.Strings[45551]="站在这儿，什么都能看见！"
D.Strings[45552]="希望这不会给你添太多麻烦，$n。但这个箱子里的东西是祖传的，对我的家族至关重要。"
D.Strings[45553]="为了这一天，我已经等待了好几年了，$n。是你帮我实现了它。现在，看看我的新造型吧！"
D.Strings[45554]="审讯拍卖师费奇！"
D.Strings[45555]="让烈焰吞没你吧！"
D.Strings[45556]="有人会替我报仇的！"
D.Strings[45557]="让你和你的盟友都去死吧！"
D.Strings[45558]="我的死改变不了什么！"
D.Strings[45559]="为您效劳……炎魔之王。"
D.Strings[45560]="尘……归尘……"
D.Strings[45561]="永远在烈焰中煎熬吧！"
D.Strings[45562]="这阻止不了我们……"
D.Strings[45563]="入侵者！我赤手空拳都能干掉你！"
D.Strings[45564]="你竟敢在火焰的国度中挑战我们？"
D.Strings[45565]="这里不欢迎火焰的敌人！"
D.Strings[45566]="入侵者！我要把你的血肉都烧化掉！"
D.Strings[45567]="入侵者将被烈焰烧成灰。"
D.Strings[45568]="你胆敢挑战烈焰的化身？"
D.Strings[45569]="你这是玩火自焚，入侵者。"
D.Strings[45570]="你的世界将熊熊燃烧，异教徒！"
D.Strings[45571]="喂，等等！你还没告诉我该怎么使用这个咒符！"
D.Strings[45572]="我这是怎么了？好烫！"
D.Strings[45573]="我别无他求。"
D.Strings[45574]="我知道这像是背信弃义，但我实在是难以拒绝哈斯廷先生的出价。真抱歉，$n。"
D.Strings[45575]="阿格娜快要溺死了！救救她！"
D.Strings[45576]="询问拍卖师德雷泽米特！"
D.Strings[45577]="您可以随意浏览拍卖中的物品并出价。我还能帮你将想要出售的物品摆上拍卖架。"
D.Strings[45578]="你最近是否见过某个可疑的家伙想要出售一箱奇怪的货物？"
D.Strings[45579]="让我查看一下拍卖的物品。"
D.Strings[45580]="我们不会和那种家伙做生意！拍卖行里只会出售正规来路的商品。"
D.Strings[45581]="好吧，听着。像我这样的人原本是不该知道这种事的，所以你得替我保守秘密。这座城里确实有那么几个……场所。"
D.Strings[45582]="我愿意帮你的忙，但你得保证不向任何人提起这件事。哪怕只是随便聊聊这种事情也会对我的声誉造成负面影响！"
D.Strings[45583]="我的力量不再受到束缚了！"
D.Strings[45584]="夷为平地！"
D.Strings[45585]="在我面前燃烧吧！"
D.Strings[45586]="燃烧殆尽！"
D.Strings[45587]="动作快，不然我会亲自把你烧成灰！"
D.Strings[45588]="|TInterface\\Icons\\spell_shadow_rainoffire.blp:20|t烈焰之末使者开始施放|cFFFF0000|Hspell:100761|h[灾变流星]|h|r！"
D.Strings[45589]="无能的蠢货，加快召唤！"
D.Strings[45590]="烈焰会吞噬那些凡人！"
D.Strings[45591]="除了灰烬，什么都不会剩下！"
D.Strings[45592]="快点施法！"
D.Strings[45593]="如果那些凡人没杀掉你们，我会亲自动手！"
D.Strings[45594]="……而你，我的爱人，还要拯救一个世界。"
D.Strings[45595]="一个图腾失效了！你必须重新激活它！"
D.Strings[45596]="快点，重新激活那个图腾！"
D.Strings[45597]="恢复那个图腾！赶快！"
D.Strings[45598]="你不用抵赖了，德兰！那个小偷当然知道应该到什么地方来处理他的赃物。"
D.Strings[45599]="我不知道你在胡说些什么，精灵。另外，我非常不喜欢你对我的生意指手画脚！"
D.Strings[45600]="我貌似确实不小心和某些奥丹姆发掘出的神器有过那么一些关联。难道神圣遗物学会对那些东西有兴趣？"
D.Strings[45601]="好吧，好吧。我也许帮那家伙联系过一个有意向的买家。但你能不能小声点！你会把我的顾客吓跑的。"
D.Strings[45602]="让我们看看那些兽人步兵对失窃的古物都知道些什么？"
D.Strings[45603]="现在我们算是有点头绪了……"
D.Strings[45604]="还有你，你干嘛要对这些事情有兴趣？让我们单独聊聊……"
D.Strings[45605]="我们绝不能让炎魔之王失望！"
D.Strings[45606]="塑能者，为这些熔岩注入生命！"
D.Strings[45607]="我的焰刃会烧焦你的血肉！"
D.Strings[45608]="继续施法！我会处理掉那些家伙。"
D.Strings[45609]="|TInterface\\Icons\\spell_shaman_stormearthfire.blp:20|t奥利瑟拉佐尔开始为|cFFFF0000|Hspell:100744|h[火焰风暴]|h|r充能！"
D.Strings[45610]="我们需要所有元素的帮助才能救回萨尔。拉格纳罗斯的爪牙可没有赛克隆纳斯、海卓里斯或者塞拉赞恩那么好说话。"
D.Strings[45611]="都结束了……我不敢相信……$b$b古伊尔自由了，我对你感激不尽，$n。"
D.Strings[45612]="啊，阿格娜……你不是应该跟着萨尔吗？"
D.Strings[45613]="没错。我们海加尔山再见，朋友。"
D.Strings[45614]="别忘了你的图腾！"
D.Strings[45615]="守住阵线，士兵们！不要给敌人任何的机会！别让他们通过！"
D.Strings[45616]="休息？除非躺在我们自己的坟墓里。今天，我们必须战斗到底！"
D.Strings[45617]="动起来，士兵们！"
D.Strings[45618]="我们不能让同伴的牺牲白费！不要松懈！"
D.Strings[45619]="我们必须坚持住，援军马上就要到了。"
D.Strings[45620]="我们的敌人以为我们很弱。我们弱吗，士兵们？向他们证明，他们大错特错了！"
D.Strings[45621]="干得好，卫士们！我们寸土不让！"
D.Strings[45622]="这场战斗的确是对勇气的极大考验。坚定你的信念，举起你的刀剑，让利刃痛饮敌人的鲜血吧！"
D.Strings[45623]="我见证了这场大灾变，亲眼目睹了生命的短暂。此时此刻，我不想再浪费哪怕一秒钟的时间。"
D.Strings[45624]="你想说什么，古伊尔？你的真心是什么？"
D.Strings[45625]="阿格娜……虽然我不是在我们的故乡——德拉诺出生，但我总是尽可能去尊重先祖的传统……"
D.Strings[45626]="我就在你身边——我是古伊尔，杜隆坦之子，加拉达之子……如果你愿意，我愿成为你的终身伴侣。"
D.Strings[45627]="终我一生，我将伴你左右……亦如你将终生伴我身侧。"
D.Strings[45628]="我就在你身边。我是阿格娜兰，瑞亚尔之女，莎拉克之女……我以成为你的伴侣为荣，古伊尔……无论身在任何世界。"
D.Strings[45629]="泰蕾苟萨的精魄与你同在。"
D.Strings[45630]="你可千万别觉得这是背叛，$n。古德温先生可是给了我一笔这辈子只能碰见一次的丰厚报酬来交换他的货物。"
D.Strings[45631]="是的。$n刚刚带着它回来。魔典怎么样了？"
D.Strings[45632]="这东西是你的了，亲爱的古德温先生。贝洛克大师想必会对我们的交易十分满意。"
D.Strings[45633]="也许贝洛克和神圣遗物学会想要把两件东西都拿到手……"
D.Strings[45634]="开门见山！很好，我迫不及待的想要拿回原本就属于我的东西。你带着它吗？"
D.Strings[45635]="没错，我的确带着麦迪文的魔典。幸好神圣遗物学会明智地认为交换对大家都有好处。"
D.Strings[45636]="一旦我拿到箱子，你就能拿到你想要的东西。你的同事一定会茅塞顿开的，我确信。"
D.Strings[45637]="多年来，我一直渴望着完成这个法术，完成我的变形。现在，见证这一切吧！"
D.Strings[45638]="我梦寐以求的这一天终于到了，$n，是你把这一切变成了现实。见证我毕生的最高成就吧！"
D.Strings[45639]="|TInterface\\Icons\\ability_vehicle_oiljets.blp:16|t你将要施放|cFFFF0000|Hspell:81831|h[腐蚀：疫病]|h|r！赶紧背对盟友！"
D.Strings[45640]="|TInterface\\Icons\\inv_elemental_mote_fire01.blp:16|t你即将被|cFFFF0000|Hspell:100460|h[炽炎之热]|h|r包围！"
D.Strings[45641]="|TInterface\\Icons\\ability_warlock_inferno.blp:20|t%s开始朝敌人群施放|cFFFF6600|Hspell:100777|h[熔岩喷泉]|h|r！"
D.Strings[45642]="来吧，飞蛾们。诺达希尔的力量是我的！"
D.Strings[45643]="泰蕾苟萨的精魄逐渐显现出其原本的模样，你能感受到一股能量的涌动。"
D.Strings[45644]="欢迎来到林荫女士，这里有最好的美酒和异域商品，只此一家！"
D.Strings[45645]="请让我看看菜单上都有些什么。"
D.Strings[45646]="不，不！我没有“背叛”巨龙军团。被背叛的是我们。这个世界即将毁灭，伊瑟拉却迷失在梦境中。"
D.Strings[45647]="我即是主人的意志！我为他守护这道大门！"
D.Strings[45648]="主人会见证你们的湮灭。"
D.Strings[45649]="淹没在烈焰之海！"
D.Strings[45650]="我的熔岩之怒会烧尽你们。"
D.Strings[45651]="无人能进入主人的领地。"
D.Strings[45652]="我为你而来，玛法里奥。"
D.Strings[45653]="你太弱了，老家伙。"
D.Strings[45654]="真理之道只有一个。那就是烈焰之道！"
D.Strings[45655]="你们的道路通向毁灭。"
D.Strings[45656]="毁掉他们的营地。烧光他们的树。"
D.Strings[45657]="烧尽一切。不留活口。"
D.Strings[45658]="把他们杀光。带玛法里奥来见我。"
D.Strings[45659]="杀掉所有人，除了玛法里奥。他是我的。"
D.Strings[45660]="这是死亡的标记。逃吧，快逃，小东西！"
D.Strings[45661]="你们是……猎物。"
D.Strings[45662]="该逃跑了。沙恩诺克斯来了。"
D.Strings[45663]="|TInterface\\Icons\\ability_mage_firestarter.blp:20|t%s施放了|cFFFF0000|Hspell:100675|h[恐惧烈焰]|h|r！"
D.Strings[45664]="熔岩的涡流在这颗宝珠内缓慢地旋转着，但半透明的宝珠表面摸上去却是坚硬冰凉的。"
D.Strings[45665]="死亡之翼命我对付泰蕾苟萨的容器。你愚蠢的旅程到此结束了。"
D.Strings[45666]="蠢货！你胆敢进入火焰的王国？"
D.Strings[45667]="你可以在奥尔多高地的南部找到铭文训练师，记录员利迪欧。"
D.Strings[45668]="占星者之台上有一个专门研究各种专业技能的图书馆。$b$b你可以去占星者之台的先知图书馆寻求你想要学习的知识。"
D.Strings[45669]="技师米希拉就在奥尔多高地上。"
D.Strings[45670]="你可以在奥尔多高地的东部找到草药学训练师吉嘉。"
D.Strings[45671]="记录员利迪欧就在奥尔多高地上。"
D.Strings[45672]="采矿训练师弗诺就在奥尔多高地上。"
D.Strings[45673]="你可以在奥尔多高地的东北部找到编织者欧尔。"
D.Strings[45674]="啊！天都要塌下来了！"
D.Strings[45675]="快躲开火焰！"
D.Strings[45676]="跑！快跑！"
D.Strings[45677]="停下来了吗？"
D.Strings[45678]="从上面来了！"
D.Strings[45679]="为什么这些破事儿来个没完了？"
D.Strings[45680]="谁引了这么多怪来？！？"
D.Strings[45681]="我们可以开拉了吗？可以拉了吗？可以拉了吗？"
D.Strings[45682]="快吃药剂，快上buff！"
D.Strings[45683]="听好了，地上有什么躲什么，boss召什么打什么，换阶段的时候记得停手。踢掉boss在二阶段的第三次施法。一阶段的第一次施法一定要踢掉，但是第二次施法一定不能踢。除非是你看到他在用闪电。如果你看到他用闪电就无论如何都踢掉。这很难吗？"
D.Strings[45684]="嘿，我以前没打过……打这个要注意点啥？"
D.Strings[45685]="别傻站在火里！"
D.Strings[45686]="|TInterface\\Icons\\achievement_boss_ragnaros.blp:20|t你将要施放|cFFFF0000|Hspell:101109|h[拉格纳罗斯之怒]|h|r！"
D.Strings[45687]="%s看到伙伴死去后被激怒了！"
D.Strings[45688]="|TInterface\\Icons\\spell_shadow_curse.blp:20|t%s准备使用|cFF7A0080|Hspell:99352|h[毁灭之刃]|h|r！"
D.Strings[45689]="|TInterface\\Icons\\inv_sword_09.blp:20|t%s准备使用|cFFFF0000|Hspell:99350|h[地狱火之刃]|h|r！"
D.Strings[45690]="莱雅娜发出了一阵残忍的笑声。"
D.Strings[45691]="有件事我可以肯定，那就是你总是可以依赖你的好朋友。如果在你的生命中有这么一个人，请好好珍惜他。"
D.Strings[45692]="安伦是我最好的朋友。要是没有他在，我真不知道该怎么办了。"
D.Strings[45693]="索罗和我一起加入了火焰之地战役。我们并肩作战，同生共死。这才是战火中的兄弟！"
D.Strings[45694]="我和索罗一起度过了无数难关。我知道他一定会为了我而格外留心。"
D.Strings[45695]="$n，你可知道要支持一只军队需要多少补给？我们需要武器、食物、掩体、绷带……这还仅仅是个开始。$B$B补给不会自己就增加。如果你想要帮忙，就去和麦托克劳谈谈吧。她会让你派上用场的。"
D.Strings[45696]="泰蕾苟萨的温暖气息环绕着你。"
D.Strings[45697]="重回战场前我需要恢复我的力量。最好你也这么做。"
D.Strings[45698]="那些蜘蛛的个头就和……我一样大！你知道该怎么对付成群的蜘蛛吗？$B$B嗯哼，没错。炸弹。成堆的炸弹。"
D.Strings[45699]="回头见！我先撤了！"
D.Strings[45700]="上诅咒！上钉刺！上痛！有什么上什么！"
D.Strings[45701]="那个乱引怪的最少扣50DKP！"
D.Strings[45702]="告诉我有关远古半神玛洛恩的故事。"
D.Strings[45703]="从我们牛头人有记录起，关于强大的白色雄鹿的传说就一直在我们的文明中流传。从开天辟地的那一刻起，玛洛恩似乎就在守护着原始的森林了。他是一位古代神灵，是自然的伟力与纯洁的化身！$B$B很久之前，最伟大的牛头人猎人会在月落时分追寻这头白鹿的踪迹。据说，哪怕是从林间瞥见一眼他那闪光的毛皮，就可以给部族里整整一代人带来巨大的幸运。$B$B你知道吗，玛洛恩还是月亮女神的伴侣。"
D.Strings[45704]="不，请继续讲！"
D.Strings[45705]="是的，玛洛恩正是月亮女神的伴侣。暗夜精灵们称这位女神为“艾露恩”。他们两位结合后生下了塞纳留斯，那位所有德鲁伊共同的守护神，同时也是艾泽拉斯最强大的生物之一。$B$B但，听我说，我还没说完呢。$B$B玛洛恩是一股难以想象的自然之力，可他只有在生死关头时，才会响应凡间种族的呼唤。你听说过他在上古战争时期的事迹吗？"
D.Strings[45706]="干得漂亮，士兵。我需要你好好活下来。"
D.Strings[45707]="这些印记象征着尊重，是战场上挥洒热血的成果。如果想要赢得这场战争，我们必须收集足够多的印记。"
D.Strings[45708]="要想战胜拉格纳罗斯，我们就必须召集起那些敢于深入火焰之地这片焦土的盟友。但在召集这些盟友之前——不管他们是德鲁伊、士兵或者仅仅是后勤人员——我们都必须给他们一个加入我们的理由。$b$b哪怕你身上只携带着几枚这种印记，也足以说明你是我们这场事业中的英雄。如果你能收集到几百枚……那就足以统领大军。$b$b现在，你明白我们的计划了吗？"
D.Strings[45709]="影歌指挥官，什么是世界之树的印记？"
D.Strings[45710]="那么请问这是为什么呢？"
D.Strings[45711]="在我身后，就是你刚进来的地方，有一个很大的排气口，里面喷出的热气流能够一直升腾到外面。你只要站在排气口上，然后……这么一跳！你跃起的动能就足以把你送到顶上去了。$b$b噢，还有一件事——根据我从其他德鲁伊那里打听来的情况看，你出去的时候，最好小心你的脑袋。"
D.Strings[45712]="当然。顺便说一句，你可以在洞穴的深处找到一些功能类似的小型排气口。慢慢的，你就能学会如何利用这些排气口更加便捷在洞穴中穿行——或者是如何利用它们去折腾那些没脑子的火妖。"
D.Strings[45713]="我应该怎样从这儿出去？"
D.Strings[45714]="我明白了。谢谢你。"
D.Strings[45715]="其实，我的导师莫希斯才是这方面的专家。不过我可以跟你说说我知道的情况。$b$b它们并不是鸟。当然了，它们也会飞，它们的翅膀上似乎也有羽毛，而且我们也管它们叫“鹰”，但那只是和鸟类对比后的称呼。实际上，它们和巨龙之间的相同点似乎更多：同样对火焰具有非凡的亲和力，同样喜爱独居，并且——据我们观察——具备一定的智力特征。"
D.Strings[45716]="难道不是吗？但它们的寿命却和巨龙有很大不同。和我们那个世界的巨龙动辄上千年的寿命不同，这些火鹰的生命非常短暂，从孵化到成年，再到死亡，不过是短短一瞬而已。$b$b虽然我的导师一再禁止我们将个人感情带到研究中来，可有时我还是忍不住要为它们难过。它们的生命燃烧得如此灿烂……可一旦死亡，它们就会被迅速取代并遗忘。"
D.Strings[45717]="关于那些火鹰，你还有什么可以告诉我的？"
D.Strings[45718]="有什么好说的呢？它们不过是一群蜘蛛。只是比我们过去见过的蜘蛛更加……亲和火元素。$b$b它们能咬人，能结网，能喷吐炽热的毒液，还把我最好的几个朋友困在了灼热的蛛丝茧里。可怕的小东西。"
D.Strings[45719]="没关系。毕竟这些蜘蛛不是我们真正需要担心的。它们的蛛后，贝丝缇拉克才是我们真正的威胁。她那结满蛛网的堡垒就在东边，我们无法靠近。那里，有一整支蜘蛛大军在保护着她，个个都甘愿为这位蛛后赴汤蹈火。$b$b而且，它们的体型也非常巨大！信不信由你，你在这儿看到的那种12尺长的蜘蛛只不过是些小家伙而已。据说，它们不能算是拉格纳罗斯真正意义上的仆从，但它们仍然对我们的事业构成了威胁。所以，我们仍然要把它们当敌人来看。"
D.Strings[45720]="你能告诉我有关这些蜘蛛的事情吗？"
D.Strings[45721]="真遗憾。"
D.Strings[45722]="我知道的恐怕也不多。我并不是德鲁伊，我只是来指挥部队的。在我看来，玛法里奥想要在战区里种一棵树的想法很古怪。不过……我也说了，我并不是德鲁伊。$b$b不过，我可以这么跟你说。没有什么能比自己的老家里长出一棵郁郁葱葱的大树更让那些火元素生气的了。就算没有其他意义，当这棵树完全长成时，也可以象征我军的希望之光……并成为敌人的眼中钉。"
D.Strings[45723]="将军，你能告诉我一些关于哨卫之树的事情吗？"
D.Strings[45724]="上古之战时都发生了些什么事？"
D.Strings[45725]="一万年前，远古半神与凡人种族并肩作战，共同抵御入侵艾泽拉斯世界的燃烧军团。许多半神死于燃烧军团之手。塞纳留斯也差点被杀，但他的父亲，玛洛恩舍身救下了他。$B$B强大的雄鹿纵身跃入战场，他的巨蹄碾碎了恶魔的颅骨，他的鹿角刺穿了无数恶魔的身躯。$B$B但随后，污染者阿克蒙德现身了。一场恶战之后，他攫住了玛洛恩的鹿角……扭断了这位半神的脖子。$B$B但只要世间还有生命在绽放，像玛洛恩这样的自然之力怎么会真正死去呢？"
D.Strings[45726]="古伊尔——你们叫他萨尔——他的灵魂四散到了各个元素位面。$b$b暮光之锤以为这样就能动摇我们的意志……但我们不会退缩。我们不会放弃古伊尔。$b$b他赌上了他的一切来拯救这个世界，而我们也会为他做同样的事情！"
D.Strings[45727]="当你准备好前往奥丹姆的时候再来找我。我们必须和赛克隆纳斯谈谈，看看他都知道些什么。"
D.Strings[45728]="我准备好前往奥丹姆了，阿格娜。"
D.Strings[45729]="范达尔回来了，还变成了“烈焰德鲁伊”……？$B$B我怀疑绿龙军团的某名成员也和这场背叛有关系！"
D.Strings[45730]="没错，$c，我们的前景似乎很惨淡。但你要记住，就算事情看似已经毫无希望，他们会这么做也一定有着重大的意义。$B$B<尽管说着安慰的话语，但诺兹多姆看上去也相当沮丧。>"
D.Strings[45731]="我真希望能帮你脱困，凡人。但现在蓝龙军团内部有一些麻烦，我本人还要去处理其他有关世界之树的紧急事件……"
D.Strings[45732]="救世萨满被范达尔·鹿盔的法术……撕碎了？这种力量已经超出了原本的界限。拉格纳罗斯向这个世界注入的力量已经超出了我的想象。$B$B我们必须阻止炎魔之王！"
D.Strings[45733]="又是你，$c。$B$B出什么事了吗？$B$B<奥利瑟拉的尾巴仿佛因害怕而畏缩着，她的双眼紧闭，但眼睑遮挡不住她游离的眼睛。>"
D.Strings[45734]="你把范达尔·鹿盔交给了暮光之锤。你为什么要背叛巨龙军团？"
D.Strings[45735]="我们太迟了！他们杀了她，如同范达尔所预料的那样。"
D.Strings[45736]="不，炎魔之王亲自挑选了她。你们想要质疑他的力量？"
D.Strings[45737]="是大地之环派你来的吗？$B$B我们将从这里，世界之树的脚下，开始治愈这片土地。真高兴你能见证这一切。"
D.Strings[45738]="守护巨龙们已经齐聚于此，我相信阿格娜马上也要到了。$B$B你准备好开始了吗，$n？"
D.Strings[45739]="送我到马戏团入口。"
D.Strings[45740]="前往马戏团入口需要交纳："
D.Strings[45741]="回到玛法里奥身边，保护玛洛恩庇护所。"
D.Strings[45742]="%s失去了耐心，并且变得|cff7115ff|Hspell:101304|h[极热]|h|r了。"
D.Strings[45743]="$C！游戏场地内禁止使用坐骑！"
D.Strings[45744]="这么快就要走了吗？$b$b只要交纳少许费用，我就能把你传回某个主城。$b$b确定要离开吗？"
D.Strings[45745]="离开马戏团需交纳："
D.Strings[45746]="奥利瑟拉深深地吸了一口气。快躲到掩体后面！"
D.Strings[45747]="我们正着力于测试新副本！我可以为您提供传送门，建立联接，杀死怪物以帮助您进行测试。"
D.Strings[45748]="尊特拉华达，我准备好了。传送我吧！"
D.Strings[45749]="我要挑战死亡之翼，送我去天火号。"
D.Strings[45750]="当心点，凡人。$b$b只有最老练的英雄才能和我一起进入魔枢。"
D.Strings[45751]="我想要测试传奇武器魔枢副本。"
D.Strings[45752]="你想制伏%s，却被它迅速躲过了！"
D.Strings[45753]="保护好海加尔小精灵，让它关闭入侵者的传送门！"
D.Strings[45754]="海加尔小精灵需要帮助！保护好海加尔小精灵，让它关闭入侵者的传送门！"
D.Strings[45755]="海加尔小精灵受伤了！保护好海加尔小精灵，让它关闭入侵者的传送门！"
D.Strings[45756]="海加尔小精灵被杀害了！"
D.Strings[45757]="我们要在这里造什么？"
D.Strings[45758]="我们将在火焰之地建立一座永久性的哨所，$n。即使拉格纳罗斯被打败了，但在将来的某一天，其他人仍有可能出来接替他的地位。我们不能让燃烧平原和海加尔的悲剧重演，再次威胁我们的世界。$B$B为此，我们将在这里种下“哨卫之树”。它扎根在艾泽拉斯，却能将树冠延伸到这个可怕的国度，形成保护。在它的庇荫下，我们就可以派一队德鲁伊永久驻扎下来，日夜监视这个荒芜的世界。"
D.Strings[45759]="门厅中回荡着刺耳的嗥叫！"
D.Strings[45760]="紫色河豚宠物"
D.Strings[45761]="投掷用海星"
D.Strings[45762]="迅捷海滨陆行鸟"
D.Strings[45763]="潮汐王座"
D.Strings[45764]="德丝缇拉克保住了他的熔火意志！"
D.Strings[45765]="%s得到了增援！"
D.Strings[45766]="索罗的温度计在这里显示不出读数。"
D.Strings[45767]="%s就要获得全部的力量了！"
D.Strings[45768]="%s指示火妖塑能者加快施法速度！"
D.Strings[45769]="%s命令火妖塑能者加快施法速度！"
D.Strings[45770]="%s打破了身上的束缚！"
D.Strings[45771]="你得去找巨魔贾布。他可以帮助你。"
D.Strings[45772]="大篷车到了。一路顺风！"
D.Strings[45773]="击败魔法追猎者，找到泰蕾苟萨！"
D.Strings[45774]="我们虚灵的技术能够改变一件物品的魔法本质，这在过去是不可想象的。我们还能将物品放入其他位面保存起来……只是需要少许费用。具体情况，你可以找我的同伴询问。$B$B你有东西要让我检查吗？"
D.Strings[45775]="对物品的外观不满意吗？$B$B来看看我们的幻化器吧，这是我们最有潜力的科技产品。有了它，一名熟练的织幻者就可以把一件物品的外观变成另外一件物品的样子。$B$B需要在下为您幻化什么物品吗，亲爱的客人？"
D.Strings[45776]="幻化一件物品。"
D.Strings[45777]="什么是幻化？"
D.Strings[45778]="储存一件物品。"
D.Strings[45779]="嘿，嘿！$B$B我敢说，你一定有本事把投环扔到一只慢腾腾的乌龟背上。$b$b你觉得呢？"
D.Strings[45780]="我准备好了！|cFF0008E8(暗月游戏代币)|r"
D.Strings[45781]="右转！"
D.Strings[45782]="时间到了，该回去工作了！"
D.Strings[45783]="我已经好多了。"
D.Strings[45784]="已经没那么疼了。"
D.Strings[45785]="真不知道该怎么感谢你！"
D.Strings[45786]="你给我一枚游戏代币，我会给你10个投环。$B$B你得想办法把它们扔到那边的暗月乌龟杜本科的背上……看到它驮着的那根柱子了吗？$b$b不过要是你没能扔中足够的环，那就再试一次！你的分数是可以累积到下一轮游戏的。"
D.Strings[45787]="发射吧！|cFF0008E8(暗月游戏代币)|r"
D.Strings[45788]="|TInterface\\Icons\\ability_warstomp.blp:20|t%s开始释放|cFFFF0000|Hspell:101626|h[粉碎]|h|r了！"
D.Strings[45789]="这是你自找的。"
D.Strings[45790]="你好啊！欢迎你！$B$B你是来进行挑战的吗？"
D.Strings[45791]="我们要开打了！|cFF0008E8(暗月游戏代币)|r"
D.Strings[45792]="我们要去见守护巨龙了，你准备好了吗？"
D.Strings[45793]="是的，萨尔。"
D.Strings[45794]="英雄们，我们得到了巨龙之魂。守护巨龙在神殿里等着我们。快——跟我来！"
D.Strings[45795]="你们别想活着走出这条峡谷。"
D.Strings[45796]="快，我们必须继续前进。"
D.Strings[45797]="这是什么魔法？"
D.Strings[45798]="快射击！"
D.Strings[45799]="建立及维护场地可不容易……"
D.Strings[45800]="我动一动胳膊都觉得疼。"
D.Strings[45801]="这条伤口看来似乎好不了了。"
D.Strings[45802]="我再也不一个人去调整大炮了……"
D.Strings[45803]="我们这儿有锤子，还有豺狼人。$b$b只要一个代币，你就可以用锤子砸这些豺狼人了。"
D.Strings[45804]="我要开始砸了！|cFF0008E8(暗月游戏代币)|r"
D.Strings[45805]="我找到一根骨头，看！"
D.Strings[45806]="在找旧的蒸汽坦克吗？$b$b好吧，我们现在有些新的货色了。$b$b通常情况下，使用坦克遥控器要花费两个代币。但由于你曾经在部队服过役，所以能享受一个代币的优惠。$b$b我们暗月马戏团的成员非常感谢你所做的贡献。"
D.Strings[45807]="你猜，它会不会来自一条巨龙？或者是一个巨人？"
D.Strings[45808]="我们将要攻陷地狱火堡垒，就从这些城墙开始。"
D.Strings[45809]="蠢货，那不是龙骨。可能是雷象或者什么别的动物的骨头。"
D.Strings[45810]="酋长已经下令攻击地狱火堡垒，我们就从外面这些城墙开始。"
D.Strings[45811]="你怎么知道的？"
D.Strings[45812]="好险！死亡之翼的爪牙把我们从天上打了下来！但龙眠神殿已经近在咫尺了。大家准备好前进了吗？"
D.Strings[45813]="是的，萨尔。我们开始吧！"
D.Strings[45814]="鲜血熔炉见证了我的族人们黑暗的过去。"
D.Strings[45815]="如果你喜欢屠杀兽人，又不爱唠叨，那么欢迎你！$B$B如果不是的话，那么东边就有一座可爱的传送门。我听说，只有在每年的这个时候，它才会特别可爱。"
D.Strings[45816]="但愿我的朋友们都没事……"
D.Strings[45817]="或许他们已经逃出去了？万一他们在外面找我怎么办？"
D.Strings[45818]="纳迦在使用奴隶劳工？他们必须为这种罪行付出代价！"
D.Strings[45819]="我们必须尽快阻止纳迦，拯救赞加沼泽，否则就太迟了！"
D.Strings[45820]="纳迦为了自己的目的，把所有的水都抽走了，这里的生物种群正在走向灭绝。$B$B如果我们不尽快采取行动，这个垂暮的世界上剩余的生物就会永远消失。"
D.Strings[45821]="我加入这个远征队的目的只有一个，$r，那就是复仇。"
D.Strings[45822]="这里的绝大部分地方还没有遭到纳迦的侵扰。可是……这片土地经历了深重的苦难。我不知道我们还有多少时间。"
D.Strings[45823]="这些蘑菇和地表上的任何东西都不一样。据说，谁吃了它们，就能获得无比的智慧和清晰的头脑。$B$B我要带一点回孢子村去。"
D.Strings[45824]="去幽暗沼泽进行研究和学习的机会一生只有一次，非常难得。$B$B尤其是想到我不久前还坐在奴隶围栏的笼子里，那时我和死人也没什么差别……"
D.Strings[45825]="有三个虚灵技师在暴风城里开了一家店，就在教堂广场南边的运河沿岸。\n\n店名叫“三缕风”。你只要找奇怪的机械和紫色的灯就对了……绝对不会找错的。\n\n他们那里有你想要的服务。"
D.Strings[45826]="虚空仓库"
D.Strings[45827]="节点亲王哈拉迈德一直在威胁我说，如果我们不能尽快穿过沙法尔的警戒线，他就要拿我当下一个实验品。$B$B他可不是开玩笑的。"
D.Strings[45828]="你问什么是“杂学家”？那当然是指，我什么都研究！在你所能想象到的任何领域，我都是最博学的人，比你认识或者不认识的任何人知道的都多。$B$B穿过沙法尔的警戒线不算什么。要是莫法鲁斯肯听我的，他连一根寒毛都不会掉。他这个人，老是我行我素。"
D.Strings[45829]="你看看我！你跟我说不会有事的！你看我像没事的样子吗？"
D.Strings[45830]="我只能给你指出那扇门，莫法鲁斯。最后还得要你自己走进去。"
D.Strings[45831]="上古之神的爪牙突然现身了！"
D.Strings[45832]="亡者不属于这个国度。$B$B那我们为什么还要在让他们安息之后，再不断地寻找他们呢？"
D.Strings[45833]="这些地穴对我的族人来说，曾经非常神圣。因为里面有我们的亲人的灵魂。许多人不远万里赶来这里朝圣。$B$B但那已经是很久之前的事了。某种力量控制了奥金尼，这个曾经与亡者们戚戚相关的地方。我请求你，在灵魂们捣毁地穴之前，做点什么吧。"
D.Strings[45834]="我们不应该窥视灵魂的国度……"
D.Strings[45835]="他们根本不知道自己打开了一扇怎样的门……"
D.Strings[45836]="船员就快窒息了！"
D.Strings[45837]="快使用医疗技能救助这名船员，否则就太迟了！"
D.Strings[45838]="看，妈妈！一个幽灵！看见了吗？看见了吗？"
D.Strings[45839]="我看见了，我肯定看见了……"
D.Strings[45840]="那里什么都没有，哈雷。好了，我只要几分钟就行了，安静一会吧。"
D.Strings[45841]="船员就快窒息了！生命危急！"
D.Strings[45842]="一泓月光突然出现了！"
D.Strings[45843]="西边出现了一泓月光！"
D.Strings[45844]="南边出现了一泓月光！"
D.Strings[45845]="北边出现了一泓月光！"
D.Strings[45846]="东边出现了一泓月光！"
D.Strings[45847]="月光隐入了黑暗之中！"
D.Strings[45848]="你根本就不懂怎么操作这个设备上的各种机械，可你心中却总有一种挥之不去的熟悉感。$B$B最好还是先别去管它。"
D.Strings[45849]="一辆坦克瞄准了你！"
D.Strings[45850]="凡人们！我不能再跟你们前进了——接受我的祝福，使用时光沙漏击败姆诺兹多吧！"
D.Strings[45851]="这里的灵魂已经被折磨了很久。我们只想安息。"
D.Strings[45852]="所有熊猫人都要探寻并确认自己的命运。无论是战士还是农夫，总有一个适合我们的角色，每个角色都具有独一无二的重要性。"
D.Strings[45853]="土水派的修行之道是获得真知的途径之一。通过沉思和冥想，我们发现我们的修行之道是解决问题最有效的方法。通过练习和修正，我们让自己的意志完美支配自己的身体。$B$B要学习土水派的修行之道，必须具有坚强的意志和完美的体魄。"
D.Strings[45854]="无为乃罪。"
D.Strings[45855]="附近出现了一泓黑暗月光！"
D.Strings[45856]="很高兴再见到你。"
D.Strings[45857]="雪雾，快看，有个$c来救我们了！"
D.Strings[45858]="嘿，$c！帮帮我，好吗？"
D.Strings[45859]="我们太迟了，$n。看来这些猴子已经杀害了工头和他的工人。"
D.Strings[45860]="小声点，$r。塞泰克已经不欢迎我了。"
D.Strings[45861]="不用担心，$c，有了这道屏障，鸦人就看不见我了。$B$B我来这里是有公务在身的。"
D.Strings[45862]="我的眼睛！这眼镜没用啊！"
D.Strings[45863]="督军卡利瑟里斯必败！"
D.Strings[45864]="这里的黑暗诡异难测，仿佛无尽的永夜。小心，英雄们，不要远离月光的庇护。"
D.Strings[45865]="我们必须立刻攻击。我要把他们撕成碎片！"
D.Strings[45866]="那是自杀，克劳恩！这太危险了。"
D.Strings[45867]="你不能再参加游戏了。"
D.Strings[45868]="你想知道什么？"
D.Strings[45869]="让开点，让其他人也来玩玩吧。"
D.Strings[45870]="凋谢的莲花是冬季降临的征兆。数千年来，神真子的背上从未经历过寒冬。"
D.Strings[45871]="李飞大师的声音在耳畔回响，“土水之道……即通过耐心和冥想获得启迪……是一种自律的生活态度。”"
D.Strings[45872]="李飞大师消失了。"
D.Strings[45873]="唤风者克劳恩大声咆哮着。"
D.Strings[45874]="我们必须控制住纳迦散播到这里的疾病，否则就太迟了！"
D.Strings[45875]="你不像是他们的人……你是谁？"
D.Strings[45876]="到韩妮的房子去。那里很安全。"
D.Strings[45877]="我们不能这样干坐着！"
D.Strings[45878]="他们人太多了。卡利瑟里斯带来了整整一支大军。"
D.Strings[45879]="这里就是碧蓝巨龙圣地的遗迹。一场大战摧毁了这片废墟通往外界的时间流。你必须修复散落在各个角落里的碎片，击败被禁锢的灵魂，才能继续前进。"
D.Strings[45880]="拜特的法术不可能永远持续下去。"
D.Strings[45881]="我要飞行。"
D.Strings[45882]="谢谢你，我马上就去。"
D.Strings[45883]="我不知道你是谁，但我对你感激不尽。"
D.Strings[45884]="这里空无一物，留给你们的只有死亡和悲伤。"
D.Strings[45885]="黑暗围绕着你，艾露恩之光是你的唯一救赎。"
D.Strings[45886]="在这遗忘之地，月光能让你们疲惫的灵魂得到安息。"
D.Strings[45887]="投入暗夜的怀抱，艾露恩会指引你们逃离凡尘。"
D.Strings[45888]="你们选择了一条黑暗的道路。月亮母亲啊，指引我的双手，让我为这些可悲的灵魂带去安宁。"
D.Strings[45889]="月之女神，您的光辉黯淡了！失去指引，我已迷失！"
D.Strings[45890]="黑暗正在逼近……阴影遮蔽了我的眼睛……"
D.Strings[45891]="月亮母亲，我看不见您的光辉了！您的女儿正在黑暗中徘徊！"
D.Strings[45892]="愿艾露恩安详的光辉在黑暗中抚慰你们的灵魂。"
D.Strings[45893]="艾露恩指引你们穿过黑夜。"
D.Strings[45894]="暗夜之眼啊，刺破这黑暗吧！"
D.Strings[45895]="艾露恩之矛，驱散这黑夜吧！"
D.Strings[45896]="我看见月亮的光辉了……如此清晰。真是……太美了……"
D.Strings[45897]="|TInterface\\Icons\\ability_druid_starfall.blp:20|t |cFFFF0000|Hspell:102241|h[艾露恩之泪]|h|r开始从天空落下！"
D.Strings[45898]="这片森林属于恐目部族。闯进来的人都要死。"
D.Strings[45899]="哼，我们会趁你们睡着的时候反攻。下一次，你们就死定了！"
D.Strings[45900]="如果你想要挑战督军卡利瑟里斯，就必须先击败机械师斯蒂里格和水术师瑟丝比娅，这样才能接触到主厅控制面板。$B$B然后，你只要按下面板上的几个按钮，就能打开通向主厅的大门了！"
D.Strings[45901]="救……救命！我的人……我们遭到了攻击！"
D.Strings[45902]="什么？有人来救我们了？这边，$r，救救我们！"
D.Strings[45903]="|TInterface\\Icons\\ability_druid_lunarguidance.blp:20|t泰兰德获得了|cFFFF0000|Hspell:102472|h[月神指引]|h|r！"
D.Strings[45904]="啊呃！鸟蛋人越来越多了。酋长，我们最好赶紧逃跑！"
D.Strings[45905]="啊！痛死了！"
D.Strings[45906]="……雷霆崖，欠两千零六十三。"
D.Strings[45907]="幽暗城，欠五千零二十二。"
D.Strings[45908]="银月城，超过九千……"
D.Strings[45909]="够了！这些王国最好识相点，否则就等死吧！"
D.Strings[45910]="他们还有两晚时间付清欠款。去告诉他们！"
D.Strings[45911]="秘教徒们必将为他们的鲁莽付出代价！"
D.Strings[45912]="布莱卡特！沃匹尔！你们死期将至！"
D.Strings[45913]="我们必须阻止暗影议会的暴行！"
D.Strings[45914]="秘教徒们对无辜者的威胁已经持续得太久了！他们的报应已经到了！"
D.Strings[45915]="我把征服之岛战袍弄丢了。"
D.Strings[45916]="上古火灵的纯洁净化了我们，他的激情更激励着我们。"
D.Strings[45917]="火盆已经点燃了。我做好挑战你的准备了。"
D.Strings[45918]="做好战斗的准备后，就告诉我吧，年轻的$c。"
D.Strings[45919]="沙漏的力量对我毫无用处！"
D.Strings[45920]="纳兹戈林，用胜利的捷报振奋下我的精神吧。"
D.Strings[45921]="立刻。"
D.Strings[45922]="雪雾，你得救了！真是太感谢你了，$c！"
D.Strings[45923]="我们自己能回到营地去。回头如果你想借狮鹫的话就来找我吧。"
D.Strings[45924]="我们贫民窟的人原本在暗影迷宫里有一张相当广大的间谍网络。$B$B可现在，除了我和托古恩，其他人都死了。"
D.Strings[45925]="谢谢你，$n！我自己能回去。如果你需要补给，就回来找我吧。"
D.Strings[45926]="桑德拉向你眨了眨眼。"
D.Strings[45927]="沙塔斯的领导层行动太缓慢了，所以贫民窟的大人物把暗影迷宫的事揽到了自己手里。"
D.Strings[45928]="英雄们，这是她曾经的战斗之地，也是她的陨落之地。希尔瓦娜斯·风行者迷失在时空中的投影将永远在巨龙圣地的残骸上徘徊。"
D.Strings[45929]="找到所有的吉安娜法杖碎片！"
D.Strings[45930]="你面前就是死亡之翼的残酷统治所造成的后果。曾经的红玉巨龙圣地已经成了一片废墟，只有焦黑的残垣和龟裂的土地证明它的存在。\n$b据说，很久之前，阿莱克斯塔萨的一滴鲜血，融化了冰雪，并催生出你面前这棵巨大的红玉橡树。这棵巨树的枝叶直刺苍穹，散发着红龙军团特有的温暖及生命力。\n$b可现在，它却被扭曲了，腐败的枝叶无法再掌管生命与活力的力量——反而成了死亡与毁灭的代言人。当烈焰与堕落灭绝这片圣地的生机之时，这棵巨树定格了一个缩影——依稀就是那些倒在这片圣地上的英雄们的残影。"
D.Strings[45931]="谢谢你。是时候抚平伤痛，回去再战了！"
D.Strings[45932]="感谢你救了我。待在那上面可真难受。"
D.Strings[45933]="我还活着？哈！加尔鲁什尔前哨站的部落真是白费力气了。给他们点颜色瞧瞧。"
D.Strings[45934]="我很高兴地向你报告，战况良好，酋长。"
D.Strings[45935]="他们真的让我来禅院修炼了！齐齐真不敢相信！$b$b齐齐办到了！"
D.Strings[45936]="闪开！齐齐正在练功！靠近我五码之内的人都有可能被踢飞……甚至可能被踢死。$b$b呀哈——！"
D.Strings[45937]="以前齐齐最擅长误伤队友，但自从开始训练之后，齐齐已经进步很多了。"
D.Strings[45938]="想过两招吗？"
D.Strings[45939]="总算有人来挑战齐齐了！"
D.Strings[45940]="够了，够了！别打齐齐了！"
D.Strings[45941]="我的朋友们，我们离目标又近了一步。休息一下吧，等你们准备好继续前进时，请和我说一声。"
D.Strings[45942]="我方军队在塔纳利斯和托尔巴拉德海岸频频告捷……"
D.Strings[45943]="前进！我们马上就要成功了！只要一声令下，我们就将继续高歌猛进！"
D.Strings[45944]="熊猫人长老允许锦鱼人进入禅院是个贤明的决定。$b$b但他们给予猢狲同样的待遇，此为不智。"
D.Strings[45945]="我喜欢这个地方。要是这里的水再多一点就好了……"
D.Strings[45946]="我从这里的武僧身上学到了很多东西，$r。希望你也一样。"
D.Strings[45947]="我想和你交手，胡苏安！"
D.Strings[45948]="很好！"
D.Strings[45949]="我早就预见了这场失败。河水早已把一切都告诉了我。"
D.Strings[45950]="如果要挑战姆诺兹多，你们必须使这些圣地重获安宁。"
D.Strings[45951]="我得说，这儿的饭菜还真是不错。啤酒也是，真心给力。"
D.Strings[45952]="你尝过这个米饭了吗？你真应该尝尝。"
D.Strings[45953]="吃东西也是一种修炼，你明白的。"
D.Strings[45954]="别吃了，露两手吧！我要挑战你！"
D.Strings[45955]="好吧，让我来尝尝单片$R三明治的味道！"
D.Strings[45956]="好吧……算你赢了。我得继续修炼体重了。"
D.Strings[45957]="轻点——我还没从上一次失败……呃……胜利中恢复过来。"
D.Strings[45958]="能和你过招是我的荣幸，$g先生:女士;。"
D.Strings[45959]="我知道你在想什么。你的心思全写在你那双$r眼睛里呢。$b$b<这名徒弟露出了微笑。>$b$b好吧，我们可以开始了吗？"
D.Strings[45960]="随时可以开始。"
D.Strings[45961]="整天都在过招。啥时候吃饭啊？"
D.Strings[45962]="你想被打得鼻青脸肿吗？"
D.Strings[45963]="很好，比试开始吧！"
D.Strings[45964]="到过招的时间了？很好！"
D.Strings[45965]="来啊，把你的爪子举起来啊！"
D.Strings[45966]="吃我一爪，$c。哈哈！"
D.Strings[45967]="别太用力打我的肚子，行吗？"
D.Strings[45968]="让我瞧瞧你打算怎么对付我的“超慢超弱拳”！"
D.Strings[45969]="好也！过招时间到！"
D.Strings[45970]="是时候让你领教下传统的“禅院欢迎拳”了！"
D.Strings[45971]="大哥……我觉得差不多可以了……"
D.Strings[45972]="好功夫。下次我再找你单练。"
D.Strings[45973]="石拳大师说的没错。你可真强。"
D.Strings[45974]="感谢你的指点。"
D.Strings[45975]="你也太认真了一点吧？"
D.Strings[45976]="好功夫。"
D.Strings[45977]="我是来向远近闻名的艾莎·云歌求助的，但我不能打扰她的修行。她是如此娴静、如此沉稳……如此美丽。"
D.Strings[45978]="我果然一点机会都没有。我先告辞了！"
D.Strings[45979]="经过激烈的战斗，我们已经恢复了与藏宝海湾之间的运输线。"
D.Strings[45980]="来吧，$n！动作要快。"
D.Strings[45981]="我们是来打仗的。$B$B这是他们强加给我们的。"
D.Strings[45982]="我们是来侦察敌人的入侵行动的，可他们已经知道我们来了。"
D.Strings[45983]="进去，快！我来挡住他们！"
D.Strings[45984]="萨满，你会把巨龙之魂交给我。"
D.Strings[45985]="该学乖了，熊猫人！"
D.Strings[45986]="这个，在这边！他正努力保护其他人！"
D.Strings[45987]="到房子里去！带上所有还能走路的人！"
D.Strings[45988]="在远古时期，人民浑浑噩噩，大地一片冷寂。"
D.Strings[45989]="此时，上古火灵燧焰降临到了神真子的背上。"
D.Strings[45990]="燧焰温暖了大地，点燃了人们的激情。"
D.Strings[45991]="从那时起，人们就开始供奉燧焰。因为他们明白，自己和燧焰是紧密相连的。"
D.Strings[45992]="尚师父教了个好徒弟。谢谢你，朋友！"
D.Strings[45993]="联盟血溅四野。真是大快人心啊，将军。"
D.Strings[45994]="海焰行动怎么样？我珍贵的货物如何了？"
D.Strings[45995]="该干正事了，对吧？"
D.Strings[45996]="有消息，酋长。"
D.Strings[45997]="说吧，地精……"
D.Strings[45998]="我不会给你的，大主教。你休想得到它。"
D.Strings[45999]="是——是，长官……马上，长官。"
D.Strings[46000]="一切都开始得很顺利。"
D.Strings[46001]="没有善，没有恶，也没有圣光。只有——力量！"
D.Strings[46002]="你曾被视为圣光的化身，本尼迪塔斯。你怎么能背叛你的人民。"
D.Strings[46003]="够了！我虽然好客，但现在必须要去处理更重要的事情了。"
D.Strings[46004]="骑士们，过来！"
D.Strings[46005]="我们通过了敌人的阵线——似乎会顺风顺水地一路航行下去。"
D.Strings[46006]="我想别无他途了。如果你们能看到我所看到的东西，你们就会明白的。"
D.Strings[46007]="然后突然之间……意外发生了！不知从哪里冒出来一大堆不速之客，长官……"
D.Strings[46008]="我衷心祈求千月之光能够赐予我这份荣光。"
D.Strings[46009]="是的，光中之光！我的生命属于您！"
D.Strings[46010]="生命之花在召唤我。我不会让您失望的，女王陛下。"
D.Strings[46011]="嘿……嘿！你在做什么？"
D.Strings[46012]="你在偷我的发明，对不对？"
D.Strings[46013]="阿莱克斯塔萨麾下的巨龙会在这片废墟的另一边接应我们。准备好你们的武器，这个地方太适合打埋伏了。\n\n你们做好行动的准备之后，就告诉我。"
D.Strings[46014]="别逼我站起来！"
D.Strings[46015]="我发誓，我会干的！我这就要站起来了！"
D.Strings[46016]="哦，我在唬谁呢？你真是个狡猾的小偷。"
D.Strings[46017]="亲爱的仆从们，我在此命令你们：除掉那些暴徒。"
D.Strings[46018]="我没时间处理这等琐事。永恒守卫，你们是否愿意为女王而战？"
D.Strings[46019]="这些外来者想要违抗你们女王的意志。谁来阻止他们？"
D.Strings[46020]="你们的行为不可饶恕。"
D.Strings[46021]="真不幸，但罪有应得。"
D.Strings[46022]="要创造一个完美的世界，必须清除一切不完美的东西。"
D.Strings[46023]="真大胆，竟敢攻击女王。幸好我宽宏大量。"
D.Strings[46024]="为永恒王庭跳支舞吧。"
D.Strings[46025]="还没等我们反应过来，他们就已经无处不在了！"
D.Strings[46026]="我们坚守货物，直至最后……呃，其实也没坚守多久……"
D.Strings[46027]="我在水面上漂了好几天，直到被一艘我们的船发现……"
D.Strings[46028]="我要怎么才能玩这个游戏？"
D.Strings[46029]="要想玩游戏，你必须拥有暗月游戏代币。$b$b马戏团里到处都有出售代币的商人。$b$b我可以帮你在地图上标记出来。"
D.Strings[46030]="这里可没有免费的午餐，走吧。"
D.Strings[46031]="你得先付钱，才能玩。"
D.Strings[46032]="抱歉伙计，我可不能让你白玩。"
D.Strings[46033]="被一队联盟懦夫给击落了？！真是可鄙！"
D.Strings[46034]="这个套圈圈怎么玩？"
D.Strings[46035]="我明白了。"
D.Strings[46036]="打豺狼人要怎么玩？"
D.Strings[46037]="蒸汽坦克大挑战该怎么玩？"
D.Strings[46038]="魔古帝国早就被推翻了。从那以后，这些遗迹就一直荒弃于此，已经记不清有多少个年头了。$b$b为什么他们偏偏现在回来了？"
D.Strings[46039]="首先，你要先给我一个游戏代币。然后，你就可以操纵一辆蒸汽坦克。$b$b你需要驾驶坦克，在有限的时间内炸飞战场上的目标。每摧毁一个目标，你可以得一分。$b$b不过你要注意，战场上还有一些邪恶坦克和飞艇。被它们打中会损毁你的坦克。$b$b你的分数可以累积到下一轮，所以死了也不用担心。"
D.Strings[46040]="他们杀了格林奇！"
D.Strings[46041]="我……的……船呢？！"
D.Strings[46042]="驶进了一片浓雾里，然后就再也没见过了，后面有联盟在追……不——不知道后来怎么样了，长官……"
D.Strings[46043]="首先，你得给我一个游戏代币，而我会给你一把步枪。$B$B然后，你就用枪射击那些亮起来的靶子。$b$b如果你出手够快，能在目标亮起后直接击中它，那你就能额外得到一分。$b$b如果你没在规定时间内打到足够的分数，或者离开了游戏场地，也不用担心。你的分数可以带到下一轮游戏里。"
D.Strings[46044]="这个射击游戏怎么玩？"
D.Strings[46045]="恕我直言，酋长，过去的已经过去了。我们现在必须集中全力做好下一步打算……"
D.Strings[46046]="让我来告诉你下一步打算是什么，将军。"
D.Strings[46047]="你去召集所有精兵强将，给我把船找回来！"
D.Strings[46048]="完成了，此地不宜久留。回去之后到营地东边来找我。"
D.Strings[46049]="机灵点。这附近有恶魔。"
D.Strings[46050]="干得好，英雄们！但愿凯尔萨斯·逐日者能永远从这个世界上消失。"
D.Strings[46051]="就是现在，朋友。进攻！"
D.Strings[46052]="尝尝我的厉害！"
D.Strings[46053]="雷电之王又多了些免费的苦力！"
D.Strings[46054]="我们可不怕你！"
D.Strings[46055]="呆子，你打碎了一坛风暴烈酒陈酿……我藏了好多年的！！！"
D.Strings[46056]="来这边，丑八怪！"
D.Strings[46057]="从我身后这三位开始吧。"
D.Strings[46058]="坐在你面前这位是孟教头。她会教你用于实战的功夫。"
D.Strings[46059]="传言她在进入禅院之前是位以一敌百的高手——她一口气收拾了一百只狂暴的猢狲。"
D.Strings[46060]="您太抬举我了，长老。那些弱小的猢狲既年幼又没有战斗经验。任何一名熊猫人都能轻松获胜的。"
D.Strings[46061]="抬举你？那时你才八岁。"
D.Strings[46062]="……八岁半了，长老。"
D.Strings[46063]="这位是石拳大师。他会主持你的过招训练。"
D.Strings[46064]="石拳大师在一对一的比试里几乎未尝一败。他的最高连胜纪录是九百九十九场。"
D.Strings[46065]="第一千个挑战者使诈了。"
D.Strings[46066]="什么？使诈？"
D.Strings[46067]="我可不会使诈！"
D.Strings[46068]="最后一位是夏教头。他十分注重基本功的磨砺，他使出的每一招都臻乎完美。"
D.Strings[46069]="夏，你的徒弟每天会练多少次直拳？"
D.Strings[46070]="一万次，每天。"
D.Strings[46071]="*你*每天会练多少次呢？"
D.Strings[46072]="一万零一次。"
D.Strings[46073]="幸好当上长老之后我就不用练基本功了。老实说，自从不练功之后我的心情好了很多。"
D.Strings[46074]="走吧，陪我喝上两杯，$n。"
D.Strings[46075]="啊！这里坐的是灵魂贤者高全，他是这间禅院最年长的成员。"
D.Strings[46076]="他见证了许多长老的兴衰沉浮。他对这些庆典也非常重视。"
D.Strings[46077]="你或许已经注意到，我们之中既有猢狲，也有锦鱼人。无论是谁，只要他渴望求知，禅院都会欢迎的。"
D.Strings[46078]="最后，这位是园丁老吴。"
D.Strings[46079]="老吴！"
D.Strings[46080]="在……在，长<嗝>老？"
D.Strings[46081]="吴，这是$n。$G他:她;将和其他弟子一起接受训练。"
D.Strings[46082]="哦……<嗝>……你好……$n呼呼……"
D.Strings[46083]="老吴会要你帮忙干些杂务。没什么复杂的，就是些禅院的日常维护工作。"
D.Strings[46084]="我们都有义务和责任来维护好我们共同的家。就算是长老，偶尔也要搭把手。"
D.Strings[46085]="你现在明白了吧。瞧见没？我的杯子又满了！当长老还真不错。"
D.Strings[46086]="欢迎，$n。你能来做客是我们的荣幸。今天，我们不仅要为你接风，也为了即将加入禅院的一批新弟子而庆祝。$b$b请随意享用我们准备的食物和酒水。等你准备好后，我要为你引见几位禅院的教头。"
D.Strings[46087]="非常好，$n。等你吃饱喝足之后再来找我吧。"
D.Strings[46088]="你确定吗？教头们会很乐意见到像你这样经验丰富的$r $c。"
D.Strings[46089]="如你所愿。干杯！敬我们的贵客，$n！"
D.Strings[46090]="我已经做好参见教头们的准备了，长老。"
D.Strings[46091]="再等一会，我还没喝好呢。"
D.Strings[46092]="我无需任何介绍，老人家。我们还是直奔主题吧。"
D.Strings[46093]="很好。让我们继续介绍吧。"
D.Strings[46094]="我确定。让我们开始战斗吧。"
D.Strings[46095]="投降免死，你这蠢货！"
D.Strings[46096]="别一个一个上，你们这些蠢货！给我一起上！"
D.Strings[46097]="你显然不是农夫……"
D.Strings[46098]="给$n再来一杯啤酒！"
D.Strings[46099]="欢迎参加我们的盛宴。云瀑长老在后面张桌子那儿等着你。"
D.Strings[46100]="终于自由了！我得去喝一杯……"
D.Strings[46101]="请稍等，$n。"
D.Strings[46102]="%s将果酒和一把碾碎的草药放入瓶子里，然后用力摇晃。"
D.Strings[46103]="这样应该就行了！"
D.Strings[46104]="魔古伏击者从树上跳下来了。小心！"
D.Strings[46105]="看看我们找到了什么！又一个从果园里跑出来的农夫……"
D.Strings[46106]="如果你想和我们一起训练，就等晚上开席时来跟我说一声吧。"
D.Strings[46107]="班应该已经到了……到营地外围去找他吧。"
D.Strings[46108]="你好，欢迎来到暗月马戏团入口处。$b$b这座传送门能送你去暗月马戏团。$b$b如果你在出发前有什么疑问的话，我也可以帮你解答。"
D.Strings[46109]="暗月马戏团里有各种有趣的游乐设施，有占卜师，音乐会，钓鱼大赛以及各种游戏。$b$b而且我们还在不断扩张马戏团，添加各种新的游乐设施！$b$b你要不要了解一下某种游乐设施的具体情况呢？"
D.Strings[46110]="那些就是坦克吗？"
D.Strings[46111]="我们给这些迷你坦克起了一个很拉风的名字，叫蒸汽坦克。它们可是我记忆当中，最受欢迎的马戏团游戏了。$b$b我们有两座坦克大战专用的战场。$b$b一座为限时挑战战场，你需要在里面快速摧毁目标，并躲避敌对坦克的攻击。只要一个代币，你就可以参加游戏了！$b$b另一座战场则是对战专用的场地，你可以驾驶自己的坦克或迷你飞艇来和朋友对战。"
D.Strings[46112]="雷管5000型超级大炮是一种代表世界最尖端技术水平的单人发射装置。$b$b它能以接近飞龙的速度将搭乘者发射出去。它的发明者是雷管家族，这个家族在航空及爆破领域享有盛名。这架超级大炮已经成为了家族的荣耀！$B$B如果你想像鸟儿一样在空中翱翔，就去找玛克希玛·雷管吧。"
D.Strings[46113]="打豺狼人？"
D.Strings[46114]="打豺狼人是一种打……豺狼人的有趣游戏。$b$b这是一个新的游乐设施，而且颇受我们大家的欢迎……好吧，其实塞格不太喜欢这玩意儿。"
D.Strings[46115]="那边！快！快！！！"
D.Strings[46116]="传送门要关闭了！快！"
D.Strings[46117]="军官：看来我们已经突破了敌人的防线，将军。"
D.Strings[46118]="军官：仍没发现失踪运输机的踪迹。"
D.Strings[46119]="纳兹戈林：我们一定要找到它，否则绝不返航——哪怕是要把大海翻个底朝天！"
D.Strings[46120]="纳兹戈林：……你知道我对那个计划的看法……"
D.Strings[46121]="地精：陆地！"
D.Strings[46122]="纳兹戈林：陆地？在这里？那不可能！"
D.Strings[46123]="$n，你绝对想象不出我有多高兴见到你。监控这活儿消耗可是很大的。"
D.Strings[46124]="我们希望各个年龄层的游客都能享受到游戏乐趣。$b$b套圈圈是一个简单的游戏，你只要设法把投环扔到一只不断移动的海龟背上就可以了。$b$b这也是我最喜欢的游戏之一。"
